    function clampReadableTrafficSpeed(type, requestedSpeed) {
        const speed = Number(requestedSpeed);
        if (!Number.isFinite(speed) || speed >= 0) return Number.isFinite(speed) ? speed : 0;
        // Player acceleration already increases the approach speed of every
        // obstacle. Limit only the additional oncoming component so late-game
        // traffic remains readable; density still supplies the difficulty.
        const playerSpeed01 = Math.max(0, Math.min(1,
            (Math.abs(moveSpeed || minMoveSpeed) - minMoveSpeed) / Math.max(0.001, maxMoveSpeed - minMoveSpeed)
        ));
        const cap = type === 'motorcycle'
            ? 1.02 - playerSpeed01 * 0.18
            : (type === 'train' ? 0.68 - playerSpeed01 * 0.12 : 0.88 - playerSpeed01 * 0.14);
        return -Math.min(Math.abs(speed), Math.max(0.46, cap));
    }

