    function getHowToPlayCopy() {
        return HOW_TO_PLAY_COPY[normalizeLanguage(menuState.language)] || HOW_TO_PLAY_COPY.en;
    }

    function applyHowToPlayCopy() {
        const copy = getHowToPlayCopy();
        if (ui.howToPlayTitle) ui.howToPlayTitle.textContent = copy.title;
        if (ui.howToPlayMove) ui.howToPlayMove.textContent = copy.move;
        if (ui.howToPlayJump) ui.howToPlayJump.textContent = copy.jump;
        if (ui.howToPlayLook) ui.howToPlayLook.textContent = copy.look;
        if (ui.howToPlaySpace) ui.howToPlaySpace.textContent = copy.space;
        if (ui.howToPlayAbility) ui.howToPlayAbility.textContent = tr('ability');
        if (ui.howToPlayMenu) ui.howToPlayMenu.textContent = tr('menu');
        if (ui.howToMobileJump) ui.howToMobileJump.textContent = copy.jump;
        if (ui.howToMobileSlide) ui.howToMobileSlide.textContent = tr('slide');
        if (ui.howToMobileSkill) ui.howToMobileSkill.textContent = tr('ability');
        if (ui.howToMobileMove) ui.howToMobileMove.textContent = copy.move;
        if (ui.howToPortraitMove) ui.howToPortraitMove.textContent = copy.move;
        if (ui.howToPortraitJump) ui.howToPortraitJump.textContent = copy.jump;
        if (ui.howToPortraitSlide) ui.howToPortraitSlide.textContent = tr('slide');
        if (ui.howToPortraitSkill) ui.howToPortraitSkill.textContent = tr('ability');
        if (ui.howToPlayOverlay) {
            ui.howToPlayOverlay.setAttribute('dir', normalizeLanguage(menuState.language) === 'ar' ? 'rtl' : 'ltr');
        }
    }

    function hideHowToPlayOverlay(instant = false) {
        if (howToPlayTimer) clearTimeout(howToPlayTimer);
        if (howToPlayLeaveTimer) clearTimeout(howToPlayLeaveTimer);
        howToPlayTimer = null;
        howToPlayLeaveTimer = null;
        howToPlayVisibleUntil = 0;
        document.body.classList.remove('tutorial-howto');
        if (!ui.howToPlayOverlay) return;
        ui.howToPlayOverlay.classList.remove('is-visible');
        ui.howToPlayOverlay.classList.toggle('is-leaving', !instant);
        if (instant) {
            ui.howToPlayOverlay.hidden = true;
            ui.howToPlayOverlay.classList.remove('is-leaving');
            ui.howToPlayOverlay.setAttribute('aria-hidden', 'true');
            return;
        }
        howToPlayLeaveTimer = setTimeout(() => {
            if (!ui.howToPlayOverlay) return;
            ui.howToPlayOverlay.hidden = true;
            ui.howToPlayOverlay.classList.remove('is-leaving');
            ui.howToPlayOverlay.setAttribute('aria-hidden', 'true');
            howToPlayLeaveTimer = null;
        }, 420);
    }

    function showHowToPlayOverlay(duration = 5000, tutorialMode = false) {
        if (!ui.howToPlayOverlay) return;
        hideHowToPlayOverlay(true);
        applyHowToPlayCopy();
        document.body.classList.toggle('tutorial-howto', !!tutorialMode);
        ui.howToPlayOverlay.hidden = false;
        ui.howToPlayOverlay.setAttribute('aria-hidden', 'false');
        void ui.howToPlayOverlay.offsetWidth;
        ui.howToPlayOverlay.classList.add('is-visible');
        const visibleFor = Math.max(1200, Number(duration) || 5000);
        howToPlayVisibleUntil = performance.now() + visibleFor;
        howToPlayTimer = setTimeout(() => hideHowToPlayOverlay(false), visibleFor);
    }

    function queueHowToPlayOverlay() {
        // Let the menu teardown and the first game frame finish first. Starting the
        // five-second timer before that work completed made the card occasionally
        // disappear immediately on slower browsers.
        requestAnimationFrame(() => {
            requestAnimationFrame(() => showHowToPlayOverlay());
        });
    }

    function replayElementClass(element, className, duration = 700) {
        if (!element) return;
        element.classList.remove(className);
        void element.offsetWidth;
        element.classList.add(className);
        setTimeout(() => element.classList.remove(className), duration);
    }

    function walletFeedbackPoint(element, fallbackX, fallbackY) {
        if (element && typeof element.getBoundingClientRect === 'function') {
            const rect = element.getBoundingClientRect();
            if (rect.width > 0 && rect.height > 0) {
                return { x: rect.left + rect.width / 2, y: rect.top + rect.height / 2 };
            }
        }
        return { x: fallbackX, y: fallbackY };
    }

    function playWalletTransactionEffect(amount, kind = 'gain', sourceElement = null) {
        if (!ui.walletFeedbackLayer || !Number.isFinite(amount) || amount <= 0) return;
        const source = walletFeedbackPoint(sourceElement, innerWidth * .5, innerHeight * .5);
        const target = walletFeedbackPoint(ui.menuShopBtn, Math.min(innerWidth - 76, 250), 80);
        const isGain = kind === 'gain';
        const value = document.createElement('span');
        value.className = 'wallet-fx-value' + (isGain ? '' : ' is-spend');
        value.style.setProperty('--fx-x', `${source.x}px`);
        value.style.setProperty('--fx-y', `${source.y}px`);
        value.textContent = `${isGain ? '+' : '−'}${Math.floor(amount).toLocaleString(menuNumberLocale())}`;
        ui.walletFeedbackLayer.appendChild(value);

        const count = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches ? 0 : (isGain ? 12 : 8);
        for (let i = 0; i < count; i++) {
            const coin = document.createElement('i');
            coin.className = 'wallet-fx-coin' + (isGain ? '' : ' is-spend');
            const spreadX = (Math.random() - .5) * (isGain ? 150 : 110);
            const spreadY = isGain ? (-45 - Math.random() * 90) : (45 + Math.random() * 75);
            const dx = isGain ? spreadX : (target.x - source.x) * .18 + spreadX;
            const dy = isGain ? spreadY : spreadY;
            coin.style.setProperty('--fx-x', `${source.x}px`);
            coin.style.setProperty('--fx-y', `${source.y}px`);
            coin.style.setProperty('--fx-dx', `${dx}px`);
            coin.style.setProperty('--fx-dy', `${dy}px`);
            coin.style.setProperty('--fx-delay', `${i * 24}ms`);
            coin.style.setProperty('--fx-dur', `${620 + Math.random() * 260}ms`);
            ui.walletFeedbackLayer.appendChild(coin);
            setTimeout(() => coin.remove(), 1250);
        }
        setTimeout(() => value.remove(), 1100);
        replayElementClass(ui.menuShopBtn, isGain ? 'is-wallet-gain' : 'is-wallet-spend', isGain ? 760 : 620);
        const card = sourceElement && sourceElement.closest ? sourceElement.closest('.menu-upgrade-card') : null;
        if (!isGain && card) replayElementClass(card, 'is-purchase-success', 640);
    }

