    function languageFromLocaleTag(locale) {
        const raw = String(locale || '').trim();
        if (!raw) return null;
        const normalized = raw.replace('_', '-');
        const parts = normalized.split('-');
        const base = parts[0].toLowerCase();
        const region = parts.find((part) => /^[A-Za-z]{2}$/.test(part) && part.toLowerCase() !== base)?.toUpperCase() || '';
        if (base === 'zh') return /hant/i.test(normalized) || ['TW','HK','MO'].includes(region) ? 'zh-Hant' : 'zh-Hans';
        if (base === 'es') return LATIN_AMERICAN_SPANISH_COUNTRIES.has(region) ? 'es-419' : 'es-ES';
        if (base === 'pt') return region === 'PT' ? 'pt-PT' : 'pt-BR';
        if (base === 'nb' || base === 'nn') return 'no';
        const direct = SUPPORTED_LANGUAGES.find((lang) => lang.code.toLowerCase() === base);
        return direct ? direct.code : null;
    }

    function detectInitialLanguage() {
        const locales = Array.isArray(navigator.languages) && navigator.languages.length
            ? navigator.languages
            : [navigator.language];
        for (const locale of locales) {
            const detected = languageFromLocaleTag(locale);
            if (detected) return detected;
        }
        return 'en';
    }

    function languageFromCountryCode(countryCode) {
        const code = String(countryCode || '').trim().toUpperCase();
        if (LATIN_AMERICAN_SPANISH_COUNTRIES.has(code)) return 'es-419';
        return COUNTRY_LANGUAGE_MAP[code] || null;
    }

    function applyAutoLanguageFromCrazyGamesSystemInfo(systemInfo) {
        if (!isCrazyGamesBuild() || menuState.languageSource !== 'auto') return false;
        const info = systemInfo && typeof systemInfo === 'object' ? systemInfo : {};
        const locale = info.locale || info.language || info.languageCode || '';
        const language = languageFromLocaleTag(locale) || languageFromCountryCode(info.countryCode);
        if (!language) return false;
        if (language !== menuState.language) {
            menuState.language = language;
            applyMainMenuSettings();
            updateMainMenuStats();
            saveMainMenuState();
        }
        return true;
    }
    // "Zaman Yavaşlatma" yeteneğinin tüm desteklenen dillerdeki adı.
