    // Başarım adları yalnızca EN+TR tutulur: Steam overlay'i panelde girilen yerelleştirilmiş
    // adı zaten kendi gösterir, 34 başarımı 30 dile çevirmek dosyayı gereksiz şişirirdi.
    // 16 başarım (2026-07-16'da 34'ten kısıldı). Kesme gerekçesi — ÇAKIŞMA:
    // faz eşikleri NATURE=5000/SKY=15000/LAVA=25000/WATER=40000/SNOW=60000 olduğu için
    // eski ACH_SCORE_5K..60K, faz rozetleriyle AYNI ANDA açılıyordu (5 kopya). Ayrıca
    // 150km/h≈maks hız, 100≈500 altın, bir-yükseltme-max≈tümü-max, ilk-günlük≈tüm-günlükler,
    // 10/50≈100 koşu çiftleri de kopyaydı. "Yeteneği bir kez kullan" rozetleri (tek tuş)
    // ve "yeni rekor" (2. koşuda herkes alır) değer katmıyordu.
    // YENİ BAŞARIM EKLERKEN: eşiğin mevcut bir rozetle aynı ana denk gelip gelmediğini kontrol et.
    const ACHIEVEMENTS = [
        { id: 'firstRun',      api: 'ACH_FIRST_RUN',       en: 'First Steps',        tr: 'İlk Adımlar' },
        { id: 'phaseNature',   api: 'ACH_PHASE_NATURE',    en: 'Green Horizon',      tr: 'Yeşil Ufuk' },
        { id: 'phaseSky',      api: 'ACH_PHASE_SKY',       en: 'Above the Clouds',   tr: 'Bulutların Üstünde' },
        { id: 'phaseLava',     api: 'ACH_PHASE_LAVA',      en: 'Molten Ground',      tr: 'Erimiş Zemin' },
        { id: 'phaseWater',    api: 'ACH_PHASE_WATER',     en: 'Against the Tide',   tr: 'Akıntıya Karşı' },
        { id: 'phaseSnow',     api: 'ACH_PHASE_SNOW',      en: 'Whiteout',           tr: 'Beyaz Karanlık' },
        { id: 'allPhases',     api: 'ACH_ALL_PHASES',      en: 'Grand Tour',         tr: 'Büyük Tur' },
        { id: 'score100k',     api: 'ACH_SCORE_100K',      en: 'Six Figures',        tr: 'Altı Basamak' },
        { id: 'coins500Run',   api: 'ACH_COINS_500_RUN',   en: 'Gold Rush',          tr: 'Altına Hücum' },
        { id: 'speedMax',      api: 'ACH_SPEED_MAX',       en: 'Terminal Velocity',  tr: 'Son Sürat' },
        { id: 'useRevive',     api: 'ACH_USE_REVIVE',      en: 'Second Wind',        tr: 'İkinci Nefes' },
        { id: 'allAbilities',  api: 'ACH_ALL_ABILITIES',   en: 'Full Arsenal',       tr: 'Tam Cephanelik' },
        { id: 'allMax',        api: 'ACH_ALL_MAX',         en: 'Maxed Out',          tr: 'Sonuna Kadar' },
        { id: 'runs100',       api: 'ACH_RUNS_100',        en: 'Centurion',          tr: 'Yüzbaşı' },
        { id: 'dailyAll',      api: 'ACH_DAILY_ALL',       en: 'Clean Sweep',        tr: 'Tam Temizlik' },
        { id: 'dailyStreak7',  api: 'ACH_DAILY_STREAK_7',  en: 'Seven Day Streak',   tr: 'Yedi Gün Üst Üste' },
        { id: 'bhop10',        api: 'ACH_BHOP_10',          en: 'Flow State',          tr: 'Akışta' },
        { id: 'megaJump',      api: 'ACH_MEGA_JUMP',        en: 'Skybound',            tr: 'Göğe Doğru' },
        { id: 'handCollector', api: 'ACH_HAND_COLLECTOR',   en: 'Handpicked',          tr: 'Eldiven Koleksiyonu' },
        { id: 'level25',       api: 'ACH_LEVEL_25',         en: 'Trailblazer',         tr: 'Öncü' }
    ];
    const ACHIEVEMENT_BY_ID = {};
    ACHIEVEMENTS.forEach((a) => { ACHIEVEMENT_BY_ID[a.id] = a; });

    function isAchievementUnlocked(id) {
        return !!(menuState.achievements && menuState.achievements[id]);
    }

    // Steam'e it. Köprü yoksa (tarayıcı/itch build) veya Steam kapalıysa sessizce geç —
    // yerel kilit zaten açıldı, bu yalnızca Steam'e yansıtma katmanı.
    function pushAchievementToSteam(apiName) {
        const shell = typeof window !== 'undefined' ? window.elementalRunShell : null;
        if (!shell || typeof shell.unlockAchievement !== 'function') return;
        try {
            Promise.resolve(shell.unlockAchievement(apiName)).catch(() => {});
        } catch (err) { /* IPC yoksa yut */ }
    }

    // Steam kapalıyken açılan başarımlar yerelde işaretlenir ama Steam'e gitmez; unlockAchievement
    // zaten-açık olanı bir daha denemediğinden o kilitler KALICI kaybolurdu. Açılışta (ve Steam
    // sonradan gelirse) yerel listeyi Steam'e gönder — main tarafı eksikleri işleyip tek store yapar.
    function syncAchievementsToSteam() {
        const shell = typeof window !== 'undefined' ? window.elementalRunShell : null;
        if (!shell || typeof shell.syncAchievements !== 'function') return;
        const unlocked = ACHIEVEMENTS.filter((a) => isAchievementUnlocked(a.id)).map((a) => a.api);
        if (!unlocked.length) return;
        try { Promise.resolve(shell.syncAchievements(unlocked)).catch(() => {}); } catch (err) { /* yut */ }
    }

    function unlockAchievement(id) {
        const def = ACHIEVEMENT_BY_ID[id];
        if (!def) return false;
        if (!menuState.achievements || typeof menuState.achievements !== 'object') menuState.achievements = {};
        if (menuState.achievements[id]) return false;
        menuState.achievements[id] = true;
        saveMainMenuState();
        // Görsel bildirim Steam overlay'e bırakılır; oyun içi sarı toast kaldırıldı.
        pushAchievementToSteam(def.api);
        return true;
    }

    // ── GÜNLÜK GÖREVLER ──────────────────────────────────────────────────────────
    // Görevler günün tarihinden DETERMİNİSTİK üretilir (aynı gün = aynı 3 görev, her
    // oyuncuda aynı) → sunucu gerekmez, kayıt bozulsa bile aynı gün aynı görevler döner.
       // görev başına altın
            // üçü de bitince ek altın
    function dailyMissionsTitleText() {
        return DAILY_MISSION_TITLES[normalizeLanguage(menuState.language)] || DAILY_MISSION_TITLES.en;
    }

    // Menü butonu için KISA etiket: tam başlık ("GÜNLÜK GÖREVLER") 960x540'ta butona
    // sığmayıp rozetin altına giriyordu. Dialog başlığı tam metni kullanmaya devam eder.
    function dailyShortLabelText() {
        return DAILY_SHORT_LABELS[normalizeLanguage(menuState.language)] || DAILY_SHORT_LABELS.en;
    }

    // {n} = hedef. Every visible mission string ships in every supported UI language.
    function getDailyLocalization() {
        return DAILY_LOCALIZATION[normalizeLanguage(menuState.language)] || DAILY_LOCALIZATION.en;
    }
    const DAILY_MISSION_TYPE_BY_ID = {};
    DAILY_MISSION_TYPES.forEach((m) => { DAILY_MISSION_TYPE_BY_ID[m.type] = m; });

    // Yerel tarih (UTC DEĞİL): oyuncunun günü kendi saatiyle dönsün.
    function getTodayKey() {
        const d = new Date();
        const mm = String(d.getMonth() + 1).padStart(2, '0');
        const dd = String(d.getDate()).padStart(2, '0');
        return `${d.getFullYear()}-${mm}-${dd}`;
    }

    function dailyHash(str) {
        let h = 2166136261 >>> 0;
        for (let i = 0; i < str.length; i++) {
            h ^= str.charCodeAt(i);
            h = Math.imul(h, 16777619) >>> 0;
        }
        return h >>> 0;
    }

    function mulberry32(seed) {
        let a = seed >>> 0;
        return function () {
            a = (a + 0x6D2B79F5) >>> 0;
            let t = Math.imul(a ^ (a >>> 15), 1 | a);
            t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
            return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
        };
    }

    function generateDailyMissions(dayKey) {
        const rand = mulberry32(dailyHash(dayKey));
        const pool = DAILY_MISSION_TYPES.slice();
        const picked = [];
        // Fisher-Yates ile çekiliş → aynı tip iki kez gelmez.
        for (let i = pool.length - 1; i > 0; i--) {
            const j = Math.floor(rand() * (i + 1));
            const tmp = pool[i]; pool[i] = pool[j]; pool[j] = tmp;
        }
        for (let i = 0; i < Math.min(DAILY_MISSION_COUNT, pool.length); i++) {
            const def = pool[i];
            const target = def.targets[Math.floor(rand() * def.targets.length)];
            picked.push({ type: def.type, target, progress: 0, done: false, rewarded: false });
        }
        return { day: dayKey, missions: picked };
    }

    // Kayıttan geleni doğrula: gün değiştiyse ya da şekil bozuksa yeniden üret.
    function normalizeDailyMissions(saved) {
        const today = getTodayKey();
        if (!saved || typeof saved !== 'object' || saved.day !== today || !Array.isArray(saved.missions)) {
            return generateDailyMissions(today);
        }
        const fresh = generateDailyMissions(today);
        // Kayıtlı ilerlemeyi taze tanımın üstüne bindir (tip listesi değişmişse bozulmasın).
        fresh.missions.forEach((m) => {
            const old = saved.missions.find((s) => s && s.type === m.type);
            if (!old) return;
            m.progress = Math.max(0, Number(old.progress) || 0);
            m.done = !!old.done;
            m.rewarded = !!old.rewarded;
        });
        return fresh;
    }

    function ensureDailyMissions() {
        const today = getTodayKey();
        if (!menuState.dailyMissions || menuState.dailyMissions.day !== today) {
            menuState.dailyMissions = generateDailyMissions(today);
            saveMainMenuState();
        }
        return menuState.dailyMissions;
    }

    function dailyMissionText(m) {
        const def = DAILY_MISSION_TYPE_BY_ID[m.type];
        if (!def) return '';
        const typeIndex = DAILY_MISSION_TYPES.findIndex((type) => type.type === m.type);
        const tpl = getDailyLocalization().missions[typeIndex] || DAILY_LOCALIZATION.en.missions[typeIndex];
        return tpl.replace('{n}', Number(m.target).toLocaleString(menuNumberLocale()));
    }

    function resetDailyMissionRunProgress() {
        // 'max' modlu görevler tek koşu içinde ölçülür; koşu başında sıfırlanacak bir
        // şey yok (ilerleme günlük kalıcı). Yalnızca koşu-içi tepe değerleri sıfırlanır.
        dailyRunPeakScore = 0;
        dailyRunPeakPhase = 0;
        dailyRunPeakSpeed = 0;
    }
    let dailyRunPeakScore = 0;
    let dailyRunPeakPhase = 0;
    let dailyRunPeakSpeed = 0;

    function noteDailyMissionEvent(type, amount = 1) {
        const data = ensureDailyMissions();
        let changed = false;
        data.missions.forEach((m) => {
            if (m.type !== type || m.done) return;
            const def = DAILY_MISSION_TYPE_BY_ID[m.type];
            if (!def) return;
            const next = def.mode === 'max' ? Math.max(m.progress, amount) : m.progress + amount;
            if (next === m.progress) return;
            m.progress = next;
            changed = true;
            if (m.progress >= m.target) {
                m.progress = m.target;
                m.done = true;
                renderDailyMissions();
            }
        });
        if (changed) saveMainMenuState();
    }

    function dailyMissionClaimText() {
        return getDailyLocalization().claim;
    }

    function claimDailyMissionReward(m, sourceElement = null) {
        if (!m || !m.done || m.rewarded) return;
        m.rewarded = true;
        menuState.walletCoins = Math.max(0, Math.floor(menuState.walletCoins) || 0) + DAILY_MISSION_REWARD;

        const data = menuState.dailyMissions;
        let grantedAmount = DAILY_MISSION_REWARD;
        if (data && data.missions.length && data.missions.every((x) => x.done && x.rewarded)) {
            menuState.walletCoins += DAILY_ALL_BONUS;
            grantedAmount += DAILY_ALL_BONUS;
            unlockAchievement('dailyAll');
            bumpDailyStreak();
        }
        const claimedRow = sourceElement && sourceElement.closest ? sourceElement.closest('.menu-daily-row') : null;
        if (claimedRow) replayElementClass(claimedRow, 'is-reward-claimed', 700);
        playWalletTransactionEffect(grantedAmount, 'gain', sourceElement);
        saveMainMenuState();
        updateMainMenuStats();
        setTimeout(() => renderDailyMissions(), 260);
    }

    // Seri: yalnızca dünkü gün tamamlandıysa artar; bir gün atlanırsa 1'e döner.
    function bumpDailyStreak() {
        const today = getTodayKey();
        if (menuState.dailyLastCompletedDay === today) return;
        const yesterday = new Date();
        yesterday.setDate(yesterday.getDate() - 1);
        const yMM = String(yesterday.getMonth() + 1).padStart(2, '0');
        const yDD = String(yesterday.getDate()).padStart(2, '0');
        const yKey = `${yesterday.getFullYear()}-${yMM}-${yDD}`;
        menuState.dailyStreak = menuState.dailyLastCompletedDay === yKey
            ? Math.max(1, Math.floor(menuState.dailyStreak) || 0) + 1
            : 1;
        menuState.dailyLastCompletedDay = today;
        if (menuState.dailyStreak >= 7) unlockAchievement('dailyStreak7');
        saveMainMenuState();
    }

    // applyLanguageTexts erken çalışabilir → elemanlar yoksa sessizce çık.
    function renderDailyMissions() {
        if (!ui || !ui.menuDailyList) return;
        const data = ensureDailyMissions();
        const doneCount = data.missions.filter((m) => m.done).length;

        const loc = menuNumberLocale();
        const dailyCopy = getDailyLocalization();
        ui.menuDailyList.innerHTML = '';
        data.missions.forEach((m) => {
            const pct = Math.max(0, Math.min(100, Math.round((m.progress / m.target) * 100)));
            const row = document.createElement('div');
            row.className = 'menu-daily-row'
                + (m.done ? ' is-done' : '')
                + (m.done && !m.rewarded ? ' is-claimable' : '');

            // Sol: durum ikonu (tamamlandıysa tik, değilse hedef halkası)
            const mark = document.createElement('span');
            mark.className = 'menu-daily-mark';
            mark.textContent = m.done ? '✓' : '◇';

            const info = document.createElement('div');
            info.className = 'menu-daily-info';
            const head = document.createElement('div');
            head.className = 'menu-daily-head';
            const text = document.createElement('span');
            text.className = 'menu-daily-text';
            text.textContent = dailyMissionText(m);
            // Sayaç başlığa taşındı: çubuğun üstünde okunması daha kolay.
            const prog = document.createElement('span');
            prog.className = 'menu-daily-count';
            prog.textContent = m.done
                ? dailyCopy.done
                : `${Math.floor(m.progress).toLocaleString(loc)} / ${Number(m.target).toLocaleString(loc)}`;
            head.appendChild(text);
            head.appendChild(prog);

            const bar = document.createElement('div');
            bar.className = 'menu-daily-bar';
            const fill = document.createElement('i');
            fill.style.width = pct + '%';
            bar.appendChild(fill);
            info.appendChild(head);
            info.appendChild(bar);

            // Sağ: ödül rozeti — görevin neden yapıldığı görünür olsun.
            let reward;
            if (m.done && !m.rewarded) {
                reward = document.createElement('button');
                reward.type = 'button';
                reward.className = 'menu-daily-reward menu-daily-claim';
                reward.innerHTML = `<span class="menu-daily-coin">●</span>${DAILY_MISSION_REWARD} ${dailyMissionClaimText()}`;
                reward.addEventListener('click', (e) => {
                    e.preventDefault();
                    e.stopPropagation();
                    playUiConfirmSound();
                    claimDailyMissionReward(m, e.currentTarget);
                });
            } else {
                reward = document.createElement('strong');
                reward.className = 'menu-daily-reward';
                reward.innerHTML = `<span class="menu-daily-coin">●</span>${DAILY_MISSION_REWARD}`;
            }

            row.appendChild(mark);
            row.appendChild(info);
            row.appendChild(reward);
            ui.menuDailyList.appendChild(row);
        });

        if (ui.menuDailyStreak) {
            const streak = Math.max(0, Math.floor(menuState.dailyStreak) || 0);
            // Seri = alev rozeti (düz metinde kayboluyordu). Seri 0 iken alev sönük.
            ui.menuDailyStreak.innerHTML = '';
            const flame = document.createElement('span');
            flame.className = 'menu-daily-streak-flame' + (streak > 0 ? ' is-lit' : '');
            flame.textContent = '🔥';
            const label = document.createElement('span');
            label.className = 'menu-daily-streak-text';
            label.innerHTML = dailyCopy.streak.replace('{n}', `<b>${streak}</b>`);
            const prog = document.createElement('span');
            prog.className = 'menu-daily-streak-count';
            prog.textContent = `${doneCount}/${data.missions.length}`;
            ui.menuDailyStreak.appendChild(flame);
            ui.menuDailyStreak.appendChild(label);
            ui.menuDailyStreak.appendChild(prog);
        }
        if (ui.menuDailyReset) {
            ui.menuDailyReset.textContent = dailyCopy.reset.replace('{time}', timeUntilMidnightText());
        }
        if (ui.menuDailyBadge) {
            const claimableCount = data.missions.filter((m) => m.done && !m.rewarded).length;
            ui.menuDailyBadge.textContent = '!';
            ui.menuDailyBadge.hidden = claimableCount === 0;
            ui.menuDailyBadge.setAttribute('aria-label', claimableCount > 0 ? `${claimableCount} ${dailyCopy.claim}` : '');
            ui.menuDailyBadge.classList.toggle('is-complete', claimableCount > 0);
        }
    }

    // ── LİDERLİK TABLOSU (Steam) ─────────────────────────────────────────────────
    // Steam köprüsü yoksa (tarayıcı/itch build) veya Steam kapalıysa panel bir bilgi
    // metni gösterir — hata vermez, oyunun geri kalanı etkilenmez.
    let leaderboardScope = 'global';
    let leaderboardBusy = false;
    const BROWSER_LEADERBOARD_ENTRIES = Object.freeze({
        global: [
            { name: 'ResoRunner', country: 'TR', score: 98420 },
            { name: 'NeonMason', country: 'US', score: 93780 },
            { name: 'BlitzNora', country: 'DE', score: 90215 },
            { name: 'LumaRafa', country: 'BR', score: 87640 },
            { name: 'KaitoDash', country: 'JP', score: 84190 },
            { name: 'VexOliver', country: 'GB', score: 80855 },
            { name: 'AeroCamille', country: 'FR', score: 77420 },
            { name: 'JinPulse', country: 'KR', score: 73110 },
            { name: 'LunaRift', country: 'ES', score: 68950 },
            { name: 'SvenVolt', country: 'NL', score: 64275 }
        ],
        friends: [
            { name: 'EmirDash', country: 'TR', score: 71580 },
            { name: 'MiraBoost', country: 'TR', score: 69240 },
            { name: 'ArdaFlux', country: 'TR', score: 65125 },
            { name: 'CanVortex', country: 'TR', score: 62890 },
            { name: 'EceNova', country: 'TR', score: 59440 },
            { name: 'NoxRider', country: 'GB', score: 55210 },
            { name: 'MaxLane', country: 'DE', score: 51170 },
            { name: 'RafiGold', country: 'BR', score: 47880 },
            { name: 'KenjiRun', country: 'JP', score: 43660 },
            { name: 'IvyByte', country: 'US', score: 39830 }
        ]
    });

    function leaderboardStatusText(key) {
        const isTr = normalizeLanguage(menuState.language) === 'tr';
        const map = {
            loading:     isTr ? 'Yükleniyor...' : 'Loading...',
            unavailable: isTr ? 'Steam bağlantısı yok. Liderlik tablosu yalnızca Steam sürümünde çalışır.'
                              : 'No Steam connection. Leaderboard is only available on the Steam build.',
            empty:       isTr ? 'Henüz kayıt yok. İlk sen ol!' : 'No entries yet. Be the first!',
            error:       isTr ? 'Liderlik tablosu yüklenemedi.' : 'Could not load the leaderboard.'
        };
        return map[key] || '';
    }

    function countryCodeToFlag(country) {
        const code = String(country || '').trim().toUpperCase();
        if (!/^[A-Z]{2}$/.test(code)) return '';
        return Array.from(code).map((letter) => String.fromCodePoint(127397 + letter.charCodeAt(0))).join('');
    }

    function getBrowserLeaderboardEntries(scope) {
        const list = BROWSER_LEADERBOARD_ENTRIES[scope === 'friends' ? 'friends' : 'global'] || BROWSER_LEADERBOARD_ENTRIES.global;
        return list.map((entry, index) => ({ ...entry, rank: index + 1, isSelf: false }));
    }

    function renderLeaderboardEntries(entries) {
        if (!ui.menuBoardList || !ui.menuBoardStatus) return;
        const list = Array.isArray(entries) ? entries : [];
        if (!list.length) {
            ui.menuBoardStatus.textContent = leaderboardStatusText('empty');
            return;
        }
        ui.menuBoardStatus.textContent = '';
        const isTr = normalizeLanguage(menuState.language) === 'tr';
        const medals = { 1: '\u{1F947}', 2: '\u{1F948}', 3: '\u{1F949}' };
        list.forEach((e, index) => {
            const rankNumber = Math.max(1, Number(e.rank) || index + 1);
            const row = document.createElement('div');
            row.className = 'menu-board-entry'
                + (e.isSelf ? ' is-self' : '')
                + (rankNumber <= 3 ? ' is-top rank-' + rankNumber : '');
            const rank = document.createElement('span');
            rank.className = 'menu-board-rank';
            rank.textContent = medals[rankNumber] || '#' + rankNumber;
            const name = document.createElement('span');
            name.className = 'menu-board-name';
            const flag = document.createElement('span');
            const country = String(e.country || '').trim().toLowerCase();
            flag.className = 'menu-board-flag' + (country ? ' is-' + country : '');
            flag.textContent = e.flag || countryCodeToFlag(e.country);
            flag.title = String(e.country || '').toUpperCase();
            flag.setAttribute('aria-hidden', 'true');
            const player = document.createElement('span');
            player.className = 'menu-board-player';
            player.textContent = e.name || 'Runner';
            name.appendChild(flag);
            name.appendChild(player);
            if (e.isSelf) {
                const you = document.createElement('em');
                you.className = 'menu-board-you';
                you.textContent = isTr ? 'SEN' : 'YOU';
                name.appendChild(you);
            }
            const sc = document.createElement('strong');
            sc.className = 'menu-board-score';
            sc.textContent = Number(e.score).toLocaleString(menuNumberLocale());
            row.appendChild(rank);
            row.appendChild(name);
            row.appendChild(sc);
            ui.menuBoardList.appendChild(row);
        });
    }

    async function refreshLeaderboard(scope = 'global') {
        leaderboardScope = scope === 'friends' ? 'friends' : 'global';
        document.querySelectorAll('.menu-board-tab').forEach((t) => {
            t.classList.toggle('is-active', t.dataset.scope === leaderboardScope);
        });
        if (!ui.menuBoardList || !ui.menuBoardStatus) return;
        if (leaderboardBusy) return;
        leaderboardBusy = true;
        ui.menuBoardList.innerHTML = '';
        ui.menuBoardStatus.textContent = leaderboardStatusText('loading');

        const shell = typeof window !== 'undefined' ? window.elementalRunShell : null;
        if (!shell || typeof shell.leaderboardTop !== 'function') {
            renderLeaderboardEntries(getBrowserLeaderboardEntries(leaderboardScope));
            leaderboardBusy = false;
            return;
        }
        try {
            const res = await shell.leaderboardTop(leaderboardScope, 10);
            if (!res || !res.ok) {
                ui.menuBoardStatus.textContent = leaderboardStatusText(res && res.available === false ? 'unavailable' : 'error');
                return;
            }
            if (!res.entries.length) {
                ui.menuBoardStatus.textContent = leaderboardStatusText('empty');
                return;
            }
            renderLeaderboardEntries(res.entries);
            return;
            ui.menuBoardStatus.textContent = '';
            const isTr = normalizeLanguage(menuState.language) === 'tr';
            const medals = { 1: '🥇', 2: '🥈', 3: '🥉' };
            res.entries.forEach((e) => {
                const row = document.createElement('div');
                // rank-1/2/3 = podyum renkleri; hepsi aynı görünüyordu, sıralama okunmuyordu.
                row.className = 'menu-board-entry'
                    + (e.isSelf ? ' is-self' : '')
                    + (e.rank <= 3 ? ' is-top rank-' + e.rank : '');
                const rank = document.createElement('span');
                rank.className = 'menu-board-rank';
                rank.textContent = medals[e.rank] || '#' + e.rank;
                const name = document.createElement('span');
                name.className = 'menu-board-name';
                name.textContent = e.name;
                if (e.isSelf) {
                    const you = document.createElement('em');
                    you.className = 'menu-board-you';
                    you.textContent = isTr ? 'SEN' : 'YOU';
                    name.appendChild(you);
                }
                const sc = document.createElement('strong');
                sc.className = 'menu-board-score';
                sc.textContent = Number(e.score).toLocaleString(menuNumberLocale());
                row.appendChild(rank);
                row.appendChild(name);
                row.appendChild(sc);
                ui.menuBoardList.appendChild(row);
            });
        } catch (err) {
            renderLeaderboardEntries(getBrowserLeaderboardEntries(leaderboardScope));
        } finally {
            leaderboardBusy = false;
        }
    }

    function submitScoreToLeaderboard(finalScore) {
        const shell = typeof window !== 'undefined' ? window.elementalRunShell : null;
        if (!shell || typeof shell.leaderboardUpload !== 'function') return;
        const s = Math.max(0, Math.floor(finalScore) || 0);
        if (!s) return;
        // KeepBest: Steam zaten daha kötü skoru yazmaz, istemcide filtrelemeye gerek yok.
        try { Promise.resolve(shell.leaderboardUpload(s)).catch(() => {}); } catch (err) { /* yut */ }
    }

    function timeUntilMidnightText() {
        const now = new Date();
        const next = new Date(now.getFullYear(), now.getMonth(), now.getDate() + 1, 0, 0, 0, 0);
        const ms = Math.max(0, next - now);
        const h = Math.floor(ms / 3600000);
        const mnt = Math.floor((ms % 3600000) / 60000);
        // Birim kısaltmaları DİLE bağlı: eskiden hep `${h}s ${mnt}dk` (Türkçe saat/dakika)
        // dönüyordu ve İngilizce panelde "Resets in: 12s 6dk" gibi karışık çıkıyordu.
        return normalizeLanguage(menuState.language) === 'tr' ? `${h}sa ${mnt}dk` : `${h}h ${mnt}m`;
    }

    // Sayı biçimi de dile bağlı olmalı — eskiden her yerde 'tr-TR' sabit kodluydu.
    function menuNumberLocale() {
        return normalizeLanguage(menuState.language);
    }

