    function initArrowEffectPool() {
        if (arrowEffectPool.length > 0 || !ui.effectsContainer) return;
        for (let i = 0; i < (isMobilePerformanceGraphics() ? 4 : 8); i++) {
            const arrow = document.createElement('div');
            arrow.className = 'traffic-arrow';
            arrow.style.display = 'none';
            ui.effectsContainer.appendChild(arrow);
            arrowEffectPool.push(arrow);
        }
    }

    function initOilSplatterPool() {
        if (oilSplatterPool.length > 0 || !ui.effectsContainer) return;
        for (let i = 0; i < (isMobilePerformanceGraphics() ? 18 : 44); i++) {
            const splatter = document.createElement('div');
            splatter.className = 'oil-splatter';
            splatter.style.display = 'none';
            ui.effectsContainer.appendChild(splatter);
            oilSplatterPool.push(splatter);
        }
    }

    function clearOilSplatterOverlay() {
        oilSplatterPool.forEach((splatter) => {
            if (splatter._hideTimer) {
                clearTimeout(splatter._hideTimer);
                splatter._hideTimer = null;
            }
            splatter.style.display = 'none';
            splatter.className = 'oil-splatter';
        });
    }

    function clampUpgradeLevel(value, maxLevel) {
        return Math.max(0, Math.min(maxLevel, Math.floor(Number(value) || 0)));
    }

    function clampScoreUpgradeLevel(value) {
        return clampUpgradeLevel(value, SCORE_UPGRADE_MAX_LEVEL);
    }

    function clampCoinUpgradeLevel(value) {
        return clampUpgradeLevel(value, COIN_UPGRADE_MAX_LEVEL);
    }

    function clampJumpUpgradeLevel(value) {
        return clampUpgradeLevel(value, JUMP_UPGRADE_MAX_LEVEL);
    }

    function clampSpeedUpgradeLevel(value) {
        return clampUpgradeLevel(value, SPEED_UPGRADE_MAX_LEVEL);
    }

    function getScoreUpgradeLevel() {
        return clampScoreUpgradeLevel(menuState.upgrades && menuState.upgrades.scoreMultiplier);
    }

    function getCoinUpgradeLevel() {
        return clampCoinUpgradeLevel(menuState.upgrades && menuState.upgrades.coinMultiplier);
    }

    function getJumpUpgradeLevel() {
        return clampJumpUpgradeLevel(menuState.upgrades && menuState.upgrades.jumpHeight);
    }

    function getSpeedUpgradeLevel() {
        return clampSpeedUpgradeLevel(menuState.upgrades && menuState.upgrades.speed);
    }

    function hasGlideUpgrade() {
        return getHandSkillForSkin() === 'glide';
    }

    function hasDoubleJumpUpgrade() {
        return getHandSkillForSkin() === 'doubleJump';
    }

    function hasReviveUpgrade() {
        return getHandSkillForSkin() === 'revive';
    }

    function hasTimeSlowUpgrade() {
        return getHandSkillForSkin() === 'timeSlow';
    }

    function hasMagnetUpgrade() {
        return getHandSkillForSkin() === 'magnet';
    }

    function getActiveSpecialAbility() {
        return getHandSkillForSkin();
    }

    function getCurrentRunFloorCenterY() {
        const floorY = (typeof onSkyLayer !== 'undefined' && onSkyLayer) ? SKY_LAYER_Y : 0;
        const currentHeight = isSliding ? slideHeight : normalHeight;
        return floorY + currentHeight * 0.5;
    }

    function getPlayerHeightAboveRunFloor() {
        if (!player) return 0;
        return Math.max(0, player.position.y - getCurrentRunFloorCenterY());
    }

    function resetGlideTimer() {
        glideTimeLeft = getGlideMaxDuration();
    }

    function queueJumpInput(timer = 0.1) {
        jumpQueue = true;
        jumpQueueTimer = timer;
        bhopAttemptFailed = false;
    }

    function performGroundJump(now = 0) {
        if (!player || isJumping || (tutorialDirector && tutorialDirector.blocksJump())) return false;
        if (isSliding) {
            isSliding = false;
            slideTimer = 0;
            document.body.classList.remove('sliding');
            if (ui.speedVignette) ui.speedVignette.classList.remove('sliding-vignette');
            player.position.y += (normalHeight - slideHeight) / 2;
            currentCameraHeight = normalHeight;
        }
        const timeSinceLand = now - lastLandTime;
        if (timeSinceLand < bhopWindow && !bhopAttemptFailed) {
            bhopCombo++;
            bhopHudCombo = Math.max(1, bhopCombo);
            bhopHudVisibleUntil = now + BHOP_HUD_HOLD_SECONDS;
        } else {
            bhopCombo = 0;
        }
        playerVelocityY = jumpForce * getJumpHeightMultiplier();
        isJumping = true;
        doubleJumpUsedInAir = false;
        resetGlideTimer();
        jumpKeyPressed = true;
        jumpQueue = false;
        bhopAttemptFailed = false;
        playJumpSound();
        // This is the canonical ground-jump path used by keyboard, gamepad,
        // wheel and touch. Advancing here keeps the tutorial input-neutral.
        if (tutorialDirector) tutorialDirector.onAction('jump');
        return true;
    }

    function requestJumpInput(timer = 0.18) {
        if (!player || isGameOver || isGamePaused || mainMenuVisible) return false;
        if (!isJumping) {
            const performed = performGroundJump(clock ? clock.getElapsedTime() : 0);
            return performed;
        }
        queueJumpInput(timer);
        return true;
    }

    function requestWheelJumpInput() {
        if (!CONTROL_ACTION_STATE.jump && !gamepadJumpHeld) jumpKeyPressed = false;
        return requestJumpInput(0.52);
    }

    function setActiveSpecialAbility(abilityKey) {
        if (abilityKey !== getHandSkillForSkin()) return false;
        menuState.activeSpecialAbility = abilityKey;
        saveMainMenuState();
        updateMainMenuStats();
        playUiConfirmSound();
        return true;
    }

    function clampRebirthLevel(value) {
        const level = Math.floor(Number(value));
        if (!Number.isFinite(level) || level < 0) return 0;
        return Math.min(REBIRTH_MAX_LEVEL, level);
    }

    function getRebirthLevel() {
        return clampRebirthLevel(menuState.rebirthLevel);
    }

    function getRebirthMultiplier() {
        const level = getRebirthLevel();
        return level > 0 ? REBIRTH_TIERS[level - 1].multiplier : 1;
    }

    function getNextRebirthTier() {
        const level = getRebirthLevel();
        return level >= REBIRTH_MAX_LEVEL ? null : REBIRTH_TIERS[level];
    }

    // Yetenek ayarları rebirth çarpanıyla ölçeklenir; jump/speed/revive muaf tutulur.
    function rebirthScaledDuration(base) {
        return base * getRebirthMultiplier();
    }

    function rebirthScaledCooldown(base) {
        return Math.max(base * REBIRTH_COOLDOWN_FLOOR_RATIO, base / getRebirthMultiplier());
    }

    function getGlideMaxDuration() {
        return rebirthScaledDuration(GLIDE_MAX_DURATION);
    }

    function getDoubleJumpCooldownTime() {
        return rebirthScaledCooldown(DOUBLE_JUMP_COOLDOWN);
    }

    function getTimeSlowDurationTime() {
        return rebirthScaledDuration(TIME_SLOW_DURATION);
    }

    function getTimeSlowCooldownTime() {
        return rebirthScaledCooldown(TIME_SLOW_COOLDOWN);
    }

    function getMagnetDurationTime() {
        return rebirthScaledDuration(MAGNET_DURATION);
    }

    function getMagnetCooldownTime() {
        return rebirthScaledCooldown(MAGNET_COOLDOWN);
    }

    function getMagnetRadiusValue() {
        return MAGNET_RADIUS * getRebirthMultiplier();
    }

    function getScoreMultiplier() {
        const timedScoreBoost = isRewardBoostActive('score') || !!fortuneWheelSystem?.isScoreActive?.();
        return (1 + (getScoreUpgradeLevel() * SCORE_UPGRADE_STEP)) * getRebirthMultiplier() * (timedScoreBoost ? 2 : 1);
    }

    function getCoinMultiplier() {
        return (1 + (getCoinUpgradeLevel() * COIN_UPGRADE_STEP)) * getRebirthMultiplier() * (isRewardBoostActive('gold') ? 2 : 1);
    }

    function getJumpHeightMultiplier() {
        return Math.min(JUMP_UPGRADE_EFFECT_MAX_MULTIPLIER, 1 + (getJumpUpgradeLevel() * JUMP_UPGRADE_STEP));
    }

    function getJumpHeightDisplayMultiplier() {
        return Math.min(JUMP_UPGRADE_DISPLAY_MAX_MULTIPLIER, 1 + (getJumpUpgradeLevel() * JUMP_UPGRADE_STEP));
    }

    function getSpeedUpgradeKmh(level = getSpeedUpgradeLevel()) {
        return SPEED_UPGRADE_BASE_KMH + (clampSpeedUpgradeLevel(level) * SPEED_UPGRADE_STEP_KMH);
    }

    function getStartingMoveSpeed() {
        const levelBonus = Math.max(0, Number(getActiveLevelTuning()?.startSpeedBonus) || 0);
        return Math.min(maxMoveSpeed, (getSpeedUpgradeKmh() / 180) + levelBonus);
    }

    function formatMultiplier(value) {
        return `${value.toFixed(1)}x`;
    }

    function formatScoreMultiplier(value = getScoreMultiplier()) {
        return formatMultiplier(value);
    }

    function formatCoinMultiplier(value = getCoinMultiplier()) {
        return formatMultiplier(value);
    }

    function formatJumpMultiplier(value = getJumpHeightDisplayMultiplier()) {
        return formatMultiplier(value);
    }

    function formatSpeedUpgradeValue() {
        return `${getSpeedUpgradeKmh()} km/h`;
    }

    function getNextScoreUpgradeCost() {
        const level = getScoreUpgradeLevel();
        return level < SCORE_UPGRADE_MAX_LEVEL ? SCORE_UPGRADE_COSTS[level] : null;
    }

    function getNextCoinUpgradeCost() {
        const level = getCoinUpgradeLevel();
        return level < COIN_UPGRADE_MAX_LEVEL ? COIN_UPGRADE_COSTS[level] : null;
    }

    function getNextJumpUpgradeCost() {
        const level = getJumpUpgradeLevel();
        return level < JUMP_UPGRADE_MAX_LEVEL ? JUMP_UPGRADE_COSTS[level] : null;
    }

    function getNextSpeedUpgradeCost() {
        const level = getSpeedUpgradeLevel();
        return level < SPEED_UPGRADE_MAX_LEVEL ? SPEED_UPGRADE_COSTS[level] : null;
    }

    function getCoinPickupValue() {
        const multiplier = Math.max(1, getCoinMultiplier());
        const baseValue = Math.max(1, Math.floor(multiplier));
        coinBonusCarry += Math.max(0, multiplier - baseValue);
        const carriedValue = Math.floor(coinBonusCarry + 0.0001);
        if (carriedValue > 0) coinBonusCarry -= carriedValue;
        return baseValue + carriedValue;
    }

    function isDesktopShellRuntime() {
        return !!(window.elementalRunDesktop || window.elementalRunShell);
    }

    function isBrowserBuild() {
        // Electron's preload bridge is authoritative. A browser bootstrap file
        // accidentally copied into the desktop package must never enable ads.
        return !isDesktopShellRuntime() && window.ELEMENTAL_BROWSER_BUILD === true;
    }

    function isCrazyGamesBuild() {
        return isBrowserBuild() && window.ELEMENTAL_CRAZYGAMES_BUILD === true;
    }

    function isPokiBuild() {
        return isBrowserBuild() && window.ELEMENTAL_POKI_BUILD === true;
    }

    function getPlatformKind() {
        return window.ElementalPlatform && typeof window.ElementalPlatform.kind === 'function'
            ? window.ElementalPlatform.kind()
            : (isCrazyGamesBuild() ? 'crazygames' : (isPokiBuild() ? 'poki' : (isDesktopShellRuntime() ? 'steam' : 'browser')));
    }

    function areRewardedAdsEnabled() {
        if (!isBrowserBuild()) return false;
        // CrazyGames disables monetization in Basic Launch. Showing a reward
        // button that cannot award anything is a QA rejection reason, so the
        // dedicated build enables this only after Full Launch approval.
        if (isPokiBuild()) return BROWSER_CONFIG.pokiRewardedAdsEnabled === true;
        if (isCrazyGamesBuild()) return BROWSER_CONFIG.crazyGamesRewardedAdsEnabled === true;
        // Standalone websites do not have an ad provider. Hiding rewarded
        // affordances is clearer than showing buttons that can never complete.
        return false;
    }

    function crazyGamesPlatform() {
        if (window.ElementalPlatform && typeof window.ElementalPlatform.current === 'function') {
            return window.ElementalPlatform.current();
        }
        return window.ElementalCrazyGames || null;
    }

    function playerFitSafePart(value, fallback = 'unknown') {
        const safe = String(value == null ? '' : value)
            .trim()
            .replace(/[\/^]/g, '-')
            .replace(/\s+/g, '-')
            .replace(/[^a-zA-Z0-9_.-]/g, '')
            .slice(0, 64);
        return safe || fallback;
    }

    function measurePlayerFit(category, what, action) {
        if (!isPokiBuild()) return false;
        const platform = crazyGamesPlatform();
        if (!platform || typeof platform.measure !== 'function') return false;
        platform.measure(
            playerFitSafePart(category, 'game'),
            playerFitSafePart(what),
            playerFitSafePart(action, 'event')
        );
        return true;
    }

    function startPlayerFitLevelAttempt(level, source = 'campaign') {
        const number = Math.max(1, Math.floor(Number(level?.number || level) || 1));
        if (playerFitLevelAttemptOpen) finishPlayerFitLevelAttempt('fail');
        playerFitCurrentLevel = number;
        playerFitLevelAttemptOpen = true;
        measurePlayerFit('level', String(number), 'start');
        measurePlayerFit('level-source', String(number), source);
    }

    function finishPlayerFitLevelAttempt(outcome) {
        if (!playerFitLevelAttemptOpen || playerFitCurrentLevel < 1) return;
        measurePlayerFit('level', String(playerFitCurrentLevel), outcome === 'complete' ? 'complete' : 'fail');
        playerFitLevelAttemptOpen = false;
    }

    function updatePlayerFitMilestones(realDelta) {
        if (!isPokiBuild() || mainMenuVisible || isGamePaused || isGameOver || !runStartedFromMenu) return;
        playerFitActiveSeconds += Math.max(0, Number(realDelta) || 0);
        for (const seconds of PLAYER_FIT_MILESTONES) {
            if (playerFitActiveSeconds < seconds || playerFitMilestonesSent.has(seconds)) continue;
            playerFitMilestonesSent.add(seconds);
            measurePlayerFit('session', 'active-play', `reached-${seconds}s`);
        }
    }

    function trackPlayerFitTutorialState(snapshot) {
        const state = String(snapshot?.state || '');
        if (!state || playerFitTutorialStatesSent.has(state)) return;
        playerFitTutorialStatesSent.add(state);
        const visibleLesson = state.endsWith('-prompt') || state === 'bunny-run';
        if (visibleLesson) {
            const lesson = state.replace('-prompt', '').replace('-run', '');
            measurePlayerFit('tutorial-step', lesson, 'visible');
        }
        const completedLesson = state.endsWith('-clear');
        if (completedLesson) measurePlayerFit('tutorial-step', state.replace('-clear', ''), 'complete');
        if (state === 'rewind') measurePlayerFit('tutorial', 'rewind', 'used');
    }

    function syncCrazyGamesAudioSetting(muted) {
        document.body.classList.toggle('crazygames-muted', !!muted);
        if (muted) {
            stopMenuMusicNow();
            stopGameplayMusicNow();
        } else if (!menuState.muted) {
            if (mainMenuVisible) setMenuAmbientActive(true);
            else if (!isGamePaused && !isGameOver) updateGameplayMusic(true);
        }
    }

    function getRewardBoostUntil(type) {
        const boosts = menuState.rewardBoosts || {};
        return Math.max(0, Number(type === 'score' ? boosts.scoreUntil : boosts.goldUntil) || 0);
    }

    function isRewardBoostActive(type) {
        return isBrowserBuild() && getRewardBoostUntil(type) > Date.now();
    }

    function formatRewardTime(milliseconds) {
        const seconds = Math.max(0, Math.ceil(milliseconds / 1000));
        const minutes = Math.floor(seconds / 60);
        const rest = String(seconds % 60).padStart(2, '0');
        return `${minutes}:${rest}`;
    }

    function showBrowserToast(message, isError = false) {
        if (!ui.browserToast) return;
        if (browserToastTimer) clearTimeout(browserToastTimer);
        ui.browserToast.textContent = message;
        ui.browserToast.classList.toggle('is-error', !!isError);
        ui.browserToast.classList.add('is-visible');
        ui.browserToast.setAttribute('aria-hidden', 'false');
        browserToastTimer = setTimeout(() => {
            ui.browserToast.classList.remove('is-visible');
            ui.browserToast.setAttribute('aria-hidden', 'true');
            browserToastTimer = null;
        }, 2600);
    }

    function updateRewardBoostUi() {
        if (!isBrowserBuild()) return;
        const now = Date.now();
        const scoreRemaining = getRewardBoostUntil('score') - now;
        const goldRemaining = getRewardBoostUntil('gold') - now;
        const scoreLabel = scoreRemaining > 0
            ? `2× ${tr('score')} · ${tr('active')} · ${formatRewardTime(scoreRemaining)}`
            : `2× ${tr('score')} · ${browserTr('watch15')}`;
        const goldLabel = goldRemaining > 0
            ? `2× ${tr('gold')} · ${tr('active')} · ${formatRewardTime(goldRemaining)}`
            : `2× ${tr('gold')} · ${browserTr('watch15')}`;
        if (ui.rewardScoreBtn) {
            ui.rewardScoreBtn.classList.toggle('is-active', scoreRemaining > 0);
            ui.rewardScoreBtn.disabled = rewardedAdBusy;
            ui.rewardScoreBtn.setAttribute('aria-label', scoreLabel);
            ui.rewardScoreBtn.title = scoreLabel;
        }
        if (ui.rewardGoldBtn) {
            ui.rewardGoldBtn.classList.toggle('is-active', goldRemaining > 0);
            ui.rewardGoldBtn.disabled = rewardedAdBusy;
            ui.rewardGoldBtn.setAttribute('aria-label', goldLabel);
            ui.rewardGoldBtn.title = goldLabel;
        }
    }

    function startRewardBoostUiClock() {
        if (rewardBoostUiTimer) clearInterval(rewardBoostUiTimer);
        updateRewardBoostUi();
        rewardBoostUiTimer = setInterval(updateRewardBoostUi, 1000);
    }

    function clearBhopFeedbackForOverlay() {
        // Pause/overlay entry freezes the gameplay update loop. Without clearing
        // the presentation state here, the last xN frame remains pinned above
        // the pause screen after Escape even though the combo is no longer live.
        bhopCombo = 0;
        bhopHudCombo = 0;
        bhopHudVisibleUntil = 0;
        bhopAttemptFailed = false;
        if (ui.bhopContainer) ui.bhopContainer.classList.remove('bhop-active');
        if (ui.bhopCount) ui.bhopCount.innerText = 'x0';
        if (ui.bhopBonus) ui.bhopBonus.innerHTML = '';
    }

    function pauseAudioForRewardedAd() {
        browserAdPauseApplied = true;
        browserAdInterruptedRun = runStartedFromMenu && !mainMenuVisible && !isGameOver && !isGamePaused;
        document.body.classList.add('browser-ad-playing');
        stopMenuMusicNow();
        stopGameplayMusicNow();
        Object.keys(keys).forEach((key) => { keys[key] = false; });
        Object.keys(CONTROL_ACTION_STATE).forEach((key) => { CONTROL_ACTION_STATE[key] = false; });
        mobileMoveX = 0;
        if (browserAdInterruptedRun) {
            isGamePaused = true;
            clearBhopFeedbackForOverlay();
            const platform = crazyGamesPlatform();
            if (platform) platform.gameplayStop();
        }
        setMobileControlsVisible(false);
        try { if (document.pointerLockElement) document.exitPointerLock(); } catch (error) {}
    }

    function armPointerLockRecovery(reason = 'external-overlay', showNow = false) {
        if (!isBrowserBuild() || MOBILE_RUNTIME || !menuState.mouseControlEnabled || mainMenuVisible || isGameOver) return false;
        pointerLockRecoveryPending = true;
        pointerLockRecoveryReason = reason;
        pointerLockRequestInFlight = false;
        if (showNow && !reviveSequenceActive && !rewardedDeathPending) {
            isGamePaused = true;
            clearBhopFeedbackForOverlay();
            if (ui.pauseScreen) ui.pauseScreen.style.display = 'flex';
            setPauseOverlay(tr('tapToStart').toLocaleUpperCase(), tr('pauseHint'));
            const platform = crazyGamesPlatform();
            if (platform) platform.gameplayStop();
        }
        return true;
    }

    function resumeAudioAfterRewardedAd() {
        if (!browserAdPauseApplied) return;
        const resumeMobileGameplay = browserAdInterruptedRun && MOBILE_RUNTIME;
        const recoverDesktopPointer = browserAdInterruptedRun && !MOBILE_RUNTIME;
        browserAdPauseApplied = false;
        browserAdInterruptedRun = false;
        document.body.classList.remove('browser-ad-playing');
        if (recoverDesktopPointer) armPointerLockRecovery('ad-finished', !rewardedDeathPending && !reviveSequenceActive);
        if (resumeMobileGameplay && !rewardedDeathPending && !reviveSequenceActive) {
            isGamePaused = false;
            resumeMobileRun();
        }
        if (!menuState.muted && mainMenuVisible) {
            setMenuAmbientActive(true);
            tryStartMenuMusicAutoplay();
        } else if (!menuState.muted && !isGameOver && !isGamePaused && !reviveSequenceActive && !rewardedDeathPending) {
            updateGameplayMusic(true);
        }
        const platform = crazyGamesPlatform();
        if (platform && !isGamePaused && !isGameOver && !pointerLockRecoveryPending) platform.gameplayStart();
    }

    async function requestRewardedAd(placement) {
        if (!areRewardedAdsEnabled()) return { status: 'unavailable', provider: 'disabled' };
        if (rewardedAdBusy) return { status: 'busy', provider: 'none' };
        const ads = window.ElementalBrowserAds;
        if (!ads || typeof ads.showRewarded !== 'function') return { status: 'unavailable', provider: 'none' };
        rewardedAdBusy = true;
        updateRewardBoostUi();
        updateRewardedUpgradeOfferButtons();
        let adStarted = false;
        try {
            const result = await ads.showRewarded({
                placement,
                labels: {
                    demoAd: browserTr('demoAd'),
                    adPlaying: browserTr('adPlaying'),
                    placement
                },
                onStart: () => {
                    adStarted = true;
                    pauseAudioForRewardedAd();
                },
                onFinish: () => {
                    if (adStarted) resumeAudioAfterRewardedAd();
                }
            });
            return { ...(result || {}), adStarted };
        } finally {
            rewardedAdBusy = false;
            updateRewardBoostUi();
            updateRewardedUpgradeOfferButtons();
        }
    }

    async function activateRewardBoost(type) {
        if (!areRewardedAdsEnabled() || rewardedAdBusy) return;
        const result = await requestRewardedAd(type === 'score' ? 'boost_score_15m' : 'boost_gold_15m');
        if (!result || result.status !== 'completed') {
            showBrowserToast(browserTr('adUnavailable'), true);
            return;
        }
        const key = type === 'score' ? 'scoreUntil' : 'goldUntil';
        const boosts = { ...(menuState.rewardBoosts || {}) };
        boosts[key] = Math.max(Date.now(), Number(boosts[key]) || 0) + REWARD_BOOST_DURATION_MS;
        menuState.rewardBoosts = boosts;
        saveMainMenuState();
        updateRewardBoostUi();
        playUiConfirmSound();
        showBrowserToast(browserTr('rewardGranted'));
    }

    function isGlideActive() {
        return hasGlideUpgrade()
            && getActiveSpecialAbility() === 'glide'
            && isJumping
            && glideTimeLeft > 0.001
            && getPlayerHeightAboveRunFloor() >= GLIDE_MIN_HEIGHT_ABOVE_FLOOR
            && (middleMouseHeld || CONTROL_ACTION_STATE.glide || gamepadGlideHeld)
            && playerVelocityY < -0.02
            && !isSlamming
            && !isGameOver
            && !isGamePaused;
    }

    function setGlideWindActive(active) {
        if (ui.glideWind) ui.glideWind.classList.toggle('is-active', !!active);
    }

    function retriggerAnim(el, className, duration) {
        if (!el) return;
        if (!el.__animTimers) el.__animTimers = {};
        el.classList.remove(className);
        void el.offsetWidth;
        el.classList.add(className);
        clearTimeout(el.__animTimers[className]);
        el.__animTimers[className] = setTimeout(() => { el.classList.remove(className); }, duration);
    }

    function checkScoreMilestoneAnim(scoreFloor) {
        const milestone = Math.floor(scoreFloor / SCORE_MILESTONE_STEP);
        if (milestone <= lastScoreMilestone) return;
        lastScoreMilestone = milestone;
        const cls = SCORE_MILESTONE_ANIMS[scoreMilestoneAnimIndex % SCORE_MILESTONE_ANIMS.length];
        scoreMilestoneAnimIndex++;
        retriggerAnim(ui.scoreContainer, cls, 900);
    }

    function updateSpeedDangerAnim(speedKmh) {
        const shouldShake = speedKmh > SPEED_DANGER_THRESHOLD;
        if (shouldShake === speedDangerActive) return;
        speedDangerActive = shouldShake;
        if (ui.speedIndicator) ui.speedIndicator.classList.toggle('speed-danger', shouldShake);
    }

    function playCoinCollectAnim() {
        retriggerAnim(ui.coinContainer, 'coin-anim-pop', 320);
    }

    function updateDoubleJumpCooldownUi(forceHide = false) {
        if (!ui.doubleJumpCooldown) return;
        const active = !forceHide
            && hasDoubleJumpUpgrade()
            && doubleJumpCooldownTimer > 0.001
            && !mainMenuVisible
            && !isGameOver
            && !isGamePaused;
        ui.doubleJumpCooldown.classList.toggle('is-active', active);
        if (active) ui.doubleJumpCooldown.innerText = Math.max(1, Math.ceil(doubleJumpCooldownTimer - 0.001)).toString();
        if (doubleJumpCooldownWasActive && !active && !forceHide && !isGamePaused && !isGameOver && !mainMenuVisible) {
            retriggerAnim(ui.doubleJumpReadyFlash, 'flash', 550);
        }
        doubleJumpCooldownWasActive = active;
    }

    function canUseDoubleJump() {
        return hasDoubleJumpUpgrade()
            && getActiveSpecialAbility() === 'doubleJump'
            && isJumping
            && !doubleJumpUsedInAir
            && doubleJumpCooldownTimer <= 0
            && !isSlamming
            && !isGameOver
            && !isGamePaused;
    }

    function tryUseDoubleJump() {
        if (!canUseDoubleJump()) return false;
        doubleJumpUsedInAir = true;
        doubleJumpCooldownTimer = getDoubleJumpCooldownTime();
        jumpQueue = false;
        bhopAttemptFailed = false;
        setGlideWindActive(false);
        playerVelocityY = Math.max(playerVelocityY * 0.2, 0) + DOUBLE_JUMP_FORCE;
        if (playerVelocityY > DOUBLE_JUMP_FORCE) playerVelocityY = DOUBLE_JUMP_FORCE;
        updateDoubleJumpCooldownUi();
        playJumpSound();
        spawnArrowEffect('blue');
        noteDailyMissionEvent('useAbility');
        return true;
    }

    function handleWheelDoubleJumpInput() {
        if (getActiveSpecialAbility() !== 'doubleJump' || !hasDoubleJumpUpgrade() || !isJumping || isGameOver || isGamePaused) {
            return false;
        }
        const now = performance.now();
        if (now - lastWheelSkillTapAt > 430) wheelSkillTapCount = 0;
        lastWheelSkillTapAt = now;
        wheelSkillTapCount += 1;
        if (wheelSkillTapCount >= 2) {
            wheelSkillTapCount = 0;
            return tryUseDoubleJump();
        }
        return false;
    }

    // ===== Zaman Yavaşlatma yeteneği =====
    function tryActivateTimeSlow() {
        if (getActiveSpecialAbility() !== 'timeSlow') return false;
        if (timeSlowActive || timeSlowCooldown > 0) return false;
        if (isGameOver || isGamePaused || mainMenuVisible || isDying) return false;
        if (typeof scene === 'undefined' || !scene) return false;
        timeSlowActive = true;
        timeSlowTimer = getTimeSlowDurationTime();
        // Shader yolu (composer aktif) materyalleri ellemez → pahalı sahne taramasını yalnızca composer'sızken yap.
        if (!gfxComposerActive) collectTimeSlowGrayTargets();
        try { playTimeSlowSound(); } catch (e) {}
        updateTimeSlowUi();
        noteDailyMissionEvent('useAbility');
        return true;
    }

    function advanceTimeSlowState(realDelta) {
        if (timeSlowCooldown > 0) timeSlowCooldown = Math.max(0, timeSlowCooldown - realDelta);
        if (timeSlowActive) {
            timeSlowTimer -= realDelta;
            if (timeSlowTimer <= 0) {
                timeSlowTimer = 0;
                timeSlowActive = false;
                timeSlowCooldown = getTimeSlowCooldownTime();
            }
        }
        const target = timeSlowActive ? 1 : 0;
        // aktive olurken hızlı, kapanırken yumuşak ramp
        const rate = (target > timeSlowBlend ? 7.0 : 3.5);
        timeSlowBlend += (target - timeSlowBlend) * Math.min(1, rate * realDelta);
        if (Math.abs(timeSlowBlend - target) < 0.002) timeSlowBlend = target;
    }

    function getWorldTimeScale() {
        const abilityScale = 1 - (1 - TIME_SLOW_FACTOR) * timeSlowBlend;
        return abilityScale * getTutorialWorldTimeScale() * (timeRewindSequence ? 0 : 1);
    }

    // Renk KIRMIZI mı? (kırmızı baskın + yeşil/mavi düşük) → yalnızca kırmızı gri efektten korunur.
    function isRedColor(c) {
        return c.r > 0.4 && c.g < 0.4 && c.b < 0.4 && (c.r - Math.max(c.g, c.b)) > 0.18;
    }

    function collectTimeSlowGrayTargets() {
        if (timeSlowGrayMats) return; // zaten yakalanmış
        const seen = new Set();
        const list = [];
        const addMat = (m) => {
            if (!m || !m.isMaterial || seen.has(m)) return;
            seen.add(m);
            if (m.userData && (m.userData.isRoadColor || m.userData.skipTimeSlowGray)) return;
            const entry = { m };
            // Saf R/G/B materyalleri grileştirme (kullanıcı isteği) → orijinali sakla ama skip işaretle.
            if (m.color && m.color.isColor) { entry.color = m.color.clone(); entry.skipColor = isRedColor(m.color); }
            if (m.emissive && m.emissive.isColor) { entry.emissive = m.emissive.clone(); entry.skipEmissive = isRedColor(m.emissive); }
            if (entry.color || entry.emissive) list.push(entry);
        };
        // 1) Sahnedeki tüm canlı materyaller
        scene.traverse((obj) => {
            if (!obj || !obj.material) return;
            const mats2 = Array.isArray(obj.material) ? obj.material : [obj.material];
            for (const m of mats2) addMat(m);
        });
        // 2) Paylaşılan materyal kaydı (mats) — slow sırasında SPAWN olan engeller/dekor
        //    bu paylaşılan örnekleri kullanır; henüz sahnede olmasalar bile grileştir.
        if (typeof mats !== 'undefined' && mats) {
            for (const key in mats) {
                const v = mats[key];
                if (!v) continue;
                if (Array.isArray(v)) { for (const m of v) addMat(m); }
                else addMat(v);
            }
        }
        timeSlowGrayMats = list;
        timeSlowFogOrig = (scene.fog && scene.fog.color) ? scene.fog.color.clone() : null;
        timeSlowBgOrig = (scene.background && scene.background.isColor) ? scene.background.clone() : null;
    }

    function grayLerpColor(target, orig, amount) {
        const lum = orig.r * 0.299 + orig.g * 0.587 + orig.b * 0.114;
        target.setRGB(
            orig.r + (lum - orig.r) * amount,
            orig.g + (lum - orig.g) * amount,
            orig.b + (lum - orig.b) * amount
        );
    }

    function applyTimeSlowVisuals() {
        const amount = Math.min(1, timeSlowBlend * TIME_SLOW_GRAY_STRENGTH);
        // Composer aktifse (high/ultra): ekran-uzayı seçici desaturasyon shader'ı kullan.
        // Dokulu/neon/backdrop dahil TÜM kareyi grileştirir, saf R/G/B'yi korur.
        const useShader = gfxComposerActive && !!gfxDesatPass;
        if (gfxDesatPass) {
            gfxDesatPass.enabled = useShader && timeSlowBlend > 0.001;
            if (gfxDesatPass.material && gfxDesatPass.material.uniforms.uAmount) {
                gfxDesatPass.material.uniforms.uAmount.value = useShader ? amount : 0.0;
            }
        }
        if (!timeSlowGrayMats) return;
        // tamamen kapandıysa orijinalleri geri yükle ve serbest bırak
        if (!timeSlowActive && timeSlowBlend <= 0.002) {
            restoreTimeSlowVisuals();
            return;
        }
        // Shader yolu materyalleri ELLEMEZ (orijinal renkler shader'a girmeli) → atla.
        if (useShader) return;
        // Composer'sız yol (low/medium): materyal-düzeyi seçici desaturasyon.
        for (const e of timeSlowGrayMats) {
            if (e.color && !e.skipColor) grayLerpColor(e.m.color, e.color, amount);
            if (e.emissive && !e.skipEmissive) grayLerpColor(e.m.emissive, e.emissive, amount);
        }
        if (timeSlowFogOrig && scene.fog && scene.fog.color && !isRedColor(timeSlowFogOrig)) grayLerpColor(scene.fog.color, timeSlowFogOrig, amount);
        if (timeSlowBgOrig && scene.background && scene.background.isColor && !isRedColor(timeSlowBgOrig)) grayLerpColor(scene.background, timeSlowBgOrig, amount);
    }

    function restoreTimeSlowVisuals() {
        if (timeSlowGrayMats) {
            for (const e of timeSlowGrayMats) {
                if (e.color) e.m.color.copy(e.color);
                if (e.emissive) e.m.emissive.copy(e.emissive);
            }
            timeSlowGrayMats = null;
        }
        if (timeSlowFogOrig && scene.fog && scene.fog.color) { scene.fog.color.copy(timeSlowFogOrig); }
        timeSlowFogOrig = null;
        if (timeSlowBgOrig && scene.background && scene.background.isColor) { scene.background.copy(timeSlowBgOrig); }
        timeSlowBgOrig = null;
        if (renderer && renderer.domElement) renderer.domElement.style.filter = '';
        if (gfxDesatPass) {
            gfxDesatPass.enabled = false;
            if (gfxDesatPass.material && gfxDesatPass.material.uniforms.uAmount) gfxDesatPass.material.uniforms.uAmount.value = 0.0;
        }
    }

    function forceEndTimeSlow() {
        timeSlowActive = false;
        timeSlowTimer = 0;
        timeSlowBlend = 0;
        restoreTimeSlowVisuals();
        updateTimeSlowUi();
    }

    // --- Mıknatıs yeteneği ---
    function tryActivateMagnet() {
        if (getActiveSpecialAbility() !== 'magnet') return false;
        if (magnetActive || magnetCooldown > 0) return false;
        if (isGameOver || isGamePaused || mainMenuVisible || isDying) return false;
        magnetActive = true;
        magnetTimer = getMagnetDurationTime();
        try { playMagnetSound(); } catch (e) {}
        updateMagnetUi();
        noteDailyMissionEvent('useAbility');
        return true;
    }

    function advanceMagnetState(realDelta) {
        magnetPulseT += realDelta;
        if (magnetCooldown > 0) magnetCooldown = Math.max(0, magnetCooldown - realDelta);
        if (magnetActive) {
            magnetTimer -= realDelta;
            if (magnetTimer <= 0) {
                magnetTimer = 0;
                magnetActive = false;
                magnetCooldown = getMagnetCooldownTime();
            }
        }
        const target = magnetActive ? 1 : 0;
        const rate = (target > magnetBlend ? 8.0 : 3.5);
        magnetBlend += (target - magnetBlend) * Math.min(1, rate * realDelta);
        if (Math.abs(magnetBlend - target) < 0.002) magnetBlend = target;
    }

    function forceEndMagnet() {
        magnetActive = false;
        magnetTimer = 0;
        magnetBlend = 0;
        updateMagnetUi();
    }

    function getClosestLaneIndex(z = player?.position?.z || 0) {
        let best = 0;
        let bestDistance = Infinity;
        for (let i = 0; i < lanePositions.length; i++) {
            const distance = Math.abs(lanePositions[i] - z);
            if (distance < bestDistance) { best = i; bestDistance = distance; }
        }
        return best;
    }

    function clearTimeRewindHistory() {
        timeRewindHead = 0;
        timeRewindCount = 0;
        timeRewindSampleAccumulator = 0;
        timeRewindSequence = null;
        timeRewindInvulnerability = 0;
    }

    function recordTimeRewindHistory(realDelta) {
        if (!player || timeRewindSequence || isGamePaused || isGameOver || mainMenuVisible) return;
        timeRewindSampleAccumulator += Math.max(0, realDelta || 0);
        const step = 1 / TIME_REWIND_SAMPLE_RATE;
        while (timeRewindSampleAccumulator >= step) {
            timeRewindSampleAccumulator -= step;
            const index = timeRewindHead;
            timeRewindX[index] = player.position.x;
            timeRewindY[index] = player.position.y;
            timeRewindZ[index] = player.position.z;
            timeRewindVy[index] = playerVelocityY;
            timeRewindFlags[index] = (isJumping ? 1 : 0) | (isSliding ? 2 : 0);
            timeRewindLane[index] = getClosestLaneIndex();
            timeRewindHead = (timeRewindHead + 1) % TIME_REWIND_CAPACITY;
            timeRewindCount = Math.min(TIME_REWIND_CAPACITY, timeRewindCount + 1);
        }
    }

    function isHandSkillCollisionImmune() {
        return !!(phaseShiftActive || timeRewindSequence || timeRewindInvulnerability > 0);
    }

    function canTriggerActiveHandSkill(expected) {
        return getActiveSpecialAbility() === expected && !isGameOver && !isGamePaused
            && !mainMenuVisible && !isDying && !!player;
    }

    function tryActivateAirDash() {
        if (!canTriggerActiveHandSkill('airDash') || airDashActive || airDashCooldown > 0) return false;
        airDashActive = true;
        airDashTimer = AIR_DASH_DURATION;
        airDashFrozenVelocityY = playerVelocityY;
        ensureHandSkillFxPoints('airDash');
        playHandSkillSfx('airDash');
        noteDailyMissionEvent('useAbility');
        updateHandSkillUi();
        return true;
    }

    function tryActivateTimeRewind() {
        if (!canTriggerActiveHandSkill('timeRewind') || timeRewindSequence || timeRewindCooldown > 0 || timeRewindCount < 12) return false;
        const oldest = (timeRewindHead - timeRewindCount + TIME_REWIND_CAPACITY) % TIME_REWIND_CAPACITY;
        timeRewindSequence = {
            elapsed: 0,
            from: { x: player.position.x, y: player.position.y, z: player.position.z, vy: playerVelocityY },
            to: {
                x: timeRewindX[oldest], y: timeRewindY[oldest], z: timeRewindZ[oldest], vy: timeRewindVy[oldest],
                flags: timeRewindFlags[oldest], lane: timeRewindLane[oldest]
            }
        };
        resetControlActionState();
        ensureHandSkillFxPoints('timeRewind');
        playHandSkillSfx('timeRewind');
        noteDailyMissionEvent('useAbility');
        updateHandSkillUi();
        return true;
    }

    function tryActivatePhaseShift() {
        if (!canTriggerActiveHandSkill('phaseShift') || phaseShiftActive || phaseShiftCooldown > 0) return false;
        phaseShiftActive = true;
        phaseShiftTimer = rebirthScaledDuration(PHASE_SHIFT_DURATION);
        ensureHandSkillFxPoints('phaseShift');
        playHandSkillSfx('phaseShift');
        noteDailyMissionEvent('useAbility');
        updateHandSkillUi();
        return true;
    }

    function triggerActiveHandSkill() {
        const ability = getActiveSpecialAbility();
        if (ability === 'timeSlow') return tryActivateTimeSlow();
        if (ability === 'magnet') return tryActivateMagnet();
        if (ability === 'airDash') return tryActivateAirDash();
        if (ability === 'timeRewind') return tryActivateTimeRewind();
        if (ability === 'phaseShift') return tryActivatePhaseShift();
        return false;
    }

    function advanceHandSkillState(realDelta) {
        const dt = Math.max(0, Number(realDelta) || 0);
        airDashCooldown = Math.max(0, airDashCooldown - dt);
        timeRewindCooldown = Math.max(0, timeRewindCooldown - dt);
        phaseShiftCooldown = Math.max(0, phaseShiftCooldown - dt);
        timeRewindInvulnerability = Math.max(0, timeRewindInvulnerability - dt);

        if (airDashActive) {
            airDashTimer -= dt;
            if (isJumping) playerVelocityY = airDashFrozenVelocityY;
            if (airDashTimer <= 0) {
                airDashActive = false;
                airDashTimer = 0;
                airDashCooldown = rebirthScaledCooldown(AIR_DASH_COOLDOWN);
            }
        }
        airDashBlend += ((airDashActive ? 1 : 0) - airDashBlend) * Math.min(1, dt * (airDashActive ? 18 : 7));

        if (timeRewindSequence && player) {
            timeRewindSequence.elapsed += dt;
            const raw = Math.min(1, timeRewindSequence.elapsed / TIME_REWIND_PLAYBACK_SECONDS);
            const t = raw * raw * (3 - 2 * raw);
            const from = timeRewindSequence.from;
            const to = timeRewindSequence.to;
            player.position.set(
                THREE.MathUtils.lerp(from.x, to.x, t),
                THREE.MathUtils.lerp(from.y, to.y, t),
                THREE.MathUtils.lerp(from.z, to.z, t)
            );
            playerVelocityY = THREE.MathUtils.lerp(from.vy, to.vy, t);
            updatePlayerSweepStart();
            updatePlayerSweepEnd();
            if (raw >= 1) {
                isJumping = !!(to.flags & 1);
                isSliding = !!(to.flags & 2);
                document.body.classList.toggle('sliding', isSliding);
                timeRewindSequence = null;
                timeRewindCooldown = rebirthScaledCooldown(TIME_REWIND_COOLDOWN);
                timeRewindInvulnerability = 0.35;
                timeRewindCount = 0;
                timeRewindHead = 0;
                playHandSkillSfx('timeRewindEnd');
            }
        } else {
            recordTimeRewindHistory(dt);
        }

        if (phaseShiftActive) {
            phaseShiftTimer -= dt;
            if (phaseShiftTimer <= 0) {
                phaseShiftActive = false;
                phaseShiftTimer = 0;
                phaseShiftCooldown = rebirthScaledCooldown(PHASE_SHIFT_COOLDOWN);
                playHandSkillSfx('phaseShiftEnd');
            }
        }
        phaseShiftBlend += ((phaseShiftActive ? 1 : 0) - phaseShiftBlend) * Math.min(1, dt * (phaseShiftActive ? 10 : 5));
        updateHandSkillFxPoints(dt);
    }

    function getHandSkillDisplayState() {
        const ability = getActiveSpecialAbility();
        if (ability === 'airDash') return { ability, active: airDashActive, remaining: airDashActive ? airDashTimer : airDashCooldown, duration: airDashActive ? AIR_DASH_DURATION : rebirthScaledCooldown(AIR_DASH_COOLDOWN) };
        if (ability === 'timeRewind') return { ability, active: !!timeRewindSequence, remaining: timeRewindSequence ? Math.max(0, TIME_REWIND_PLAYBACK_SECONDS - timeRewindSequence.elapsed) : timeRewindCooldown, duration: timeRewindSequence ? TIME_REWIND_PLAYBACK_SECONDS : rebirthScaledCooldown(TIME_REWIND_COOLDOWN) };
        if (ability === 'phaseShift') return { ability, active: phaseShiftActive, remaining: phaseShiftActive ? phaseShiftTimer : phaseShiftCooldown, duration: phaseShiftActive ? rebirthScaledDuration(PHASE_SHIFT_DURATION) : rebirthScaledCooldown(PHASE_SHIFT_COOLDOWN) };
        return null;
    }

    function ensureHandSkillUi() {
        if (handSkillUi) return handSkillUi;
        const hud = document.createElement('div');
        hud.id = 'hand-skill-hud';
        hud.innerHTML = '<span class="hand-skill-ring"><b></b></span><span class="hand-skill-copy"><strong></strong><small>E</small></span>';
        const fx = document.createElement('div');
        fx.id = 'hand-skill-screen-fx';
        document.body.append(hud, fx);
        handSkillUi = { hud, ring: hud.querySelector('.hand-skill-ring'), icon: hud.querySelector('b'), name: hud.querySelector('strong'), time: hud.querySelector('small'), fx };
        return handSkillUi;
    }

    function updateHandSkillUi() {
        const uiState = ensureHandSkillUi();
        const state = getHandSkillDisplayState();
        // Skill HUD belongs to an active run only. Paused/menu/shop states may
        // stop the gameplay update loop, so use the native hidden flag as well
        // as the animation class; this prevents the last gameplay frame from
        // remaining visible over the main menu.
        const hidden = !state || isGameOver || mainMenuVisible || isGamePaused
            || !runStartedFromMenu || handShopPreviewActive;
        uiState.hud.hidden = hidden;
        uiState.fx.hidden = hidden;
        uiState.hud.classList.toggle('is-visible', !hidden);
        uiState.fx.className = '';
        if (hidden) return;
        const meta = HAND_SKILL_META[state.ability];
        const ratio = state.duration > 0 ? THREE.MathUtils.clamp(state.remaining / state.duration, 0, 1) : 0;
        uiState.hud.dataset.skill = state.ability;
        uiState.hud.classList.toggle('is-active', !!state.active);
        uiState.ring.style.setProperty('--skill-progress', `${Math.round(ratio * 360)}deg`);
        uiState.icon.textContent = meta?.icon || '✦';
        uiState.name.textContent = tr('handSkill_' + state.ability);
        uiState.time.textContent = state.remaining > 0 ? `${state.remaining.toFixed(state.remaining < 1 ? 1 : 0)}s` : 'E';
        if (state.active) uiState.fx.className = `is-${state.ability}`;
    }

    function ensureHandSkillFxPoints(kind) {
        if (!viewmodelHands) return null;
        if (!handSkillFxPoints) {
            const geometry = new THREE.BufferGeometry();
            geometry.setAttribute('position', new THREE.BufferAttribute(new Float32Array(24 * 3), 3));
            const material = new THREE.PointsMaterial({ size: 0.012, transparent: true, opacity: 0.7, depthTest: false, depthWrite: false, blending: THREE.AdditiveBlending });
            handSkillFxPoints = new THREE.Points(geometry, material);
            handSkillFxPoints.layers.set(VIEWMODEL_LAYER);
            handSkillFxPoints.frustumCulled = false;
            viewmodelHands.add(handSkillFxPoints);
        }
        handSkillFxPoints.userData.kind = kind;
        handSkillFxPoints.material.color.set(kind === 'phaseShift' ? 0x9b48ff : (kind === 'timeRewind' ? 0x4ce9ff : 0xe6fbff));
        handSkillFxPoints.visible = true;
        return handSkillFxPoints;
    }

    function updateHandSkillFxPoints(dt) {
        if (!handSkillFxPoints) return;
        const active = airDashActive || !!timeRewindSequence || phaseShiftActive;
        handSkillFxPoints.visible = active && !!viewmodelRig?.visible;
        if (!handSkillFxPoints.visible) return;
        const positions = handSkillFxPoints.geometry.attributes.position.array;
        const t = (clock?.getElapsedTime?.() || performance.now() * 0.001);
        const kind = handSkillFxPoints.userData.kind;
        for (let i = 0; i < 24; i++) {
            const side = i & 1 ? 1 : -1;
            const phase = t * (kind === 'timeRewind' ? -7 : 8) + i * 1.71;
            positions[i * 3] = side * (0.19 + (i % 6) * 0.045) + Math.sin(phase) * 0.025;
            positions[i * 3 + 1] = -0.8 + ((i * 7) % 13) * 0.045 + Math.cos(phase * 0.8) * 0.025;
            positions[i * 3 + 2] = -0.55 - ((t * (kind === 'airDash' ? 1.8 : 0.35) + i * 0.07) % 0.45);
        }
        handSkillFxPoints.geometry.attributes.position.needsUpdate = true;
        handSkillFxPoints.material.opacity = kind === 'phaseShift' ? 0.76 : 0.58;
    }

    function setViewmodelSkillOpacity(opacity) {
        viewmodelGlbPivot?.traverse?.((object) => {
            if (!object.isMesh || !object.material) return;
            const materials = Array.isArray(object.material) ? object.material : [object.material];
            materials.forEach((material) => {
                if (!Number.isFinite(material.userData.handBaseOpacity)) material.userData.handBaseOpacity = Number.isFinite(material.opacity) ? material.opacity : 1;
                material.transparent = opacity < 0.999 || material.userData.handBaseOpacity < 0.999;
                material.opacity = material.userData.handBaseOpacity * opacity;
            });
        });
    }

    function disposeHandSkillFxPoints() {
        if (!handSkillFxPoints) return;
        handSkillFxPoints.parent?.remove(handSkillFxPoints);
        handSkillFxPoints.geometry?.dispose?.();
        handSkillFxPoints.material?.dispose?.();
        handSkillFxPoints = null;
    }

    function forceEndAllHandSkills(resetCooldowns = false) {
        airDashActive = false; airDashTimer = 0; airDashBlend = 0;
        phaseShiftActive = false; phaseShiftTimer = 0; phaseShiftBlend = 0;
        clearTimeRewindHistory();
        if (resetCooldowns) { airDashCooldown = 0; timeRewindCooldown = 0; phaseShiftCooldown = 0; }
        setViewmodelSkillOpacity(1);
        disposeHandSkillFxPoints();
        if (handSkillUi) { handSkillUi.hud.classList.remove('is-visible'); handSkillUi.fx.className = ''; }
    }

    function playTimeSlowSound() {
        if (!audioContext || !timeSlowSfxBuffer) { loadTimeSlowSfx(); return; }
        try {
            if (audioContext.state === 'suspended') audioContext.resume();
            const src = audioContext.createBufferSource();
            src.buffer = timeSlowSfxBuffer;
            // Pitch/hız kaydırarak sesi orijinalinden farklılaştır.
            try { src.playbackRate.value = TIME_SLOW_SFX_PITCH; } catch (e) {}
            try { if (src.detune) src.detune.value = TIME_SLOW_SFX_DETUNE; } catch (e) {}
            const g = audioContext.createGain();
            g.gain.value = TIME_SLOW_SFX_GAIN;
            // sfxGain → masterGain zincirine bağla: ses/mute ayarları otomatik uygulanır.
            src.connect(g).connect(sfxGain || masterGain || audioContext.destination);
            const offset = Math.max(0, Math.min(TIME_SLOW_SFX_OFFSET, timeSlowSfxBuffer.duration - 0.05));
            src.start(0, offset); // ikinci argüman = buffer içi başlangıç ofseti (saniye)
        } catch (e) {}
    }

    function ensureTimeSlowUi() {
        if (timeSlowUi) return timeSlowUi;
        // Diğer skill HUD'larıyla (double-jump cooldown) aynı stil: büyük Orbitron sayı, sol-alt.
        const label = document.createElement('div');
        label.id = 'timeSlowIndicator';
        label.style.cssText = "position:absolute;left:26px;bottom:24px;z-index:7;display:none;pointer-events:none;font-family:'Orbitron','Rajdhani',sans-serif;font-size:54px;font-weight:900;line-height:1;color:rgba(255,255,255,0.96);text-shadow:0 0 16px rgba(255,255,255,0.42),0 4px 14px rgba(0,0,0,0.56);";
        document.body.appendChild(label);
        // ekran kenarı vignette (aktifken belirir)
        const vign = document.createElement('div');
        vign.id = 'timeSlowVignette';
        vign.style.cssText = 'position:fixed;inset:0;z-index:6;pointer-events:none;opacity:0;background:radial-gradient(ellipse at center, rgba(0,0,0,0) 52%, rgba(120,170,210,0.10) 78%, rgba(40,70,110,0.30) 100%);transition:opacity 0.2s;';
        document.body.appendChild(vign);
        timeSlowUi = { label, vign };
        return timeSlowUi;
    }

    function updateTimeSlowUi() {
        const u = ensureTimeSlowUi();
        const hidden = isGameOver || mainMenuVisible || getActiveSpecialAbility() !== 'timeSlow';
        if (hidden) { u.label.style.display = 'none'; u.vign.style.opacity = '0'; return; }
        u.vign.style.opacity = timeSlowBlend > 0.01 ? (0.85 * timeSlowBlend).toFixed(2) : '0';
        if (timeSlowActive) {
            // aktif süre sayacı — cyan tonla (zaman duruyor hissi)
            u.label.style.display = 'block';
            u.label.style.color = 'rgba(155,231,255,0.98)';
            u.label.textContent = Math.max(1, Math.ceil(timeSlowTimer - 0.001)).toString();
        } else if (timeSlowCooldown > 0) {
            // cooldown sayacı — double-jump ile aynı beyaz stil
            u.label.style.display = 'block';
            u.label.style.color = 'rgba(255,255,255,0.96)';
            u.label.textContent = Math.max(1, Math.ceil(timeSlowCooldown - 0.001)).toString();
        } else {
            // hazır → double-jump gibi gizli
            u.label.style.display = 'none';
        }
    }

    let magnetUi = null;
    function ensureMagnetUi() {
        if (magnetUi) return magnetUi;
        // Cooldown/aktif sayaç — time-slow/double-jump ile aynı sol-alt Orbitron stili.
        const label = document.createElement('div');
        label.id = 'magnetIndicator';
        label.style.cssText = "position:absolute;left:26px;bottom:24px;z-index:7;display:none;pointer-events:none;font-family:'Orbitron','Rajdhani',sans-serif;font-size:54px;font-weight:900;line-height:1;color:rgba(255,255,255,0.96);text-shadow:0 0 16px rgba(120,200,255,0.5),0 4px 14px rgba(0,0,0,0.56);";
        // Küçük mıknatıs ikonu sayacın üstünde
        const icon = document.createElement('div');
        icon.style.cssText = "position:absolute;left:0;bottom:66px;font-size:26px;filter:drop-shadow(0 0 10px rgba(120,200,255,0.7));";
        icon.textContent = '🧲';
        label.appendChild(icon);
        const num = document.createElement('span');
        label.appendChild(num);
        document.body.appendChild(label);
        // Manyetik alan vignette (aktifken mavi kenar parıltısı)
        const vign = document.createElement('div');
        vign.id = 'magnetVignette';
        vign.style.cssText = 'position:fixed;inset:0;z-index:6;pointer-events:none;opacity:0;background:radial-gradient(ellipse at center, rgba(0,0,0,0) 50%, rgba(80,170,255,0.12) 76%, rgba(40,110,220,0.34) 100%);transition:opacity 0.2s;';
        document.body.appendChild(vign);
        // Ekran ortasında dönen manyetik alan halkaları (aktifken)
        const ring = document.createElement('div');
        ring.id = 'magnetRing';
        ring.style.cssText = "position:fixed;left:50%;top:50%;width:340px;height:340px;margin:-170px 0 0 -170px;z-index:6;pointer-events:none;opacity:0;transition:opacity 0.25s;border-radius:50%;border:2px solid rgba(120,200,255,0.28);box-shadow:0 0 60px rgba(90,170,255,0.22) inset, 0 0 40px rgba(90,170,255,0.18);";
        document.body.appendChild(ring);
        magnetUi = { label, icon, num, vign, ring };
        return magnetUi;
    }

    function updateMagnetUi() {
        const u = ensureMagnetUi();
        const hidden = isGameOver || mainMenuVisible || getActiveSpecialAbility() !== 'magnet';
        if (hidden) { u.label.style.display = 'none'; u.vign.style.opacity = '0'; u.ring.style.opacity = '0'; return; }
        u.vign.style.opacity = magnetBlend > 0.01 ? (0.9 * magnetBlend).toFixed(2) : '0';
        if (magnetBlend > 0.01) {
            const pulse = 1 + Math.sin(magnetPulseT * 6.0) * 0.06;
            const spin = (magnetPulseT * 40) % 360;
            u.ring.style.opacity = (0.85 * magnetBlend).toFixed(2);
            u.ring.style.transform = `rotate(${spin.toFixed(1)}deg) scale(${(pulse * (0.7 + 0.3 * magnetBlend)).toFixed(3)})`;
        } else {
            u.ring.style.opacity = '0';
        }
        if (magnetActive) {
            u.label.style.display = 'block';
            u.label.style.color = 'rgba(150,210,255,0.98)';
            u.num.textContent = Math.max(1, Math.ceil(magnetTimer - 0.001)).toString();
        } else if (magnetCooldown > 0) {
            u.label.style.display = 'block';
            u.label.style.color = 'rgba(255,255,255,0.96)';
            u.num.textContent = Math.max(1, Math.ceil(magnetCooldown - 0.001)).toString();
        } else {
            u.label.style.display = 'none';
        }
    }

    function getWheelScrollDirection(e) {
        if (!e) return 0;
        if (typeof e.deltaY === 'number' && Math.abs(e.deltaY) > 0.01) return Math.sign(e.deltaY);
        if (typeof e.wheelDelta === 'number' && Math.abs(e.wheelDelta) > 0.01) return Math.sign(-e.wheelDelta);
        if (typeof e.detail === 'number' && Math.abs(e.detail) > 0.01) return Math.sign(e.detail);
        return 0;
    }

    function setControllerInputActive(active) {
        controllerInputActive = !!active;
        document.body.classList.toggle('controller-active', controllerInputActive);
    }

    function markMouseInputActive() {
        if (controllerInputActive) setControllerInputActive(false);
    }

    function normalizeGamepadAxis(value) {
        const raw = Number(value) || 0;
        const magnitude = Math.abs(raw);
        if (magnitude < GAMEPAD_AXIS_DEADZONE) return 0;
        return Math.sign(raw) * Math.min(1, (magnitude - GAMEPAD_AXIS_DEADZONE) / (1 - GAMEPAD_AXIS_DEADZONE));
    }

    function ensureGamepadAxisNeutral(pad) {
        if (!pad) return;
        const key = `${pad.index}:${pad.id || 'gamepad'}:${pad.axes ? pad.axes.length : 0}`;
        if (gamepadAxisNeutralKey === key) return;
        gamepadAxisNeutralKey = key;
        gamepadAxisNeutral = Array.from(pad.axes || [], value => Number(value) || 0);
    }

    function readGamepadAxis(pad, index) {
        if (!pad || !pad.axes || index >= pad.axes.length) return 0;
        ensureGamepadAxisNeutral(pad);
        const raw = Number(pad.axes[index]) || 0;
        const neutral = Number(gamepadAxisNeutral[index]) || 0;
        return Math.max(-1, Math.min(1, raw - neutral));
    }

    function readStrongestGamepadAxis(pad, indices) {
        let strongest = 0;
        for (const index of indices) {
            const value = readGamepadAxis(pad, index);
            if (Math.abs(value) > Math.abs(strongest)) strongest = value;
        }
        return strongest;
    }

    function gamepadButtonGroups(pad) {
        const standard = pad && pad.mapping === 'standard';
        return {
            confirm: standard ? [0] : [0],
            cancel: standard ? [1] : [1, 2],
            jump: standard ? [0, 12] : [0, 12],
            slide: standard ? [1, 13] : [1, 5, 13],
            glide: standard ? [4, 6, 7] : [4, 6, 7, 10, 11],
            doubleJump: standard ? [3] : [3, 10],
            skill: [2],
            menu: standard ? [8, 9] : [8, 9, 11]
        };
    }

    function getPrimaryGamepad() {
        if (!navigator.getGamepads) return null;
        const pads = navigator.getGamepads();
        let firstConnected = null;
        let mostActivePad = null;
        let mostActiveScore = 0;
        for (const pad of pads) {
            if (!pad || !pad.connected) continue;
            if (!firstConnected) firstConnected = pad;
            ensureGamepadAxisNeutral(pad);
            let activity = 0;
            if (pad.buttons) {
                for (const button of pad.buttons) {
                    if (button && (button.pressed || button.value > GAMEPAD_TRIGGER_THRESHOLD)) activity += 1 + button.value;
                }
            }
            if (pad.axes) {
                for (let i = 0; i < pad.axes.length; i++) activity += Math.abs(normalizeGamepadAxis(readGamepadAxis(pad, i)));
            }
            if (activity > mostActiveScore) {
                mostActiveScore = activity;
                mostActivePad = pad;
            }
        }
        if (mostActivePad && mostActiveScore > 0.05) {
            activeGamepadIndex = mostActivePad.index;
            return mostActivePad;
        }
        if (activeGamepadIndex !== null) {
            const activePad = pads[activeGamepadIndex];
            if (activePad && activePad.connected) return activePad;
        }
        if (firstConnected) {
            activeGamepadIndex = firstConnected.index;
            return firstConnected;
        }
        activeGamepadIndex = null;
        return null;
    }

    function gamepadButtonDown(pad, index) {
        const button = pad && pad.buttons ? pad.buttons[index] : null;
        return !!button && (button.pressed || button.value >= GAMEPAD_TRIGGER_THRESHOLD);
    }

    function anyGamepadButtonDown(pad, indices) {
        return indices.some(index => gamepadButtonDown(pad, index));
    }

    function anyGamepadButtonJustPressed(indices) {
        return indices.some(index => gamepadButtons[index] && !gamepadPrevButtons[index]);
    }

    function gamepadAxisPressed(pad, indices, direction = 0) {
        return indices.some(index => {
            const value = normalizeGamepadAxis(readGamepadAxis(pad, index));
            if (direction < 0) return value < -GAMEPAD_TRIGGER_THRESHOLD;
            if (direction > 0) return value > GAMEPAD_TRIGGER_THRESHOLD;
            return Math.abs(value) > GAMEPAD_TRIGGER_THRESHOLD;
        });
    }

    function readGamepadLookAxes(pad) {
        if (!pad) return { x: 0, y: 0 };
        if (pad.mapping === 'standard') {
            return {
                x: normalizeGamepadAxis(readGamepadAxis(pad, 0)),
                y: normalizeGamepadAxis(readGamepadAxis(pad, 1))
            };
        }
        return {
            x: normalizeGamepadAxis(readGamepadAxis(pad, 0)),
            y: normalizeGamepadAxis(readGamepadAxis(pad, 1))
        };
    }

    function readGamepadStrafeAxis(pad) {
        if (!pad) return 0;
        if (pad.mapping === 'standard') return normalizeGamepadAxis(readGamepadAxis(pad, 2));
        return normalizeGamepadAxis(readStrongestGamepadAxis(pad, [2, 3, 4, 5]));
    }

    function updateGamepadButtonSnapshots(pad) {
        const count = Math.max(gamepadButtons.length, pad && pad.buttons ? pad.buttons.length : 0, 16);
        for (let i = 0; i < count; i++) {
            gamepadPrevButtons[i] = !!gamepadButtons[i];
            gamepadButtons[i] = gamepadButtonDown(pad, i);
        }
    }

    function resetGamepadRuntimeInput() {
        gamepadMoveInput = 0;
        gamepadJumpHeld = false;
        gamepadGlideHeld = false;
        if (!CONTROL_ACTION_STATE.jump) {
            jumpKeyPressed = false;
            jumpQueue = false;
        }
    }

    function pauseRunForExternalInterruption(title = tr('pauseTitle'), subtitle = tr('pauseHint')) {
        if (mainMenuVisible || isGameOver || isGamePaused) return false;
        isGamePaused = true;
        forceEndAllHandSkills(false);
        clearBhopFeedbackForOverlay();
        middleMouseHeld = false;
        gamepadGlideHeld = false;
        gamepadJumpHeld = false;
        gamepadMoveInput = 0;
        wheelSkillTapCount = 0;
        resetControlActionState();
        setGlideWindActive(false);
        updateDoubleJumpCooldownUi(true);
        if (ui.pauseScreen) ui.pauseScreen.style.display = 'flex';
        setPauseOverlay(title, subtitle);
        resetGamepadUiFocus(0);
        try {
            if (document.pointerLockElement) document.exitPointerLock();
        } catch (e) {}
        const platform = crazyGamesPlatform();
        if (platform) platform.gameplayStop();
        return true;
    }

    async function resumeRunFromGamepad() {
        if (isGameOver || rewardedAdBusy) return;
        if (pointerLockRecoveryPending) {
            // Controllers do not require pointer lock. The first confirmation
            // after a portal ad resumes directly and must not request a second ad.
            pointerLockRecoveryPending = false;
            pointerLockRecoveryReason = '';
            closePauseSettingsPanel();
            hideMainMenu();
            isGamePaused = false;
            if (ui.pauseScreen) ui.pauseScreen.style.display = 'none';
            updateDoubleJumpCooldownUi();
            const activePlatform = crazyGamesPlatform();
            if (activePlatform) activePlatform.gameplayStart();
            return;
        }
        await requestCommercialAd('resume_after_pause');
        if (isGameOver) return;
        if (!MOBILE_RUNTIME) {
            armPointerLockRecovery('commercial-break-finished', true);
            return;
        }
        closePauseSettingsPanel();
        hideMainMenu();
        isGamePaused = false;
        if (ui.pauseScreen) ui.pauseScreen.style.display = 'none';
        updateDoubleJumpCooldownUi();
        const platform = crazyGamesPlatform();
        if (platform) platform.gameplayStart();
        playUiConfirmSound();
    }

    function pauseRunFromGamepad() {
        if (!pauseRunForExternalInterruption(tr('tapToStart').toLocaleUpperCase(), tr('pauseHint'))) return;
        playUiConfirmSound();
    }

    function beginRunFromGamepad(resetRun = true) {
        if (resetRun) resetGame({ startPaused: false, skipImmediateRender: true });
        hideMainMenu();
        runStartedFromMenu = true;
        menuState.runCount += 1;
        saveMainMenuState();
        updateMainMenuStats();
        isGamePaused = false;
        const platform = crazyGamesPlatform();
        if (platform) platform.gameplayStart();
        if (ui.pauseScreen) ui.pauseScreen.style.display = 'none';
        stopMenuMusicNow();
        updateDoubleJumpCooldownUi();
        playUiConfirmSound();
    }

    function isGamepadVisibleElement(el) {
        if (!el || el.disabled) return false;
        const style = window.getComputedStyle(el);
        if (style.display === 'none' || style.visibility === 'hidden' || Number(style.opacity) <= 0.01) return false;
        const rect = el.getBoundingClientRect();
        return rect.width > 2 && rect.height > 2;
    }

    function getGamepadFocusableElements() {
        let elements = [];
        if (mainMenuVisible) {
            const activeDialog = ui.mainMenu ? ui.mainMenu.querySelector('.menu-dialog.is-open') : null;
            if (activeDialog) {
                elements = Array.from(activeDialog.querySelectorAll('button:not([disabled]), input[type="range"]'));
            } else {
                elements = [
                    ui.menuStartBtn,
                    ui.menuResumeBtn,
                    ui.menuHighscoreBtn,
                    ui.menuSettingsBtn,
                    ui.menuQuitBtn
                ];
            }
        } else if (isGamePaused && ui.pauseScreen && ui.pauseScreen.style.display !== 'none') {
            if (ui.pauseSettingsPanel && ui.pauseSettingsPanel.classList.contains('is-open')) {
                elements = Array.from(ui.pauseSettingsPanel.querySelectorAll('button:not([disabled]), input[type="range"]'));
            } else {
                elements = [ui.pauseContinueBtn, ui.pauseSettingsBtn, ui.pauseMenuBtn];
            }
        } else if (isGameOver && ui.gameOver && ui.gameOver.style.display !== 'none') {
            elements = Array.from(ui.gameOver.querySelectorAll('button:not([disabled])'));
        }
        return elements.filter(isGamepadVisibleElement);
    }

    function getGamepadFocusListKey(elements) {
        return elements.map((el, index) => el.id || el.dataset.settingsAction || el.textContent.trim().slice(0, 24) || index).join('|');
    }

    function clearGamepadUiFocus() {
        document.querySelectorAll('.is-gamepad-focus').forEach((el) => el.classList.remove('is-gamepad-focus'));
    }

    function resetGamepadUiFocus(index = 0) {
        gamepadUiFocusIndex = Math.max(0, index | 0);
        gamepadUiFocusKey = '';
        gamepadUiNavLatch = '';
        gamepadUiLastNavAt = 0;
        focusGamepadUiElement(gamepadUiFocusIndex, false);
    }

    function getPreferredGamepadFocusIndex() {
        const elements = getGamepadFocusableElements();
        const contentIndex = elements.findIndex((el) => {
            if (!el || !el.classList) return false;
            return !el.classList.contains('menu-dialog-close') && !el.classList.contains('settings-back-btn');
        });
        return contentIndex >= 0 ? contentIndex : 0;
    }

    function focusGamepadUiElement(index = gamepadUiFocusIndex, playSound = false) {
        const elements = getGamepadFocusableElements();
        clearGamepadUiFocus();
        if (!elements.length) {
            gamepadUiFocusIndex = 0;
            gamepadUiFocusKey = '';
            return null;
        }
        const key = getGamepadFocusListKey(elements);
        if (key !== gamepadUiFocusKey) {
            gamepadUiFocusKey = key;
            gamepadUiFocusIndex = Math.max(0, Math.min(gamepadUiFocusIndex, elements.length - 1));
        }
        gamepadUiFocusIndex = (index + elements.length) % elements.length;
        const target = elements[gamepadUiFocusIndex];
        target.classList.add('is-gamepad-focus');
        try { target.focus({ preventScroll: true }); } catch (e) { try { target.focus(); } catch (_) {} }
        try {
            target.scrollIntoView({ block: 'nearest', inline: 'nearest' });
        } catch (e) {}
        if (playSound) playUiHoverSound();
        return target;
    }

    function moveGamepadUiFocus(direction) {
        const elements = getGamepadFocusableElements();
        if (!elements.length) return false;
        const key = getGamepadFocusListKey(elements);
        if (key !== gamepadUiFocusKey) {
            gamepadUiFocusKey = key;
            gamepadUiFocusIndex = 0;
        } else {
            gamepadUiFocusIndex = (gamepadUiFocusIndex + direction + elements.length) % elements.length;
        }
        focusGamepadUiElement(gamepadUiFocusIndex, true);
        return true;
    }

    function clickGamepadUiFocus() {
        const target = focusGamepadUiElement(gamepadUiFocusIndex, false);
        if (!target) return false;
        unlockMenuMusicFromUserGesture();
        ensureMenuAudio();
        if (target === ui.menuStartBtn) {
            unlockGameplayAudioFromUserGesture();
            target.click();
            return true;
        }
        if (target === ui.menuResumeBtn || target === ui.pauseContinueBtn) {
            unlockGameplayAudioFromUserGesture();
            resumeRunFromGamepad();
            return true;
        }
        target.click();
        return true;
    }

    function closeGamepadUiLayer() {
        if (pendingControlBinding) return cancelPendingControlBinding();
        if (mainMenuVisible) {
            const dialogOpen = [ui.menuUpgradesDialog, ui.menuSettingsDialog]
                .some(el => el && el.classList.contains('is-open'));
            if (dialogOpen) {
                closeMenuDialogs();
                resetGamepadUiFocus(gamepadUiReturnFocusIndex);
                playUiConfirmSound();
                return true;
            }
            return false;
        }
        if (ui.pauseSettingsPanel && ui.pauseSettingsPanel.classList.contains('is-open')) {
            closePauseSettingsPanel();
            resetGamepadUiFocus(1);
            playUiConfirmSound();
            return true;
        }
        return false;
    }

    function readGamepadUiNavVector(pad) {
        const xAxis = normalizeGamepadAxis(readStrongestGamepadAxis(pad, [0, 6]));
        const yAxis = normalizeGamepadAxis(readStrongestGamepadAxis(pad, [1, 7]));
        const xButtons = (gamepadButtonDown(pad, 15) ? 1 : 0) - (gamepadButtonDown(pad, 14) ? 1 : 0);
        const yButtons = (gamepadButtonDown(pad, 13) ? 1 : 0) - (gamepadButtonDown(pad, 12) ? 1 : 0);
        return {
            x: xButtons || xAxis,
            y: yButtons || yAxis
        };
    }

    function adjustFocusedGamepadRange(range, direction) {
        if (!range || range.type !== 'range') return false;
        const min = Number(range.min);
        const max = Number(range.max);
        const step = Number(range.step) || 0.05;
        const current = Number(range.value);
        if (!Number.isFinite(min) || !Number.isFinite(max) || !Number.isFinite(current)) return false;
        const next = Math.max(min, Math.min(max, current + (direction * step)));
        if (Math.abs(next - current) < 0.0001) return true;
        range.value = next.toFixed(3).replace(/0+$/, '').replace(/\.$/, '');
        range.dispatchEvent(new Event('input', { bubbles: true }));
        playUiHoverSound();
        return true;
    }

    function handleGamepadUiNavigation(pad, buttonMap, confirmJustPressed, cancelJustPressed) {
        const elements = getGamepadFocusableElements();
        if (!elements.length) {
            clearGamepadUiFocus();
            return false;
        }
        focusGamepadUiElement(gamepadUiFocusIndex, false);
        if (cancelJustPressed) return closeGamepadUiLayer();
        if (confirmJustPressed) return clickGamepadUiFocus();

        const focused = elements[gamepadUiFocusIndex];
        const nav = readGamepadUiNavVector(pad);
        const xDir = Math.abs(nav.x) > 0.62 ? Math.sign(nav.x) : 0;
        const yDir = Math.abs(nav.y) > 0.55 ? Math.sign(nav.y) : 0;
        const now = performance.now();
        let actionKey = '';
        if (focused && focused.matches && focused.matches('input[type="range"]') && xDir !== 0) {
            actionKey = `range:${xDir}`;
        } else if (yDir !== 0) {
            actionKey = `nav:${yDir}`;
        } else if (xDir !== 0) {
            actionKey = `nav:${xDir}`;
        }
        if (!actionKey) {
            gamepadUiNavLatch = '';
            return false;
        }
        if (actionKey !== gamepadUiNavLatch || now - gamepadUiLastNavAt > GAMEPAD_UI_REPEAT_MS) {
            gamepadUiNavLatch = actionKey;
            gamepadUiLastNavAt = now;
            if (actionKey.startsWith('range:')) return adjustFocusedGamepadRange(focused, xDir);
            return moveGamepadUiFocus(yDir || xDir);
        }
        return false;
    }

    function applyGamepadLook(pad, delta) {
        if (mainMenuVisible || isGamePaused || isGameOver) return;
        const lookAxes = readGamepadLookAxes(pad);
        const lookX = lookAxes.x;
        const lookY = lookAxes.y;
        if (lookX === 0 && lookY === 0) return;
        lastCameraLookInputAt = performance.now();
        cameraAutoCenterActive = false;
        const sensitivityScale = clampNumber(menuState.mouseSensitivity, 0.45, 1.85, 1);
        const lookSpeed = 1.75 * sensitivityScale;
        yaw -= lookX * lookSpeed * delta;
        pitch += lookY * lookSpeed * 0.78 * delta * (menuState.invertY ? 1 : -1);
        const limitPitch = 75 * (Math.PI / 180);
        pitch = Math.max(-limitPitch, Math.min(limitPitch, pitch));
        const limitYaw = 80 * (Math.PI / 180);
        const centerYaw = CAMERA_CENTER_YAW;
        yaw = Math.max(centerYaw - limitYaw, Math.min(centerYaw + limitYaw, yaw));
    }

    function updateCameraAutoCenter(delta) {
        const nowMs = performance.now();
        if (mainMenuVisible || isGamePaused || isGameOver || tutorialDirector?.state === 'start-gate') {
            lastCameraLookInputAt = nowMs;
            cameraAutoCenterActive = false;
            return;
        }
        if (nowMs - lastCameraLookInputAt < CAMERA_AUTO_CENTER_DELAY_MS) {
            cameraAutoCenterActive = false;
            return;
        }
        const safeDelta = Math.max(0, Math.min(0.1, Number(delta) || 0));
        const yawBlend = 1 - Math.exp(-2.15 * safeDelta);
        const pitchBlend = 1 - Math.exp(-2.45 * safeDelta);
        const yawError = Math.atan2(Math.sin(CAMERA_CENTER_YAW - yaw), Math.cos(CAMERA_CENTER_YAW - yaw));
        yaw += yawError * yawBlend;
        pitch += (0 - pitch) * pitchBlend;
        if (Math.abs(yawError) < 0.0005) yaw = CAMERA_CENTER_YAW;
        if (Math.abs(pitch) < 0.0005) pitch = 0;
        cameraAutoCenterActive = true;
    }

    function pollGamepadInput(delta) {
        const pad = getPrimaryGamepad();
        if (!pad) {
            setControllerInputActive(false);
            resetGamepadRuntimeInput();
            updateGamepadButtonSnapshots(null);
            return;
        }

        setControllerInputActive(true);
        updateGamepadButtonSnapshots(pad);

        const buttonMap = gamepadButtonGroups(pad);
        const confirmJustPressed = anyGamepadButtonJustPressed(buttonMap.confirm);
        const cancelJustPressed = anyGamepadButtonJustPressed(buttonMap.cancel);
        const menuJustPressed = anyGamepadButtonJustPressed(buttonMap.menu);

        if (rewardedDeathPending) {
            if ((confirmJustPressed || menuJustPressed) && rewardedDeathOfferReady && !rewardedAdBusy) watchRewardedContinue();
            else if (cancelJustPressed && !rewardedAdBusy) declineRewardedContinue();
            resetGamepadRuntimeInput();
            return;
        }

        if (mainMenuVisible) {
            handleGamepadUiNavigation(pad, buttonMap, confirmJustPressed || menuJustPressed, cancelJustPressed);
            resetGamepadRuntimeInput();
            return;
        }

        if (isGameOver) {
            handleGamepadUiNavigation(pad, buttonMap, confirmJustPressed || menuJustPressed, cancelJustPressed);
            resetGamepadRuntimeInput();
            return;
        }

        if (isGamePaused) {
            if (handleGamepadUiNavigation(pad, buttonMap, confirmJustPressed, cancelJustPressed)) {
                resetGamepadRuntimeInput();
                return;
            }
            if (menuJustPressed) {
                resumeRunFromGamepad();
                return;
            }
            resetGamepadRuntimeInput();
            return;
        }

        if (menuJustPressed) {
            pauseRunFromGamepad();
            return;
        }

        const stickMove = readGamepadStrafeAxis(pad);
        const dpadAxisMove = normalizeGamepadAxis(readStrongestGamepadAxis(pad, [6]));
        const dpadMove = (gamepadButtonDown(pad, 15) ? 1 : 0) - (gamepadButtonDown(pad, 14) ? 1 : 0);
        const axisDpadMove = Math.abs(dpadAxisMove) > 0.01 ? Math.sign(dpadAxisMove) : 0;
        gamepadMoveInput = dpadMove !== 0 ? dpadMove : (axisDpadMove !== 0 ? axisDpadMove : stickMove);

        const previousJumpHeld = gamepadJumpHeld;
        gamepadJumpHeld = anyGamepadButtonDown(pad, buttonMap.jump) || gamepadAxisPressed(pad, [7], -1);
        if (!gamepadJumpHeld && previousJumpHeld && !CONTROL_ACTION_STATE.jump) {
            jumpKeyPressed = false;
            jumpQueue = false;
        }

        const jumpJustPressed = anyGamepadButtonJustPressed(buttonMap.jump) || gamepadAxisPressed(pad, [7], -1);
        if (!isGamePaused && jumpJustPressed && isJumping) {
            jumpQueue = true;
            jumpQueueTimer = 0.06;
            bhopAttemptFailed = false;
        }

        const doubleJumpJustPressed = anyGamepadButtonJustPressed(buttonMap.doubleJump);
        if (!isGamePaused && doubleJumpJustPressed && isJumping) tryUseDoubleJump();
        if (!isGamePaused && anyGamepadButtonJustPressed(buttonMap.skill)) triggerActiveHandSkill();

        const slideJustPressed = anyGamepadButtonJustPressed(buttonMap.slide) || gamepadAxisPressed(pad, [7], 1);
        if (!isGamePaused && slideJustPressed && !isSliding) startSlide();

        gamepadGlideHeld = !isGamePaused && (
            anyGamepadButtonDown(pad, buttonMap.glide) ||
            gamepadAxisPressed(pad, [4, 5], 0)
        );

        applyGamepadLook(pad, delta);
    }

    function loadMainMenuState() {
        let shouldSaveMenuState = false;
        try {
            const raw = localStorage.getItem(MAIN_MENU_STORAGE_KEY);
            if (raw) {
                const saved = JSON.parse(raw);
                if (isBrowserBuild()) {
                    const hasSeal = Number(saved.browserSaveIntegrityVersion) === BROWSER_SAVE_INTEGRITY_VERSION && typeof saved.browserSaveSeal === 'string';
                    if (hasSeal && !verifyBrowserSaveIntegrity(saved)) throw new Error('Browser save integrity check failed');
                    if (!hasSeal) shouldSaveMenuState = true;
                }
                const savedBestCoins = Math.max(0, Number(saved.bestCoins) || 0);
                let savedWalletCoins = Number.isFinite(Number(saved.walletCoins))
                    ? Math.max(0, Number(saved.walletCoins) || 0)
                    : savedBestCoins;
                const savedWalletGrantVersion = Math.max(0, Number(saved.walletGrantVersion) || 0);
                if (savedWalletGrantVersion < WALLET_GRANT_VERSION) {
                    savedWalletCoins = Math.max(savedWalletCoins, STARTING_WALLET_COINS) + WALLET_GRANT_BONUS;
                    shouldSaveMenuState = true;
                }
                const savedWalletResetVersion = Math.max(0, Number(saved.walletResetVersion) || 0);
                if (savedWalletResetVersion < WALLET_RESET_VERSION) {
                    savedWalletCoins = 0;
                    shouldSaveMenuState = true;
                }
                const savedUpgrades = saved.upgrades && typeof saved.upgrades === 'object' ? saved.upgrades : {};
                const savedGlideUnlocked = !!(savedUpgrades.glide ?? saved.glideUnlocked);
                const savedDoubleJumpUnlocked = !!(savedUpgrades.doubleJump ?? saved.doubleJumpUnlocked);
                const savedReviveUnlocked = !!(savedUpgrades.revive ?? saved.reviveUnlocked);
                const savedTimeSlowUnlocked = !!(savedUpgrades.timeSlow ?? saved.timeSlowUnlocked);
                const savedMagnetUnlocked = !!(savedUpgrades.magnet ?? saved.magnetUnlocked);
                const savedCrosshairDefaultVersion = Math.max(0, Number(saved.crosshairDefaultVersion) || 0);
                const migrateCrosshairDefault = isBrowserBuild() && savedCrosshairDefaultVersion < CROSSHAIR_DEFAULT_VERSION;
                if (migrateCrosshairDefault) shouldSaveMenuState = true;
                const savedOwnedHandSkins = Array.isArray(saved.ownedHandSkins)
                    ? [...new Set(saved.ownedHandSkins.filter((id) => !!HAND_SKIN_BY_ID[id]))]
                    : [];
                const savedSelectedHandSkin = saved.selectedHandSkin === 'default' || savedOwnedHandSkins.includes(saved.selectedHandSkin)
                    ? saved.selectedHandSkin
                    : 'default';
                const savedActiveSpecialAbility = getHandSkillForSkin(savedSelectedHandSkin);
                // Yalnızca tanımlı başarım id'lerini geri yükle: eski/silinmiş bir id kayıtta
                // kalırsa sayaç şişer ve "hepsi açık" kontrolleri yanlış sonuç verir.
                const savedAchievements = {};
                if (saved.achievements && typeof saved.achievements === 'object') {
                    ACHIEVEMENTS.forEach((a) => { if (saved.achievements[a.id]) savedAchievements[a.id] = true; });
                }
                menuState = {
                    ...menuState,
                    bestScore: Math.max(0, Number(saved.bestScore) || 0),
                    bestCoins: savedBestCoins,
                    walletCoins: savedWalletCoins,
                    runCount: Math.max(0, Number(saved.runCount) || 0),
                    firstRunRewindCompleted: saved.firstRunRewindCompleted === true,
                    tutorialVersion: Math.max(0, Math.min(TUTORIAL_VERSION, Math.floor(Number(saved.tutorialVersion) || 0))),
                    achievements: savedAchievements,
                    dailyMissions: normalizeDailyMissions(saved.dailyMissions),
                    dailyStreak: Math.max(0, Number(saved.dailyStreak) || 0),
                    dailyLastCompletedDay: typeof saved.dailyLastCompletedDay === 'string' ? saved.dailyLastCompletedDay : null,
                    rewardBoosts: {
                        scoreUntil: Math.max(0, Number(saved.rewardBoosts && saved.rewardBoosts.scoreUntil) || 0),
                        goldUntil: Math.max(0, Number(saved.rewardBoosts && saved.rewardBoosts.goldUntil) || 0)
                    },
                    adUpgradeOffers: normalizeAdUpgradeOffers(saved.adUpgradeOffers),
                    upgrades: {
                        scoreMultiplier: clampScoreUpgradeLevel(savedUpgrades.scoreMultiplier ?? saved.scoreUpgradeLevel),
                        coinMultiplier: clampCoinUpgradeLevel(savedUpgrades.coinMultiplier ?? saved.coinUpgradeLevel),
                        jumpHeight: clampJumpUpgradeLevel(savedUpgrades.jumpHeight ?? saved.jumpUpgradeLevel),
                        speed: clampSpeedUpgradeLevel(savedUpgrades.speed ?? saved.speedUpgradeLevel),
                        glide: savedGlideUnlocked,
                        doubleJump: savedDoubleJumpUnlocked,
                        revive: savedReviveUnlocked,
                        timeSlow: savedTimeSlowUnlocked,
                        magnet: savedMagnetUnlocked
                    },
                    rebirthLevel: clampRebirthLevel(saved.rebirthLevel),
                    activeSpecialAbility: savedActiveSpecialAbility,
                    muted: Number(saved.menuAudioVersion) === MENU_AUDIO_VERSION ? !!saved.muted : false,
                    compactHud: !!saved.compactHud,
                    ownedHandSkins: savedOwnedHandSkins,
                    selectedHandSkin: savedSelectedHandSkin,
                    // Version 2 moved this onboarding out of the main menu and
                    // into the Level 3 completion flow. Old menu-only completion
                    // flags must not suppress the redesigned tutorial.
                    handPurchaseTutorialSeen: saved.handPurchaseTutorialSeen === true
                        && Number(saved.handPurchaseTutorialVersion) === HAND_PURCHASE_TUTORIAL_VERSION,
                    handPurchaseTutorialVersion: Math.max(0, Math.floor(Number(saved.handPurchaseTutorialVersion) || 0)),
                    ...normalizeMenuSettings(saved),
                    crosshairEnabled: migrateCrosshairDefault ? false : saved.crosshairEnabled === true,
                    crosshairDefaultVersion: CROSSHAIR_DEFAULT_VERSION,
                    menuAudioVersion: MENU_AUDIO_VERSION,
                    walletGrantVersion: WALLET_GRANT_VERSION,
                    walletResetVersion: WALLET_RESET_VERSION
                };
            } else {
                menuState.language = detectInitialLanguage();
                menuState.languageSource = 'auto';
                shouldSaveMenuState = true;
            }
        } catch (err) {
            console.warn('Menu state could not be loaded:', err);
            shouldSaveMenuState = true;
        }
        if (shouldSaveMenuState) saveMainMenuState();
        applyMainMenuSettings();
        updateMainMenuStats();
        // Kayıt yüklendikten SONRA: çevrimdışıyken açılmış başarımları Steam'e yetiştir.
        syncAchievementsToSteam();
    }

    function saveMainMenuState() {
        try {
            if (isBrowserBuild()) {
                const payload = { ...menuState, browserSaveIntegrityVersion: BROWSER_SAVE_INTEGRITY_VERSION };
                payload.browserSaveSeal = computeBrowserSaveSeal(payload);
                localStorage.setItem(MAIN_MENU_STORAGE_KEY, JSON.stringify(payload));
            } else {
                localStorage.setItem(MAIN_MENU_STORAGE_KEY, JSON.stringify(menuState));
            }
        } catch (err) {
            console.warn('Menu state could not be saved:', err);
        }
    }

    async function requestCommercialAd(placement) {
        if (window.ELEMENTAL_POKI_BUILD !== true || rewardedAdBusy) return { status: 'skipped', provider: 'none' };
        const protectedEarlyAttempt = playerFitLevelAttemptOpen && playerFitCurrentLevel >= 1 && playerFitCurrentLevel <= 3;
        const commercialCooldownActive = playerFitActiveSeconds - playerFitLastCommercialAtSeconds < 150;
        if (playerFitActiveSeconds < 180 || protectedEarlyAttempt || commercialCooldownActive) {
            measurePlayerFit('ad-gate', playerFitSafePart(placement, 'commercial'), 'deferred');
            return { status: 'deferred', provider: 'poki' };
        }
        const ads = window.ElementalBrowserAds;
        if (!ads || typeof ads.showCommercial !== 'function') return { status: 'unavailable', provider: 'none' };
        rewardedAdBusy = true;
        updateMobileControlsVisibility();
        let adStarted = false;
        try {
            const result = await ads.showCommercial({
                placement,
                onStart: () => {
                    adStarted = true;
                    pauseAudioForRewardedAd();
                },
                onFinish: () => {
                    if (adStarted) resumeAudioAfterRewardedAd();
                }
            });
            if (adStarted) playerFitLastCommercialAtSeconds = playerFitActiveSeconds;
            return { ...(result || {}), adStarted };
        } finally {
            rewardedAdBusy = false;
            updateMobileControlsVisibility();
        }
    }

    async function refineAutoLanguageFromCountry() {
        if (!isBrowserBuild() || menuState.languageSource !== 'auto') return;
        const platform = crazyGamesPlatform();
        if (isCrazyGamesBuild()) {
            // CrazyGames provides platform locale/system information after SDK
            // initialization. Never delay the game with an external geo lookup.
            if (applyAutoLanguageFromCrazyGamesSystemInfo(platform && platform.getSystemInfo && platform.getSystemInfo())) return;
            if (platform && platform.ready) {
                platform.ready.then(() => applyAutoLanguageFromCrazyGamesSystemInfo(platform.getSystemInfo && platform.getSystemInfo()));
            }
            return;
        }
        const cacheKey = 'elementalRunCountryCodeV1';
        let countryCode = '';
        try { countryCode = sessionStorage.getItem(cacheKey) || ''; } catch (error) {}
        if (!countryCode) {
            const controller = new AbortController();
            const timeout = setTimeout(() => controller.abort(), 3500);
            try {
                const response = await fetch('https://api.country.is/', {
                    cache: 'no-store',
                    signal: controller.signal
                });
                if (!response.ok) return;
                const data = await response.json();
                if (!data) return;
                countryCode = String(data.country || '').toUpperCase();
                if (countryCode) {
                    try { sessionStorage.setItem(cacheKey, countryCode); } catch (error) {}
                }
            } catch (error) {
                return;
            } finally {
                clearTimeout(timeout);
            }
        }
        if (menuState.languageSource !== 'auto') return;
        const countryLanguage = languageFromCountryCode(countryCode);
        if (!countryLanguage || countryLanguage === menuState.language) return;
        menuState.language = countryLanguage;
        applyMainMenuSettings();
        updateMainMenuStats();
        saveMainMenuState();
    }

    function computeBrowserSaveSeal(value) {
        const copy = { ...(value || {}) };
        delete copy.browserSaveSeal;
        const text = `${JSON.stringify(copy)}|${BROWSER_SAVE_INTEGRITY_PEPPER}`;
        let hash = 0x811c9dc5;
        for (let i = 0; i < text.length; i++) {
            hash ^= text.charCodeAt(i);
            hash = Math.imul(hash, 0x01000193);
        }
        return `er${BROWSER_SAVE_INTEGRITY_VERSION}-${(hash >>> 0).toString(36).padStart(7, '0')}`;
    }

    function verifyBrowserSaveIntegrity(value) {
        return !!value && value.browserSaveSeal === computeBrowserSaveSeal(value);
    }

    function clampNumber(value, min, max, fallback) {
        const n = Number(value);
        if (!Number.isFinite(n)) return fallback;
        return Math.max(min, Math.min(max, n));
    }

    function getLanguageMeta(code) {
        return SUPPORTED_LANGUAGES.find((lang) => lang.code === code) || SUPPORTED_LANGUAGES.find((lang) => lang.code === 'en') || SUPPORTED_LANGUAGES[0];
    }

    function normalizeLanguage(code) {
        const exact = SUPPORTED_LANGUAGES.find((lang) => lang.code === code);
        return exact ? exact.code : (languageFromLocaleTag(code) || 'en');
    }

    function normalizeDisplayMode(mode) {
        return DISPLAY_MODES.includes(mode) ? mode : 'fullscreen';
    }

    function normalizeControlBindings(savedBindings = {}) {
        const normalized = { ...DEFAULT_CONTROL_BINDINGS };
        if (savedBindings && typeof savedBindings === 'object') {
            CONTROL_ACTION_ORDER.forEach((action) => {
                const value = savedBindings[action];
                if (typeof value === 'string' && value.trim().length > 0) normalized[action] = value.trim();
            });
        }
        return normalized;
    }

    function getControlBinding(action) {
        const bindings = menuState.controlBindings || DEFAULT_CONTROL_BINDINGS;
        return bindings[action] || DEFAULT_CONTROL_BINDINGS[action] || '';
    }

    function resetControlActionState() {
        CONTROL_ACTION_ORDER.forEach((action) => { CONTROL_ACTION_STATE[action] = false; });
    }

    function getActionsForControlCode(code) {
        if (!code) return [];
        const actions = CONTROL_ACTION_ORDER.filter((action) => getControlBinding(action) === code);
        // WASD and the arrow keys are permanent gameplay aliases. They work in
        // every run as well as in the tutorial and never overwrite custom binds.
        const ergonomicAlias = {
            KeyA: 'moveLeft', ArrowLeft: 'moveLeft',
            KeyD: 'moveRight', ArrowRight: 'moveRight',
            KeyW: 'jump', ArrowUp: 'jump',
            KeyS: 'slide', ArrowDown: 'slide'
        }[code];
        if (ergonomicAlias && !actions.includes(ergonomicAlias)) actions.push(ergonomicAlias);
        return actions;
    }

    function isBlockedControlBindingCode(code) {
        return !code || code === 'Escape' || code === 'F5' || code === 'F11' || code === 'F12';
    }

    function formatControlBinding(code) {
        if (!code) return '-';
        if (code === 'Space') return 'SPACE';
        if (code === 'MouseLeft') return 'MOUSE 1';
        if (code === 'MouseMiddle') return 'MOUSE 3';
        if (code === 'MouseRight') return 'MOUSE 2';
        if (code === 'WheelUp') return 'WHEEL UP';
        if (code === 'WheelDown') return 'WHEEL DOWN';
        if (/^Key[A-Z]$/.test(code)) return code.slice(3);
        if (/^Digit[0-9]$/.test(code)) return code.slice(5);
        if (code === 'ArrowLeft') return 'LEFT';
        if (code === 'ArrowRight') return 'RIGHT';
        if (code === 'ArrowUp') return 'UP';
        if (code === 'ArrowDown') return 'DOWN';
        return code
            .replace('Shift', 'SHIFT ')
            .replace('Control', 'CTRL ')
            .replace('Alt', 'ALT ')
            .replace('Left', 'LEFT')
            .replace('Right', 'RIGHT')
            .replace('Numpad', 'NUM ')
            .trim()
            .toLocaleUpperCase('en-US');
    }

    function getControlActionLabel(action) {
        if (action === 'moveLeft') return tr('moveLeft');
        if (action === 'moveRight') return tr('moveRight');
        if (action === 'jump') return tr('jump');
        if (action === 'slide') return tr('slide');
        if (action === 'glide') return tr('glide');
        if (action === 'doubleJump') return tr('doubleJump');
        if (action === 'timeSlow') return getActiveSpecialAbility() === 'magnet' ? magnetName() : timeSlowName();
        return action;
    }

    function tr(key) {
        const lang = normalizeLanguage(menuState.language);
        return (UI_TRANSLATIONS[lang] && UI_TRANSLATIONS[lang][key])
            || (UI_TRANSLATIONS.en && UI_TRANSLATIONS.en[key])
            || (UI_TRANSLATIONS.tr && UI_TRANSLATIONS.tr[key])
            || key;
    }

    function browserTr(key) {
        const lang = normalizeLanguage(menuState.language);
        return (BROWSER_TEXT[lang] && BROWSER_TEXT[lang][key])
            || (BROWSER_TEXT.en && BROWSER_TEXT.en[key])
            || key;
    }

    function normalizeMenuSettings(saved = {}) {
        const quality = GRAPHICS_QUALITY_PRESETS[saved.graphicsQuality] ? saved.graphicsQuality : 'high';
        return {
            graphicsQuality: quality,
            graphicsManualOverride: saved.graphicsManualOverride === true,
            displayMode: normalizeDisplayMode(saved.displayMode || 'fullscreen'),
            masterVolume: clampNumber(saved.masterVolume, 0, 1.35, 1.0),
            musicVolume: clampNumber(saved.musicVolume, 0, 1.0, 0.55),
            sfxVolume: clampNumber(saved.sfxVolume, 0, 1.4, 1.15),
            uiVolume: clampNumber(saved.uiVolume, 0, 1.6, 1.25),
            gameplayUiHidden: !!saved.gameplayUiHidden,
            crosshairEnabled: saved.crosshairEnabled === true,
            handsEnabled: saved.handsEnabled !== false,
            adaptiveGraphicsQuality: ADAPTIVE_QUALITY_ORDER.includes(saved.adaptiveGraphicsQuality)
                ? saved.adaptiveGraphicsQuality
                : 'performance',
            mouseSensitivity: clampNumber(saved.mouseSensitivity, 0.45, 1.85, 1.0),
            // Older profiles did not store this key and intentionally migrate
            // to the child-friendly default: camera mouse-look is off.
            mouseControlEnabled: saved.mouseControlEnabled === true,
            invertY: !!saved.invertY,
            language: normalizeLanguage(saved.language || 'en'),
            languageSource: saved.languageSource === 'manual' ? 'manual' : 'auto',
            subtitles: !!saved.subtitles,
            fullVoice: !!saved.fullVoice,
            interfaceLanguage: saved.interfaceLanguage !== false,
            controlBindings: normalizeControlBindings(saved.controlBindings),
            controlBindingVersion: CONTROL_BINDING_VERSION
        };
    }

    function getQualityPreset() {
        const qualityName = getEffectiveGraphicsQualityName();
        if (MOBILE_RUNTIME) return MOBILE_GRAPHICS_QUALITY_PRESETS[qualityName] || MOBILE_GRAPHICS_QUALITY_PRESETS.high;
        return GRAPHICS_QUALITY_PRESETS[qualityName] || GRAPHICS_QUALITY_PRESETS.balanced;
    }

    function getDesktopBridge() {
        return window.elementalRunDesktop || window.elementalRunShell || null;
    }

    function isSteamOverlayShortcut(event) {
        return !!event
            && event.key === 'Tab'
            && event.shiftKey
            && !event.ctrlKey
            && !event.altKey
            && !event.metaKey;
    }

    function requestSteamOverlayFromShortcut() {
        const bridge = getDesktopBridge();
        middleMouseHeld = false;
        gamepadGlideHeld = false;
        resetControlActionState();
        wheelSkillTapCount = 0;
        if (!mainMenuVisible && !isGameOver) {
            pauseRunForExternalInterruption(tr('pauseTitle'), tr('pauseHint'));
        }
        if (bridge && typeof bridge.openSteamOverlay === 'function') {
            bridge.openSteamOverlay().catch((err) => {
                console.warn('Steam overlay request failed:', err);
            });
        }
    }

    function applyDisplayMode(userGesture = false) {
        // CrazyGames owns fullscreen outside the iframe. The submission must not
        // make its own requestFullscreen()/exitFullscreen() calls.
        if (isCrazyGamesBuild() || isPokiBuild()) return;
        const mode = normalizeDisplayMode(menuState.displayMode);
        menuState.displayMode = mode;
        document.body.dataset.displayMode = mode;

        const desktopBridge = getDesktopBridge();
        if (desktopBridge && typeof desktopBridge.setDisplayMode === 'function') {
            desktopBridge.setDisplayMode(mode).catch(() => {});
            return;
        }

        if (!userGesture) return;
        if (mode === 'windowed') {
            if (document.fullscreenElement && document.exitFullscreen) document.exitFullscreen().catch(() => {});
        } else if (!document.fullscreenElement && document.documentElement.requestFullscreen) {
            document.documentElement.requestFullscreen().catch(() => {});
        }
    }

    // ===== Cinematic GFX module =====
    let gfxComposerActive = false;

    function gfxComputePixelRatio(preset) {
        return graphicsEngine.computePixelRatio(preset);
    }

    // Frame-time governor lives in graphics-engine.js. Runtime-only scene objects
    // are exposed through a narrow adapter so the global IIFE and load order stay intact.
    const graphicsModule = window.ElementalGraphicsEngine;
    if (!graphicsModule) throw new Error('graphics-engine.js must load before game-runtime.js');
    const graphicsEngine = graphicsModule.create({
        isBrowserBuild,
        isMobile: () => MOBILE_RUNTIME,
        isPaused: () => isGamePaused,
        isMainMenuVisible: () => mainMenuVisible,
        hasRunStarted: () => runStartedFromMenu,
        getSmoothedFps: () => smoothedFps,
        getRenderer: () => renderer,
        getQualityPreset,
        setQualityIndex: (index, reason) => setAdaptiveQualityIndex(index, reason),
        setPerformanceLevel: (level) => setAdaptivePerfLevel(level),
        resizePipeline: () => gfxResize(),
        getGraphicsContext: () => ({
            renderer, scene, dirLight, three: THREE,
            cinematicColor: GFX_CINEMATIC_COLOR, defaultExposure: GFX_DEFAULT_EXPOSURE,
            getRuntimeShadowMapSize, getRoadHalfWidth,
            invalidateShadowCommit: () => {
                shadowCommittedTargetX = Number.NaN;
                shadowCommittedTargetY = Number.NaN;
                shadowCommittedTargetZ = Number.NaN;
                shadowCommittedLightY = Number.NaN;
            },
            ensureEnvironment: gfxEnsureEnvironment, ensureComposer: gfxEnsureComposer,
            getBloomPass: () => gfxBloomPass, getAoPass: () => gfxAoPass, getFxaaPass: () => gfxFxaaPass,
            getDesatPass: () => gfxDesatPass, getComposer: () => gfxComposer,
            applyMaterialTier: applyAdaptivePbrMaterialTier,
            setBloomBase: (strength, threshold) => {
                gfxBaseBloomStrength = strength;
                gfxBaseBloomThreshold = threshold;
            },
            applyPhaseBloom: gfxApplyPhaseBloom,
            getPhase: () => (typeof gamePhase !== 'undefined' ? gamePhase : 0),
            resize: gfxResize, setComposerActive: (active) => { gfxComposerActive = active; }
        }),
        getShadowContext: () => ({
            renderer, player, adaptiveRenderDistance,
            resetPending: (cooldown) => {
                pendingShadowRefreshX = Number.POSITIVE_INFINITY;
                shadowRefreshCooldown = cooldown;
            },
            queuePending: (xPos) => { pendingShadowRefreshX = Math.min(pendingShadowRefreshX, xPos); }
        })
    }, {
        adaptiveEnabled: MOBILE_RUNTIME,
        graceSeconds: ADAPTIVE_GRAPHICS_GRACE_SECONDS,
        promoteFps: ADAPTIVE_GRAPHICS_PROMOTE_FPS,
        demoteFps: ADAPTIVE_GRAPHICS_DEMOTE_FPS
    });
    const graphicsState = graphicsEngine.state;
    function selectedQualityCeilingIndex() {
        const index = ADAPTIVE_QUALITY_ORDER.indexOf(menuState.graphicsQuality);
        return index >= 0 ? index : 2;
    }

    function getEffectiveGraphicsQualityName() {
        if (!isBrowserBuild()) return menuState.graphicsQuality;
        return ADAPTIVE_QUALITY_ORDER[Math.max(0, Math.min(ADAPTIVE_QUALITY_ORDER.length - 1, graphicsState.qualityIndex))] || 'performance';
    }

    function getGraphicsQualityLabel(quality) {
        if (quality === 'performance') return tr('performance');
        if (quality === 'balanced') return tr('balanced');
        if (quality === 'high') return tr('high');
        return tr('ultra');
    }

    function updateAdaptiveGraphicsStatusUi() {
        const quality = getEffectiveGraphicsQualityName();
        document.querySelectorAll('[data-adaptive-quality-current]').forEach((node) => {
            node.textContent = getGraphicsQualityLabel(quality).toLocaleUpperCase();
            node.dataset.value = quality;
        });
    }

    function detectAdaptiveHardwareProfile() {
        const profile = {
            cores: Math.max(0, Number(navigator.hardwareConcurrency) || 0),
            memoryGb: Math.max(0, Number(navigator.deviceMemory) || 0),
            devicePixelRatio: Math.max(1, Number(window.devicePixelRatio) || 1),
            gpu: 'unknown', score: 0, recommendedQuality: 'balanced'
        };
        if (profile.cores >= 12) profile.score += 3;
        else if (profile.cores >= 8) profile.score += 2;
        else if (profile.cores >= 6) profile.score += 1;
        else if (profile.cores > 0 && profile.cores <= 2) profile.score -= 3;
        else if (profile.cores > 0 && profile.cores <= 4) profile.score -= 1;
        if (profile.memoryGb >= 8) profile.score += 2;
        else if (profile.memoryGb >= 6) profile.score += 1;
        else if (profile.memoryGb > 0 && profile.memoryGb <= 2) profile.score -= 3;
        else if (profile.memoryGb > 0 && profile.memoryGb <= 4) profile.score -= 1;
        if (profile.devicePixelRatio > 2.5) profile.score -= 1;
        if (MOBILE_RUNTIME) profile.score -= 1;
        let gpuQualityCap = 3;
        try {
            const gl = renderer && renderer.getContext ? renderer.getContext() : null;
            const debugInfo = gl && gl.getExtension && gl.getExtension('WEBGL_debug_renderer_info');
            profile.gpu = String(debugInfo ? gl.getParameter(debugInfo.UNMASKED_RENDERER_WEBGL) : (gl && gl.getParameter ? gl.getParameter(gl.RENDERER) : 'unknown'));
            const gpu = profile.gpu.toLowerCase();
            if (/swiftshader|llvmpipe|software|microsoft basic render/.test(gpu)) {
                profile.score -= 4;
                gpuQualityCap = 0;
            }
            else if (/rtx|radeon rx|arc\(tm\)|apple m[2-9]|apple gpu/.test(gpu)) profile.score += 2;
            else if (/intel.*(hd 4|hd 5|uhd 6|uhd 7)|mali-t|adreno \(tm\) 5/.test(gpu)) {
                profile.score -= 2;
                gpuQualityCap = 1;
            }
            const maxTexture = renderer?.capabilities?.maxTextureSize || 0;
            if (maxTexture >= 8192) profile.score += 1;
            else if (maxTexture > 0 && maxTexture <= 4096) profile.score -= 1;
        } catch (error) {}
        const scoredIndex = profile.score >= 6 ? 3 : (profile.score >= 2 ? 2 : (profile.score >= 0 ? 1 : 0));
        const recommendedIndex = Math.min(scoredIndex, gpuQualityCap, MOBILE_LOW_END ? 1 : 3);
        profile.recommendedQuality = ADAPTIVE_QUALITY_ORDER[recommendedIndex];
        graphicsState.hardwareProfile = profile;
        graphicsState.qualityCeilingIndex = Math.min(selectedQualityCeilingIndex(), recommendedIndex);
        return profile;
    }

    function setAdaptiveQualityIndex(nextIndex, reason = 'fps') {
        if (graphicsState.qualityLocked) return false;
        if (!isBrowserBuild()) return false;
        const clamped = Math.max(0, Math.min(graphicsState.qualityCeilingIndex, Math.floor(nextIndex) || 0));
        if (clamped === graphicsState.qualityIndex) return false;
        graphicsState.qualityIndex = clamped;
        menuState.adaptiveGraphicsQuality = ADAPTIVE_QUALITY_ORDER[clamped] || 'performance';
        graphicsState.qualityReason = reason;
        graphicsState.qualityStableSeconds = 0;
        graphicsState.qualityLowSeconds = 0;
        graphicsState.qualityCriticalSeconds = 0;
        graphicsState.qualityCooldown = clamped > 0 ? 3.5 : 2;
        graphicsState.lastLevelChangeAt = graphicsState.runSeconds;
        applyGraphicsQuality();
        scheduleAdaptiveCyberSceneRefresh();
        requestShadowMapRefresh(null, true);
        saveMainMenuState();
        return true;
    }

    function openPauseMenuFromKeyboard() {
        if (mainMenuVisible || isGameOver || rewardedAdBusy || rewardedDeathPending || reviveSequenceActive) return false;
        pointerLockRecoveryPending = false;
        pointerLockRecoveryReason = 'menu-key';
        if (pauseRunForExternalInterruption(tr('pauseTitle').toLocaleUpperCase(), tr('pauseHint'))) {
            playUiConfirmSound();
            return true;
        }
        if (!isGamePaused) return false;
        if (ui.pauseScreen) ui.pauseScreen.style.display = 'flex';
        setPauseOverlay(tr('pauseTitle').toLocaleUpperCase(), tr('pauseHint'));
        resetGamepadUiFocus(0);
        try {
            if (document.pointerLockElement) document.exitPointerLock();
        } catch (error) {}
        const platform = crazyGamesPlatform();
        if (platform) platform.gameplayStop();
        return true;
    }

    function resetAdaptiveGraphicsForRun() {
        if (!isBrowserBuild()) return;
        // Keep the named quality ladder fixed. Mobile adapts only its internal
        // render scale and scene budget, so High remains the visible default.
        // Desktop retains its hardware safety fallback on first launch.
        graphicsState.qualityLocked = false;
        graphicsState.adaptiveEnabled = MOBILE_RUNTIME;
        const selectedIndex = ADAPTIVE_QUALITY_ORDER.indexOf(menuState.graphicsQuality);
        const fallbackIndex = ADAPTIVE_QUALITY_ORDER.indexOf('high');
        const requestedIndex = selectedIndex >= 0 ? selectedIndex : fallbackIndex;
        const recommendedIndex = ADAPTIVE_QUALITY_ORDER.indexOf(
            graphicsState.hardwareProfile && graphicsState.hardwareProfile.recommendedQuality
        );
        const hardwareSafetyRequired = !MOBILE_RUNTIME && !menuState.graphicsManualOverride
            && (MOBILE_LOW_END || RUNTIME_LOW_POWER || (recommendedIndex >= 0 && recommendedIndex <= requestedIndex));
        graphicsState.qualityIndex = hardwareSafetyRequired ? recommendedIndex : requestedIndex;
        if (graphicsState.qualityIndex < 0) graphicsState.qualityIndex = ADAPTIVE_QUALITY_ORDER.indexOf('performance');
        graphicsState.qualityCeilingIndex = graphicsState.qualityIndex;
        menuState.adaptiveGraphicsQuality = ADAPTIVE_QUALITY_ORDER[graphicsState.qualityIndex];
        if (hardwareSafetyRequired) menuState.graphicsQuality = menuState.adaptiveGraphicsQuality;
        graphicsState.qualityStableSeconds = 0;
        graphicsState.qualityLowSeconds = 0;
        graphicsState.qualityCriticalSeconds = 0;
        graphicsState.qualityCooldown = ADAPTIVE_GRAPHICS_GRACE_SECONDS;
        graphicsState.qualityReason = hardwareSafetyRequired ? 'hardware-safety' : 'manual-selection';
        updateAdaptiveGraphicsStatusUi();
    }

    function updateAdaptiveQualityTier(sampleDelta, rawFrameDelta) {
        graphicsEngine.updateAdaptiveQualityTier(sampleDelta, rawFrameDelta);
    }

    function setAdaptivePerfLevel(nextLevel) {
        if (graphicsState.qualityLocked) return;
        const level = Math.max(0, Math.min(2, Math.floor(nextLevel) || 0));
        if (level === graphicsState.performanceLevel) return;
        graphicsState.performanceLevel = level;
        graphicsState.recoverySeconds = 0;
        graphicsState.lastLevelChangeAt = graphicsState.runSeconds;
        applyGraphicsQuality();
        if (timeSlowActive && !gfxComposerActive && !timeSlowGrayMats) collectTimeSlowGrayTargets();
    }

    function getRuntimeRenderDistanceTarget(preset = getQualityPreset()) {
        const base = preset.renderDistance;
        if (MOBILE_RUNTIME) {
            const mobileFloor = MOBILE_LOW_END ? 280 : 320;
            const scale = graphicsState.performanceLevel === 2 ? 0.62 : (graphicsState.performanceLevel === 1 ? 0.78 : 1);
            return Math.max(mobileFloor, Math.min(base, base * scale));
        }
        const quality = getEffectiveGraphicsQualityName();
        const floor = quality === 'performance' ? 400 : (quality === 'balanced' ? 500 : 560);
        const scale = graphicsState.performanceLevel === 2 ? 0.58 : (graphicsState.performanceLevel === 1 ? 0.76 : 1);
        return Math.max(floor, Math.min(base, base * scale));
    }

    function updateDynamicResolution(rawFrameDelta) {
        graphicsEngine.updateDynamicResolution(rawFrameDelta);
    }

    function lockGraphicsToHighForCampaign() {
        if (!isBrowserBuild()) return false;
        // Kept as a compatibility hook for existing Level 2 routing. It no
        // longer locks the UI: manual settings remain authoritative.
        const selectedIndex = ADAPTIVE_QUALITY_ORDER.indexOf(menuState.graphicsQuality);
        const activeIndex = selectedIndex >= 0 ? selectedIndex : ADAPTIVE_QUALITY_ORDER.indexOf('high');
        graphicsState.qualityLocked = false;
        graphicsState.adaptiveEnabled = MOBILE_RUNTIME;
        graphicsState.qualityIndex = activeIndex;
        graphicsState.qualityCeilingIndex = activeIndex;
        menuState.adaptiveGraphicsQuality = ADAPTIVE_QUALITY_ORDER[activeIndex];
        // A Level 2 transition must not erase the mobile perf budget learned
        // during tutorial; doing so recreates a burst of slow frames.
        if (!MOBILE_RUNTIME) {
            graphicsState.performanceLevel = 0;
            graphicsState.dynamicResolutionScale = 1;
        }
        graphicsState.qualityStableSeconds = 0;
        graphicsState.qualityLowSeconds = 0;
        graphicsState.qualityCriticalSeconds = 0;
        graphicsState.lowFpsSeconds = 0;
        graphicsState.criticalFpsSeconds = 0;
        graphicsState.recoverySeconds = 0;
        graphicsState.qualityReason = 'manual-selection';
        applyGraphicsQuality();
        saveMainMenuState();
        return true;
    }

    function gfxMakeEnvScene(top, bottom, sun) {
        const s = new THREE.Scene();
        const geo = new THREE.SphereGeometry(60, 32, 16);
        const mat = new THREE.ShaderMaterial({
            side: THREE.BackSide, depthWrite: false,
            uniforms: { top: { value: new THREE.Color(top) }, bottom: { value: new THREE.Color(bottom) }, sun: { value: new THREE.Color(sun) } },
            vertexShader: 'varying vec3 vd; void main(){ vd = normalize(position); gl_Position = projectionMatrix * modelViewMatrix * vec4(position,1.0); }',
            fragmentShader: 'varying vec3 vd; uniform vec3 top; uniform vec3 bottom; uniform vec3 sun; void main(){ float h = clamp(vd.y*0.5+0.5,0.0,1.0); vec3 c = mix(bottom, top, pow(h,0.85)); float s = clamp(dot(normalize(vd), normalize(vec3(0.4,0.7,0.3))),0.0,1.0); c += sun * pow(s, 6.0) * 0.7; gl_FragColor = vec4(c,1.0); }'
        });
        s.add(new THREE.Mesh(geo, mat));
        return s;
    }

    function setGfxEnvMood(key, top, bottom, sun) {
        if (!renderer || !scene || typeof THREE.PMREMGenerator !== 'function') return;
        const cached = gfxEnvCache.get(key);
        if (cached) {
            gfxEnvRT = cached;
            gfxEnvMoodKey = key;
            scene.environment = cached.texture;
            return;
        }
        if (!gfxPmrem) { gfxPmrem = new THREE.PMREMGenerator(renderer); gfxPmrem.compileEquirectangularShader(); }
        const envScene = gfxMakeEnvScene(top, bottom, sun);
        const rt = gfxPmrem.fromScene(envScene, 0.04, 0.1, 200);
        gfxEnvCache.set(key, rt);
        gfxEnvRT = rt;
        scene.environment = rt.texture;
        gfxEnvMoodKey = key;
        envScene.traverse((o) => { if (o.geometry) o.geometry.dispose(); if (o.material) o.material.dispose(); });
    }

    function gfxEnsureEnvironmentForPhase(phase = 0) {
        const p = Math.max(0, Math.min(5, Math.floor(Number(phase) || 0)));
        if (p === 1) setGfxEnvMood('nature', 0x91c9db, 0x24351f, 0xffe0a4);
        else if (p === 2) setGfxEnvMood('sky', 0xddecff, 0x596f91, 0xffffff);
        else if (p === 3) setGfxEnvMood('lava', 0x421008, 0x100201, 0xff6b20);
        else if (p === 4) setGfxEnvMood('water', 0x5d9fa6, 0x06191c, 0xffd071);
        else if (p >= 5) setGfxEnvMood('snow', 0x5d769e, 0x111b35, 0xeaf6ff);
        else setGfxEnvMood('city', 0x2a2350, 0x05030f, 0x7a5cff);
    }

    function gfxEnsureEnvironment() {
        gfxEnsureEnvironmentForPhase(typeof gamePhase !== 'undefined' ? gamePhase : 0);
    }

    function gfxEnsureComposer() {
        if (gfxComposer || !renderer || !scene || !camera) return gfxComposer;
        if (typeof THREE.EffectComposer !== 'function' || typeof THREE.UnrealBloomPass !== 'function') return null;
        const initialSize = new THREE.Vector2();
        renderer.getSize(initialSize);
        const composerTarget = new THREE.WebGLRenderTarget(initialSize.x, initialSize.y, {
            type: THREE.HalfFloatType,
            depthBuffer: true,
            stencilBuffer: false
        });
        // The contact-AO pass samples the depth generated by the normal curved
        // world render. It therefore follows the exact visible bend without a
        // second override-material scene pass whose silhouettes could detach.
        composerTarget.depthTexture = new THREE.DepthTexture(initialSize.x, initialSize.y, THREE.UnsignedIntType);
        composerTarget.depthTexture.format = THREE.DepthFormat;
        composerTarget.depthTexture.name = 'ELEMENTAL RUN Curved Scene Depth';
        // WebGLMultisampleRenderTarget was removed after r152. Modern Three.js
        // exposes the same WebGL2 MSAA path through WebGLRenderTarget.samples.
        // Keep low-power devices on FXAA to avoid doubling transient bandwidth.
        const maxSamples = Number(renderer.capabilities?.maxSamples) || 0;
        composerTarget.samples = !window.ElementalPixelArt?.enabled && renderer.capabilities?.isWebGL2 && !RUNTIME_LOW_POWER
            ? Math.min(4, maxSamples)
            : 0;
        composerTarget.texture.name = 'ELEMENTAL RUN Composer r185.1';
        gfxComposer = new THREE.EffectComposer(renderer, composerTarget);
        // EffectComposer captures the renderer DPR in its constructor. Avoid an
        // immediate setPixelRatio()+setSize() pair, which disposed and recreated
        // both full-screen targets twice on modern Three.js.
        gfxComposerPixelRatio = renderer.getPixelRatio();
        gfxComposerWidth = 0;
        gfxComposerHeight = 0;
        gfxRenderPass = new THREE.RenderPass(scene, camera);
        gfxComposer.addPass(gfxRenderPass);
        const sz = new THREE.Vector2(); renderer.getSize(sz);
        if (typeof THREE.ShaderPass === 'function') {
            const contactAoShader = {
                uniforms: {
                    tDiffuse: { value: null },
                    tDepth: { value: composerTarget.depthTexture },
                    uResolution: { value: new THREE.Vector2(Math.max(1, sz.x), Math.max(1, sz.y)) },
                    uCameraNear: { value: camera.near },
                    uCameraFar: { value: camera.far },
                    uIntensity: { value: 0.16 },
                    uRadius: { value: 1.25 }
                },
                vertexShader: 'varying vec2 vUv; void main(){ vUv=uv; gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.0); }',
                fragmentShader: [
                    'uniform sampler2D tDiffuse;',
                    'uniform sampler2D tDepth;',
                    'uniform vec2 uResolution;',
                    'uniform float uCameraNear;',
                    'uniform float uCameraFar;',
                    'uniform float uIntensity;',
                    'uniform float uRadius;',
                    'varying vec2 vUv;',
                    'float viewDistance(float depth){',
                    '  float z=depth*2.0-1.0;',
                    '  return (2.0*uCameraNear*uCameraFar)/max(0.0001,uCameraFar+uCameraNear-z*(uCameraFar-uCameraNear));',
                    '}',
                    'void main(){',
                    '  vec4 base=texture2D(tDiffuse,vUv);',
                    '  float raw=texture2D(tDepth,vUv).x;',
                    '  if(raw>=0.99999 || uIntensity<=0.0001){ gl_FragColor=base; return; }',
                    '  float center=viewDistance(raw);',
                    '  vec2 px=(uRadius/max(uResolution,vec2(1.0)));',
                    '  float occ=0.0;',
                    '  vec2 d0=vec2(px.x,0.0), d1=vec2(0.0,px.y);',
                    '  vec2 d2=px*0.70710678, d3=vec2(px.x,-px.y)*0.70710678;',
                    '  float s0=viewDistance(texture2D(tDepth,clamp(vUv+d0,vec2(0.0),vec2(1.0))).x);',
                    '  float s1=viewDistance(texture2D(tDepth,clamp(vUv-d0,vec2(0.0),vec2(1.0))).x);',
                    '  float s2=viewDistance(texture2D(tDepth,clamp(vUv+d1,vec2(0.0),vec2(1.0))).x);',
                    '  float s3=viewDistance(texture2D(tDepth,clamp(vUv-d1,vec2(0.0),vec2(1.0))).x);',
                    '  float s4=viewDistance(texture2D(tDepth,clamp(vUv+d2,vec2(0.0),vec2(1.0))).x);',
                    '  float s5=viewDistance(texture2D(tDepth,clamp(vUv-d2,vec2(0.0),vec2(1.0))).x);',
                    '  float s6=viewDistance(texture2D(tDepth,clamp(vUv+d3,vec2(0.0),vec2(1.0))).x);',
                    '  float s7=viewDistance(texture2D(tDepth,clamp(vUv-d3,vec2(0.0),vec2(1.0))).x);',
                    '  occ+=smoothstep(0.0015,0.035,(center-s0)/max(center,1.0));',
                    '  occ+=smoothstep(0.0015,0.035,(center-s1)/max(center,1.0));',
                    '  occ+=smoothstep(0.0015,0.035,(center-s2)/max(center,1.0));',
                    '  occ+=smoothstep(0.0015,0.035,(center-s3)/max(center,1.0));',
                    '  occ+=smoothstep(0.0015,0.035,(center-s4)/max(center,1.0));',
                    '  occ+=smoothstep(0.0015,0.035,(center-s5)/max(center,1.0));',
                    '  occ+=smoothstep(0.0015,0.035,(center-s6)/max(center,1.0));',
                    '  occ+=smoothstep(0.0015,0.035,(center-s7)/max(center,1.0));',
                    '  float shade=1.0-(occ*0.125*uIntensity);',
                    '  gl_FragColor=vec4(base.rgb*shade,base.a);',
                    '}'
                ].join('\n')
            };
            gfxAoPass = new THREE.ShaderPass(contactAoShader);
            gfxAoPass.enabled = false;
            const aoRender = gfxAoPass.render.bind(gfxAoPass);
            gfxAoPass.render = function elementalContactAoRender(webglRenderer, writeBuffer, readBuffer, deltaTime, maskActive) {
                const uniforms = this.material.uniforms;
                uniforms.tDepth.value = readBuffer.depthTexture || composerTarget.depthTexture;
                uniforms.uCameraNear.value = camera.near;
                uniforms.uCameraFar.value = camera.far;
                return aoRender(webglRenderer, writeBuffer, readBuffer, deltaTime, maskActive);
            };
            gfxComposer.addPass(gfxAoPass);
        }
        gfxBloomPass = new THREE.UnrealBloomPass(new THREE.Vector2(sz.x, sz.y), 0.12, 0.34, 0.93);
        gfxComposer.addPass(gfxBloomPass);
        if (composerTarget.samples === 0 && typeof THREE.ShaderPass === 'function' && THREE.FXAAShader) {
            gfxFxaaPass = new THREE.ShaderPass(THREE.FXAAShader);
            gfxComposer.addPass(gfxFxaaPass);
        }
        // Zaman-yavaşlatma seçici desaturasyon pass'i (son pass → ekrana basılır).
        // Tüm kareyi grileştirir ama SAF kırmızı/yeşil/mavi tonları korur (uAmount=0 iken kimlik).
        if (typeof THREE.ShaderPass === 'function') {
            const desatShader = {
                uniforms: { tDiffuse: { value: null }, uAmount: { value: 0.0 } },
                vertexShader: 'varying vec2 vUv; void main(){ vUv = uv; gl_Position = projectionMatrix * modelViewMatrix * vec4(position,1.0); }',
                fragmentShader: [
                    'uniform sampler2D tDiffuse;',
                    'uniform float uAmount;',
                    'varying vec2 vUv;',
                    'void main(){',
                    '  vec4 c = texture2D(tDiffuse, vUv);',
                    '  vec3 col = c.rgb;',
                    '  float luma = dot(col, vec3(0.299, 0.587, 0.114));',
                    // YALNIZCA KIRMIZI korunur: kırmızı baskın + yeşil/mavi düşük olmalı.',
                    '  float keep = (1.0 - smoothstep(0.18, 0.42, col.g)) * (1.0 - smoothstep(0.18, 0.42, col.b)) * smoothstep(0.30, 0.55, col.r);',
                    '  float d = uAmount * (1.0 - keep);',
                    '  gl_FragColor = vec4(mix(col, vec3(luma), d), c.a);',
                    '}'
                ].join('\n')
            };
            gfxDesatPass = new THREE.ShaderPass(desatShader);
            gfxDesatPass.enabled = false;
            gfxComposer.addPass(gfxDesatPass);
        }
        // ShaderPass materials intentionally stay in the linear working space.
        // OutputPass performs tone mapping and the final Linear-sRGB -> sRGB
        // conversion exactly once at the end of the post-processing chain.
        if (!window.ElementalPixelArt?.enabled && typeof THREE.OutputPass === 'function') {
            gfxOutputPass = new THREE.OutputPass();
            gfxComposer.addPass(gfxOutputPass);
        }
        gfxResize();
        // r185 can allocate framebuffer storage explicitly. Prime both composer
        // targets behind the loading/menu surface instead of on the first bloom
        // frame, where allocation would otherwise show up as a frame spike.
        if (typeof renderer.initRenderTarget === 'function') {
            renderer.initRenderTarget(gfxComposer.renderTarget1);
            renderer.initRenderTarget(gfxComposer.renderTarget2);
            r185OptimizationStats.renderTargetsPrimed += 2;
        }
        return gfxComposer;
    }

    function gfxResize() {
        if (!gfxComposer || !renderer) return;
        r185OptimizationStats.composerResizeRequests += 1;
        const sz = new THREE.Vector2(); renderer.getSize(sz);
        const dpr = renderer.getPixelRatio();
        const width = Math.max(1, Math.round(sz.x));
        const height = Math.max(1, Math.round(sz.y));
        const ratioChanged = Math.abs(dpr - gfxComposerPixelRatio) > 0.0001;
        const sizeChanged = width !== gfxComposerWidth || height !== gfxComposerHeight;
        if (!ratioChanged && !sizeChanged) {
            r185OptimizationStats.composerResizeNoops += 1;
            return;
        }
        // setPixelRatio() already resizes with the composer's remembered logical
        // dimensions. Only call setSize() as well when the viewport itself also
        // changed. EffectComposer propagates the final size to bloom/other passes.
        if (ratioChanged) gfxComposer.setPixelRatio(dpr);
        if (sizeChanged) gfxComposer.setSize(width, height);
        gfxComposerPixelRatio = dpr;
        gfxComposerWidth = width;
        gfxComposerHeight = height;
        r185OptimizationStats.composerResizeChanges += 1;
        if (gfxFxaaPass && gfxFxaaPass.material && gfxFxaaPass.material.uniforms['resolution']) {
            gfxFxaaPass.material.uniforms['resolution'].value.set(1 / (width * dpr), 1 / (height * dpr));
        }
        if (gfxAoPass?.material?.uniforms?.uResolution) {
            gfxAoPass.material.uniforms.uResolution.value.set(width * dpr, height * dpr);
        }
    }

    function gfxMarkColorMap(tex) {
        if (tex && tex.isTexture && THREE.SRGBColorSpace && tex.colorSpace !== THREE.SRGBColorSpace) {
            tex.colorSpace = THREE.SRGBColorSpace; tex.needsUpdate = true; return true;
        }
        return false;
    }

    function gfxFixMaterialColorSpace(mat) {
        if (!mat) return;
        let changed = false;
        if (gfxMarkColorMap(mat.map)) changed = true;
        if (gfxMarkColorMap(mat.emissiveMap)) changed = true;
        if (changed) mat.needsUpdate = true;
    }

    function gfxFixColorSpace(root) {
        const r = root || scene;
        if (!r || !r.traverse) return;
        r.traverse((o) => {
            if (!o.material) return;
            if (Array.isArray(o.material)) o.material.forEach(gfxFixMaterialColorSpace);
            else gfxFixMaterialColorSpace(o.material);
        });
        gfxColorReady = true;
    }

    function configureAdaptivePbrMaterial(material, preset = getQualityPreset(), performanceLevel = graphicsState.performanceLevel) {
        if (!material?.userData?.elementalPbrRole) return;
        const detailed = !!preset?.pbrDetail && performanceLevel === 0;
        const data = material.userData;
        if (!Object.prototype.hasOwnProperty.call(data, 'elementalBaseNormalMap')) {
            data.elementalBaseNormalMap = material.normalMap || null;
            data.elementalBaseRoughnessMap = material.roughnessMap || null;
            data.elementalBaseMetalnessMap = material.metalnessMap || null;
            data.elementalBaseEnvIntensity = Number(material.envMapIntensity) || 0;
        }
        const nextNormal = detailed ? data.elementalBaseNormalMap : null;
        const nextRough = detailed ? data.elementalBaseRoughnessMap : null;
        const nextMetal = detailed ? data.elementalBaseMetalnessMap : null;
        const changed = material.normalMap !== nextNormal
            || material.roughnessMap !== nextRough
            || material.metalnessMap !== nextMetal;
        material.normalMap = nextNormal;
        material.roughnessMap = nextRough;
        material.metalnessMap = nextMetal;
        material.envMapIntensity = detailed ? data.elementalBaseEnvIntensity : 0.04;
        if (changed) material.needsUpdate = true;
    }

    function applyAdaptivePbrMaterialTier(preset, performanceLevel = 0) {
        const detailed = !!preset?.pbrDetail && performanceLevel === 0;
        if (mats.road) {
            const nextNormal = detailed ? roadNormalTexScroll : null;
            const nextRough = detailed ? roadRoughTexScroll : null;
            const changed = mats.road.normalMap !== nextNormal || mats.road.roughnessMap !== nextRough;
            mats.road.normalMap = nextNormal;
            mats.road.roughnessMap = nextRough;
            mats.road.envMapIntensity = detailed ? 0.16 : 0.03;
            if (changed) mats.road.needsUpdate = true;
        }
        if (mats.roadLane) {
            const nextNormal = detailed ? roadNormalTexLane : null;
            const nextRough = detailed ? roadRoughTexLane : null;
            const changed = mats.roadLane.normalMap !== nextNormal || mats.roadLane.roughnessMap !== nextRough;
            mats.roadLane.normalMap = nextNormal;
            mats.roadLane.roughnessMap = nextRough;
            mats.roadLane.envMapIntensity = detailed ? 0.16 : 0.03;
            if (changed) mats.roadLane.needsUpdate = true;
        }
        const visited = new Set();
        const apply = (material) => {
            if (!material || visited.has(material)) return;
            visited.add(material);
            configureAdaptivePbrMaterial(material, preset, performanceLevel);
        };
        spawnPoolMats.forEach(apply);
        scene?.traverse?.((object) => {
            if (!object.material) return;
            if (Array.isArray(object.material)) object.material.forEach(apply);
            else apply(object.material);
        });
    }

    function shouldRenderDynamicShadows(preset = getQualityPreset()) {
        return !!preset.shadows
            && (typeof gamePhase === 'undefined' || gamePhase === 0);
    }

    function shouldContinuouslyUpdateDynamicShadows(preset = getQualityPreset()) {
        if (!shouldRenderDynamicShadows(preset)) return false;
        // Keep one scheduler on every browser/device. The previous desktop-only
        // autoUpdate path rebuilt the complete 2K shadow atlas every frame,
        // including while the tutorial's four cars were approaching. Besides
        // the large frame-time spike, pooled casters entering/leaving that atlas
        // could appear as a one-frame dark patch. Explicit refresh requests and
        // the moving-caster cadence below keep the texture and caster set stable.
        return false;
    }

    function getRuntimeShadowMapSize(preset = getQualityPreset()) {
        const requested = Math.max(512, Number(preset.shadowMapSize) || 1024);
        const maxTexture = renderer?.capabilities?.maxTextureSize || 4096;
        let cap = 2048;
        if (RUNTIME_LOW_POWER) cap = 1024;
        else if (MOBILE_RUNTIME && getEffectiveGraphicsQualityName() !== 'ultra') cap = 1024;
        return Math.max(512, Math.min(requested, cap, maxTexture));
    }

    function applyGfxQuality(preset) {
        graphicsEngine.applyQuality(preset);
    }

    // Per-phase bloom safety: bright/white phases (snow, water) use a higher
    // threshold and lower strength so the post bloom never washes the scene out.
    function gfxApplyPhaseBloom(phase) {
        if (!gfxBloomPass) return;
        let sMul = 1.0, tAdd = 0.0;
        if (phase === 0) { sMul = 0.42; tAdd = 0.065; } // cyber: keep neon readable without turning the whole city into glare
        else if (phase === 2) { sMul = 0.30; tAdd = 0.12; }  // sky: very gentle so the bright daytime sky isn't washed out (close to low-graphics + a touch of sun glow)
        else if (phase === 3) { sMul = 0.85; tAdd = 0.04; } // lava (bright orange)
        else if (phase === 4) { sMul = 0.70; tAdd = 0.06; } // water
        else if (phase >= 5) { sMul = 0.45; tAdd = 0.12; }  // snow (near-white)
        gfxBloomPass.strength = gfxBaseBloomStrength * sMul;
        gfxBloomPass.threshold = Math.min(0.98, gfxBaseBloomThreshold + tAdd);
        if (getQualityPreset()?.envMap && graphicsState.performanceLevel === 0) {
            gfxEnsureEnvironmentForPhase(phase);
        }
        gfxLastBloomPhase = phase;
    }

    function applyGraphicsQuality() {
        const preset = getQualityPreset();
        adaptiveRenderDistance = getRuntimeRenderDistanceTarget(preset);
        document.body.dataset.graphicsQuality = getEffectiveGraphicsQualityName();
        document.body.dataset.graphicsQualityTarget = menuState.graphicsQuality;
        updateAdaptiveGraphicsStatusUi();
        if (renderer) {
            const dpr = gfxComputePixelRatio(preset);
            if (typeof renderer.setPixelRatio === 'function') renderer.setPixelRatio(dpr);
            if (renderer.shadowMap) {
                const shadowsEnabled = shouldRenderDynamicShadows(preset);
                renderer.shadowMap.enabled = shadowsEnabled;
                renderer.shadowMap.autoUpdate = shouldContinuouslyUpdateDynamicShadows(preset);
                renderer.shadowMap.needsUpdate = true;
            }
            applyGfxQuality(preset);
        }
        if (dirLight) {
            dirLight.castShadow = shouldRenderDynamicShadows(preset);
        }
        applyDisplayMode(false);
    }

    function applyAudioSettings() {
        const audio = ensureElementalAudioSystem();
        if (!audio) return;
        audio.applySettings();
        syncLegacyAudioNodes();
    }

    function syncHtmlAudioWithSettings(forceGameplayPlay = false) {
        ensureElementalAudioSystem()?.syncHtmlAudioWithSettings(forceGameplayPlay);
    }

    function setText(node, value) {
        if (node) node.innerText = value;
    }

    function setTextBySelector(selector, value, root = document) {
        const node = root.querySelector(selector);
        if (node) node.innerText = value;
    }

