    function handSkinCardMarkup(skin, owned, selected, canBuy, loading = false) {
        const costText = skin.cost > 0 ? skin.cost.toLocaleString('tr-TR') : '0';
        const action = loading ? tr('loading') : (selected ? tr('selected') : (owned ? tr('select') : `${tr('buy')} · ${costText}`));
        const status = loading ? tr('loading') : (selected ? tr('active') : (owned ? tr('owned') : (canBuy ? tr('ready') : tr('notEnoughGold'))));
        const particleDots = '<i></i>'.repeat(skin.id === 'elemental' ? 8 : 5);
        const skill = HAND_SKILL_META[skin.skill] || { icon: '—', name: 'NO SKILL' };
        return `<article class="menu-hand-card${owned ? ' is-owned' : ' is-locked'}${selected ? ' is-selected' : ''}${canBuy ? ' is-affordable' : ''}${loading ? ' is-loading' : ''}" data-hand-id="${skin.id}" style="--hand-base:${skin.base};--hand-accent:${skin.accent};--hand-edge:${skin.edge}">
            <div class="menu-hand-art${skin.preview && handShopPreviewActive ? ' has-preview' : ''}" aria-hidden="true">
                <span class="menu-hand-aura"></span>
                ${handSkinPreviewMarkup(skin)}
                <span class="menu-hand-particles">${particleDots}</span>
            </div>
            <div class="menu-hand-info"><strong>${skin.name}</strong><span>${status}</span></div>
            <div class="menu-hand-skill"><span aria-hidden="true">${skill.icon}</span><strong>${skin.skill ? tr('handSkill_' + skin.skill) : '—'}</strong></div>
            <button class="menu-hand-action" type="button" data-hand-action="${skin.id}"${selected || loading ? ' disabled' : ''}>${action}</button>
        </article>`;
    }

    let handShopScrollRestoreToken = 0;

    function captureHandShopScrollState() {
        const pane = ui.menuHandsPane;
        const pageScroller = document.scrollingElement || document.documentElement;
        if (!pane || pane.hidden || !pane.isConnected) return null;
        return {
            pane,
            paneScrollTop: pane.scrollTop,
            pageScroller,
            pageScrollLeft: pageScroller?.scrollLeft || 0,
            pageScrollTop: pageScroller?.scrollTop || 0
        };
    }

    function restoreHandShopScrollState(state) {
        if (!state || !state.pane?.isConnected) return;
        const token = ++handShopScrollRestoreToken;
        const restore = () => {
            if (token !== handShopScrollRestoreToken || !state.pane.isConnected) return;
            state.pane.scrollTop = Math.min(state.paneScrollTop, Math.max(0, state.pane.scrollHeight - state.pane.clientHeight));
            if (state.pageScroller?.isConnected) {
                state.pageScroller.scrollLeft = state.pageScrollLeft;
                state.pageScroller.scrollTop = state.pageScrollTop;
            }
        };
        // Restore once immediately and once after layout/image state has settled.
        // The second pass prevents browser scroll anchoring from moving the shop
        // when the focused action button is replaced by the selected state.
        restore();
        requestAnimationFrame(restore);
    }

    function updateHandShopUi(force = false) {
        if (!ui.menuHandsGrid) return;
        const owned = getOwnedHandSkinIds();
        const selectedId = menuState.selectedHandSkin === 'default' || owned.includes(menuState.selectedHandSkin)
            ? menuState.selectedHandSkin
            : 'default';
        menuState.selectedHandSkin = selectedId;
        if (ui.menuHandsWallet) ui.menuHandsWallet.innerText = Math.floor(menuState.walletCoins || 0).toLocaleString('tr-TR');
        ui.menuHandsPane?.setAttribute('aria-busy', String(viewmodelGlbRequested && viewmodelGlbRequestedSkinId === selectedId));
        if (!force && ui.menuHandsPane?.hidden && ui.menuHandsGrid.childElementCount > 0) return;
        const defaultSkin = {
            id: 'default', name: 'STONE HANDS', cost: 0, skill: null,
            base: '#615f58', accent: '#8d897d', edge: '#d7d0bc',
            preview: `assets/hands/previews/hand_default.webp?v=${HAND_PREVIEW_VERSION}`
        };
        const scrollState = captureHandShopScrollState();
        const wallet = Math.floor(menuState.walletCoins || 0);
        ui.menuHandsGrid.innerHTML = [defaultSkin, ...HAND_SKINS].map((skin) => {
            const isOwned = skin.id === 'default' || owned.includes(skin.id);
            const loading = selectedId === skin.id && viewmodelGlbRequested && viewmodelGlbRequestedSkinId === selectedId;
            return handSkinCardMarkup(skin, isOwned, selectedId === skin.id, !isOwned && wallet >= skin.cost, loading);
        }).join('');
        restoreHandShopScrollState(scrollState);
    }

    function buyOrEquipHandSkin(id, sourceButton = null) {
        if (id !== 'default' && !HAND_SKIN_BY_ID[id]) return;
        const owned = getOwnedHandSkinIds();
        const skin = HAND_SKIN_BY_ID[id];
        if (id !== 'default' && !owned.includes(id)) {
            if ((Math.floor(menuState.walletCoins) || 0) < skin.cost) {
                playUiErrorSound();
                updateHandShopUi(true);
                return;
            }
            spendWalletCoins(skin.cost, sourceButton);
            owned.push(id);
            menuState.ownedHandSkins = owned;
            measurePlayerFit('hand-skin', id, 'purchased');
        }
        menuState.selectedHandSkin = id;
        menuState.activeSpecialAbility = getHandSkillForSkin(id);
        menuState.handsEnabled = true;
        measurePlayerFit('hand-skin', id, 'equipped');
        saveMainMenuState();
        applySelectedHandSkin();
        updateHandShopUi(true);
        updateMainMenuStats();
        playUiConfirmSound();
        if (handPurchaseTutorial.active || handPurchaseTutorial.pending) {
            abortHandPurchaseTutorial(getOwnedHandSkinIds().length > 0);
        }
    }

    function setUpgradeButtonUnavailable(buttonEl, unavailable) {
        if (!buttonEl) return;
        buttonEl.disabled = false;
        buttonEl.tabIndex = 0;
        buttonEl.setAttribute('aria-disabled', unavailable ? 'true' : 'false');
        buttonEl.classList.toggle('is-disabled', !!unavailable);
    }

    function updateMultiplierUpgradeCard(config) {
        const { level, maxLevel, multiplierText, nextCost, levelEl, multiplierEl, costEl, statusEl, buttonEl, steps } = config;
        const walletCoins = Math.max(0, Math.floor(menuState.walletCoins) || 0);
        const isMax = level >= maxLevel;
        const canAfford = !isMax && walletCoins >= nextCost;
        const goldLabel = tr('gold').toLocaleUpperCase();
        if (levelEl) levelEl.innerText = `${level}/${maxLevel}`;
        if (multiplierEl) multiplierEl.innerText = multiplierText;
        if (costEl) costEl.innerText = isMax ? tr('maxLevel') : `${nextCost.toLocaleString(menuNumberLocale())} ${goldLabel}`;
        if (statusEl) {
            statusEl.innerText = isMax
                ? tr('maxLevel')
                : (canAfford ? tr('ready') : tr('notEnoughGold'));
        }
        if (buttonEl) {
            setUpgradeButtonUnavailable(buttonEl, isMax || !canAfford);
            buttonEl.innerText = isMax ? tr('maxLevel') : `${nextCost.toLocaleString(menuNumberLocale())} ${goldLabel}`;
        }
        (steps || []).forEach((step, index) => {
            step.classList.toggle('is-filled', index < level);
            step.classList.toggle('is-next', !isMax && index === level);
        });
    }

