    const REWARDED_UPGRADE_KEYS = ['scoreMultiplier', 'coinMultiplier', 'jumpHeight', 'speed'];

    function normalizeAdUpgradeOffers(saved) {
        if (!saved || typeof saved !== 'object' || saved.day !== getTodayKey()) return null;
        const offers = Array.isArray(saved.offers) ? saved.offers.filter((key, index, list) => REWARDED_UPGRADE_KEYS.includes(key) && list.indexOf(key) === index).slice(0, 2) : [];
        const claimed = Array.isArray(saved.claimed) ? saved.claimed.filter((key, index, list) => offers.includes(key) && list.indexOf(key) === index) : [];
        // An empty list is still a valid daily state when every eligible
        // upgrade is already at its maximum. Keeping it avoids regenerating
        // and re-saving the same empty offer set on every menu refresh.
        return { day: saved.day, offers, claimed };
    }

    function isRewardedUpgradeEligible(key) {
        if (key === 'scoreMultiplier') return getScoreUpgradeLevel() < SCORE_UPGRADE_MAX_LEVEL;
        if (key === 'coinMultiplier') return getCoinUpgradeLevel() < COIN_UPGRADE_MAX_LEVEL;
        if (key === 'jumpHeight') return getJumpUpgradeLevel() < JUMP_UPGRADE_MAX_LEVEL;
        if (key === 'speed') return getSpeedUpgradeLevel() < SPEED_UPGRADE_MAX_LEVEL;
        if (key === 'glide') return !hasGlideUpgrade();
        if (key === 'doubleJump') return !hasDoubleJumpUpgrade();
        if (key === 'revive') return !hasReviveUpgrade();
        if (key === 'timeSlow') return !hasTimeSlowUpgrade();
        if (key === 'magnet') return !hasMagnetUpgrade();
        return false;
    }

    function ensureAdUpgradeOffers() {
        if (!areRewardedAdsEnabled()) return null;
        const normalized = normalizeAdUpgradeOffers(menuState.adUpgradeOffers);
        if (normalized) {
            menuState.adUpgradeOffers = normalized;
            return normalized;
        }
        const day = getTodayKey();
        const random = mulberry32(dailyHash(`${day}:browser-upgrades`));
        const pool = REWARDED_UPGRADE_KEYS.filter(isRewardedUpgradeEligible);
        for (let i = pool.length - 1; i > 0; i--) {
            const j = Math.floor(random() * (i + 1));
            const temp = pool[i]; pool[i] = pool[j]; pool[j] = temp;
        }
        const desired = REWARDED_UPGRADE_MIN + Math.floor(random() * (REWARDED_UPGRADE_MAX - REWARDED_UPGRADE_MIN + 1));
        menuState.adUpgradeOffers = { day, offers: pool.slice(0, Math.min(desired, pool.length)), claimed: [] };
        saveMainMenuState();
        return menuState.adUpgradeOffers;
    }

    function rewardedUpgradeAnchor(key) {
        if (key === 'scoreMultiplier') return ui.scoreUpgradeBtn;
        if (key === 'coinMultiplier') return ui.coinUpgradeBtn;
        if (key === 'jumpHeight') return ui.jumpUpgradeBtn;
        if (key === 'speed') return ui.speedUpgradeBtn;
        if (key === 'glide') return ui.glideUpgradeBtn;
        if (key === 'doubleJump') return ui.doubleJumpUpgradeBtn;
        if (key === 'revive') return ui.reviveUpgradeBtn;
        if (key === 'timeSlow') return ui.timeSlowUpgradeBtn;
        if (key === 'magnet') return ui.magnetUpgradeBtn;
        return null;
    }

    function getOrCreateRewardedUpgradeButton(key) {
        const anchor = rewardedUpgradeAnchor(key);
        if (!anchor || !anchor.parentElement) return null;
        let button = anchor.parentElement.querySelector(`.menu-upgrade-ad[data-ad-upgrade="${key}"]`);
        if (button) return button;
        button = document.createElement('button');
        button.type = 'button';
        button.className = 'menu-upgrade-ad';
        button.dataset.adUpgrade = key;
        const icon = document.createElement('span');
        icon.className = 'menu-upgrade-ad-icon';
        icon.setAttribute('aria-hidden', 'true');
        icon.innerHTML = '<svg viewBox="0 0 30 20"><rect x="1.5" y="1.5" width="27" height="17" rx="4"/><path d="m12 6 7 4-7 4V6Z"/></svg>';
        const label = document.createElement('span');
        label.className = 'menu-upgrade-ad-label';
        button.append(icon, label);
        button.addEventListener('click', (event) => {
            event.stopPropagation();
            watchRewardedUpgrade(key);
        });
        anchor.insertAdjacentElement('afterend', button);
        return button;
    }

    function updateRewardedUpgradeOfferButtons() {
        if (!areRewardedAdsEnabled()) {
            document.querySelectorAll('.menu-upgrade-ad').forEach((button) => { button.hidden = true; });
            return;
        }
        const state = ensureAdUpgradeOffers();
        REWARDED_UPGRADE_KEYS.forEach((key) => {
            const button = getOrCreateRewardedUpgradeButton(key);
            if (!button) return;
            const visible = !!state && state.offers.includes(key) && !state.claimed.includes(key) && isRewardedUpgradeEligible(key);
            button.hidden = !visible;
            button.disabled = rewardedAdBusy;
            const label = button.querySelector('.menu-upgrade-ad-label');
            if (label) label.textContent = browserTr('watchUpgrade');
            button.setAttribute('aria-label', browserTr('watchUpgrade'));
        });
    }

    function grantRewardedUpgrade(key) {
        const upgrades = { ...(menuState.upgrades || {}) };
        if (key === 'scoreMultiplier') upgrades.scoreMultiplier = Math.min(SCORE_UPGRADE_MAX_LEVEL, getScoreUpgradeLevel() + 1);
        else if (key === 'coinMultiplier') upgrades.coinMultiplier = Math.min(COIN_UPGRADE_MAX_LEVEL, getCoinUpgradeLevel() + 1);
        else if (key === 'jumpHeight') upgrades.jumpHeight = Math.min(JUMP_UPGRADE_MAX_LEVEL, getJumpUpgradeLevel() + 1);
        else if (key === 'speed') upgrades.speed = Math.min(SPEED_UPGRADE_MAX_LEVEL, getSpeedUpgradeLevel() + 1);
        else if (key === 'glide') upgrades.glide = true;
        else if (key === 'doubleJump') upgrades.doubleJump = true;
        else if (key === 'revive') upgrades.revive = true;
        else if (key === 'timeSlow') upgrades.timeSlow = true;
        else if (key === 'magnet') upgrades.magnet = true;
        else return false;
        menuState.upgrades = upgrades;
        if (key === 'revive' && runStartedFromMenu && !isGameOver) reviveAvailable = true;
        return true;
    }

    async function watchRewardedUpgrade(key) {
        if (!areRewardedAdsEnabled() || rewardedAdBusy || !isRewardedUpgradeEligible(key)) return;
        const state = ensureAdUpgradeOffers();
        if (!state || !state.offers.includes(key) || state.claimed.includes(key)) return;
        const result = await requestRewardedAd(`upgrade_${key}`);
        if (!result || result.status !== 'completed') {
            showBrowserToast(browserTr('adUnavailable'), true);
            return;
        }
        if (!grantRewardedUpgrade(key)) return;
        state.claimed.push(key);
        menuState.adUpgradeOffers = state;
        saveMainMenuState();
        updateMainMenuStats();
        evaluateShopAchievements();
        playUiConfirmSound();
        showBrowserToast(browserTr('upgradeGranted'));
    }

