        updateGlideUpgradeCard();
        updateDoubleJumpUpgradeCard();
        updateReviveUpgradeCard();
        updateRebirthUpgradeCard();
        updateTimeSlowUpgradeCard();
        updateMagnetUpgradeCard();
        updateRewardedUpgradeOfferButtons();
        updateSimpleUpgradePresentation();
