    function buyMultiplierUpgrade(upgradeKey, getLevel, getCost, maxLevel) {
        const level = getLevel();
        if (level >= maxLevel) {
            playUiErrorSound();
            return;
        }
        const cost = getCost();
        if ((Math.floor(menuState.walletCoins) || 0) < cost) {
            playUiErrorSound();
            updateUpgradeCards();
            return;
        }
        const sourceButton = {
            scoreMultiplier: ui.scoreUpgradeBtn,
            coinMultiplier: ui.coinUpgradeBtn,
            jumpHeight: ui.jumpUpgradeBtn,
            speed: ui.speedUpgradeBtn
        }[upgradeKey] || null;
        spendWalletCoins(cost, sourceButton);
        menuState.upgrades = {
            ...(menuState.upgrades || {}),
            [upgradeKey]: level + 1
        };
        measurePlayerFit('upgrade', upgradeKey, 'purchased');
        saveMainMenuState();
        updateMainMenuStats();
        playUiConfirmSound();
    }

