    function buyMagnetUpgrade() {
        if (hasMagnetUpgrade()) {
            if (!setActiveSpecialAbility('magnet')) playUiErrorSound();
            return;
        }
        if ((Math.floor(menuState.walletCoins) || 0) < MAGNET_UPGRADE_COST) {
            playUiErrorSound();
            updateUpgradeCards();
            return;
        }
        spendWalletCoins(MAGNET_UPGRADE_COST, ui.magnetUpgradeBtn);
        menuState.upgrades = {
            ...(menuState.upgrades || {}),
            magnet: true
        };
        menuState.activeSpecialAbility = 'magnet';
        measurePlayerFit('upgrade', 'magnet', 'purchased');
        saveMainMenuState();
        updateMainMenuStats();
        playUiConfirmSound();
    }

    // Rebirth yıkıcı: ilk tık onayı silahlandırır, ikinci tık uygular.
    // closeMenuDialogs() bayrağı düşürür — diyalog kapanıp açılınca silahlı kalmasın.
    function buyRebirthUpgrade() {
        const tier = getNextRebirthTier();
        if (!tier || (Math.floor(menuState.walletCoins) || 0) < tier.cost) {
            rebirthConfirmArmed = false;
            playUiErrorSound();
            updateUpgradeCards();
            return;
        }
        if (!rebirthConfirmArmed) {
            rebirthConfirmArmed = true;
            updateUpgradeCards();
            playUiHoverSound();
            return;
        }
        performRebirth();
    }

    function performRebirth() {
        const rebirthCost = getNextRebirthTier()?.cost || Math.max(0, Math.floor(menuState.walletCoins) || 0);
        rebirthConfirmArmed = false;
        // Koşu sırasında da rebirth yapılabilir: canlı yetenek state'ini kapat,
        // yoksa sıfırlanmış bir yetenek aktif kalmaya devam eder.
        forceEndTimeSlow();
        forceEndMagnet();
        reviveAvailable = false;
        menuState.rebirthLevel = getRebirthLevel() + 1;
        spendWalletCoins(rebirthCost, ui.rebirthUpgradeBtn);
        menuState.walletCoins = 0;
        menuState.bestScore = 0;
        menuState.bestCoins = 0;
        menuState.upgrades = {
            scoreMultiplier: 0,
            coinMultiplier: 0,
            jumpHeight: 0,
            speed: 0,
            glide: false,
            doubleJump: false,
            revive: false,
            timeSlow: false,
            magnet: false
        };
        menuState.activeSpecialAbility = null;
        // Başarımlar, koşu sayısı ve günlük görevler kasten korunur (Steam'e senkron kalıcı kayıtlar).
        saveMainMenuState();
        updateMainMenuStats();
        playUiConfirmSound();
    }


    function updateMouseControlUi() {
        const button = ui.menuMouseControlBtn;
        if (!button) return;
        const enabled = menuState.mouseControlEnabled === true;
        button.classList.toggle('is-on', enabled);
        button.setAttribute('aria-pressed', String(enabled));
        button.setAttribute('aria-label', enabled ? tr('mouseControlOn') : tr('mouseControlOff'));
        const state = button.querySelector('.mouse-control-state');
        if (state) state.textContent = enabled ? 'ON' : 'OFF';
        const label = button.closest('.mouse-control-menu-slot')?.querySelector('.mouse-control-menu-label');
        if (label) label.textContent = tr('mouseControl').toLocaleUpperCase();
    }

    function applyMainMenuSettings() {
        Object.assign(menuState, normalizeMenuSettings(menuState));
        document.body.classList.toggle('hud-compact', !!menuState.compactHud);
        document.body.classList.toggle('gameplay-ui-hidden', !!menuState.gameplayUiHidden);
        document.body.classList.toggle('crosshair-hidden', MOBILE_RUNTIME || !menuState.crosshairEnabled);
        document.body.classList.toggle('mouse-control-enabled', !!menuState.mouseControlEnabled);
        if (!menuState.mouseControlEnabled) {
            yaw = CAMERA_CENTER_YAW;
            pitch = 0;
            cameraAutoCenterActive = true;
        }
        updateMouseControlUi();
        applyGraphicsQuality();
        applyAudioSettings();
        applyLanguageTexts();
        setMenuAmbientActive(mainMenuVisible && !menuState.muted);
    }

    function closeMenuDialogs() {
        if (document.body.classList.contains('hub-panel-open')) {
            document.body.classList.remove('hub-panel-open');
            if (!mainMenuVisible && ui.mainMenu) ui.mainMenu.style.display = 'none';
        }
        pendingControlBinding = null;
        rebirthConfirmArmed = false;
        handShopPreviewActive = false;
        if (ui.menuDialogLayer) {
            ui.menuDialogLayer.classList.remove('is-open');
            ui.menuDialogLayer.setAttribute('aria-hidden', 'true');
        }
        // Elle yazılan liste yerine tüm .menu-dialog'lar: yeni bir dialog eklenip buraya
        // eklenmeyi unutunca eskisiyle üst üste açık kalıyordu (daily+leaderboard'da oldu).
        document.querySelectorAll('.menu-dialog').forEach((dialog) => {
            dialog.classList.remove('is-open');
            dialog.setAttribute('aria-hidden', 'true');
        });
        gamepadUiFocusKey = '';
        clearGamepadUiFocus();
    }

    function openMenuDialog(dialog) {
        if (!dialog || !ui.menuDialogLayer) return;
        gamepadUiReturnFocusIndex = gamepadUiFocusIndex;
        closeMenuDialogs();
        if (dialog === ui.menuSettingsDialog) {
            SETTINGS_PAGES.menu = 'home';
            renderSettingsPanel('menu');
        }
        if (dialog === ui.menuUpgradesDialog) setUpgradeShopTab('upgrades');
        ui.menuDialogLayer.classList.add('is-open');
        ui.menuDialogLayer.setAttribute('aria-hidden', 'false');
        dialog.classList.add('is-open');
        dialog.setAttribute('aria-hidden', 'false');
        resetGamepadUiFocus(getPreferredGamepadFocusIndex());
    }

    function requestGameQuit() {
        const desktopBridge = getDesktopBridge();
        stopGameplayMusicNow();
        stopMenuMusicNow();
        setMenuAmbientActive(false);
        if (desktopBridge && typeof desktopBridge.quit === 'function') {
            desktopBridge.quit().catch(() => {});
            return;
        }
        try {
            window.close();
        } catch (e) {}
    }

    // Koşu-içi başarım izleme. gamePhase 0=City (rozeti yok) → 5=Snow.
    const PHASE_ACHIEVEMENT_IDS = [null, 'phaseNature', 'phaseSky', 'phaseLava', 'phaseWater', 'phaseSnow'];
    // Yalnızca 100k: 5k–60k eşikleri faz rozetleriyle birebir aynı anda açılıyordu.
    const SCORE_ACHIEVEMENT_STEPS = [
        [100000, 'score100k']
    ];
    let runPhasesSeen = {};
    let achievementCheckTimer = 0;

    function resetRunAchievementTracking() {
        runPhasesSeen = {};
        achievementCheckTimer = 0;
    }

    // stepGame'den her karede çağrılır ama tarama saniyede ~4'e kısılır: 34 başarımı
    // 60fps'te yoklamak boşuna CPU. Faz kaydı kare başına (ucuz, kaçırılmamalı).
    function updateAchievementTracking(realDelta) {
        if (!runStartedFromMenu || isGameOver || mainMenuVisible) return;
        runPhasesSeen[gamePhase] = true;
        achievementCheckTimer -= realDelta;
        if (achievementCheckTimer > 0) return;
        achievementCheckTimer = 0.25;

        const phaseAch = PHASE_ACHIEVEMENT_IDS[gamePhase];
        if (phaseAch) unlockAchievement(phaseAch);
        if (runPhasesSeen[0] && runPhasesSeen[1] && runPhasesSeen[2]
            && runPhasesSeen[3] && runPhasesSeen[4] && runPhasesSeen[5]) unlockAchievement('allPhases');

        const kmh = moveSpeed * 180;
        if (kmh >= maxMoveSpeed * 180 - 0.5) unlockAchievement('speedMax');

        const liveScore = Math.floor(score);
        SCORE_ACHIEVEMENT_STEPS.forEach(([need, id]) => { if (liveScore >= need) unlockAchievement(id); });

        const liveCoins = Math.floor(totalCoins);
        if (liveCoins >= 500) unlockAchievement('coins500Run');
        if (bhopCombo >= 10) unlockAchievement('bhop10');

        // Günlük görevlerin 'max' modlu tipleri: tepe değeri ilet (mükerrer sayım yok,
        // Math.max ile birikiyor). Coin/koşu gibi 'sum' tipleri kendi olay yerlerinden gelir.
        if (liveScore > dailyRunPeakScore) { dailyRunPeakScore = liveScore; noteDailyMissionEvent('reachScore', liveScore); }
        if (gamePhase > dailyRunPeakPhase) { dailyRunPeakPhase = gamePhase; noteDailyMissionEvent('reachPhase', gamePhase); }
        if (kmh > dailyRunPeakSpeed) { dailyRunPeakSpeed = kmh; noteDailyMissionEvent('speedKmh', Math.floor(kmh)); }
    }

    // Mağaza durumuna bağlı başarımlar: satın alma sonrası ve menü açılışında çağrılır.
    function evaluateShopAchievements() {
        const u = menuState.upgrades || {};
        if (u.glide && u.doubleJump && u.timeSlow && u.magnet && u.revive) unlockAchievement('allAbilities');
        if (getOwnedHandSkinIds().length >= 4) unlockAchievement('handCollector');
        const levels = [
            [u.scoreMultiplier, SCORE_UPGRADE_MAX_LEVEL],
            [u.coinMultiplier, COIN_UPGRADE_MAX_LEVEL],
            [u.jumpHeight, JUMP_UPGRADE_MAX_LEVEL],
            [u.speed, SPEED_UPGRADE_MAX_LEVEL]
        ];
        if (levels.every(([lvl, max]) => (Number(lvl) || 0) >= max)) unlockAchievement('allMax');
    }

    function getDisplayedRunScore() {
        if (levelSystem && typeof levelSystem.snapshot === 'function') {
            const levelState = levelSystem.snapshot(score);
            if (levelState && (levelState.active || levelState.completed || levelState.tutorialPending)) {
                return Math.max(0, Math.floor(levelState.progressScore || 0));
            }
        }
        return Math.floor(score);
    }

    function recordMainMenuRunStats() {
        const finalScore = getDisplayedRunScore();
        const finalCoins = Math.floor(totalCoins);
        if (finalScore > menuState.bestScore) menuState.bestScore = finalScore;
        if (finalCoins > menuState.bestCoins) menuState.bestCoins = finalCoins;
        menuState.walletCoins = Math.max(0, Math.floor(menuState.walletCoins) || 0) + finalCoins;
        // runCount burada ARTIRILMAZ — koşu başlangıcında (beginRunFromMainMenu /
        // beginRunFromGamepad) zaten artıyor; buraya eklemek çift sayar.
        saveMainMenuState();

        unlockAchievement('firstRun');
        if (menuState.runCount >= 100) unlockAchievement('runs100');
        noteDailyMissionEvent('playRuns', 1);
        submitScoreToLeaderboard(finalScore);
        const platform = crazyGamesPlatform();
        if (platform) {
            platform.reportCompletion(Math.min(100, Math.floor(Math.max(menuState.bestScore, finalScore) / 5000 * 100)));
        }

        updateMainMenuStats();
    }

    function updateMenuAudioUnlockPrompt() {
        // No visible prompt: blocked menu music is unlocked by the next menu click.
    }

    async function compileSceneForR185(root, activeCamera, label = 'scene') {
        if (!renderer || !root || !activeCamera) return false;
        const startedAt = performance.now();
        if (window.ElementalLoadingMinigame?.getState?.().active) {
            // During the loading card we own the GPU exclusively. Synchronous
            // compile has a bounded completion on drivers whose async shader
            // extension never reports completion; the flight is gated meanwhile.
            try {
                renderer.compile(root, activeCamera);
                r185OptimizationStats.compileWaitMs += performance.now() - startedAt;
                return true;
            } catch (error) {
                console.warn(`[r185 loading compile failed: ${label}]`, error);
                r185OptimizationStats.compileAsyncErrors += 1;
                return false;
            }
        }
        r185OptimizationStats.compileAsyncSupported = typeof renderer.compileAsync === 'function';
        if (typeof renderer.compileAsync === 'function') {
            try {
                r185OptimizationStats.compileAsyncCalls += 1;
                // A few Windows/WebGL drivers expose KHR_parallel_shader_compile
                // but never settle the completion promise. Shader preparation is
                // an optimization, not a boot requirement: wait for a small budget
                // and let the already-started driver compilation finish in the
                // background instead of trapping Live Server/Poki on loading.
                const compilePromise = Promise.resolve(renderer.compileAsync(root, activeCamera))
                    .then(() => ({ status: 'ready' }))
                    .catch((error) => ({ status: 'error', error }));
                let timeoutHandle = 0;
                const timeoutMs = label === 'full-gameplay-prewarm'
                    ? 8000
                    : (label === 'gameplay-prewarm'
                        ? 1400
                        : (label.startsWith('campaign-phase-')
                            ? 6000
                            : (label === 'nature-critical-prewarm' ? 5000 : 1800)));
                const timeoutPromise = new Promise((resolve) => {
                    timeoutHandle = setTimeout(() => resolve({ status: 'timeout' }), timeoutMs);
                });
                const outcome = await Promise.race([compilePromise, timeoutPromise]);
                r185OptimizationStats.compileWaitMs += performance.now() - startedAt;
                if (outcome.status === 'ready') {
                    clearTimeout(timeoutHandle);
                    return true;
                }
                if (outcome.status === 'timeout') {
                    r185OptimizationStats.compileAsyncTimeouts += 1;
                    compilePromise.then((lateOutcome) => {
                        if (lateOutcome.status === 'ready') r185OptimizationStats.compileAsyncBackgroundSettled += 1;
                        else {
                            r185OptimizationStats.compileAsyncErrors += 1;
                            console.warn(`[r185 background compile failed: ${label}]`, lateOutcome.error);
                        }
                    });
                    return false;
                }
                clearTimeout(timeoutHandle);
                r185OptimizationStats.compileAsyncErrors += 1;
                console.warn(`[r185 compileAsync failed: ${label}]`, outcome.error);
                // Browser boot must remain recoverable. A synchronous compile on
                // the same broken driver can block the main thread indefinitely.
                if (isBrowserBuild()) return false;
            } catch (error) {
                console.warn(`[r185 compileAsync fallback: ${label}]`, error);
                r185OptimizationStats.compileAsyncErrors += 1;
                if (isBrowserBuild()) {
                    r185OptimizationStats.compileWaitMs += performance.now() - startedAt;
                    return false;
                }
            }
        }
        if (typeof renderer.compile === 'function') {
            r185OptimizationStats.compileFallbackCalls += 1;
            renderer.compile(root, activeCamera);
            r185OptimizationStats.compileWaitMs += performance.now() - startedAt;
            return true;
        }
        return false;
    }

    function getR185OptimizationSnapshot() {
        const curvedSnapshot = curvedPathSystem && typeof curvedPathSystem.snapshot === 'function'
            ? curvedPathSystem.snapshot()
            : null;
        return {
            ...r185OptimizationStats,
            compileWaitMs: roundForText(r185OptimizationStats.compileWaitMs, 1),
            composer: gfxComposer ? {
                width: gfxComposerWidth,
                height: gfxComposerHeight,
                pixelRatio: roundForText(gfxComposerPixelRatio, 3),
                samples: Number(gfxComposer.readBuffer?.samples) || 0
            } : null,
            rendererMemory: renderer?.info?.memory ? {
                geometries: Number(renderer.info.memory.geometries) || 0,
                textures: Number(renderer.info.memory.textures) || 0
            } : null,
            shaderPrograms: Array.isArray(renderer?.info?.programs) ? renderer.info.programs.length : 0,
            curvedAllocationReuse: curvedSnapshot?.allocationReuse || null
        };
    }

    function primeObjectTexturesForR185(root) {
        if (!renderer || typeof renderer.initTexture !== 'function' || !root?.traverse) return 0;
        const seen = new Set();
        const textureKeys = [
            'map', 'emissiveMap', 'normalMap', 'roughnessMap', 'metalnessMap',
            'aoMap', 'alphaMap', 'lightMap', 'bumpMap', 'displacementMap'
        ];
        root.traverse((object) => {
            const materials = Array.isArray(object?.material)
                ? object.material
                : (object?.material ? [object.material] : []);
            for (const material of materials) {
                for (const key of textureKeys) {
                    const texture = material?.[key];
                    if (!texture?.isTexture || seen.has(texture)) continue;
                    seen.add(texture);
                    renderer.initTexture(texture);
                }
            }
        });
        r185OptimizationStats.textureUploadsPrimed += seen.size;
        return seen.size;
    }

    async function primeObjectTexturesForR185Sliced(root, perSlice = 2) {
        if (!renderer || typeof renderer.initTexture !== 'function' || !root?.traverse) return 0;
        const seen = new Set();
        const keys = [
            'map', 'emissiveMap', 'normalMap', 'roughnessMap', 'metalnessMap',
            'aoMap', 'alphaMap', 'lightMap', 'bumpMap', 'displacementMap'
        ];
        root.traverse((object) => {
            const materials = Array.isArray(object?.material)
                ? object.material : (object?.material ? [object.material] : []);
            for (const material of materials) {
                for (const key of keys) {
                    const texture = material?.[key];
                    if (texture?.isTexture) seen.add(texture);
                }
            }
        });
        let uploaded = 0;
        for (const texture of seen) {
            renderer.initTexture(texture);
            r185OptimizationStats.textureUploadsPrimed += 1;
            if (++uploaded % perSlice === 0) await yieldLoadingSlice();
        }
        return uploaded;
    }

    function prepareNaturePrewarmScene() {
        ensureNatureModelTypes();
        if (!natureMenuPrewarmScene) {
            natureMenuPrewarmScene = new THREE.Scene();
            natureMenuPrewarmScene.name = 'level-one-nature-prewarm-scene';
            natureMenuPrewarmScene.fog = new THREE.FogExp2(0x18331a, 0.0012);
            natureMenuPrewarmScene.add(new THREE.AmbientLight(0xffffff, 0.20));
            natureMenuPrewarmScene.add(new THREE.HemisphereLight(0xbfe7ff, 0x26351a, 0.34));
            const warmSun = new THREE.DirectionalLight(0xfff1d0, 0.72);
            warmSun.position.set(-90, 150, 70);
            warmSun.castShadow = true;
            warmSun.target.position.set(40, 0, 0);
            natureMenuPrewarmScene.add(warmSun, warmSun.target);
        }
        return natureMenuPrewarmScene;
    }

    async function warmNextNatureModelType(options = {}) {
        if (natureMenuPrewarmComplete || !renderer || !camera) return false;
        const warmScene = prepareNaturePrewarmScene();
        const type = NATURE_MENU_PREWARM_TYPES[natureMenuPrewarmCursor];
        const made = createNatureObjectByType(type);
        // createNatureObjectByType returns placement metadata. Compile the actual
        // Object3D, then detach it without disposing shared geometry/materials.
        const node = made?.obj || made;
        if (node?.isObject3D) {
            node.position.set(0, Number(made?.yPos) || 0, 0);
            node.visible = true;
            node.traverse?.((child) => { child.frustumCulled = false; });
            warmScene.add(node);
            try {
                primeObjectTexturesForR185(node);
                if (options.compile !== false) await compileSceneForR185(warmScene, camera, `nature-${type}`);
            } finally {
                warmScene.remove(node);
            }
        }
        natureMenuPrewarmCursor += 1;
        natureMenuPrewarmComplete = natureMenuPrewarmCursor >= NATURE_MENU_PREWARM_TYPES.length;
        return true;
    }

    async function compileCriticalNatureAssetsDuringLoading() {
        if (natureCriticalShadersCompiled || !renderer || !camera) return natureCriticalShadersCompiled;
        const warmScene = prepareNaturePrewarmScene();
        const nodes = [];
        const warmShadows = !!getQualityPreset()?.shadows;
        const addWarmNode = (node, y = 0) => {
            if (!node?.isObject3D) return;
            node.position.set((nodes.length % 8) * 22, y, Math.floor(nodes.length / 8) * 24);
            node.visible = true;
            node.traverse?.((child) => {
                child.frustumCulled = false;
                if (child.isMesh) {
                    child.castShadow = warmShadows;
                    child.receiveShadow = warmShadows;
                }
            });
            nodes.push(node);
        };

        // Shader programs are keyed by material/light defines, not by every
        // geometry variant. One representative per material family avoids
        // compiling the same PBR program dozens of times on Poki's first load.
        if (natureTypeCache.tree[0]) addWarmNode(instantiatePartsSet(natureTypeCache.tree[0]), -2);
        for (const type of ['bush', 'rock', 'camp', 'windmill']) {
            const made = createNatureObjectByType(type);
            const node = made?.obj || made;
            addWarmNode(node, Number(made?.yPos) || 0);
        }
        if (natureTypeCache.mountainGeos[0]) {
            addWarmNode(new THREE.Mesh(natureTypeCache.mountainGeos[0], mats.mountainVC), -4);
        }
        // Include the real Nature floor material permutation (normal/roughness maps + fog) without
        // reparenting the live floor out of the gameplay scene.
        if (natureFloor?.geometry && natureFloor?.material) {
            const floorWarm = new THREE.Mesh(natureFloor.geometry, natureFloor.material);
            floorWarm.rotation.x = -Math.PI / 2;
            floorWarm.scale.setScalar(0.08);
            addWarmNode(floorWarm, -2.5);
        }
        // Compile each representative material family separately. Compiling
        // the whole Nature scene in one call monopolised older WebGL drivers
        // for several seconds and visibly froze the loading flight.
        const previousTarget = renderer.getRenderTarget?.() || null;
        const previousShadowEnabled = renderer.shadowMap.enabled;
        const previousShadowAutoUpdate = renderer.shadowMap.autoUpdate;
        const warmTarget = new THREE.WebGLRenderTarget(16, 16, {
            depthBuffer: true,
            stencilBuffer: false
        });
        try {
            renderer.shadowMap.enabled = true;
            renderer.shadowMap.autoUpdate = true;
            for (const node of nodes) {
                warmScene.add(node);
                try {
                    primeObjectTexturesForR185(node);
                    renderer.setRenderTarget(warmTarget);
                    const compiled = await compileSceneForR185(warmScene, camera, 'nature-critical-node');
                    if (!compiled) {
                        // Some drivers never resolve parallel compile. Keep a
                        // bounded one-material fallback, not a whole-scene stall.
                        const startedAt = performance.now();
                        r185OptimizationStats.compileFallbackCalls += 1;
                        renderer.compile(warmScene, camera);
                        r185OptimizationStats.compileWaitMs += performance.now() - startedAt;
                    }
                    renderer.shadowMap.needsUpdate = true;
                    renderer.clear(true, true, true);
                    renderer.render(warmScene, camera);
                } finally {
                    warmScene.remove(node);
                }
                await yieldLoadingSlice();
            }
            natureCriticalShadersCompiled = true;
        } finally {
            nodes.forEach((node) => warmScene.remove(node));
            renderer.setRenderTarget(previousTarget);
            renderer.shadowMap.enabled = previousShadowEnabled;
            renderer.shadowMap.autoUpdate = previousShadowAutoUpdate;
            warmTarget.dispose();
        }
        return natureCriticalShadersCompiled;
    }

    async function runFlightSafePreparation(work) {
        const prepare = async () => {
            try { return await work(); }
            finally {
                const gl = renderer?.getContext?.();
                if (gl?.fenceSync && !gl.isContextLost()) {
                    const fence = gl.fenceSync(gl.SYNC_GPU_COMMANDS_COMPLETE, 0);
                    if (fence) {
                        gl.flush();
                        try {
                            while (!gl.isContextLost()) {
                                if (gl.clientWaitSync(fence, 0, 0) !== gl.TIMEOUT_EXPIRED) break;
                                await new Promise(resolve => setTimeout(resolve, 16));
                            }
                        } finally { gl.deleteSync(fence); }
                    }
                }
            }
        };
        const flight = window.ElementalLoadingMinigame;
        return flight?.runPreparation ? flight.runPreparation(prepare) : prepare();
    }

    function createFlightSafeGLTFLoader() {
        const loader = new THREE.GLTFLoader();
        // Vehicle and hand GLBs are Meshopt-compressed. Every loader, including
        // the flight-safe wrapper, must register the decoder before parsing.
        if (THREE.MeshoptDecoder && typeof loader.setMeshoptDecoder === 'function') {
            loader.setMeshoptDecoder(THREE.MeshoptDecoder);
        }
        const parse = loader.parse;
        // Fetch remains concurrent; parsing and onLoad share the flight gate.
        loader.parse = function (data, path, onLoad, onError) {
            runFlightSafePreparation(() => new Promise((resolve, reject) => {
                parse.call(loader, data, path, gltf => {
                    try { onLoad(gltf); resolve(); } catch (error) { reject(error); }
                }, reject);
            })).catch(error => { if (onError) onError(error); });
        };
        return loader;
    }

    function yieldLoadingSlice() {
        return new Promise((resolve) => {
            const fallback = setTimeout(resolve, 34);
            requestAnimationFrame(() => {
                clearTimeout(fallback);
                resolve();
            });
        });
    }

    async function prewarmMapCachesDuringLoading() {
        // Only the immediate route belongs on the critical loading path:
        // Tutorial/City -> Level 1/Nature. Level 2/Snow and later biomes are
        // compiled by prepareCampaignLevelStart before their own run begins.
        if (getQualityPreset()?.envMap) {
            const previousEnv = scene.environment;
            const previousRT = gfxEnvRT;
            const previousMood = gfxEnvMoodKey;
            try {
                for (const phase of [0, 1]) {
                    gfxEnsureEnvironmentForPhase(phase);
                    await yieldLoadingSlice();
                }
            } finally {
                scene.environment = previousEnv;
                gfxEnvRT = previousRT;
                gfxEnvMoodKey = previousMood;
            }
        }
    }

    async function prewarmNatureAssetsDuringLoading() {
        // Nature is Level 1. Finish CPU cache creation and shader/GPU uploads while
        // the loading panel is still visible, in small slices, so the tutorial ->
        // Nature hand-off never creates a whole biome on one gameplay frame.
        await compileCriticalNatureAssetsDuringLoading();
        // ensureNatureModelTypes() above has already populated every shared CPU
        // geometry/material cache. The remaining per-type draw checks are safe
        // to run in idle slices after the loading card closes.
        await prepareNatureIntroObjectsDuringLoading();
    }

    async function prepareNatureIntroObjectsDuringLoading() {
        if (natureIntroCacheReady || natureIntroCacheUsed || !scene || !player) return;
        // Shared shaders alone were not enough: Level 1 still cloned and merged dozens of
        // trees in its first visible frames. Build the opening corridor while the loading
        // card is authoritative, then only rebase/reveal these objects at the hand-off.
        let seed = 0x4e415455;
        const random = () => {
            seed = (Math.imul(seed, 1664525) + 1013904223) >>> 0;
            return seed / 4294967296;
        };
        const nearTypes = ['tree', 'tree', 'bush', 'rock', 'flower', 'mushroom', 'grass', 'cattail', 'stump', 'log'];
        const roadCenter = getRoadCenterZ();
        const roadHalf = getRoadHalfWidth();
        let madeCount = 0;
        const stage = (relativeX, z, type) => {
            const object = spawnNatureObjectHidden(relativeX, z, type);
            if (!object) return;
            object.userData.natureIntroRelativeX = relativeX;
            natureIntroPreparedObjects.push(object);
            madeCount += 1;
        };

        const weakNatureHardware = graphicsState.hardwareProfile?.recommendedQuality === 'performance' || MOBILE_LOW_END || RUNTIME_LOW_POWER;
        const rowCount = MOBILE_RUNTIME ? (weakNatureHardware ? 7 : 10) : (weakNatureHardware ? 8 : 20);
        for (let row = 0; row < rowCount; row++) {
            const relativeX = 54 + row * 34 + (random() - 0.5) * 7;
            for (let side = -1; side <= 1; side += 2) {
                const type = nearTypes[Math.floor(random() * nearTypes.length)];
                stage(relativeX + (random() - 0.5) * 8, roadCenter + side * (roadHalf + 18 + random() * 74), type);
                if (row % (weakNatureHardware ? 6 : 4) === 1) {
                    stage(relativeX + 10 + random() * 8, roadCenter + side * (roadHalf + 95 + random() * 90), random() > 0.55 ? 'hill' : 'tree');
                }
                if (row % (weakNatureHardware ? 9 : 7) === 3) {
                    stage(relativeX + 230 + random() * 70, roadCenter + side * (roadHalf + 540 + random() * 260), 'mountain');
                }
            }
            // Time-slice CPU mesh creation on weak browsers. A slightly longer loading card is
            // preferable to a gameplay freeze exactly when the tutorial finishes.
            if (madeCount > 0 && madeCount % 6 < 3) await yieldLoadingSlice();
        }
        natureIntroCacheReady = natureIntroPreparedObjects.length > 0;
        // The final loading task applies the selected quality preset before drawing
        // these objects. Drawing them here as well compiles the same Nature shaders
        // twice and starves the loading minigame on weak GPUs.
        if (!loadingPipelineActive) await warmPreparedNatureIntroRenderDuringLoading();
    }

    async function warmPreparedNatureIntroRenderDuringLoading() {
        if (!natureIntroCacheReady || !renderer || !scene || !camera) return;
        const previousTarget = renderer.getRenderTarget?.() || null;
        const previousShadowEnabled = renderer.shadowMap.enabled;
        const previousShadowAuto = renderer.shadowMap.autoUpdate;
        const previousViewport = renderer.getViewport(new THREE.Vector4());
        const previousScissor = renderer.getScissor(new THREE.Vector4());
        const previousScissorTest = renderer.getScissorTest();
        // Boot camera still faces -Z. Gameplay faces +X; warming with the boot
        // camera left the prepared corridor outside the rasterized area.
        const warmCamera = camera.clone();
        warmCamera.position.set(player.position.x, normalHeight / 2, getRoadCenterZ());
        warmCamera.up.set(0, 1, 0);
        warmCamera.lookAt(player.position.x + 100, normalHeight / 2, getRoadCenterZ());
        warmCamera.updateMatrixWorld(true);
        const drawingBufferSize = renderer.getDrawingBufferSize(new THREE.Vector2());
        // A 24x24 draw compiled shaders but did not force weak drivers to finish
        // texture/mipmap and render-target work representative of gameplay. Pay
        // that first full Nature draw behind the loading card at a bounded size.
        const warmWidthCap = MOBILE_RUNTIME ? 384 : 640;
        const warmHeightCap = MOBILE_RUNTIME ? 216 : 360;
        const warmWidth = Math.max(96, Math.min(warmWidthCap, Math.floor(drawingBufferSize.x || warmWidthCap)));
        const warmHeight = Math.max(54, Math.min(warmHeightCap, Math.floor(drawingBufferSize.y || warmHeightCap)));
        const warmTarget = new THREE.WebGLRenderTarget(warmWidth, warmHeight, { depthBuffer: true, stencilBuffer: false });
        const warmScene = prepareNaturePrewarmScene();
        const variants = new THREE.Group();
        variants.name = 'nature-live-material-variants';
        const addVariant = (node) => {
            if (!node?.isObject3D) return;
            const i = variants.children.length;
            node.position.set(35 + (i % 5) * 14, 0, (i % 2 ? -1 : 1) * (12 + (i % 4) * 7));
            node.traverse(child => { child.frustumCulled = false; });
            variants.add(node);
        };
        // The earlier isolated light rig forced cast/receiveShadow on all
        // prototypes. Actual scenery uses unshadowed meshes; warm those exact
        // material/geometry families in the live lighting environment as well.
        if (natureTypeCache.tree[0]) addVariant(instantiatePartsSet(natureTypeCache.tree[0]));
        for (const type of ['bush', 'rock', 'camp', 'windmill', 'mountain']) {
            const made = createNatureObjectByType(type);
            addVariant(made?.obj || made);
        }
        if (natureFloor?.geometry && natureFloor?.material) {
            const floorWarm = new THREE.Mesh(natureFloor.geometry, natureFloor.material);
            floorWarm.rotation.x = -Math.PI / 2;
            floorWarm.scale.setScalar(0.08);
            addVariant(floorWarm);
        }
        const warmNodes = [...variants.children];
        variants.remove(...warmNodes);
        // Gameplay obstacle families were compiled by gameplay-prewarm already.
        // Rasterizing that entire mixed-map catalogue a second time here was
        // the longest GPU stall in the loading flight; only Nature's actual
        // opening environment needs this real hidden draw.
        try {
            // Compile the exact shadow permutation selected for this device.
            // Forcing shadows on here warmed the High shader, then Performance
            // devices compiled a second shadowless PBR program on Level 1's
            // first visible frame.
            // Nature has no dynamic shadows in the live phase policy, even
            // when Cyber uses High. Warm its actual shader variant.
            renderer.shadowMap.enabled = false;
            renderer.shadowMap.autoUpdate = false;
            // A full-scene compile/render monopolised the GPU for several seconds
            // and stalled the concurrently running loading flight. Shader programs
            // are cached per material family, so rasterize one family per slice.
            for (const node of warmNodes) {
                warmScene.add(node);
                try {
                    primeObjectTexturesForR185(node);
                    renderer.setRenderTarget(warmTarget);
                    renderer.setViewport(0, 0, warmWidth, warmHeight);
                    renderer.setScissorTest(false);
                    if (!await compileSceneForR185(warmScene, warmCamera, 'nature-live-target')) {
                        renderer.compile(warmScene, warmCamera);
                    }
                    renderer.clear(true, true, true);
                    renderer.render(warmScene, warmCamera);
                    // Performance renders straight to the sRGB canvas, while
                    // High uses a linear target. Warm both output permutations.
                    renderer.setRenderTarget(null);
                    renderer.setViewport(0, 0, 192, 108);
                    renderer.setScissor(0, 0, 192, 108);
                    renderer.setScissorTest(true);
                    if (!await compileSceneForR185(warmScene, warmCamera, 'nature-live-canvas')) {
                        renderer.compile(warmScene, warmCamera);
                    }
                    renderer.render(warmScene, warmCamera);
                } finally {
                    warmScene.remove(node);
                }
                await yieldLoadingSlice();
            }
        } finally {
            renderer.setRenderTarget(previousTarget);
            renderer.shadowMap.enabled = previousShadowEnabled;
            renderer.shadowMap.autoUpdate = previousShadowAuto;
            renderer.setViewport(previousViewport);
            renderer.setScissor(previousScissor);
            renderer.setScissorTest(previousScissorTest);
            warmTarget.dispose();
        }
        await yieldLoadingSlice();
    }

    function scheduleLevelOneNaturePrewarm() {
        const scheduleFinalPhaseWarm = () => {
            if (natureCampaignWarmScheduled || campaignWarmPhases.has(1)) return;
            const tutorialIsAvailable = tutorialDirector?.active || tutorialDirector?.state === 'start-gate';
            if (!tutorialIsAvailable) return;
            // The loading pipeline already performed a real hidden Nature draw
            // (floor + trees + rocks + mountains + live lighting). Once every
            // shared model type has been materialized below, Phase 1 is fully
            // resident; compiling the same shader family again only recreates
            // the tutorial-to-level hitch on slow WebGL drivers.
            if (natureCriticalShadersCompiled && (natureIntroCacheReady || natureIntroCacheUsed)) {
                campaignWarmPhases.add(1);
                return;
            }
            natureCampaignWarmScheduled = true;
            const finishWarm = () => {
                ensureCampaignPhaseWarm(1)
                    .catch(() => {})
                    .finally(() => { natureCampaignWarmScheduled = false; });
            };
            if (typeof requestIdleCallback === 'function') requestIdleCallback(finishWarm, { timeout: 1800 });
            else setTimeout(finishWarm, 260);
        };
        if (natureMenuPrewarmComplete) {
            scheduleFinalPhaseWarm();
            return;
        }
        if (natureMenuPrewarmScheduled) return;
        natureMenuPrewarmScheduled = true;
        const warmNext = async () => {
            natureMenuPrewarmScheduled = false;
            if (natureMenuPrewarmComplete || !renderer || !camera) return;
            try {
                // The complete Nature PBR/shadow permutations were already
                // rasterized by warmPreparedNatureIntroRenderDuringLoading().
                // Re-running compileAsync for every geometry type can wait up
                // to 1.8 s per driver promise. Here we only materialize shared
                // geometry and prime texture uploads, one cheap type per slice.
                await warmNextNatureModelType({ compile: false });
            } catch (error) {
                console.warn('[NaturePrewarmSkipped]', error);
            }
            if (!natureMenuPrewarmComplete) scheduleLevelOneNaturePrewarm();
            else scheduleFinalPhaseWarm();
        };
        // One model/material permutation per quiet slice. The small inter-slice
        // gap prevents several driver compiles from clustering into one FTUE
        // frame on low-end portal devices.
        const enqueueIdleSlice = () => {
            const tutorialIsRunning = tutorialDirector?.active || tutorialDirector?.state === 'start-gate';
            if (tutorialIsRunning) setTimeout(warmNext, 1);
            else if (typeof requestIdleCallback === 'function') requestIdleCallback(warmNext, { timeout: 1500 });
            else setTimeout(warmNext, 24);
        };
        setTimeout(enqueueIdleSlice, tutorialDirector?.active ? 180 : 72);
    }

    function ensureCampaignPrepareOverlay() {
        if (campaignPrepareOverlay?.isConnected) return campaignPrepareOverlay;
        const overlay = document.createElement('div');
        overlay.id = 'campaign-level-loading';
        overlay.setAttribute('aria-hidden', 'true');
        overlay.innerHTML = '<section class="campaign-level-loading-card" role="status" aria-live="polite"><div class="campaign-level-loading-spinner" aria-hidden="true"></div><strong></strong><span></span></section>';
        document.body.appendChild(overlay);
        campaignPrepareOverlay = overlay;
        return overlay;
    }

    function showCampaignPrepareOverlay(levelNumber, phase) {
        const overlay = ensureCampaignPrepareOverlay();
        campaignPrepareLevel = Math.max(1, Math.floor(Number(levelNumber) || 1));
        campaignPreparePhase = Math.max(0, Math.min(5, Math.floor(Number(phase) || 0)));
        campaignPrepareStartedAt = performance.now();
        const title = overlay.querySelector('strong');
        const detail = overlay.querySelector('span');
        if (title) title.textContent = tr('loadingWorld').toLocaleUpperCase();
        if (detail) detail.textContent = `${tr('level')} ${campaignPrepareLevel} · ${getPhaseName(campaignPreparePhase).toLocaleUpperCase()} · ${tr('preparing')}`;
        overlay.classList.add('is-visible');
        overlay.setAttribute('aria-hidden', 'false');
        window.ElementalLoadingMinigame?.begin?.({
            host: overlay,
            mode: 'campaign',
            title: tr('loadingWorld').toLocaleUpperCase(),
            detail: `${tr('level')} ${campaignPrepareLevel} · ${getPhaseName(campaignPreparePhase).toLocaleUpperCase()}`
        });
        window.ElementalLoadingMinigame?.setProgress?.(4, tr('loadingWorld'), tr('preparing'));
    }

    function hideCampaignPrepareOverlay() {
        if (!campaignPrepareOverlay) return;
        campaignPrepareLastDurationMs = campaignPrepareStartedAt ? Math.round(performance.now() - campaignPrepareStartedAt) : 0;
        campaignPrepareOverlay.classList.remove('is-visible');
        campaignPrepareOverlay.setAttribute('aria-hidden', 'true');
        window.ElementalLoadingMinigame?.end?.({ force: true });
        campaignPrepareLevel = 0;
        campaignPrepareStartedAt = 0;
    }

    function waitForCampaignLoadingPaint() {
        return new Promise((resolve) => {
            const fallback = setTimeout(resolve, 80);
            requestAnimationFrame(() => requestAnimationFrame(() => {
                clearTimeout(fallback);
                resolve();
            }));
        });
    }

    function getCampaignWarmMaterials(phase) {
        const floorMaterial = phase === 1 ? natureFloor?.material
            : phase === 2 ? skyFloor?.material
            : phase === 3 ? lavaFloor?.material
            : phase === 4 ? waterFloor?.material
            : phase === 5 ? snowFloor?.material
            : cyberFloor?.material;
        const byPhase = {
            0: [mats.road, mats.building, mats.neon],
            1: [mats.natVCWood, mats.natVCFoliage, mats.natureGround, mats.road],
            2: [mats.skyVCSolid, mats.skyVCGlow, mats.skyMountainVC, mats.skyRoad],
            3: [mats.lavaRock, mats.lavaRockWarm, mats.lavaCore, mats.lavaSmoke],
            4: [mats.waterRock, mats.waterRockDark, mats.waterGlow, mats.waterFoam],
            5: [mats.snowRock, mats.snowRockDark, mats.snowCap, mats.snowIce]
        };
        return [...new Set([floorMaterial, ...(byPhase[phase] || [])].filter(Boolean))];
    }

    async function compileCampaignPhaseMaterials(phase) {
        if (!renderer || !camera || campaignWarmPhases.has(phase)) return;
        const previousTarget = renderer.getRenderTarget?.() || null;
        const previousEnv = scene.environment;
        const previousRT = gfxEnvRT;
        const previousMood = gfxEnvMoodKey;
        const previousShadow = renderer.shadowMap.enabled;
        const previousShadowAuto = renderer.shadowMap.autoUpdate;
        const warmScene = new THREE.Scene();
        const warmCamera = new THREE.PerspectiveCamera(62, 16 / 9, 0.1, 100);
        warmCamera.position.set(0, 3, 12);
        warmCamera.lookAt(0, 1, 0);
        warmScene.add(new THREE.AmbientLight(0xffffff, 0.32));
        warmScene.add(new THREE.HemisphereLight(0xcfe8ff, 0x263148, 0.45));
        const light = new THREE.DirectionalLight(0xffffff, 0.65);
        light.position.set(5, 9, 7);
        warmScene.add(light);
        const geometry = new THREE.BoxGeometry(1.7, 1.7, 1.7, 2, 2, 2);
        const colors = new Float32Array(geometry.attributes.position.count * 3).fill(0.82);
        geometry.setAttribute('color', new THREE.BufferAttribute(colors, 3));
        getCampaignWarmMaterials(phase).forEach((material, index) => {
            const mesh = new THREE.Mesh(geometry, material);
            mesh.position.set((index % 4 - 1.5) * 2.2, Math.floor(index / 4) * 2.1, 0);
            mesh.frustumCulled = false;
            warmScene.add(mesh);
        });
        const target = new THREE.WebGLRenderTarget(96, 54, { depthBuffer: true, stencilBuffer: false });
        try {
            gfxEnsureEnvironmentForPhase(phase);
            warmScene.environment = scene.environment;
            primeObjectTexturesForR185(warmScene);
            renderer.shadowMap.enabled = false;
            renderer.shadowMap.autoUpdate = false;
            // r185's parallel compile keeps the small loading game responsive.
            // The old synchronous renderer.compile() monopolised the main
            // thread once for every biome. Only issue the tiny upload render
            // after the async compile really completed; a timed-out driver is
            // allowed to finish its already-started compilation in background.
            const compiled = await compileSceneForR185(warmScene, warmCamera, `campaign-phase-${phase}`);
            if (compiled) {
                renderer.setRenderTarget(target);
                renderer.clear(true, true, true);
                renderer.render(warmScene, warmCamera);
            }
        } finally {
            renderer.setRenderTarget(previousTarget);
            renderer.shadowMap.enabled = previousShadow;
            renderer.shadowMap.autoUpdate = previousShadowAuto;
            scene.environment = previousEnv;
            gfxEnvRT = previousRT;
            gfxEnvMoodKey = previousMood;
            target.dispose();
            geometry.dispose();
        }
        await yieldLoadingSlice();
    }

    function ensureCampaignPhaseWarm(phase) {
        const targetPhase = Math.max(0, Math.min(5, Math.floor(Number(phase) || 0)));
        if (campaignWarmPhases.has(targetPhase)) return Promise.resolve();
        if (campaignWarmPromises.has(targetPhase)) return campaignWarmPromises.get(targetPhase);
        const promise = (async () => {
            await yieldLoadingSlice();
            if (targetPhase === 1) {
                await prewarmNatureAssetsDuringLoading();
                while (!natureMenuPrewarmComplete) {
                    await warmNextNatureModelType({ compile: false });
                    await yieldLoadingSlice();
                }
            } else if (targetPhase === 2) {
                ensureSkyModelTypes();
                await yieldLoadingSlice();
            } else if (targetPhase >= 3) {
                while (buildNextLavaModelTypeStep()) await yieldLoadingSlice();
                if (targetPhase >= 4) {
                    while (buildNextElementalMountainTypeStep()) await yieldLoadingSlice();
                }
                if (!browserDeferredPrototypeWarmReady) {
                    await prewarmLavaDecorPrototypes();
                    browserDeferredPrototypeWarmScheduled = true;
                    browserDeferredPrototypeWarmReady = true;
                }
            }
            await compileCampaignPhaseMaterials(targetPhase);
            campaignWarmPhases.add(targetPhase);
        })().catch((error) => {
            campaignWarmPromises.delete(targetPhase);
            console.warn('[CampaignMapPrewarm]', targetPhase, error);
            throw error;
        });
        campaignWarmPromises.set(targetPhase, promise);
        return promise;
    }

    async function prepareCampaignLevelStart(levelNumber, options = {}) {
        const level = levelSystem?.getLevelDefinition?.(levelNumber);
        if (!level) return false;
        const phases = [...new Set([level.themePhase, level.transitionThemePhase].filter((phase) => phase !== null && phase !== undefined))];
        const missing = phases.filter((phase) => !campaignWarmPhases.has(phase));
        if (!missing.length) return false;
        if (options.showOverlay !== false) {
            showCampaignPrepareOverlay(level.number, missing[0]);
            await waitForCampaignLoadingPaint();
        }
        const startedAt = performance.now();
        try {
            // Map preparation shares the flight exclusion gate with boot.
            for (let index = 0; index < missing.length; index++) {
                const phase = missing[index];
                if (options.showOverlay !== false) {
                    const startPercent = 8 + (index / missing.length) * 84;
                    window.ElementalLoadingMinigame?.setProgress?.(
                        startPercent,
                        tr('loadingWorld'),
                        `${getPhaseName(phase).toLocaleUpperCase()} · ${tr('preparing')}`
                    );
                }
                await runFlightSafePreparation(() => ensureCampaignPhaseWarm(phase));
                if (options.showOverlay !== false) {
                    const endPercent = 8 + ((index + 1) / missing.length) * 84;
                    window.ElementalLoadingMinigame?.setProgress?.(
                        endPercent,
                        tr('loadingShaders'),
                        `${getPhaseName(phase).toLocaleUpperCase()} · ${tr('readyToPlay')}`
                    );
                }
            }
            loadingTaskTimings.push({
                stage: `campaign-level-${level.number}-prewarm`,
                durationMs: Math.round((performance.now() - startedAt) * 10) / 10
            });
            if (options.showOverlay !== false) {
                await (window.ElementalLoadingMinigame?.markLoadingComplete?.({
                    label: tr('readyToPlay').toLocaleUpperCase(),
                    title: tr('readyToPlay').toLocaleUpperCase(),
                    detail: tr('tapToStart')
                }) || Promise.resolve());
            }
        } finally {
            if (options.showOverlay !== false) hideCampaignPrepareOverlay();
        }
        return true;
    }

    function primeCampaignLevelStart(levelNumber) {
        setTimeout(() => {
            prepareCampaignLevelStart(levelNumber, { showOverlay: false }).catch(() => {});
        }, 80);
    }

    function ensureLobbyHub() {
        if (lobbyHub || !window.ElementalLobbyHub || !renderer) return lobbyHub;
        const handStatus = (skin) => menuState.selectedHandSkin === skin.id ? tr('selected')
            : getOwnedHandSkinIds().includes(skin.id) ? tr('select')
            : `${tr('buy')} · ${skin.cost.toLocaleString()} ${tr('gold')}`;
        lobbyHub = new window.ElementalLobbyHub(THREE, {
            renderer: () => renderer, mobile: MOBILE_RUNTIME,
            lockPointer: () => requestPointerLockFromUi?.({ force: true, allowDisabled: true, lobby: true }),
            language: () => normalizeLanguage(menuState.language), tr,
            wallet: () => Math.max(0, Math.floor(menuState.walletCoins || 0)),
            skins: () => HAND_SKINS, handStatus,
            handPath: (id) => getHandModelAssetPath(id),
            adsAvailable: areRewardedAdsEnabled,
            wheelRotation: () => fortuneWheelSystem?.rotation || 0,
            blocked: () => rewardedAdBusy || fortuneWheelSystem?.overlayOpen || ui.menuDialogLayer?.classList.contains('is-open'),
            onEnter: () => {
                hideMainMenu();
                isGamePaused = true;
                if (viewmodelRig) viewmodelRig.visible = false;
                unlockMenuMusicFromUserGesture(); resetControlActionState();
                updateHandSkillUi(); clearBhopFeedbackForOverlay();
                crazyGamesPlatform()?.gameplayStop();
            },
            equip: (id) => {
                const skin = HAND_SKIN_BY_ID[id];
                if (!getOwnedHandSkinIds().includes(id) && menuState.walletCoins < skin.cost) return tr('notEnoughGold');
                buyOrEquipHandSkin(id);
                return `${skin.name} · ${tr('selected')}`;
            },
            wheelStatus: () => {
                if (fortuneWheelSystem?.canOpenFromMenu()) return tr('ready');
                const state = fortuneWheelSystem?.snapshot();
                if (!state?.firstSpinClaimed) return normalizeLanguage(menuState.language) === 'tr' ? 'BÖLÜM 2 SONRASI' : 'AFTER LEVEL 2';
                const seconds = Math.max(0, 300 - Math.floor(state.cooldownSeconds));
                return `${Math.floor(seconds / 60)}:${String(seconds % 60).padStart(2, '0')}`;
            },
            spin: () => {
                if (!fortuneWheelSystem?.canOpenFromMenu()) return normalizeLanguage(menuState.language) === 'tr' ? 'Çark henüz hazır değil' : 'Wheel is not ready yet';
                if (fortuneWheelSystem.open('menu')) fortuneWheelSystem.spin();
            },
            rewardSpeed: async () => {
                if (!areRewardedAdsEnabled() || rewardedAdBusy) return browserTr('adUnavailable');
                const result = await requestRewardedAd('lobby_speed_5m');
                if (result?.status !== 'completed') return browserTr('adUnavailable');
                fortuneWheelSystem.applyReward({ type: 'speed', seconds: 300 });
                fortuneWheelSystem.persist(); fortuneWheelSystem.refreshUi(true);
                playUiConfirmSound(); return browserTr('rewardGranted');
            },
            upgrades: () => [
                [tr('score'), getScoreUpgradeLevel(), SCORE_UPGRADE_MAX_LEVEL, getNextScoreUpgradeCost()],
                [tr('gold'), getCoinUpgradeLevel(), COIN_UPGRADE_MAX_LEVEL, getNextCoinUpgradeCost()],
                [tr('jump'), getJumpUpgradeLevel(), JUMP_UPGRADE_MAX_LEVEL, getNextJumpUpgradeCost()],
                [tr('speed'), getSpeedUpgradeLevel(), SPEED_UPGRADE_MAX_LEVEL, getNextSpeedUpgradeCost()]
            ].map(([name, level, max, cost]) => ({ name, level, max, cost, maxed: level >= max, canBuy: level < max && menuState.walletCoins >= cost })),
            buyUpgrade: (index) => [buyScoreMultiplierUpgrade, buyCoinMultiplierUpgrade, buyJumpHeightUpgrade, buySpeedUpgrade][index]?.(),
            openPanel: (panel) => openLobbyPanel(panel),
            escape: () => {
                if (fortuneWheelSystem?.overlayOpen) return;
                if (ui.menuDialogLayer?.classList.contains('is-open')) closeMenuDialogs();
                else openLobbyPanel('settings');
            },
            levelLabel: () => shouldRunFirstTutorial() ? (normalizeLanguage(menuState.language) === 'tr' ? 'EĞİTİM' : 'TUTORIAL') : `LEVEL ${levelSystem?.getSelectedLevel() || 1}`,
            selectLevel: (direction) => levelSystem?.selectLevel((levelSystem.getSelectedLevel() || 1) + direction),
            prepare: async (mode) => {
                if (mode === 'level' && !shouldRunFirstTutorial()) await prepareCampaignLevelStart(levelSystem.getSelectedLevel(), { showOverlay: false });
            },
            theme: () => {
                if (shouldRunFirstTutorial()) return 0;
                const level = levelSystem?.getLevelDefinition?.(levelSystem.getSelectedLevel());
                return Math.max(0, Math.min(5, Math.floor(Number(level?.themePhase) || 0)));
            },
            warmTheme: async () => {
                if (!shouldRunFirstTutorial()) await prepareCampaignLevelStart(levelSystem.getSelectedLevel(), { showOverlay: false });
            },
            start: (mode) => {
                unlockGameplayAudioFromUserGesture();
                if (mode === 'level' && shouldRunFirstTutorial()) {
                    const director = initializeTutorialDirector();
                    // An unfinished lesson can be restarted after returning to the hub.
                    if (!director.active && director.state === 'idle') director.gateConsumed = false;
                    director.start();
                }
                else beginRunFromMainMenu(true, mode === 'endless'
                    ? { endless: true, deferPointerLock: true }
                    : { level: levelSystem.getSelectedLevel(), source: 'lobby', deferPointerLock: true });
            }
        });
        return lobbyHub;
    }

    function openLobbyPanel(panel = 'upgrades') {
        hideHowToPlayOverlay(true);
        openMenuDialog(panel === 'settings' ? ui.menuSettingsDialog : ui.menuUpgradesDialog);
        document.body.classList.add('hub-panel-open');
        if (ui.mainMenu) { ui.mainMenu.style.display = 'flex'; ui.mainMenu.setAttribute('aria-hidden', 'false'); }
        if (panel === 'hands') setUpgradeShopTab('hands');
        updateUpgradeCards();
        try { if (document.pointerLockElement) document.exitPointerLock(); } catch (_) {}
    }

    function showMainMenu(resetRun = false) {
        levelGhostSystem?.stop();
        if (tutorialDirector && (tutorialDirector.active || tutorialDirector.state === 'start-gate')) tutorialDirector.cancel();
        hideHowToPlayOverlay(true);
        if (MOBILE_RUNTIME) setMobileControlsVisible(false);
        rewardedDeathPending = false;
        pendingRewardedDeathMessage = '';
        hideRewardedContinueOverlay();
        document.body.classList.remove('game-over-active');
        document.body.classList.add('main-menu-active');
        levelSystem?.deactivateForEndless?.();
        currentRunMode = 'endless';
        mainMenuVisible = true;
        measurePlayerFit('screen', 'main-menu', 'visible');
        isGamePaused = true;
        updateHandSkillUi();
        clearBhopFeedbackForOverlay();
        gamepadUiFocusIndex = 0;
        gamepadUiFocusKey = '';
        gamepadUiNavLatch = '';
        middleMouseHeld = false;
        gamepadGlideHeld = false;
        gamepadJumpHeld = false;
        gamepadMoveInput = 0;
        resetControlActionState();
        wheelSkillTapCount = 0;
        setGlideWindActive(false);
        updateDoubleJumpCooldownUi(true);
        stopGameplayMusicNow();
        if (resetRun) runStartedFromMenu = false;
        updateMainMenuStats();
        applyMainMenuSettings();
        closeMenuDialogs();
        if (ui.gameOver) ui.gameOver.style.display = 'none';
        if (ui.pauseScreen) ui.pauseScreen.style.display = 'none';
        if (ui.mainMenu) {
            ui.mainMenu.style.display = 'flex';
            ui.mainMenu.setAttribute('aria-hidden', 'false');
        }
        const menuPad = getPrimaryGamepad();
        if (menuPad) setControllerInputActive(true);
        if (controllerInputActive) resetGamepadUiFocus(0);
        tryStartMenuMusicAutoplay();
        updateMenuAudioUnlockPrompt();
        if (levelSystem && typeof levelSystem.refreshMenu === 'function') levelSystem.refreshMenu();
        scheduleLevelOneNaturePrewarm();
        try {
            if (document.pointerLockElement) document.exitPointerLock();
        } catch (e) {}
        const platform = crazyGamesPlatform();
        if (platform) {
            platform.gameplayStop();
            platform.clearContext();
        }
        if (lobbyHub?.active) lobbyHub.exit();
        ensureLobbyHub()?.show();
    }

    function hideMainMenu() {
        mainMenuVisible = false;
        document.body.classList.remove('main-menu-active');
        setMenuAmbientActive(false);
        updateMenuAudioUnlockPrompt();
        closeMenuDialogs();
        if (ui.mainMenu) {
            ui.mainMenu.style.display = 'none';
            ui.mainMenu.setAttribute('aria-hidden', 'true');
        }
    }

    function shouldRunFirstTutorial() {
        const params = new URLSearchParams(window.location.search);
        if (params.get('tutorial') === 'off') return false;
        if (params.get('tutorial') === '1') return true;
        return BROWSER_CONFIG.tutorialEnabled !== false && Number(menuState.tutorialVersion || 0) < TUTORIAL_VERSION;
    }

    function getTutorialCopy() {
        const language = normalizeLanguage(menuState.language);
        const mobile = MOBILE_RUNTIME;
        const copy = {
            title: 'ELEMENTAL RUN',
            // This is a universal, non-verbal entry affordance and intentionally
            // stays in English across locales to match the requested start screen.
            clickToStart: 'PLAY',
            skip: language === 'tr' ? 'EĞİTİMİ ATLA' : 'SKIP TUTORIAL',
            start: language === 'tr' ? 'EĞİTİMİ BAŞLAT' : 'START TUTORIAL',
            intro: language === 'tr'
              ? 'İki temel hareketi öğren, sonra koşu kesintisiz devam etsin.'
              : 'Learn two essential moves, then continue straight into the endless run.',
            jumpTitle: language === 'tr' ? 'TRAFİĞİN ÜZERİNDEN ZIPLA' : 'JUMP OVER THE TRAFFIC',
            slideTitle: language === 'tr' ? 'BARİYERİN ALTINDAN KAY' : 'SLIDE UNDER THE BARRIER',
            laneTitle: language === 'tr' ? 'DIŞ ŞERİDE GEÇ' : 'MOVE TO AN OUTER LANE',
            bunnyTitle: language === 'tr' ? 'ZIPLAMAYA DEVAM ET' : 'KEEP JUMPING',
            desktopJump: language === 'tr' ? 'SPACE / W / YUKARI OK' : 'SPACE / W / UP ARROW',
            desktopSlide: language === 'tr' ? 'C / AŞAĞI OK / S' : 'C / DOWN ARROW / S',
            desktopLane: language === 'tr' ? 'A / D / SOL / SAĞ OK' : 'A / D / LEFT / RIGHT',
            mobileJump: language === 'tr' ? 'YUKARI KAYDIR' : 'SWIPE UP',
            mobileSlide: language === 'tr' ? 'AŞAĞI KAYDIR' : 'SWIPE DOWN',
            mobileLane: language === 'tr' ? 'SOLA VEYA SAĞA KAYDIR' : 'SWIPE LEFT OR RIGHT',
            ready: language === 'tr' ? 'HAZIR OL' : 'GET READY',
            go: language === 'tr' ? 'DEVAM!' : 'GO!'
        };
        if (!mobile) return copy;
        return copy;
    }

    function tagTutorialObstacle(obs, lesson = '') {
        if (!obs) return null;
        const stableLesson = lesson || obs.userData?.tutorialLesson || 'jump';
        const sequence = ++tutorialHazardSerial;
        obs.userData = {
            ...obs.userData,
            tutorial: true,
            tutorialLesson: stableLesson,
            tutorialSequence: sequence,
            tutorialRewindId: `tutorial-${sequence}`,
            tutorialSpawnedAt: performance.now()
        };
        return obs;
    }

    // The lesson corridor is staged while the entry gate still covers the
    // world. Larger absolute gaps give new players time to read each obstacle
    // without creating visible mid-tutorial geometry pop-in.
    const TUTORIAL_CORRIDOR = Object.freeze({
        jumpLead: 210,
        slideX: 430,
        laneX: 680,
        bunnyX: 930,
        bunnyRowSpacing: 42,
        fallbackSlideLead: 220,
        fallbackLaneLead: 240,
        fallbackBunnyLead: 240
    });

    function spawnObstacleRow(type, spawnX, laneIndices, options = {}) {
        return laneIndices.map((laneIndex) => createObstacle(type, spawnX, laneIndex, options)).filter(Boolean);
    }

    function prewarmTutorialOpeningAssets() {
        if (!isPokiBuild() || !shouldRunFirstTutorial()) return;
        if (!tutorialCarPrototypes.length) {
            tutorialCarPrototypes = lanePositions.map((_, index) => {
                const car = createCarModel(mats.vehicles[index % mats.vehicles.length]);
                car.visible = false;
                return car;
            });
        }
        const seedPool = (type, count, factory) => {
            const pool = obstaclePool[type];
            if (!pool) return;
            while (pool.length < count) {
                const obstacle = factory();
                if (!obstacle) break;
                obstacle.visible = false;
                obstacle.position.set(-99999, -99999, -99999);
                obstacle.userData = { ...(obstacle.userData || {}), type };
                pool.push(obstacle);
            }
        };
        // The gate used to allocate 18 multi-mesh hazards in one input frame.
        // Pre-seeding the exact tutorial corridor moves those allocations to the
        // loading screen and makes the first playable frames stable.
        seedPool('wall', 2, createDetailedWall);
        seedPool('slide_barrier', lanePositions.length, createDetailedSlideBarrier);
        seedPool('low_wall', lanePositions.length * 3, createDetailedLowWall);
    }

    function consumeStagedTutorialHazards(lesson) {
        if (!tutorialStagedHazards || !Array.isArray(tutorialStagedHazards[lesson])) return [];
        const staged = tutorialStagedHazards[lesson]
            .filter((hazard) => hazard && obstacles.includes(hazard) && hazard.userData?.tutorialLesson === lesson)
            .sort((a, b) => (Number(a.userData?.tutorialSequence) || 0) - (Number(b.userData?.tutorialSequence) || 0));
        tutorialStagedHazards[lesson] = [];
        return staged;
    }

    function createTutorialSlideBarriersAt(spawnX) {
        return spawnObstacleRow('slide_barrier', spawnX, lanePositions.map((_, index) => index), {
            tutorial: true,
            lesson: 'slide'
        });
    }

    function createTutorialLaneWallsAt(spawnX) {
        // The four-lane opening road has two centre lanes (1, 2). Blocking
        // exactly those leaves the far-left and far-right routes readable.
        return spawnObstacleRow('wall', spawnX, [1, 2], { tutorial: true, lesson: 'lane' });
    }

    function createTutorialBunnyHopBarriersAt(firstX) {
        const rowSpacing = TUTORIAL_CORRIDOR.bunnyRowSpacing;
        const barriers = [];
        for (let row = 0; row < 3; row++) {
            const rowX = firstX + row * rowSpacing;
            for (let laneIndex = 0; laneIndex < lanePositions.length; laneIndex++) {
                const barrier = createObstacle('low_wall', rowX, laneIndex, { tutorial: true, lesson: 'bunny' });
                if (!barrier) continue;
                barrier.userData.tutorialRow = row;
                barriers.push(barrier);
            }
        }
        return barriers;
    }

    function stageRemainingTutorialHazards(runStartX) {
        // Build the complete lesson corridor in the same frame as the first
        // cars, while the dark PRESS ANY gate still covers the scene. Later
        // lesson transitions only consume these existing objects; they never
        // create geometry in the player's visible horizon.
        tutorialStagedHazards = {
            slide: createTutorialSlideBarriersAt(runStartX + TUTORIAL_CORRIDOR.slideX),
            lane: createTutorialLaneWallsAt(runStartX + TUTORIAL_CORRIDOR.laneX),
            bunny: createTutorialBunnyHopBarriersAt(runStartX + TUTORIAL_CORRIDOR.bunnyX)
        };
    }

    function buildTutorialOpeningCorridor() {
        if (!player) return [];
        // The first traffic row now approaches after a calm opening rather than
        // immediately demanding a jump on the first playable frames.
        const spawnX = player.position.x + TUTORIAL_CORRIDOR.jumpLead;
        const cars = lanePositions.map((_, index) => {
            const prepared = tutorialCarPrototypes[index] || null;
            tutorialCarPrototypes[index] = null;
            return createObstacle('vehicle', spawnX, index, {
                tutorial: true,
                lesson: 'jump',
                forceProcedural: true,
                instance: prepared,
                speedX: -0.035,
                lightsActive: false
            });
        }).filter(Boolean);
        stageRemainingTutorialHazards(player.position.x);
        return cars;
    }

    function spawnTutorialCars() {
        if (Array.isArray(tutorialPreparedOpeningCars)) {
            const prepared = tutorialPreparedOpeningCars
                .filter((hazard) => hazard?.userData?.tutorialLesson === 'jump' && obstacles.includes(hazard))
                .sort((a, b) => (Number(a.userData?.tutorialSequence) || 0) - (Number(b.userData?.tutorialSequence) || 0));
            tutorialPreparedOpeningCars = null;
            if (prepared.length === lanePositions.length) return prepared;
            clearTutorialHazards(getAllTutorialHazards());
            tutorialStagedHazards = null;
            tutorialHazardSerial = 0;
        }
        return buildTutorialOpeningCorridor();
    }

    function spawnTutorialSlideBarriers() {
        if (!player) return [];
        const staged = consumeStagedTutorialHazards('slide');
        return staged.length ? staged : createTutorialSlideBarriersAt(player.position.x + TUTORIAL_CORRIDOR.fallbackSlideLead);
    }

    function spawnTutorialLaneWalls() {
        if (!player) return [];
        const staged = consumeStagedTutorialHazards('lane');
        return staged.length ? staged : createTutorialLaneWallsAt(player.position.x + TUTORIAL_CORRIDOR.fallbackLaneLead);
    }

    function spawnTutorialBunnyHopBarriers() {
        if (!player) return [];
        const staged = consumeStagedTutorialHazards('bunny');
        return staged.length ? staged : createTutorialBunnyHopBarriersAt(player.position.x + TUTORIAL_CORRIDOR.fallbackBunnyLead);
    }

    function getTutorialHazardDistance(hazards) {
        if (!player || !Array.isArray(hazards) || !hazards.length) return Infinity;
        return Math.min(...hazards.filter(Boolean).map((hazard) => hazard.position.x - player.position.x));
    }

    function havePassedTutorialHazards(hazards) {
        if (!player || !Array.isArray(hazards) || !hazards.length) return true;
        return hazards.filter(Boolean).every((hazard) => player.position.x > hazard.position.x + (hazard.userData.length || 5) * 0.5 + 5);
    }

    function clearTutorialHazards(hazards) {
        if (!Array.isArray(hazards)) return;
        hazards.forEach((hazard) => {
            const index = obstacles.indexOf(hazard);
            if (index >= 0) removeObstacleAt(index);
        });
    }

    function getAllTutorialHazards() {
        return obstacles.filter((hazard) => hazard && hazard.userData?.tutorial === true);
    }

    // Capture the complete staged corridor, not only the active lesson. Moving
    // one lesson backwards while future lessons stayed in place caused rows to
    // overlap after a collision. Stable ids also make the snapshot independent
    // of obstacle-array order and pool reuse.
    function captureTutorialRewindState() {
        if (!player) return null;
        return {
            player: {
                y: player.position.y,
                z: player.position.z,
                velocityY: playerVelocityY,
                strafeVelocity: currentStrafeVelocity,
                jumping: isJumping,
                sliding: isSliding,
                slideTimer
            },
            score,
            hazards: getAllTutorialHazards().map((hazard) => ({
                id: hazard.userData.tutorialRewindId,
                relX: hazard.position.x - player.position.x,
                y: hazard.position.y,
                z: hazard.position.z
            }))
        };
    }

    function restoreTutorialRewindState(from, to, amount) {
        if (!player || !from || !to) return;
        const t = Math.max(0, Math.min(1, Number(amount) || 0));
        const lerp = (a, b) => a + (b - a) * t;
        const source = from.player || {};
        const target = to.player || {};
        player.position.y = lerp(Number(source.y) || 0, Number(target.y) || 0);
        player.position.z = lerp(Number(source.z) || 0, Number(target.z) || 0);
        playerVelocityY = lerp(Number(source.velocityY) || 0, Number(target.velocityY) || 0);
        currentStrafeVelocity = lerp(Number(source.strafeVelocity) || 0, Number(target.strafeVelocity) || 0);
        score = lerp(Number(from.score) || 0, Number(to.score) || 0);
        if (t >= 1) {
            isJumping = !!target.jumping;
            isSliding = !!target.sliding;
            slideTimer = Math.max(0, Number(target.slideTimer) || 0);
            document.body.classList.toggle('sliding', isSliding);
        }
        const fromHazards = new Map((from.hazards || []).map((entry) => [entry.id, entry]));
        const toHazards = new Map((to.hazards || []).map((entry) => [entry.id, entry]));
        getAllTutorialHazards().forEach((hazard) => {
            const id = hazard.userData?.tutorialRewindId;
            const a = fromHazards.get(id);
            const b = toHazards.get(id);
            if (!hazard || !a || !b) return;
            hazard.position.x = player.position.x + lerp(a.relX, b.relX);
            hazard.position.y = lerp(a.y, b.y);
            hazard.position.z = lerp(a.z, b.z);
        });
    }

    function getTutorialWorldTimeScale() {
        return tutorialDirector && typeof tutorialDirector.timeScale === 'function' ? tutorialDirector.timeScale() : 1;
    }

    function isTutorialRunActive() {
        return !!(tutorialDirector && tutorialDirector.active);
    }

    function initializeTutorialDirector() {
        if (tutorialDirector || !window.ElementalTutorialDirector) return tutorialDirector;
        tutorialDirector = new window.ElementalTutorialDirector({
            copy: getTutorialCopy,
            isMobile: () => MOBILE_RUNTIME,
            prepareInput: (sourceEvent) => {
                focusGameplaySurface();
                if (!MOBILE_RUNTIME && sourceEvent?.isTrusted && sourceEvent.code !== 'Escape' && requestPointerLockFromUi) {
                    // This is the only trusted gate gesture. Request capture
                    // synchronously before tutorial setup returns to the event
                    // loop; portal iframes revoke user activation afterwards.
                    requestPointerLockFromUi({ force: true, allowDisabled: true });
                }
            },
            beginRun: () => {
                playerFitTutorialStatesSent.clear();
                measurePlayerFit('button', 'tutorial-start', 'interact');
                measurePlayerFit('level', 'tutorial', 'start');
                if (tutorialGateWorldPrepared) {
                    tutorialGateWorldPrepared = false;
                    showHowToPlayOverlay(3700, true);
                    runStartedFromMenu = true;
                    menuState.runCount += 1;
                    saveMainMenuState();
                    updateMainMenuStats();
                    scheduleVehicleModelLoads();
                    isGamePaused = false;
                    if (ui.pauseScreen) ui.pauseScreen.style.display = 'none';
                    const platform = crazyGamesPlatform();
                    if (platform) {
                        platform.setContext({ mode: 'tutorial', map: getPhaseName(gamePhase), score: String(Math.floor(score)) });
                        platform.gameplayStart();
                    }
                    updateMobileControlsVisibility();
                    return;
                }
                beginRunFromMainMenu(true, { tutorial: true });
            },
            spawnCars: spawnTutorialCars,
            spawnSlideBarriers: spawnTutorialSlideBarriers,
            spawnLaneWalls: spawnTutorialLaneWalls,
            spawnBunnyHopBarriers: spawnTutorialBunnyHopBarriers,
            spawnFinish: () => {
                createLevelFinishGate({ number: 0, finishLead: 175 });
                if (levelFinishGate?.userData) {
                    levelFinishGate.name = 'TutorialFinishGate';
                    levelFinishGate.userData.type = 'tutorial_finish';
                    levelFinishGate.userData.tutorial = true;
                }
                return levelFinishGate;
            },
            hasCrossedFinish: () => !!(player && levelFinishGate && player.position.x >= levelFinishX),
            clearFinish: disposeLevelFinishGate,
            distanceToHazards: getTutorialHazardDistance,
            hasPassedHazards: havePassedTutorialHazards,
            clearHazards: clearTutorialHazards,
            captureState: captureTutorialRewindState,
            restoreState: restoreTutorialRewindState,
            complete: (completion = {}) => {
                menuState.tutorialVersion = TUTORIAL_VERSION;
                const skipped = completion?.skipped === true;
                measurePlayerFit('level', 'tutorial', skipped ? 'fail' : 'complete');
                if (skipped) measurePlayerFit('tutorial', 'ftue', 'skip');
                // Keep late-map merged caches and vehicle parsing away from the
                // delicate Tutorial -> Nature hand-off. They remain time-sliced,
                // but now begin after Level 1 has had time to settle.
                tutorialHeavyLoadReleaseAt = performance.now() + (skipped ? 4500 : 6500);
                saveMainMenuState();

                if (skipped) {
                    // CrazyGames' skip action used to enter Level 1, swap the
                    // complete Nature theme and release all deferred GLBs in
                    // one trusted-click frame. Return to the menu immediately
                    // and let the existing idle pre-warmer/model queue spread
                    // that work over several frames instead.
                    isGamePaused = true;
                    activeLevelConfig = null;
                    window.requestAnimationFrame(() => {
                        showMainMenu(false);
                        scheduleLevelOneNaturePrewarm();
                        window.setTimeout(() => scheduleVehicleModelLoads(), 420);
                    });
                    beginShadowStabilization(MOBILE_RUNTIME ? 2 : 3, 'tutorial-skip-menu');
                    return;
                }

                // End FTUE like a real level. Keeping the Cyber frame behind a
                // completion card removes the old same-frame Cyber -> Nature
                // rebuild. Level 1 is prepared while this static card is visible
                // and starts only after the player chooses Next Level.
                isGamePaused = true;
                activeLevelConfig = null;
                levelCompletionInProgress = false;
                runStartedFromMenu = false;
                pointerLockRecoveryPending = false;
                pointerLockRecoveryReason = '';
                hideHowToPlayOverlay(true);
                updateMobileControlsVisibility();
                const platform = crazyGamesPlatform();
                if (platform) {
                    platform.gameplayStop();
                    platform.clearContext();
                }
                levelSystem?.showTutorialCompletion?.({ score, coins: totalCoins });
                if (ui.pauseScreen) ui.pauseScreen.style.display = 'none';
                try {
                    if (document.pointerLockElement) document.exitPointerLock();
                } catch (e) {}
                primeCampaignLevelStart(1);
                beginShadowStabilization(MOBILE_RUNTIME ? 2 : 3, 'tutorial-complete-card');
            },
            onState: (snapshot) => {
                updateMobileControlsVisibility();
                trackPlayerFitTutorialState(snapshot);
            }
        });
        return tutorialDirector;
    }

    function showFirstRunTutorialGate() {
        measurePlayerFit('button', 'tutorial-start', 'visible');
        const director = initializeTutorialDirector();
        if (!director) {
            showMainMenu(true);
            return false;
        }
        // Portal SDKs may finish after gameplay has already begun. Let the
        // director reject that duplicate request before mutating pause/menu
        // state; otherwise a harmless late callback can freeze the run even
        // though the PRESS ANY gate itself stays hidden.
        if (!director.showGate()) return false;
        // Level 1 now follows a dedicated Tutorial Complete card. Warm Nature
        // during the gate as an early head start; the level-start preloader is
        // still authoritative if a slow device has not finished yet.
        scheduleLevelOneNaturePrewarm();
        if (!tutorialGateWorldPrepared) {
            // Build/reset the complete tutorial world while the loading screen
            // and dark gate still cover it. The player's first trusted input
            // must only reveal an already prepared run, never construct one.
            beginRunFromMainMenu(true, { tutorial: true, preparingGate: true, deferPointerLock: true });
            tutorialPreparedOpeningCars = buildTutorialOpeningCorridor();
            tutorialGateWorldPrepared = true;
        }
        isGamePaused = true;
        mainMenuVisible = false;
        if (ui.mainMenu) {
            ui.mainMenu.style.display = 'none';
            ui.mainMenu.setAttribute('aria-hidden', 'true');
        }
        return true;
    }

    function protectTutorialCollision(obstacle) {
        if (!tutorialDirector || !tutorialDirector.protects(obstacle) || !player) return false;
        // Correct inputs stay protected for their single teaching obstacle. A
        // missed input is intentionally allowed to reach the rewind handler.
        return !tutorialDirector.isWaitingForAction();
    }

    function resetFirstRunRewindRuntime() {
        firstRunRewindProtectionActive = false;
        firstRunRewindSequence = null;
        firstRunRewindHistory = [];
        firstRunRewindSampleAccumulator = 0;
        firstRunRewindInvulnerability = 0;
        firstRunRewindCount = 0;
        if (tutorialDirector && typeof tutorialDirector.setRewindVisual === 'function') tutorialDirector.setRewindVisual(false);
    }

    function isEarlyLevelAutoRewindEligible() {
        if (!isBrowserBuild() || currentRunMode !== 'level') return false;
        if (!levelSystem?.isActive?.()) return false;
        if (typeof levelSystem.allowsAutoRewind === 'function') return levelSystem.allowsAutoRewind();
        const selected = Number(levelSystem?.getActiveLevel?.()?.number || levelSystem?.selectedLevel || 0);
        return selected >= 1 && selected <= EARLY_LEVEL_REWIND_MAX_LEVEL;
    }

    function activateFirstRunRewindProtection() {
        if (!isEarlyLevelAutoRewindEligible()) return false;
        firstRunRewindProtectionActive = true;
        firstRunRewindHistory = [];
        firstRunRewindSampleAccumulator = 0;
        return true;
    }

    function finishFirstRunRewindProtection() {
        firstRunRewindProtectionActive = false;
        firstRunRewindHistory = [];
    }

    function captureFirstRunRewindState() {
        if (!player) return null;
        const minX = player.position.x - 120;
        const maxX = player.position.x + 1050;
        return {
            player: {
                y: player.position.y,
                z: player.position.z,
                velocityY: playerVelocityY,
                strafeVelocity: currentStrafeVelocity,
                jumping: isJumping,
                sliding: isSliding,
                slideTimer
            },
            score,
            totalCoins,
            obstacles: obstacles.filter((obstacle) => obstacle && obstacle.position && obstacle.position.x >= minX && obstacle.position.x <= maxX).map((obstacle) => ({
                uuid: obstacle.uuid,
                relX: obstacle.position.x - player.position.x,
                y: obstacle.position.y,
                z: obstacle.position.z,
                visible: obstacle.visible !== false
            }))
        };
    }

    function recordFirstRunRewindHistory(realDelta) {
        if (!firstRunRewindProtectionActive || firstRunRewindSequence || isTutorialRunActive() || !player) return;
        if (!isEarlyLevelAutoRewindEligible()) {
            finishFirstRunRewindProtection();
            return;
        }
        firstRunRewindInvulnerability = Math.max(0, firstRunRewindInvulnerability - realDelta);
        firstRunRewindSampleAccumulator += realDelta;
        firstRunRewindHistory.forEach((entry) => { entry.age += realDelta; });
        if (firstRunRewindSampleAccumulator < 0.1 && firstRunRewindHistory.length) return;
        firstRunRewindSampleAccumulator = 0;
        const state = captureFirstRunRewindState();
        if (state) firstRunRewindHistory.push({ age: 0, state });
        while (firstRunRewindHistory.length > 1 && firstRunRewindHistory[0].age > FIRST_RUN_REWIND_HISTORY_SECONDS) firstRunRewindHistory.shift();
    }

    function applyFirstRunRewindState(from, to, amount, complete = false) {
        if (!player || !from || !to) return;
        const t = Math.max(0, Math.min(1, Number(amount) || 0));
        const lerp = (a, b) => a + (b - a) * t;
        const sourcePlayer = from.player || {};
        const targetPlayer = to.player || {};
        player.position.y = lerp(Number(sourcePlayer.y) || 0, Number(targetPlayer.y) || 0);
        player.position.z = lerp(Number(sourcePlayer.z) || 0, Number(targetPlayer.z) || 0);
        playerVelocityY = lerp(Number(sourcePlayer.velocityY) || 0, Number(targetPlayer.velocityY) || 0);
        currentStrafeVelocity = lerp(Number(sourcePlayer.strafeVelocity) || 0, Number(targetPlayer.strafeVelocity) || 0);
        score = lerp(Number(from.score) || 0, Number(to.score) || 0);
        totalCoins = Math.round(lerp(Number(from.totalCoins) || 0, Number(to.totalCoins) || 0));

        const currentById = new Map(obstacles.filter(Boolean).map((obstacle) => [obstacle.uuid, obstacle]));
        const fromById = new Map((from.obstacles || []).map((snapshot) => [snapshot.uuid, snapshot]));
        const targetIds = new Set();
        (to.obstacles || []).forEach((target) => {
            targetIds.add(target.uuid);
            const obstacle = currentById.get(target.uuid);
            if (!obstacle) return;
            const source = fromById.get(target.uuid) || target;
            obstacle.position.x = player.position.x + lerp(Number(source.relX) || 0, Number(target.relX) || 0);
            obstacle.position.y = lerp(Number(source.y) || 0, Number(target.y) || 0);
            obstacle.position.z = lerp(Number(source.z) || 0, Number(target.z) || 0);
            if (complete) obstacle.visible = target.visible !== false;
        });

        if (!complete) return;
        for (let i = obstacles.length - 1; i >= 0; i--) {
            const obstacle = obstacles[i];
            if (!obstacle || targetIds.has(obstacle.uuid)) continue;
            const relX = obstacle.position.x - player.position.x;
            if (relX > -120 && relX < 1050) removeObstacleAt(i);
        }
        isJumping = !!targetPlayer.jumping;
        isSliding = !!targetPlayer.sliding;
        slideTimer = Math.max(0, Number(targetPlayer.slideTimer) || 0);
        document.body.classList.toggle('sliding', isSliding);
        updatePlayerSweepStart();
        updatePlayerSweepEnd();
    }

    function beginFirstRunRewind() {
        if (!firstRunRewindProtectionActive || firstRunRewindSequence || firstRunRewindInvulnerability > 0 || !player) return false;
        if (firstRunRewindCount >= 1) return false;
        if (!isEarlyLevelAutoRewindEligible()) {
            finishFirstRunRewindProtection();
            return false;
        }
        const targetEntry = firstRunRewindHistory.find((entry) => entry.age >= FIRST_RUN_REWIND_SECONDS) || firstRunRewindHistory[0];
        const from = captureFirstRunRewindState();
        if (!targetEntry || !from) return false;
        firstRunRewindSequence = { from, to: targetEntry.state, elapsed: 0, duration: 0.82 };
        firstRunRewindCount += 1;
        measurePlayerFit('assist', `level-${Math.max(1, playerFitCurrentLevel || 1)}`, 'auto-rewind');
        isGamePaused = true;
        resetControlActionState();
        jumpQueue = false;
        jumpQueueTimer = 0;
        if (tutorialDirector && typeof tutorialDirector.setRewindVisual === 'function') tutorialDirector.setRewindVisual(true);
        return true;
    }

    function updateFirstRunRewind(realDelta) {
        const rewind = firstRunRewindSequence;
        if (!rewind) return;
        rewind.elapsed += Math.max(0, Number(realDelta) || 0);
        const t = Math.min(1, rewind.elapsed / rewind.duration);
        const eased = 1 - Math.pow(1 - t, 3);
        applyFirstRunRewindState(rewind.from, rewind.to, eased, t >= 1);
        if (t < 1) return;
        firstRunRewindSequence = null;
        firstRunRewindHistory = [];
        firstRunRewindSampleAccumulator = 0;
        firstRunRewindInvulnerability = 1.15;
        isGamePaused = false;
        isDying = false;
        if (tutorialDirector && typeof tutorialDirector.setRewindVisual === 'function') tutorialDirector.setRewindVisual(false);
        requestShadowMapRefresh(null, true);
    }

    function getActiveLevelTuning() {
        return activeLevelConfig || (levelSystem && typeof levelSystem.getTuning === 'function' ? levelSystem.getTuning() : null);
    }

    function isEarlyLevelOnboardingActive() {
        const level = getActiveLevelTuning();
        return !!(levelSystem?.isActive?.() && level && Number(level.number) <= 5);
    }

    function areMotorcyclesAllowedForCurrentRun() {
        const level = getActiveLevelTuning();
        if (!levelSystem?.isActive?.() || !level) return true;
        return level.motorcyclesAllowed !== false && Number(level.number) > 5;
    }

    function setCyberWorldVisible(visible) {
        const show = !!visible;
        if (cyberFloor) cyberFloor.visible = show;
        cityBuildingInstances.forEach((mesh) => { if (mesh) mesh.visible = show; });
        cyberDecorObjects.forEach((entry) => { if (entry?.obj) entry.obj.visible = show; });
    }

    function activateLevelMapPhase(targetPhase, options = {}) {
        const target = Math.max(0, Math.min(5, Math.floor(Number(targetPhase) || 0)));
        const instant = options.instant !== false;
        if (!player || target === 0) {
            gamePhase = 0;
            transitionFactor = 0;
            setCyberWorldVisible(true);
            updateEnvironmentColors(0, 0);
            updateHudMapLabel(0);
            return;
        }

        clearObstacleCollection();
        // A selected campaign map owns the very first render. Keeping the city
        // instance batches alive but hidden avoids both a Cyber flash and a costly
        // rebuild when the player later returns to the menu/City.
        setCyberWorldVisible(false);
        if (target === 1) {
            gamePhase = 1;
            transitionFactor = 1;
            natureIntroSpawnActive = true;
            natureIntroStartX = player.position.x;
            natureIntroFillCompleted = false;
            nextNatureSpawnX = natureIntroStartX + NATURE_INTRO_SPAWN_START_AHEAD;
            if (!activatePreparedNatureIntro(natureIntroStartX)) removePreloadedNatureObjects();
            if (natureFloor) {
                natureFloor.visible = true;
                natureFloor.material.transparent = false;
                natureFloor.material.opacity = 1;
                natureFloor.material.depthWrite = true;
                if (natureFloor.userData?.leafSystem) natureFloor.userData.leafSystem.visible = true;
            }
            updateEnvironmentColors(1, 1);
            updateHudMapLabel(1);
            if (gfxBloomPass) gfxApplyPhaseBloom(1);
            requestShadowMapRefresh(null, true);
            return;
        }

        // The existing phase activators already build Sky/Lava/Water/Snow
        // correctly. Preserve the campaign score around this developer helper:
        // map selection must not fake thousands of points in a 300-point level.
        const preservedScore = score;
        debugForceMap(target, { instant });
        score = preservedScore;
        updateHudMapLabel(target);
        updateLevelProgressUi();
    }

    function applyActiveLevelTheme() {
        const level = getActiveLevelTuning();
        if (!level || !player) return;
        const phase = Math.max(0, Math.min(5, Math.floor(Number(level.themePhase) || 0)));
        activateLevelMapPhase(phase, { instant: true });
        if (levelSystem && typeof levelSystem.setScoreBase === 'function') levelSystem.setScoreBase(score);
        if (curvedPathSystem && typeof curvedPathSystem.configure === 'function') curvedPathSystem.configure(level);
        updateLevelProgressUi();
    }

    function ensureCurvedLaneGuides(requiredCount = getLaneSeparators().length) {
        if (curvedLaneGuideGroup && curvedLaneGuideMeshes.length === requiredCount) return;
        if (curvedLaneGuideGroup) disposeNode(curvedLaneGuideGroup);
        curvedLaneGuideGroup = new THREE.Group();
        curvedLaneGuideGroup.name = 'CurvedLaneGuides';
        curvedLaneGuideGroup.userData.worldRebaseExempt = true;
        curvedLaneGuideAnchorVirtualX = Math.floor(((player?.position.x || 0) + worldScrollX) / 18) * 18 - 36;
        curvedLaneGuideMeshes = Array.from({ length: requiredCount }, (_, index) => {
            const geometry = new THREE.BufferGeometry();
            geometry.setAttribute('position', new THREE.BufferAttribute(new Float32Array(48 * 6 * 3), 3));
            const material = new THREE.MeshBasicMaterial({
                color: 0xfff6ba,
                transparent: true,
                opacity: 0.9,
                depthWrite: false,
                polygonOffset: true,
                polygonOffsetFactor: -1,
                polygonOffsetUnits: -1,
                side: THREE.DoubleSide,
                toneMapped: false
            });
            const mesh = new THREE.Mesh(geometry, material);
            mesh.frustumCulled = false;
            mesh.renderOrder = 3;
            mesh.userData.laneGuideIndex = index;
            curvedLaneGuideGroup.add(mesh);
            return mesh;
        });
        scene.add(curvedLaneGuideGroup);
    }

    function updateCurvedLaneGuides() {
        const curveEnabled = !!(curvedPathSystem && curvedPathSystem.enabled && player);
        laneLines.forEach((line) => { if (line) line.visible = !curveEnabled; });
        animatingLines.forEach((line) => { if (line) line.visible = !curveEnabled; });
        // Sky also owns a legacy straight InstancedMesh lane-paint layer. If it
        // stays visible beside these spline guides, both layers overlap on a
        // straight and separate on a bend, leaving one set floating in space.
        if (skyLines?.mesh) {
            skyLines.mesh.visible = !curveEnabled;
            skyLines.mesh.userData.suppressedByCurvedGuides = curveEnabled;
        }
        if (!curveEnabled) {
            if (curvedLaneGuideGroup) curvedLaneGuideGroup.visible = false;
            return;
        }
        const separators = getLaneSeparators();
        const visualSeparators = isAnimatingLane
            ? separators.concat([laneAnimStartLimitZMax])
            : separators;
        ensureCurvedLaneGuides(visualSeparators.length);
        curvedLaneGuideGroup.visible = true;
        const floorY = getActiveRoadFloorY() + 0.045;
        const segmentCount = 48;
        const stride = 18;
        const dashLength = 9.5;
        const halfWidth = 0.24;
        const playerVirtualX = player.position.x + worldScrollX;
        const requiredStart = Math.floor((playerVirtualX - 36) / stride) * stride;
        // Advance only in whole dash intervals. Tying every vertex directly to
        // player.position.x made the lane paint travel with the camera. These
        // virtual-world anchors now remain planted on the asphalt and recycle
        // only after passing behind the player.
        if (!Number.isFinite(curvedLaneGuideAnchorVirtualX)) curvedLaneGuideAnchorVirtualX = requiredStart;
        while (curvedLaneGuideAnchorVirtualX < requiredStart) curvedLaneGuideAnchorVirtualX += stride;
        curvedLaneGuideMeshes.forEach((mesh, laneIndex) => {
            const isExpansionGuide = laneIndex >= separators.length;
            if (mesh.material) mesh.material.opacity = isExpansionGuide ? 0.9 * getLaneAnimationEase() : 0.9;
            const attribute = mesh.geometry.getAttribute('position');
            const vertices = attribute.array;
            let cursor = 0;
            for (let index = 0; index < segmentCount; index++) {
                const virtualX0 = curvedLaneGuideAnchorVirtualX + index * stride;
                const virtualX1 = virtualX0 + dashLength;
                const d0 = virtualX0 - playerVirtualX;
                const d1 = virtualX1 - playerVirtualX;
                const separator = visualSeparators[laneIndex];
                const p0L = curvedPathSystem.pointAt(d0, separator - halfWidth);
                const p0R = curvedPathSystem.pointAt(d0, separator + halfWidth);
                const p1L = curvedPathSystem.pointAt(d1, separator - halfWidth);
                const p1R = curvedPathSystem.pointAt(d1, separator + halfWidth);
                const quad = [
                    player.position.x + p0L.forward, floorY + p0L.vertical, p0L.lateral,
                    player.position.x + p1L.forward, floorY + p1L.vertical, p1L.lateral,
                    player.position.x + p1R.forward, floorY + p1R.vertical, p1R.lateral,
                    player.position.x + p0L.forward, floorY + p0L.vertical, p0L.lateral,
                    player.position.x + p1R.forward, floorY + p1R.vertical, p1R.lateral,
                    player.position.x + p0R.forward, floorY + p0R.vertical, p0R.lateral
                ];
                vertices.set(quad, cursor);
                cursor += quad.length;
            }
            attribute.needsUpdate = true;
        });
    }

    function primeActiveLevelCourse() {
        const level = getActiveLevelTuning();
        if (!player || !level || !levelSystem?.isActive?.()) return;
        // The course cursor is anchored once to the run start. Rows then keep
        // their exact world positions regardless of frame rate, retries or the
        // player's momentary speed. Replaying a level therefore reconstructs
        // the same route instead of sampling the endless-run spawner again.
        levelPatternSerial = 0;
        lastLevelPatternSpawnX = -9999;
        nextLevelPatternX = player.position.x + getLevelPatternFirstLead(level);
        // Prime the near course. Opening rows deliberately use lightweight
        // static hazards; if a later traffic row is waiting for its GLB/fallback
        // visual, stop here and let the streaming spawner retry that same row.
        for (let index = 0; index < 6; index++) {
            const before = levelPatternSerial;
            spawnActiveLevelPattern(player.position.x + 520);
            if (levelPatternSerial === before) break;
        }
    }

    function disposeLevelFinishGate() {
        if (levelFinishGate) disposeNode(levelFinishGate);
        levelFinishGate = null;
        levelFinishX = Number.POSITIVE_INFINITY;
        levelFinishTransition = null;
        if (levelFinishTexture) {
            try { levelFinishTexture.dispose(); } catch (e) {}
            levelFinishTexture = null;
        }
    }

    function clearLevelFinishCorridor(finishX) {
        if (!player) return;
        const minX = player.position.x + 52;
        const maxX = finishX + 72;
        for (let i = obstacles.length - 1; i >= 0; i--) {
            const obstacle = obstacles[i];
            if (obstacle?.position?.x < minX || obstacle.position.x > maxX) continue;
            obstacle.userData = obstacle.userData || {};
            obstacle.userData.levelFinishDissolve = {
                elapsed: 0,
                delay: Math.max(0, Math.min(0.42, (obstacle.position.x - minX) / Math.max(1, maxX - minX) * 0.42)),
                duration: 0.48,
                startY: obstacle.position.y,
                startScale: obstacle.scale.clone()
            };
            obstacle.userData.triggerOnly = true;
            obstacle.traverse((child) => { child.castShadow = false; });
        }
        for (let i = jumpPads.length - 1; i >= 0; i--) {
            const pad = jumpPads[i];
            if (pad?.position?.x < minX || pad.position.x > maxX) continue;
            pad.userData = pad.userData || {};
            pad.userData.levelFinishDissolve = {
                elapsed: 0,
                delay: Math.max(0, Math.min(0.32, (pad.position.x - minX) / Math.max(1, maxX - minX) * 0.32)),
                duration: 0.42,
                startY: pad.position.y,
                startScale: pad.scale.clone()
            };
        }
        requestShadowMapRefresh(null, true);
    }

    function updateLevelFinishTransition(delta) {
        if (!levelFinishTransition) return;
        levelFinishTransition.elapsed += Math.max(0, Number(delta) || 0);
        const elapsed = levelFinishTransition.elapsed;
        const updateDissolve = (object, remove) => {
            const fx = object?.userData?.levelFinishDissolve;
            if (!fx) return false;
            fx.elapsed += Math.max(0, Number(delta) || 0);
            const progress = Math.max(0, Math.min(1, (fx.elapsed - fx.delay) / fx.duration));
            const eased = progress * progress * (3 - 2 * progress);
            object.position.y = fx.startY + eased * 7.5;
            const scale = Math.max(0.025, 1 - eased);
            object.scale.set(fx.startScale.x * scale, fx.startScale.y * scale, fx.startScale.z * scale);
            if (progress < 1) return false;
            remove();
            return true;
        };
        for (let i = obstacles.length - 1; i >= 0; i--) {
            const obstacle = obstacles[i];
            updateDissolve(obstacle, () => removeObstacleAt(i));
        }
        for (let i = jumpPads.length - 1; i >= 0; i--) {
            const pad = jumpPads[i];
            updateDissolve(pad, () => {
                jumpPads.splice(i, 1);
                disposeNode(pad);
            });
        }
        if (!levelFinishGate) return;
        syncLevelFinishGateWidth();
        const entranceDelay = levelFinishTransition.gateDelay;
        const gateProgress = Math.max(0, Math.min(1, (elapsed - entranceDelay) / 0.82));
        const back = 1.70158;
        const eased = gateProgress < 1
            ? 1 + (back + 1) * Math.pow(gateProgress - 1, 3) + back * Math.pow(gateProgress - 1, 2)
            : 1;
        levelFinishGate.visible = gateProgress > 0;
        const finishFloorY = Number(levelFinishGate.userData?.floorY) || 0;
        levelFinishGate.position.y = finishFloorY + (1 - gateProgress) * -8;
        levelFinishGate.scale.set(1, Math.max(0.04, eased), Math.max(0.04, eased));
        levelFinishGate.rotation.x = (1 - gateProgress) * -0.06;
        const glow = levelFinishGate.userData?.arrivalGlow;
        if (glow?.material) {
            glow.material.opacity = gateProgress > 0 ? Math.max(0, (1 - gateProgress) * 0.72) : 0;
            const glowPulse = 0.65 + gateProgress * 1.9;
            const layout = levelFinishGate.userData?.finishWidthLayout;
            const glowWidthRatio = layout
                ? (levelFinishGate.userData.syncedFinishWidth || layout.baseRoadWidth) / Math.max(0.001, layout.baseRoadWidth)
                : 1;
            glow.scale.set(glowPulse * glowWidthRatio, glowPulse, glowPulse);
        }
        if (gateProgress >= 1 && !levelFinishTransition.settled) {
            levelFinishTransition.settled = true;
            levelFinishGate.position.y = finishFloorY;
            levelFinishGate.rotation.x = 0;
            levelFinishGate.scale.set(1, 1, 1);
            requestShadowMapRefresh(levelFinishX, true);
        }
    }

    function createLevelFinishGate(level) {
        disposeLevelFinishGate();
        if (!scene || !player || !level) return;
        levelFinishX = player.position.x + Math.max(150, Number(level.finishLead) || 190);
        clearLevelFinishCorridor(levelFinishX);

        const group = new THREE.Group();
        group.name = 'LevelFinishGate';
        const finishFloorY = getActiveRoadFloorY();
        group.position.set(levelFinishX, finishFloorY, getRoadCenterZ());
        group.userData = { type: 'level_finish', level: level.number, floorY: finishFloorY, mapPhase: gamePhase };
        const roadWidth = Math.max(28, getRoadWidth() + 3.5);
        const dark = new THREE.MeshStandardMaterial({ color: 0x17191d, roughness: 0.78, metalness: 0.22 });
        const light = new THREE.MeshStandardMaterial({ color: 0xe8e1d2, roughness: 0.68, metalness: 0.08 });
        const gold = new THREE.MeshStandardMaterial({ color: 0xc4a15f, roughness: 0.54, metalness: 0.34, emissive: 0x241707, emissiveIntensity: 0.32 });
        const postGeo = new THREE.BoxGeometry(1.35, 12.5, 1.35);
        const beamGeo = new THREE.BoxGeometry(1.4, 1.45, roadWidth + 4.8);
        const postAssemblies = [];
        [-1, 1].forEach((side) => {
            const assembly = new THREE.Group();
            assembly.userData.finishSide = side;
            assembly.position.z = side * (roadWidth * 0.5 + 1.55);
            const post = new THREE.Mesh(postGeo, dark);
            post.position.set(0, 6.25, 0);
            post.castShadow = true;
            post.receiveShadow = true;
            assembly.add(post);
            for (let y = 1.1; y < 11.7; y += 2.15) {
                const band = new THREE.Mesh(new THREE.BoxGeometry(1.48, 0.72, 1.48), y % 4 < 2 ? light : gold);
                band.position.set(0, y, 0);
                band.castShadow = true;
                band.receiveShadow = true;
                assembly.add(band);
            }
            postAssemblies.push(assembly);
            group.add(assembly);
        });
        const beam = new THREE.Mesh(beamGeo, dark);
        beam.position.y = 12.2;
        beam.castShadow = true;
        beam.receiveShadow = true;
        group.add(beam);

        const stripGeo = new THREE.BoxGeometry(7.5, 0.12, roadWidth);
        const strip = new THREE.Mesh(stripGeo, dark);
        strip.position.y = 0.08;
        strip.receiveShadow = true;
        group.add(strip);
        const tileWidth = roadWidth / 12;
        const finishTiles = [];
        for (let row = 0; row < 4; row++) {
            for (let col = 0; col < 12; col++) {
                const tile = new THREE.Mesh(
                    new THREE.BoxGeometry(1.86, 0.07, tileWidth + 0.02),
                    (row + col) % 2 === 0 ? light : dark
                );
                tile.position.set(-2.8 + row * 1.86, 0.17, -roadWidth * 0.5 + tileWidth * (col + 0.5));
                tile.receiveShadow = true;
                tile.userData.finishColumn = col;
                finishTiles.push(tile);
                group.add(tile);
            }
        }

        const canvas = document.createElement('canvas');
        canvas.width = 1024;
        canvas.height = 224;
        const ctx = canvas.getContext('2d');
        ctx.fillStyle = '#17191d';
        ctx.fillRect(0, 0, canvas.width, canvas.height);
        ctx.strokeStyle = '#c4a15f';
        ctx.lineWidth = 14;
        ctx.strokeRect(9, 9, canvas.width - 18, canvas.height - 18);
        ctx.fillStyle = '#eee7d8';
        ctx.font = '900 94px Arial, sans-serif';
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText('FINISH', canvas.width / 2, canvas.height / 2 + 2);
        levelFinishTexture = new THREE.CanvasTexture(canvas);
        levelFinishTexture.colorSpace = THREE.SRGBColorSpace;
        const banner = new THREE.Mesh(
            new THREE.PlaneGeometry(Math.min(roadWidth, 31), 6.4),
            new THREE.MeshBasicMaterial({ map: levelFinishTexture, transparent: false, side: THREE.DoubleSide })
        );
        // Face the approaching player; +PI/2 showed the double-sided texture
        // from its back and mirrored the FINISH lettering.
        banner.rotation.y = -Math.PI / 2;
        banner.position.set(-0.78, 9.3, 0);
        group.add(banner);
        const arrivalGlow = new THREE.Mesh(
            new THREE.RingGeometry(Math.max(8, roadWidth * 0.34), Math.max(11, roadWidth * 0.55), 48),
            new THREE.MeshBasicMaterial({ color: 0xffd77a, transparent: true, opacity: 0.7, depthWrite: false, side: THREE.DoubleSide, blending: THREE.AdditiveBlending })
        );
        arrivalGlow.rotation.y = -Math.PI / 2;
        arrivalGlow.position.set(-0.9, 6.2, 0);
        arrivalGlow.renderOrder = 8;
        group.add(arrivalGlow);
        group.userData.arrivalGlow = arrivalGlow;
        group.userData.finishWidthLayout = {
            baseRoadWidth: roadWidth,
            baseTileWidth: tileWidth,
            baseBannerWidth: Math.min(roadWidth, 31),
            postAssemblies,
            beam,
            strip,
            tiles: finishTiles,
            banner,
            arrivalGlow
        };
        group.visible = false;
        group.position.y = finishFloorY - 8;
        group.scale.set(1, 0.04, 0.04);
        group.frustumCulled = false;
        group.traverse((child) => {
            if (child?.isMesh || child?.isLine || child?.isPoints) child.frustumCulled = false;
        });
        scene.add(group);
        levelFinishGate = group;
        syncLevelFinishGateWidth();
        levelFinishTransition = { elapsed: 0, gateDelay: 0.34, settled: false };
    }

    function syncLevelFinishGateWidth() {
        if (!levelFinishGate?.userData?.finishWidthLayout) return;
        const layout = levelFinishGate.userData.finishWidthLayout;
        const visualRoadMax = isAnimatingLane ? getLaneAnimationCurrentRoadEdgeZ() : roadLimitZMax;
        const visualRoadWidth = Math.max(1, visualRoadMax - roadLimitZMin);
        const targetWidth = Math.max(28, visualRoadWidth + 3.5);
        const widthRatio = targetWidth / Math.max(0.001, layout.baseRoadWidth);

        // Lane expansion grows to the right, so resize and recenter together.
        // Recentring is what removes the one-sided gap seen after 1000 points.
        levelFinishGate.position.z = (roadLimitZMin + visualRoadMax) * 0.5;
        for (const assembly of layout.postAssemblies) {
            assembly.position.z = assembly.userData.finishSide * (targetWidth * 0.5 + 1.55);
        }
        layout.beam.scale.z = (targetWidth + 4.8) / Math.max(0.001, layout.baseRoadWidth + 4.8);
        layout.strip.scale.z = widthRatio;

        // The checker pattern is made from repeated geometry rather than one
        // stretched bitmap, so every square preserves its aspect/UV quality.
        const tileWidth = targetWidth / 12;
        for (const tile of layout.tiles) {
            const col = tile.userData.finishColumn || 0;
            tile.position.z = -targetWidth * 0.5 + tileWidth * (col + 0.5);
            tile.scale.z = tileWidth / Math.max(0.001, layout.baseTileWidth);
        }

        // Keep the sign readable while allowing it to cover the wider gate.
        const targetBannerWidth = Math.min(targetWidth, 42);
        layout.banner.scale.x = targetBannerWidth / Math.max(0.001, layout.baseBannerWidth);
        layout.arrivalGlow.scale.x = widthRatio;
        levelFinishGate.userData.syncedRoadWidth = visualRoadWidth;
        levelFinishGate.userData.syncedFinishWidth = targetWidth;
    }

    function clearLevelMegaJumpCorridor(padX) {
        if (!player) return;
        const minX = player.position.x + 58;
        const maxX = padX + 150;
        for (let index = obstacles.length - 1; index >= 0; index--) {
            const obstacle = obstacles[index];
            if (!obstacle?.position || obstacle.position.x < minX || obstacle.position.x > maxX) continue;
            removeObstacleAt(index);
        }
        for (let index = jumpPads.length - 1; index >= 0; index--) {
            const pad = jumpPads[index];
            if (!pad?.position || pad.position.x < minX || pad.position.x > maxX) continue;
            jumpPads.splice(index, 1);
            disposeNode(pad);
        }
        for (let index = coins.length - 1; index >= 0; index--) {
            const coin = coins[index];
            if (!coin?.position || coin.position.x < minX || coin.position.x > maxX) continue;
            coins.splice(index, 1);
            recycleCoin(coin);
        }
    }

    function stageLevelMegaJumpTransition(info, preservedProgress) {
        if (!player || levelMegaJumpTransition) return;
        const padX = player.position.x + 205;
        clearLevelMegaJumpCorridor(padX);
        // Capture the live world, not a hard-coded/Cyber authoring default. This
        // remains correct if a future special level reaches the pad from Snow,
        // Lava, or a previously transitioned map.
        const sourcePhase = Math.max(0, Math.min(5, Number(gamePhase) || 0));
        const targetPhase = Math.max(0, Math.min(5, Number(info?.targetPhase) || 2));
        const pad = createMegaJumpPad(padX);
        if (pad) {
            pad.userData.levelMidTransition = true;
            pad.userData.levelNumber = Number(info?.level?.number) || 0;
        }
        megaJumpSpawned = true;
        levelMegaJumpTransition = {
            sourcePhase,
            authoredSourcePhase: Number.isFinite(Number(info?.sourcePhase)) ? Number(info.sourcePhase) : sourcePhase,
            targetPhase,
            padX,
            padTriggered: false,
            resumed: false,
            progress: preservedProgress
        };
        // The pre-authored ground rows beyond the pad were removed above.
        // Resume the same deterministic row stream only after the player has
        // landed on Sky, so no Nature-height colliders survive the jump.
        nextLevelPatternX = Number.POSITIVE_INFINITY;
        beginShadowStabilization(MOBILE_RUNTIME ? 4 : 6, 'level-mega-jump-stage');
        updateHudMapLabel(sourcePhase);
    }

    function handleLevelThemeTransition(info) {
        if (!info || currentRunMode !== 'level') return;
        const preservedProgress = Math.max(0, Number(info.progress) || 0);
        if (info.level?.megaJumpTransition && Number(info.targetPhase) === 2) {
            stageLevelMegaJumpTransition(info, preservedProgress);
        } else {
            activateLevelMapPhase(Math.max(0, Math.min(5, Number(info.targetPhase) || 0)), { instant: false });
        }
        if (levelSystem && typeof levelSystem.setScoreBase === 'function') {
            levelSystem.setScoreBase(score - preservedProgress);
        }
        beginShadowStabilization(MOBILE_RUNTIME ? 4 : 6, 'level-theme-transition');
        updateLevelProgressUi();
    }

    function finalizeSuccessfulLevel(completion) {
        if (!completion || levelCompletionInProgress) return;
        levelGhostSystem?.stop();
        levelCompletionInProgress = true;
        finishPlayerFitLevelAttempt('complete');
        if (Math.floor(Number(completion.level?.number) || 0) >= 25) unlockAchievement('level25');
        isGamePaused = true;
        forceEndAllHandSkills(false);
        runStartedFromMenu = false;
        hideHowToPlayOverlay(true);
        if (MOBILE_RUNTIME) setMobileControlsVisible(false);
        ensureElementalAudioSystem()?.invalidateGameplayMusicPlay();
        // Keep the gameplay track alive under the celebration at a low volume.
        // Stopping it here used to race the next-level play() request and left
        // subsequent runs silent on portal builds.
        fadeGameplayMusicVolume((ensureElementalAudioSystem()?.constants.GAMEPLAY_MUSIC_VOLUME || 0.42) * 0.16, 380, false);
        playLevelCompleteFanfare();
        triggerLevelFinishViewmodelCelebration();
        try { if (document.pointerLockElement) document.exitPointerLock(); } catch (e) {}
        menuState.walletCoins = Math.max(0, Math.floor(menuState.walletCoins) || 0)
            + Math.max(0, Math.floor(Number(completion.reward) || 0));
        recordMainMenuRunStats();
        saveMainMenuState();
        updateMainMenuStats();
        requestAnimationFrame(() => maybeBeginHandPurchaseTutorial({
            fromLevelFinish: true,
            levelNumber: completion.level?.number
        }));
        const platform = crazyGamesPlatform();
        if (platform) platform.gameplayStop();
        fortuneWheelSystem?.onLevelCompleted?.(completion);
        const completedNumber = Math.max(0, Math.floor(Number(completion.level?.number) || 0));
        if (completedNumber > 0 && completedNumber < 120) primeCampaignLevelStart(completedNumber + 1);
    }

    function initializeFortuneWheel() {
        if (!fortuneWheelSystem || typeof fortuneWheelSystem.initialize !== 'function') return;
        fortuneWheelSystem.initialize({
            getLanguage: () => normalizeLanguage(menuState.language),
            grantGold: (amount) => {
                menuState.walletCoins = Math.max(0, Math.floor(menuState.walletCoins) || 0)
                    + Math.max(0, Math.floor(Number(amount) || 0));
                saveMainMenuState();
                updateMainMenuStats();
                playWalletTransactionEffect(Math.max(1, Math.floor(Number(amount) || 0)), 'gain');
            },
            onOverlayOpen: () => {
                try { if (document.pointerLockElement) document.exitPointerLock(); } catch (error) {}
                const activePlatform = crazyGamesPlatform();
                if (activePlatform && !mainMenuVisible) activePlatform.gameplayStop();
                playUiConfirmSound();
            },
            onOverlayClose: () => {
                playUiConfirmSound();
                if (lobbyHub?.active && !MOBILE_RUNTIME && requestPointerLockFromUi) {
                    requestPointerLockFromUi({ force: true, allowDisabled: true, lobby: true });
                }
            }
        });
    }

    function initializeLevelSystem() {
        if (!levelSystem || typeof levelSystem.initialize !== 'function') return;
        levelSystem.initialize({
            getLanguage: () => normalizeLanguage(menuState.language),
            getWalletGold: () => Math.max(0, Math.floor(menuState.walletCoins) || 0),
            measure: measurePlayerFit,
            onLevelStart: ({ level, source }) => startPlayerFitLevelAttempt(level, source),
            startLevel: async (levelNumber, startOptions = {}) => {
                unlockGameplayAudioFromUserGesture();
                stopMenuMusicNow();
                playUiConfirmSound();
                // A commercial break between Levels 1 and 2 was placed exactly
                // on the largest Player Fit drop-off. Protect the complete first
                // three-minute onboarding arc; ads begin only at Level 4 and only
                // after three minutes of genuine active play.
                const completedLevel = Math.max(0, Math.floor(Number(levelNumber) || 1) - 1);
                const nextLevelBreak = isPokiBuild()
                    && startOptions?.source === 'next-level'
                    && completedLevel >= 3
                    && playerFitActiveSeconds >= 180;
                if (isPokiBuild() && startOptions?.source === 'next-level' && !nextLevelBreak) {
                    measurePlayerFit('ad-gate', 'next-level', 'deferred-early-session');
                }
                if (!MOBILE_RUNTIME && menuState.mouseControlEnabled && !nextLevelBreak && requestPointerLockFromUi) {
                    // Preserve the trusted button gesture before any asynchronous
                    // map work begins. Pointer lock can remain active beneath the
                    // preparation card, avoiding a redundant second click.
                    focusGameplaySurface();
                    requestPointerLockFromUi({ force: true });
                }
                if (nextLevelBreak) await requestCommercialAd('next_level');
                // Never compile a biome or merge its procedural model library
                // after movement has started. The transition card is painted
                // first, then all CPU/GPU warm work finishes off the live run.
                let waitedForMapPreparation = false;
                try {
                    waitedForMapPreparation = await prepareCampaignLevelStart(levelNumber, { showOverlay: true });
                } catch (error) {
                    // A warm-up failure must not strand the player on a hidden
                    // completion/menu layer. The level can still compile lazily
                    // as the safe fallback used by older builds.
                    console.warn('[CampaignLevelStartFallback]', error);
                }
                const pointerCaptured = !!(renderer && document.pointerLockElement === renderer.domElement);
                const needsPointerRecovery = !MOBILE_RUNTIME
                    && menuState.mouseControlEnabled
                    && (nextLevelBreak || (waitedForMapPreparation && !pointerCaptured));
                beginRunFromMainMenu(true, {
                    level: levelNumber,
                    source: startOptions?.source || 'campaign',
                    deferPointerLock: needsPointerRecovery,
                    startPausedForPointerRecovery: needsPointerRecovery
                });
            },
            openUpgrades: (options = {}) => {
                const fromLevelFinish = options?.fromLevelFinish === true;
                if (!fromLevelFinish) showMainMenu(false);
                else {
                    document.body.classList.add('level-finish-upgrade-open');
                    if (ui.mainMenu) {
                        ui.mainMenu.style.display = 'flex';
                        ui.mainMenu.setAttribute('aria-hidden', 'false');
                    }
                    // Always enter through the Upgrades pane. The first-glove
                    // onboarding then deliberately guides the player to Hands.
                    setUpgradeShopTab('upgrades');
                }
                openMenuDialog(ui.menuUpgradesDialog);
                if (fromLevelFinish && handPurchaseTutorial.active) {
                    advanceHandPurchaseTutorial('upgrades-open');
                }
                playUiConfirmSound();
            },
            showMenu: () => {
                if (handPurchaseTutorial.active || handPurchaseTutorial.pending) abortHandPurchaseTutorial(false);
                showMainMenu(true);
                playUiConfirmSound();
            },
            onFinishArmed: ({ level }) => createLevelFinishGate(level),
            onThemeTransition: handleLevelThemeTransition,
            onLevelComplete: finalizeSuccessfulLevel
        });
    }

    function updateLevelProgressUi() {
        if (!levelSystem || typeof levelSystem.snapshot !== 'function') return false;
        const levelState = levelSystem.snapshot(score);
        if (!levelState.active) return false;
        if (ui.progressFill) ui.progressFill.style.width = `${Math.max(0, Math.min(100, levelState.progress * 100)).toFixed(2)}%`;
        if (ui.progressText) ui.progressText.innerText = `LEVEL ${levelState.number} · ${levelState.progressScore} / ${levelState.targetScore}`;
        return true;
    }

    function beginRunFromMainMenu(resetRun = true, options = {}) {
        if (lobbyHub?.active) lobbyHub.exit();
        document.body.classList.remove('hub-panel-open');
        levelGhostSystem?.stop();
        if (handPurchaseTutorial.active || handPurchaseTutorial.pending) abortHandPurchaseTutorial(false);
        const tutorialRun = !!options.tutorial;
        const preparingGate = tutorialRun && !!options.preparingGate;
        const endlessRun = !!options.endless && !tutorialRun;
        const requestedLevel = Number(options.level)
            || (levelSystem && typeof levelSystem.getSelectedLevel === 'function' ? levelSystem.getSelectedLevel() : 1);
        const startPausedForPointerRecovery = !!options.startPausedForPointerRecovery && !MOBILE_RUNTIME;
        currentRunMode = endlessRun ? 'endless' : 'level';
        // A run may start after the player changed Performance -> Balanced/High.
        // The original deferred queue used to be permanently "complete" in that
        // case, leaving Cyber traffic on the procedural legacy models forever.
        if (shouldRequireDetailedAuxVehicleModels()) requestDetailedAuxVehicleModels();
        if (endlessRun) {
            activeLevelConfig = null;
            levelSystem?.deactivateForEndless?.();
        } else {
            activeLevelConfig = levelSystem && typeof levelSystem.beginRun === 'function'
                ? levelSystem.beginRun({ level: requestedLevel, tutorial: tutorialRun, scoreBase: 0, coins: 0, source: options.source || 'campaign' })
                : null;
        }
        levelCompletionInProgress = false;
        const initialMapPhase = (!tutorialRun && !endlessRun && activeLevelConfig)
            ? Math.max(0, Math.min(5, Math.floor(Number(activeLevelConfig.themePhase) || 0)))
            : 0;
        if (resetRun) resetGame({ startPaused: startPausedForPointerRecovery, skipImmediateRender: true, initialMapPhase });
        if (!tutorialRun && !endlessRun && requestedLevel >= 2) lockGraphicsToHighForCampaign();
        if (!tutorialRun) activateFirstRunRewindProtection();
        hideMainMenu();
        beginShadowStabilization(MOBILE_RUNTIME ? 5 : 7, 'run-start');
        if (tutorialRun) {
            if (!preparingGate) showHowToPlayOverlay(3700, true);
        } else queueHowToPlayOverlay();
        runStartedFromMenu = !preparingGate;
        if (!tutorialRun && !endlessRun) {
            applyActiveLevelTheme();
            if (activeLevelConfig && player && scene) {
                levelGhostSystem?.start(THREE, scene, activeLevelConfig, player.position.x, worldScrollX, getActiveRoadFloorY());
            }
        } else if (tutorialRun && activeLevelConfig && curvedPathSystem && typeof curvedPathSystem.configure === 'function') {
            curvedPathSystem.configure(activeLevelConfig);
        }
        else if (endlessRun && curvedPathSystem && typeof curvedPathSystem.configure === 'function') {
            curvedPathSystem.configure({ curveEnabled: true, curveDirection: -1, curveStrength: 1 });
        }
        else if (curvedPathSystem && typeof curvedPathSystem.clear === 'function') curvedPathSystem.clear();
        updateCurvedLaneGuides();
        curvedLaneGuideAnchorVirtualX = Math.floor(((player?.position.x || 0) + worldScrollX - 36) / 18) * 18;
        updateCurvedLaneGuides();
        if (preparingGate) {
            isGamePaused = true;
            if (ui.pauseScreen) ui.pauseScreen.style.display = 'none';
            updateMobileControlsVisibility();
            return;
        }
        menuState.runCount += 1;
        saveMainMenuState();
        updateMainMenuStats();
        const platform = crazyGamesPlatform();
        if (platform) {
            platform.setContext({ mode: currentRunMode === 'level' ? `level-${requestedLevel}` : 'endless-runner', map: getPhaseName(gamePhase), score: String(Math.floor(score)) });
            if (!startPausedForPointerRecovery) platform.gameplayStart();
        }
        // Defer non-critical detailed vehicle GLBs until the player has entered
        // actual gameplay. This keeps the CrazyGames SDK loading window focused
        // on the tutorial's playable core while preserving detailed cars,
        // motorcycles and trains during the run.
        scheduleVehicleModelLoads();
        if (!tutorialRun && !endlessRun) primeActiveLevelCourse();
        isGamePaused = startPausedForPointerRecovery;
        if (startPausedForPointerRecovery) {
            pointerLockRecoveryPending = true;
            pointerLockRecoveryReason = 'commercial-break-finished';
            if (ui.pauseScreen) ui.pauseScreen.style.display = 'flex';
            setPauseOverlay(tr('tapToStart').toLocaleUpperCase(), tr('pauseHint'));
        } else if (ui.pauseScreen) ui.pauseScreen.style.display = 'none';
        if (MOBILE_RUNTIME) {
            resumeMobileRun();
            return;
        }
        if (!options.deferPointerLock && requestPointerLockFromUi) {
            // This path is invoked directly from the first keyboard/pointer
            // gesture. Never defer it: portal iframes revoke pointer-lock
            // permission as soon as the gesture task has completed.
            requestPointerLockFromUi({ force: true });
        }
    }

    function requestShadowMapRefresh(xPos = null, force = false) {
        graphicsEngine.requestShadowMapRefresh(xPos, force);
    }

    function beginShadowStabilization(frames = 5, reason = 'scene-change') {
        shadowStabilizationFrames = Math.max(shadowStabilizationFrames, Math.max(1, Math.floor(frames)));
        shadowStabilizationReason = reason;
        shadowRefreshFrame = 0;
        shadowRefreshCooldown = 0;
        pendingShadowRefreshX = Number.POSITIVE_INFINITY;
        if (renderer && renderer.shadowMap && renderer.shadowMap.enabled) {
            renderer.shadowMap.needsUpdate = true;
        }
    }

    function isNearbyMovingCityShadowCaster(obstacle) {
        if (!obstacle || !obstacle.visible || !obstacle.userData || !player) return false;
        const type = obstacle.userData.type;
        if (type !== 'vehicle' && type !== 'motorcycle' && type !== 'train' && type !== 'tutorial_vehicle') return false;
        if (!Number.isFinite(obstacle.userData.speedX) || Math.abs(obstacle.userData.speedX) < 0.001) return false;
        const distance = obstacle.position.x - player.position.x;
        return distance >= -35 && distance <= 210;
    }

    function updateNearbyMovingShadowState(delta) {
        nearbyMovingShadowType = '';
        if (gamePhase === 0) {
            const movingCaster = obstacles.find(isNearbyMovingCityShadowCaster);
            if (movingCaster) {
                nearbyMovingShadowHold = MOVING_SHADOW_HOLD_SECONDS;
                nearbyMovingShadowType = movingCaster.userData.type;
                return;
            }
        }
        nearbyMovingShadowHold = Math.max(0, nearbyMovingShadowHold - Math.max(0, delta || 0));
    }

    function getShadowRefreshInterval() {
        if (!shouldRenderDynamicShadows()) return Number.POSITIVE_INFINITY;
        // Cars, motorcycles and moving trains cross the road quickly. Reusing a
        // shadow texture for several frames made their silhouettes jump into
        // the asphalt as a one-frame dark slab. Refresh only while one is near;
        // static stretches keep the cheaper cadence.
        if (nearbyMovingShadowHold > 0) {
            // Four tutorial cars share the screen. A 30 Hz shadow update is
            // visually smooth with PCF filtering and halves their opening cost.
            if (nearbyMovingShadowType === 'tutorial_vehicle') return MOBILE_RUNTIME ? 3 : 2;
            return MOBILE_RUNTIME ? 2 : 1;
        }
        const quality = getEffectiveGraphicsQualityName();
        const curvedWorldActive = !!curvedPathSystem?.enabled && curvedPathSystem.strength > 0;
        if (curvedWorldActive) {
            const curveTransitioning = Math.abs(
                (Number(curvedPathSystem.targetDirection) || 0)
                - (Number(curvedPathSystem.direction) || 0)
            ) > 0.002;
            // Colour/depth shaders and the CPU-deformed road must sample the
            // same recent shadow atlas while the world curve is blending.
            if (curveTransitioning && !MOBILE_RUNTIME && !RUNTIME_LOW_POWER
                && (quality === 'high' || quality === 'ultra')) return 1;
            return MOBILE_RUNTIME || RUNTIME_LOW_POWER ? 3 : 2;
        }
        let interval = quality === 'ultra' ? 2 : (quality === 'high' ? 4 : 6);
        if (MOBILE_RUNTIME) interval += 2;
        if (RUNTIME_LOW_POWER) interval += 2;
        interval += graphicsState.performanceLevel * 3;
        if (smoothedFps < 48) interval += 2;
        return interval;
    }

    function updateShadowRefreshQueue(delta) {
        if (!(renderer && renderer.shadowMap && renderer.shadowMap.enabled) || !player) return;
        const continuousUpdates = shouldContinuouslyUpdateDynamicShadows();
        if (renderer.shadowMap.autoUpdate !== continuousUpdates) {
            renderer.shadowMap.autoUpdate = continuousUpdates;
            renderer.shadowMap.needsUpdate = true;
            shadowRefreshFrame = 0;
            shadowRefreshCooldown = 0;
            pendingShadowRefreshX = Number.POSITIVE_INFINITY;
        }
        updateNearbyMovingShadowState(delta);
        if (continuousUpdates) {
            // Retained as a safe fallback if a future platform explicitly opts
            // into continuous shadows. Current browser presets use the bounded
            // manual scheduler on every device.
            shadowStabilizationFrames = 0;
            shadowStabilizationReason = '';
            return;
        }
        if (shadowStabilizationFrames > 0) {
            // A fresh run rebuilds/pools many casters before its first visible
            // frame. Refresh a short, bounded series after every world update
            // so no stale first-run silhouette can survive on the road.
            renderer.shadowMap.needsUpdate = true;
            shadowStabilizationFrames -= 1;
            shadowRefreshFrame = 0;
            shadowRefreshCooldown = 0;
            if (shadowStabilizationFrames === 0) shadowStabilizationReason = '';
            return;
        }
        if (shadowRefreshCooldown > 0) {
            shadowRefreshCooldown = Math.max(0, shadowRefreshCooldown - delta);
        }
        shadowRefreshFrame += 1;
        const interval = getShadowRefreshInterval();
        const cadenceDue = Number.isFinite(interval) && shadowRefreshFrame >= interval;
        const flushAhead = Math.min(180, adaptiveRenderDistance * 0.22);
        const queuedDue = Number.isFinite(pendingShadowRefreshX)
            && pendingShadowRefreshX <= player.position.x + flushAhead;
        if (shadowRefreshCooldown <= 0 && (cadenceDue || queuedDue)) {
            renderer.shadowMap.needsUpdate = true;
            shadowRefreshFrame = 0;
            pendingShadowRefreshX = Number.POSITIVE_INFINITY;
            shadowRefreshCooldown = cadenceDue ? 0 : 0.06;
        }
    }

    function isPoolableObstacleType(type) {
        return !!obstaclePool[type];
    }

    function acquirePooledObstacle(type, factory) {
        const pool = obstaclePool[type];
        if (pool && pool.length > 0) {
            const obs = pool.pop();
            if (obs.userData) {
                delete obs.userData.levelFinishDissolve;
                delete obs.userData.tutorial;
                delete obs.userData.tutorialLesson;
                delete obs.userData.tutorialSequence;
                delete obs.userData.tutorialRewindId;
                delete obs.userData.tutorialSpawnedAt;
                delete obs.userData.tutorialRow;
            }
            obs.visible = true;
            obs.rotation.set(0, 0, 0);
            obs.scale.set(1, 1, 1);
            setObjectOpacity(obs, 1);
            obs.traverse((child) => {
                child.visible = true;
            });
            return obs;
        }
        return factory();
    }

    function recycleOrDisposeObstacle(obs) {
        if (!obs) return;
        if (obs.userData) delete obs.userData.levelFinishDissolve;
        const type = obs.userData && obs.userData.type;
        if (isPoolableObstacleType(type)) {
            if (obs.parent) obs.parent.remove(obs);
            obs.visible = false;
            obs.position.set(-99999, -99999, -99999);
            obs.rotation.set(0, 0, 0);
            setObjectOpacity(obs, 1);
            obstaclePool[type].push(obs);
        } else {
            disposeNode(obs);
        }
    }

    function removeObstacleAt(index) {
        const obs = obstacles[index];
        if (!obs) return;
        obstacles.splice(index, 1);
        recycleOrDisposeObstacle(obs);
        requestShadowMapRefresh();
    }

    function clearObstacleCollection() {
        for (let i = 0; i < obstacles.length; i++) {
            recycleOrDisposeObstacle(obstacles[i]);
        }
        obstacles = [];
        requestShadowMapRefresh();
    }

    function clearReviveDangerZone() {
        if (!player) return;
        const playerX = player.position.x;
        for (let i = obstacles.length - 1; i >= 0; i--) {
            const obstacle = obstacles[i];
            if (!obstacle || !obstacle.position) continue;
            // A Mega Jump pad is progression infrastructure, not a hazard.
            // Removing it leaves megaJumpSpawned=true and makes the transition
            // permanently unreachable after respawn.
            if (obstacle.userData?.type === 'mega_jump_pad') continue;
            const dx = obstacle.position.x - playerX;
            if (dx > -REVIVE_DANGER_BEHIND && dx < REVIVE_DANGER_AHEAD) removeObstacleAt(i);
        }
    }

    function cloneReviveFadeMaterials(obstacle) {
        const bindings = [];
        if (!obstacle || !obstacle.traverse) return bindings;
        obstacle.traverse((child) => {
            if (!child.isMesh || !child.material) return;
            const original = child.material;
            if (Array.isArray(child.material)) {
                child.material = child.material.map((material) => material && material.clone ? material.clone() : material);
            } else if (child.material.clone) {
                child.material = child.material.clone();
            }
            if (child.material !== original) {
                const transientOwned = Array.isArray(child.material)
                    ? child.material.filter((material, index) => material && material !== original[index])
                    : [child.material];
                bindings.push({ child, original, transientOwned });
            }
        });
        return bindings;
    }

    function restoreReviveFadeMaterials(entry) {
        if (!entry || !entry.materialBindings) return;
        entry.materialBindings.forEach(({ child, original, transientOwned }) => {
            if (!child) return;
            child.material = original;
            transientOwned.forEach((material) => {
                // Material klonlarını serbest bırak; paylaşılan texture'ları dispose etme.
                if (material && material.dispose) material.dispose();
            });
        });
        entry.materialBindings = [];
    }

    function prepareReviveDangerZone() {
        if (!player) return [];
        const playerX = player.position.x;
        const entries = [];
        obstacles.forEach((obstacle) => {
            if (!obstacle || !obstacle.position) return;
            if (obstacle.userData?.type === 'mega_jump_pad') return;
            const dx = obstacle.position.x - playerX;
            if (dx <= -REVIVE_DANGER_BEHIND || dx >= REVIVE_DANGER_AHEAD) return;
            const materialBindings = cloneReviveFadeMaterials(obstacle);
            entries.push({
                obstacle,
                distance: Math.abs(dx),
                baseY: obstacle.position.y,
                baseScale: obstacle.scale.clone(),
                materialBindings,
                delay: 0,
                burstPlayed: false
            });
        });
        entries.sort((a, b) => a.distance - b.distance);
        entries.forEach((entry, index) => {
            entry.delay = Math.min(0.24, index * 0.025 + Math.min(0.08, entry.distance / 2600));
        });
        return entries;
    }

    function animateReviveDangerZone(sequenceTime) {
        if (!reviveClearingObstacles.length) return;
        for (let i = reviveClearingObstacles.length - 1; i >= 0; i--) {
            const entry = reviveClearingObstacles[i];
            const obstacle = entry.obstacle;
            if (!obstacle || !obstacles.includes(obstacle)) {
                reviveClearingObstacles.splice(i, 1);
                continue;
            }
            const localTime = sequenceTime - REVIVE_CLEAR_START - entry.delay;
            if (localTime <= 0) continue;
            const progress = Math.min(1, localTime / REVIVE_CLEAR_DURATION);
            const eased = 1 - Math.pow(1 - progress, 3);
            setObjectOpacity(obstacle, Math.max(0, 1 - eased));
            obstacle.scale.set(
                entry.baseScale.x * (1 - eased * 0.16),
                entry.baseScale.y * (1 - eased * 0.16),
                entry.baseScale.z * (1 - eased * 0.16)
            );
            obstacle.position.y = entry.baseY + eased * (1.4 + Math.min(2.4, entry.distance * 0.012));
            if (!entry.burstPlayed && progress >= 0.34) {
                entry.burstPlayed = true;
                if (i < 10) {
                    spawnGlobalExplosion(obstacle.position.x, obstacle.position.y, obstacle.position.z, 0xff789c, 10);
                }
            }
            if (progress >= 1) {
                restoreReviveFadeMaterials(entry);
                const obstacleIndex = obstacles.indexOf(obstacle);
                if (obstacleIndex >= 0) removeObstacleAt(obstacleIndex);
                reviveClearingObstacles.splice(i, 1);
            }
        }
    }

    function retriggerReviveBeatAnimation() {
        const overlay = ui.reviveSequence;
        if (!overlay) return;
        overlay.classList.remove('is-beat');
        void overlay.offsetWidth;
        overlay.classList.add('is-beat');
    }

    // Diriliş surge'ü — ÖZGÜN sentez, asset yok (time-stop/magnet ile aynı yaklaşım; telifsiz).
    // Üç katman: (1) yükselen sweep = "geri dönüş", (2) parlak akor = kurtuluş vurgusu,
    // (3) ters-zarflı gürültü "nefes" = doruk öncesi çekiş. Kalp atışıyla çakışmasın diye
    // sub-bas bölgesinden uzak durur (sweep 140Hz'den başlar).
    function playReviveSurge() {
        if (!audioContext || audioContext.state !== 'running' || menuState.muted) return;
        const output = sfxGain || masterGain || audioContext.destination;
        const t0 = audioContext.currentTime;

        // (1) yükselen sweep + açılan lowpass
        const sweep = audioContext.createOscillator();
        const sweepGain = audioContext.createGain();
        const sweepLp = audioContext.createBiquadFilter();
        sweep.type = 'sawtooth';
        sweep.frequency.setValueAtTime(140, t0);
        sweep.frequency.exponentialRampToValueAtTime(880, t0 + 0.42);
        sweepLp.type = 'lowpass';
        sweepLp.frequency.setValueAtTime(320, t0);
        sweepLp.frequency.exponentialRampToValueAtTime(4200, t0 + 0.42);
        sweepLp.Q.value = 3.2;
        sweepGain.gain.setValueAtTime(0.0001, t0);
        sweepGain.gain.exponentialRampToValueAtTime(0.15, t0 + 0.30);
        sweepGain.gain.exponentialRampToValueAtTime(0.0001, t0 + 0.72);
        sweep.connect(sweepLp).connect(sweepGain).connect(output);
        sweep.start(t0);
        sweep.stop(t0 + 0.75);

        // (2) parlak akor (A5 + E6 + A6) sweep'in tepesinde patlar
        [880, 1318.5, 1760].forEach((f, i) => {
            const t = t0 + 0.34 + i * 0.035;
            const osc = audioContext.createOscillator();
            const g = audioContext.createGain();
            osc.type = 'triangle';
            osc.frequency.setValueAtTime(f, t);
            g.gain.setValueAtTime(0.0, t);
            g.gain.linearRampToValueAtTime(0.085 - i * 0.018, t + 0.03);
            g.gain.exponentialRampToValueAtTime(0.0008, t + 0.85);
            osc.connect(g).connect(output);
            osc.start(t);
            osc.stop(t + 0.9);
        });

        // (3) ters-zarflı gürültü: sese doğru "çekilen nefes"
        const len = Math.floor(audioContext.sampleRate * 0.38);
        const buf = audioContext.createBuffer(1, len, audioContext.sampleRate);
        const data = buf.getChannelData(0);
        for (let i = 0; i < len; i++) data[i] = (Math.random() * 2 - 1) * Math.pow(i / len, 2.2);
        const noise = audioContext.createBufferSource();
        const nf = audioContext.createBiquadFilter();
        const ng = audioContext.createGain();
        noise.buffer = buf;
        nf.type = 'bandpass';
        nf.frequency.setValueAtTime(600, t0);
        nf.frequency.exponentialRampToValueAtTime(2600, t0 + 0.38);
        nf.Q.value = 0.8;
        ng.gain.value = 0.10;
        noise.connect(nf).connect(ng).connect(output);
        noise.start(t0);
        noise.stop(t0 + 0.4);
    }

    function playReviveHeartbeat(intensity = 1) {
        if (!audioContext || audioContext.state !== 'running' || menuState.muted) return;
        const output = sfxGain || masterGain || audioContext.destination;
        const now = audioContext.currentTime;
        [0, 0.115].forEach((offset, index) => {
            const time = now + offset;
            const osc = audioContext.createOscillator();
            const body = audioContext.createGain();
            const lowpass = audioContext.createBiquadFilter();
            osc.type = index === 0 ? 'sine' : 'triangle';
            osc.frequency.setValueAtTime((index === 0 ? 64 : 52) + intensity * 4, time);
            osc.frequency.exponentialRampToValueAtTime(index === 0 ? 38 : 34, time + 0.2);
            lowpass.type = 'lowpass';
            lowpass.frequency.value = 125;
            lowpass.Q.value = 1.4;
            body.gain.setValueAtTime(0.0001, time);
            body.gain.exponentialRampToValueAtTime((index === 0 ? 0.2 : 0.11) * intensity, time + 0.018);
            body.gain.exponentialRampToValueAtTime(0.0001, time + (index === 0 ? 0.25 : 0.19));
            osc.connect(lowpass).connect(body).connect(output);
            osc.start(time);
            osc.stop(time + 0.28);
        });

        const noise = audioContext.createBufferSource();
        const noiseFilter = audioContext.createBiquadFilter();
        const noiseGain = audioContext.createGain();
        noise.buffer = getNoiseBuffer(0.16);
        noiseFilter.type = 'lowpass';
        noiseFilter.frequency.value = 92;
        noiseGain.gain.setValueAtTime(0.035 * intensity, now);
        noiseGain.gain.exponentialRampToValueAtTime(0.0001, now + 0.15);
        noise.connect(noiseFilter).connect(noiseGain).connect(output);
        noise.start(now);
        noise.stop(now + 0.16);
    }

    function playReviveImpactSound() {
        if (!audioContext || audioContext.state !== 'running' || menuState.muted) return;
        const now = audioContext.currentTime;
        const output = sfxGain || masterGain || audioContext.destination;
        const noise = audioContext.createBufferSource();
        const filter = audioContext.createBiquadFilter();
        const gain = audioContext.createGain();
        noise.buffer = getNoiseBuffer(0.52);
        filter.type = 'lowpass';
        filter.frequency.setValueAtTime(520, now);
        filter.frequency.exponentialRampToValueAtTime(90, now + 0.46);
        gain.gain.setValueAtTime(0.16, now);
        gain.gain.exponentialRampToValueAtTime(0.0001, now + 0.5);
        noise.connect(filter).connect(gain).connect(output);
        noise.start(now);
        noise.stop(now + 0.52);
    }

    function playReviveReleaseSound() {
        if (!audioContext || audioContext.state !== 'running' || menuState.muted) return;
        const now = audioContext.currentTime;
        const output = sfxGain || masterGain || audioContext.destination;
        [174.61, 261.63, 392.0, 523.25].forEach((frequency, index) => {
            const time = now + index * 0.055;
            const osc = audioContext.createOscillator();
            const gain = audioContext.createGain();
            osc.type = index < 2 ? 'triangle' : 'sine';
            osc.frequency.setValueAtTime(frequency, time);
            osc.frequency.linearRampToValueAtTime(frequency * 1.035, time + 0.48);
            gain.gain.setValueAtTime(0.0001, time);
            gain.gain.exponentialRampToValueAtTime(0.07, time + 0.025);
            gain.gain.exponentialRampToValueAtTime(0.0001, time + 0.7);
            osc.connect(gain).connect(output);
            osc.start(time);
            osc.stop(time + 0.74);
        });
    }

    function resetReviveSequenceState() {
        reviveClearingObstacles.forEach(restoreReviveFadeMaterials);
        reviveSequenceActive = false;
        reviveMusicHold = false;
        reviveSequenceTime = 0;
        reviveBeatIndex = 0;
        reviveSurgePlayed = false;
        reviveClearingObstacles = [];
        isDying = false;
        if (reviveOverlayCleanupTimer) {
            clearTimeout(reviveOverlayCleanupTimer);
            reviveOverlayCleanupTimer = null;
        }
        if (camera) {
            camera.fov = reviveBaseCameraFov || currentFov || 85;
            camera.rotation.z = reviveBaseCameraRoll || 0;
            camera.updateProjectionMatrix();
        }
        document.body.classList.remove('revive-sequence-active');
        if (ui.reviveSequence) {
            ui.reviveSequence.className = '';
            ui.reviveSequence.setAttribute('aria-hidden', 'true');
            ui.reviveSequence.style.setProperty('--revive-gray', '0');
            ui.reviveSequence.style.setProperty('--revive-glow', '0');
        }
    }

    function finishReviveSequence(options = {}) {
        const instant = !!options.instant;
        const skipReleaseSound = !!options.skipReleaseSound;
        reviveClearingObstacles.forEach(restoreReviveFadeMaterials);
        clearReviveDangerZone();
        reviveClearingObstacles = [];
        player.position.y = Math.max(player.position.y, (onSkyLayer ? SKY_LAYER_Y : 0) + normalHeight / 2);
        playerVelocityY = Math.max(playerVelocityY, 0.14);
        currentStrafeVelocity *= 0.2;
        trafficSpeedPenalty = Math.max(trafficSpeedPenalty, 0.08);
        activateReviveShield();
        spawnGlobalExplosion(player.position.x, player.position.y, player.position.z, 0x8ff5ff, 64);
        if (!skipReleaseSound) playReviveReleaseSound();
        reviveSequenceActive = false;
        isDying = false;
        if (pointerLockRecoveryPending && !MOBILE_RUNTIME) {
            isGamePaused = true;
            if (ui.pauseScreen) ui.pauseScreen.style.display = 'flex';
            setPauseOverlay(tr('tapToStart').toLocaleUpperCase(), tr('pauseHint'));
        }
        const platform = crazyGamesPlatform();
        if (platform && !isGamePaused && !isGameOver && !pointerLockRecoveryPending) platform.gameplayStart();
        if (camera) {
            camera.fov = reviveBaseCameraFov;
            camera.rotation.z = reviveBaseCameraRoll;
            camera.updateProjectionMatrix();
        }
        if (instant) {
            if (reviveOverlayCleanupTimer) clearTimeout(reviveOverlayCleanupTimer);
            reviveOverlayCleanupTimer = null;
            document.body.classList.remove('revive-sequence-active');
            if (ui.reviveSequence) {
                ui.reviveSequence.className = '';
                ui.reviveSequence.setAttribute('aria-hidden', 'true');
                ui.reviveSequence.style.setProperty('--revive-gray', '0');
                ui.reviveSequence.style.setProperty('--revive-glow', '0');
            }
            reviveMusicHold = false;
            updateGameplayMusic(true);
        } else {
            if (ui.reviveSequence) {
                ui.reviveSequence.classList.add('is-restoring', 'is-exiting');
                ui.reviveSequence.style.setProperty('--revive-gray', '0');
            }
            reviveOverlayCleanupTimer = setTimeout(() => {
                document.body.classList.remove('revive-sequence-active');
                if (ui.reviveSequence) {
                    ui.reviveSequence.className = '';
                    ui.reviveSequence.setAttribute('aria-hidden', 'true');
                }
                reviveMusicHold = false;
                updateGameplayMusic(true);
                reviveOverlayCleanupTimer = null;
            }, 360);
        }
    }

    function updateReviveSequence(realDelta) {
        if (!reviveSequenceActive) return;
        reviveSequenceTime = Math.min(REVIVE_SEQUENCE_DURATION, reviveSequenceTime + Math.min(0.05, realDelta));
        const progress = Math.min(1, reviveSequenceTime / REVIVE_SEQUENCE_DURATION);
        const gray = reviveSequenceTime < 0.18
            ? reviveSequenceTime / 0.18
            : (reviveSequenceTime < 1.9 ? 1 : Math.max(0, 1 - (reviveSequenceTime - 1.9) / (REVIVE_SEQUENCE_DURATION - 1.9)));
        const glow = Math.max(0, Math.sin(progress * Math.PI)) * 0.75 + progress * 0.25;
        if (ui.reviveSequence) {
            ui.reviveSequence.style.setProperty('--revive-gray', gray.toFixed(3));
            ui.reviveSequence.style.setProperty('--revive-glow', glow.toFixed(3));
            if (reviveSequenceTime >= REVIVE_CLEAR_START) ui.reviveSequence.classList.add('is-clearing');
            if (reviveSequenceTime >= 1.74) ui.reviveSequence.classList.add('is-restoring');
        }
        while (reviveBeatIndex < REVIVE_BEAT_TIMES.length && reviveSequenceTime >= REVIVE_BEAT_TIMES[reviveBeatIndex]) {
            const intensity = 0.78 + reviveBeatIndex * 0.075;
            playReviveHeartbeat(intensity);
            retriggerReviveBeatAnimation();
            reviveBeatIndex++;
        }
        // Renk geri gelirken (is-restoring) surge — görselle aynı ANDA olması şart, yoksa
        // ses efekt kopuk hissettirir.
        if (!reviveSurgePlayed && reviveSequenceTime >= REVIVE_SURGE_TIME) {
            reviveSurgePlayed = true;
            playReviveSurge();
        }
        animateReviveDangerZone(reviveSequenceTime);
        if (camera) {
            const impact = Math.exp(-reviveSequenceTime * 3.2);
            camera.fov = reviveBaseCameraFov - gray * 4.6 + Math.sin(reviveSequenceTime * 23) * impact * 1.8;
            camera.rotation.z = reviveBaseCameraRoll + Math.sin(reviveSequenceTime * 34) * impact * 0.009;
            camera.updateProjectionMatrix();
        }
        if (reviveSequenceTime >= REVIVE_SEQUENCE_DURATION) finishReviveSequence();
    }

    function activateReviveShield() {
        shieldActive = true;
        shieldTimer = REVIVE_SHIELD_DURATION;
        if (ui.shieldBar) ui.shieldBar.style.display = 'block';
        if (ui.shieldTime) ui.shieldTime.innerText = shieldTimer.toFixed(1);
        if (ui.speedVignette) ui.speedVignette.classList.add('shield-active-vignette');
    }

    function startReviveSequence(options = {}) {
        const consumeUpgrade = options.consumeUpgrade !== false;
        if (reviveSequenceActive || isGameOver || !player) return false;
        if (consumeUpgrade && (!hasReviveUpgrade() || !reviveAvailable || reviveUsedThisRun)) return false;
        // Rewarded ads may release pointer lock, which can briefly open the
        // pause screen. A revive is its own cinematic state: keep only the
        // heartbeat/heart treatment visible and resume simulation immediately.
        isGamePaused = false;
        closePauseSettingsPanel();
        if (ui.pauseScreen) ui.pauseScreen.style.display = 'none';
        unlockAchievement('useRevive');
        if (consumeUpgrade) {
            reviveAvailable = false;
            reviveUsedThisRun = true;
        }
        reviveSequenceActive = true;
        reviveMusicHold = true;
        reviveSequenceTime = 0;
        reviveBeatIndex = 0;
        reviveSurgePlayed = false;
        isDying = true;
        mainMenuVisible = false;
        middleMouseHeld = false;
        forceEndTimeSlow();
        forceEndMagnet();
        resetControlActionState();
        wheelSkillTapCount = 0;
        jumpQueue = false;
        jumpQueueTimer = 0;
        isSlamming = false;
        doubleJumpUsedInAir = false;
        resetGlideTimer();
        setGlideWindActive(false);
        updateDoubleJumpCooldownUi(true);
        document.body.classList.remove('game-over-active');
        if (isSliding) {
            isSliding = false;
            slideTimer = 0;
            document.body.classList.remove('sliding');
            player.position.y += (normalHeight - slideHeight) / 2;
            currentCameraHeight = normalHeight;
        }
        reviveClearingObstacles = prepareReviveDangerZone();
        reviveBaseCameraFov = camera ? camera.fov : (currentFov || 85);
        reviveBaseCameraRoll = camera ? camera.rotation.z : 0;
        document.body.classList.add('revive-sequence-active');
        if (ui.reviveSequence) {
            ui.reviveSequence.className = 'is-active';
            ui.reviveSequence.setAttribute('aria-hidden', 'false');
            ui.reviveSequence.style.setProperty('--revive-gray', '0');
            ui.reviveSequence.style.setProperty('--revive-glow', '0');
        }
        stopGameplayMusicNow();
        spawnGlobalExplosion(player.position.x, player.position.y, player.position.z, 0xff486f, 24);
        playReviveImpactSound();
        return true;
    }

    function tryUseRevive() {
        return startReviveSequence({ consumeUpgrade: true });
    }

    let gameOverStatAnim = null;
    let gameOverStatTimers = [];

    function clearGameOverCelebration() {
        if (gameOverStatAnim) { cancelAnimationFrame(gameOverStatAnim); gameOverStatAnim = null; }
        gameOverStatTimers.forEach((t) => clearTimeout(t));
        gameOverStatTimers = [];
        if (ui.gameOver) ui.gameOver.classList.remove('is-new-record', 'is-counting', 'stat-pop');
        if (ui.gameOverConfetti) ui.gameOverConfetti.innerHTML = '';
        if (ui.gameOverRecordBadge) ui.gameOverRecordBadge.style.display = 'none';
    }

    // Skor/altın 0'dan gerçek değere sayılır; eski rekoru geçtiği anda kutlama tetiklenir.
    function showGameOverStats(finalScoreVal, finalCoinsVal, prevBest) {
        clearGameOverCelebration();
        const beatsRecord = finalScoreVal > prevBest && prevBest > 0;
        const fmt = (v) => Math.floor(v).toLocaleString('tr-TR');
        if (ui.gameOverRecordText) ui.gameOverRecordText.innerText = newRecordName();
        if (ui.gameOver) ui.gameOver.classList.add('is-counting');
        const duration = 1250;
        const start = performance.now();
        let celebrated = false;
        const tick = (now) => {
            const t = Math.min(1, (now - start) / duration);
            const eased = 1 - Math.pow(1 - t, 3); // ease-out cubic
            const curScore = finalScoreVal * eased;
            if (ui.finalScore) ui.finalScore.innerText = fmt(curScore);
            if (ui.finalCoins) ui.finalCoins.innerText = fmt(finalCoinsVal * eased);
            if (!celebrated && beatsRecord && curScore >= prevBest) {
                celebrated = true;
                triggerNewRecordCelebration();
            }
            if (t < 1) {
                gameOverStatAnim = requestAnimationFrame(tick);
            } else {
                gameOverStatAnim = null;
                if (ui.finalScore) ui.finalScore.innerText = fmt(finalScoreVal);
                if (ui.finalCoins) ui.finalCoins.innerText = fmt(finalCoinsVal);
                if (ui.gameOver) {
                    ui.gameOver.classList.remove('is-counting');
                    ui.gameOver.classList.add('stat-pop');
                    gameOverStatTimers.push(setTimeout(() => { if (ui.gameOver) ui.gameOver.classList.remove('stat-pop'); }, 500));
                }
            }
        };
        gameOverStatAnim = requestAnimationFrame(tick);
    }

    function triggerNewRecordCelebration() {
        if (ui.gameOver) ui.gameOver.classList.add('is-new-record');
        if (ui.gameOverRecordBadge) ui.gameOverRecordBadge.style.display = 'flex';
        spawnGameOverConfetti(40);
        // ikinci konfeti dalgası
        gameOverStatTimers.push(setTimeout(() => spawnGameOverConfetti(28), 450));
        try { playRecordFanfare(); } catch (e) {}
    }

    function spawnGameOverConfetti(count) {
        const layer = ui.gameOverConfetti;
        if (!layer) return;
        const colors = ['#ffd24a', '#ff7ac0', '#5ed0ff', '#8dffb0', '#c79bff', '#fff1b0'];
        const frag = document.createDocumentFragment();
        for (let i = 0; i < count; i++) {
            const piece = document.createElement('div');
            piece.className = 'confetti-piece';
            const left = Math.random() * 100;
            const drift = (Math.random() * 2 - 1) * 120;
            const fall = 240 + Math.random() * 260;
            const dur = 1.6 + Math.random() * 1.3;
            const delay = Math.random() * 0.35;
            const spin = (Math.random() * 2 - 1) * 900;
            piece.style.left = left + '%';
            piece.style.background = colors[(Math.random() * colors.length) | 0];
            piece.style.setProperty('--drift', drift.toFixed(0) + 'px');
            piece.style.setProperty('--fall', fall.toFixed(0) + 'px');
            piece.style.setProperty('--dur', dur.toFixed(2) + 's');
            piece.style.setProperty('--delay', delay.toFixed(2) + 's');
            piece.style.setProperty('--spin', spin.toFixed(0) + 'deg');
            if (Math.random() < 0.4) piece.style.borderRadius = '50%';
            frag.appendChild(piece);
        }
        layer.appendChild(frag);
        // temizle (en uzun süre + gecikme sonrası)
        gameOverStatTimers.push(setTimeout(() => { if (layer) layer.innerHTML = ''; }, 3600));
    }

    // Zafer fanfarı — özgün sentez, yükselen majör arpej + shimmer.
    function playRecordFanfare() {
        if (!audioContext || audioContext.state !== 'running') { if (audioContext && audioContext.state === 'suspended') audioContext.resume(); }
        if (!audioContext || audioContext.state !== 'running') return;
        const t0 = audioContext.currentTime;
        const notes = [523.25, 659.25, 783.99, 1046.5]; // C5 E5 G5 C6
        notes.forEach((f, i) => {
            const t = t0 + i * 0.11;
            const osc = audioContext.createOscillator();
            const gain = audioContext.createGain();
            osc.type = 'triangle';
            osc.frequency.setValueAtTime(f, t);
            gain.gain.setValueAtTime(0.0, t);
            gain.gain.linearRampToValueAtTime(0.16, t + 0.03);
            gain.gain.exponentialRampToValueAtTime(0.008, t + 0.5);
            osc.connect(gain).connect(sfxGain || masterGain);
            osc.start(t);
            osc.stop(t + 0.55);
        });
        // final shimmer akoru
        const tc = t0 + notes.length * 0.11;
        [1046.5, 1318.5, 1568.0].forEach((f) => {
            const osc = audioContext.createOscillator();
            const gain = audioContext.createGain();
            osc.type = 'sine';
            osc.frequency.setValueAtTime(f, tc);
            gain.gain.setValueAtTime(0.0, tc);
            gain.gain.linearRampToValueAtTime(0.09, tc + 0.04);
            gain.gain.exponentialRampToValueAtTime(0.006, tc + 0.9);
            osc.connect(gain).connect(sfxGain || masterGain);
            osc.start(tc);
            osc.stop(tc + 0.95);
        });
    }

    function hideRewardedContinueOverlay() {
        if (rewardedDeathOfferTimer) clearTimeout(rewardedDeathOfferTimer);
        rewardedDeathOfferTimer = null;
        rewardedDeathOfferReady = false;
        document.body.classList.remove('rewarded-continue-active', 'rewarded-death-delay');
        if (ui.rewardedContinue) {
            ui.rewardedContinue.classList.remove('is-active');
            ui.rewardedContinue.setAttribute('aria-hidden', 'true');
        }
        if (ui.rewardedContinueStatus) ui.rewardedContinueStatus.textContent = '';
        if (ui.rewardedContinueWatch) ui.rewardedContinueWatch.disabled = false;
        if (ui.rewardedContinueDecline) ui.rewardedContinueDecline.disabled = false;
    }

    function showRewardedDeathOffer() {
        rewardedDeathOfferTimer = null;
        if (!rewardedDeathPending || isGameOver) return;
        rewardedDeathOfferReady = true;
        document.body.classList.remove('rewarded-death-delay');
        document.body.classList.add('rewarded-continue-active');
        if (ui.rewardedContinue) {
            ui.rewardedContinue.classList.add('is-active');
            ui.rewardedContinue.setAttribute('aria-hidden', 'false');
        }
        if (ui.rewardedContinueStatus) ui.rewardedContinueStatus.textContent = '';
        applyBrowserLanguageTexts();
        setTimeout(() => {
            if (rewardedDeathPending && rewardedDeathOfferReady && ui.rewardedContinueWatch) ui.rewardedContinueWatch.focus();
        }, 40);
    }

    function beginRewardedDeathOffer(msg) {
        hideHowToPlayOverlay(true);
        rewardedDeathPending = true;
        if (isCrazyGamesBuild()) rewardedContinueNextEligibleAt = Date.now() + REWARDED_CONTINUE_COOLDOWN_MS;
        rewardedDeathOfferReady = false;
        pendingRewardedDeathMessage = msg || '';
        mainMenuVisible = false;
        isGamePaused = true;
        isDying = true;
        middleMouseHeld = false;
        forceEndTimeSlow();
        forceEndMagnet();
        forceEndAllHandSkills(false);
        magnetCooldown = 0;
        resetControlActionState();
        wheelSkillTapCount = 0;
        resetGlideTimer();
        setGlideWindActive(false);
        updateDoubleJumpCooldownUi(true);
        setMenuAmbientActive(false);
        stopGameplayMusicNow();
        closeMenuDialogs();
        closePauseSettingsPanel();
        document.body.classList.remove('main-menu-active', 'game-over-active', 'rewarded-continue-active');
        document.body.classList.add('rewarded-death-delay');
        const platform = crazyGamesPlatform();
        if (platform) platform.gameplayStop();
        if (ui.gameOver) ui.gameOver.style.display = 'none';
        if (ui.mainMenu) {
            ui.mainMenu.style.display = 'none';
            ui.mainMenu.setAttribute('aria-hidden', 'true');
        }
        if (ui.pauseScreen) ui.pauseScreen.style.display = 'none';
        if (ui.rewardedContinue) {
            ui.rewardedContinue.classList.remove('is-active');
            ui.rewardedContinue.setAttribute('aria-hidden', 'true');
        }
        if (ui.rewardedContinueStatus) ui.rewardedContinueStatus.textContent = '';
        applyBrowserLanguageTexts();
        playCrashSound();
        try { if (document.pointerLockElement) document.exitPointerLock(); } catch (error) {}
        if (rewardedDeathOfferTimer) clearTimeout(rewardedDeathOfferTimer);
        rewardedDeathOfferTimer = setTimeout(showRewardedDeathOffer, REWARDED_DEATH_OFFER_DELAY_MS);
    }

    async function watchRewardedContinue() {
        if (!areRewardedAdsEnabled() || !rewardedDeathPending || !rewardedDeathOfferReady || rewardedAdBusy) return;
        if (ui.rewardedContinueStatus) ui.rewardedContinueStatus.textContent = browserTr('adLoading');
        if (ui.rewardedContinueWatch) ui.rewardedContinueWatch.disabled = true;
        if (ui.rewardedContinueDecline) ui.rewardedContinueDecline.disabled = true;
        const result = await requestRewardedAd('continue_after_death');
        if (!rewardedDeathPending) return;
        if (!result || result.status !== 'completed') {
            if (ui.rewardedContinueStatus) ui.rewardedContinueStatus.textContent = browserTr('adUnavailable');
            if (ui.rewardedContinueWatch) ui.rewardedContinueWatch.disabled = false;
            if (ui.rewardedContinueDecline) ui.rewardedContinueDecline.disabled = false;
            return;
        }
        const deathMessage = pendingRewardedDeathMessage;
        rewardedDeathPending = false;
        pendingRewardedDeathMessage = '';
        hideRewardedContinueOverlay();
        isGamePaused = false;
        if (!startReviveSequence({ consumeUpgrade: false, source: 'rewarded-ad' })) {
            finalizeGameOver(deathMessage, { impactAlreadyPlayed: true });
        }
    }

    function declineRewardedContinue() {
        if (!rewardedDeathPending || rewardedAdBusy) return;
        const deathMessage = pendingRewardedDeathMessage;
        rewardedDeathPending = false;
        pendingRewardedDeathMessage = '';
        hideRewardedContinueOverlay();
        isGamePaused = false;
        finalizeGameOver(deathMessage, { impactAlreadyPlayed: true });
    }

    function finalizeGameOver(msg, options = {}) {
        hideHowToPlayOverlay(true);
        isGameOver = true;
        finishPlayerFitLevelAttempt('fail');
        const normalizedDeath = String(msg || '').toLocaleLowerCase('tr-TR');
        const deathKind = normalizedDeath.includes('kartopu') ? 'snowball' : 'collision';
        measurePlayerFit('death', deathKind, currentRunMode === 'level' ? `level-${Math.max(1, playerFitCurrentLevel || 1)}` : 'endless');
        mainMenuVisible = false;
        isGamePaused = false;
        document.body.classList.remove('main-menu-active');
        middleMouseHeld = false;
        forceEndTimeSlow();
        forceEndMagnet();
        magnetCooldown = 0;
        resetControlActionState();
        wheelSkillTapCount = 0;
        resetGlideTimer();
        setGlideWindActive(false);
        updateDoubleJumpCooldownUi(true);
        if (shieldActive) deactivateShield();
        shieldTimer = 0;
        document.body.classList.add('game-over-active');
        closeMenuDialogs();
        setMenuAmbientActive(false);
        stopGameplayMusicNow();
        if (!options.impactAlreadyPlayed) {
            playCrashSound();
            spawnGlobalExplosion(player.position.x, player.position.y, player.position.z, 0xff4444, 30);
        }
        try { if (document.pointerLockElement) document.exitPointerLock(); } catch(e) {}
        if (ui.mainMenu) {
            ui.mainMenu.style.display = 'none';
            ui.mainMenu.setAttribute('aria-hidden', 'true');
        }
        if (ui.pauseScreen) ui.pauseScreen.style.display = 'none';
        closePauseSettingsPanel();
        if (ui.deathReason) ui.deathReason.innerText = translateDeathReason(msg);
        const finalScoreVal = getDisplayedRunScore();
        const finalCoinsVal = Math.floor(totalCoins);
        const prevBest = Math.floor(menuState.bestScore) || 0;
        if (ui.gameOver) ui.gameOver.style.display = 'grid';
        const platform = crazyGamesPlatform();
        if (platform) platform.gameplayStop();
        showGameOverStats(finalScoreVal, finalCoinsVal, prevBest);
        recordMainMenuRunStats();
        const gameOverPad = getPrimaryGamepad();
        if (gameOverPad) setControllerInputActive(true);
        if (controllerInputActive) resetGamepadUiFocus(0);
    }

    function gameOver(msg) {
        if (localQaInvulnerable) return;
        if (isHandSkillCollisionImmune()) return;
        // The FTUE never opens a death screen. Teaching hazards instead route
        // through the director's rewind handler below.
        if (isTutorialRunActive()) return;
        if (isGameOver || reviveSequenceActive || rewardedDeathPending || firstRunRewindSequence || firstRunRewindInvulnerability > 0) return;
        if (beginFirstRunRewind()) return;
        hideHowToPlayOverlay(true);
        if (MOBILE_RUNTIME) setMobileControlsVisible(false);
        if (tryUseRevive()) return;
        if (areRewardedAdsEnabled() && (!isCrazyGamesBuild() || Date.now() >= rewardedContinueNextEligibleAt)) {
            beginRewardedDeathOffer(msg);
            return;
        }
        finalizeGameOver(msg);
    }

