                menuState.handPurchaseTutorialSeen = false;
                menuState.handPurchaseTutorialVersion = 0;
                menuState.ownedHandSkins = getOwnedHandSkinIds().filter((id) => id !== 'ember');
                if (menuState.selectedHandSkin === 'ember') menuState.selectedHandSkin = 'default';
                menuState.walletCoins = Math.max(200, Math.floor(Number(wallet) || 0));
                updateMainMenuStats();
                saveMainMenuState();
                return window.__elementalBrowserTest.inspectHandPurchaseTutorial();
