    function createCyberGridTexture() {
        const size = isPerformanceGraphics() ? 512 : 1024;
        const canvas = document.createElement('canvas');
        canvas.width = size;
        canvas.height = size;
        const ctx = canvas.getContext('2d');
        ctx.fillStyle = '#02010a'; ctx.fillRect(0, 0, size, size);
        ctx.strokeStyle = '#220033'; ctx.lineWidth = 2; const step = 64;
        for (let i = 0; i <= size; i += step) {
            ctx.beginPath(); ctx.moveTo(i, 0); ctx.lineTo(i, size); ctx.stroke();
            ctx.beginPath(); ctx.moveTo(0, i); ctx.lineTo(size, i); ctx.stroke();
        }
        ctx.strokeStyle = '#aa00ff'; ctx.lineWidth = 3; const bigStep = 256;
        for (let i = 0; i <= size; i += bigStep) {
            ctx.beginPath(); ctx.moveTo(i, 0); ctx.lineTo(i, size); ctx.stroke();
            ctx.beginPath(); ctx.moveTo(0, i); ctx.lineTo(size, i); ctx.stroke();
        }
        const texture = new THREE.CanvasTexture(canvas);
        texture.colorSpace = THREE.SRGBColorSpace;
        texture.wrapS = THREE.RepeatWrapping; texture.wrapT = THREE.RepeatWrapping; texture.anisotropy = 16;
        return texture;
    }

    function createCyberFloor() {
        const tex = createCyberGridTexture(); tex.repeat.set(100, 100); 
        const geo = new THREE.PlaneGeometry(4000, 4000, 56, 8);
        const mat = new THREE.MeshBasicMaterial({ map: tex, color: 0x888888, transparent: true, opacity: 1.0, polygonOffset: true, polygonOffsetFactor: 1, polygonOffsetUnits: 1 });
        cyberFloor = new THREE.Mesh(geo, mat);
        cyberFloor.rotation.x = -Math.PI / 2; cyberFloor.position.y = -0.06; scene.add(cyberFloor);
        curvedPathSystem?.installObjectMaterials?.(cyberFloor);
    }

    const floorPbrDetailCache = new Map();
    function getFloorPbrDetails(kind, repeatX, repeatY) {
        const size = isPerformanceGraphics() ? 128 : 384;
        const cacheKey = `${kind}:${size}:${repeatX}:${repeatY}`;
        if (floorPbrDetailCache.has(cacheKey)) return floorPbrDetailCache.get(cacheKey);
        const normalData = new Uint8Array(size * size * 4);
        const roughData = new Uint8Array(size * size * 4);
        let seed = ({ nature: 0x51a713, lava: 0x1a7a52, water: 0x47a7e2, snow: 0x5a0f17 }[kind] || 0x71f00d) >>> 0;
        const random = () => {
            seed = (Math.imul(seed ^ (seed >>> 15), 1 | seed) + 0x6d2b79f5) >>> 0;
            let value = seed;
            value = Math.imul(value ^ (value >>> 7), 61 | value);
            return ((value ^ (value >>> 14)) >>> 0) / 4294967296;
        };
        for (let y = 0; y < size; y++) {
            for (let x = 0; x < size; x++) {
                const index = (y * size + x) * 4;
                const nx = x / size;
                const ny = y / size;
                let waveX = Math.sin(nx * Math.PI * (kind === 'water' ? 18 : 34) + y * 0.035);
                let waveY = Math.cos(ny * Math.PI * (kind === 'lava' ? 22 : 31) - x * 0.028);
                // A second scale gives every biome its own surface language:
                // directional water ripples, cracked magma, grass/soil clumps
                // and broad wind-shaped snow drifts.
                if (kind === 'water') {
                    waveX += Math.sin(nx * 78 + ny * 17) * 0.55;
                    waveY += Math.cos(ny * 54 - nx * 22) * 0.42;
                } else if (kind === 'lava') {
                    const crust = Math.sin(nx * 51 + Math.sin(ny * 19) * 2.6);
                    waveX += crust * 0.72;
                    waveY += Math.cos(ny * 47 - nx * 13) * 0.58;
                } else if (kind === 'nature') {
                    waveX += Math.sin(nx * 96 + ny * 41) * 0.38;
                    waveY += Math.cos(ny * 88 - nx * 31) * 0.46;
                } else if (kind === 'snow') {
                    waveX += Math.sin(nx * 23 + ny * 7) * 0.34;
                    waveY += Math.cos(ny * 18 - nx * 5) * 0.3;
                }
                const grain = random() - 0.5;
                const amplitude = kind === 'nature' ? 24 : (kind === 'snow' ? 12 : (kind === 'water' ? 18 : 27));
                normalData[index] = Math.max(0, Math.min(255, 128 + waveX * amplitude + grain * 18));
                normalData[index + 1] = Math.max(0, Math.min(255, 128 + waveY * amplitude + grain * 14));
                normalData[index + 2] = kind === 'lava' ? 238 : 246;
                normalData[index + 3] = 255;
                const baseRough = kind === 'nature' ? 232 : (kind === 'snow' ? 218 : (kind === 'water' ? 198 : 226));
                const roughness = Math.max(96, Math.min(252, baseRough + grain * 34 + waveX * 8));
                roughData[index] = roughData[index + 1] = roughData[index + 2] = roughness;
                roughData[index + 3] = 255;
            }
        }
        const createTexture = (data) => {
            const texture = new THREE.DataTexture(data, size, size, THREE.RGBAFormat, THREE.UnsignedByteType);
            texture.colorSpace = THREE.NoColorSpace;
            texture.wrapS = texture.wrapT = THREE.RepeatWrapping;
            texture.repeat.set(repeatX, repeatY);
            texture.anisotropy = Math.min(8, renderer?.capabilities?.getMaxAnisotropy?.() || 1);
            texture.generateMipmaps = true;
            texture.__pooled = true;
            texture.needsUpdate = true;
            return texture;
        };
        const result = Object.freeze({ normalMap: createTexture(normalData), roughnessMap: createTexture(roughData) });
        floorPbrDetailCache.set(cacheKey, result);
        return result;
    }

    function createNatureFloor() {
    // 1024px doku (eski 512) + tekrar 48→40: birim başına ~2.4x daha fazla texel.
    const size = isPerformanceGraphics() ? 512 : 1024;
    const canvas = document.createElement('canvas');
    canvas.width = size; canvas.height = size;
    const ctx = canvas.getContext('2d');
    ctx.fillStyle = '#1d3a19';
    ctx.fillRect(0,0,size,size);
    // yumuşak ton yamaları (tek düze görünmesin)
    for(let i=0; i<(isPerformanceGraphics() ? 90 : 260); i++){
        const x = Math.random()*size, y = Math.random()*size, r = 30 + Math.random()*95;
        const grad = ctx.createRadialGradient(x, y, 0, x, y, r);
        const c = Math.random() > 0.5 ? '34,71,24' : '24,49,19';
        grad.addColorStop(0, `rgba(${c},0.32)`);
        grad.addColorStop(1, `rgba(${c},0)`);
        ctx.fillStyle = grad;
        ctx.fillRect(x-r, y-r, r*2, r*2);
    }
    // çimen bıçakları — İKİ vuruş: koyu taban + açık uç (derinlik hissi), 4 ton
    const grassDark = ['#20421c', '#1b3817', '#25491f', '#2a5323'];
    const grassLight = ['#3f7a35', '#4c8a3e', '#356b2e', '#57a04a'];
    ctx.lineWidth = 1;
    for(let i=0; i<(isPerformanceGraphics() ? 6500 : 26000); i++){
        const x = Math.random()*size, y = Math.random()*size;
        const len = 5 + Math.random()*7;
        const tilt = (Math.random()-0.5) * 3.6;
        const tone = Math.floor(Math.random()*4);
        ctx.strokeStyle = grassDark[tone];
        ctx.beginPath(); ctx.moveTo(x, y); ctx.lineTo(x + tilt, y - len); ctx.stroke();
        ctx.strokeStyle = grassLight[tone];
        ctx.beginPath(); ctx.moveTo(x + tilt * 0.55, y - len * 0.55); ctx.lineTo(x + tilt, y - len); ctx.stroke();
    }
    // yonca/çalı yamaları — küçük koyu daire kümeleri
    for(let i=0; i<(isPerformanceGraphics() ? 70 : 220); i++){
        const cx = Math.random()*size, cy = Math.random()*size;
        ctx.fillStyle = Math.random() > 0.5 ? '#2e6027' : '#264f20';
        for(let k=0; k<5; k++){
            ctx.beginPath();
            ctx.arc(cx + (Math.random()-0.5)*7, cy + (Math.random()-0.5)*7, 1.4 + Math.random()*1.3, 0, Math.PI*2);
            ctx.fill();
        }
    }
    // çakıl taşları — gölge + gövde + parlak kenar (hacim hissi)
    for(let i=0; i<(isPerformanceGraphics() ? 120 : 420); i++){
        const x = Math.random()*size, y = Math.random()*size, w = 2 + Math.random()*3.5;
        ctx.fillStyle = 'rgba(10,18,8,0.55)';
        ctx.fillRect(x+0.8, y+0.8, w, w*0.75);
        ctx.fillStyle = Math.random() > 0.5 ? '#4a3b28' : '#5a6258';
        ctx.fillRect(x, y, w, w*0.75);
        ctx.fillStyle = 'rgba(220,225,215,0.28)';
        ctx.fillRect(x, y, w*0.5, 1);
    }
    // minik kır çiçekleri — taç yaprak + sarı merkez
    const flowerPix = ['#ffe066', '#ff9bb0', '#e8f0ff', '#ffb84d'];
    for(let i=0; i<(isPerformanceGraphics() ? 90 : 300); i++){
        const x = Math.random()*size, y = Math.random()*size;
        ctx.fillStyle = flowerPix[Math.floor(Math.random()*flowerPix.length)];
        ctx.fillRect(x-1.5, y, 4, 1.6);
        ctx.fillRect(x, y-1.5, 1.6, 4);
        ctx.fillStyle = '#ffd94a';
        ctx.fillRect(x, y, 1.6, 1.6);
    }
    const tex = new THREE.CanvasTexture(canvas);
    tex.colorSpace = THREE.SRGBColorSpace;
    tex.wrapS = THREE.RepeatWrapping; tex.wrapT = THREE.RepeatWrapping;
    tex.repeat.set(40, 40);
    // Yatık bakış açısında (koşucu kamerası) netlik için anisotropy
    if (typeof renderer !== 'undefined' && renderer && renderer.capabilities) {
        tex.anisotropy = renderer.capabilities.getMaxAnisotropy();
    }

    const geo = new THREE.PlaneGeometry(4000, 4000, 56, 8);
    const naturePbr = getFloorPbrDetails('nature', 40, 40);
    const mat = new THREE.MeshStandardMaterial({
        map: tex,
        normalMap: naturePbr.normalMap,
        normalScale: new THREE.Vector2(0.34, 0.34),
        roughnessMap: naturePbr.roughnessMap,
        roughness: 0.92,
        metalness: 0.01,
        envMapIntensity: 0.07,
        transparent: true,
        opacity: 0.0,
        depthWrite: true,
        emissive: 0x10250d,
        emissiveIntensity: 0.12,
        polygonOffset: true,
        polygonOffsetFactor: 1,
        polygonOffsetUnits: 1
    });
    
    natureFloor = new THREE.Mesh(geo, mat);
    natureFloor.rotation.x = -Math.PI / 2; 
    natureFloor.position.y = -0.08; 
    natureFloor.renderOrder = 0; 
    natureFloor.visible = false;
    scene.add(natureFloor);
    curvedPathSystem?.installObjectMaterials?.(natureFloor);

    const leafGeo = new THREE.BufferGeometry();
    const leafCount = isPerformanceGraphics() ? 70 : 230;
    const lPos = new Float32Array(leafCount * 3);
    const lCol = new Float32Array(leafCount * 3);
    const lSpeed = [];
    // karışık yaprak tonları: yeşiller + seyrek amber/sarı (sonbahar aksanı)
    const leafPalette = [0x4CAF50, 0x66bb6a, 0x9ccc65, 0x7cb342, 0xd4a017, 0xffd54f];
    const lc = new THREE.Color();
    for(let i=0; i<leafCount; i++) {
        lPos[i*3] = (Math.random() - 0.5) * 600;
        lPos[i*3+1] = 40 + Math.random() * 120;
        lPos[i*3+2] = (Math.random() - 0.5) * 400;
        lc.setHex(leafPalette[Math.floor(Math.random() * (Math.random() > 0.25 ? 4 : leafPalette.length))]);
        lCol[i*3] = lc.r; lCol[i*3+1] = lc.g; lCol[i*3+2] = lc.b;
        lSpeed.push({ y: 0.1 + Math.random() * 0.2, x: (Math.random() - 0.5) * 0.1, z: 0.2 + Math.random() * 0.3 });
    }
    leafGeo.setAttribute('position', new THREE.BufferAttribute(lPos, 3).setUsage(THREE.DynamicDrawUsage));
    r185OptimizationStats.dynamicBufferHints += 1;
    leafGeo.setAttribute('color', new THREE.BufferAttribute(lCol, 3));
    const leafMat = new THREE.PointsMaterial({ vertexColors: true, size: 0.55, transparent: true, opacity: 0.0 });
    const leafSystem = new THREE.Points(leafGeo, leafMat);
    leafSystem.name = 'natureLeaves';
    leafSystem.visible = false; 
    scene.add(leafSystem);
    natureFloor.userData.leafSystem = leafSystem;
    natureFloor.userData.leafSpeeds = lSpeed;
}

    function createRepeatSurfaceTexture(data, size, colorSpace, repeatX, repeatY) {
        const texture = new THREE.DataTexture(data, size, size, THREE.RGBAFormat);
        texture.wrapS = THREE.RepeatWrapping;
        texture.wrapT = THREE.RepeatWrapping;
        texture.repeat.set(repeatX, repeatY);
        texture.colorSpace = colorSpace;
        texture.generateMipmaps = true;
        texture.minFilter = THREE.LinearMipmapLinearFilter;
        texture.magFilter = THREE.LinearFilter;
        texture.anisotropy = Math.min(8, renderer?.capabilities?.getMaxAnisotropy?.() || 1);
        texture.needsUpdate = true;
        return texture;
    }

    function loadAuthoredFloorTexture(url, repeatX, repeatY) {
        const texture = new THREE.TextureLoader().load(
            url,
            (loaded) => {
                loaded.colorSpace = THREE.SRGBColorSpace;
                loaded.wrapS = THREE.RepeatWrapping;
                loaded.wrapT = THREE.RepeatWrapping;
                loaded.repeat.set(repeatX, repeatY);
                loaded.generateMipmaps = true;
                loaded.minFilter = THREE.LinearMipmapLinearFilter;
                loaded.magFilter = THREE.LinearFilter;
                loaded.anisotropy = Math.min(8, renderer?.capabilities?.getMaxAnisotropy?.() || 1);
                loaded.needsUpdate = true;
            },
            undefined,
            () => console.warn(`[surface] Could not load ${url}; procedural PBR detail remains active.`)
        );
        texture.colorSpace = THREE.SRGBColorSpace;
        texture.wrapS = THREE.RepeatWrapping;
        texture.wrapT = THREE.RepeatWrapping;
        texture.repeat.set(repeatX, repeatY);
        texture.generateMipmaps = true;
        texture.minFilter = THREE.LinearMipmapLinearFilter;
        texture.magFilter = THREE.LinearFilter;
        texture.anisotropy = Math.min(8, renderer?.capabilities?.getMaxAnisotropy?.() || 1);
        texture.userData.authoredWorldFloor = true;
        return texture;
    }

    function samplePeriodicLava(u, v) {
        const tau = Math.PI * 2;
        const warpedU = u + Math.sin(v * tau * 2) * 0.075 + Math.sin(v * tau * 5) * 0.018;
        const warpedV = v + Math.cos(u * tau * 3) * 0.064 + Math.sin(u * tau * 7) * 0.015;
        const field = Math.sin(tau * (warpedU * 3 + warpedV)) * 0.58
            + Math.sin(tau * (warpedV * 4 - warpedU * 0.65)) * 0.34
            + Math.sin(tau * (warpedU * 7 + warpedV * 5)) * 0.14;
        const vein = Math.exp(-Math.abs(field) * 4.25);
        const pool = 0.5 + 0.5 * Math.sin(tau * (warpedU * 2 - warpedV * 3));
        const micro = 0.5 + 0.5 * Math.sin(tau * (u * 13 + v * 11));
        return Math.max(0, Math.min(1, vein * (0.74 + pool * 0.24) + micro * 0.055));
    }

    function createSeamlessLavaSurfaceTextures() {
        const size = isMobilePerformanceGraphics() ? 256 : 512;
        const normalData = new Uint8Array(size * size * 4);
        const roughnessData = new Uint8Array(size * size * 4);
        const step = 1 / size;
        for (let y = 0; y < size; y++) {
            const v = y / size;
            for (let x = 0; x < size; x++) {
                const u = x / size;
                const heat = samplePeriodicLava(u, v);
                const hot = Math.pow(heat, 1.35);
                const crustVariation = 0.5 + 0.5 * Math.sin(Math.PI * 2 * (u * 17 - v * 19));
                const i = (y * size + x) * 4;

                const dx = samplePeriodicLava((u + step) % 1, v) - samplePeriodicLava((u - step + 1) % 1, v);
                const dy = samplePeriodicLava(u, (v + step) % 1) - samplePeriodicLava(u, (v - step + 1) % 1);
                const nx = -dx * 5.5;
                const ny = -dy * 5.5;
                const inv = 1 / Math.sqrt(nx * nx + ny * ny + 1);
                normalData[i] = Math.round((nx * inv * 0.5 + 0.5) * 255);
                normalData[i + 1] = Math.round((ny * inv * 0.5 + 0.5) * 255);
                normalData[i + 2] = Math.round((inv * 0.5 + 0.5) * 255);
                normalData[i + 3] = 255;

                const rough = Math.round(220 - hot * 74 + crustVariation * (1 - hot) * 18);
                roughnessData[i] = roughnessData[i + 1] = roughnessData[i + 2] = rough;
                roughnessData[i + 3] = 255;
            }
        }
        const repeatX = 8;
        const repeatY = 8;
        const authored = loadAuthoredFloorTexture('assets/textures/lava-world-floor-v3.webp?v=1.7.0', repeatX, repeatY);
        return {
            albedo: authored,
            emissive: authored,
            normal: createRepeatSurfaceTexture(normalData, size, THREE.NoColorSpace, repeatX, repeatY),
            roughness: createRepeatSurfaceTexture(roughnessData, size, THREE.NoColorSpace, repeatX, repeatY),
            repeatX,
            repeatY
        };
    }

    function createLavaTexture() {
        const size = isMobilePerformanceGraphics() ? 512 : 1024;
        const canvas = document.createElement('canvas');
        canvas.width = size;
        canvas.height = size;
        const ctx = canvas.getContext('2d');

        const drawWrappedCircle = (x, y, r, fillStyle) => {
            ctx.fillStyle = fillStyle;
            for (let ox = -1; ox <= 1; ox++) {
                for (let oy = -1; oy <= 1; oy++) {
                    ctx.beginPath();
                    ctx.arc(x + ox * size, y + oy * size, r, 0, Math.PI * 2);
                    ctx.fill();
                }
            }
        };

        const drawWrappedLine = (points, strokeStyle, lineWidth) => {
            ctx.strokeStyle = strokeStyle;
            ctx.lineWidth = lineWidth;
            ctx.lineCap = 'round';
            ctx.lineJoin = 'round';
            for (let ox = -1; ox <= 1; ox++) {
                for (let oy = -1; oy <= 1; oy++) {
                    ctx.beginPath();
                    ctx.moveTo(points[0].x + ox * size, points[0].y + oy * size);
                    for (let i = 1; i < points.length; i++) {
                        ctx.lineTo(points[i].x + ox * size, points[i].y + oy * size);
                    }
                    ctx.stroke();
                }
            }
        };

        const grad = ctx.createLinearGradient(0, 0, size, size);
        grad.addColorStop(0, '#080101');
        grad.addColorStop(0.28, '#170302');
        grad.addColorStop(0.56, '#3d0904');
        grad.addColorStop(0.82, '#6b1207');
        grad.addColorStop(1, '#541007');
        ctx.fillStyle = grad;
        ctx.fillRect(0, 0, size, size);

        for (let i = 0; i < 3200; i++) {
            const x = Math.random() * size;
            const y = Math.random() * size;
            const w = 2 + Math.random() * 6;
            const h = 2 + Math.random() * 6;
            ctx.fillStyle = Math.random() > 0.6 ? 'rgba(18,4,2,0.28)' : 'rgba(86,14,8,0.14)';
            ctx.fillRect(x, y, w, h);
        }

        for (let i = 0; i < 420; i++) {
            const x = Math.random() * size;
            const y = Math.random() * size;
            const r = 36 + Math.random() * 120;
            const crust = ctx.createRadialGradient(x, y, 0, x, y, r);
            crust.addColorStop(0, 'rgba(152,30,14,0.16)');
            crust.addColorStop(0.3, 'rgba(82,16,8,0.18)');
            crust.addColorStop(0.72, 'rgba(16,4,2,0.36)');
            crust.addColorStop(1, 'rgba(0,0,0,0)');
            drawWrappedCircle(x, y, r, crust);
        }

        // Parlak lav gölcükleri — daha yoğun ve daha aydınlık (beyaz-sıcak çekirdek)
        for (let i = 0; i < 200; i++) {
            const x = Math.random() * size;
            const y = Math.random() * size;
            const r = 20 + Math.random() * 82;
            const glow = ctx.createRadialGradient(x, y, 0, x, y, r);
            glow.addColorStop(0, 'rgba(255,246,206,0.62)');
            glow.addColorStop(0.14, 'rgba(255,190,74,0.5)');
            glow.addColorStop(0.4, 'rgba(228,84,20,0.28)');
            glow.addColorStop(0.72, 'rgba(120,28,10,0.14)');
            glow.addColorStop(1, 'rgba(24,6,2,0)');
            drawWrappedCircle(x, y, r, glow);
        }

        // Akan lav damarları — çok katmanlı (koyu kabuk kenarı + turuncu gövde + parlak çekirdek)
        for (let i = 0; i < 170; i++) {
            let px = Math.random() * size;
            let py = Math.random() * size;
            const points = [{ x: px, y: py }];
            const segments = 3 + Math.floor(Math.random() * 6);
            for (let j = 0; j < segments; j++) {
                px += (Math.random() - 0.5) * 110;
                py += (Math.random() - 0.5) * 110;
                points.push({ x: px, y: py });
            }
            drawWrappedLine(points, 'rgba(10,2,1,0.4)', 9 + Math.random() * 8);              // koyu kabuk kenarı
            drawWrappedLine(points, 'rgba(232,88,26,0.42)', 5 + Math.random() * 6);           // turuncu gövde
            drawWrappedLine(points, Math.random() > 0.5 ? 'rgba(255,224,140,0.72)' : 'rgba(255,168,60,0.55)', 1.6 + Math.random() * 2.8); // parlak çekirdek
        }

        for (let i = 0; i < 180; i++) {
            let px = Math.random() * size;
            let py = Math.random() * size;
            const points = [{ x: px, y: py }];
            const segments = 4 + Math.floor(Math.random() * 7);
            for (let j = 0; j < segments; j++) {
                px += (Math.random() - 0.5) * 150;
                py += (Math.random() - 0.5) * 150;
                points.push({ x: px, y: py });
            }
            drawWrappedLine(points, 'rgba(12,2,1,0.26)', 10 + Math.random() * 10);
        }

        const tex = new THREE.CanvasTexture(canvas);
        tex.wrapS = THREE.RepeatWrapping;
        tex.wrapT = THREE.RepeatWrapping;
        tex.repeat.set(20, 20);
        tex.anisotropy = Math.min(8, renderer?.capabilities?.getMaxAnisotropy?.() || 1);
        if ('colorSpace' in tex && THREE.SRGBColorSpace) tex.colorSpace = THREE.SRGBColorSpace;
        return tex;
    }

    function setLavaFloorAlpha(alpha) {
        if (!lavaFloor || !lavaFloor.material) return;
        lavaFloor.material.opacity = Math.max(0, Math.min(1, alpha));
    }

    function setLavaFloorTime(value) {
        if (!lavaFloor || !lavaFloor.material || !lavaFloor.material.map) return;
        const floorSize = lavaFloor.userData.floorSize || 4000;
        const repeatX = lavaFloor.material.map.repeat.x || 1;
        const virtualCenterX = lavaFloor.position.x + worldScrollX;
        const worldLockedU = (virtualCenterX / floorSize) * repeatX;
        const u = ((worldLockedU + value * 0.006) % 1 + 1) % 1;
        // Plane U is world-forward and V is world-lateral after rotation.
        // Animating V made the entire magma field visibly drift to the right.
        const v = 0;
        [lavaFloor.material.map, lavaFloor.material.emissiveMap, lavaFloor.material.normalMap, lavaFloor.material.roughnessMap]
            .filter(Boolean)
            .forEach((texture) => { texture.offset.set(u, v); });
    }

    function createLavaFloor() {
        const surface = createSeamlessLavaSurfaceTextures();
        const geo = new THREE.PlaneGeometry(4000, 4000, 56, 8);
        const mat = new THREE.MeshStandardMaterial({
            map: surface.albedo,
            normalMap: surface.normal,
            normalScale: new THREE.Vector2(0.42, 0.42),
            roughnessMap: surface.roughness,
            emissive: 0xffa45e,
            emissiveMap: surface.emissive,
            // Dark crust and genuinely emissive flowing veins; the periodic
            // source data removes tile-border lines at every mip level.
            emissiveIntensity: 0.72,
            roughness: 0.91,
            metalness: 0.0,
            envMapIntensity: 0.015,
            transparent: true,
            opacity: 0.0,
            depthTest: true,
            depthWrite: true,
            side: THREE.FrontSide
        });

        if (lavaFloor && lavaFloor.parent) {
            lavaFloor.parent.remove(lavaFloor);
            disposeNode(lavaFloor);
        }
        if (lavaEmbers && lavaEmbers.parent) {
            lavaEmbers.parent.remove(lavaEmbers);
            disposeNode(lavaEmbers);
        }

        lavaFloor = new THREE.Mesh(geo, mat);
        lavaFloor.rotation.x = -Math.PI / 2;
        // Keep a stable visual clearance below the curved asphalt. The authored
        // magma is a world floor, not a coplanar road decal.
        lavaFloor.position.y = -4.25;
        lavaFloor.visible = false;
        lavaFloor.renderOrder = -1;
        lavaFloor.receiveShadow = false;
        lavaFloor.frustumCulled = false;
        lavaFloor.userData.isLavaWorldFloor = true;
        lavaFloor.userData.floorSize = 4000;
        scene.add(lavaFloor);
        // Follow the road centreline without rotating the full 4000-unit sheet.
        // This prevents both road/floor intersections and far-plane folding.
        // Physics stays on the straight CPU plane; rendering is the only change.
        curvedPathSystem?.installObjectMaterials?.(lavaFloor, { mode: 'sheet', baseY: 0, centerZ: getRoadCenterZ() });

        // ZENGİN KIVILCIMLAR: 320 adet, çok-renkli (beyaz-sıcak → sarı → turuncu → kırmızı),
        // değişken boyutta (vertex-color + boyut attribute'u ile canlı kor hissi).
        const emberCount = isMobilePerformanceGraphics() ? 100 : 320;
        const emberPos = new Float32Array(emberCount * 3);
        const emberCol = new Float32Array(emberCount * 3);
        const emberPalette = [0xfff2c8, 0xffd257, 0xff9a2e, 0xff5a1a, 0xe33410];
        const ec = new THREE.Color();
        lavaEmberData = [];
        for (let i = 0; i < emberCount; i++) {
            const side = Math.random() > 0.5 ? 1 : -1;
            const relX = (Math.random() - 0.5) * 1100;
            const z = side * (30 + Math.random() * 180);
            const baseY = 1 + Math.random() * 12;
            emberPos[i * 3] = relX;
            emberPos[i * 3 + 1] = baseY;
            emberPos[i * 3 + 2] = z;
            ec.setHex(emberPalette[Math.floor(Math.random() * (Math.random() > 0.3 ? 3 : emberPalette.length))]);
            emberCol[i * 3] = ec.r; emberCol[i * 3 + 1] = ec.g; emberCol[i * 3 + 2] = ec.b;
            lavaEmberData.push({
                relX, z, baseY,
                rise: 4 + Math.random() * 11,
                drift: (Math.random() - 0.5) * 1.3,
                phase: Math.random() * Math.PI * 2
            });
        }

        const emberGeo = new THREE.BufferGeometry();
        emberGeo.setAttribute('position', new THREE.BufferAttribute(emberPos, 3).setUsage(THREE.DynamicDrawUsage));
        r185OptimizationStats.dynamicBufferHints += 1;
        emberGeo.setAttribute('color', new THREE.BufferAttribute(emberCol, 3));
        const emberMat = new THREE.PointsMaterial({
            vertexColors: true,
            size: 2.0,
            transparent: true,
            opacity: 0.0,
            depthWrite: false,
            blending: THREE.AdditiveBlending,
            fog: true
        });
        lavaEmbers = new THREE.Points(emberGeo, emberMat);
        lavaEmbers.visible = false;
        lavaEmbers.userData.worldRebaseExempt = true; // buffer dünya-uzayı; applyWorldRebase kaydırır
        scene.add(lavaEmbers);

        // YOL SEVİYESİ LAV IŞIĞI: oyuncuyu takip eden sıcak nabızlı ışık (yol + yakın modelleri
        // aydınlatır). Yükleme ekranında eklenir (intensity 0) → prewarm shader'ı derler, faz
        // dışında görsel etki yok. updateLava içinde konum/intensity sürülür.
        if (!lavaGlowLight) {
            lavaGlowLight = new THREE.PointLight(0xff5c1e, 0, 340, 1.6);
            scene.add(lavaGlowLight);
        }

        // SICAKLIK TİTREŞİMİ: yolun üstünde yükselen yarı saydam sıcak puf katmanı (additive)
        if (lavaHeatHaze && lavaHeatHaze.parent) { lavaHeatHaze.parent.remove(lavaHeatHaze); disposeNode(lavaHeatHaze); }
        const hazeCount = isMobilePerformanceGraphics() ? 6 : 14;
        const hazeGeo = new THREE.BufferGeometry();
        const hazePos = new Float32Array(hazeCount * 3);
        // z min 20→58: puflar yol lane'inden dışarıda kalsın, tam oyuncunun üstünden geçmesin
        for (let i = 0; i < hazeCount; i++) { hazePos[i*3] = (Math.random()-0.5)*900; hazePos[i*3+1] = 2 + Math.random()*7; hazePos[i*3+2] = (Math.random()>0.5?1:-1)*(58+Math.random()*110); }
        hazeGeo.setAttribute('position', new THREE.BufferAttribute(hazePos, 3).setUsage(THREE.DynamicDrawUsage));
        r185OptimizationStats.dynamicBufferHints += 1;
        const hazeMat = new THREE.PointsMaterial({ color: 0xff7a30, size: 36, transparent: true, opacity: 0.0, depthWrite: false, blending: THREE.AdditiveBlending, map: makeSoftHazeSprite(), fog: true });
        lavaHeatHaze = new THREE.Points(hazeGeo, hazeMat);
        lavaHeatHaze.visible = false;
        lavaHeatHaze.userData.worldRebaseExempt = true; // buffer dünya-uzayı; applyWorldRebase kaydırır
        scene.add(lavaHeatHaze);
    }

    // Yumuşak radyal sprite (sıcaklık pufu için) — bir kez üretilir, cache'lenir
    let _softHazeSprite = null;
    function makeSoftHazeSprite() {
        if (_softHazeSprite) return _softHazeSprite;
        const s = 64, cv = document.createElement('canvas'); cv.width = cv.height = s;
        const c = cv.getContext('2d');
        const g = c.createRadialGradient(s/2, s/2, 0, s/2, s/2, s/2);
        g.addColorStop(0, 'rgba(255,255,255,0.5)');
        g.addColorStop(0.5, 'rgba(255,180,90,0.2)');
        g.addColorStop(1, 'rgba(255,120,40,0)');
        c.fillStyle = g; c.fillRect(0, 0, s, s);
        _softHazeSprite = new THREE.CanvasTexture(cv);
        _softHazeSprite.colorSpace = THREE.SRGBColorSpace;
        return _softHazeSprite;
    }

    function createWaterTexture() {
        if (typeof WATER_CAUSTIC_IMAGE_DATA === 'string' && WATER_CAUSTIC_IMAGE_DATA.length > 64) {
            const tex = new THREE.TextureLoader().load(WATER_CAUSTIC_IMAGE_DATA);
            tex.wrapS = THREE.RepeatWrapping;
            tex.wrapT = THREE.RepeatWrapping;
            tex.repeat.set(12.0, 18.0);
            tex.anisotropy = 16;
            tex.colorSpace = THREE.SRGBColorSpace;
            return tex;
        }

        const size = 512;
        const canvas = document.createElement('canvas');
        canvas.width = size;
        canvas.height = size;
        const ctx = canvas.getContext('2d');

        const grad = ctx.createLinearGradient(0, 0, size, size);
        grad.addColorStop(0, '#c9f8f7');
        grad.addColorStop(0.24, '#69d4df');
        grad.addColorStop(0.56, '#22a2bf');
        grad.addColorStop(0.82, '#64d2d8');
        grad.addColorStop(1, '#d9fbf4');
        ctx.fillStyle = grad;
        ctx.fillRect(0, 0, size, size);

        const drawWrappedPath = (points, strokeStyle, lineWidth, blur = 0, alpha = 1) => {
            ctx.save();
            ctx.globalAlpha = alpha;
            ctx.strokeStyle = strokeStyle;
            ctx.lineWidth = lineWidth;
            ctx.lineCap = 'round';
            ctx.lineJoin = 'round';
            ctx.filter = blur > 0 ? `blur(${blur}px)` : 'none';
            for (let ox = -size; ox <= size; ox += size) {
                for (let oy = -size; oy <= size; oy += size) {
                    ctx.beginPath();
                    points.forEach((p, idx) => {
                        const x = p.x + ox;
                        const y = p.y + oy;
                        if (idx === 0) ctx.moveTo(x, y);
                        else ctx.lineTo(x, y);
                    });
                    ctx.stroke();
                }
            }
            ctx.restore();
        };

        for (let i = 0; i < 3200; i++) {
            const shade = 210 + Math.random() * 35;
            ctx.fillStyle = `rgba(${Math.floor(shade)}, ${Math.floor(246 + Math.random() * 8)}, 255, ${0.018 + Math.random() * 0.03})`;
            ctx.fillRect(Math.random() * size, Math.random() * size, 1 + Math.random() * 2, 1 + Math.random() * 2);
        }

        for (let i = 0; i < 58; i++) {
            const x = Math.random() * size;
            const y = Math.random() * size;
            const rx = 34 + Math.random() * 72;
            const ry = 18 + Math.random() * 48;
            const rot = Math.random() * Math.PI;
            ctx.save();
            ctx.translate(x, y);
            ctx.rotate(rot);
            const glow = ctx.createRadialGradient(0, 0, 0, 0, 0, rx);
            glow.addColorStop(0, 'rgba(232,255,255,0.16)');
            glow.addColorStop(0.55, 'rgba(68,183,210,0.08)');
            glow.addColorStop(1, 'rgba(0,0,0,0)');
            ctx.fillStyle = glow;
            ctx.beginPath();
            ctx.ellipse(0, 0, rx, ry, 0, 0, Math.PI * 2);
            ctx.fill();
            ctx.restore();
        }

        for (let i = 0; i < 36; i++) {
            let x = Math.random() * size;
            let y = Math.random() * size;
            let angle = Math.random() * Math.PI * 2;
            const points = [{ x, y }];
            const steps = 5 + Math.floor(Math.random() * 5);
            for (let s = 0; s < steps; s++) {
                angle += (Math.random() - 0.5) * 0.95;
                const len = 22 + Math.random() * 46;
                x += Math.cos(angle) * len;
                y += Math.sin(angle) * len;
                points.push({ x, y });
            }
            drawWrappedPath(points, 'rgba(240,255,255,0.36)', 8.0 + Math.random() * 5.0, 5.0, 1);
            drawWrappedPath(points, 'rgba(255,255,255,0.72)', 1.3 + Math.random() * 1.5, 0, 1);
        }

        for (let i = 0; i < 22; i++) {
            const cx = Math.random() * size;
            const cy = Math.random() * size;
            const radius = 22 + Math.random() * 66;
            const sides = 5 + Math.floor(Math.random() * 4);
            const points = [];
            for (let s = 0; s <= sides; s++) {
                const a = (s / sides) * Math.PI * 2;
                const r = radius * (0.72 + Math.random() * 0.42);
                points.push({
                    x: cx + Math.cos(a) * r,
                    y: cy + Math.sin(a) * r
                });
            }
            drawWrappedPath(points, 'rgba(255,255,255,0.22)', 8.0, 4.0, 0.8);
            drawWrappedPath(points, 'rgba(255,255,255,0.42)', 1.25, 0, 0.85);
        }

        const tex = new THREE.CanvasTexture(canvas);
        tex.colorSpace = THREE.SRGBColorSpace;
        tex.wrapS = THREE.RepeatWrapping;
        tex.wrapT = THREE.RepeatWrapping;
        tex.repeat.set(7.0, 7.0);
        tex.generateMipmaps = false;
        tex.minFilter = THREE.LinearFilter;
        tex.magFilter = THREE.LinearFilter;
        tex.anisotropy = 16;
        return tex;
    }

    function createWaterWaveOverlayTexture() {
        const size = 512;
        const canvas = document.createElement('canvas');
        canvas.width = size;
        canvas.height = size;
        const ctx = canvas.getContext('2d');
        ctx.clearRect(0, 0, size, size);

        const drawWrappedPath = (points, strokeStyle, lineWidth, blur = 0) => {
            ctx.save();
            ctx.strokeStyle = strokeStyle;
            ctx.lineWidth = lineWidth;
            ctx.lineCap = 'round';
            ctx.lineJoin = 'round';
            ctx.filter = blur > 0 ? `blur(${blur}px)` : 'none';
            for (let ox = -size; ox <= size; ox += size) {
                for (let oy = -size; oy <= size; oy += size) {
                    ctx.beginPath();
                    points.forEach((p, idx) => {
                        const x = p.x + ox;
                        const y = p.y + oy;
                        if (idx === 0) ctx.moveTo(x, y);
                        else ctx.lineTo(x, y);
                    });
                    ctx.stroke();
                }
            }
            ctx.restore();
        };

        for (let i = 0; i < 24; i++) {
            let x = Math.random() * size;
            let y = Math.random() * size;
            let angle = Math.random() * Math.PI * 2;
            const points = [{ x, y }];
            const steps = 5 + Math.floor(Math.random() * 4);
            for (let s = 0; s < steps; s++) {
                angle += (Math.random() - 0.5) * 0.95;
                const len = 30 + Math.random() * 52;
                x += Math.cos(angle) * len;
                y += Math.sin(angle) * len;
                points.push({ x, y });
            }
            drawWrappedPath(points, 'rgba(235,255,255,0.48)', 10.0, 5.0);
            drawWrappedPath(points, 'rgba(255,255,255,0.82)', 2.0, 0);
        }

        const tex = new THREE.CanvasTexture(canvas);
        tex.colorSpace = THREE.SRGBColorSpace;
        tex.wrapS = THREE.RepeatWrapping;
        tex.wrapT = THREE.RepeatWrapping;
        tex.repeat.set(7.0, 7.0);
        tex.generateMipmaps = false;
        tex.minFilter = THREE.LinearFilter;
        tex.magFilter = THREE.LinearFilter;
        tex.anisotropy = 16;
        return tex;
    }

    function setWaterFloorAlpha(alpha) {
        if (!waterFloor || !waterFloor.material) return;
        const clamped = Math.max(0, Math.min(1, alpha));
        waterFloor.material.opacity = clamped;
        const waveOverlay = waterFloor.userData && waterFloor.userData.waveOverlay;
        if (waveOverlay && waveOverlay.material) {
            waveOverlay.material.opacity = clamped * 0.32; // köpük katmanı (eskiden kapalıydı)
        }
    }

    function setWaterFloorTime(value) {
        if (!waterFloor || !waterFloor.material || !waterFloor.material.map) return;
        const floorSize = waterFloor.userData.floorSize || 4000;
        const repeatX = waterFloor.material.map.repeat.x || 1;
        const virtualCenterX = waterFloor.position.x + worldScrollX;
        const worldLockedU = (virtualCenterX / floorSize) * repeatX;
        const u = ((worldLockedU + value * 0.0018) % 1 + 1) % 1;
        // Keep lateral phase fixed. Only forward flow is animated, preventing
        // the ocean from sliding sideways while preserving subtle movement.
        const v = 0;
        [waterFloor.material.map, waterFloor.material.emissiveMap, waterFloor.material.normalMap, waterFloor.material.roughnessMap]
            .filter(Boolean)
            .forEach((texture) => { texture.offset.set(u, v); });
        const waveOverlay = waterFloor.userData && waterFloor.userData.waveOverlay;
        if (waveOverlay && waveOverlay.material && waveOverlay.material.map) {
            waveOverlay.material.map.offset.x = ((worldLockedU + value * 0.0026) % 1 + 1) % 1;
            waveOverlay.material.map.offset.y = 0;
        }
    }

    function createWaterNormalTexture() {
        const size = 256;
        const data = new Uint8Array(size * size * 4);
        for (let y = 0; y < size; y++) {
            for (let x = 0; x < size; x++) {
                const u = (x / size) * Math.PI * 2;
                const v = (y / size) * Math.PI * 2;
                const dx = Math.cos(u * 3.0 + v * 1.2) * 0.62
                    + Math.cos(u * 7.0 - v * 2.1) * 0.24
                    + Math.sin(v * 11.0 + u) * 0.14;
                const dy = Math.sin(v * 4.0 - u * 1.4) * 0.58
                    + Math.sin(v * 8.0 + u * 2.2) * 0.27
                    + Math.cos(u * 13.0 - v) * 0.15;
                const invLength = 1 / Math.sqrt(dx * dx + dy * dy + 2.25);
                const offset = (y * size + x) * 4;
                data[offset] = Math.round((dx * invLength * 0.5 + 0.5) * 255);
                data[offset + 1] = Math.round((dy * invLength * 0.5 + 0.5) * 255);
                data[offset + 2] = Math.round((1.5 * invLength * 0.5 + 0.5) * 255);
                data[offset + 3] = 255;
            }
        }
        const texture = new THREE.DataTexture(data, size, size, THREE.RGBAFormat);
        texture.colorSpace = THREE.NoColorSpace;
        texture.wrapS = THREE.RepeatWrapping;
        texture.wrapT = THREE.RepeatWrapping;
        texture.repeat.set(14, 20);
        texture.minFilter = THREE.LinearMipmapLinearFilter;
        texture.magFilter = THREE.LinearFilter;
        texture.generateMipmaps = true;
        texture.anisotropy = Math.min(8, renderer?.capabilities?.getMaxAnisotropy?.() || 1);
        texture.needsUpdate = true;
        return texture;
    }

    function samplePeriodicWater(u, v) {
        const tau = Math.PI * 2;
        return Math.sin(tau * (u * 3 + v * 0.75)) * 0.48
            + Math.sin(tau * (v * 5 - u * 1.25)) * 0.29
            + Math.sin(tau * (u * 8 + v * 7)) * 0.13
            + Math.cos(tau * (u * 13 - v * 4)) * 0.07;
    }

    function createSeamlessWaterSurfaceTextures() {
        const size = isMobilePerformanceGraphics() ? 256 : 512;
        const normalData = new Uint8Array(size * size * 4);
        const roughnessData = new Uint8Array(size * size * 4);
        const foamData = new Uint8Array(size * size * 4);
        const step = 1 / size;
        for (let y = 0; y < size; y++) {
            const v = y / size;
            for (let x = 0; x < size; x++) {
                const u = x / size;
                const height = samplePeriodicWater(u, v);
                const normalized = Math.max(0, Math.min(1, height * 0.5 + 0.5));
                const crest = Math.pow(Math.max(0, (Math.abs(height) - 0.34) / 0.63), 2.2);
                const i = (y * size + x) * 4;

                const dx = samplePeriodicWater((u + step) % 1, v) - samplePeriodicWater((u - step + 1) % 1, v);
                const dy = samplePeriodicWater(u, (v + step) % 1) - samplePeriodicWater(u, (v - step + 1) % 1);
                const nx = -dx * 6.2;
                const ny = -dy * 6.2;
                const inv = 1 / Math.sqrt(nx * nx + ny * ny + 1);
                normalData[i] = Math.round((nx * inv * 0.5 + 0.5) * 255);
                normalData[i + 1] = Math.round((ny * inv * 0.5 + 0.5) * 255);
                normalData[i + 2] = Math.round((inv * 0.5 + 0.5) * 255);
                normalData[i + 3] = 255;

                const rough = Math.round(192 + (1 - normalized) * 28 - crest * 24);
                roughnessData[i] = roughnessData[i + 1] = roughnessData[i + 2] = rough;
                roughnessData[i + 3] = 255;

                foamData[i] = 218;
                foamData[i + 1] = 250;
                foamData[i + 2] = 255;
                foamData[i + 3] = Math.round(Math.min(1, crest * 1.55) * 255);
            }
        }
        const repeatX = 8;
        const repeatY = 10;
        return {
            albedo: loadAuthoredFloorTexture('assets/textures/water-world-floor-v3.webp?v=1.7.0', repeatX, repeatY),
            normal: createRepeatSurfaceTexture(normalData, size, THREE.NoColorSpace, repeatX, repeatY),
            roughness: createRepeatSurfaceTexture(roughnessData, size, THREE.NoColorSpace, repeatX, repeatY),
            foam: createRepeatSurfaceTexture(foamData, size, THREE.SRGBColorSpace, repeatX, repeatY),
            repeatX,
            repeatY
        };
    }

    function createWaterFloor() {
        const surface = createSeamlessWaterSurfaceTextures();
        // v2 (2026-07-10): segmentli plane → hareketli okyanus kabarcıkları (vertex yer değiştirme).
        // 96 segment = ~9.4k vertex; buffer güncelleme ucuz (geometri YARATIMI değil, sadece yeniden yükleme).
        const geo = new THREE.PlaneGeometry(4000, 4000, 96, 96);
        const mat = new THREE.MeshStandardMaterial({
            color: 0xffffff,
            map: surface.albedo,
            emissive: 0x063b50,
            emissiveMap: surface.albedo,
            emissiveIntensity: 0.055,
            normalMap: surface.normal,
            normalScale: new THREE.Vector2(0.46, 0.39),
            roughnessMap: surface.roughness,
            roughness: 0.72,
            metalness: 0.0,
            envMapIntensity: 0.11,
            transparent: true,
            opacity: 0.0,
            depthWrite: true,
            fog: false
        });

        if (waterFloor && waterFloor.parent) {
            const oldWaveOverlay = waterFloor.userData && waterFloor.userData.waveOverlay;
            if (oldWaveOverlay) disposeNode(oldWaveOverlay);
            waterFloor.parent.remove(waterFloor);
            disposeNode(waterFloor);
        }

        waterFloor = new THREE.Mesh(geo, mat);
        waterFloor.rotation.x = -Math.PI / 2;
        // Water waves peak above their base plane. A deeper base prevents the
        // road shoulders from entering the animated surface on long curves.
        waterFloor.position.y = -4.35;
        waterFloor.visible = false;
        waterFloor.renderOrder = -1;
        // Kabarcık animasyonu için taban (düz) z değerleri ve çalışma tamponu
        waterFloor.userData.waveBaseZ = geo.attributes.position.array.slice();

        // Köpük overlay'i AYNI geometriyi paylaşır → dalgalarla birlikte deforme olur (köpük tepelerde durur)
        const waveOverlay = new THREE.Mesh(
            geo,
            new THREE.MeshBasicMaterial({
                map: surface.foam,
                color: 0xe5fdff,
                transparent: true,
                opacity: 0.0,
                side: THREE.DoubleSide,
                depthWrite: false,
                fog: false,
                blending: THREE.AdditiveBlending,
                polygonOffset: true,
                polygonOffsetFactor: -1,
                polygonOffsetUnits: 1
            })
        );
        waveOverlay.position.z = 0.35;
        waveOverlay.renderOrder = 0;
        waterFloor.add(waveOverlay);
        waterFloor.userData.waveOverlay = waveOverlay;
        waterFloor.userData.floorSize = 4000;
        scene.add(waterFloor);
        curvedPathSystem?.installObjectMaterials?.(waterFloor, { mode: 'sheet', baseY: 0, centerZ: getRoadCenterZ() });
    }

    // Okyanus yüzeyi: mesh kapsama amacıyla oyuncunun çevresinde yeniden merkezlenir,
    // fakat dalga fazı sanal dünya koordinatına kilitlidir; yüzey karakterle sürüklenmez.
    let _waterWaveClock = 0;
    function animateWaterSurface(worldX, delta) {
        if (!waterFloor || !waterFloor.visible) return;
        _waterWaveClock += delta;
        const t = _waterWaveClock;
        const pos = waterFloor.geometry.attributes.position;
        const base = waterFloor.userData.waveBaseZ;
        if (!base) return;
        const arr = pos.array;
        // PlaneGeometry XY düzleminde: x = arr[i], y = arr[i+1]; yükseklik z = arr[i+2] (döndürülünce dünya-Y)
        for (let i = 0; i < arr.length; i += 3) {
            const lx = base[i];
            const ly = base[i + 1];
            const wx = worldX + worldScrollX + lx;
            const z = Math.sin(wx * 0.018 + t * 1.1) * 0.56
                    + Math.sin(ly * 0.023 - t * 0.9) * 0.4
                    + Math.sin((wx + ly) * 0.031 + t * 1.7) * 0.24;
            arr[i + 2] = base[i + 2] + z;
        }
        pos.needsUpdate = true;
    }

    function createSnowTexture() {
        const size = 768;
        const canvas = document.createElement('canvas');
        canvas.width = size;
        canvas.height = size;
        const ctx = canvas.getContext('2d');
        const grad = ctx.createLinearGradient(0, 0, size, size * 0.92);
        grad.addColorStop(0, '#f7fdff');
        grad.addColorStop(0.28, '#e2f2fc');
        grad.addColorStop(0.62, '#c7e0f0');
        grad.addColorStop(1, '#a8c8dc');
        ctx.fillStyle = grad;
        ctx.fillRect(0, 0, size, size);

        const drawIcePlate = (cx, cy, radius, sides, rot, fill, stroke, alpha) => {
            ctx.save();
            ctx.translate(cx, cy);
            ctx.rotate(rot);
            ctx.beginPath();
            for (let i = 0; i < sides; i++) {
                const a = (i / sides) * Math.PI * 2;
                const r = radius * (0.72 + Math.random() * 0.5);
                const x = Math.cos(a) * r * (1.1 + Math.random() * 0.28);
                const y = Math.sin(a) * r * (0.45 + Math.random() * 0.2);
                if (i === 0) ctx.moveTo(x, y);
                else ctx.lineTo(x, y);
            }
            ctx.closePath();
            ctx.globalAlpha = alpha;
            ctx.fillStyle = fill;
            ctx.fill();
            ctx.globalAlpha = Math.min(1, alpha + 0.18);
            ctx.strokeStyle = stroke;
            ctx.lineWidth = 1.2 + Math.random() * 1.4;
            ctx.stroke();
            ctx.restore();
            ctx.globalAlpha = 1;
        };

        for (let i = 0; i < 26; i++) {
            drawIcePlate(
                Math.random() * size,
                Math.random() * size,
                44 + Math.random() * 128,
                7 + Math.floor(Math.random() * 5),
                Math.random() * Math.PI,
                i % 3 === 0 ? '#f9feff' : '#dbeefa',
                i % 4 === 0 ? 'rgba(72,139,174,0.28)' : 'rgba(255,255,255,0.52)',
                0.13 + Math.random() * 0.18
            );
        }

        const drawCrack = (x, y, len, angle, width, deep = false) => {
            ctx.save();
            ctx.translate(x, y);
            ctx.rotate(angle);
            ctx.beginPath();
            const pts = 8 + Math.floor(Math.random() * 7);
            for (let i = 0; i < pts; i++) {
                const t = i / (pts - 1);
                const px = (t - 0.5) * len;
                const py = Math.sin(t * Math.PI * 3.0 + x * 0.01) * width * 1.1
                    + (i % 2 === 0 ? -1 : 1) * width * (0.32 + Math.random() * 0.75);
                if (i === 0) ctx.moveTo(px, py);
                else ctx.lineTo(px, py);
            }
            ctx.strokeStyle = deep ? 'rgba(5,55,88,0.54)' : 'rgba(48,116,154,0.30)';
            ctx.lineWidth = deep ? Math.max(1.1, width * 0.55) : Math.max(0.35, width * 0.22);
            ctx.lineCap = 'round';
            ctx.lineJoin = 'round';
            ctx.stroke();
            ctx.strokeStyle = deep ? 'rgba(228,250,255,0.48)' : 'rgba(255,255,255,0.32)';
            ctx.lineWidth = deep ? Math.max(0.35, width * 0.16) : 0.25;
            ctx.stroke();
            ctx.restore();
        };

        for (let i = 0; i < 56; i++) {
            drawCrack(
                Math.random() * size,
                Math.random() * size,
                80 + Math.random() * 260,
                Math.random() * Math.PI,
                1.2 + Math.random() * 3.8,
                i % 4 === 0
            );
        }

        for (let i = 0; i < 320; i++) {
            drawCrack(
                Math.random() * size,
                Math.random() * size,
                14 + Math.random() * 52,
                Math.random() * Math.PI * 2,
                0.35 + Math.random() * 0.8,
                false
            );
        }

        for (let i = 0; i < 6200; i++) {
            const x = Math.random() * size;
            const y = Math.random() * size;
            const r = 0.4 + Math.random() * 1.7;
            const a = 0.045 + Math.random() * 0.18;
            ctx.fillStyle = Math.random() > 0.22
                ? `rgba(255,255,255,${a})`
                : `rgba(116,157,196,${a * 0.55})`;
            ctx.beginPath();
            ctx.arc(x, y, r, 0, Math.PI * 2);
            ctx.fill();
        }

        const tex = new THREE.CanvasTexture(canvas);
        tex.colorSpace = THREE.SRGBColorSpace;
        tex.wrapS = THREE.RepeatWrapping;
        tex.wrapT = THREE.RepeatWrapping;
        tex.repeat.set(SNOW_FLOOR_TEXTURE_REPEAT, SNOW_FLOOR_TEXTURE_REPEAT);
        tex.generateMipmaps = true;
        tex.minFilter = THREE.LinearMipmapLinearFilter;
        tex.magFilter = THREE.LinearFilter;
        tex.anisotropy = 12;
        tex.userData = {
            antarcticTexture: true,
            icePlateCount: 26,
            microCrackCount: 320,
            crackStyle: 'antarctic_plate_cracks',
            removedDistantLeads: true
        };
        return tex;
    }

    // Buz ışıltısı dokusu: seyrek küçük parlak noktalar (additive katmanda parıltı verir)
    function createSnowSparkleTexture() {
        const size = 512;
        const canvas = document.createElement('canvas');
        canvas.width = size;
        canvas.height = size;
        const ctx = canvas.getContext('2d');
        ctx.clearRect(0, 0, size, size);
        for (let i = 0; i < 340; i++) {
            const x = Math.random() * size;
            const y = Math.random() * size;
            const r = 0.5 + Math.random() * 1.4;
            const a = 0.25 + Math.random() * 0.75;
            const warm = Math.random() < 0.18;
            const g = ctx.createRadialGradient(x, y, 0, x, y, r * 2.4);
            g.addColorStop(0, warm ? `rgba(255,244,214,${a})` : `rgba(235,250,255,${a})`);
            g.addColorStop(0.5, warm ? `rgba(255,244,214,${a * 0.35})` : `rgba(200,240,255,${a * 0.35})`);
            g.addColorStop(1, 'rgba(0,0,0,0)');
            ctx.fillStyle = g;
            ctx.beginPath();
            ctx.arc(x, y, r * 2.4, 0, Math.PI * 2);
            ctx.fill();
        }
        const tex = new THREE.CanvasTexture(canvas);
        tex.colorSpace = THREE.SRGBColorSpace;
        tex.wrapS = THREE.RepeatWrapping;
        tex.wrapT = THREE.RepeatWrapping;
        tex.repeat.set(SNOW_SPARKLE_TEXTURE_REPEAT, SNOW_SPARKLE_TEXTURE_REPEAT);
        tex.generateMipmaps = false;
        tex.minFilter = THREE.LinearFilter;
        tex.magFilter = THREE.LinearFilter;
        tex.anisotropy = 8;
        return tex;
    }

    function setSnowFloorAlpha(alpha) {
        if (!snowFloor || !snowFloor.material) return;
        const clamped = Math.max(0, Math.min(1, alpha));
        const requiresFadeBlend = clamped < 0.999;
        if (snowFloor.material.transparent !== requiresFadeBlend) {
            snowFloor.material.transparent = requiresFadeBlend;
            snowFloor.material.needsUpdate = true;
        }
        snowFloor.material.opacity = clamped;
        snowFloor.material.depthWrite = true;
        snowFloor.visible = clamped > 0.01;
        const sparkleOverlay = snowFloor.userData && snowFloor.userData.sparkleOverlay;
        if (sparkleOverlay && sparkleOverlay.material) {
            const fadeRatio = Math.max(0, Math.min(1, clamped / SNOW_FLOOR_TARGET_ALPHA));
            sparkleOverlay.visible = snowFloor.visible && fadeRatio > 0.02;
            sparkleOverlay.material.opacity = 0.34 * fadeRatio;
        }
        const seaLeads = snowFloor.userData && snowFloor.userData.seaLeads;
        if (seaLeads && seaLeads.userData) {
            const fadeRatio = Math.max(0, Math.min(1, clamped / SNOW_FLOOR_TARGET_ALPHA));
            seaLeads.visible = snowFloor.visible && fadeRatio > 0.02;
            const waterMat = seaLeads.userData.waterMaterial;
            const rimMat = seaLeads.userData.rimMaterial;
            if (waterMat) waterMat.opacity = (seaLeads.userData.baseWaterOpacity || 0.88) * fadeRatio;
            if (rimMat) rimMat.opacity = (seaLeads.userData.baseRimOpacity || 0.58) * fadeRatio;
        }
        const crackOverlay = snowFloor.userData && snowFloor.userData.crackOverlay;
        if (crackOverlay && crackOverlay.userData) {
            const fadeRatio = Math.max(0, Math.min(1, clamped / SNOW_FLOOR_TARGET_ALPHA));
            crackOverlay.visible = snowFloor.visible && fadeRatio > 0.03;
            crackOverlay.children.forEach((mesh) => {
                if (!mesh.material) return;
                mesh.material.opacity = (mesh.userData.baseOpacity || 0.32) * fadeRatio;
            });
        }
    }

    function setSnowFloorTime(value) {
        if (!snowFloor || !snowFloor.material || !snowFloor.material.map) return;
        // Mesh geniş alanı sürekli örtmek için oyuncuyu takip eder; desen ise sanal dünya-X'e
        // kilitlenir. Böylece sabit-karakter mimarisinde kar karaktere yapışmaz, dünya ile akar.
        const virtualCenterX = (player ? player.position.x : snowFloor.position.x) + worldScrollX;
        const textureScroll = (virtualCenterX / SNOW_FLOOR_SIZE) * SNOW_FLOOR_TEXTURE_REPEAT;
        snowFloor.material.map.offset.x = ((textureScroll % 1) + 1) % 1;
        snowFloor.material.map.offset.y = 0;
        if (snowFloor.material.normalMap) {
            snowFloor.material.normalMap.offset.x = snowFloor.material.map.offset.x;
            snowFloor.material.normalMap.offset.y = 0;
        }
        if (snowFloor.material.roughnessMap) {
            snowFloor.material.roughnessMap.offset.x = snowFloor.material.map.offset.x;
            snowFloor.material.roughnessMap.offset.y = 0;
        }
        const sparkleMap = snowFloor.userData?.sparkleOverlay?.material?.map;
        if (sparkleMap) {
            // Parıltı da aynı dünya hareketini izler; üstüne yalnız çok küçük bir ışıldama eklenir.
            const sparkleScroll = (virtualCenterX / SNOW_FLOOR_SIZE) * SNOW_SPARKLE_TEXTURE_REPEAT + Math.sin(value * 0.6) * 0.0016;
            sparkleMap.offset.x = ((sparkleScroll % 1) + 1) % 1;
            sparkleMap.offset.y = Math.cos(value * 0.5) * 0.0016;
        }
        const crackOverlay = snowFloor.userData?.crackOverlay;
        if (crackOverlay) {
            const crackTravel = ((virtualCenterX % SNOW_CRACK_REPEAT_DISTANCE) + SNOW_CRACK_REPEAT_DISTANCE) % SNOW_CRACK_REPEAT_DISTANCE;
            crackOverlay.position.x = -crackTravel;
        }
        const seaLeadWaterMat = snowFloor.userData?.seaLeads?.userData?.waterMaterial;
        if (seaLeadWaterMat && seaLeadWaterMat.map) {
            seaLeadWaterMat.map.offset.x = value * 0.0035;
            seaLeadWaterMat.map.offset.y = value * 0.006;
            if (seaLeadWaterMat.emissiveMap) {
                seaLeadWaterMat.emissiveMap.offset.x = seaLeadWaterMat.map.offset.x;
                seaLeadWaterMat.emissiveMap.offset.y = seaLeadWaterMat.map.offset.y;
            }
        }
        updateSnowSeaLeads();
    }

    function getSnowTerrainElevation(x, y, roadSafeHalfWidth) {
        const distFromRoad = Math.max(0, Math.abs(y) - roadSafeHalfWidth);
        const sideBlend = Math.min(1, distFromRoad / 360);
        const broad = Math.sin(x * 0.006) * Math.cos(y * 0.005) * 1.35;
        const cross = Math.sin((x + y) * 0.012) * 0.62;
        const ridge = Math.max(0, Math.sin(x * 0.019 + y * 0.008)) * 0.58;
        const windPacked = Math.sin(x * 0.047 + Math.cos(y * 0.013) * 2.4) * 0.18;
        const shelfBreak = Math.max(0, 1 - Math.abs(Math.sin(x * 0.011 + y * 0.017)) * 6.0) * 1.1;
        const hardIcePlate = Math.max(0, Math.sin(x * 0.026 - y * 0.019)) * 0.48;
        return (broad + cross + ridge + windPacked + hardIcePlate - shelfBreak) * sideBlend;
    }

    function createSnowIceCrackOverlay(roadSafeHalfWidth) {
        const group = new THREE.Group();
        const crackGeo = new THREE.PlaneGeometry(1, 1);
        const deepCrackMat = new THREE.MeshBasicMaterial({
            color: 0x0b577c,
            transparent: true,
            opacity: 0.48,
            depthWrite: false,
            fog: false
        });
        const frostEdgeMat = new THREE.MeshBasicMaterial({
            color: 0xf4fdff,
            transparent: true,
            opacity: 0.34,
            depthWrite: false,
            fog: false
        });
        const deepCracks = [];
        const frostEdges = [];

        for (let side of [-1, 1]) {
            for (let i = 0; i < 86; i++) {
                const x = -1900 + Math.random() * 3800;
                const lateral = side * (roadSafeHalfWidth + 4 + Math.random() * 310);
                const len = 18 + Math.random() * (i % 5 === 0 ? 165 : 72);
                const width = 0.22 + Math.random() * (i % 5 === 0 ? 0.9 : 0.42);
                const angle = (Math.random() - 0.5) * (i % 6 === 0 ? 1.45 : 0.72);
                const lift = getSnowTerrainElevation(x, lateral, roadSafeHalfWidth) + 0.48 + Math.random() * 0.08;
                deepCracks.push({
                    x,
                    y: lateral,
                    z: lift,
                    rz: angle,
                    sx: len,
                    sy: width,
                    sz: 1
                });
                if (i % 2 === 0) {
                    frostEdges.push({
                        x: x + Math.sin(angle) * width * 1.8,
                        y: lateral - Math.cos(angle) * width * 1.8,
                        z: lift + 0.012,
                        rz: angle,
                        sx: len * (0.82 + Math.random() * 0.24),
                        sy: Math.max(0.1, width * 0.58),
                        sz: 1
                    });
                }
            }
        }

        const deepMesh = addInstancedDecor(group, crackGeo, deepCrackMat, deepCracks, { name: 'snowDeepIceCracks' });
        const frostMesh = addInstancedDecor(group, crackGeo, frostEdgeMat, frostEdges, { name: 'snowFrostCrackEdges' });
        if (deepMesh) deepMesh.userData.baseOpacity = deepCrackMat.opacity;
        if (frostMesh) frostMesh.userData.baseOpacity = frostEdgeMat.opacity;
        // Çatlak alanını ileri yönde bir kez tekrarla. Katman sanal dünya mesafesiyle
        // geriye kayarken ikinci kopya önden kesintisiz girer; karaktere yapışık kalmaz.
        if (deepMesh) {
            const repeatDeep = deepMesh.clone();
            repeatDeep.position.x += SNOW_CRACK_REPEAT_DISTANCE;
            repeatDeep.name = 'snowDeepIceCracksRepeat';
            group.add(repeatDeep);
        }
        if (frostMesh) {
            const repeatFrost = frostMesh.clone();
            repeatFrost.position.x += SNOW_CRACK_REPEAT_DISTANCE;
            repeatFrost.name = 'snowFrostCrackEdgesRepeat';
            group.add(repeatFrost);
        }
        group.userData = {
            type: 'snow_ice_crack_overlay',
            crackCount: deepCracks.length,
            frostEdgeCount: frostEdges.length,
            repeatDistance: SNOW_CRACK_REPEAT_DISTANCE,
            worldStable: true
        };
        return group;
    }

    function createSnowSeaLeadGeometry(length, width, seed, centerX, centerY, rot, lift, roadSafeHalfWidth) {
        const geo = new THREE.PlaneGeometry(length, width, 14, 3);
        const pos = geo.attributes.position;
        const cosR = Math.cos(rot);
        const sinR = Math.sin(rot);
        for (let p = 0; p < pos.count; p++) {
            const px = pos.getX(p);
            const py = pos.getY(p);
            const t = (px / length) + 0.5;
            const seg = Math.floor(t * 10.0);
            const taper = 1 - Math.min(1, Math.abs(px) / (length * 0.5));
            const centerWobble = Math.sin(t * Math.PI * 5.4 + seed) * width * 0.34
                + (seg % 2 === 0 ? -1 : 1) * width * (0.18 + taper * 0.18);
            const edge = Math.sign(py || 1) * Math.pow(Math.abs(py) / (width * 0.5), 1.8) * width * 0.12 * Math.sin(t * Math.PI * 9.0 + seed);
            const localY = py * (0.18 + taper * 0.9) + centerWobble + edge;
            pos.setY(p, localY);
            const floorX = centerX + px * cosR - localY * sinR;
            const floorY = centerY + px * sinR + localY * cosR;
            pos.setZ(p, getSnowTerrainElevation(floorX, floorY, roadSafeHalfWidth) + lift);
        }
        geo.computeVertexNormals();
        return geo;
    }

    function positionSnowSeaLeadPair(pair) {
        if (!pair || !snowFloor) return;
        const floorVirtualX = snowFloor.position.x + worldScrollX;
        const localX = pair.worldX - floorVirtualX;
        pair.lead.position.set(localX, pair.lateralY, 0);
        pair.rim.position.set(localX, pair.lateralY, 0);
    }

    function resetSnowSeaLeadPair(pair, worldX, side, roadSafeHalfWidth) {
        const length = 70 + Math.random() * 155;
        const width = 5.5 + Math.random() * 15.5;
        const lateralY = side * (roadSafeHalfWidth + 18 + Math.random() * 172);
        const seed = Math.random() * Math.PI * 2;
        const rot = (Math.random() - 0.5) * 0.58 + side * 0.04;

        pair.worldX = worldX;
        pair.side = side;
        pair.lateralY = lateralY;
        pair.length = length;
        pair.width = width;
        pair.seed = seed;
        pair.rot = rot;

        if (pair.lead.geometry) pair.lead.geometry.dispose();
        if (pair.rim.geometry) pair.rim.geometry.dispose();
        pair.lead.geometry = createSnowSeaLeadGeometry(length, width, seed, worldX, lateralY, rot, 0.38, roadSafeHalfWidth);
        pair.rim.geometry = createSnowSeaLeadGeometry(length * 1.04, width + 5.6, seed, worldX, lateralY, rot, 0.32, roadSafeHalfWidth);
        pair.lead.rotation.z = rot;
        pair.rim.rotation.z = rot;
        positionSnowSeaLeadPair(pair);
    }

    function updateSnowSeaLeads() {
        const seaLeads = snowFloor?.userData?.seaLeads;
        const pairs = seaLeads?.userData?.pairs;
        if (!snowFloor || !player || !Array.isArray(pairs)) return;
        const roadSafeHalfWidth = seaLeads.userData.roadSafeHalfWidth || Math.max(getRoadHalfWidth() + 42, 58);
        const playerVirtualX = player.position.x + worldScrollX;
        pairs.forEach((pair, idx) => {
            if (pair.worldX < playerVirtualX - 280 || pair.worldX > playerVirtualX + 860) {
                const resetX = playerVirtualX + 260 + Math.random() * 520;
                const side = idx % 2 === 0 ? 1 : -1;
                resetSnowSeaLeadPair(pair, resetX, side, roadSafeHalfWidth);
            } else {
                positionSnowSeaLeadPair(pair);
            }
        });
        const widths = pairs.map(pair => pair.width || 0);
        seaLeads.userData.minLeadWidth = Math.min(...widths);
        seaLeads.userData.maxLeadWidth = Math.max(...widths);
        snowFloor.userData.seaLeadMinWidth = seaLeads.userData.minLeadWidth;
        snowFloor.userData.seaLeadMaxWidth = seaLeads.userData.maxLeadWidth;
    }

    function createSnowSeaLeadOverlay(roadSafeHalfWidth) {
        const group = new THREE.Group();
        const leadWaterTex = createWaterTexture();
        leadWaterTex.repeat.set(3.1, 1.8);
        leadWaterTex.userData = { source: 'water_floor_texture', forSnowIceCracks: true };
        const leadMat = new THREE.MeshStandardMaterial({
            color: 0x0e6a8f,
            map: leadWaterTex,
            emissive: 0x02384f,
            emissiveMap: leadWaterTex,
            emissiveIntensity: 0.16,
            roughness: 0.18,
            metalness: 0.02,
            transparent: true,
            opacity: 0.76,
            depthWrite: false,
            fog: false
        });
        leadMat.userData = { usesWaterFloorTexture: true };
        const rimMat = new THREE.MeshBasicMaterial({
            color: 0xe9fcff,
            transparent: true,
            opacity: 0.5,
            depthWrite: false,
            fog: false
        });
        const count = 34;
        let maxLeadWidth = 0;
        let minLeadWidth = Infinity;
        const pairs = [];
        const floorCenterX = player ? player.position.x + worldScrollX : worldScrollX;
        for (let i = 0; i < count; i++) {
            const side = i % 2 === 0 ? 1 : -1;
            const worldX = floorCenterX - 340 + Math.random() * 1360;
            const z = side * (roadSafeHalfWidth + 18 + Math.random() * 172);
            const length = 70 + Math.random() * 155;
            const width = 5.5 + Math.random() * 15.5;
            maxLeadWidth = Math.max(maxLeadWidth, width);
            minLeadWidth = Math.min(minLeadWidth, width);
            const seed = i * 1.73 + Math.random() * 0.5;
            const rot = (Math.random() - 0.5) * 0.58 + side * 0.04;
            const leadGeo = createSnowSeaLeadGeometry(length, width, seed, worldX, z, rot, 0.38, roadSafeHalfWidth);
            const lead = new THREE.Mesh(leadGeo, leadMat);
            lead.position.set(worldX - floorCenterX, z, 0);
            lead.rotation.z = rot;
            lead.renderOrder = 2;
            group.add(lead);

            const rim = new THREE.Mesh(createSnowSeaLeadGeometry(length * 1.04, width + 5.6, seed, worldX, z, rot, 0.32, roadSafeHalfWidth), rimMat);
            rim.position.set(worldX - floorCenterX, z, 0);
            rim.rotation.z = rot;
            rim.renderOrder = 1;
            group.add(rim);

            pairs.push({ lead, rim, side, worldX, lateralY: z, length, width, seed, rot });
        }
        group.userData = {
            type: 'snow_sea_leads',
            seaLeadCount: count,
            crackStyle: 'antarctic_open_water_leads',
            usesWaterFloorTexture: true,
            removedDistantLeads: true,
            terrainConformed: true,
            worldStable: true,
            roadSafeHalfWidth,
            pairs,
            waterMaterial: leadMat,
            rimMaterial: rimMat,
            baseWaterOpacity: leadMat.opacity,
            baseRimOpacity: rimMat.opacity,
            maxLeadWidth,
            minLeadWidth
        };
        return group;
    }

    function createSnowFloor() {
        const tex = createSnowTexture();
        const snowPbr = getFloorPbrDetails('snow', SNOW_FLOOR_TEXTURE_REPEAT, SNOW_FLOOR_TEXTURE_REPEAT);
        const snowSegments = isMobilePerformanceGraphics() ? 40 : 80;
        const geo = new THREE.PlaneGeometry(SNOW_FLOOR_SIZE, SNOW_FLOOR_SIZE, snowSegments, snowSegments);
        const pos = geo.attributes.position;
        const roadSafeHalfWidth = Math.max(getRoadHalfWidth() + 54, 70);
        for (let i = 0; i < pos.count; i++) {
            const x = pos.getX(i);
            const y = pos.getY(i);
            pos.setZ(i, getSnowTerrainElevation(x, y, roadSafeHalfWidth));
        }
        geo.computeVertexNormals();
        // v2 (2026-07-10): hafif buz parlaklığı (roughness ↓) + emissive dokunuşu
        const mat = new THREE.MeshStandardMaterial({
            color: 0xeef8ff,
            map: tex,
            normalMap: snowPbr.normalMap,
            normalScale: new THREE.Vector2(0.18, 0.18),
            roughnessMap: snowPbr.roughnessMap,
            emissive: 0xa8cfe7,
            emissiveMap: tex,
            emissiveIntensity: 0.055,
            roughness: 0.82,
            metalness: 0.01,
            envMapIntensity: 0.12,
            transparent: true,
            opacity: 0.0,
            depthWrite: true,
            fog: false
        });

        if (snowFloor && snowFloor.parent) {
            snowFloor.parent.remove(snowFloor);
            disposeNode(snowFloor);
        }

        snowFloor = new THREE.Mesh(geo, mat);
        snowFloor.rotation.x = -Math.PI / 2;
        snowFloor.position.y = -2.64;
        snowFloor.visible = false;
        snowFloor.frustumCulled = false;
        snowFloor.renderOrder = -1;
        const crackOverlay = createSnowIceCrackOverlay(roadSafeHalfWidth);
        const seaLeads = createSnowSeaLeadOverlay(roadSafeHalfWidth);
        snowFloor.add(crackOverlay);
        snowFloor.add(seaLeads);

        // v2 (2026-07-10): buz ışıltısı katmanı — AYNI arazi geometrisini paylaşır (kabartmaya
        // oturur), additive küçük parlak noktalar güneşte parıldayan kar hissi verir.
        const sparkleOverlay = new THREE.Mesh(
            geo,
            new THREE.MeshBasicMaterial({
                map: createSnowSparkleTexture(),
                color: 0xffffff,
                transparent: true,
                opacity: 0.0,
                depthWrite: false,
                fog: false,
                blending: THREE.AdditiveBlending,
                polygonOffset: true,
                polygonOffsetFactor: -1,
                polygonOffsetUnits: 1
            })
        );
        sparkleOverlay.position.z = 0.18;
        sparkleOverlay.renderOrder = 0;
        snowFloor.add(sparkleOverlay);
        snowFloor.traverse((child) => {
            if (child?.isMesh || child?.isLine || child?.isPoints) child.frustumCulled = false;
        });
        snowFloor.userData = {
            sparkleOverlay,
            antarcticTexture: true,
            seaLeadCount: seaLeads.userData.seaLeadCount,
            crackStyle: seaLeads.userData.crackStyle,
            iceCrackCount: crackOverlay.userData.crackCount,
            frostEdgeCount: crackOverlay.userData.frostEdgeCount,
            seaLeadMaxWidth: seaLeads.userData.maxLeadWidth,
            seaLeadMinWidth: seaLeads.userData.minLeadWidth,
            usesWaterFloorTexture: seaLeads.userData.usesWaterFloorTexture,
            terrainConformedSeaLeads: seaLeads.userData.terrainConformed,
            worldStableSeaLeads: seaLeads.userData.worldStable,
            crackOverlay,
            seaLeads
        };
        scene.add(snowFloor);
        curvedPathSystem?.installObjectMaterials?.(snowFloor);
    }

    function createSnowFlurries() {
        if (snowFlurries) disposeNode(snowFlurries);
        const count = isMobilePerformanceGraphics() ? 130 : 420;
        const geo = new THREE.BufferGeometry();
        const positions = new Float32Array(count * 3);
        snowFlurryData = [];
        for (let i = 0; i < count; i++) {
            const relX = -260 + Math.random() * 1700;
            const y = 18 + Math.random() * 92;
            const z = (Math.random() - 0.5) * 440;
            positions[i * 3] = player ? player.position.x + relX : relX;
            positions[i * 3 + 1] = y;
            positions[i * 3 + 2] = z;
            snowFlurryData.push({
                relX,
                y,
                z,
                speed: 5 + Math.random() * 16,
                drift: (Math.random() - 0.5) * 11,
                phase: Math.random() * Math.PI * 2
            });
        }
        geo.setAttribute('position', new THREE.BufferAttribute(positions, 3).setUsage(THREE.DynamicDrawUsage));
        r185OptimizationStats.dynamicBufferHints += 1;
        const mat = new THREE.PointsMaterial({
            color: 0xffffff,
            size: 1.5,
            transparent: true,
            opacity: 0.0,
            depthWrite: false,
            fog: true
        });
        snowFlurries = new THREE.Points(geo, mat);
        snowFlurries.visible = false;
        snowFlurries.userData.worldRebaseExempt = true; // buffer dünya-uzayı; applyWorldRebase kaydırır
        scene.add(snowFlurries);
        createSnowAurora();
    }

    // Kutup ışıkları dokusu: yatay parıltı bandı + aşağı sarkan dikey ışık huzmeleri
    // v2 (2026-07-10, "çok düz duruyor" fix): daha yoğun/doygun huzme deseni — açık kar
    // gökyüzünde (0xd8e9f7) additive blend soluk kalıyordu, alpha/yoğunluk belirgin arttırıldı.
    function createSnowAuroraTexture() {
        const w = 512, h = 320;
        const canvas = document.createElement('canvas');
        canvas.width = w;
        canvas.height = h;
        const ctx = canvas.getContext('2d');
        ctx.clearRect(0, 0, w, h);
        const bandY = h * 0.42;
        const colors = [
            [70, 255, 150],  // yeşil (baskın)
            [50, 235, 220],  // teal
            [175, 110, 255]  // mor (nadir)
        ];
        for (let i = 0; i < 34; i++) {
            const x = Math.random() * w;
            const bw = 14 + Math.random() * 34;
            const len = 100 + Math.random() * 190;
            const c = colors[Math.random() < 0.55 ? 0 : (Math.random() < 0.72 ? 1 : 2)];
            const a = 0.45 + Math.random() * 0.5;
            const g = ctx.createLinearGradient(0, bandY - 22, 0, bandY + len);
            g.addColorStop(0, `rgba(${c[0]},${c[1]},${c[2]},0)`);
            g.addColorStop(0.14, `rgba(${c[0]},${c[1]},${c[2]},${a})`);
            g.addColorStop(0.5, `rgba(${c[0]},${c[1]},${c[2]},${a * 0.5})`);
            g.addColorStop(1, `rgba(${c[0]},${c[1]},${c[2]},0)`);
            ctx.fillStyle = g;
            // kenarları yumuşak dikey huzme (üstte dar, altta hafif genişleyen)
            ctx.save();
            ctx.filter = 'blur(3px)';
            ctx.beginPath();
            ctx.moveTo(x - bw * 0.5, bandY - 16);
            ctx.lineTo(x + bw * 0.5, bandY - 16);
            ctx.lineTo(x + bw * 0.85, bandY + len);
            ctx.lineTo(x - bw * 0.85, bandY + len);
            ctx.closePath();
            ctx.fill();
            ctx.restore();
        }
        // bandın kendisi: tüm genişlikte yumuşak yatay parıltı (daha güçlü, sabit çekirdek)
        const bg = ctx.createLinearGradient(0, bandY - 34, 0, bandY + 56);
        bg.addColorStop(0, 'rgba(100,255,190,0)');
        bg.addColorStop(0.4, 'rgba(100,255,190,0.5)');
        bg.addColorStop(1, 'rgba(100,255,190,0)');
        ctx.fillStyle = bg;
        ctx.fillRect(0, bandY - 34, w, 90);
        const tex = new THREE.CanvasTexture(canvas);
        tex.colorSpace = THREE.SRGBColorSpace;
        tex.wrapS = THREE.RepeatWrapping;
        tex.wrapT = THREE.ClampToEdgeWrapping;
        tex.generateMipmaps = false;
        tex.minFilter = THREE.LinearFilter;
        tex.magFilter = THREE.LinearFilter;
        return tex;
    }

    // Dalgalı perde geometrisi: düz PlaneGeometry yerine segmentli, Z-eksende bükülmüş
    // "ribbon" (sky/lava jitter kalıbı) — kart gibi değil, süzülen kumaş gibi görünür.
    // Kenarlar vertex-color ile siyaha soldurulur (additive'de = alfa fade), sert dikdörtgen
    // silüeti kaybolur. Taban (y=0) sabit, tepe daha çok dalgalanır (asılı kumaş hissi).
    function buildAuroraCurtainGeometry(w, h, seed) {
        const segX = 56, segY = 3; // v3: 44→56, büyümüş genişlikte dalga pürüzsüz kalsın
        const geo = new THREE.PlaneGeometry(w, h, segX, segY);
        const rnd = natSeedRand(seed);
        const waves1 = 2 + Math.floor(rnd() * 2);
        const waves2 = 5 + Math.floor(rnd() * 3);
        const amp1 = w * (0.05 + rnd() * 0.035);
        const amp2 = w * 0.016;
        const ph1 = rnd() * Math.PI * 2;
        const ph2 = rnd() * Math.PI * 2;
        const pos = geo.attributes.position;
        const col = new Float32Array(pos.count * 3);
        for (let i = 0; i < pos.count; i++) {
            const x = pos.getX(i);
            const y = pos.getY(i);
            const u = x / w + 0.5;
            const vNorm = y / h + 0.5; // 0 taban, 1 tepe
            const anchor = 0.3 + vNorm * 0.7;
            const z = (Math.sin(u * Math.PI * 2 * waves1 + ph1) * amp1
                     + Math.sin(u * Math.PI * 2 * waves2 + ph2) * amp2) * anchor;
            pos.setZ(i, z);
            const edgeFade = Math.min(1, Math.min(u, 1 - u) / 0.14);
            col[i * 3] = col[i * 3 + 1] = col[i * 3 + 2] = edgeFade;
        }
        geo.setAttribute('color', new THREE.BufferAttribute(col, 3));
        return geo;
    }

    // v2 (2026-07-10, "çok düz duruyor" fix): eski yerleşim yolun YANINDA (z=±420) idi —
    // kamera dikeyde 110° FOV ile ama pitch=0 dümdüz ileri baktığından bu perdelerin çoğu
    // görüş alanının tamamen dışında kalıyordu, sadece kenardan soluk bir şerit sızıyordu
    // (ölçüldü: aurora-project2.js, curtain merkezi kamera arkasında/dışında çıktı). Güneşin
    // kanıtlanmış kalıbı kopyalandı (`cyberSun.position.x = player.x+800`, bkz. satır ~12860):
    // perdeler artık YOLUN TAM ÖNÜNDE (x=forward offset), genişlik ekseni Z'ye çevrildi
    // (rotation.y≈90°) → dalga artık kameraya doğru/uzağa bükülüyor, düz bir çizgi değil
    // gerçek bir perde gibi okunuyor. updateSnowFlurries sürer (opacity/ripple/offset).
    function createSnowAurora() {
        if (snowAurora) { disposeNode(snowAurora); snowAurora = null; }
        const baseTex = createSnowAuroraTexture();
        snowAurora = new THREE.Group();
        // v3 (2026-07-11, "daha uzun ve boyutu çok daha büyük olsun"): w/h ~2× büyütüldü.
        // Y, alt kenar sabit tutulup (güneşin üstü y=460'ın üzerinde temiz boşluk) yukarı
        // doğru büyütülerek hesaplandı — yoksa büyüyen gövde güneşe gömülürdü.
        const curtains = [
            { x: 1150, z: -30, y: 900, w: 3200, h: 480, drift: 0.011, baseOp: 0.7, yaw: 0.06, seed: 4101 },
            { x: 900, z: 50, y: 760, w: 2650, h: 380, drift: -0.008, baseOp: 0.58, yaw: -0.05, seed: 4213 },
            { x: 700, z: -60, y: 640, w: 2100, h: 300, drift: 0.014, baseOp: 0.5, yaw: 0.08, seed: 4327 }
        ];
        curtains.forEach((c, idx) => {
            const tex = idx === 0 ? baseTex : baseTex.clone();
            tex.needsUpdate = true;
            tex.repeat.set(c.w / 900, 1);
            tex.offset.x = idx * 0.37;
            const geo = buildAuroraCurtainGeometry(c.w, c.h, c.seed);
            const mat = new THREE.MeshBasicMaterial({
                map: tex,
                vertexColors: true,
                transparent: true,
                opacity: 0.0,
                side: THREE.DoubleSide,
                depthWrite: false,
                fog: false,
                blending: THREE.AdditiveBlending
            });
            // Zaman-yavaşlatma gri efektinden muaf (2026-07-11, kullanıcı isteği): composer'sız
            // yolda collectTimeSlowGrayTargets bu materyali ATLAR (bkz. addMat isRoadColor kalıbı).
            mat.userData.skipTimeSlowGray = true;
            const mesh = new THREE.Mesh(geo, mat);
            // Aurora ana sahne render'ında (layer 0) çizilir → derinlik doğru: dağ/ağaçlar önündeyse
            // onları örtmez, arkalarında kalır (2026-07-15 fix; eski AURORA_LAYER overlay'i derinlik
            // temizlediğinden her şeyin önüne geçiyordu). Time-slow'da composer gri shader'ı auroraya
            // da uygulanır (kabul edildi — kalıcı derinlik bug'ı nadir gri efektinden daha önemli).
            mesh.layers.set(0);
            mesh.position.set(c.x, c.y, c.z);
            mesh.rotation.y = Math.PI / 2 + c.yaw;
            const rnd = natSeedRand(c.seed + 7);
            mesh.userData = {
                drift: c.drift, baseOp: c.baseOp, pulseSeed: idx * 2.1, pulseSpeed: 0.35 + idx * 0.12,
                waveBaseZ: geo.attributes.position.array.slice(),
                rippleAmp: c.w * 0.012, rippleFreq: 3.5 + rnd() * 2.0,
                rippleSpeed: 0.5 + rnd() * 0.35, ripplePhase: rnd() * Math.PI * 2,
                width: c.w
            };
            snowAurora.add(mesh);
        });
        snowAurora.visible = false;
        scene.add(snowAurora);
    }

    function updateSnowFlurries(delta, alpha) {
        if (!snowFlurries || !snowFlurries.geometry || !snowFlurries.material || !player) return;
        const coveredBySnowTunnel = !!getSnowTunnelCoveringX(player.position.x, 4);
        const flurryAlpha = coveredBySnowTunnel ? 0 : alpha;
        snowFlurries.visible = flurryAlpha > 0.02;
        snowFlurries.material.opacity = Math.min(0.72, flurryAlpha * 0.68);
        const positions = snowFlurries.geometry.attributes.position.array;
        const time = clock.getElapsedTime();
        for (let i = 0; i < snowFlurryData.length; i++) {
            const flake = snowFlurryData[i];
            flake.relX -= moveSpeed * 5.4 * delta;
            flake.y -= flake.speed * delta;
            if (flake.relX < -320 || flake.y < 3) {
                flake.relX = 1120 + Math.random() * 820;
                flake.y = 46 + Math.random() * 86;
                flake.z = (Math.random() - 0.5) * 440;
                flake.phase = Math.random() * Math.PI * 2;
            }
            positions[i * 3] = player.position.x + flake.relX + Math.sin(time * 0.75 + flake.phase) * 10;
            positions[i * 3 + 1] = flake.y;
            positions[i * 3 + 2] = flake.z + Math.cos(time * 0.9 + flake.phase) * flake.drift;
        }
        snowFlurries.geometry.attributes.position.needsUpdate = true;

        // Aurora: kar yağışıyla aynı alpha'yla sürülür (faz geçişlerinde birlikte belirir/söner)
        if (snowAurora) {
            snowAurora.visible = alpha > 0.02;
            if (snowAurora.visible) {
                snowAurora.position.x = player.position.x;
                snowAurora.children.forEach((band) => {
                    const u = band.userData;
                    if (band.material.map) band.material.map.offset.x = time * u.drift;
                    band.material.opacity = alpha * u.baseOp * (0.8 + Math.sin(time * u.pulseSpeed + u.pulseSeed) * 0.2);
                    // Z-dalga titreşimi: kart gibi durmasın diye statik büküme ek olarak zaman-bazlı ripple
                    const posAttr = band.geometry.attributes.position;
                    const arr = posAttr.array;
                    const base = u.waveBaseZ;
                    const w = u.width;
                    for (let i = 0; i < arr.length; i += 3) {
                        const uCoord = arr[i] / w + 0.5;
                        arr[i + 2] = base[i + 2] + Math.sin(time * u.rippleSpeed + uCoord * u.rippleFreq + u.ripplePhase) * u.rippleAmp;
                    }
                    posAttr.needsUpdate = true;
                });
            }
        }
    }

    function createSkyCloudFloor() {
        if (skyCloudFloor) { disposeNode(skyCloudFloor); skyCloudFloor = null; }

        // Sis katmanlarÄ± â€” birbirinden farklÄ± yÃ¼kseklikte, farklÄ± boyutta
        const group = new THREE.Group();
        const layers = [
            { y: -30, size: 6000, opacity: 0.55 },
            { y: -45, size: 5000, opacity: 0.65 },
            { y: -60, size: 4200, opacity: 0.70 },
            { y: -80, size: 3400, opacity: 0.60 },
            { y: -100, size: 2600, opacity: 0.50 },
        ];

        layers.forEach(l => {
            const geo = new THREE.PlaneGeometry(l.size, l.size);
            const mat = new THREE.MeshBasicMaterial({
                color: 0xddeeff,
                transparent: true,
                opacity: 0.0,
                depthWrite: false,
                fog: true
            });
           mat.userData.targetOpacity = l.opacity;
            const mesh = new THREE.Mesh(geo, mat);
            mesh.rotation.x = -Math.PI / 2;
            mesh.position.y = l.y;
            mesh.renderOrder = 1;
            group.add(mesh);
        });

        skyCloudFloor = group;
        skyCloudFloor.position.set(player ? player.position.x : 0, SKY_LAYER_Y, 0);
        skyCloudFloor.visible = false;
        scene.add(skyCloudFloor);
        curvedPathSystem?.installObjectMaterials?.(skyCloudFloor);
    }

    function updateCyberFloor() {
        if(!player) return;
        if(cyberFloor) {
            cyberFloor.position.x = player.position.x; cyberFloor.position.z = player.position.z; 
            const tex = cyberFloor.material.map; tex.offset.x = ((player.position.x + worldScrollX) / 40) % 1; tex.offset.y = -player.position.z / 40;
        }
        if(natureFloor) {
            natureFloor.position.x = player.position.x; natureFloor.position.z = 0; 
            const tex = natureFloor.material.map; tex.offset.x = ((player.position.x + worldScrollX) / 80) % 1; tex.offset.y = 0;
            if (natureFloor.material.normalMap) natureFloor.material.normalMap.offset.copy(tex.offset);
            if (natureFloor.material.roughnessMap) natureFloor.material.roughnessMap.offset.copy(tex.offset);
        }
        if (lavaFloor) {
            lavaFloor.position.x = player.position.x;
            lavaFloor.position.z = 0;
        }
        if (waterFloor) {
            waterFloor.position.x = player.position.x;
            waterFloor.position.z = 0;
        }
        if(skyCloudFloor && skyCloudFloor.visible) {
            skyCloudFloor.position.x = player.position.x;
            skyCloudFloor.position.z = player.position.z;
        }
    }
    
    function createSky() {
        const starGeo = new THREE.BufferGeometry();
        const starCount = isMobilePerformanceGraphics() ? 800 : (RUNTIME_LOW_POWER ? 1600 : 3000);
        const starPos = new Float32Array(starCount * 3);
        const starCol = new Float32Array(starCount * 3);
        for(let i=0; i<starCount; i++) {
            starPos[i*3] = (Math.random() - 0.5) * 3000;
            starPos[i*3+1] = Math.random() * 1500 + 100;
            starPos[i*3+2] = (Math.random() - 0.5) * 2000;
            // renk çeşitliliği: çoğu beyaz, %18 soğuk mavi, %10 pembe (synthwave) + parlaklık varyasyonu
            const roll = Math.random(); let cr, cg, cb;
            if (roll < 0.10) { cr = 1; cg = 0.6; cb = 0.8; }
            else if (roll < 0.28) { cr = 0.65; cg = 0.78; cb = 1; }
            else { cr = 1; cg = 1; cb = 1; }
            const br = 0.4 + Math.random() * 0.6;
            starCol[i*3] = cr * br; starCol[i*3+1] = cg * br; starCol[i*3+2] = cb * br;
        }
        starGeo.setAttribute('position', new THREE.BufferAttribute(starPos, 3));
        starGeo.setAttribute('color', new THREE.BufferAttribute(starCol, 3));
        // fog:false KRİTİK — sis (~1200) yıldızları örtüyordu, yıldızlar hiç görünmüyordu
        const starMat = new THREE.PointsMaterial({color: 0xffffff, size: 2.2, transparent: true, opacity: 0.8, sizeAttenuation: false, vertexColors: true, fog: false, depthWrite: false, blending: THREE.AdditiveBlending});
        starField = new THREE.Points(starGeo, starMat); scene.add(starField);
        
        const sunGeo = new THREE.CircleGeometry(160, 64);
        const sunMat = new THREE.MeshBasicMaterial({ color: 0xff00aa, fog: false });
        cyberSun = new THREE.Mesh(sunGeo, sunMat);
        cyberSun.position.set(1500, 300, 0); cyberSun.rotation.y = -Math.PI / 2;
        cyberSun.renderOrder = -1;
        scene.add(cyberSun);
    }

    function clearCityBuildings() {
        for (let i = 0; i < cityBuildingInstances.length; i++) {
            scene.remove(cityBuildingInstances[i]);
        }
        cityBuildingInstances = [];
        cityBuildings = [];
        cityInstanceLayoutDirty = true;
        compactCityInstances._sig = '';
        compactCityInstances._compacted = false;
    }

    // PERF (2026-07-05): INSTANCE SIKIŞTIRMA — sıfır-ölçek submit edilen üçgeni AZALTMAZ
    // (InstancedMesh count×geometri üçgenini her zaman gönderir). Canlı (sis-içi) binalar her
    // karede slot 0..N-1'e yazılır ve mesh.count=N yapılır → vertex yükü gerçekten düşer.
    // NOT: doğa geçişindeki sink kodu instanceIndex-bazlı yazar — geçişte restoreCityInstanceOrder
    // ile orijinal slot düzeni + tam count geri yüklenir.
    function compactCityInstances() {
        const fn = compactCityInstances;
        const sig = cityBuildings.length + ':' + (cityBuildings[0] && cityBuildings[0].instanceMeshes[0] ? cityBuildings[0].instanceMeshes[0].uuid : '');
        if (!fn._meshes || fn._sig !== sig) {
            fn._sig = sig;
            fn._meshes = new Map();
            fn._live = new Map();
            for (const b of cityBuildings) {
                if (!fn._meshes.has(b.typeIndex)) {
                    fn._meshes.set(b.typeIndex, b.instanceMeshes);
                    fn._live.set(b.typeIndex, []);
                    for (const m of b.instanceMeshes) if (m.userData.fullCount === undefined) m.userData.fullCount = m.count;
                }
            }
            cityInstanceLayoutDirty = true;
        }
        // Floating-origin kaydırması canlı instance matrislerinin X hücresini doğrudan
        // günceller. Görünür bina kümesi/konumu değişmedikçe aynı 1000+ matrisi her
        // kare yeniden kurup GPU'ya yüklemek gereksizdir.
        if (fn._compacted && !cityInstanceLayoutDirty) return;
        fn._live.forEach(a => { a.length = 0; });
        for (const b of cityBuildings) {
            if (!b.userData.fogCollapsed) { const arr = fn._live.get(b.typeIndex); if (arr) arr.push(b); }
        }
        fn._meshes.forEach((meshes, t) => {
            const live = fn._live.get(t);
            for (let i = 0; i < live.length; i++) {
                tempCityBuildingDummy.position.copy(live[i].position);
                tempCityBuildingDummy.rotation.set(0, 0, 0);
                tempCityBuildingDummy.scale.set(1, 1, 1);
                tempCityBuildingDummy.updateMatrix();
                for (const m of meshes) m.setMatrixAt(i, tempCityBuildingDummy.matrix);
            }
            for (const m of meshes) { m.count = live.length; m.instanceMatrix.needsUpdate = true; }
        });
        fn._compacted = true;
        cityInstanceLayoutDirty = false;
    }

    function restoreCityInstanceOrder() {
        const fn = compactCityInstances;
        if (!fn._compacted) return;
        fn._compacted = false;
        cityInstanceLayoutDirty = true;
        const seen = new Set();
        for (const b of cityBuildings) {
            for (const m of b.instanceMeshes) {
                if (!seen.has(m)) { seen.add(m); m.count = (m.userData.fullCount !== undefined) ? m.userData.fullCount : m.count; }
            }
            syncCityBuildingMatrix(b);
        }
    }

    function syncCityBuildingMatrix(building) {
        if (!building || !building.instanceMeshes) return;
        tempCityBuildingDummy.position.copy(building.position);
        tempCityBuildingDummy.rotation.set(0, 0, 0);
        // PERF (2026-07-05): sis-dışı binalar sıfır-ölçek (fog 0.006, ~450+ birimde tamamen
        // görünmez ama instanced mesh yine de rasterize ediliyordu — ~5.6M üçgen/kare).
        if (building.userData && building.userData.fogCollapsed) tempCityBuildingDummy.scale.set(0, 0, 0);
        else tempCityBuildingDummy.scale.set(1, 1, 1);
        tempCityBuildingDummy.updateMatrix();
        // a building is several InstancedMeshes (one per material-part) sharing the same matrices
        for (let k = 0; k < building.instanceMeshes.length; k++) {
            building.instanceMeshes[k].setMatrixAt(building.instanceIndex, tempCityBuildingDummy.matrix);
            building.instanceMeshes[k].instanceMatrix.needsUpdate = true;
        }
    }

    // ===== CYBERPUNK CITY BUILDINGS (detailed procedural model, merged-by-material → instanced) =====
    const CB_NEON = [0xff2d95, 0x00e5ff, 0x2d7bff, 0xb14bff]; // fewer neon hues (dropped green/orange)
    function cbRng(seed){ return function(){ seed|=0; seed=seed+0x6D2B79F5|0; let t=Math.imul(seed^seed>>>15,1|seed); t=t+Math.imul(t^t>>>7,61|t)^t; return ((t^t>>>14)>>>0)/4294967296; }; }
    const CBG = {
        box:   new THREE.BoxGeometry(1,1,1),
        win:   new THREE.BoxGeometry(1,1,0.12),
        frame: new THREE.BoxGeometry(1,1,0.16),
        col:   new THREE.BoxGeometry(0.34,1,0.42),
        band:  new THREE.BoxGeometry(1,0.32,0.12),
        cyl:   new THREE.CylinderGeometry(1,1,1,8),
    };
    const CBM = {
        stone:    new THREE.MeshStandardMaterial({ color:0x9a938a, roughness:0.96, metalness:0.02 }),
        steel:    new THREE.MeshStandardMaterial({ color:0x191c23, roughness:0.5,  metalness:0.65 }),
        band:     new THREE.MeshStandardMaterial({ color:0x6c675f, roughness:0.9,  metalness:0.05 }),
        dark:     new THREE.MeshStandardMaterial({ color:0x0a0c10, roughness:0.7,  metalness:0.3 }),
        shutter:  new THREE.MeshStandardMaterial({ color:0x33363d, roughness:0.45, metalness:0.7 }),
        glassOff: new THREE.MeshStandardMaterial({ color:0x0c1118, roughness:0.25, metalness:0.6 }),
        concrete: new THREE.MeshStandardMaterial({ color:0x4d4a44, roughness:1.0,  metalness:0.0 }),
    };
    const _cbNeon = {};
    function cbNeonMat(hex){ if(!_cbNeon[hex]) _cbNeon[hex]=new THREE.MeshStandardMaterial({ color:0x05070b, emissive:hex, emissiveIntensity:2.0, roughness:0.35, metalness:0.0 }); return _cbNeon[hex]; }
    function cbMesh(geo,mat,x,y,z,sx,sy,sz,ry){ const m=new THREE.Mesh(geo,mat); m.position.set(x,y,z); m.scale.set(sx,sy,sz); if(ry!==undefined)m.rotation.y=ry; return m; }

    // Faithful port of the cyberpunk-building model (full detail) — parameterised for
    // variations (floors/size/neon accent/roof). Body + bands + columns + neon window grid
    // (with frames, dividers, AC units) + hanging cables + vertical sign + full ground floor
    // (shutter, neon entrance, awning, vitrine, kiosk, bollards) + roof (parapet/machine/AC/antenna).
    function buildCyberpunkBuilding(opts){
        const o = opts||{}; const R = cbRng(o.seed||1337); const grp = new THREE.Group();
        const W = o.W||11, D = o.D||8.5, G0 = 3.6, FH = 2.7;
        const FLOORS = Math.max(2, o.floors||3); const H = G0 + FLOORS*FH;
        const accent = o.accent || CB_NEON[0]; const roofStyle = o.roofStyle || 'full';
        const style = o.style || 'block';
        const neonFor = () => (R()<0.5 ? accent : CB_NEON[(R()*CB_NEON.length)|0]);
        // big, fewer window panes (reference grid but larger & sparser columns)
        const fb = Math.min(8, Math.max(2, Math.round(W/9)));
        const sb = Math.min(5, Math.max(2, Math.round(D/9)));
        const sx = W/11; // ground-floor detail scale (original designed for W=11)
        const FACES = [
            { ry:0,          half:W/2, out:D/2, bays:fb },
            { ry:Math.PI,    half:W/2, out:D/2, bays:fb },
            { ry:Math.PI/2,  half:D/2, out:W/2, bays:sb },
            { ry:-Math.PI/2, half:D/2, out:W/2, bays:sb },
        ];
        const fvec = f => ({ nx:Math.sin(f.ry), nz:Math.cos(f.ry), rx:Math.cos(f.ry), rz:-Math.sin(f.ry) });
        const onF = (f,u,v,d) => { const k=fvec(f); return { x:k.rx*u+k.nx*(f.out+d), z:k.rz*u+k.nz*(f.out+d), y:v }; };
        // upper setback tower (different silhouette) — a narrower windowed box rising from the roof
        function addTower(cx, tw, td, yb, tf){
            const th=tf*FH;
            grp.add(cbMesh(CBG.box, CBM.stone, cx, yb+th/2, 0, tw, th, td));
            const fb2=Math.min(6,Math.max(2,Math.round(tw/9))), sb2=Math.min(4,Math.max(2,Math.round(td/9)));
            const TF=[ {ry:0,half:tw/2,out:td/2,bays:fb2}, {ry:Math.PI,half:tw/2,out:td/2,bays:fb2},
                       {ry:Math.PI/2,half:td/2,out:tw/2,bays:sb2}, {ry:-Math.PI/2,half:td/2,out:tw/2,bays:sb2} ];
            for(let fl=0;fl<=tf;fl++){ const y=yb+fl*FH;
                grp.add(cbMesh(CBG.band,CBM.band, cx,y, td/2+0.02, tw+0.4,1,1));
                grp.add(cbMesh(CBG.band,CBM.band, cx,y,-td/2-0.02, tw+0.4,1,1));
                grp.add(cbMesh(CBG.band,CBM.band, cx+tw/2+0.02,y,0, td+0.4,1,1,Math.PI/2));
                grp.add(cbMesh(CBG.band,CBM.band, cx-tw/2-0.02,y,0, td+0.4,1,1,Math.PI/2)); }
            TF.forEach(f=>{ const span=2*f.half/f.bays;
                for(let i=0;i<=f.bays;i++){ const u=-f.half+(i/f.bays)*2*f.half; const p=onF(f,u,yb+th/2,0.18); grp.add(cbMesh(CBG.col,CBM.steel,cx+p.x,p.y,p.z,1,th,1,f.ry)); }
                for(let fl=0;fl<tf;fl++){ const vc=yb+fl*FH+FH*0.54;
                    for(let b=0;b<f.bays;b++){ const u=-f.half+(b+0.5)*span;
                        const ww=Math.min(4.6,span*0.76), wh=FH*0.88;
                        const fp=onF(f,u,vc,0.10); grp.add(cbMesh(CBG.frame,CBM.dark,cx+fp.x,fp.y,fp.z,ww+0.24,wh+0.24,1,f.ry));
                        const off=R()<0.12; const mat=off?CBM.glassOff:cbNeonMat(neonFor());
                        const gp=onF(f,u,vc,0.16); grp.add(cbMesh(CBG.win,mat,cx+gp.x,gp.y,gp.z,ww,wh,1,f.ry));
                    } }
            });
            grp.add(cbMesh(CBG.box,CBM.band, cx, yb+th+0.4, 0, tw+0.4,0.8,td+0.4));               // crown cap
            grp.add(cbMesh(CBG.cyl,CBM.steel, cx, yb+th+2.4, 0, 0.06,4.0,0.06));                    // antenna mast
            grp.add(cbMesh(CBG.cyl,cbNeonMat(accent), cx, yb+th+4.5, 0, 0.12,0.3,0.12));            // beacon
        }
        // body + base
        grp.add(cbMesh(CBG.box, CBM.stone, 0,H/2,0, W,H,D));
        grp.add(cbMesh(CBG.box, CBM.concrete, 0,-0.15,0, W+3.2,0.3,D+3.2));
        // floor bands
        const bandYs=[]; for(let fl=0;fl<FLOORS;fl++) bandYs.push(G0+fl*FH); bandYs.push(H);
        bandYs.forEach(y=>{
            grp.add(cbMesh(CBG.band,CBM.band, 0,y, D/2+0.02, W+0.5,1,1));
            grp.add(cbMesh(CBG.band,CBM.band, 0,y,-D/2-0.02, W+0.5,1,1));
            grp.add(cbMesh(CBG.band,CBM.band,  W/2+0.02,y,0, D+0.5,1,1, Math.PI/2));
            grp.add(cbMesh(CBG.band,CBM.band, -W/2-0.02,y,0, D+0.5,1,1, Math.PI/2));
        });
        // steel columns
        FACES.forEach(f=>{ const n=f.bays; for(let i=0;i<=n;i++){ const u=-f.half+(i/n)*(2*f.half); const p=onF(f,u,H/2,0.18); grp.add(cbMesh(CBG.col,CBM.steel,p.x,p.y,p.z,1,H,1,f.ry)); } });
        // window grid (reference image style): uniform square-ish framed panes, one row per floor,
        // steel columns act as pillars between them, floor bands between rows.
        FACES.forEach(f=>{
            const span=2*f.half/f.bays;
            for(let fl=0;fl<FLOORS;fl++){
                const vc=G0+fl*FH+FH*0.54;
                for(let b=0;b<f.bays;b++){
                    const u=-f.half+(b+0.5)*span;
                    const ww=Math.min(4.6, span*0.76), wh=FH*0.88; // bigger panes, fewer columns
                    const fp=onF(f,u,vc,0.10); grp.add(cbMesh(CBG.frame,CBM.dark,fp.x,fp.y,fp.z,ww+0.24,wh+0.24,1,f.ry));
                    const off=R()<0.12; const mat=off?CBM.glassOff:cbNeonMat(neonFor());
                    const gp=onF(f,u,vc,0.16); grp.add(cbMesh(CBG.win,mat,gp.x,gp.y,gp.z,ww,wh,1,f.ry));
                    if(R()<0.3) grp.add(cbMesh(CBG.frame,CBM.dark,gp.x,gp.y,gp.z,0.06,wh,1.4,f.ry)); // occasional center mullion
                }
            }
        });
        // hanging cables (front + right faces, lower floors)
        function cable(f,u,y0){ const a=onF(f,u-0.9,y0,0.30), b=onF(f,u+0.9,y0-1.1,0.30), m=onF(f,u,y0-1.5,0.30);
            const curve=new THREE.CatmullRomCurve3([new THREE.Vector3(a.x,a.y,a.z),new THREE.Vector3(m.x,m.y,m.z),new THREE.Vector3(b.x,b.y,b.z)]);
            grp.add(new THREE.Mesh(new THREE.TubeGeometry(curve,8,0.03,5,false),CBM.dark)); }
        cable(FACES[0],-2.5*sx,G0+FH*1.6); cable(FACES[0],2.0*sx,G0+Math.min(FLOORS-1,2)*FH*1.05); cable(FACES[2],0.8,G0+FH*1.4);
        // vertical neon sign (right face, accent colour)
        (function(){ const f=FACES[2]; const sh=Math.min(H*0.44,3.2); const p=onF(f,f.half-0.5,H*0.62,0.35); grp.add(cbMesh(CBG.box,CBM.dark,p.x,p.y,p.z,0.9,sh,0.35,f.ry)); const p2=onF(f,f.half-0.5,H*0.62,0.55); grp.add(cbMesh(CBG.box,cbNeonMat(accent),p2.x,H*0.62,p2.z,0.55,sh*0.88,0.1,f.ry)); })();
        // ground floor (front): shutter + slats, neon entrance, awning, vitrine, kiosk, bollards
        (function(){ const f=FACES[0];
            const sp=onF(f,-3.2*sx,1.7,0.05); grp.add(cbMesh(CBG.box,CBM.shutter,sp.x,sp.y,sp.z,3.0*sx,3.0,0.2));
            for(let i=0;i<6;i++) grp.add(cbMesh(CBG.box,CBM.dark,sp.x,0.6+i*0.45,sp.z+0.12,2.9*sx,0.05,0.05));
            const dp=onF(f,0.4*sx,1.6,0.05); grp.add(cbMesh(CBG.box,CBM.dark,dp.x,dp.y,dp.z,2.4*sx,3.0,0.2));
            const nm=cbNeonMat(0x00e5ff), gm=cbNeonMat(0x2d7bff);
            const lp=onF(f,0.4*sx-1.15*sx,1.6,0.12), rp=onF(f,0.4*sx+1.15*sx,1.6,0.12);
            grp.add(cbMesh(CBG.box,nm,lp.x,1.6,lp.z,0.1,3.0,0.1));
            grp.add(cbMesh(CBG.box,nm,rp.x,1.6,rp.z,0.1,3.0,0.1));
            grp.add(cbMesh(CBG.box,gm,dp.x,3.05,dp.z+0.12,2.4*sx,0.1,0.1));
            grp.add(cbMesh(CBG.box,gm,dp.x,0.9,dp.z+0.14,1.4*sx,0.06,0.06));
            const tp=onF(f,0.4*sx,3.3,0.7); const tent=cbMesh(CBG.box,CBM.steel,tp.x,tp.y,tp.z,2.8*sx,0.12,1.2); tent.rotation.x=-0.32; grp.add(tent);
            const wp=onF(f,3.3*sx,1.7,0.05); grp.add(cbMesh(CBG.box,CBM.dark,wp.x,wp.y,wp.z,2.4*sx,2.6,0.2)); grp.add(cbMesh(CBG.win,cbNeonMat(0xff2d95),wp.x,1.7,wp.z+0.12,2.0*sx,2.0,1));
            const kp=onF(f,4.9*sx,0.85,1.5); grp.add(cbMesh(CBG.box,CBM.steel,kp.x,kp.y,kp.z,1.0,1.7,0.8)); grp.add(cbMesh(CBG.win,cbNeonMat(0x2d7bff),kp.x,1.15,kp.z+0.42,0.6,0.5,1));
            for(let i=-1;i<=1;i++){ const bp=onF(f,(i*1.6-0.2)*sx,0.45,2.4); grp.add(cbMesh(CBG.cyl,CBM.steel,bp.x,bp.y,bp.z,0.12,0.9,0.12)); }
        })();
        // roof
        (function(){ const y=H;
            grp.add(cbMesh(CBG.box,CBM.band,0,y+0.45,D/2-0.05,W,0.9,0.25));
            grp.add(cbMesh(CBG.box,CBM.band,0,y+0.45,-D/2+0.05,W,0.9,0.25));
            grp.add(cbMesh(CBG.box,CBM.band,W/2-0.05,y+0.45,0,0.25,0.9,D));
            grp.add(cbMesh(CBG.box,CBM.band,-W/2+0.05,y+0.45,0,0.25,0.9,D));
            // rooftop clutter only on plain blocks; setback/twin towers supply their own crown/antenna
            if(style==='block'){
                if(roofStyle==='full'||roofStyle==='box') grp.add(cbMesh(CBG.box,CBM.concrete,-W*0.18,y+0.9,-D*0.18,W*0.32,1.4,D*0.32));
                if(roofStyle==='full'){ grp.add(cbMesh(CBG.box,CBM.steel,W*0.22,y+0.55,D*0.14,1.6,0.9,1.2)); grp.add(cbMesh(CBG.box,CBM.steel,W*0.22,y+0.55,-D*0.12,1.6,0.9,1.2)); }
                if(roofStyle==='full'||roofStyle==='antenna'){ grp.add(cbMesh(CBG.cyl,CBM.steel,W*0.3,y+2.6,-D*0.3,0.05,5.0,0.05)); grp.add(cbMesh(CBG.box,CBM.steel,W*0.3,y+4.2,-D*0.3,0.9,0.06,0.06)); grp.add(cbMesh(CBG.box,CBM.steel,W*0.3,y+3.6,-D*0.3,0.6,0.06,0.06)); grp.add(cbMesh(CBG.cyl,cbNeonMat(0xff2020),W*0.3,y+5.15,-D*0.3,0.09,0.18,0.09)); }
            }
        })();
        // different building silhouettes
        if(style==='setback') addTower(0, W*0.62, D*0.64, H+0.9, Math.max(3, Math.round(FLOORS*0.42)));
        else if(style==='twin'){ addTower(-W*0.24, W*0.34, D*0.62, H+0.9, Math.max(3, Math.round(FLOORS*0.5)));
                                  addTower( W*0.24, W*0.34, D*0.62, H+0.9, Math.max(3, Math.round(FLOORS*0.34))); }
        return grp;
    }

    // merge a building Group's meshes grouped by material → [{geo, mat}] (instanceable parts)
    function cbMergeGeos(geos){
        let vc=0, ic=0;
        geos.forEach(g=>{ vc+=g.attributes.position.count; ic+=(g.index?g.index.count:g.attributes.position.count); });
        const pos=new Float32Array(vc*3), nor=new Float32Array(vc*3), uv=new Float32Array(vc*2), idx=new Uint32Array(ic);
        let vo=0, io=0, base=0;
        geos.forEach(g=>{ const p=g.attributes.position, n=g.attributes.normal, u=g.attributes.uv;
            pos.set(p.array, vo*3); if(n) nor.set(n.array, vo*3); if(u) uv.set(u.array, vo*2);
            const cnt=p.count;
            if(g.index){ for(let k=0;k<g.index.count;k++) idx[io++]=g.index.array[k]+base; } else { for(let k=0;k<cnt;k++) idx[io++]=k+base; }
            vo+=cnt; base+=cnt;
        });
        const m=new THREE.BufferGeometry();
        m.setAttribute('position', new THREE.BufferAttribute(pos,3));
        m.setAttribute('normal',   new THREE.BufferAttribute(nor,3));
        m.setAttribute('uv',       new THREE.BufferAttribute(uv,2));
        m.setIndex(new THREE.BufferAttribute(idx,1));
        m.computeBoundingSphere();
        return m;
    }
    function cbMergeByMaterial(group){
        group.updateMatrixWorld(true);
        const byMat = new Map();
        group.traverse(o=>{ if(o.isMesh){ const g=o.geometry.clone(); g.applyMatrix4(o.matrixWorld);
            if(!g.attributes.uv){ const c=g.attributes.position.count; g.setAttribute('uv', new THREE.BufferAttribute(new Float32Array(c*2),2)); }
            if(!byMat.has(o.material)) byMat.set(o.material,[]); byMat.get(o.material).push(g); } });
        const parts=[];
        byMat.forEach((geos,mat)=>{ parts.push({ geo: cbMergeGeos(geos), mat }); geos.forEach(g=>g.dispose()); });
        return parts;
    }

    // RENK-BAKE KOVA BİRLEŞTİRME (FPS, 2026-07-05): cache'lenmiş dekor parçalarının materyal
    // renklerini vertex-color'a yazıp az sayıda ortak vertexColors materyalinde toplar —
    // obje başına draw call 4-6'dan 1-2'ye düşer. UV kopyalanmaz (bu materyaller map kullanmaz);
    // classify null dönerse parça kendi materyaliyle bırakılır (güçlü emissive / DoubleSide özel).
    function mergeColoredGeos(geos) {
        let vc = 0, ic = 0;
        geos.forEach(g => { vc += g.attributes.position.count; ic += (g.index ? g.index.count : g.attributes.position.count); });
        const pos = new Float32Array(vc * 3), nor = new Float32Array(vc * 3), col = new Float32Array(vc * 3), idx = new Uint32Array(ic);
        let vo = 0, io = 0, base = 0;
        geos.forEach(g => {
            const p = g.attributes.position, n = g.attributes.normal, c = g.attributes.color;
            pos.set(p.array, vo * 3);
            if (n) nor.set(n.array, vo * 3);
            if (c) col.set(c.array, vo * 3);
            const cnt = p.count;
            if (g.index) { for (let k = 0; k < g.index.count; k++) idx[io++] = g.index.array[k] + base; }
            else { for (let k = 0; k < cnt; k++) idx[io++] = k + base; }
            vo += cnt; base += cnt;
        });
        const m = new THREE.BufferGeometry();
        m.setAttribute('position', new THREE.BufferAttribute(pos, 3));
        m.setAttribute('normal', new THREE.BufferAttribute(nor, 3));
        m.setAttribute('color', new THREE.BufferAttribute(col, 3));
        m.setIndex(new THREE.BufferAttribute(idx, 1));
        m.computeBoundingSphere();
        return m;
    }

    function bakeCachedParts(parts, classify, bucketMats) {
        const buckets = new Map(); const out = [];
        for (const p of parts) {
            const key = classify(p.mat);
            if (!key || !bucketMats[key]) { out.push(p); continue; }
            const g = p.geo; // cbMergeByMaterial çıktısı — sahiplik bizde
            const n = g.attributes.position.count;
            const colArr = new Float32Array(n * 3);
            const mc = p.mat.color; const ex = g.attributes.color;
            for (let i = 0; i < n; i++) {
                if (ex) { colArr[i*3] = ex.getX(i) * mc.r; colArr[i*3+1] = ex.getY(i) * mc.g; colArr[i*3+2] = ex.getZ(i) * mc.b; }
                else { colArr[i*3] = mc.r; colArr[i*3+1] = mc.g; colArr[i*3+2] = mc.b; }
            }
            g.setAttribute('color', new THREE.BufferAttribute(colArr, 3));
            if (!buckets.has(key)) buckets.set(key, []);
            buckets.get(key).push(g);
        }
        buckets.forEach((list, key) => {
            const merged = mergeColoredGeos(list);
            list.forEach(g => g.dispose());
            out.push({ geo: merged, mat: bucketMats[key] });
        });
        return out;
    }

    const CB_VARIATIONS = [
        { floors:14, W:42, D:28, accent:0xff2d95, roofStyle:'full',    seed:11, style:'block'   },
        { floors:22, W:52, D:30, accent:0x00e5ff, roofStyle:'antenna', seed:23, style:'setback' },
        { floors:32, W:64, D:34, accent:0x2d7bff, roofStyle:'box',     seed:37, style:'block'   },
        { floors:44, W:76, D:36, accent:0xb14bff, roofStyle:'full',    seed:51, style:'twin'    },
        { floors:56, W:88, D:38, accent:0xff2d95, roofStyle:'antenna', seed:67, style:'setback' },
        { floors:68, W:100,D:40, accent:0x00e5ff, roofStyle:'box',     seed:83, style:'block'   },
    ];

    function buildLiteCyberBuildingTypes() {
        const types = [];
        const configs = [
            { width: 26, depth: 20, height: 52, accent: '#ff2d95', seed: 11 },
            { width: 34, depth: 24, height: 78, accent: '#00e5ff', seed: 37 },
            { width: 42, depth: 28, height: 112, accent: '#7c55ff', seed: 67 },
            { width: 52, depth: 32, height: 146, accent: '#ff5fc8', seed: 83 }
        ];
        configs.forEach((config) => {
            const canvas = document.createElement('canvas');
            canvas.width = 128;
            canvas.height = 256;
            const ctx = canvas.getContext('2d');
            const gradient = ctx.createLinearGradient(0, 0, 0, canvas.height);
            gradient.addColorStop(0, '#10162d');
            gradient.addColorStop(1, '#040714');
            ctx.fillStyle = gradient;
            ctx.fillRect(0, 0, canvas.width, canvas.height);
            ctx.fillStyle = 'rgba(44,55,92,.82)';
            for (let x = 0; x < canvas.width; x += 16) ctx.fillRect(x, 0, 2, canvas.height);
            for (let y = 0; y < canvas.height; y += 14) ctx.fillRect(0, y, canvas.width, 2);
            for (let y = 5; y < canvas.height - 5; y += 14) {
                for (let x = 5; x < canvas.width - 5; x += 16) {
                    const lit = ((x * 13 + y * 7 + config.seed) % 11) > 2;
                    ctx.fillStyle = lit
                        ? (((x + y + config.seed) % 3 === 0) ? config.accent : '#37dff5')
                        : '#070b19';
                    ctx.globalAlpha = lit ? 0.88 : 0.76;
                    ctx.fillRect(x, y, 8, 6);
                }
            }
            ctx.globalAlpha = 1;
            ctx.fillStyle = config.accent;
            ctx.fillRect(2, 0, 3, canvas.height);
            ctx.fillRect(canvas.width - 5, 0, 3, canvas.height);
            const texture = new THREE.CanvasTexture(canvas);
            texture.colorSpace = THREE.SRGBColorSpace;
            texture.wrapS = THREE.RepeatWrapping;
            texture.wrapT = THREE.RepeatWrapping;
            // The canvas was authored for the smallest 26x52 facade. Scale its
            // repeat against that reference so large buildings add window rows
            // instead of stretching them, without producing micro-sized panes.
            texture.repeat.set(
                Math.max(1, config.width / 26),
                Math.max(1, config.height / 52)
            );
            texture.anisotropy = 2;
            const bodyMat = new THREE.MeshBasicMaterial({ map: texture, color: 0xffffff, fog: true });
            const accentMat = new THREE.MeshBasicMaterial({ color: new THREE.Color(config.accent), fog: true });
            const bodyGeo = new THREE.BoxGeometry(config.width, config.height, config.depth);
            bodyGeo.translate(0, config.height * 0.5, 0);
            const capGeo = new THREE.BoxGeometry(config.width * 1.04, 0.8, config.depth * 1.04);
            capGeo.translate(0, config.height + 0.4, 0);
            const parts = [
                { geo: bodyGeo, mat: bodyMat },
                { geo: capGeo, mat: accentMat }
            ];
            types.push({
                parts,
                width: config.width,
                depth: config.depth,
                height: config.height
            });
            parts.forEach((part) => {
                cityBuildingGeoms.push(part.geo);
                if (!cityBuildingMats.includes(part.mat)) cityBuildingMats.push(part.mat);
            });
        });
        return types;
    }

    function getCyberBehindCullDistance() {
        if (MOBILE_RUNTIME) return -90;
        const quality = getEffectiveGraphicsQualityName();
        if (quality === 'performance') return -90;
        return quality === 'balanced' ? -110 : -140;
    }

    // Apply city visibility culling before its first menu/gameplay render. Previously all
    // high-detail buildings were submitted while the menu was open, even far beyond view.
    function primeCyberCityVisibility() {
        if (!player || cityBuildings.length === 0) return;
        const aheadLimit = getCyberVisibleAheadDistance();
        const behindLimit = getCyberBehindCullDistance();
        for (const building of cityBuildings) {
            const dx = building.position.x - player.position.x;
            building.userData.fogCollapsed = dx > aheadLimit || dx < behindLimit;
        }
        cityInstanceLayoutDirty = true;
        compactCityInstances();
    }

    function resetCityForNewRun() {
        const requestedTier = getRequestedCyberBuildingTier();
        if (!cityBuildings.length || activeCyberBuildingTier !== requestedTier) {
            initCity();
            return;
        }

        // The city/nature transition temporarily changes instance ordering.
        restoreCityInstanceOrder();
        for (const building of cityBuildings) {
            const data = building.userData;
            building.position.set(data.initialX, data.initialY, data.initialZ);
            data.originalY = data.initialY;
            data.fogCollapsed = false;
        }
        primeCyberCityVisibility();
    }

    function getRequestedCyberBuildingTier() {
        const quality = getEffectiveGraphicsQualityName();
        return (quality === 'performance'
            || quality === 'balanced'
            || (RUNTIME_LOW_POWER && quality !== 'ultra')) ? 'lite' : 'detailed';
    }

    function ensureCyberBuildingTypes(){
        const requestedTier = getRequestedCyberBuildingTier();
        if (!cyberBuildingTypeCache[requestedTier]) {
            if (requestedTier === 'lite') {
                cyberBuildingTypeCache.lite = buildLiteCyberBuildingTypes();
            } else {
                const detailed = [];
                CB_VARIATIONS.forEach(v=>{
                    const grp = buildCyberpunkBuilding(v);
                    const parts = cbMergeByMaterial(grp);
                    const H = 3.6 + Math.max(2, v.floors) * 2.7;
                    detailed.push({ parts, width: v.W, depth: v.D, height: H });
                    parts.forEach(p=>{ cityBuildingGeoms.push(p.geo); if(cityBuildingMats.indexOf(p.mat)<0) cityBuildingMats.push(p.mat); });
                });
                cyberBuildingTypeCache.detailed = detailed;
            }
        }
        activeCyberBuildingTier = requestedTier;
        cityBuildingTypes = cyberBuildingTypeCache[requestedTier];
    }

    // ===== CYBER STREET DECOR — neon signage, overhead gantries, chevron arrows, flying cars.
    // Reference-styled "Sector 7" street. Pooled + recycled along the road (road itself untouched).
    let cyberDecorObjects = [];   // { obj, role, span, reseed? }
    let cyberDecorBuilt = false;
    let activeCyberDecorQuality = null;
    const cdGeo = {}, cdMat = {};
    function cdEnsure(){
        if (cdGeo.built) return; cdGeo.built = true;
        cdGeo.plane = new THREE.PlaneGeometry(1,1);
        cdGeo.box = new THREE.BoxGeometry(1,1,1);
        cdGeo.cyl = new THREE.CylinderGeometry(1,1,1,8);
        // 2026-07-19 ilk-giriş hitch: round-sign halka/diski her tabelada YENİDEN yaratılıyordu
        // (8 tabela = 16 tekil geometri, ilk çizimde toplu GPU upload — koşu başı spike'ında ölçüldü)
        cdGeo.roundRing = new THREE.TorusGeometry(2.3,0.28,8,20);
        cdGeo.roundDisc = new THREE.CircleGeometry(2.1,20);
        cdMat.backing = new THREE.MeshStandardMaterial({ color:0x070a10, roughness:0.7, metalness:0.3 });
        cdMat.steel   = new THREE.MeshStandardMaterial({ color:0x141821, roughness:0.5, metalness:0.6 });
        cdMat.chevron = new THREE.MeshBasicMaterial({ color:0xff2733 });
        cdMat.glassCar= new THREE.MeshStandardMaterial({ color:0x0a2a3a, emissive:0x12c0e8, emissiveIntensity:1.4, roughness:0.2, metalness:0.7 });
        cdMat.carBody = new THREE.MeshStandardMaterial({ color:0x2a3038, roughness:0.4, metalness:0.7 });
        cdMat.bridgeGlass = new THREE.MeshStandardMaterial({
            color:0x062537, emissive:0x00a8c8, emissiveIntensity:0.55,
            roughness:0.14, metalness:0.72, transparent:true, opacity:0.38,
            depthWrite:false, side:THREE.DoubleSide
        });
        cdMat.neon = {
            cyan: new THREE.MeshBasicMaterial({ color:0x00e5ff }),
            mag:  new THREE.MeshBasicMaterial({ color:0xff2d95 }),
            blue: new THREE.MeshBasicMaterial({ color:0x2d7bff }),
            red:  new THREE.MeshBasicMaterial({ color:0xff2733 }),
        };
        // shared/pooled — reused across every city rebuild, clearCyberDecor must never dispose these
        [cdMat.backing, cdMat.steel, cdMat.chevron, cdMat.glassCar, cdMat.carBody, cdMat.bridgeGlass, cdMat.neon.cyan, cdMat.neon.mag, cdMat.neon.blue, cdMat.neon.red].forEach(m => { m.__pooled = true; });
        // PERF: pre-merge the chevron cluster (6 thin boxes) into ONE geometry → 6× fewer draw calls
        { const tmp=new THREE.Group();
          for(let i=0;i<3;i++){ for(const arm of [-1,1]){
              const b=new THREE.Mesh(cdGeo.box,cdMat.chevron); b.scale.set(2.6,0.6,0.4); b.position.set(i*2.2, arm*1.05, 0); b.rotation.z=arm*0.7; tmp.add(b);
          }}
          cdGeo.chevronMerged = cbMergeByMaterial(tmp)[0].geo;
        }
        // Cyber skybridge: the old version was only one dark beam and a neon line. Build a
        // readable enclosed bridge with grounded support towers, glass, an exterior truss and
        // under-deck lighting. All static pieces are merged by material ONCE, keeping each of
        // the six recycled bridges to four static draw calls despite the added detail.
        { const tmp=new THREE.Group(); const span=110, deckY=32.5, roofY=42.25;
          const addBox=(mat,x,y,z,sx,sy,sz,rx=0,ry=0,rz=0)=>{
              const m=new THREE.Mesh(cdGeo.box,mat); m.position.set(x,y,z); m.scale.set(sx,sy,sz); m.rotation.set(rx,ry,rz); tmp.add(m); return m;
          };
          const addTruss=(x,y1,z1,y2,z2)=>{
              const dy=y2-y1, dz=z2-z1, len=Math.hypot(dy,dz);
              addBox(cdMat.steel,x,(y1+y2)*0.5,(z1+z2)*0.5,0.52,0.52,len,-Math.atan2(dy,dz));
          };

          // Enclosed pedestrian deck, roof and tinted side walls.
          addBox(cdMat.steel,0,deckY,0,11.8,2.6,span-2);
          addBox(cdMat.backing,0,deckY-1.38,0,10.7,0.38,span-5);
          addBox(cdMat.steel,0,roofY,0,10.8,0.9,span-2);
          addBox(cdMat.bridgeGlass,-5.25,37.4,0,0.22,7.4,span-12);
          addBox(cdMat.bridgeGlass, 5.25,37.4,0,0.22,7.4,span-12);

          // Front/rear structural frames and alternating diagonals make it read as a bridge
          // from a distance instead of a floating black bar.
          for(const x of [-5.55,5.55]){
              addBox(cdMat.steel,x,34.0,0,0.6,0.62,span-10);
              addBox(cdMat.steel,x,41.6,0,0.6,0.62,span-10);
              for(let i=0;i<=6;i++) addBox(cdMat.steel,x,37.8,-45+i*15,0.62,8.2,0.62);
              for(let i=0;i<6;i++){
                  const z1=-45+i*15, z2=z1+15;
                  if(i%2===0) addTruss(x,34.4,z1,41.2,z2);
                  else addTruss(x,41.2,z1,34.4,z2);
              }
          }

          // Four full-height legs and broad end caps visibly anchor the span on both sidewalks.
          // They sit close enough to be seen, while their nearest edge remains 18+ units
          // outside the road's playable bounds (road edge is currently z +/-14).
          for(const side of [-1,1]){
              const z=side*35;
              for(const x of [-4.15,4.15]) addBox(cdMat.steel,x,15.65,z,2.8,31.3,2.8);
              addBox(cdMat.steel,0,31.0,z,12.4,2.4,4.4);
              addBox(cdMat.backing,0,16.0,z,8.0,23.5,3.0);
              addBox(cdMat.neon.cyan,-4.22,16.0,z-side*1.55,0.28,25.0,0.3);
              addBox(cdMat.neon.mag,4.22,16.0,z-side*1.55,0.28,17.0,0.3);
              addBox(cdMat.neon.mag,0,43.0,z,3.4,0.55,3.4);
          }

          // Continuous neon silhouette plus five under-deck guide lights.
          addBox(cdMat.neon.cyan,-5.92,33.15,0,0.24,0.3,span-7);
          addBox(cdMat.neon.cyan,-5.92,42.7,0,0.24,0.24,span-7);
          addBox(cdMat.neon.mag,-5.96,41.95,0,0.26,0.18,span-14);
          for(let z=-36;z<=36;z+=18) addBox(cdMat.neon.cyan,0,deckY-1.65,z,7.4,0.18,1.0);

          cdGeo.skybridgeParts = cbMergeByMaterial(tmp);
        }
    }
    // PERF: persistent texture pool — sign/ad canvases are generated ONCE and reused across
    // every spawn AND every map reset (no per-instance canvas+GPU upload hitch on city entry).
    const cdTexCache = new Map();
    function cdCachedTex(key, gen){ let t=cdTexCache.get(key); if(!t){ t=gen(); t.__pooled=true; cdTexCache.set(key,t); } return t; }
    function cdTextTex(text, fg, opts){
        opts = opts || {}; const W = opts.w||512, H = opts.h||128;
        const cv = document.createElement('canvas'); cv.width=W; cv.height=H; const c = cv.getContext('2d');
        c.fillStyle = opts.bg||'#04060a'; c.fillRect(0,0,W,H);
        if (opts.border){ c.strokeStyle=fg; c.lineWidth=6; c.strokeRect(5,5,W-10,H-10); }
        c.fillStyle = fg; c.textAlign='center'; c.textBaseline='middle';
        c.shadowColor = fg; c.shadowBlur = opts.glow||20;
        c.font = `${opts.weight||'700'} ${opts.size||78}px ${opts.font||'Orbitron, Arial, sans-serif'}`;
        c.fillText(text, W/2, H/2);
        const t = new THREE.CanvasTexture(cv); t.colorSpace = THREE.SRGBColorSpace; t.anisotropy = 4; return t;
    }
    function cdGlyphTex(fg){
        const W=64,H=256; const cv=document.createElement('canvas'); cv.width=W; cv.height=H; const c=cv.getContext('2d');
        c.fillStyle=fg; c.fillRect(0,0,W,H);                       // bright neon panel (reads as a lit sign)
        c.fillStyle='rgba(3,6,12,0.82)'; c.textAlign='center'; c.textBaseline='middle'; c.font='800 42px Arial';
        const g='日京ウク新放客都電力夜光速未来街区東'.split('');
        for(let i=0;i<6;i++) c.fillText(g[(Math.random()*g.length)|0], W/2, 24+i*40);
        const t=new THREE.CanvasTexture(cv); t.colorSpace = THREE.SRGBColorSpace; return t;
    }
    function cdSignMesh(map, w, h, neonKey){
        const g = new THREE.Group();
        const back = new THREE.Mesh(cdGeo.box, cdMat.backing); back.scale.set(w+0.5,h+0.5,0.4); g.add(back);
        const face = new THREE.Mesh(cdGeo.plane, new THREE.MeshBasicMaterial({ map, transparent:false })); face.scale.set(w,h,1); face.position.z=0.22; g.add(face);
        const edge = new THREE.Mesh(cdGeo.box, cdMat.neon[neonKey]||cdMat.neon.cyan); edge.scale.set(w+0.5,0.18,0.5); edge.position.set(0,-(h/2+0.25),0.1); g.add(edge);
        g.userData.faceMesh = face; g.userData.faceMap = map;
        return g;
    }
    // randomly mark a sign group as animated (flicker / scrolling text)
    function cdMaybeAnimate(g, sign){
        // flicker only (toggles a mesh's visibility) — pool-safe, unlike scroll which would mutate a shared texture
        if (Math.random() < 0.34) { g.userData.anim = 'flicker'; g.userData.animSeed = Math.random()*99; g.userData.animFace = sign.userData.faceMesh; }
    }
    function cdBuildVerticalSign(side){
        const keys=['cyan','mag','blue']; const k=keys[(Math.random()*keys.length)|0];
        const fg = k==='cyan'?'#00e5ff':(k==='mag'?'#ff2d95':'#2d7bff');
        const g = new THREE.Group(); // ground-origin pylon: mast + raised neon panel
        const panelY = 12 + Math.random()*8, mastH = panelY + 5;
        const mast = new THREE.Mesh(cdGeo.cyl, cdMat.steel); mast.scale.set(0.3, mastH, 0.3); mast.position.y = mastH/2; g.add(mast);
        const sign = cdSignMesh(cdCachedTex('glyph:'+k+':'+((Math.random()*6)|0), ()=>cdGlyphTex(fg)), 2.4, 9.0, k); sign.position.set(0, panelY, 0.32); g.add(sign);
        g.userData.edgeOffset = 11; g.userData.faceCam = true; cdMaybeAnimate(g, sign);
        return g;
    }
