    function clearCyberDecor(){
        for(const d of cyberDecorObjects){ const o=d.obj; if(!o) continue;
            // pooled materials/textures (__pooled, e.g. cdMat.* and cached sign textures) persist for
            // reuse across every city rebuild; only per-instance materials (e.g. sign face maps) are disposed
            o.traverse(m=>{ if(m.isMesh && m.material && !m.material.__pooled){ if(m.material.map && !m.material.map.__pooled && m.material.map.dispose) m.material.map.dispose(); m.material.dispose(); } });
            if(o.parent) o.parent.remove(o);
        }
        cyberDecorObjects = []; cyberDecorBuilt = false;
    }
