    function initCyberDecor(){
        if (!player) return; cdEnsure(); clearCyberDecor();
        const px = player.position.x;
        const add=(obj, role, side, edgeOffset, span)=>{ scene.add(obj); cyberDecorObjects.push({obj, role, side, edgeOffset, span}); };
        // sidewalk rail on BOTH sides — fewer signs (mostly non-sign props), road-edge-relative
        const builders=[cdBuildVerticalSign,cdBuildHoloAd,cdBuildHangingSign,cdBuildRoundSign,cdBuildLamp,cdBuildLamp,cdBuildKiosk,cdBuildKiosk,cdBuildBarrier,cdBuildBarrier,cdBuildPod,cdBuildVents,cdBuildVents];
        const quality = getEffectiveGraphicsQualityName();
        activeCyberDecorQuality = quality;
        const decorProfiles = {
            performance: { edgeCount: 24, edgeStep: 32, shopCount: 2, shopStep: 420, chevronCount: 14, chevronStep: 72, carCount: 4 },
            balanced: { edgeCount: 32, edgeStep: 25, shopCount: 3, shopStep: 310, chevronCount: 18, chevronStep: 60, carCount: 6 },
            high: { edgeCount: 38, edgeStep: 21, shopCount: 4, shopStep: 230, chevronCount: 22, chevronStep: 52, carCount: 8 },
            ultra: { edgeCount: 44, edgeStep: 18, shopCount: 4, shopStep: 230, chevronCount: 26, chevronStep: 44, carCount: 10 }
        };
        const mobileDecorProfiles = {
            performance: { edgeCount: 14, edgeStep: 48, shopCount: 1, shopStep: 680, chevronCount: 10, chevronStep: 72, carCount: 3 },
            balanced: { edgeCount: 18, edgeStep: 39, shopCount: 1, shopStep: 560, chevronCount: 12, chevronStep: 66, carCount: 3 },
            high: { edgeCount: 24, edgeStep: 31, shopCount: 2, shopStep: 430, chevronCount: 15, chevronStep: 58, carCount: 4 },
            ultra: { edgeCount: 28, edgeStep: 27, shopCount: 2, shopStep: 380, chevronCount: 18, chevronStep: 52, carCount: 5 }
        };
        const lowPowerDesktopQuality = RUNTIME_LOW_POWER && quality === 'high' ? 'balanced' : quality;
        const decorProfile = MOBILE_RUNTIME
            ? mobileDecorProfiles[quality]
            : decorProfiles[lowPowerDesktopQuality];
        const COUNT=decorProfile.edgeCount, STEP=decorProfile.edgeStep; const span=COUNT*STEP;
        for(const side of [-1,1]){
            for(let i=0;i<COUNT;i++){
                const o = builders[(Math.random()*builders.length)|0](side);
                o.position.x = px - 140 + i*STEP + (side>0?9:0);
                o.rotation.y = o.userData.alongX ? 0 : (o.userData.hanging ? (side<0?Math.PI:0) : (side<0 ? 0.3 : Math.PI - 0.3));
                add(o,'edge',side, o.userData.edgeOffset||8, span);
            }
        }
        // a few shop signs at street level (road-edge-relative, well off the road)
        for(const side of [-1,1]){ for(let i=0;i<decorProfile.shopCount;i++){ const o=cdBuildShopSign(side); o.userData.edgeOffset=13; o.position.x=px - 80 + i*decorProfile.shopStep; add(o,'shop',side,13,decorProfile.shopCount*decorProfile.shopStep); } }
        // Floating skybridges: keep the detailed model, but make encounters rare.
        const mobilePerformance = MOBILE_RUNTIME && quality === 'performance';
        const SKYBRIDGE_COUNT = mobilePerformance ? 1 : 2, SKYBRIDGE_STEP = mobilePerformance ? 980 : 620;
        for(let i=0;i<SKYBRIDGE_COUNT;i++){
            const o=cdBuildGantry();
            o.position.set(px + 180 + i*SKYBRIDGE_STEP, 0, getRoadCenterZ());
            add(o,'gantry',0,0,SKYBRIDGE_COUNT*SKYBRIDGE_STEP);
        }
        // red chevron arrows along BOTH road edges
        const chevronCount = decorProfile.chevronCount;
        const chevronStep = decorProfile.chevronStep;
        for(const side of [-1,1]){ for(let i=0;i<chevronCount;i++){ const o=cdBuildChevrons(side); o.position.x=px - 120 + i*chevronStep; add(o,'chev',side,4.5,chevronCount*chevronStep); } }
        // flying cars crossing the road overhead (left↔right)
        for(let i=0;i<decorProfile.carCount;i++){ const o=cdBuildFlyingCar(); o.position.set(px + 80 + Math.random()*820, 30 + Math.random()*26, -60 + Math.random()*120); add(o,'car',0,0,0); }
        cyberDecorBuilt = true;
    }

    function scheduleAdaptiveCyberSceneRefresh() {
        if (!isBrowserBuild() || !player || gamePhase !== 0 || graphicsState.sceneRefreshPending) return;
        const requestedTier = getRequestedCyberBuildingTier();
        const quality = getEffectiveGraphicsQualityName();
        if (activeCyberBuildingTier === requestedTier && activeCyberDecorQuality === quality) return;
        graphicsState.sceneRefreshPending = true;
        setTimeout(() => {
            graphicsState.sceneRefreshPending = false;
            if (!player || gamePhase !== 0 || isGameOver) return;
            const nextTier = getRequestedCyberBuildingTier();
            const nextQuality = getEffectiveGraphicsQualityName();
            if (activeCyberBuildingTier === nextTier && activeCyberDecorQuality === nextQuality) return;
            initCity();
            requestShadowMapRefresh(null, true);
        }, 0);
    }

    // Exp2 sis katkısı bu eşiğin altında kalan piksel 8-bit çıktı ve bloom zincirinde
    // ölçülebilir bir renk farkı üretemez. Bu mesafenin ötesindeki sahne yine simüle
    // edilir; sadece GPU'ya çizim emri gönderilmez, yaklaştığında aynı durumda görünür.
    function getFogInvisibleDistance(padding = 0) {
        const fog = scene && scene.fog;
        if (fog && fog.isFogExp2 && fog.density > 0) {
            return Math.sqrt(-Math.log(1 / 4096)) / fog.density + padding;
        }
        if (fog && fog.isFog && Number.isFinite(fog.far)) return fog.far + padding;
        return (camera && Number.isFinite(camera.far) ? camera.far : 3000) + padding;
    }

    function getCyberVisibleAheadDistance() {
        const quality = getEffectiveGraphicsQualityName();
        if (MOBILE_RUNTIME && quality === 'performance') {
            return Math.min(adaptiveRenderDistance + 70, MOBILE_LOW_END ? 430 : 470);
        }
        const capByQuality = {
            performance: 420,
            balanced: 520,
            high: 640,
            ultra: 760
        };
        const qualityCap = capByQuality[quality] || capByQuality.balanced;
        const adaptiveScale = graphicsState.performanceLevel === 2 ? 0.70 : (graphicsState.performanceLevel === 1 ? 0.86 : 1);
        return Math.min(adaptiveRenderDistance + 60, qualityCap * adaptiveScale);
    }

    function updateCyberDecor(delta){
        if (!cyberDecorBuilt || !player) return;
        const px = player.position.x; const t = clock.getElapsedTime();
        const reMin = roadLimitZMin, reMax = roadLimitZMax;
        const fogCullAhead = Math.min(
            getFogInvisibleDistance(MOBILE_RUNTIME ? 80 : 120),
            getCyberVisibleAheadDistance() + (MOBILE_RUNTIME ? 50 : 90)
        );
        const quality = getEffectiveGraphicsQualityName();
        let decorStride = MOBILE_RUNTIME && quality === 'performance'
            ? (MOBILE_LOW_END ? 3 : (smoothedFps < 52 ? 3 : (smoothedFps < 58 ? 2 : 1)))
            : (quality === 'performance'
                ? 3
                : (quality === 'balanced' ? 2 : 1));
        if (graphicsState.performanceLevel === 1) decorStride = Math.max(decorStride, 2);
        else if (graphicsState.performanceLevel === 2) decorStride = Math.max(decorStride, 3);
        // Adaptive quality may change while the player is looking at an object.
        // Never apply stride thinning inside the stable near field; otherwise a
        // sign, traffic prop or its shadow vanishes for one quality sample and
        // appears again when FPS recovers. Far objects are still culled before
        // the stride changes become perceptible.
        const stableNearDistance = Math.min(420, Math.max(280, fogCullAhead * 0.62));
        for(let decorIndex = 0; decorIndex < cyberDecorObjects.length; decorIndex++){
            const d = cyberDecorObjects[decorIndex];
            const o = d.obj;
            const distanceAhead = o.position.x - px;
            if (decorStride > 1
                && (d.role === 'edge' || d.role === 'chev' || d.role === 'car')
                && decorIndex % decorStride !== 0
                && distanceAhead > stableNearDistance) {
                o.visible = false;
                continue;
            }
            if (d.role === 'car'){
                o.position.z += o.userData.vz; o.position.y += Math.sin(t*0.8 + o.userData.bob)*0.02; // cross the road in Z
                if (o.userData.vz > 0 && o.position.z > 72) o.position.z = -72;
                else if (o.userData.vz < 0 && o.position.z < -72) o.position.z = 72;
                if (o.position.x < px - 280){ o.position.x = px + 200 + Math.random()*720; o.position.y = 30 + Math.random()*26; }
                o.visible = (o.position.x - px) <= fogCullAhead;
                continue;
            }
            if (d.role === 'gantry'){
                if (o.position.x < px - 280) o.position.x += d.span;
                o.visible = (o.position.x - px) <= fogCullAhead;
                if (o.visible && o.userData.scanner){
                    o.userData.scanner.position.z = Math.sin(t*0.82 + o.userData.scannerPhase) * 44;
                    const pulse = 0.82 + Math.sin(t*5.2 + o.userData.scannerPhase)*0.18;
                    o.userData.scanner.scale.x = 0.32 * pulse;
                    o.userData.scanner.scale.y = 0.28 * pulse;
                }
                continue;
            }
            // road-edge-relative side decor (signs/props/chev): keep just outside the road
            o.position.z = d.side < 0 ? (reMin - d.edgeOffset) : (reMax + d.edgeOffset);
            if (o.position.x < px - 280) o.position.x += d.span;
            o.visible = (o.position.x - px) <= fogCullAhead;
            if (o.visible) {
                if (o.userData.faceCam) o.rotation.y = Math.atan2(px - o.position.x, player.position.z - o.position.z); // signs face the player
                if (o.userData.anim === 'flicker' && o.userData.animFace) o.userData.animFace.visible = (Math.sin(t*15 + o.userData.animSeed) + Math.sin(t*27 + o.userData.animSeed*1.7)) > -0.5; // blinking sign
                else if (o.userData.anim === 'scroll' && o.userData.animMap) o.userData.animMap.offset.x = (o.userData.animMap.offset.x + delta*0.35) % 1; // ticker
            }
        }
    }

    function checkCyberSkybridgeCollision(actualPhysicsHeight, previousPlayerY) {
        if (!cyberDecorBuilt || !player || isGameOver || reviveSequenceActive || noclipActive) return false;
        const playerHalfHeight = actualPhysicsHeight * 0.5;
        const sweptPlayerMinY = Math.min(previousPlayerY, player.position.y) - playerHalfHeight;
        const sweptPlayerMaxY = Math.max(previousPlayerY, player.position.y) + playerHalfHeight;

        for (const decor of cyberDecorObjects) {
            if (decor.role !== 'gantry') continue;
            const bridge = decor.obj;
            if (!bridge || !bridge.visible || bridge.userData.decorType !== 'cyber_skybridge') continue;

            const halfX = bridge.userData.collisionHalfX || 6.35;
            const minY = bridge.position.y + (bridge.userData.collisionMinY || 31.1);
            const maxY = bridge.position.y + (bridge.userData.collisionMaxY || 43.25);
            const halfZ = bridge.userData.collisionHalfZ || 54.5;
            const overlapsX = sweptXOverlaps(bridge.position.x, halfX, 0.08);
            const overlapsY = sweptPlayerMaxY > minY && sweptPlayerMinY < maxY;
            const overlapsZ = Math.abs(player.position.z - bridge.position.z) < halfZ + PLAYER_DEPTH * 0.5;

            if (overlapsX && overlapsY && overlapsZ) {
                gameOver("Kaza yaptın!");
                // A revive resumes in place. Recycle only the bridge that was hit so the
                // player cannot be killed again by the same volume as the effect ends.
                if (reviveSequenceActive && decor.span) bridge.position.x += decor.span;
                return true;
            }
        }
        return false;
    }

     function initCity() {
        clearCityBuildings();
        // Bina tiplerini her zaman tanÄ±mla (Meshe oluÅŸtururken lazÄ±m)
        ensureCyberBuildingTypes();
        if (curvedPathSystem && typeof curvedPathSystem.installMaterialBend === 'function') {
            // A building is a rigid object (or an InstancedMesh instance), not
            // a strip of road. Pivot-frame bending preserves its dimensions and
            // UVs on both the inside and outside of a curve.
            curvedPathSystem.installMaterialBend(cityBuildingMats, { mode: 'rigid' });
        }
        const NTYPES = cityBuildingTypes.length;

        // 1. KaynaklarÄ± (Geometry/Material) sadece EÄER YOKSA oluÅŸtur (Reset atÄ±nca tekrar Ã¼retmesin)
        const quality = getEffectiveGraphicsQualityName();
        const layerProfiles = {
            performance: [
                { count: 22, layerType: 0, minZOffset: 0 },
                { count: 12, layerType: 1, minZOffset: 78 },
                { count: 6, layerType: 2, minZOffset: 165 }
            ],
            balanced: [
                { count: 28, layerType: 0, minZOffset: 0 },
                { count: 16, layerType: 1, minZOffset: 74 },
                { count: 8, layerType: 2, minZOffset: 160 }
            ],
            high: [
                { count: 30, layerType: 0, minZOffset: 0 },
                { count: 18, layerType: 1, minZOffset: 72 },
                { count: 10, layerType: 2, minZOffset: 155 }
            ],
            ultra: [
                { count: 34, layerType: 0, minZOffset: 0 },
                { count: 24, layerType: 1, minZOffset: 70 },
                { count: 16, layerType: 2, minZOffset: 150 }
            ]
        };
        const effectiveLayerQuality = RUNTIME_LOW_POWER && quality === 'high' ? 'balanced' : quality;
        const layers = MOBILE_RUNTIME
            ? [
                { count: 16, layerType: 0, minZOffset: 0 },
                { count: 8, layerType: 1, minZOffset: 78 },
                { count: 4, layerType: 2, minZOffset: 165 }
            ]
            : layerProfiles[effectiveLayerQuality];
        
        const rangeX = 1500;
        const originX = player ? player.position.x : 0;
        
        const buildingBuckets = cityBuildingTypes.map(() => []);

        for(let side=0; side<2; side++) {
            const isLeft = side === 0;
            const sideBaseDistance = isLeft ? 45 : 55;

            layers.forEach(layer => {
                // near layer = shorter buildings, far layer = taller ones (skyline depth)
                const tierRange = activeCyberBuildingTier === 'lite'
                    ? [[0, 1], [1, 2], [2, NTYPES - 1]][layer.layerType]
                    : [[0, 2], [2, 4], [4, NTYPES - 1]][layer.layerType];
                const typeMin = Math.min(NTYPES - 1, tierRange[0]);
                const typeMax = Math.max(typeMin, Math.min(NTYPES - 1, tierRange[1]));

                const cell = rangeX / layer.count; // even spacing so the row reads as a continuous wall (no see-through gaps)
                for(let i=0; i<layer.count; i++) {
                    const typeIdx = Math.min(NTYPES - 1, Math.floor(Math.random() * (typeMax - typeMin + 1)) + typeMin);
                    const xPos = originX - 200 + (i + Math.random() * 0.45) * cell + layer.layerType * (cell * 0.33);
                    const dist = sideBaseDistance + layer.minZOffset + Math.random() * 40;
                    const zPos = isLeft ? -dist : dist;
                    const yPos = -2 - Math.random() * 6; // base ~ground, slightly sunk for varied skyline

                    const building = {
                        position: new THREE.Vector3(xPos, yPos, zPos),
                        typeIndex: typeIdx,
                        instanceMeshes: null,
                        instanceIndex: 0,
                        userData: {
                            sideLeft: isLeft,
                            originalY: yPos,
                            baseMinZ: sideBaseDistance + layer.minZOffset,
                            initialX: xPos,
                            initialY: yPos,
                            initialZ: zPos
                        }
                    };
                    buildingBuckets[typeIdx].push(building);
                    cityBuildings.push(building);
                }
            });
        }

        // one InstancedMesh per (type, material-part); all parts of a type share the building matrices
        for (let typeIdx = 0; typeIdx < cityBuildingTypes.length; typeIdx++) {
            const bucket = buildingBuckets[typeIdx];
            if (bucket.length === 0) continue;
            const type = cityBuildingTypes[typeIdx];
            const meshes = type.parts.map(part => {
                const im = new THREE.InstancedMesh(part.geo, part.mat, bucket.length);
                im.castShadow = false; im.receiveShadow = false; im.frustumCulled = false;
                // Matrisler DÜNYA-uzayı: kaydırmayı applyWorldRebase matris içinde yapar
                im.userData.worldRebaseExempt = true;
                scene.add(im); cityBuildingInstances.push(im);
                return im;
            });
            for (let i = 0; i < bucket.length; i++) {
                bucket[i].instanceMeshes = meshes;
                bucket[i].instanceIndex = i;
                syncCityBuildingMatrix(bucket[i]);
            }
        }
        initCyberDecor();
        primeCyberCityVisibility();
    }


