        mats.tunnelPanel = new THREE.MeshStandardMaterial({ color: 0x0a0e16, roughness: 0.7, metalness: 0.4 });
        mats.tunnelNeonMag = new THREE.MeshBasicMaterial({ color: 0xff2d95 });

        geoms.wall = new THREE.BoxGeometry(4.0, 18, 6.8);
        geoms.lowWall = new THREE.BoxGeometry(4.0, 3.5, 6.8);
        geoms.fallingWall = new THREE.BoxGeometry(4.0, 20, 6.8);
        // Çarpma şok halkası (birim yarıçap, scale ile büyütülür) + falling_wall iniş-hedef halkası
        geoms.impactRing = new THREE.RingGeometry(0.62, 1.0, 44);
        geoms.fwDropRing = new THREE.RingGeometry(2.35, 3.1, 40);
        geoms.slideBarrier = new THREE.BoxGeometry(2.0, 6.9, 6.8);
        geoms.vehicleSmall = new THREE.BoxGeometry(4.0, 1.6, 1.4); 
        geoms.vehicleCar = new THREE.BoxGeometry(10, 3.5, 5.2); 
        geoms.trainUnit = new THREE.BoxGeometry(16, 6.5, 6.2); 
        geoms.jumpPad = new THREE.CylinderGeometry(2.2, 2.2, 0.4, 32);
        
        geoms.jumpPadBeam = new THREE.CylinderGeometry(3.5, 2.0, 5.0, 16, 1, true); 
        geoms.jumpPadBeam.translate(0, 2.5, 0); 
