    function createFadeBeamTexture() {
        const canvas = document.createElement('canvas');
        canvas.width = 32; canvas.height = 64;
        const ctx = canvas.getContext('2d');
        const grd = ctx.createLinearGradient(0, 64, 0, 0); 
        grd.addColorStop(0, 'rgba(0, 255, 255, 0.6)'); 
        grd.addColorStop(1, 'rgba(0, 255, 255, 0)');   
        ctx.fillStyle = grd;
        ctx.fillRect(0,0, 32, 64);
        const tex = new THREE.CanvasTexture(canvas);
        tex.colorSpace = THREE.SRGBColorSpace;
        return tex;
    }
    
    function createGlowTexture() {
        const canvas = document.createElement('canvas'); canvas.width = 64; canvas.height = 64; const ctx = canvas.getContext('2d');
        const grd = ctx.createRadialGradient(32, 32, 0, 32, 32, 32);
        grd.addColorStop(0, 'rgba(255, 230, 100, 1)'); grd.addColorStop(0.3, 'rgba(255, 180, 0, 0.5)'); grd.addColorStop(1, 'rgba(0, 0, 0, 0)'); 
        ctx.fillStyle = grd; ctx.fillRect(0, 0, 64, 64); const texture = new THREE.CanvasTexture(canvas); texture.colorSpace = THREE.SRGBColorSpace; return texture;
    }

    function initCoinResources() {
        glowTexture = createGlowTexture();
        coinMaterial = new THREE.MeshStandardMaterial({ color: 0xffd700, emissive: 0xffaa00, emissiveIntensity: 0.3, roughness: 0.1, metalness: 1.0, transparent: false, opacity: 1.0, depthWrite: true });
        rimMaterial = new THREE.MeshStandardMaterial({ color: 0xB8860B, emissive: 0xff8800, emissiveIntensity: 0.3, roughness: 0.3, metalness: 1.0, transparent: false, opacity: 1.0, depthWrite: true });
        dollarMaterial = new THREE.MeshStandardMaterial({ color: 0xFFD700, emissive: 0xffaa00, emissiveIntensity: 0.5, roughness: 0.3, metalness: 1.0 });
        coinGeometry = new THREE.CylinderGeometry(1.6, 1.6, 0.4, 16); coinGeometry.rotateX(Math.PI / 2);
        const bodyMesh = new THREE.Mesh(coinGeometry, coinMaterial);
        const dollarGroup = createDollarSignGeometry(1.2, dollarMaterial); dollarGroup.position.z = 0.25;
        const dollarGroupBack = dollarGroup.clone(); dollarGroupBack.rotation.y = Math.PI; dollarGroupBack.position.z = -0.25;
        rimGeometry = new THREE.TorusGeometry(1.6, 0.35, 8, 16); const rimMesh = new THREE.Mesh(rimGeometry, rimMaterial);
        // A Sprite cannot use the curved-world vertex adapter. Once a train
        // installed the shared coin materials, the coin body followed the bend
        // while its Sprite halo stayed in straight screen space. Use a camera-
        // facing mesh so body and halo share the exact same rigid pivot.
        geoms.coinGlow = geoms.coinGlow || new THREE.PlaneGeometry(1, 1);
        mats.coinGlow = mats.coinGlow || new THREE.MeshBasicMaterial({
            map: glowTexture,
            color: 0xffaa00,
            transparent: true,
            blending: THREE.AdditiveBlending,
            depthWrite: false,
            depthTest: true,
            opacity: 0.3,
            side: THREE.DoubleSide,
            fog: true
        });
        const glowSprite = new THREE.Mesh(geoms.coinGlow, mats.coinGlow);
        glowSprite.scale.set(4, 4, 1);
        glowSprite.name = "glow";
        glowSprite.renderOrder = 7;
        coinPrototype = new THREE.Group();
        coinPrototype.add(bodyMesh); coinPrototype.add(rimMesh); coinPrototype.add(dollarGroup); coinPrototype.add(dollarGroupBack); coinPrototype.add(glowSprite);
        // Install the shared coin materials before any train can visit them with
        // its smooth bend mode. Every coin clone then owns one rigid curve pivot.
        curvedPathSystem?.installGpuCurvedObject?.(coinPrototype, false, { mode: 'rigid' });
        coinPrototype.updateMatrix();
    }

    function initGlobalParticles() {
        const geo = new THREE.BufferGeometry();
        for(let i=0; i<MAX_PARTICLES; i++) { pPos[i*3] = 0; pPos[i*3+1] = -1000; pPos[i*3+2] = 0; pCol[i*3] = 1; pCol[i*3+1] = 1; pCol[i*3+2] = 1; pData.push({ vx: 0, vy: 0, vz: 0, life: -1 }); }
        geo.setAttribute('position', new THREE.BufferAttribute(pPos, 3).setUsage(THREE.DynamicDrawUsage));
        geo.setAttribute('color', new THREE.BufferAttribute(pCol, 3).setUsage(THREE.DynamicDrawUsage));
        r185OptimizationStats.dynamicBufferHints += 2;
        const mat = new THREE.PointsMaterial({ size: 0.6, vertexColors: true, transparent: true, opacity: 1, blending: THREE.AdditiveBlending, depthWrite: false });
        globalParticleMesh = new THREE.Points(geo, mat); globalParticleMesh.frustumCulled = false;
        globalParticleMesh.visible = false;
        // Buffer DÜNYA-uzayı koordinat tutar: applyWorldRebase buffer'ı kaydırır, obje origin'de kalır
        globalParticleMesh.userData.worldRebaseExempt = true;
        scene.add(globalParticleMesh);
        initImpactFx();
    }

    function initImpactFx() {
        if (impactFxRings.length) return;
        for (let i = 0; i < IMPACT_RING_POOL; i++) {
            const mat = new THREE.MeshBasicMaterial({ color: 0xffffff, transparent: true, opacity: 0, blending: THREE.AdditiveBlending, depthWrite: false, side: THREE.DoubleSide });
            const ring = new THREE.Mesh(geoms.impactRing, mat);
            ring.rotation.x = -Math.PI / 2;
            ring.visible = false;
            ring.renderOrder = 6;
            ring.frustumCulled = false;
            scene.add(ring);
            impactFxRings.push({ mesh: ring, life: -1, dur: 0.5, maxScale: 6, baseOpacity: 0.85 });
        }
    }

    // Zeminde büyüyüp solan şok halkası. Havuz doluysa efekt sessizce atlanır (kritik değil).
    function spawnImpactRing(x, y, z, colorHex, maxScale = 6, dur = 0.5, baseOpacity = 0.85) {
        for (let i = 0; i < impactFxRings.length; i++) {
            const slot = impactFxRings[i];
            if (slot.life > 0) continue;
            slot.life = dur; slot.dur = dur; slot.maxScale = maxScale; slot.baseOpacity = baseOpacity;
            slot.mesh.material.color.setHex(colorHex);
            slot.mesh.material.opacity = baseOpacity;
            slot.mesh.position.set(x, y, z);
            slot.mesh.scale.setScalar(maxScale * 0.18);
            slot.mesh.visible = true;
            return;
        }
    }

    function updateImpactFx(delta) {
        for (let i = 0; i < impactFxRings.length; i++) {
            const r = impactFxRings[i];
            if (r.life <= 0) continue;
            r.life -= delta;
            if (r.life <= 0) { r.mesh.visible = false; r.mesh.material.opacity = 0; continue; }
            const t = 1 - (r.life / r.dur);
            const eased = 1 - (1 - t) * (1 - t);
            r.mesh.scale.setScalar(r.maxScale * (0.18 + 0.82 * eased));
            r.mesh.material.opacity = r.baseOpacity * (1 - eased);
        }
        if (impactShake > 0) impactShake = Math.max(0, impactShake - delta * 1.7);
    }

    function resetImpactFx() {
        for (let i = 0; i < impactFxRings.length; i++) {
            impactFxRings[i].life = -1;
            impactFxRings[i].mesh.visible = false;
            impactFxRings[i].mesh.material.opacity = 0;
        }
        impactShake = 0;
    }

    function spawnGlobalExplosion(x, y, z, colorHex, count = 20) {
        if (MOBILE_RUNTIME) count = Math.min(count, 12);
        const c = new THREE.Color(colorHex); let spawned = 0;
        for(let i=0; i<MAX_PARTICLES; i++) {
            if (pData[i].life <= 0) {
                pPos[i*3] = x + (Math.random()-0.5)*1.5; pPos[i*3+1] = y + (Math.random()-0.5)*1.5; pPos[i*3+2] = z + (Math.random()-0.5)*1.5;
                pCol[i*3] = c.r; pCol[i*3+1] = c.g; pCol[i*3+2] = c.b;
                pData[i].vx = (Math.random() - 0.5) * 0.8; pData[i].vy = Math.random() * 0.8 + 0.3; pData[i].vz = (Math.random() - 0.5) * 0.8; pData[i].life = 1.0; 
                spawned++; if (spawned >= count) break;
            }
        }
        if (spawned > 0) {
            globalParticleMesh.visible = true;
            globalParticleMesh.geometry.attributes.position.needsUpdate = true;
            globalParticleMesh.geometry.attributes.color.needsUpdate = true;
        }
    }

    function updateGlobalParticles(delta) {
        if (!globalParticleMesh || !globalParticleMesh.geometry) return;
        let bufferDirty = false;
        let activeCount = 0;
        const positions = globalParticleMesh.geometry.attributes.position.array;
        const frameScale = Math.max(0, Math.min(3, delta * 60));
        for(let i=0; i<MAX_PARTICLES; i++) {
            if (pData[i].life > 0) {
                pData[i].life -= delta * 1.5; 
                if (pData[i].life <= 0) {
                    // Son canlı slot burada ölürse de GPU buffer'ı mutlaka güncellenmeli.
                    // Önceki activeCount koşulu bu son upload'u atlıyor, parçacık ekranda
                    // donuyor ve sonraki patlamada "yeniden doğmuş" gibi görünüyordu.
                    positions[i*3] = 0;
                    positions[i*3+1] = -1000;
                    positions[i*3+2] = 0;
                    bufferDirty = true;
                } else {
                    activeCount++;
                    pData[i].vy -= 0.02 * frameScale;
                    positions[i*3] += pData[i].vx * frameScale;
                    positions[i*3+1] += pData[i].vy * frameScale;
                    positions[i*3+2] += pData[i].vz * frameScale;
                    bufferDirty = true;
                }
            }
        }
        if (bufferDirty) globalParticleMesh.geometry.attributes.position.needsUpdate = true;
        // Havuzda canlı slot yokken Points mesh'ini tamamen çizim dışına al. Böylece
        // eski sarı/mavi slotlar herhangi bir buffer/rebase güncellemesinde tekrar
        // görünemez; yeni ve kasıtlı bir patlama mesh'i yeniden açar.
        globalParticleMesh.visible = activeCount > 0;
    }

    function createDollarSignGeometry(size = 1.0, material = null) {
        const group = new THREE.Group();
        const vGeo = new THREE.BoxGeometry(0.15 * size, 1.8 * size, 0.1 * size);
        const hGeo = new THREE.BoxGeometry(0.8 * size, 0.2 * size, 0.1 * size);
        const sideGeo = new THREE.BoxGeometry(0.2 * size, 0.6 * size, 0.1 * size);
        const mat = material || new THREE.MeshStandardMaterial({ color: 0xffd700, emissive: 0xffaa00, roughness: 0.2, metalness: 1.0 });
        const vMesh = new THREE.Mesh(vGeo, mat); group.add(vMesh);  
        const top = new THREE.Mesh(hGeo, mat); top.position.y = 0.6 * size; group.add(top);
        const mid = new THREE.Mesh(hGeo, mat); mid.position.y = 0; group.add(mid);
        const bot = new THREE.Mesh(hGeo, mat); bot.position.y = -0.6 * size; group.add(bot);
        const left = new THREE.Mesh(sideGeo, mat); left.position.set(-0.35 * size, 0.3 * size, 0); group.add(left);
        const right = new THREE.Mesh(sideGeo, mat); right.position.set(0.35 * size, -0.3 * size, 0); group.add(right);
        return group;
    }

    function onWindowResize() {
        updateMobileLayoutMode();
        const viewport = MOBILE_RUNTIME ? getMobileViewportSize() : {
            width: Math.max(1, window.innerWidth),
            height: Math.max(1, window.innerHeight)
        };
        camera.fov = MOBILE_RUNTIME && viewport.height > viewport.width ? 74 : 65;
        camera.aspect = viewport.width / viewport.height;
        camera.updateProjectionMatrix();
        const preset = getQualityPreset();
        renderer.setPixelRatio(gfxComputePixelRatio(preset));
        renderer.setSize(viewport.width, viewport.height);
        gfxResize();
    }

    // Portal previews run the game inside an iframe. Making the canvas
    // focusable and focusing it before a lock request prevents the first
    // Space press from being consumed by the Inspector rather than the game.
    // This is deliberately best-effort: browsers may decline focus while a
    // portal overlay is active, but gameplay must remain available either way.
    function focusGameplaySurface() {
        if (!renderer || !renderer.domElement) return false;
        const surface = renderer.domElement;
        if (!surface.hasAttribute('tabindex')) surface.tabIndex = 0;
        try {
            surface.focus({ preventScroll: true });
            return document.activeElement === surface;
        } catch (error) {
            try {
                surface.focus();
                return document.activeElement === surface;
            } catch (innerError) {
                return false;
            }
        }
    }

    function onMouseMove(event) {
        if (event && (Math.abs(event.movementX || 0) > 0 || Math.abs(event.movementY || 0) > 0)) {
            markMouseInputActive();
        }
        if (document.pointerLockElement === renderer.domElement && !isGameOver) {
            // Pointer-lock yeni yakalandığında tarayıcı tek seferlik dev bir movementX
            // gönderebilir → kamera anında limite çarpıp "ışınlanıyor" gibi görünür. İlk
            // olayı yut ve sonraki olaylarda per-olay büyüklüğü makul bir tavana sıkıştır.
            if (pointerJustLocked) { pointerJustLocked = false; return; }
            if (!menuState.mouseControlEnabled) return;
            const MAX_MOUSE_STEP = 110;
            const mvX = Math.max(-MAX_MOUSE_STEP, Math.min(MAX_MOUSE_STEP, event.movementX || 0));
            const mvY = Math.max(-MAX_MOUSE_STEP, Math.min(MAX_MOUSE_STEP, event.movementY || 0));
            if (Math.abs(mvX) > 0 || Math.abs(mvY) > 0) {
                lastCameraLookInputAt = performance.now();
                cameraAutoCenterActive = false;
            }
            const sensitivity = BASE_MOUSE_SENSITIVITY * clampNumber(menuState.mouseSensitivity, 0.45, 1.85, 1);
            yaw -= mvX * sensitivity;
            pitch += mvY * sensitivity * (menuState.invertY ? 1 : -1);
            const limitPitch = 75 * (Math.PI / 180); pitch = Math.max(-limitPitch, Math.min(limitPitch, pitch));
            const limitYaw = 80 * (Math.PI / 180); const centerYaw = CAMERA_CENTER_YAW;
            yaw = Math.max(centerYaw - limitYaw, Math.min(centerYaw + limitYaw, yaw));
        }
    }

    function bindPendingControl(code) {
        if (!pendingControlBinding) return false;
        const target = pendingControlBinding;
        if (isBlockedControlBindingCode(code)) {
            playUiErrorSound();
            return true;
        }
        menuState.controlBindings = normalizeControlBindings(menuState.controlBindings);
        menuState.controlBindings[target.action] = code;
        menuState.controlBindingVersion = CONTROL_BINDING_VERSION;
        pendingControlBinding = null;
        resetControlActionState();
        persistAndApplySettings(true);
        renderSettingsPanel(target.surface);
        if (ui.pauseControls) ui.pauseControls.innerText = getControlSummaryText();
        return true;
    }

    function cancelPendingControlBinding() {
        if (!pendingControlBinding) return false;
        const surface = pendingControlBinding.surface;
        pendingControlBinding = null;
        renderSettingsPanel(surface);
        playUiConfirmSound();
        return true;
    }

    function pressControlAction(action, isRepeat = false) {
        if (!CONTROL_ACTION_ORDER.includes(action)) return;
        CONTROL_ACTION_STATE[action] = true;
        if (isGameOver || isGamePaused || mainMenuVisible) return;
        if (!isRepeat && tutorialDirector && (action === 'moveLeft' || action === 'moveRight')) {
            tutorialDirector.onAction(action === 'moveLeft' ? 'left' : 'right');
        }
        if (action === 'slide') {
            if (!isRepeat && !isSliding) startSlide();
            return;
        }
        if (action === 'jump') {
            if (!isRepeat && isJumping) {
                if (getActiveSpecialAbility() === 'doubleJump') {
                    tryUseDoubleJump();
                } else if (getActiveSpecialAbility() !== 'glide') {
                    queueJumpInput(0.06);
                }
            }
            return;
        }
        if (action === 'doubleJump') {
            if (!isRepeat && isJumping) tryUseDoubleJump();
            return;
        }
        if (action === 'timeSlow') {
            // E / middle mouse / mobile double tap all share one glove-skill pipeline.
            if (!isRepeat) triggerActiveHandSkill();
        }
    }

    function releaseControlAction(action) {
        if (!CONTROL_ACTION_ORDER.includes(action)) return;
        CONTROL_ACTION_STATE[action] = false;
        if ((action === 'jump' || action === 'doubleJump') && !CONTROL_ACTION_STATE.jump && !gamepadJumpHeld) {
            jumpKeyPressed = false;
            jumpQueue = false;
        }
    }

    function pressControlCode(code, isRepeat = false) {
        const actions = getActionsForControlCode(code);
        actions.forEach((action) => pressControlAction(action, isRepeat));
        return actions.length > 0;
    }

    function releaseControlCode(code) {
        const actions = getActionsForControlCode(code);
        actions.forEach((action) => releaseControlAction(action));
        return actions.length > 0;
    }

    function mouseButtonToControlCode(button) {
        if (button === 0) return 'MouseLeft';
        if (button === 1) return 'MouseMiddle';
        if (button === 2) return 'MouseRight';
        return '';
    }
    
    function startSlide() {
        const blockingSkyLaunch = megaJumpSpawned && !onSkyLayer && (isSkyFading || skyTransitionInvulnTimer > 0);
        if (blockingSkyLaunch || (tutorialDirector && typeof tutorialDirector.blocksSlide === 'function' && tutorialDirector.blocksSlide())) return false;
        isSliding = true; slideTimer = slideDuration; playSlideSound();
        document.body.classList.add('sliding');
        if (ui.speedVignette) ui.speedVignette.classList.add('sliding-vignette');
        const roofSupported = snapPlayerToTrainRoofIfSupported(slideHeight);
        if (isJumping && !roofSupported) { playerVelocityY = -0.8; isSlamming = true; }
        if (tutorialDirector) tutorialDirector.onAction('slide');
        return true;
    }

    function createWindSystem() {
        const count = isMobilePerformanceGraphics() ? 10 : 30;
        if (!sharedWindGeometry) sharedWindGeometry = new THREE.BoxGeometry(6, 0.05, 0.05);
        if (!sharedWindMaterial) {
            sharedWindMaterial = new THREE.MeshBasicMaterial({ color: 0xffffff, transparent: true, opacity: 0.05 });
        }
        for(let i = 0; i < count; i++) {
            const wind = new THREE.Mesh(sharedWindGeometry, sharedWindMaterial);
            resetWindParticle(wind); wind.position.x = player.position.x + (Math.random() * 100); scene.add(wind); windParticles.push(wind);
        }
    }

    function resetWindParticle(wind) {
        wind.position.x = player.position.x + 100 + Math.random() * 60;
        wind.position.y = player.position.y + (Math.random() - 0.5) * 25;
        wind.position.z = player.position.z + (Math.random() - 0.5) * 40;
        wind.userData.speed = 2.0 + Math.random() * 2.0;
    }

    function updateWindParticles(delta) {
        const speedRatio = Math.max(0, (moveSpeed - minMoveSpeed) / (maxMoveSpeed - minMoveSpeed));
        const baseIntensity = 0.2;
        const totalIntensity = baseIntensity + (Math.pow(speedRatio, 1.5) * (1 - baseIntensity));
        const slideBoost = isSliding ? 3.0 : 1.0;
        const glideActive = isGlideActive();
        const glideBoost = glideActive ? 2.4 : 1.0;
        const bhopBoost = 1.0 + (bhopCombo * 0.1);
        const windMult = (1 + speedRatio * 0.5) * slideBoost * glideBoost * bhopBoost;
        if (windWasSliding !== isSliding) {
            if (sharedWindMaterial) sharedWindMaterial.color.setHex(isSliding ? 0x00ffff : 0xffffff);
            windWasSliding = isSliding;
        }
        if (sharedWindMaterial) {
            sharedWindMaterial.color.setHex(isSliding ? 0x00ffff : 0xffffff);
            sharedWindMaterial.opacity = glideActive
                ? Math.max(0.2, totalIntensity * 0.42)
                : (isSliding ? (totalIntensity * 0.18) * 1.5 : (totalIntensity * 0.18));
        }

        for (let i = 0; i < windParticles.length; i++) {
            const wind = windParticles[i];
            wind.position.x -= wind.userData.speed * windMult;
            if (wind.position.x < player.position.x - 30) resetWindParticle(wind);
        }

        const vignette = ui.speedVignette;
        if (vignette && !shieldActive && trafficBonusTimer <= 0) {
            vignette.classList.toggle('sliding-vignette', isSliding);
            vignette.style.opacity = isSliding ? 0.3 : totalIntensity * 0.35;
        }
    }
    function spawnArrowEffect(type) {
        if (arrowEffectPool.length === 0) return;
        const isBlue = type === 'blue';
        const color = isBlue ? '#00ffff' : (type === 'green' ? '#00ff00' : '#ff0000');
        const arrowChar = (type === 'green' || isBlue) ? '⬆' : '⬇';
        
        for (let i = 0; i < arrowEffectPool.length; i++) { 
            const arrow = arrowEffectPool[i];
            if (arrow._hideTimer) {
                clearTimeout(arrow._hideTimer);
                arrow._hideTimer = null;
            }
            arrow.className = 'traffic-arrow ' + (type === 'red' ? 'arrow-down-anim' : ''); 
            arrow.innerHTML = arrowChar;
            arrow.style.color = color;
            const size = 40 + Math.random() * 30; arrow.style.fontSize = size + 'px';
            const rot = (Math.random() - 0.5) * 40; arrow.style.setProperty('--r', rot + 'deg');
            const isLeft = Math.random() > 0.5; const spread = 2 + Math.random() * 13; 
            if (isLeft) { arrow.style.left = spread + '%'; arrow.style.right = 'auto'; } else { arrow.style.right = spread + '%'; arrow.style.left = 'auto'; }
            arrow.style.top = (10 + Math.random() * 80) + '%'; arrow.style.animationDelay = (Math.random() * 0.8) + 's';
            arrow.style.display = 'block';
            arrow.style.animation = 'none';
            void arrow.offsetWidth;
            arrow.style.animation = '';
            arrow._hideTimer = setTimeout(() => {
                arrow.style.display = 'none';
                arrow._hideTimer = null;
            }, 2000); 
        }
    }

    function createShieldMesh() {
        const geo = new THREE.IcosahedronGeometry(1.5, 0);
        const mat = new THREE.MeshPhongMaterial({ color: 0x00ffff, emissive: 0x0044aa, transparent: true, opacity: 0.8, shininess: 100 });
        const shield = new THREE.Mesh(geo, mat); shield.name = 'shield';
        const ringGeo = new THREE.TorusGeometry(2.2, 0.1, 8, 32); const ringMat = new THREE.MeshBasicMaterial({ color: 0xffffff, transparent: true, opacity: 0.5 });
        const ring = new THREE.Mesh(ringGeo, ringMat); shield.add(ring); return shield;
    }

    function resetCoinVisuals(coin) {
        if (!coin) return;
        coin.traverse((child) => {
            if (!child.material) return;
            if (child.name === "glow") {
                child.material.transparent = true;
                child.material.opacity = 0.3;
                child.material.depthWrite = false;
                child.material.needsUpdate = true;
                return;
            }
            if (child.material === coinMaterial || child.material === rimMaterial || child.material === dollarMaterial) {
                child.material.transparent = false;
                child.material.opacity = 1.0;
                child.material.depthWrite = true;
                child.material.needsUpdate = true;
            }
        });
    }

    function createCoin(x, z, parent = scene, yOffset = 2.5) { 
        let coin; if (coinPool.length > 0) { coin = coinPool.pop(); coin.visible = true; } else { coin = coinPrototype.clone(); }
        const glowRef = coin.userData.glowRef || coin.getObjectByName("glow");
        coin.rotation.y = Math.PI / 2; coin.position.set(x, yOffset, z);
        resetCoinVisuals(coin);
        coin.userData = {
            ...coin.userData,
            rotSpeed: 2.0 + Math.random(),
            baseY: yOffset,
            bobOffset: Math.random() * Math.PI * 2,
            glowRef,
            elementalGpuCurved: true,
            elementalCurveMode: 'rigid'
        };
        parent.add(coin); coins.push(coin);
        return coin;
    }
    
    function recycleCoin(coin) {
        coin.visible = false; if (coin.parent) coin.parent.remove(coin); coinPool.push(coin);
    }

    function activateShield() {
        shieldActive = true; shieldTimer = shieldDuration;
        if (ui.shieldBar) { ui.shieldBar.style.display = 'block'; ui.shieldBar.classList.remove('shield-warning'); }
        if (ui.speedVignette) ui.speedVignette.classList.add('shield-active-vignette');
        playPickupSound();
    }

    function deactivateShield() {
        shieldActive = false;
        if (ui.shieldBar) { ui.shieldBar.style.display = 'none'; ui.shieldBar.classList.remove('shield-warning'); }
        if (ui.speedVignette) ui.speedVignette.classList.remove('shield-active-vignette');
    }

    function isXInsideTunnelRange(x, padding = 0) {
        return tunnels.some((t) => t && x >= t.startX - padding && x <= t.endX + padding);
    }

    function getSnowTunnelCoveringX(x, padding = 0) {
        return tunnels.find((t) => t?.mesh?.userData?.snowIceTunnel
            && x >= t.startX - padding
            && x <= t.endX + padding) || null;
    }

    function removeJumpPadsInTunnelRange(startX, endX, padding = 90) {
        for (let i = jumpPads.length - 1; i >= 0; i--) {
            const pad = jumpPads[i];
            if (!pad || pad.position.x < startX - padding || pad.position.x > endX + padding) continue;
            scene.remove(pad);
            disposeNode(pad);
            jumpPads.splice(i, 1);
        }
    }

    // PERF (2026-07-19 ilk-giriş hitch): ring geo+mat ve particle mat her spawn'da
    // yaratılıyordu; İLK pad spawn'ında PointsMaterial shader'ı OYUN İÇİNDE derleniyordu
    // (ölçüldü: t=2.4s'te 13.8ms spike, prog+1). Paylaşımlı cache — geoms/mats registry'de
    // olduğundan disposeNode koruması otomatik. Particle BufferGeometry per-pad KALIR
    // (pozisyonlar pad başına bağımsız animasyonlu).
    function ensureJumpPadShared() {
        if (geoms.jumpPadRing) return;
        geoms.jumpPadRing = new THREE.TorusGeometry(1.5, 0.1, 8, 16);
        mats.jumpPadRing = new THREE.MeshBasicMaterial({ color: 0xffffff });
        mats.jumpPadParticles = new THREE.PointsMaterial({ color: 0x00ffff, size: 0.15, transparent: true, opacity: 0.6 });
    }

    function createJumpPad(x, z) {
        if (isXInsideTunnelRange(x, 90)) return null;
        ensureJumpPadShared();
        const padGroup = new THREE.Group();
        const pad = new THREE.Mesh(geoms.jumpPad, mats.jumpPad);
        padGroup.add(pad);

        const ring = new THREE.Mesh(geoms.jumpPadRing, mats.jumpPadRing);
        ring.rotation.x = -Math.PI / 2;
        ring.position.y = 0.21;
        padGroup.add(ring);

        const beam = new THREE.Mesh(geoms.jumpPadBeam, mats.jumpPadBeam);
        padGroup.add(beam);
        
        const pCount = 15;
        const pGeo = new THREE.BufferGeometry();
        const pPosArr = new Float32Array(pCount * 3);
        const pSpeeds = [];
        
        for(let i=0; i<pCount; i++) {
            const r = Math.random() * 2.0;
            const theta = Math.random() * Math.PI * 2;
            pPosArr[i*3] = r * Math.cos(theta);
            pPosArr[i*3+1] = Math.random() * 5.0; 
            pPosArr[i*3+2] = r * Math.sin(theta);
            pSpeeds.push(0.05 + Math.random() * 0.1);
        }
        
        pGeo.setAttribute('position', new THREE.BufferAttribute(pPosArr, 3));
        const particles = new THREE.Points(pGeo, mats.jumpPadParticles);
        padGroup.add(particles);

        padGroup.position.set(x, 0.2, z);
        padGroup.userData = { rotSpeed: 1.0, particles: particles, pSpeeds: pSpeeds, triggered: false }; 

        scene.add(padGroup);
        jumpPads.push(padGroup);
        requestShadowMapRefresh(x);
        return padGroup;
    }

    function createWorld() {
        rebuildLaneState(laneExpansionCount);
        rebuildMainRoadMesh();
        createLanesDecor();
        
        leftBarrier = createDetailedBarrier(); 
        leftBarrier.position.set(0, 0, getBarrierPositionZ(-1));
        scene.add(leftBarrier);
        
        rightBarrier = createDetailedBarrier(); 
        rightBarrier.position.set(0, 0, getBarrierPositionZ(1)); 
        scene.add(rightBarrier);
        requestShadowMapRefresh();
    }

    function createLanesDecor() {
        laneLines.forEach(l => { disposeNode(l); }); laneLines = [];
        const lineSeparators = getLaneSeparators();
        const entries = [];
        lineSeparators.forEach((lineZ) => {
            for(let i = -100; i < 600; i += 18) entries.push({ x: (player ? player.position.x : 0) + i, y: 0.02, z: lineZ });
        });
        createLaneLineBatch(entries, mats.laneLine, laneLines);
    }

    const laneLineMatrixDummy = new THREE.Object3D();
    function ensureLaneLineResources() {
        if (!geoms.laneLine) geoms.laneLine = new THREE.PlaneGeometry(8, 0.5);
        if (!mats.laneLine) {
            mats.laneLine = new THREE.MeshStandardMaterial({
                color: 0xffff88,
                emissive: 0x444400,
                roughness: 0.4,
                metalness: 0.6,
                polygonOffset: true,
                polygonOffsetFactor: -2,
                polygonOffsetUnits: -2
            });
            mats.laneLine.userData.isRoadColor = true;
        }
    }

    // Yüzlerce aynı yol çizgisini ayrı Mesh olarak göndermek yerine aynı geometriyi
    // InstancedMesh ile tek draw-call'da çizer. Matrisler eski Mesh dönüşümlerinin aynısıdır;
    // bu nedenle renk, konum, boyut, ışık ve animasyon görünümü değişmez.
    function createLaneLineBatch(entries, material, array) {
        if (!entries || !entries.length) return null;
        ensureLaneLineResources();
        const batch = new THREE.InstancedMesh(geoms.laneLine, material || mats.laneLine, entries.length);
        batch.name = 'lane_line_batch';
        batch.frustumCulled = false;
        batch.userData.laneLineInstances = entries;
        laneLineMatrixDummy.rotation.set(-Math.PI / 2, 0, 0);
        laneLineMatrixDummy.scale.set(1, 1, 1);
        for (let i = 0; i < entries.length; i++) {
            const e = entries[i];
            laneLineMatrixDummy.position.set(e.x, e.y, e.z);
            laneLineMatrixDummy.updateMatrix();
            batch.setMatrixAt(i, laneLineMatrixDummy.matrix);
        }
        batch.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
        batch.instanceMatrix.needsUpdate = true;
        array.push(batch);
        scene.add(batch);
        return batch;
    }

    function recycleLaneLineBatch(batch) {
        const entries = batch && batch.userData ? batch.userData.laneLineInstances : null;
        if (!entries) return;
        let changed = false;
        const batchWorldX = batch.position.x;
        laneLineMatrixDummy.rotation.set(-Math.PI / 2, 0, 0);
        laneLineMatrixDummy.scale.set(1, 1, 1);
        for (let i = 0; i < entries.length; i++) {
            const e = entries[i];
            if (batchWorldX + e.x >= player.position.x - 100) continue;
            e.x += 700;
            laneLineMatrixDummy.position.set(e.x, e.y, e.z);
            laneLineMatrixDummy.updateMatrix();
            batch.setMatrixAt(i, laneLineMatrixDummy.matrix);
            changed = true;
        }
        if (changed) batch.instanceMatrix.needsUpdate = true;
    }

    function createSingleLaneLine(relX, z, array, y = 0.02) {
        // PERF (2026-07-07 hitch fix): geo+mat ESKİDEN her çizgide yaratılıyordu (faz-geçişi/
        // şerit-değişiminde 40+ çizgi toplu → 858 geo+mat/oturum → shader/GC hitch). Paylaşımlı.
        if (!geoms.laneLine) {
            geoms.laneLine = new THREE.PlaneGeometry(8, 0.5);
            mats.laneLine = new THREE.MeshStandardMaterial({
                color: 0xffff88,
                emissive: 0x444400,
                roughness: 0.4,
                metalness: 0.6,
                polygonOffset: true,
                polygonOffsetFactor: -2,
                polygonOffsetUnits: -2
            });
            mats.laneLine.userData.isRoadColor = true;
        }
        const line = new THREE.Mesh(geoms.laneLine, mats.laneLine);
        line.rotation.x = -Math.PI / 2;
        const startY = (array === animatingLines && y < -4.5) ? -5 : y;
        line.position.set(player ? player.position.x + relX : relX, startY, z);
        line.userData.relativeX = relX; array.push(line); scene.add(line);
    }

    function updateLanesProgress() {
        levelCurveVisualFrame += 1;
        laneLines.forEach(line => {
            if (line.userData && line.userData.laneLineInstances) recycleLaneLineBatch(line);
            else if (line.position.x < player.position.x - 100) line.position.x += 700;
        });
        animatingLines.forEach(line => {
            if (line.userData && line.userData.laneLineInstances) recycleLaneLineBatch(line);
            else if (line.position.x < player.position.x - 100) line.position.x += 700;
        });
        if (ground) {
            ground.position.x = player.position.x + 150;
            ground.position.z = getRoadCenterZ();
            // Doku dünyaya sabit: mesh player'ı takip ettiğinden offset mesh-X'e bağlanır
            // (offset = meshX / kareBoyu; kare = 1500 / repeat.x = 24 birim).
            // Floating origin: meshX artık sabit → dünyaya-sabitlik sanal X ile sağlanır.
            const roadOffset = ((ground.position.x + worldScrollX) / 24) % 1;
            if (roadTexScroll) roadTexScroll.offset.x = roadOffset;
            if (roadTexLane) roadTexLane.offset.x = roadOffset;
            if (roadNormalTexScroll) roadNormalTexScroll.offset.x = roadOffset;
            if (roadNormalTexLane) roadNormalTexLane.offset.x = roadOffset;
            if (roadRoughTexScroll) roadRoughTexScroll.offset.x = roadOffset;
            if (roadRoughTexLane) roadRoughTexLane.offset.x = roadOffset;
        }
        if (newLaneSegment) newLaneSegment.position.x = player.position.x + 150;

        // 240 is the common repeat period of rails (40), posts (20), and
        // barrier lights (80). Recycling on 80 moved rail seams by 20 units,
        // which read as the barrier sliding even when every matrix was stable.
        const segmentSize = 240;
        const barrierX = Math.floor((player.position.x + worldScrollX) / segmentSize) * segmentSize + 150 - worldScrollX;
        // Snap parents first. Building curved matrices against their previous
        // transform and moving the parent afterwards caused the visible spin.
        leftBarrier.position.x = barrierX;
        leftBarrier.position.z = getBarrierPositionZ(-1);
        rightBarrier.position.x = barrierX;
        if (!isAnimatingLane) rightBarrier.position.z = getBarrierPositionZ(1);

        if (curvedPathSystem) {
            // Curved lane paint is generated from virtual-world anchors below;
            // avoid rewriting the hidden straight batches as well.
            if (ground) curvedPathSystem.deformRoad(ground, player.position.x);
            updateCurvedLaneGuides();
        }
        // Parent positions are already final for this frame.
    }

    function startLaneAddition() {
        if (isAnimatingLane) return;
        isAnimatingLane = true; 
        laneAnimProgress = 0; 
        earthquakeIntensity = 0.9; 
        playEarthquakeSound();

        laneAnimStartLimitZMax = roadLimitZMax;
        laneAnimTargetLimitZMax = roadLimitZMax + LANE_WIDTH;
        laneAnimFloorY = getActiveRoadFloorY();

        const skyLaneEdgeOverlap = onSkyLayer ? 1.2 : 0;
        const laneWidth = LANE_WIDTH + skyLaneEdgeOverlap;
        const laneGeometry = new THREE.PlaneGeometry(1500, laneWidth, 96, 1);
        curvedPathSystem?.finalizeProceduralGeometry?.(laneGeometry, { segmentLength: 1500 / 96 });
        const laneMaterial = (mats.roadLane || mats.road).clone();
        laneMaterial.userData = { ...(laneMaterial.userData || {}), elementalLaneExpansionMaterial: true };
        delete laneMaterial.userData.elementalCurvedPathMaterial;
        laneMaterial.polygonOffset = true;
        laneMaterial.polygonOffsetFactor = -1;
        laneMaterial.polygonOffsetUnits = -1;
        ['map', 'normalMap', 'roughnessMap', 'metalnessMap', 'aoMap'].forEach((key) => {
            if (laneMaterial[key]) laneMaterial[key].__pooled = true;
        });
        newLaneSegment = new THREE.Mesh(laneGeometry, laneMaterial);
        newLaneSegment.rotation.x = -Math.PI / 2;
        newLaneSegment.userData.skyLaneEdgeOverlap = skyLaneEdgeOverlap;
        newLaneSegment.userData.elementalSplineLaneExpansion = true;
        newLaneSegment.position.set(player.position.x + 150, laneAnimFloorY + 0.008, laneAnimStartLimitZMax + (laneWidth * 0.5));
        // Plane local Y becomes world lane-right after the -90deg rotation.
        // Scaling and centring in logical lane space lets the spline shader map
        // the animation along its local side/binormal on every curve sample.
        newLaneSegment.scale.y = 0.001;
        newLaneSegment.receiveShadow = true; 
        newLaneSegment.frustumCulled = false;
        curvedPathSystem?.installGpuCurvedObject?.(newLaneSegment, false, {
            mode: 'spline',
            baseY: laneAnimFloorY,
            centerZ: getRoadCenterZ()
        });
        curvedPathSystem?.stabilizeObjectBounds?.(newLaneSegment, {
            lateralPadding: getRoadHalfWidth() + LANE_WIDTH * 2,
            verticalPadding: 16
        });
        scene.add(newLaneSegment);

        // PERF: paylaşımlı fade-materyali (tüm yeni-şerit çizgileri birlikte fade-in olur) +
        // paylaşımlı çizgi geometrisi.
        ensureLaneLineResources();
        if (!mats.laneLineFade) {
            mats.laneLineFade = new THREE.MeshStandardMaterial({
                color: 0xffff88,
                emissive: 0x444400,
                roughness: 0.4,
                metalness: 0.6,
                transparent: true,
                opacity: 0.0,
                depthWrite: false,
                polygonOffset: true,
                polygonOffsetFactor: -2,
                polygonOffsetUnits: -2
            });
            mats.laneLineFade.userData.isRoadColor = true;
        }
        const entries = [];
        for(let i = -100; i < 600; i += 18) entries.push({ x: player.position.x + i, y: laneAnimFloorY + 0.03, z: laneAnimStartLimitZMax });
        createLaneLineBatch(entries, mats.laneLineFade, animatingLines);
        
        if (ui.infoText) ui.infoText.style.display = "none";
    }

function updateLaneAnimation(delta) {
        if (!isAnimatingLane) { 
            if (earthquakeIntensity > 0) earthquakeIntensity -= delta * 0.5; else earthquakeIntensity = 0; return; 
        }
        
        laneAnimProgress += delta * 0.8; 
        if (laneAnimProgress > 1.0) laneAnimProgress = 1.0;
        
        earthquakeIntensity = 0.6 + Math.random() * 0.4;
        
        const t = getLaneAnimationEase();
        const currentRoadEdgeZ = getLaneAnimationCurrentRoadEdgeZ();
        const visibleRightBarrier = (onSkyLayer && skyBarriers[1]) ? skyBarriers[1] : rightBarrier;

        visibleRightBarrier.position.z = currentRoadEdgeZ + ROAD_EDGE_BARRIER_OFFSET;
        visibleRightBarrier.position.y = laneAnimFloorY; 
        
        if (newLaneSegment) {
            const skyLaneEdgeOverlap = newLaneSegment.userData.skyLaneEdgeOverlap || 0;
            const visibleLaneWidth = (currentRoadEdgeZ - laneAnimStartLimitZMax) + skyLaneEdgeOverlap;
            const baseLaneWidth = LANE_WIDTH + skyLaneEdgeOverlap;
            newLaneSegment.scale.y = Math.max(0.001, visibleLaneWidth / baseLaneWidth);
            newLaneSegment.position.z = laneAnimStartLimitZMax + (visibleLaneWidth * 0.5);
            newLaneSegment.position.y = laneAnimFloorY + 0.008;
        }

        if (onSkyLayer && skyFloor) {
            syncSkyFloorForLaneAnimation(currentRoadEdgeZ);
        }
        
        animatingLines.forEach(line => {
            if (line.material) {
                line.material.opacity = t; 
            }
        });
        
        if (laneAnimProgress >= 1.0) {
            isAnimatingLane = false; 
            rebuildLaneState(laneExpansionCount + 1);
            
            scene.remove(ground); 
            if (newLaneSegment) disposeNode(newLaneSegment);
            newLaneSegment = null;
            
            animatingLines.forEach(line => disposeNode(line)); 
            animatingLines = []; 
            
            rebuildMainRoadMesh();
            createLanesDecor();
            leftBarrier.position.z = getBarrierPositionZ(-1);
            rightBarrier.position.z = getBarrierPositionZ(1);
            realignNatureDecorToRoad();
            realignLavaDecorToRoad();
            windFans.forEach(retuneWindFan);
            obstacles.forEach((o) => {
                if (o && o.userData && o.userData.type === 'sky_sweeper') retuneSkySweeperObstacle(o);
            });
            if (onSkyLayer) {
                createSkyFloor();
                if (skyFloor && skyFloor.material) {
                    skyFloor.material.opacity = 1;
                    skyFloor.material.transparent = false;
                    skyFloor.visible = true;
                }
            }
            
            earthquakeIntensity = 0.3; 
            requestShadowMapRefresh();
        }
    }

function cancelLaneAnimationForLavaDrop() {
    if (!isAnimatingLane) return;
    isAnimatingLane = false;
    laneAnimProgress = 0;
    earthquakeIntensity = 0;
    if (newLaneSegment) {
        disposeNode(newLaneSegment);
        newLaneSegment = null;
    }
    animatingLines.forEach(line => disposeNode(line));
    animatingLines = [];
    if (rightBarrier) {
        rightBarrier.position.z = getBarrierPositionZ(1);
        rightBarrier.position.y = 0;
        rightBarrier.scale.x = 1;
    }
    if (skyBarriers[1]) {
        skyBarriers[1].position.z = getBarrierPositionZ(1);
        skyBarriers[1].position.y = SKY_LAYER_Y;
        skyBarriers[1].scale.x = 1;
    }
}

    function createPlayer() {
        const geometry = new THREE.BoxGeometry(PLAYER_WIDTH, normalHeight, PLAYER_DEPTH);
        const material = new THREE.MeshPhongMaterial({ color: 0x00ff88, wireframe: true, visible: false });
        player = new THREE.Mesh(geometry, material); player.position.set(startPosX, normalHeight/2, 0); scene.add(player);
    }

    function setTrafficLightVisualAlpha(group, alpha) {
        if (!group) return;
        // Do not toggle the pole/arm/bulb materials to transparent every frame.
        // Besides forcing shader recompiles, that moved the entire traffic light
        // into Three's transparent sort and made the structure flicker or vanish
        // behind buildings. Only its already-transparent beam/glow particles fade.
        const effects = group.userData?.trafficEffectMaterials || [];
        effects.forEach((mat) => {
            if (!mat) return;
            const baseOpacity = typeof mat.userData.trafficBaseOpacity === 'number'
                ? mat.userData.trafficBaseOpacity
                : (typeof mat.opacity === 'number' ? mat.opacity : 1.0);
            mat.userData.trafficBaseOpacity = baseOpacity;
            mat.opacity = baseOpacity * alpha;
        });
        group.visible = alpha > 0.02;
        if (group.userData) group.userData.visualAlpha = alpha;
    }

    function updateTrafficLightVisibility(group) {
        if (!group || !group.userData) return;
        const distAhead = group.position.x - player.position.x;
        const visibleDistance = group.userData.trafficVisibleDistance || 280;
        const fadeDistance = Math.max(20, group.userData.trafficFadeDistance || 80);
        let alpha = 0;
        if (distAhead > -70 && distAhead < visibleDistance) {
            alpha = distAhead <= visibleDistance - fadeDistance
                ? 1
                : 1 - ((distAhead - (visibleDistance - fadeDistance)) / fadeDistance);
        }
        alpha = Math.max(0, Math.min(1, alpha));
        if (Math.abs((group.userData.visualAlpha ?? -1) - alpha) > 0.015) {
            setTrafficLightVisualAlpha(group, alpha);
        }
    }

    function getNearestTrafficLaneZ(rawTriggerZ) {
        if (!lanePositions.length) return Number(rawTriggerZ) || 0;
        let bestZ = lanePositions[0];
        let bestDistance = Math.abs(bestZ - rawTriggerZ);
        for (let index = 1; index < lanePositions.length; index++) {
            const distance = Math.abs(lanePositions[index] - rawTriggerZ);
            if (distance < bestDistance) {
                bestDistance = distance;
                bestZ = lanePositions[index];
            }
        }
        return bestZ;
    }

    function didPlayerCrossTrafficLight(group) {
        if (!group?.userData || !player) return false;
        // Relative distance survives floating-origin rebases. Retaining the
        // previous sample also prevents a low-FPS frame from skipping the
        // signal's short longitudinal trigger volume.
        const relativeX = group.position.x - player.position.x;
        const previousRelativeX = Number.isFinite(group.userData.previousRelativeX)
            ? group.userData.previousRelativeX
            : relativeX;
        group.userData.previousRelativeX = relativeX;
        const crossedX = previousRelativeX >= relativeX
            && Math.min(previousRelativeX, relativeX) <= 5.5
            && Math.max(previousRelativeX, relativeX) >= -5.5;
        const triggerLaneZ = Number.isFinite(group.userData.triggerLaneZ)
            ? group.userData.triggerLaneZ
            : group.userData.triggerZ;
        const triggerHalfWidth = Number(group.userData.triggerHalfWidth) || (LANE_WIDTH * 0.48);
        const crossedLane = Math.abs(player.position.z - triggerLaneZ) <= triggerHalfWidth + PLAYER_DEPTH * 0.25;
        return crossedX && crossedLane;
    }

    // PERF (2026-07-07 hitch fix): trafik ışığı ESKİDEN her spawn'ında 7 geometri + 1 CanvasTexture
    // (GPU upload!) yaratıyordu → FPS-drop. GEOMETRİLER + 2 beam texture (yeşil/kırmızı) + glow
    // texture cache'lenir (`__pooled` → dispose'dan korunur). MATERYALLER per-instance kalır (ucuz,
    // GPU-upload yok) çünkü mesafe-fade (setTrafficLightVisualAlpha) materyal opacity'sini ışık
    // başına değiştiriyor — paylaşımlı olsalardı bir ışık fade olunca HEPSİ kaybolurdu (bug fix).
    const _tl = { ready: false };
    function ensureTrafficLightCache() {
        if (_tl.ready) return;
        const poleHeight = 22, armLength = 5.5, beamHeight = 12;
        _tl.poleHeight = poleHeight; _tl.armLength = armLength; _tl.beamHeight = beamHeight;
        _tl.geoPole = new THREE.CylinderGeometry(0.38, 0.5, poleHeight, 8);
        _tl.geoBase = new THREE.CylinderGeometry(0.75, 0.95, 1.0, 8);
        _tl.geoArm = new THREE.BoxGeometry(0.55, 0.55, armLength);
        _tl.geoBox = new THREE.BoxGeometry(1.6, 4.0, 1.5);
        _tl.geoBulb = new THREE.SphereGeometry(0.82, 16, 16);
        _tl.geoBeam = new THREE.CylinderGeometry(0.4, 2.2, beamHeight, 20, 1, true); _tl.geoBeam.translate(0, -beamHeight / 2, 0);
        _tl.geoGlow = new THREE.PlaneGeometry(6, 6);
        const makeBeamTex = (rgba) => { const cv = document.createElement('canvas'); cv.width = 32; cv.height = 128; const c = cv.getContext('2d'); const g = c.createLinearGradient(0, 0, 0, 128); g.addColorStop(0, rgba); g.addColorStop(1, 'rgba(0,0,0,0)'); c.fillStyle = g; c.fillRect(0, 0, 32, 128); const t = new THREE.CanvasTexture(cv); t.colorSpace = THREE.SRGBColorSpace; t.__pooled = true; return t; };
        _tl.beamTexGreen = makeBeamTex('rgba(0,255,0,0.4)');
        _tl.beamTexRed = makeBeamTex('rgba(255,0,0,0.4)');
        if (glowTexture) glowTexture.__pooled = true; // per-instance glow-mat referans eder, dispose'dan koru
        spawnPoolGeoms.push(_tl.geoPole, _tl.geoBase, _tl.geoArm, _tl.geoBox, _tl.geoBulb, _tl.geoBeam, _tl.geoGlow);
        _tl.ready = true;
    }

    function createTrafficLight(x, z, onWall = false, wallSide = 'right') {
        ensureTrafficLightCache();
        const trafficGroup = new THREE.Group();
        const poleHeight = _tl.poleHeight, armLength = _tl.armLength, beamHeight = _tl.beamHeight;

        // Materyaller PER-INSTANCE (mesafe-fade her ışığa özel çalışsın). Ucuz — yeni geo/texture yok.
        const metalMat = new THREE.MeshStandardMaterial({ color: 0x5c7085, emissive: 0x071522, roughness: 0.32, metalness: 0.78 });
        const boxMat = new THREE.MeshStandardMaterial({ color: 0x111927, emissive: 0x060b12, roughness: 0.38, metalness: 0.55 });

        const pole = new THREE.Mesh(_tl.geoPole, metalMat);
        pole.position.y = poleHeight / 2;
        trafficGroup.add(pole);

        const base = new THREE.Mesh(_tl.geoBase, metalMat);
        base.position.y = 0.5;
        trafficGroup.add(base);

        // Işık yola dönsün: sağdaysa sola, soldaysa sağa bak
        let lookDir = 1;
        if (z > 0.1) lookDir = -1; else if (z < -0.1) lookDir = 1; else lookDir = Math.random() > 0.5 ? 1 : -1;

        const arm = new THREE.Mesh(_tl.geoArm, metalMat);
        arm.position.set(0, poleHeight - 1, (armLength / 2 - 0.2) * lookDir);
        trafficGroup.add(arm);

        const box = new THREE.Mesh(_tl.geoBox, boxMat);
        box.position.set(0, poleHeight - 3, (armLength - 0.8) * lookDir);
        trafficGroup.add(box);

        const isGreen = Math.random() > 0.5;
        const lightColor = isGreen ? 0x00ff00 : 0xff0000;
        const beamTex = isGreen ? _tl.beamTexGreen : _tl.beamTexRed;

        const bulb = new THREE.Mesh(_tl.geoBulb, new THREE.MeshBasicMaterial({ color: lightColor }));
        bulb.position.copy(box.position);
        bulb.position.y -= 0.5;
        // Put the signal on the road-facing surface instead of leaving most of
        // the sphere embedded inside the dark housing.
        bulb.position.z += 0.82 * lookDir;
        trafficGroup.add(bulb);

        // A small billboard halo keeps the actual signal readable on Performance
        // graphics without adding a light source or shadow pass.
        const bulbHaloMat = new THREE.SpriteMaterial({
            map: glowTexture,
            color: lightColor,
            transparent: true,
            opacity: 0.58,
            blending: THREE.AdditiveBlending,
            depthWrite: false,
            depthTest: true,
            fog: true
        });
        const bulbHalo = new THREE.Sprite(bulbHaloMat);
        bulbHalo.position.copy(bulb.position);
        bulbHalo.scale.set(4.8, 4.8, 1);
        bulbHalo.renderOrder = 6;
        trafficGroup.add(bulbHalo);

        const beamMat = new THREE.MeshBasicMaterial({ map: beamTex, color: lightColor, transparent: true, opacity: 0.22, side: THREE.DoubleSide, blending: THREE.AdditiveBlending, depthWrite: false, fog: true });
        const beam = new THREE.Mesh(_tl.geoBeam, beamMat);
        beam.position.copy(bulb.position);
        beam.frustumCulled = false;
        // Keep the guidance cone inside normal transparent sorting. The previous
        // renderOrder=2000 forced a close red beam over every building and made it
        // look like a giant solid wall across the road.
        beam.renderOrder = 4;
        trafficGroup.add(beam);

        const particleCount = isMobilePerformanceGraphics() ? 8 : 20;
        const pGeo = new THREE.BufferGeometry();
        const pPos = new Float32Array(particleCount * 3);
        const pVels = [];
        for (let i = 0; i < particleCount; i++) {
            const r = Math.random() * 1.5, theta = Math.random() * Math.PI * 2;
            pPos[i * 3] = r * Math.cos(theta); pPos[i * 3 + 1] = Math.random() * beamHeight; pPos[i * 3 + 2] = r * Math.sin(theta);
            pVels.push((Math.random() - 0.5) * 0.02, 0.05 + Math.random() * 0.1, (Math.random() - 0.5) * 0.02);
        }
        pGeo.setAttribute('position', new THREE.BufferAttribute(pPos, 3));
        const particleMat = new THREE.PointsMaterial({ color: lightColor, size: 0.38, transparent: true, opacity: 0.78, blending: THREE.AdditiveBlending, depthWrite: false, fog: true });
        const particles = new THREE.Points(pGeo, particleMat);
        particles.position.copy(bulb.position);
        particles.position.y -= beamHeight;
        particles.renderOrder = 5;
        trafficGroup.add(particles);

        const glowMat = new THREE.MeshBasicMaterial({ map: glowTexture, color: lightColor, transparent: true, opacity: 0.34, blending: THREE.AdditiveBlending, depthWrite: false, fog: true });
        const groundGlow = new THREE.Mesh(_tl.geoGlow, glowMat);
        groundGlow.rotation.x = -Math.PI / 2;
        groundGlow.position.set(bulb.position.x, 0.1, bulb.position.z);
        groundGlow.renderOrder = 3;
        trafficGroup.add(groundGlow);

        // YENÄ° EKLENDÄ°: Zemin yÃ¼ksekliÄŸini (Sky Layer) kontrol et
        const floorY = onSkyLayer ? SKY_LAYER_Y : 0;
        
        // DÃœZELTME: 0 yerine floorY deÄŸiÅŸkeni atandÄ±
        trafficGroup.position.set(x, floorY, z);
        trafficGroup.traverse((obj) => { obj.frustumCulled = false; });

        const rawTriggerZ = bulb.position.z + z;
        trafficGroup.userData = { 
            type: 'traffic_light', 
            lightType: isGreen ? 'green' : 'red', 
            active: true, 
            triggerZ: rawTriggerZ,
            triggerLaneZ: getNearestTrafficLaneZ(rawTriggerZ),
            triggerHalfWidth: LANE_WIDTH * 0.48,
            previousRelativeX: null,
            widthZ: 4.5,
            lavaVisibilityLimit: gamePhase >= 3,
            lavaVisibleDistance: 260,
            trafficVisibleDistance: gamePhase >= 4 ? 210 : (gamePhase >= 3 ? 240 : 320),
            trafficFadeDistance: gamePhase >= 4 ? 85 : 95,
            visualAlpha: 0,
            trafficEffectMaterials: [bulbHaloMat, beamMat, particleMat, glowMat],
            trafficVisuals: { bulb, bulbHalo, beam, particles, groundGlow },
            smoke: { 
                mesh: particles, 
                velocities: pVels, 
                height: beamHeight, 
                zOffset: 0 
            }
        };
        setTrafficLightVisualAlpha(trafficGroup, 0);
        
        scene.add(trafficGroup);
        obstacles.push(trafficGroup);
        requestShadowMapRefresh(x);
    }

    function createObstacle(type, spawnX, startLaneIdx, spawnOptions = {}) {
        // A single hard gate protects every campaign spawn path (authored rows,
        // companion traffic and legacy/random fallbacks). This prevents a new
        // caller from accidentally reintroducing motorcycles during Levels 1-5.
        if (type === 'motorcycle' && !spawnOptions.tutorial && !areMotorcyclesAllowedForCurrentRun()) {
            type = 'car';
        }
        if (type === 'lava_lane' && gamePhase >= 5) return;

        let obs; 
        let vehicleZWidth = 5.2; 
        let currentHasBarrier = false; 
        let difficulty = Math.min(2.5, 1.0 + score * 0.00015); 
        
        // ZEMÄ°N YÃœKSEKLÄ°K AYARI
        const floorY = onSkyLayer ? SKY_LAYER_Y : 0;

        if (type === 'wall' || type === 'low_wall') {
            const lane = lanePositions[startLaneIdx]; 
            const h = type === 'wall' ? 18 : 3.5;
            const wallWidth = 6.8; 
            if (!spawnOptions.tutorial) {
                spawnX = resolveStaticRoadSpawnX(type, spawnX, lane, 5.0, wallWidth);
            }

            if (type === 'wall') {
                obs = acquirePooledObstacle('wall', createDetailedWall);
            } else {
                obs = acquirePooledObstacle('low_wall', createDetailedLowWall);
            }

            obs.position.set(spawnX, floorY, lane);

            obs.userData = {
                ...obs.userData, // 'wall' fabrikası warningLights/pulseSeed kurar, ezilmesin (falling_wall'daki aynı tuzak)
                speedX: 0,
                length: 5.0,
                height: h,
                type: type,
                widthZ: wallWidth
            };
            scene.add(obs); 
            obstacles.push(obs);
        }
        else if (type === 'falling_wall') {
            const lane = lanePositions[startLaneIdx]; 
            const wallWidth = 6.8; 
            const h = 20;
            if (!spawnOptions.tutorial) {
                spawnX = resolveStaticRoadSpawnX(type, spawnX, lane, 6.0, wallWidth);
            }
            
            obs = acquirePooledObstacle('falling_wall', createDetailedFallingWall);
            obs.position.set(spawnX, floorY + 35, lane);
            obs.rotation.z = 0; // pool reuse: düşüş salınımından kalan tilt temizlensin

            const authoredLevelDrop = currentRunMode === 'level' && !!levelPatternSpawnContext?.forceExact;
            obs.userData = {
                ...obs.userData, // warningLights/pulseSeed factory'de kuruldu, ezilmesin (tren userData'sıyla aynı tuzak)
                speedX: 0,
                length: 6.0,
                height: h,
                type: 'falling_wall',
                widthZ: wallWidth,
                targetY: floorY,
                // Endless keeps its close immediate drop. A deterministic level
                // row may be hundreds of units ahead, so hold it in the sky
                // until the player reaches its visible warning corridor.
                fallSpeed: 3.5,
                dropArmed: !authoredLevelDrop,
                dropTriggerDistance: authoredLevelDrop ? 54 : Number.POSITIVE_INFINITY,
                // Authored level rows wait outside the camera corridor, but as
                // soon as they arm they use the same visible airborne body and
                // Y descent as Endless. Hiding it for the entire fall caused
                // the wall to pop into existence only on the landing frame.
                revealBodyOnArm: authoredLevelDrop,
                hideAirborneBody: false,
                fwLanded: false // pool reuse: spread önceki koşunun true değerini taşır, landing FX bir daha çalmazdı
            };
            // The wall starts high above the camera and descends within a few
            // frames. Casting from that airborne box projected a large detached
            // rectangle onto the road. Its real shadow begins at touchdown.
            if (obs.userData.shadowCaster) obs.userData.shadowCaster.castShadow = false;
            if (obs.userData.dropMarker) obs.userData.dropMarker.visible = false;
            setFallingWallBodyVisible(obs, !authoredLevelDrop);
            scene.add(obs); 
            obstacles.push(obs);
        }
        else if (type === 'high_beam') {
            const totalLanes = lanePositions.length; 
            const spanCount = Math.floor(Math.random() * Math.min(3, totalLanes - 1)) + 1;
            const maxStartIndex = totalLanes - spanCount; 
            const startIdx = Math.floor(Math.random() * (maxStartIndex + 1));
            const startZ = lanePositions[startIdx]; 
            const endZ = lanePositions[startIdx + spanCount - 1];
            
            const beamPos = (startZ + endZ) / 2;
            const beamWidth = (spanCount * 7.0) - 0.5;
            // h/yPos kept in sync with the spawnManager high_beam branch (hand-tuned clearance: floor+9.2)
            const h = 10.0;
            const yPos = floorY + 14.2;

            obs = createDetailedHighBeam(beamWidth, h);
            obs.position.set(spawnX, yPos, beamPos);
            
            obs.userData = { speedX: 0, length: 2.5, height: h, type: 'high_beam', widthZ: beamWidth }; 
            obs.castShadow = true; 
            obs.receiveShadow = true; 
            scene.add(obs); 
            obstacles.push(obs);
        } 
        else if (type === 'slide_barrier') {
            const lane = lanePositions[startLaneIdx]; 
            const barrierHeight = 6.9; 
            const yPos = floorY + 5.5; 
            const barrierWidth = 6.8;
            if (!spawnOptions.tutorial) {
                spawnX = resolveStaticRoadSpawnX(type, spawnX, lane, 2.0, barrierWidth);
            }
            
            obs = acquirePooledObstacle('slide_barrier', createDetailedSlideBarrier); 
            obs.position.set(spawnX, yPos, lane);
            
            obs.userData = { speedX: 0, length: 2.0, height: barrierHeight, type: 'slide_barrier', widthZ: barrierWidth }; 
            obs.castShadow = true; 
            obs.receiveShadow = true; 
            scene.add(obs); 
            obstacles.push(obs); 
            currentHasBarrier = true;
        }
        else if (type === 'trap') {
            const lane = lanePositions[startLaneIdx];
            if (!spawnOptions.tutorial) {
                spawnX = resolveStaticRoadSpawnX(type, spawnX, lane, 2.0, 6.0);
            }
            const trapGroup = new THREE.Group();
            
            const pillarGeo = new THREE.BoxGeometry(1.5, 14, 1.5);
            const leftPillar = new THREE.Mesh(pillarGeo, mats.ruin);
            leftPillar.position.set(-2.5, 7, 0); leftPillar.castShadow = true; trapGroup.add(leftPillar);
            
            const rightPillar = new THREE.Mesh(pillarGeo, mats.ruin);
            rightPillar.position.set(2.5, 7, 0); rightPillar.castShadow = true; trapGroup.add(rightPillar);
            
            const topGeo = new THREE.BoxGeometry(8, 2, 2);
            const topBeam = new THREE.Mesh(topGeo, mats.ruin);
            topBeam.position.set(0, 13, 0); trapGroup.add(topBeam);
            
            const bladeGeo = new THREE.ConeGeometry(1.2, 4, 4); 
            const blade = new THREE.Mesh(bladeGeo, mats.fallingWall);
            blade.rotation.z = Math.PI; blade.position.set(0, 9, 0); trapGroup.add(blade);

            trapGroup.position.set(spawnX, floorY, lane);
            
            trapGroup.userData = { speedX: 0, length: 2.0, height: 14.0, type: 'trap', widthZ: 6.0, bladeHeight: floorY + 9.0 };
            scene.add(trapGroup); obstacles.push(trapGroup);
        }
        else if (type === 'rising_rock') { 
            const lane = lanePositions[startLaneIdx];
            if (!spawnOptions.tutorial) {
                spawnX = resolveStaticRoadSpawnX(type, spawnX, lane, 6.0, 5.0);
            }
            obs = createRisingRock();
            obs.position.set(spawnX, floorY - 15, lane);
            
            obs.userData = { 
                speedX: 0, length: 6.0, height: 7.0, type: 'rising_rock', widthZ: 5.0, targetY: floorY + 3.5, riseSpeed: 0.4 
            };
            scene.add(obs); obstacles.push(obs);
        }
        else if (type === 'sky_sweeper') {
            obs = createSkySweeperObstacle();
            obs.position.set(spawnX, floorY, getRoadCenterZ());
            scene.add(obs);
            obstacles.push(obs);
            currentHasBarrier = true;
        }
        else if (type === 'energy_plasma') {
            obs = acquirePooledObstacle('energy_plasma', createEnergyPlasmaObstacle);
            setEnergyPlasmaTheme(obs, gamePhase >= 5 ? 'snow' : (gamePhase >= 4 ? 'water' : 'lava'));
            const plasmaRadius = obs.userData.radius || 2.2;
            const minZ = roadLimitZMin + plasmaRadius + 0.9;
            const maxZ = roadLimitZMax - plasmaRadius - 0.9;
            const direction = Math.random() > 0.5 ? 1 : -1;
            const startZ = direction > 0 ? minZ : maxZ;
            obs.position.set(spawnX, floorY + (obs.userData.height || 5.2) * 0.5 + 1.8, startZ);
            obs.userData.speedZ = 30.0 + Math.random() * 8.0;
            obs.userData.direction = direction;
            obs.userData.pulseSeed = Math.random() * Math.PI * 2;
            if (obs.userData.coreMesh) obs.userData.coreMesh.scale.setScalar(obs.userData.baseScale || 1.0);
            if (obs.userData.shellMesh) obs.userData.shellMesh.scale.setScalar(obs.userData.shellBaseScale || 1.36);
            scene.add(obs);
            obstacles.push(obs);
        }
        else if (type === 'lava_lane') {
            const lane = lanePositions[startLaneIdx];
            obs = createLavaLaneHazard();
            obs.position.set(spawnX, floorY, lane);
            scene.add(obs);
            obstacles.push(obs);
        }
        else if (type === 'snow_ice_road') {
            obs = createSnowIceRoadHazard();
            obs.position.set(spawnX, floorY, getRoadCenterZ());
            scene.add(obs);
            obstacles.push(obs);
        }
        else if (type === 'snow_falling_ball') {
            obs = createSnowFallingBallObstacle();
            obs.position.set(spawnX, floorY, getSnowballTargetZ(startLaneIdx));
            scene.add(obs);
            obstacles.push(obs);
            currentHasBarrier = true;
        }
        else if (type === 'static_train' || type === 'stopped_train' || type === 'train') {
            if (shouldRequireDetailedTrainModel() && !trainGlbReady && !canUseStreamingVehicleFallback('train')) {
                startVehicleModelLoads();
                vehicleSpawnDeferredCounts.train++;
                // Never create the legacy box train in a detailed tier. Slow or
                // failed requests postpone this spawn while background retries
                // continue; gameplay remains live with the other obstacle types.
                return null;
            }
            let lane = lanePositions[startLaneIdx]; const isRamp = type === 'static_train'; const isMoving = type === 'train';
            const wagonCount = Math.floor(Math.random() * 4) + 3; const segmentLength = 16; const gap = 0.8;
            const trainColorMat = mats.vehicles[Math.floor(Math.random() * mats.vehicles.length)]; // one paint per train
            const totalTrainLength = (wagonCount * segmentLength) + ((wagonCount - 1) * gap);
            const vHeight = trainGlbReady ? trainGlbRoofTop : 6.5; const width = trainGlbReady ? TRAIN_WIDTH : 6.2;
            const resolvedPlacement = resolveTrafficSpawnPlacement(type, spawnX, startLaneIdx, totalTrainLength + (isRamp ? 22 : 0), width, lane);
            if (!resolvedPlacement) return null;
            spawnX = resolvedPlacement.x;
            lane = resolvedPlacement.lane;
            startLaneIdx = resolvedPlacement.laneIdx;
            const trainGroup = new THREE.Group(); trainGroup.position.set(spawnX, floorY, lane); 
            const startOffset = -totalTrainLength / 2;
            const useGlbTrainBatch = addGlbTrainVisualBatch(trainGroup, wagonCount, startOffset, segmentLength + gap, trainColorMat);
            let barrierAddedToTrain = false;
            
            if (Math.random() < 0.02) {
                const shield = createShieldMesh(); shield.position.set((Math.random() - 0.5) * totalTrainLength * 0.8, vHeight + 3.5, 0); trainGroup.add(shield);
                trainGroup.userData.attachedShield = shield; // per-frame getObjectByName yerine O(1) referans
            }
            
            for(let i=0; i<wagonCount; i++) {
                const localX = startOffset + (i * (segmentLength + gap)) + (segmentLength/2);
                const isLoco = (i === 0); const isLast = (i === wagonCount - 1);
                
                let wagon;
                if (useGlbTrainBatch) {
                    wagon = new THREE.Group();
                    if (isLoco && isMoving) addTrainLocoLight(wagon);
                } else {
                    wagon = createTrainWagonModel(isLoco && isMoving, null, trainColorMat, isLast, isMoving);
                }
                wagon.position.set(localX, 0, 0);
                
                if (isRamp && isLoco) {
                    // train-sized loco (flat roof) + a gray climb ramp in front that reaches the
                    // roof (vHeight) and spans the full train width
                    const rampShape = new THREE.Shape();
                    rampShape.moveTo(0, 1.0); rampShape.lineTo(0, vHeight); rampShape.lineTo(-22, 0); rampShape.lineTo(0, 0);
                    const rampGeo = new THREE.ExtrudeGeometry(rampShape, { depth: width, bevelEnabled: false });
                    const rampMat = mats.trainStatic.clone();
                    rampMat.transparent = false;
                    rampMat.opacity = 1.0;
                    rampMat.depthWrite = true;
                    const ramp = new THREE.Mesh(rampGeo, rampMat); ramp.position.set(-segmentLength / 2, 0, -width / 2);
                    wagon.add(ramp); trainGroup.add(wagon);
                } else {
                    wagon.position.set(localX, 0, 0); trainGroup.add(wagon);
                }

                // A static train's front ramp is a readable route onto the roof.
                // Spawning an overhead barrier on its first roof segment killed a
                // player about one second after a successful walk-up and looked
                // exactly like a ramp collision. Keep ramp trains as safe traversal
                // routes; moving/stopped trains can still carry roof barriers.
                const canSpawnBarrier = !isRamp && !lastObstacleHadBarrier && lastObstacleType !== 'slide_barrier' && !barrierAddedToTrain;
                if (!isLoco && canSpawnBarrier && Math.random() < 0.3) { 
                    const barrierHeight = 6.9; const barrierWidth = 6.8;
                    const barrier = createDetailedSlideBarrier();
                    barrier.position.set(localX, vHeight + 6.5, 0); 
                    barrier.name = 'train_barrier';
                    barrier.userData = { height: barrierHeight, widthZ: barrierWidth, length: 2.0, collisionDrop: 0.75, requiresSlideOrJump: true }; 
                    trainGroup.add(barrier);
                    currentHasBarrier = true; barrierAddedToTrain = true;
                } else if (!isLoco && !isLast && Math.random() < 0.3) {
                    for(let k=0; k<4; k++) { const offset = (k * 8) - 12; createCoin(localX + offset, 0, trainGroup, vHeight + 4.5); }
                }
                
                if (isLast && !isMoving) {
                     const lightGeo = new THREE.BoxGeometry(0.4, 0.8, 4.0); const lightMat = new THREE.MeshBasicMaterial({ color: 0xff0000 });
                     const tailLight = new THREE.Mesh(lightGeo, lightMat); tailLight.position.set(segmentLength/2 + 0.1, 3, 0); tailLight.name = 'light_mesh'; wagon.add(tailLight);
                }
            }
            trainGroup.userData = {
                ...trainGroup.userData,
                type,
                length: totalTrainLength + (isRamp ? 22 : 0),
                bodyLength: totalTrainLength,
                collisionCenterOffsetX: isRamp ? -11 : 0,
                widthZ: width,
                height: vHeight,
                speedX: 0,
                originalSpeed: 0,
                rampLength: isRamp ? 22 : 0,
                lane,
                targetLane: lane,
                laneChanging: false,
                lastLaneChangeTime: 0,
                previousTrafficX: spawnX,
                lightsActive: true
            };
            if (isMoving) {
                const levelTrafficScale = Math.max(0.5, Math.min(1.45, Number(getActiveLevelTuning()?.trafficSpeedScale) || 1));
                const readableDifficulty = 1 + Math.max(0, difficulty - 1) * 0.34;
                let trainBase = 0.3 + (Math.random() * 0.5);
                let baseSpeed = clampReadableTrafficSpeed('train', -(trainBase * readableDifficulty * levelTrafficScale));
                trainGroup.userData.speedX = baseSpeed; trainGroup.userData.originalSpeed = baseSpeed;
            }
            obs = trainGroup;
            scene.add(trainGroup); obstacles.push(trainGroup);
            vehicleSpawnSuccessCounts.train++;
        }
        else {
            const isMotor = type === 'motorcycle';
            if (!spawnOptions.forceProcedural && shouldRequireDetailedAuxVehicleModels()
                && ((isMotor && !motorGlbReady && !canUseStreamingVehicleFallback('motorcycle'))
                    || (!isMotor && !carGlbReady && !canUseStreamingVehicleFallback('car')))) {
                startVehicleModelLoads();
                vehicleSpawnDeferredCounts[isMotor ? 'motorcycle' : 'car']++;
                // Never expose the old box-built car or motorcycle while a
                // detailed tier is active. A slow first request postpones this
                // traffic spawn; other obstacles continue normally.
                return null;
            }
            
            let lane;
            if (isMotor) {
                const minZ = roadLimitZMin + 2.0; 
                const maxZ = roadLimitZMax - 2.0; 
                lane = minZ + Math.random() * (maxZ - minZ);
            } else {
                lane = lanePositions[startLaneIdx] || 0;
            }
             
            let vHeight = 3.5; let vLength = 10;
            let vehicleZWidth = 5.2; 
            if (isMotor) {
                vHeight = 3.4; vLength = 7.0; vehicleZWidth = 2.2; // bigger GLB motorcycle
            }
             
            // FTUE rows are authored at exact distances. The regular traffic
            // resolver enforces a 520-unit spawn safety distance and used to
            // push the first tutorial cars behind the later slide row. Bypass
            // all lane randomization/clearance offsets only for tutorial cars.
            const resolvedPlacement = spawnOptions.tutorial
                ? { x: spawnX, lane: lanePositions[startLaneIdx] || 0, laneIdx: startLaneIdx }
                : resolveTrafficSpawnPlacement(isMotor ? 'motorcycle' : 'vehicle', spawnX, startLaneIdx, vLength, vehicleZWidth, lane);
            if (!resolvedPlacement) return null;
            spawnX = resolvedPlacement.x;
            lane = resolvedPlacement.lane;
            startLaneIdx = resolvedPlacement.laneIdx;

            if (spawnOptions.instance) {
                obs = spawnOptions.instance;
                obs.visible = true;
            } else if (isMotor) { 
                obs = createBikeModel();
            } else { 
                obs = createCarModel(mats.vehicles[Math.floor(Math.random() * mats.vehicles.length)]);
            }
            
            obs.position.set(spawnX, floorY, lane); 
            
            let carBase = 0.4 + (Math.random() * 0.7);
            let motorBase = MOTORCYCLE_SPEED_MIN + (Math.random() * MOTORCYCLE_SPEED_RANGE);
            // Browser-only opening balance: traffic starts markedly calmer and
            // smoothly reaches the original speed by score 1200. Tutorial traffic
            // has its own deterministic speed and is intentionally unaffected.
            const openingProgress = isBrowserBuild() ? Math.max(0, Math.min(1, score / 1200)) : 1;
            const openingTrafficScale = isBrowserBuild()
                ? ((isMotor ? 0.52 : 0.55) + (isMotor ? 0.48 : 0.45) * openingProgress)
                : 1;
            const levelTrafficScale = Math.max(0.5, Math.min(1.45, Number(getActiveLevelTuning()?.trafficSpeedScale) || 1));
            // Difficulty may increase density and player speed, but multiplying
            // oncoming traffic by the full difficulty value removes the player's
            // reaction window at high score. Keep the authored vehicle hierarchy
            // while compressing only its traffic-speed contribution.
            const readableDifficulty = 1 + Math.max(0, difficulty - 1) * 0.34;
            let baseSpeed = Number.isFinite(spawnOptions.speedX)
                ? Number(spawnOptions.speedX)
                : -((isMotor ? motorBase : carBase) * readableDifficulty * openingTrafficScale * levelTrafficScale);
            if (!spawnOptions.tutorial) baseSpeed = clampReadableTrafficSpeed(isMotor ? 'motorcycle' : 'vehicle', baseSpeed);
            
            obs.userData = {
                ...obs.userData,
                speedX: baseSpeed, 
                originalSpeed: baseSpeed, 
                browserOpeningSpeedScale: openingTrafficScale,
                levelTrafficSpeedScale: levelTrafficScale,
                length: vLength, 
                height: vHeight, 
                type: spawnOptions.tutorial ? 'tutorial_vehicle' : (isMotor ? 'motorcycle' : 'vehicle'), 
                lane: lane, 
                targetLane: lane, 
                laneChanging: false, 
                widthZ: vehicleZWidth, 
                lastLaneChangeTime: 0, 
                previousTrafficX: spawnX,
                lightsActive: spawnOptions.lightsActive !== false
            };

            if (spawnOptions.lightsActive === false) {
                obs.traverse((child) => {
                    if (!child.isObject3D) return;
                    if (child.name === 'light_mesh' || child.name === 'light_beam') child.visible = false;
                });
            }
            
            obs.castShadow = true; 
            obs.receiveShadow = true; 
            scene.add(obs); 
            obstacles.push(obs);
            if (!spawnOptions.tutorial) vehicleSpawnSuccessCounts[isMotor ? 'motorcycle' : 'car']++;
        }
        
        if (obs && spawnOptions.tutorial) tagTutorialObstacle(obs, spawnOptions.lesson || 'jump');
        if (obs && ['vehicle', 'motorcycle', 'tutorial_vehicle', 'train', 'stopped_train', 'static_train'].includes(obs.userData?.type)) {
            // Cars/bikes preserve their rigid silhouette. Long train bodies and
            // their ramps remain smooth so their length follows the same visual
            // lane-normal equation as the road. Physics stays straight inside
            // the protected near collision corridor in both cases.
            const curveMode = ['train', 'stopped_train', 'static_train'].includes(obs.userData.type)
                ? 'smooth'
                : 'rigid';
            curvedPathSystem?.installGpuCurvedObject?.(obs, true, { mode: curveMode });
        } else if (obs && ['wall', 'low_wall', 'falling_wall', 'slide_barrier', 'high_beam', 'rising_rock'].includes(obs.userData?.type)) {
            // Long barriers must share the road's per-vertex bend. This remains
            // visual-only: obstacle roots and swept collision records stay in
            // the original straight CPU coordinate system.
            const curveMode = curvedPathSystem?.resolveObstacleCurveMode?.(obs.userData.type, 'rigid') || 'rigid';
            curvedPathSystem?.installGpuCurvedObject?.(obs, true, { mode: curveMode });
        }
        lastObstacleType = type;
        lastObstacleX = spawnX;
        lastObstacleHadBarrier = currentHasBarrier;
        requestShadowMapRefresh(spawnX, !!spawnOptions.tutorial);
        return obs || null;
    }
  
    function createRisingRock() {
        const group = new THREE.Group();
        
        // Çimenli toprak tümseği. Yükseklik ~7 (zıplanabilir). Geometri+materyaller cache'ten paylaşılır.
        // Grup orijini targetY'de; gövde tabanı yerde (local -3.5).
        const body = new THREE.Mesh(geoms.risingRockCore, mats.risingRock);
        body.position.y = -0.4; // taban ~yerde, üst ~+2.7
        body.castShadow = true;
        body.receiveShadow = true;
        group.add(body);

        // Çim kapağı — gövdeden geniş, öne taşar → alçak 1. şahıs açısından bile yeşil görünür
        const cap = new THREE.Mesh(geoms.risingRockCap, mats.risingRockGrass);
        cap.position.y = 2.9;
        cap.castShadow = true;
        group.add(cap);

        // Çim tutamları — kapağın üstünden yukarı çıkan bıçaklar (koyu/açık karışık)
        for (let i = 0; i < 7; i++) {
            const tuft = new THREE.Mesh(geoms.risingRockTuft, (i % 3 === 0) ? mats.risingRockGrassDark : mats.risingRockGrass);
            tuft.position.set((Math.random() - 0.5) * 5.6, 3.35 + Math.random() * 0.35, (Math.random() - 0.5) * 4.6);
            tuft.rotation.set((Math.random() - 0.5) * 0.5, Math.random() * Math.PI, (Math.random() - 0.5) * 0.5);
            tuft.scale.setScalar(0.7 + Math.random() * 0.6);
            group.add(tuft);
        }

        // Tabana yarı-gömülü küçük tan taşlar — en altta yer hizasında, kenara yaslı
        for (let i = 0; i < 3; i++) {
            const ang = Math.random() * Math.PI * 2;
            const stone = new THREE.Mesh(geoms.risingRockStone, mats.risingRockStone);
            stone.position.set(Math.cos(ang) * 3.3, -3.2 + Math.random() * 0.5, Math.sin(ang) * 2.9);
            stone.rotation.set(Math.random(), Math.random(), Math.random());
            stone.scale.setScalar(0.35 + Math.random() * 0.3);
            group.add(stone);
        }

        return group;
    }

    function checkObstacleAhead(currentObstacle, lookAheadDist) {
        let nearest = null; let minDest = lookAheadDist;
        for(let o of obstacles) {
            if (!o || !o.userData || !o.position) continue;
            if (o === currentObstacle) continue; 
            if (isTrafficPhantomHazard(o)) continue;
            
            if (o.userData.type === 'rising_rock' && o.position.y < -1.0) continue;
            if (o.userData.type === 'falling_wall' && o.position.y > 8.0) continue;
            if (o.userData.type === 'gate_part' && o.position.y < -5.0) continue;

            if (trafficZRangesOverlap(getTrafficObjectZRange(o), getTrafficObjectZRange(currentObstacle), 0.5)) {
                const dx = currentObstacle.position.x - o.position.x; 
                if (dx > 0 && dx < minDest) { minDest = dx; nearest = o; }
            }
        }
        return nearest;
    }

    function getTrafficLaneZRange(centerZ, widthZ) {
        const center = Number.isFinite(Number(centerZ)) ? Number(centerZ) : 0;
        const halfWidth = Math.max(0.1, (Number.isFinite(Number(widthZ)) ? Number(widthZ) : 4.0) * 0.5);
        return { min: center - halfWidth, max: center + halfWidth };
    }

    function getTrafficObjectZRange(obstacle) {
        if (!obstacle || !obstacle.userData) return getTrafficLaneZRange(obstacle ? obstacle.position.z : 0, 4.0);
        const centers = [Number(obstacle.position.z) || 0];
        // Motorcycles ride a free z (not a lane) and never update userData.lane, so its stale
        // spawn value would otherwise balloon the z-range across the whole road and make the
        // bike "see" phantom traffic ahead. Use only its live position (+ target while merging).
        if (obstacle.userData.type !== 'motorcycle' && typeof obstacle.userData.lane === 'number') centers.push(obstacle.userData.lane);
        if (obstacle.userData.laneChanging && typeof obstacle.userData.targetLane === 'number') centers.push(obstacle.userData.targetLane);
        const minCenter = Math.min(...centers);
        const maxCenter = Math.max(...centers);
        const halfWidth = Math.max(0.1, (obstacle.userData.widthZ || 4.0) * 0.5);
        return { min: minCenter - halfWidth, max: maxCenter + halfWidth };
    }

    function getTrafficObjectXRange(obstacle, rootX = null) {
        const hasRootOverride = rootX !== null && rootX !== undefined && Number.isFinite(Number(rootX));
        if (!obstacle || !obstacle.userData) {
            const center = hasRootOverride ? Number(rootX) : (Number(obstacle?.position?.x) || 0);
            return { min: center - 2, max: center + 2 };
        }
        const center = (hasRootOverride ? Number(rootX) : (Number(obstacle.position.x) || 0))
            + (Number(obstacle.userData.collisionCenterOffsetX) || 0);
        const halfLength = Math.max(0.5, (Number(obstacle.userData.length) || 4) * 0.5);
        return { min: center - halfLength, max: center + halfLength };
    }

    function trafficZRangesOverlap(a, b, extra = 0) {
        return a.max + extra > b.min && b.max + extra > a.min;
    }

    function trafficObjectOverlapsLane(obstacle, lane, widthZ, extra = 0) {
        return trafficZRangesOverlap(getTrafficObjectZRange(obstacle), getTrafficLaneZRange(lane, widthZ), extra);
    }

    function getClosestLaneIndexForZ(z) {
        if (!lanePositions || lanePositions.length === 0) return -1;
        let bestIdx = 0;
        let bestDist = Infinity;
        for (let i = 0; i < lanePositions.length; i++) {
            const dist = Math.abs(lanePositions[i] - z);
            if (dist < bestDist) {
                bestDist = dist;
                bestIdx = i;
            }
        }
        return bestIdx;
    }

    function isIgnoredForTrafficMerge(obstacle) {
        if (!obstacle || !obstacle.userData) return true;
        const type = obstacle.userData.type;
        if (isTrafficPhantomHazard(obstacle)) return true;
        if (type === 'rising_rock' && obstacle.position.y < -1.0) return true;
        if (type === 'falling_wall' && obstacle.position.y > 8.0) return true;
        if (type === 'gate_part' && obstacle.position.y < -5.0) return true;
        return false;
    }

    function isTrafficMergeLaneClear(currentObstacle, lane, xPos, forwardBuffer = 125, backBuffer = 45) {
        if (!currentObstacle || !currentObstacle.userData) return false;
        const currentLength = currentObstacle.userData.length || 10;
        const currentWidth = currentObstacle.userData.widthZ || 5.2;
        for (let o of obstacles) {
            if (o === currentObstacle || isIgnoredForTrafficMerge(o)) continue;
            if (o.userData.type === 'sky_sweeper') {
                if (Math.abs(o.position.x - xPos) < (o.userData.blockRangeX || 180)) return false;
                continue;
            }
            if (!trafficObjectOverlapsLane(o, lane, currentWidth, 0.35)) continue;

            const dx = xPos - o.position.x;
            const otherLength = o.userData.length || 8;
            const bodyBuffer = (currentLength + otherLength) * 0.5 + 14;
            const aheadBuffer = Math.max(forwardBuffer, bodyBuffer);
            const rearBuffer = Math.max(backBuffer, bodyBuffer * 0.75);
            if (dx > -rearBuffer && dx < aheadBuffer) return false;
        }
        return true;
    }

    function isTrafficSpawnType(type) {
        return type === 'vehicle'
            || type === 'car'
            || type === 'motorcycle'
            || type === 'train'
            || type === 'stopped_train'
            || type === 'static_train';
    }

    function isTrafficObjectType(type) {
        return type === 'vehicle'
            || type === 'motorcycle'
            || type === 'train'
            || type === 'stopped_train'
            || type === 'static_train';
    }

    function isTrainLikeTrafficType(type) {
        return type === 'train' || type === 'stopped_train' || type === 'static_train';
    }

    function isTrafficVisualReadyForSpawn(type) {
        if (isTrainLikeTrafficType(type)) {
            return !shouldRequireDetailedTrainModel() || trainGlbReady || canUseStreamingVehicleFallback('train');
        }
        if (type === 'motorcycle') {
            return !shouldRequireDetailedAuxVehicleModels() || motorGlbReady || canUseStreamingVehicleFallback('motorcycle');
        }
        if (type === 'vehicle' || type === 'car') {
            return !shouldRequireDetailedAuxVehicleModels() || carGlbReady || canUseStreamingVehicleFallback('car');
        }
        return true;
    }

    function resolveReadyTrafficSpawnType(preferredType) {
        if (isTrafficVisualReadyForSpawn(preferredType)) return preferredType;
        const alternatives = isTrainLikeTrafficType(preferredType)
            ? ['car', 'motorcycle']
            : preferredType === 'motorcycle'
                ? ['car']
                : ['motorcycle'];
        return alternatives.find(isTrafficVisualReadyForSpawn) || null;
    }

    function getTrafficSafeGap(backObject, frontObject, extra = 10) {
        const backLength = backObject && backObject.userData ? (backObject.userData.length || 8) : 8;
        const frontLength = frontObject && frontObject.userData ? (frontObject.userData.length || 8) : 8;
        const trainBuffer = (isTrainLikeTrafficType(backObject && backObject.userData && backObject.userData.type)
            || isTrainLikeTrafficType(frontObject && frontObject.userData && frontObject.userData.type)) ? 14 : 0;
        return (backLength + frontLength) * 0.5 + extra + trainBuffer;
    }

    function getTrafficStopRootX(trafficObject, blocker, clearance = 1.25) {
        const blockerRange = getTrafficObjectXRange(blocker);
        const trafficOffset = Number(trafficObject?.userData?.collisionCenterOffsetX) || 0;
        const trafficHalfLength = Math.max(0.5, (Number(trafficObject?.userData?.length) || 8) * 0.5);
        return blockerRange.max + trafficHalfLength + clearance - trafficOffset;
    }

    function getTrafficSafeFollowSpeed(ownSpeed, frontSpeed) {
        const own = Number.isFinite(Number(ownSpeed)) ? Number(ownSpeed) : 0;
        const front = Number.isFinite(Number(frontSpeed)) ? Number(frontSpeed) : 0;
        if (own < 0 || front < 0) return Math.max(own, front);
        return Math.min(own, front);
    }

    // Map hazards still collide with the player, but they are trigger volumes for
    // road traffic. Keeping this as one collision-layer predicate prevents the
    // AI, spawn resolver and final overlap clamp from disagreeing with each other.
    function isTrafficPhantomHazard(obstacle) {
        if (!obstacle?.userData) return true;
        const type = obstacle.userData.type;
        // These shapes are real solid road blockers for both player and AI.
        // Keep the explicit allow-list ahead of legacy pooled flags so a reused
        // low wall can never inherit trigger/phantom behaviour. Sky sweepers
        // also reserve their entire rotating arm envelope; traffic must brake
        // before the mechanism instead of visibly driving through its blades.
        if (type === 'wall'
            || type === 'low_wall'
            || type === 'slide_barrier'
            || type === 'falling_wall'
            || type === 'rising_rock'
            || type === 'sky_sweeper') return false;
        if (obstacle.userData.trafficPhantom || obstacle.userData.triggerOnly) return true;
        return type === 'high_beam'
            || type === 'lava_lane'
            || type === 'energy_plasma'
            || type === 'snow_ice_road'
            || type === 'snow_falling_ball'
            || type === 'wind_fan'
            || type === 'traffic_light'
            || type === 'jump_pad'
            || type === 'coin';
    }

    // Traffic placement already avoids existing solid rows. This reciprocal guard handles the
    // opposite creation order: when a static wall/barrier is authored after a car, motorcycle or
    // train, move only that new static root farther down-road. Tutorial rows keep their exact
    // authored coordinates; normal/level spawns remain deterministic because no randomness is used.
    function resolveStaticRoadSpawnX(type, requestedX, lane, length, widthZ) {
        let resolvedX = Number(requestedX) || 0;
        const staticStub = { userData: { type, length } };
        for (let pass = 0; pass < 10; pass++) {
            let nextX = resolvedX;
            for (const traffic of obstacles) {
                if (!traffic?.userData || !isTrafficObjectType(traffic.userData.type)) continue;
                if (!trafficObjectOverlapsLane(traffic, lane, widthZ, 0.45)) continue;
                const safeGap = getTrafficSafeGap(traffic, staticStub, 18);
                if (Math.abs(resolvedX - traffic.position.x) < safeGap) {
                    nextX = Math.max(nextX, traffic.position.x + safeGap);
                }
            }
            if (nextX <= resolvedX + 0.001) break;
            resolvedX = nextX;
        }
        return resolvedX;
    }

    // Level formations are deterministic, but authored rows can place a long train beside a
    // wall/vehicle whose bounds overlap. Keep the requested lane and deterministically move only
    // the new traffic root farther down-road until its complete body has a safe gap.
    function resolveExactTrafficSpawnX(type, spawnX, lane, length, widthZ) {
        let resolvedX = spawnX;
        const trainLike = isTrainLikeTrafficType(type);
        for (let pass = 0; pass < 12; pass++) {
            let nextX = resolvedX;
            for (const other of obstacles) {
                if (!other || !other.userData) continue;
                const otherType = other.userData.type;
                if (isTrafficPhantomHazard(other)) continue;
                if (otherType === 'rising_rock' && other.position.y < -1.0) continue;
                if (otherType === 'gate_part' && other.position.y < -5.0) continue;
                if (!trafficObjectOverlapsLane(other, lane, widthZ, 0.45)) continue;

                const otherLength = other.userData.length || 8;
                const otherTrainLike = isTrainLikeTrafficType(otherType);
                const safeGap = (length + otherLength) * 0.5 + 16 + ((trainLike || otherTrainLike) ? 24 : 0);
                if (Math.abs(resolvedX - other.position.x) < safeGap) {
                    nextX = Math.max(nextX, other.position.x + safeGap);
                }
            }
            if (nextX <= resolvedX + 0.001) break;
            resolvedX = nextX;
        }
        return resolvedX;
    }

    function shouldTrafficBypassEmbeddedBlocker(trafficObject, blocker, distanceToBlocker) {
        if (!trafficObject || !trafficObject.userData || !blocker || !blocker.userData) return false;
        if (isTrafficObjectType(blocker.userData.type)) return false;
        if (blocker.userData.type === 'traffic_light') return true;
        return false;
    }

    function isTrafficSpawnAreaClear(type, x, lane, length, widthZ) {
        if (!player || x < player.position.x + 520) return false;
        const isTrainLike = isTrainLikeTrafficType(type);
        // RİTİM: geç koşuda aynı şeritteki ARAÇ aralığı daralır → "geç sert".
        // Neden burası: yoğunluğu spawn tick hızı DEĞİL bu occupancy kuralı sınırlıyor
        // (taban: 7.4 tick/sn → 0.8 spawn/sn). Aralığı kısaltmak ölçülebilir etki vermiyor,
        // asıl tavan burası. Tren benzerleri HARİÇ: uzun gövdeleri yüzünden daraltmak
        // geçilemez tıkaç riski taşır. Yalnız dalgada; nefeste bugünkü aralık korunur.
        const trafficGapScale = (!isTrainLike && rhythmMode === 'wave')
            ? rhythmLerp(RHYTHM_TRAFFIC_GAP_SCALE, getRhythmIntensity())
            : 1;
        const baseAheadBuffer = (isTrainLike ? 185 : 128) * trafficGapScale;
        const baseRearBuffer = (isTrainLike ? 135 : 92) * trafficGapScale;

        for (let o of obstacles) {
            if (!o || !o.userData) continue;
            // A high falling wall still reserves its landing area. Ignoring it here allowed a
            // newly spawned train to occupy the drop row and later appear embedded in the wall.
            if (isIgnoredForTrafficMerge(o) && o.userData.type !== 'falling_wall') continue;
            if (!trafficObjectOverlapsLane(o, lane, widthZ, 0.45)) continue;

            const otherLength = o.userData.length || 8;
            const otherTrainLike = isTrainLikeTrafficType(o.userData.type);
            // DİKKAT: yalnız EK boşluk (28) ölçeklenir. (length+otherLength)*0.5 gövdelerin
            // geometrik çakışmama mesafesidir — onu ölçeklemek araçları iç içe geçirir.
            const bodyBuffer = (length + otherLength) * 0.5 + (28 * trafficGapScale) + (isTrainLike || otherTrainLike ? 34 : 0);
            const aheadBuffer = Math.max(baseAheadBuffer, bodyBuffer);
            const rearBuffer = Math.max(baseRearBuffer, bodyBuffer * 0.9);
            const dx = x - o.position.x;
            if (dx > -rearBuffer && dx < aheadBuffer) return false;
        }

        if (gamePhase >= 4) {
            for (let cap of waterBounceCaps) {
                if (!cap || !cap.userData) continue;
                const dz = Math.abs(cap.position.z - lane);
                const combinedWidth = ((cap.userData.widthZ || 11.8) + widthZ) * 0.5 + 1.2;
                if (dz >= combinedWidth) continue;
                const dx = Math.abs(cap.position.x - x);
                const combinedLength = ((cap.userData.length || 11.8) + length) * 0.5 + 35;
                if (dx < combinedLength) return false;
            }
        }

        if (hasGroundCoinNearLane(x, lane, length, widthZ)) return false;
        return true;
    }

    function resolveTrafficSpawnPlacement(type, spawnX, preferredLaneIdx, length, widthZ, preferredLaneZ = null) {
        if (!lanePositions || lanePositions.length === 0) return null;
        const laneOrder = [];
        const preferredIdx = Number.isInteger(preferredLaneIdx)
            ? Math.max(0, Math.min(lanePositions.length - 1, preferredLaneIdx))
            : getClosestLaneIndexForZ(typeof preferredLaneZ === 'number' ? preferredLaneZ : getRoadCenterZ());

        const addLane = (idx) => {
            if (idx >= 0 && idx < lanePositions.length && !laneOrder.includes(idx)) laneOrder.push(idx);
        };
        addLane(preferredIdx);
        if (levelPatternSpawnContext?.forceExact && levelSystem?.isActive?.()) {
            const lane = lanePositions[preferredIdx];
            return {
                x: resolveExactTrafficSpawnX(type, spawnX, lane, length, widthZ),
                lane,
                laneIdx: preferredIdx
            };
        }
        for (let step = 1; step < lanePositions.length; step++) {
            if (Math.random() < 0.5) {
                addLane(preferredIdx - step);
                addLane(preferredIdx + step);
            } else {
                addLane(preferredIdx + step);
                addLane(preferredIdx - step);
            }
        }

        const isTrainLike = type === 'train' || type === 'stopped_train' || type === 'static_train';
        const xOffsets = isTrainLike ? [0, 180, -140, 300, -240, 430] : [0, 110, -90, 220, -170, 340];
        for (let offset of xOffsets) {
            const x = spawnX + offset;
            if (!player || x < player.position.x + 520) continue;
            for (let idx of laneOrder) {
                const lane = lanePositions[idx];
                if (isTrafficSpawnAreaClear(type, x, lane, length, widthZ)) {
                    return { x, lane, laneIdx: idx };
                }
            }
        }
        return null;
    }

    function beginTrafficLaneChange(obstacle, targetLane, currentTime) {
        obstacle.userData.targetLane = targetLane;
        obstacle.userData.laneChanging = true;
        obstacle.userData.lastLaneChangeTime = currentTime;
        obstacle.userData.nextLaneDecisionTime = currentTime + 0.35;
    }

    function setTrafficLaneDecisionDelay(obstacle, currentTime, delay = 0.35) {
        if (!obstacle || !obstacle.userData) return;
        obstacle.userData.nextLaneDecisionTime = currentTime + delay;
    }

    function checkAreaForObstacles(x, lane, length, widthZ, idToIgnore) {
        for (let o of obstacles) {
            if (o.uuid === idToIgnore || isTrafficPhantomHazard(o)) continue;
            const dx = x - o.position.x; if (dx <= -2) continue;
            const combinedLength = (length + (o.userData.length || 4.0)) / 2 + 35;
            if (trafficObjectOverlapsLane(o, lane, widthZ, 0.8) && dx < combinedLength) return o;
        }
        return null;
    }

    function checkLaneIsBlocked(lane, startX) {
        for(let o of obstacles) {
            if (isTrafficPhantomHazard(o)) continue;
            if (o.userData.speedX === 0 || o.userData.type === 'falling_wall' || o.userData.type === 'slide_barrier') {
                const dist = Math.abs(o.position.x - startX);
                if (dist < 100 && trafficObjectOverlapsLane(o, lane, 3.5, 0.3)) return true;
            }
        }
        return false;
    }
    function checkLaneSafety(lane, xPos, length) {
        for (let o of obstacles) {
            if (isTrafficPhantomHazard(o)) continue;
            
            if (o.userData.type === 'rising_rock' && o.position.y < -1.0) continue;
            if (o.userData.type === 'falling_wall' && o.position.y > 8.0) continue;
            if (o.userData.type === 'gate_part' && o.position.y < -5.0) continue;

            if (trafficObjectOverlapsLane(o, lane, 3.5, 0.3)) {
                const dx = Math.abs(o.position.x - xPos);
                const safeDist = ((o.userData.length || 4.0) / 2) + (length / 2) + 20;
                if (dx < safeDist) return false; 
            }
        }
        return true; 
    }

    function hasGroundCoinNearLane(x, lane, length = 8.0, widthZ = 4.8) {
        const halfLength = length * 0.5 + GROUND_COIN_LINE_SPACING;
        const halfWidth = widthZ * 0.5 + 1.8;
        for (let c of coins) {
            if (!c || !c.userData || !c.userData.isGroundCoinLine || c.parent !== scene) continue;
            if (Math.abs(c.position.x - x) < halfLength && Math.abs(c.position.z - lane) < halfWidth) {
                return true;
            }
        }
        return false;
    }

    function canPlaceGroundCoinLine(startX, laneIdx, count) {
        if (!lanePositions || laneIdx < 0 || laneIdx >= lanePositions.length) return false;
        const lane = lanePositions[laneIdx];
        const lineLength = Math.max(8, (count - 1) * GROUND_COIN_LINE_SPACING + 4);
        const centerX = startX + lineLength * 0.5;
        if (!checkLaneSafety(lane, centerX, lineLength)) return false;
        if (checkAreaForObstacles(centerX, lane, lineLength, 4.8, null)) return false;
        if (hasGroundCoinNearLane(centerX, lane, lineLength, 4.8)) return false;
        if (gamePhase >= 4) {
            const waterCapBlocked = waterBounceCaps.some((cap) => {
                if (!cap || !cap.userData) return false;
                const capLength = cap.userData.length || 11.8;
                const capWidth = cap.userData.widthZ || 11.8;
                return Math.abs(cap.position.x - centerX) < ((capLength + lineLength) * 0.5 + 10)
                    && Math.abs(cap.position.z - lane) < ((capWidth + 4.8) * 0.5 + 0.8);
            });
            if (waterCapBlocked) return false;
        }
        return true;
    }

    function getGroundCoinLineInterval() {
        const pressure = getLanePressureLevel();
        return Math.max(340, 520 - pressure * 26 + Math.random() * 160);
    }

    function spawnGroundCoinLine(startX, laneIdx, count) {
        const lane = lanePositions[laneIdx];
        const floorY = getActiveRoadFloorY();
        const yOffset = floorY + 2.4;
        const zDrift = (Math.random() - 0.5) * 0.6;
        for (let i = 0; i < count; i++) {
            const coin = createCoin(startX + i * GROUND_COIN_LINE_SPACING, lane + zDrift, scene, yOffset);
            coin.userData.isGroundCoinLine = true;
            coin.userData.baseY = yOffset;
            coin.userData.groundLineIndex = i;
        }
    }

    function trySpawnGroundCoinLine() {
        if (!player || !coinPrototype || !lanePositions || !lanePositions.length) return false;
        if (isSkyNoGameplaySpawnActive()) return false;
        if (lavaDropTransitionActive && !lavaMapActivated) return false;

        const playerX = player.position.x;
        if (nextGroundCoinSpawnX <= 0 || nextGroundCoinSpawnX < playerX + 300) {
            nextGroundCoinSpawnX = playerX + 430 + Math.random() * 190;
        }
        if (nextGroundCoinSpawnX > playerX + 780) return false;

        const liveGroundCoins = coins.reduce((count, c) => {
            return count + (c && c.userData && c.userData.isGroundCoinLine && c.parent === scene ? 1 : 0);
        }, 0);
        if (liveGroundCoins > 34) return false;

        const count = GROUND_COIN_LINE_MIN_COUNT + Math.floor(Math.random() * (GROUND_COIN_LINE_MAX_COUNT - GROUND_COIN_LINE_MIN_COUNT + 1));
        const laneOrder = lanePositions.map((_, idx) => idx).sort(() => Math.random() - 0.5);
        for (let laneIdx of laneOrder) {
            if (!canPlaceGroundCoinLine(nextGroundCoinSpawnX, laneIdx, count)) continue;
            spawnGroundCoinLine(nextGroundCoinSpawnX, laneIdx, count);
            nextGroundCoinSpawnX += getGroundCoinLineInterval();
            return true;
        }

        nextGroundCoinSpawnX += 120;
        return false;
    }

    function isFallingWallDropZoneBlocked(xPos, lane) {
        const wallLength = 6.0;
        const wallWidthZ = 6.8;
        for (let o of obstacles) {
            if (!o || !o.userData) continue;
            const type = o.userData.type;
            if (type === 'high_beam' || type === 'traffic_light' || type === 'wind_fan') continue;

            const otherLength = o.userData.length || 4.0;
            const otherWidthZ = o.userData.widthZ || 4.0;
            const combinedLength = (wallLength + otherLength) / 2 + 12.0;
            const combinedWidth = (wallWidthZ + otherWidthZ) / 2 + 0.4;

            if (Math.abs(o.position.x - xPos) < combinedLength &&
                Math.abs(o.position.z - lane) < combinedWidth) {
                return true;
            }
        }
        return false;
    }

    function canPlaceSkySweeperAt(candidateX, floorY = getSweeperFloorY()) {
        const sweeperClearance = Math.max(120, getRoadHalfWidth() + 92);
        for (let o of obstacles) {
            if (o.userData.type === 'sky_sweeper') {
                if (Math.abs(o.position.x - candidateX) < (o.userData.blockRangeX || 220)) return false;
                continue;
            }
            if (Math.abs(o.position.y - floorY) >= 40) continue;
            let blockDist = sweeperClearance + ((o.userData.length || 4.0) * 0.18);
            if (o.userData.type === 'wind_fan') blockDist = 170;
            else if (o.userData.type === 'traffic_light') blockDist = 90;
            if (Math.abs(o.position.x - candidateX) < blockDist) return false;
        }
        return true;
    }

    function getScheduledSweeperSpawnX() {
        if (!player || !isSweeperPhaseActive()) return null;
        if (!Number.isFinite(nextSkySweeperSpawnX) || nextSkySweeperSpawnX <= player.position.x + 120) return null;
        return nextSkySweeperSpawnX;
    }

    function isXReservedForScheduledSweeper(x, buffer = 260) {
        const scheduledX = getScheduledSweeperSpawnX();
        return scheduledX !== null && Math.abs(x - scheduledX) < buffer;
    }

    function isXBlockedByActiveOrScheduledSweeper(x, buffer = 260) {
        if (isXReservedForScheduledSweeper(x, buffer)) return true;
        for (let o of obstacles) {
            if (!o || !o.userData || o.userData.type !== 'sky_sweeper') continue;
            if (Math.abs(o.position.x - x) < (o.userData.blockRangeX || 270)) return true;
        }
        return false;
    }

    function canPlaceLavaLaneHazardAt(candidateX, lane) {
        const lavaLength = 34;
        const lavaWidth = LANE_WIDTH - 0.6;
        if (isXReservedForScheduledSweeper(candidateX, 330)) return false;
        for (let o of obstacles) {
            if (!o || !o.userData) continue;
            const type = o.userData.type;
            if (type !== 'lava_lane' && type !== 'sky_sweeper' && type !== 'energy_plasma' && type !== 'traffic_light' && type !== 'wind_fan') continue;

            const otherLength = o.userData.length || 4.0;
            const otherWidth = o.userData.widthZ || 4.0;
            const combinedLength = (lavaLength + otherLength) * 0.5 + 18;
            const combinedWidth = (lavaWidth + otherWidth) * 0.5 + 0.6;

            if (Math.abs(o.position.x - candidateX) < combinedLength &&
                Math.abs(o.position.z - lane) < combinedWidth) {
                return false;
            }
        }
        return true;
    }

    function canPlaceEnergyPlasmaAt(candidateX) {
        const plasmaLength = 5.2;
        if (isXReservedForScheduledSweeper(candidateX, 300)) return false;
        for (let o of obstacles) {
            if (!o || !o.userData) continue;
            const type = o.userData.type;
            if (type === 'sky_sweeper') {
                if (Math.abs(o.position.x - candidateX) < (o.userData.blockRangeX || 270)) return false;
                continue;
            }
            if (type !== 'energy_plasma') continue;

            const otherLength = o.userData.length || 4.0;
            const combinedLength = (plasmaLength + otherLength) * 0.5 + 34;

            if (Math.abs(o.position.x - candidateX) < combinedLength) {
                return false;
            }
        }
        return true;
    }

    function canPlaceSnowIceRoadAt(candidateX) {
        const patchLength = SNOW_ICE_ROAD_LENGTH;
        if (isXReservedForScheduledSweeper(candidateX, Math.max(360, patchLength * 0.5 + 190))) return false;
        for (let o of obstacles) {
            if (!o || !o.userData) continue;
            const type = o.userData.type;
            if (type === 'sky_sweeper') {
                const blockRange = (patchLength + (o.userData.blockRangeX || 270)) * 0.5 + 120;
                if (Math.abs(o.position.x - candidateX) < blockRange) return false;
                continue;
            }
            if (type !== 'snow_ice_road') continue;
            const otherLength = o.userData.length || 6.0;
            const combinedLength = (patchLength + otherLength) * 0.5 + 86;
            if (Math.abs(o.position.x - candidateX) < combinedLength) {
                return false;
            }
        }
        return true;
    }

    function getSnowballTargetZ(startLaneIdx = 0) {
        const laneCount = lanePositions.length || 1;
        const safeIndex = ((startLaneIdx % laneCount) + laneCount) % laneCount;
        const laneZ = lanePositions[safeIndex] ?? getRoadCenterZ();
        const halfImpact = SNOWBALL_RADIUS;
        const minZ = roadLimitZMin + halfImpact;
        const maxZ = roadLimitZMax - halfImpact;
        if (minZ >= maxZ) return getRoadCenterZ();
        return Math.max(minZ, Math.min(maxZ, laneZ));
    }

    function getSnowballStrikeY() {
        const headY = player ? player.position.y + (isSliding ? slideHeight : normalHeight) * 0.5 : normalHeight;
        return headY + SNOWBALL_RADIUS - 0.35;
    }

    function getSnowballRunDirection() {
        const dir = tempSnowballForward.set(0, 0, -1).applyAxisAngle(tempUp, yaw);
        let scaleFactor = 1;
        if (Math.abs(dir.x) > 0.01) {
            scaleFactor = 1 / Math.abs(dir.x);
            scaleFactor = Math.min(scaleFactor, 2.5);
        }
        dir.multiplyScalar(scaleFactor);
        if (dir.x < 0.05) dir.x = 1;
        return dir;
    }

    function clampSnowballPathZ(z) {
        const halfImpact = SNOWBALL_RADIUS;
        const minZ = roadLimitZMin + halfImpact;
        const maxZ = roadLimitZMax - halfImpact;
        if (minZ >= maxZ) return getRoadCenterZ();
        return Math.max(minZ, Math.min(maxZ, z));
    }

    function getSnowballRunPathTarget(lead) {
        if (!player) return { x: lead, z: getRoadCenterZ(), dirZ: 0 };
        const dir = getSnowballRunDirection();
        const strafePreview = Math.max(-10, Math.min(10, currentStrafeVelocity * 18));
        return {
            x: player.position.x + Math.max(6, lead),
            z: clampSnowballPathZ(player.position.z + dir.z * lead + strafePreview),
            dirZ: dir.z
        };
    }

    function getSnowballPlayerSpeedPerSecond() {
        const fps = Math.max(30, Math.min(180, smoothedFps || 60));
        return Math.max(12, moveSpeed * fps);
    }

    function getPlayerLaneIndexForSnowball() {
        if (!player || !lanePositions.length) return 0;
        let nearestIdx = 0;
        let nearestDist = Number.POSITIVE_INFINITY;
        for (let i = 0; i < lanePositions.length; i++) {
            const dist = Math.abs(player.position.z - lanePositions[i]);
            if (dist < nearestDist) {
                nearestDist = dist;
                nearestIdx = i;
            }
        }
        return nearestIdx;
    }

    function getSnowballWallStyleDropPlan() {
        const strikeY = getSnowballStrikeY();
        const targetY = SNOWBALL_RADIUS;
        const speedPerSecond = getSnowballPlayerSpeedPerSecond();
        const impactTime = SNOWBALL_WALL_STYLE_LANDING_TIME;
        // The ball must reach the player's HEAD (strikeY) exactly when the player runs under it.
        // Lead = how far the player travels in impactTime; fall speed is tuned to strikeY (not
        // the ground) so it doesn't pass the head and shatter early ("kar erken düşüyor").
        const lead = Math.max(42, Math.min(360, (speedPerSecond * impactTime) + PLAYER_WIDTH * 0.5));
        const arrivalTime = impactTime;
        const fallSpeed = Math.max(
            SNOWBALL_MIN_FALL_SPEED,
            Math.min(SNOWBALL_MAX_FALL_SPEED, (SNOWBALL_FALL_START_Y - strikeY) / impactTime)
        );
        return { lead, fallSpeed, impactTime, arrivalTime, strikeY, targetY, speedPerSecond };
    }

    function spawnSnowballLikeFallingWall(laneIdx = null, forcedImpactX = null, presetDropPlan = null) {
        if (!player || !lanePositions.length) return null;
        const targetLaneIdx = Number.isInteger(laneIdx) ? laneIdx : getPlayerLaneIndexForSnowball();
        const dropPlan = presetDropPlan || getSnowballWallStyleDropPlan();
        const targetLead = Number.isFinite(forcedImpactX)
            ? Math.max(8, forcedImpactX - player.position.x)
            : dropPlan.lead;
        const target = getSnowballRunPathTarget(targetLead);
        target.x = Number.isFinite(forcedImpactX) ? forcedImpactX : target.x;
        target.z = getSnowballTargetZ(targetLaneIdx);
        if (isXBlockedByActiveOrScheduledSweeper(target.x, 310)) return null;
        if (getSnowTunnelCoveringX(target.x, SNOWBALL_RADIUS + 8)) return null;

        createObstacle('snow_falling_ball', target.x, targetLaneIdx);
        const snowball = obstacles[obstacles.length - 1];
        if (snowball && snowball.userData && snowball.userData.type === 'snow_falling_ball') {
            snowball.position.z = target.z;
            snowball.userData.fallSpeed = dropPlan.fallSpeed;
            snowball.userData.dropLead = Math.max(0, target.x - player.position.x);
            snowball.userData.expectedImpactTime = dropPlan.arrivalTime;
            snowball.userData.groundImpactTime = dropPlan.impactTime;
            snowball.userData.headImpactTime = dropPlan.arrivalTime;
            snowball.userData.headImpactY = dropPlan.strikeY;
            snowball.userData.groundImpactY = dropPlan.targetY;
            snowball.userData.spawnMoveSpeed = moveSpeed;
            snowball.userData.wallStyleDrop = true;
            snowball.userData.pathTargetZ = target.z;
            snowball.userData.pathDirZ = target.dirZ;
            return snowball;
        }
        return null;
    }

    function trySpawnSnowballHazard() {
        if (gamePhase < 5 || !snowMapActivated || !player || onSkyLayer) return false;
        const playerX = player.position.x;
        if (nextSnowballX <= 0 || nextSnowballX < playerX - 240) {
            nextSnowballX = playerX + SNOWBALL_FIRST_TRIGGER_MIN + Math.random() * SNOWBALL_FIRST_TRIGGER_RANDOM;
            return false;
        }
        const dropPlan = getSnowballWallStyleDropPlan();
        const earliestSafeImpactX = playerX + dropPlan.lead;
        if (nextSnowballX < earliestSafeImpactX) {
            nextSnowballX = earliestSafeImpactX;
        }
        if (playerX + dropPlan.lead < nextSnowballX) return false;

        const coveringTunnel = getSnowTunnelCoveringX(nextSnowballX, SNOWBALL_RADIUS + 8);
        if (coveringTunnel) {
            nextSnowballX = coveringTunnel.endX + SNOWBALL_REPEAT_TRIGGER_MIN;
            return false;
        }

        const snowball = spawnSnowballLikeFallingWall(getPlayerLaneIndexForSnowball(), nextSnowballX, dropPlan);
        if (!snowball) return false;
        nextSnowballX = snowball.position.x + SNOWBALL_REPEAT_TRIGGER_MIN + Math.random() * SNOWBALL_REPEAT_TRIGGER_RANDOM;
        return true;
    }

    function trySpawnSnowIceRoadHazard() {
        if (gamePhase < 5 || !snowMapActivated || !player) return false;
        const playerX = player.position.x;
        if (nextSnowIceRoadX < playerX + 620) {
            nextSnowIceRoadX = playerX + 980 + Math.random() * 320;
        }
        if (nextSnowIceRoadX > playerX + 1180) return false;

        const hasLiveIceRoad = obstacles.some((o) => {
            return o && o.userData && o.userData.type === 'snow_ice_road'
                && o.position.x + ((o.userData.length || SNOW_ICE_ROAD_LENGTH) * 0.5) > playerX - 180;
        });
        if (hasLiveIceRoad) {
            nextSnowIceRoadX = Math.max(nextSnowIceRoadX, playerX + 1500 + Math.random() * 480);
            return false;
        }

        if (canPlaceSnowIceRoadAt(nextSnowIceRoadX)) {
            createObstacle('snow_ice_road', nextSnowIceRoadX, 0);
            nextSnowIceRoadX += 1850 + Math.random() * 850;
            return true;
        }

        nextSnowIceRoadX += 190;
        return false;
    }

    function getActiveSnowIceRoadUnderPlayer() {
        if (!player || gamePhase < 5 || !snowMapActivated || onSkyLayer) return null;
        const px = player.position.x;
        const pz = player.position.z;
        for (let i = 0; i < obstacles.length; i++) {
            const o = obstacles[i];
            if (!o || !o.userData || o.userData.type !== 'snow_ice_road' || !o.userData.active) continue;
            const halfLen = (o.userData.length || SNOW_ICE_ROAD_LENGTH) * 0.5;
            const halfWidth = (o.userData.widthZ || getRoadWidth()) * 0.5;
            if (px >= o.position.x - halfLen && px <= o.position.x + halfLen &&
                pz >= o.position.z - halfWidth - 0.6 && pz <= o.position.z + halfWidth + 0.6) {
                return o;
            }
        }
        return null;
    }

    function findSkySweeperSpawnX(baseX, floorY = getSweeperFloorY()) {
        const candidateOffsets = [0, 70, 140, 210];
        for (let offset of candidateOffsets) {
            const candidateX = baseX + offset;
            if (canPlaceSkySweeperAt(candidateX, floorY)) return candidateX;
        }
        return null;
    }

    function trySpawnSkySweeperEscort(sweeperX, offset, preferredTypes) {
        const escortX = sweeperX + offset;
        const laneOrder = lanePositions.map((_, idx) => idx).sort(() => Math.random() - 0.5);
        const lengthHints = { vehicle: 7, high_beam: 3, stopped_train: 26 };
        for (let laneIdx of laneOrder) {
            const lane = lanePositions[laneIdx];
            for (let type of preferredTypes) {
                type = resolveReadyTrafficSpawnType(type);
                if (!type) continue;
                const approxLength = lengthHints[type] || 8;
                if (!checkLaneSafety(lane, escortX, approxLength)) continue;
                const occupied = obstacles.some(o => {
                    return Math.abs(o.position.x - escortX) < 120 && trafficObjectOverlapsLane(o, lane, 4.0, 2.0);
                });
                if (occupied) continue;
                if (isTrafficSpawnType(type) && !isTrafficSpawnAreaClear(type, escortX, lane, getLaneSequenceFootprint(type).length, getLaneSequenceFootprint(type).widthZ)) continue;
                const createdEscort = createObstacle(type, escortX, laneIdx);
                if (createdEscort) return true;
            }
        }
        return false;
    }

    function spawnSkySweeperEscortObstacles(sweeperX) {
        const trailingOffsets = [-340, -270, -210];
        const leadingOffsets = [240, 310, 380];

        let trailingPlaced = false;
        for (let offset of trailingOffsets) {
            trailingPlaced = trySpawnSkySweeperEscort(sweeperX, offset, ['stopped_train', 'vehicle', 'high_beam']);
            if (trailingPlaced) break;
        }

        let leadingPlaced = false;
        for (let offset of leadingOffsets) {
            leadingPlaced = trySpawnSkySweeperEscort(sweeperX, offset, ['stopped_train', 'vehicle', 'high_beam', 'slide_barrier']);
            if (leadingPlaced) break;
        }

        if (!trailingPlaced) {
            trySpawnSkySweeperEscort(sweeperX, -170, ['vehicle', 'high_beam']);
        }
        if (!leadingPlaced) {
            trySpawnSkySweeperEscort(sweeperX, 170, ['vehicle', 'high_beam', 'slide_barrier']);
        }
    }

    function getLaneSequenceFootprint(type) {
        if (type === 'motorcycle') return { length: 4.0, widthZ: 1.4 };
        if (type === 'stopped_train' || type === 'static_train' || type === 'train') return { length: 72.0, widthZ: 7.0 };
        if (type === 'wall') return { length: 5.0, widthZ: 6.8 };
        if (type === 'low_wall') return { length: 5.0, widthZ: 6.8 };
        if (type === 'rising_rock') return { length: 6.0, widthZ: 5.0 };
        if (type === 'slide_barrier') return { length: 2.0, widthZ: 6.8 };
        return { length: 10.0, widthZ: 5.2 };
    }

    function getMinimumOpenLaneCountForSequence() {
        return lanePositions.length >= 7 ? 3 : 2;
    }

    function shouldIgnoreLaneSequenceObstacle(type) {
        return type === 'lava_lane'
            || type === 'snow_ice_road'
            || type === 'traffic_light'
            || type === 'wind_fan';
    }

    function isLaneBlockedNearXForSequence(x, lane, length, widthZ) {
        for (let o of obstacles) {
            if (!o || !o.userData) continue;
            const type = o.userData.type;
            if (shouldIgnoreLaneSequenceObstacle(type)) continue;
            if (type === 'rising_rock' && o.position.y < -1.0) continue;
            if (type === 'falling_wall' && o.position.y > 8.0) continue;
            if (type === 'gate_part' && o.position.y < -5.0) continue;

            const otherLength = o.userData.length || 6.0;
            const combinedLength = (length + otherLength) * 0.5 + 28.0;
            if (Math.abs(o.position.x - x) < combinedLength && trafficObjectOverlapsLane(o, lane, widthZ, 0.6)) {
                return true;
            }
        }

        if (gamePhase >= 4) {
            for (let cap of waterBounceCaps) {
                if (!cap || !cap.userData) continue;
                const otherLength = cap.userData.length || 11.8;
                const otherWidth = cap.userData.widthZ || 11.8;
                const combinedLength = (length + otherLength) * 0.5 + 24.0;
                const combinedWidth = (widthZ + otherWidth) * 0.5 + 0.6;
                if (Math.abs(cap.position.x - x) < combinedLength && Math.abs(cap.position.z - lane) < combinedWidth) {
                    return true;
                }
            }
        }

        return false;
    }

    function getBlockedLaneCountNearXForSequence(x, length = 12.0, widthZ = 5.2) {
        let count = 0;
        for (let lane of lanePositions) {
            if (isLaneBlockedNearXForSequence(x, lane, length, widthZ)) count++;
        }
        return count;
    }

    function canPlaceLaneSequenceObstacle(type, x, laneIdx) {
        if (!lanePositions || laneIdx < 0 || laneIdx >= lanePositions.length) return false;
        if (!player || x < player.position.x + 520) return false;

        const lane = lanePositions[laneIdx];
        const footprint = getLaneSequenceFootprint(type);
        if (getBlockedLaneCountNearXForSequence(x, footprint.length, footprint.widthZ) >= lanePositions.length - getMinimumOpenLaneCountForSequence()) {
            return false;
        }
        if (isLaneBlockedNearXForSequence(x, lane, footprint.length, footprint.widthZ)) return false;

        const sweeperBlocked = obstacles.some(o => {
            return o && o.userData && o.userData.type === 'sky_sweeper'
                && Math.abs(x - o.position.x) < (o.userData.blockRangeX || 180);
        });
        if (sweeperBlocked) return false;

        if (!checkLaneSafety(lane, x, footprint.length)) return false;
        if (hasGroundCoinNearLane(x, lane, footprint.length, footprint.widthZ)) return false;
        if (isTrafficSpawnType(type) && !isTrafficSpawnAreaClear(type, x, lane, footprint.length, footprint.widthZ)) return false;
        return !checkAreaForObstacles(x, lane, footprint.length, footprint.widthZ, null);
    }

    function getSequencedLaneOrder(baseLaneIdx) {
        const order = [];
        const addLane = (idx) => {
            if (idx >= 0 && idx < lanePositions.length && idx !== baseLaneIdx && !order.includes(idx)) order.push(idx);
        };

        const preferredSteps = [2, 1, 3, 4, 5, 6, 7];
        for (let step of preferredSteps) {
            if (step >= lanePositions.length) continue;
            if (Math.random() < 0.5) {
                addLane(baseLaneIdx - step);
                addLane(baseLaneIdx + step);
            } else {
                addLane(baseLaneIdx + step);
                addLane(baseLaneIdx - step);
            }
        }

        return order;
    }

    function getLaneSequenceExtraCount(primaryChoice, baseX) {
        if (primaryChoice === 'gate_cluster' || primaryChoice === 'high_beam' || primaryChoice === 'falling_wall') return 0;

        const pressure = getLanePressureLevel();
        if (pressure <= 0) return 0;

        let extraCount = 0;
        const firstExtraChance = Math.min(0.88, 0.30 + pressure * 0.14);
        if (Math.random() < firstExtraChance) extraCount++;
        if (pressure >= 2 && Math.random() < Math.min(0.52, 0.16 + pressure * 0.07)) extraCount++;
        if (pressure >= 4 && Math.random() < 0.20) extraCount++;

        const blockedCount = getBlockedLaneCountNearXForSequence(baseX);
        const maxExtra = Math.max(0, lanePositions.length - getMinimumOpenLaneCountForSequence() - blockedCount);
        return Math.min(extraCount, maxExtra);
    }

    function pickLaneSequenceCompanionType(primaryChoice, placedCount) {
        const pressure = getLanePressureLevel();
        const r = Math.random();

        if (primaryChoice === 'train_type') {
            if (pressure >= 3 && placedCount === 0 && r < 0.30) return 'stopped_train';
            return r < 0.78 ? 'car' : 'motorcycle';
        }

        if (primaryChoice === 'vehicle') {
            if (pressure >= 2 && r < 0.20) return 'stopped_train';
            return r < 0.72 ? 'car' : 'motorcycle';
        }

        if (primaryChoice === 'wall_type') {
            return gamePhase === 0 && r < 0.24 ? 'low_wall' : (r < 0.82 ? 'car' : 'motorcycle');
        }

        if (primaryChoice === 'low_wall_type' || primaryChoice === 'slide_barrier') {
            return r < 0.80 ? 'car' : 'motorcycle';
        }

        return r < 0.76 ? 'car' : 'motorcycle';
    }

    function spawnLaneScaledCompanions(primaryChoice, baseX, baseLaneIdx) {
        const targetCount = getLaneSequenceExtraCount(primaryChoice, baseX);
        if (targetCount <= 0) return 0;

        const laneOrder = getSequencedLaneOrder(baseLaneIdx);
        const xOffsets = primaryChoice === 'train_type' ? [36, -42, 74] : [28, -34, 58];
        let placed = 0;

        for (let laneIdx of laneOrder) {
            if (placed >= targetCount) break;

            const companionType = resolveReadyTrafficSpawnType(pickLaneSequenceCompanionType(primaryChoice, placed));
            if (!companionType) continue;
            const xOffset = xOffsets[placed % xOffsets.length] + (Math.random() * 14 - 7);
            const companionX = baseX + xOffset;

            if (!canPlaceLaneSequenceObstacle(companionType, companionX, laneIdx)) continue;
            const createdCompanion = createObstacle(companionType, companionX, laneIdx);
            if (createdCompanion) placed++;
        }

        return placed;
    }

    function trySpawnExtraTrain(baseX, baseLaneIdx) {
        if (Math.random() < 0.35) {
            const possibleTargets = [];
            if (baseLaneIdx - 2 >= 0) possibleTargets.push(baseLaneIdx - 2);
            if (baseLaneIdx + 2 < lanePositions.length) possibleTargets.push(baseLaneIdx + 2);
            let targetLaneIdx;
            if (possibleTargets.length > 0) targetLaneIdx = possibleTargets[Math.floor(Math.random() * possibleTargets.length)];
            else {
                const neighbors = [];
                if (baseLaneIdx > 0) neighbors.push(baseLaneIdx - 1); if (baseLaneIdx < lanePositions.length - 1) neighbors.push(baseLaneIdx + 1);
                if (neighbors.length > 0) targetLaneIdx = neighbors[Math.floor(Math.random() * neighbors.length)];
            }
            if (targetLaneIdx !== undefined) {
                let occupiedCount = 0; for(let l of lanePositions) { if (checkLaneIsBlocked(l, baseX)) occupiedCount++; }
                if (occupiedCount < lanePositions.length - 2) {
                    const xOffset = 25 + Math.random() * 15; const newX = baseX + xOffset; const nLane = lanePositions[targetLaneIdx];
                    const nOccupied = obstacles.some(o => Math.abs(newX - o.position.x) < 200 && trafficObjectOverlapsLane(o, nLane, 3.5, 0.3));
                    const sweeperBlocked = obstacles.some(o => o.userData.type === 'sky_sweeper' && Math.abs(newX - o.position.x) < (o.userData.blockRangeX || 180));
                    const coinBlocked = hasGroundCoinNearLane(newX, nLane, 72.0, 6.2);
                    const spawnClear = isTrafficSpawnAreaClear('stopped_train', newX, nLane, 72.0, 6.2);
                    if (!nOccupied && !sweeperBlocked && !coinBlocked && spawnClear) { createObstacle('stopped_train', newX, targetLaneIdx); }
                }
            }
        }
    }

    // Düzenli engel spawn'ının şerit doluluk testi. spawnManager'daki ana guard'dan
    // ÇIKARILDI çünkü ölü-koridor kurtarması aynı testi birden çok şerit için tekrarlıyor;
    // iki kopya ayrışırsa biri diğerinden geniş bloklar ve sessizce ölü bölge büyür.
    // Spawn koridorunda (oyuncunun 120-960 birim önü) kaç engel var.
    // "Yol GERÇEKTEN ölü mü" ölçütü: spawn'ın durması iki farklı sebepten olabilir —
    // yol boş (kurtarılmalı) ya da yol dolu (kurtarılMAmalı). Ayırt eden budur.
    // Oyuncuya GÖRELİ mesafe → floating origin altında rebase-invariant.
    function countObstaclesInSpawnCorridor() {
        let n = 0;
        for (const o of obstacles) {
            const d = o.position.x - player.position.x;
            if (d > 120 && d < 960) n++;
        }
        return n;
    }

    function isRegularSpawnLaneOccupied(x, lane) {
        return obstacles.some(o => {
            if (o.userData.type === 'lava_lane') return false;
            if (o.userData.type === 'snow_ice_road') return false;
            const dx = Math.abs(x - o.position.x);
            const halfLen = (o.userData.length || 4) / 2;
            const safeDistance = 80 + halfLen;
            const laneOverlap = trafficObjectOverlapsLane(o, lane, 4.0, 2.0);
            return dx < safeDistance && laneOverlap;
        });
    }

    function markLevelPatternObstacle(obstacle, concept, row, slot, seed) {
        if (!obstacle) return null;
        obstacle.userData = {
            ...obstacle.userData,
            levelPattern: concept,
            levelPatternRow: row,
            levelPatternSlot: slot,
            levelPatternSeed: seed,
            // Campaign traffic keeps the authored lane. Endless traffic still
            // owns the dynamic lane-change AI, while a replayed level remains
            // the same readable challenge every time.
            levelPatternLaneLocked: isTrafficObjectType(obstacle.userData?.type)
        };
        return obstacle;
    }

    function getLevelPatternFirstLead(level) {
        return 110 + Math.max(0, Number(level?.safeOpeningSeconds) || 0) * 8;
    }

    function getLevelPatternSeed(level, row, salt = 0) {
        let value = ((Number(level?.layoutSeed) || Math.imul(Number(level?.number) || 1, 0x9e3779b1)) >>> 0)
            ^ Math.imul((row + 1) >>> 0, 0x85ebca6b)
            ^ (salt >>> 0);
        value ^= value >>> 16;
        value = Math.imul(value, 0x7feb352d) >>> 0;
        value ^= value >>> 15;
        value = Math.imul(value, 0x846ca68b) >>> 0;
        value ^= value >>> 16;
        return value >>> 0;
    }

    function shuffleLevelPatternLanes(laneCount, random) {
        const lanes = Array.from({ length: laneCount }, (_, index) => index);
        for (let index = lanes.length - 1; index > 0; index--) {
            const swapIndex = Math.floor(random() * (index + 1));
            [lanes[index], lanes[swapIndex]] = [lanes[swapIndex], lanes[index]];
        }
        return lanes;
    }

    function getOnboardingEscapeLaneOrder(level, sectionIndex, laneCount, requestedOpenLaneCount, random) {
        // Guarantee separated escape corridors as well as adjacent pairs.
        // The six-pair cycle is deterministic for retries and visits every
        // possible pair before repeating instead of falling into left/right
        // halves for several consecutive sections.
        if (level?.onboardingLevel && laneCount === 4 && requestedOpenLaneCount === 2) {
            const pairs = [
                [0, 2], [1, 3], [0, 3],
                [1, 2], [0, 1], [2, 3]
            ];
            const levelOffset = getLevelPatternSeed(level, 0, 0x0e5ca9e) % pairs.length;
            const pair = pairs[(levelOffset + sectionIndex * 5) % pairs.length];
            const remaining = shuffleLevelPatternLanes(laneCount, random).filter((lane) => !pair.includes(lane));
            return [...pair, ...remaining];
        }
        return shuffleLevelPatternLanes(laneCount, random);
    }

    function getLevelPatternBlueprint(level, row, laneCount = lanePositions.length) {
        const safeLaneCount = Math.max(1, Math.floor(Number(laneCount) || 1));
        const seed = getLevelPatternSeed(level, row, 0x51f15e);
        const random = mulberry32(seed);
        const difficulty = Math.max(0, Math.min(1, ((Number(level?.number) || 1) - 1) / 119));
        const activeMapPhase = Math.max(0, Math.min(5, Number(
            levelMegaJumpTransition?.padTriggered ? levelMegaJumpTransition.targetPhase : gamePhase
        ) || 0));
        const cityLevel = activeMapPhase === 0;
        const openingKinds = ['slalom', 'jump', 'slide', 'walls', 'mixed'];
        const mixedKinds = ['traffic', 'mixed', 'slalom', 'jump', 'slide', 'walls', 'rush', 'traffic', 'mixed'];
        let kind;
        if (level?.concept === 'bonus') {
            kind = 'bonus';
        } else if (row < 3) {
            const offset = getLevelPatternSeed(level, 0, 0x0f3a91) % openingKinds.length;
            const step = (getLevelPatternSeed(level, 0, 0x72c4d3) & 1) ? 2 : 3;
            kind = openingKinds[(offset + row * step) % openingKinds.length];
        } else if (row >= 9 && (row - 9 - getLevelPatternSeed(level, 0, 0x6a7e) % 6) % 32 === 0) {
            // One seeded schedule for all campaign maps: 9-14 opening rows,
            // then at least 31 ordinary rows between door formations. Do not
            // also include doors in the Cyber shuffle (that doubled their rate).
            kind = 'gate';
        } else if (activeMapPhase > 0 && row >= 5 && row % 8 === 5) {
            // Trains belong to every road map, not only Cyber. The seeded row
            // cadence keeps retries identical and guarantees train gameplay in
            // Nature, Sky, Lava, Water and Snow campaign levels.
            kind = 'train';
        } else if (activeMapPhase > 0 && row >= 4 && row % 10 === 4) {
            // Traffic signals are global road rules, not a City-only prop.
            kind = 'signal';
        } else if (activeMapPhase > 0 && row >= 7 && row % 10 === 7) {
            // The falling red wall belongs to the shared Endless vocabulary.
            kind = 'falling';
        } else if (activeMapPhase > 0 && (row - 3) % 5 === 0) {
            // Campaign rows inherit the active map's Endless-only vocabulary.
            // The schedule is seeded by row, so replaying the same level keeps
            // every special hazard at the same location.
            kind = activeMapPhase === 1 ? 'nature_hazard'
                : activeMapPhase === 2 ? 'sky_hazard'
                    : activeMapPhase === 3 ? 'lava_hazard'
                        : activeMapPhase === 4 ? 'water_hazard'
                            : 'snow_hazard';
        } else if (cityLevel && row < 6) {
            // Every short Cyber level receives the three most recognizable
            // Endless systems before its finish corridor: road traffic, a
            // train formation, and a working traffic signal. Cars/signals swap
            // per level, while the train stays third so a slow train GLB cannot
            // hold back the first two traffic rows during background loading.
            const core = ['traffic', 'signal'];
            const coreRandom = mulberry32(getLevelPatternSeed(level, 0, 0xc17c0de));
            for (let index = core.length - 1; index > 0; index--) {
                const swap = Math.floor(coreRandom() * (index + 1));
                [core[index], core[swap]] = [core[swap], core[index]];
            }
            kind = row === 5 ? 'train' : core[row - 3];
        } else if (cityLevel) {
            // This is the full City Endless obstacle vocabulary. The block is
            // reshuffled for every level and every ten-row section, making the
            // route authored/replayable without feeling like a short cycle.
            const cityKinds = ['traffic', 'rush', 'train', 'signal', 'falling', 'overhead', 'walls', 'mixed', 'jump', 'slide'];
            const block = Math.floor((row - 6) / cityKinds.length);
            const blockRandom = mulberry32(getLevelPatternSeed(level, block, 0xc17b10c));
            for (let index = cityKinds.length - 1; index > 0; index--) {
                const swap = Math.floor(blockRandom() * (index + 1));
                [cityKinds[index], cityKinds[swap]] = [cityKinds[swap], cityKinds[index]];
            }
            kind = cityKinds[(row - 6) % cityKinds.length];
        } else if (row % 4 === 3) {
            kind = (seed & 1) ? 'traffic' : 'rush';
        } else if (random() < 0.34 && level?.concept && level.concept !== 'bonus') {
            kind = level.concept;
        } else {
            kind = mixedKinds[Math.floor(random() * mixedKinds.length)];
        }

        // Rows that can overlap longitudinally share a guaranteed escape lane.
        // The safe lane changes by seeded section rather than by frame or retry.
        const sectionSpan = difficulty < 0.28 ? 6 : 4;
        const sectionIndex = Math.floor(row / sectionSpan);
        const sectionSeed = getLevelPatternSeed(level, sectionIndex, 0x5afe1a9e);
        const requestedOpenLaneCount = Math.max(1, Math.min(
            safeLaneCount,
            Number(level?.minimumOpenLanes) || 1
        ));
        // Low seed bits repeated the same 0/1 corridor for several authored
        // sections. Shuffle with an isolated deterministic RNG so the safe
        // lanes use the whole road without changing between retries.
        const escapeRandom = mulberry32((sectionSeed ^ Math.imul(sectionIndex + 1, 0x9e3779b1)) >>> 0);
        const shuffledEscapeLanes = getOnboardingEscapeLaneOrder(
            level,
            sectionIndex,
            safeLaneCount,
            requestedOpenLaneCount,
            escapeRandom
        );
        const openLanes = new Set(shuffledEscapeLanes.slice(0, requestedOpenLaneCount));
        const openLane = shuffledEscapeLanes[0] ?? 0;
        const laneOrder = shuffleLevelPatternLanes(safeLaneCount, random).filter((lane) => !openLanes.has(lane));
        const entries = [];
        const add = (type, lane, xOffset = 0, extra = null) => {
            const safeType = type === 'motorcycle' && level?.motorcyclesAllowed === false ? 'vehicle' : type;
            entries.push({ type: safeType, lane, xOffset, ...(extra || {}) });
        };
        const blockAllLanes = (type) => {
            // Jump/slide rows may teach the action in later levels. During the
            // first five, however, they always preserve the same seeded escape
            // corridor as every other formation.
            const lanes = level?.onboardingLevel ? laneOrder : Array.from({ length: safeLaneCount }, (_, lane) => lane);
            lanes.forEach((lane) => add(type, lane, 0));
        };

        if (kind === 'jump') {
            blockAllLanes('low_wall');
        } else if (kind === 'slide') {
            blockAllLanes('slide_barrier');
        } else if (kind === 'walls') {
            laneOrder.forEach((lane) => add('wall', lane));
        } else if (kind === 'slalom') {
            laneOrder.forEach((lane, slot) => add((slot + row + (seed & 1)) % 3 === 0 ? 'low_wall' : 'wall', lane, slot % 2 ? 7 : 0));
        } else if (kind === 'traffic' || kind === 'rush') {
            const count = Math.min(safeLaneCount - 1, kind === 'rush' || level.number > 12 ? 3 : 2);
            laneOrder.slice(0, Math.max(1, count)).forEach((lane, slot) => {
                const motorChance = kind === 'rush' ? 0.46 : 0.28;
                add(random() < motorChance ? 'motorcycle' : 'vehicle', lane, slot % 2 ? 10 : 0);
            });
        } else if (kind === 'train') {
            const trainRoll = random();
            const trainType = trainRoll < 0.34 ? 'train' : (trainRoll < 0.67 ? 'stopped_train' : 'static_train');
            add(trainType, laneOrder[0] ?? ((openLane + 1) % safeLaneCount), 20);
            if (laneOrder.length > 1) {
                add(random() < 0.38 ? 'motorcycle' : 'vehicle', laneOrder[1], 4);
            }
            if (difficulty > 0.42 && laneOrder.length > 2) {
                add(random() < 0.48 ? 'motorcycle' : 'vehicle', laneOrder[2], 30);
            }
        } else if (kind === 'signal') {
            add('traffic_light', openLane, 0, { signalSlot: seed % (safeLaneCount + 3) });
            const signalTrafficCount = difficulty > 0.35 ? 2 : 1;
            laneOrder.slice(0, signalTrafficCount).forEach((lane, slot) => {
                add(random() < 0.28 ? 'motorcycle' : 'vehicle', lane, 10 + slot * 9);
            });
        } else if (kind === 'falling') {
            add('falling_wall', laneOrder[0] ?? ((openLane + 1) % safeLaneCount), 0);
            if (laneOrder.length > 1) add(random() < 0.35 ? 'motorcycle' : 'vehicle', laneOrder[1], 18);
            if (difficulty > 0.55 && laneOrder.length > 2) add('low_wall', laneOrder[2], 8);
        } else if (kind === 'gate') {
            add('gate_cluster', openLane, 0);
        } else if (kind === 'overhead') {
            // A high beam can span several lanes and is passed by sliding, so
            // it remains a single formation instead of pairing incompatible
            // jump/avoid requirements at the same X coordinate.
            add('high_beam', openLane, 0);
        } else if (kind === 'nature_hazard') {
            add('rising_rock', laneOrder[0] ?? ((openLane + 1) % safeLaneCount), 0);
            if (difficulty > 0.28 && laneOrder.length > 1) add('low_wall', laneOrder[1], 12);
        } else if (kind === 'sky_hazard') {
            add('sky_sweeper', openLane, 0);
        } else if (kind === 'lava_hazard') {
            if ((seed & 1) === 0) add('energy_plasma', openLane, 0);
            else add('lava_lane', laneOrder[0] ?? openLane, 0);
        } else if (kind === 'water_hazard') {
            add('energy_plasma', openLane, 0);
            if (difficulty > 0.5 && laneOrder.length) add('low_wall', laneOrder[0], 20);
        } else if (kind === 'snow_hazard') {
            // Keep the signature ice patch rare: once near the opening and
            // then only after six Snow-special rows in very long levels.
            const snowHazardIndex = Math.max(0, Math.floor((row - 3) / 5));
            if (snowHazardIndex % 6 === 0) add('snow_ice_road', openLane, 0);
            else add('snow_falling_ball', laneOrder[0] ?? openLane, 0);
        } else if (kind === 'mixed') {
            const staticOnly = row < 3;
            let trainPlaced = false;
            laneOrder.forEach((lane, slot) => {
                const selector = Math.floor(random() * (staticOnly ? 3 : (cityLevel ? 8 : 5)));
                let type = selector === 0 ? 'wall'
                    : selector === 1 ? 'low_wall'
                        : selector === 2 ? 'slide_barrier'
                            : selector === 3 ? 'vehicle'
                                : selector === 4 ? 'motorcycle'
                                    : selector === 5 ? 'falling_wall'
                                        : selector === 6 ? 'stopped_train'
                                            : 'static_train';
                if (isTrainLikeTrafficType(type)) {
                    if (trainPlaced) type = random() < 0.35 ? 'motorcycle' : 'vehicle';
                    else trainPlaced = true;
                }
                add(type, lane, slot % 2 ? 6 : 0);
            });
        }

        const spacingBase = {
            bonus: 58,
            traffic: 64,
            rush: 60,
            train: 126,
            signal: 62,
            falling: 66,
            gate: 118,
            overhead: 66,
            jump: 62,
            slide: 64,
            walls: 58,
            slalom: 56,
            mixed: 60,
            nature_hazard: 72,
            sky_hazard: 132,
            lava_hazard: 82,
            water_hazard: 82,
            snow_hazard: entries.some((entry) => entry.type === 'snow_ice_road') ? 470 : 94
        }[kind] || 60;
        const spacingScale = Math.max(0.58, Math.min(1.45, Number(level?.patternSpacingScale) || 1));
        const minimumGap = kind === 'train' ? 96
            : (entries.some((entry) => entry.type === 'snow_ice_road') ? 450 : 46);
        const gap = Math.max(minimumGap, Math.round(spacingBase * spacingScale + random() * 7));
        const coinCount = kind === 'bonus' ? 7 : (((row + (Number(level?.number) || 1)) % 3 === 0) ? 4 : 0);
        return {
            level: Number(level?.number) || 1,
            row,
            seed,
            mapPhase: activeMapPhase,
            kind,
            openLane,
            gap,
            coinCount,
            entries
        };
    }

    function withDeterministicLevelPatternRandom(seed, callback) {
        const previousRandom = Math.random;
        const previousContext = levelPatternSpawnContext;
        Math.random = mulberry32(seed >>> 0);
        levelPatternSpawnContext = { forceExact: true, seed: seed >>> 0 };
        try {
            return callback();
        } finally {
            levelPatternSpawnContext = previousContext;
            Math.random = previousRandom;
        }
    }

    function spawnLevelPatternObstacle(level, blueprint, entry, slot, spawnX) {
        const seed = getLevelPatternSeed(level, blueprint.row, blueprint.seed ^ Math.imul(slot + 1, 0x9e3779b1));
        const obstacle = withDeterministicLevelPatternRandom(seed, () => {
            if (entry.type === 'traffic_light') {
                const separators = getLaneSeparators();
                const wallPositions = [getBarrierPositionZ(-1), getBarrierPositionZ(1)];
                const spots = [...separators, ...wallPositions];
                const selectedZ = spots[(Number(entry.signalSlot) || 0) % Math.max(1, spots.length)] ?? 0;
                const onWall = Number(level?.themePhase) === 0 && wallPositions.includes(selectedZ);
                const before = obstacles.length;
                createTrafficLight(spawnX + entry.xOffset, selectedZ, onWall, (seed & 1) ? 'left' : 'right');
                return obstacles.length > before ? obstacles[obstacles.length - 1] : null;
            }
            if (entry.type === 'snow_falling_ball') {
                const before = obstacles.length;
                createObstacle(entry.type, spawnX + entry.xOffset, entry.lane);
                const snowball = obstacles.length > before ? obstacles[obstacles.length - 1] : null;
                if (snowball?.userData?.type === 'snow_falling_ball') {
                    const dropPlan = getSnowballWallStyleDropPlan();
                    snowball.userData.phase = 'waiting';
                    snowball.userData.activationDistance = dropPlan.lead;
                    snowball.userData.fallSpeed = dropPlan.fallSpeed;
                    snowball.userData.ballGroup.position.y = snowball.userData.fallStartY;
                    setSnowFallingBallVisualAlpha(snowball.userData, 0, 0);
                }
                return snowball;
            }
            return createObstacle(entry.type, spawnX + entry.xOffset, entry.lane);
        });
        if (!obstacle) return null;
        markLevelPatternObstacle(obstacle, blueprint.kind, blueprint.row, slot, blueprint.seed);
        if (isTrafficObjectType(obstacle.userData?.type)) {
            const lane = lanePositions[Math.max(0, Math.min(lanePositions.length - 1, entry.lane))];
            obstacle.position.z = lane;
            obstacle.userData.lane = lane;
            obstacle.userData.targetLane = lane;
            obstacle.userData.laneChanging = false;
        }
        return obstacle;
    }

    function spawnLevelPatternBlueprint(level, blueprint, spawnX) {
        if (blueprint.entries.some((entry) => entry.type === 'gate_cluster')) {
            const before = obstacles.length;
            withDeterministicLevelPatternRandom(blueprint.seed ^ 0x6a7e5eed, () => spawnGateCluster(spawnX));
            const createdGateParts = obstacles.slice(before);
            if (!createdGateParts.length) return false;
            createdGateParts.forEach((obstacle, slot) => markLevelPatternObstacle(obstacle, blueprint.kind, blueprint.row, slot, blueprint.seed));
            return true;
        }
        const trafficEntries = blueprint.entries.filter((entry) => isTrafficSpawnType(entry.type));
        if (trafficEntries.some((entry) => !isTrafficVisualReadyForSpawn(entry.type))) return false;

        const created = [];
        for (let slot = 0; slot < blueprint.entries.length; slot++) {
            const obstacle = spawnLevelPatternObstacle(level, blueprint, blueprint.entries[slot], slot, spawnX);
            if (!obstacle) {
                for (let index = created.length - 1; index >= 0; index--) {
                    const obstacleIndex = obstacles.indexOf(created[index]);
                    if (obstacleIndex >= 0) removeObstacleAt(obstacleIndex);
                }
                return false;
            }
            created.push(obstacle);
        }

        if (blueprint.coinCount > 0 && player && coinPrototype) {
            const laneIndex = Math.max(0, Math.min(lanePositions.length - 1, blueprint.openLane));
            const coinStartX = spawnX - Math.max(18, (blueprint.coinCount - 1) * GROUND_COIN_LINE_SPACING + 4);
            const liveGroundCoins = coins.reduce((count, coin) => count + (coin?.userData?.isGroundCoinLine && coin.parent === scene ? 1 : 0), 0);
            if (liveGroundCoins <= 48 && canPlaceGroundCoinLine(coinStartX, laneIndex, blueprint.coinCount)) {
                withDeterministicLevelPatternRandom(blueprint.seed ^ 0xc01d5eed, () => {
                    spawnGroundCoinLine(coinStartX, laneIndex, blueprint.coinCount);
                });
            }
        }
        return true;
    }

    function spawnActiveLevelPattern(spawnLimitX) {
        const level = getActiveLevelTuning();
        if (!level || !levelSystem?.isActive?.() || !player) return false;
        if (levelMegaJumpTransition) {
            if (!levelMegaJumpTransition.padTriggered || !onSkyLayer) return true;
            if (!levelMegaJumpTransition.resumed) {
                levelMegaJumpTransition.resumed = true;
                nextLevelPatternX = player.position.x + 170;
                beginShadowStabilization(MOBILE_RUNTIME ? 3 : 5, 'level-mega-jump-landed');
            }
        }
        if (!Number.isFinite(nextLevelPatternX)) nextLevelPatternX = player.position.x + getLevelPatternFirstLead(level);
        if (nextLevelPatternX > spawnLimitX) return true;

        const row = levelPatternSerial;
        const blueprint = getLevelPatternBlueprint(level, row);
        if (!spawnLevelPatternBlueprint(level, blueprint, nextLevelPatternX)) return true;
        lastLevelPatternSpawnX = nextLevelPatternX;
        nextLevelPatternX += blueprint.gap;
        levelPatternSerial += 1;
        return true;
    }

    function spawnManager() {
        if (isGameOver) return;
        if (levelSystem?.isFinishArmed?.()) return;
        if (lavaDropTransitionActive && !lavaMapActivated) return;
        if (isSkyNoGameplaySpawnActive()) return;

        // Campaign levels use an authored deterministic stream. Keeping this
        // branch ahead of the endless-run random hazards guarantees that the
        // same level number rebuilds the same obstacle types, lanes and world
        // coordinates on every replay. Bonus levels are represented by seeded
        // coin rows inside the same stream.
        if (levelSystem?.isActive?.()) {
            const level = getActiveLevelTuning();
            const difficulty = Math.max(0, Math.min(1, ((Number(level?.number) || 1) - 1) / 119));
            spawnActiveLevelPattern(player.position.x + 520 + difficulty * 90);
            return;
        }

        // --- MEGA JUMP GEÃ‡Ä°ÅÄ° ---
        const SKY_TARGET = SKY_SCORE;

        if (gamePhase === 2 && score >= SKY_TARGET && !megaJumpSpawned) {
            createMegaJumpPad(player.position.x + 600);
            megaJumpSpawned = true;
            return; 
        }

        if (gamePhase === 2 && megaJumpSpawned && !onSkyLayer) {
            return; 
        }
        // -------------------------

        // HAVADAYSAK KORUMA DUVARLARI
        if (onSkyLayer && Math.random() < 0.1) {
             // GÃ¶kyÃ¼zÃ¼nde kenarlara dÃ¼ÅŸmemek iÃ§in bariyer atÄ±labilir veya boÅŸ bÄ±rakÄ±labilir
        }

        // DÃ–NER ENGEL â€” hava, lav ve su mapinde
        if (isSweeperPhaseActive()) {
            if (nextSkySweeperSpawnX < player.position.x + 420) {
                nextSkySweeperSpawnX = player.position.x + (onSkyLayer ? 640 : 760) + Math.random() * 120;
            }
            if (nextSkySweeperSpawnX <= player.position.x + (onSkyLayer ? 1020 : 900)) {
                const scheduledX = nextSkySweeperSpawnX;
                const sweeperX = findSkySweeperSpawnX(scheduledX, getSweeperFloorY());
                if (sweeperX !== null) {
                    const spawnChance = onSkyLayer ? 0.68 : 0.4;
                    nextSkySweeperSpawnX = sweeperX + (onSkyLayer ? 560 : 700) + Math.random() * (onSkyLayer ? 160 : 220);
                    if (Math.random() < spawnChance) {
                        createObstacle('sky_sweeper', sweeperX, 0);
                        if (onSkyLayer) {
                            spawnSkySweeperEscortObstacles(sweeperX);
                        }
                    }
                    return;
                }
                nextSkySweeperSpawnX = scheduledX + 260;
            }
        }

        const reservedSkySweeperX = getScheduledSweeperSpawnX();

        if (gamePhase >= 3 && !lavaDropTransitionActive) {
            if (nextLavaPlasmaX < player.position.x + 220) {
                nextLavaPlasmaX = player.position.x + 320 + Math.random() * 160;
            }
            if (nextLavaPlasmaX <= player.position.x + 520) {
                if (isXReservedForScheduledSweeper(nextLavaPlasmaX, 300)) {
                    nextLavaPlasmaX += 170;
                } else if (canPlaceEnergyPlasmaAt(nextLavaPlasmaX)) {
                    createObstacle('energy_plasma', nextLavaPlasmaX, 0);
                    nextLavaPlasmaX += 540 + Math.random() * 220;
                } else {
                    nextLavaPlasmaX += 140;
                }
            }

            if (gamePhase < 5) {
                if (nextLavaLaneHazardX < player.position.x + 140) {
                    nextLavaLaneHazardX = player.position.x + 220 + Math.random() * 120;
                }
                if (nextLavaLaneHazardX <= player.position.x + 340) {
                    const hasLiveLavaLane = obstacles.some(o => o.userData && o.userData.type === 'lava_lane');
                    if (!hasLiveLavaLane) {
                        const edgeSafeLaneCount = lanePositions.length;
                        const laneIdx = edgeSafeLaneCount > 2
                            ? (1 + Math.floor(Math.random() * (edgeSafeLaneCount - 2)))
                            : Math.floor(Math.random() * edgeSafeLaneCount);
                        const lane = lanePositions[laneIdx];
                        if (isXReservedForScheduledSweeper(nextLavaLaneHazardX, 330)) {
                            nextLavaLaneHazardX += 140;
                        } else if (canPlaceLavaLaneHazardAt(nextLavaLaneHazardX, lane)) {
                            createObstacle('lava_lane', nextLavaLaneHazardX, laneIdx);
                            nextLavaLaneHazardX += 420 + Math.random() * 180;
                            return;
                        }
                        nextLavaLaneHazardX += 90;
                    } else {
                        nextLavaLaneHazardX = Math.max(nextLavaLaneHazardX, player.position.x + 140);
                    }
                } else {
                    nextLavaLaneHazardX = Math.max(nextLavaLaneHazardX, player.position.x + 140);
                }
            } else {
                nextLavaLaneHazardX = Math.max(nextLavaLaneHazardX, player.position.x + 1200);
            }
        }

        if (gamePhase >= 5 && snowMapActivated) {
            if (!isXReservedForScheduledSweeper(nextSnowballX, 310) && trySpawnSnowballHazard()) return;
            if (!isXReservedForScheduledSweeper(nextSnowIceRoadX, 430) && trySpawnSnowIceRoadHazard()) return;
        }

        if (onSkyLayer && Math.random() < 0.18) {
            const fanX = player.position.x + 800 + Math.random() * 200;
            const noFanNearby = !windFans.some(f => Math.abs(f.position.x - fanX) < 300);
            const reservedForSweeper = nextSkySweeperSpawnX > player.position.x && Math.abs(fanX - nextSkySweeperSpawnX) < 220;
            const nearLiveSweeper = obstacles.some(o => o.userData && o.userData.type === 'sky_sweeper' && Math.abs(o.position.x - fanX) < 340);
            if (noFanNearby && !reservedForSweeper && !nearLiveSweeper) {
                const side = Math.random() > 0.5 ? 1 : -1;
                createWindFan(fanX, side);
            }
        }

        if (Math.random() < 0.008) {
            const sX = player.position.x + 350 + Math.random() * 50; 
            const sLane = lanePositions[Math.floor(Math.random() * lanePositions.length)];
            const yPos = onSkyLayer ? SKY_LAYER_Y + 2.5 : 2.5;
            if (!(reservedSkySweeperX !== null && Math.abs(sX - reservedSkySweeperX) < 180)) {
                const shield = createShieldMesh(); shield.position.set(sX, yPos, sLane); scene.add(shield); powerups.push(shield);
            }
        }

        if (!megaJumpSpawned && Math.random() < 0.035 && player.position.x - lastJumpPadSpawnX > 1500) { 
            const jpX = player.position.x + 350 + Math.random() * 50;
            const jpLane = lanePositions[Math.floor(Math.random() * lanePositions.length)];
            if (!isXInsideTunnelRange(jpX, 110) && !obstacles.some(o => Math.abs(jpX - o.position.x) < 50)) {
                createJumpPad(jpX, jpLane);
                lastJumpPadSpawnX = jpX; 
            }
        }

        trySpawnGroundCoinLine();

        // === NEFES KAPISI ===
        // Bu satırın ÜSTÜNDE kalan her şey (coin dizisi, kalkan, zıplama pedi, faza özel
        // hazard'lar) nefes sırasında da akmaya devam eder — nefes "boş ekran" değil,
        // "coin toplayıp soluklanma" anıdır. Susturulan yalnızca DÜZENLİ engel akışıdır;
        // taban ölçümü geç fazların %60-87'sinin düz trafik olduğunu gösterdi, yani asıl
        // baskıyı yapan da bu akış. Hazard'lar kendi X imleçleriyle sürer (faz kimliği bozulmasın).
        // rhythmDrySec tavanı updateSpawnRhythm'de nefesi zorla kesiyor → kapı kilitlenemez.
        if (rhythmMode === 'breather') return;

        // Bring only the opening wave into readable view sooner. The lead
        // returns smoothly to the established 900-unit spacing as score rises.
        const openingLeadBlend = Math.max(0, Math.min(1, score / 1200));
        const levelDifficulty = Math.max(0, Math.min(1, ((getActiveLevelTuning()?.number || 1) - 1) / 119));
        const regularSpawnLead = levelSystem?.isActive?.()
            ? 430 + levelDifficulty * 90
            : (isBrowserBuild() ? 560 + (900 - 560) * openingLeadBlend : 900);
        const regularSpawnX = player.position.x + regularSpawnLead;
        // Henüz doğmamış (rezerve) süpürge de canlı olanla AYNI yasak yarıçapını kullanmalı;
        // ayrışırsa biri diğerinden geniş blokladığı için ölü bölge sessizce büyür.
        if (reservedSkySweeperX !== null && Math.abs(regularSpawnX - reservedSkySweeperX) < SKY_SWEEPER_BLOCK_RANGE_X) return;
        let laneIdx = Math.floor(Math.random() * lanePositions.length);
        let lane = lanePositions[laneIdx];

        // ÖLÜ KORİDOR KURTARMASI — taban ölçümünde Nature 674m / Sky 713m / Water 791m
        // (≈20-22sn) hiç engelsiz koridorlar vardı. Kök neden: her tick TEK rastgele şerit
        // seçiliyor, o şerit doluysa fonksiyon dönüyor; sıkışık trafikte bu üst üste binince
        // yol dakikalarca boş kalabiliyor. Uzun sessizlikte tek şeride küsmek yerine
        // şeritleri sırayla dene. Burada YALNIZ şerit seçimi değişir — mustLeaveOpen,
        // süpürge rezervi, water cap ve coin guard'ları aşağıda aynen uygulanır.
        if (rhythmDrySec > getRhythmMaxDrySec() && countObstaclesInSpawnCorridor() <= RHYTHM_RESCUE_MAX_AHEAD) {
            for (let k = 1; k < lanePositions.length; k++) {
                if (!isRegularSpawnLaneOccupied(regularSpawnX, lane)) break;
                laneIdx = (laneIdx + 1) % lanePositions.length;
                lane = lanePositions[laneIdx];
            }
        }
        const sweeperReserved = obstacles.some(o => o.userData.type === 'sky_sweeper' && Math.abs(regularSpawnX - o.position.x) < (o.userData.blockRangeX || 180));
        if (sweeperReserved) return;
        
        const lavaTunnelPhase = gamePhase === 3 && lavaMapActivated && !waterMapActivated && !lavaDropTransitionActive;
        let tunnelChance = 0.004;
        let tunnelSpacing = 1000;
        if (lavaTunnelPhase) {
            tunnelChance = 0.028;
            tunnelSpacing = 1450;
        } else if (gamePhase === 1) {
            tunnelChance = NATURE_TUNNEL_CHANCE;
            tunnelSpacing = NATURE_TUNNEL_SPACING;
        } else if (gamePhase === 2) {
            tunnelChance = SKY_TUNNEL_CHANCE;
            tunnelSpacing = SKY_TUNNEL_SPACING;
        } else if (gamePhase >= 3) {
            tunnelChance = 0.0;
        }
        // Tünel bir BASKI öğesi değil ÇEVRE öğesidir; nefes kapısı yuvarlamayı atlattığı için
        // ritimsiz haline göre seyrekleşirdi (erken Nature/Sky'da ~yarıya inerdi). Şansı dalga
        // görev döngüsüne bölerek uzun vadeli tünel sıklığını değişiklik ÖNCESİYLE aynı tut.
        tunnelChance /= Math.max(0.2, getRhythmWaveDuty());

        if (regularSpawnX > activeTunnelEndX + tunnelSpacing && Math.random() < tunnelChance) {
             const len = lavaTunnelPhase ? (380 + Math.random() * 260) : (300 + Math.random() * 500);
             // Normal engellerden (regularSpawnX=900) çok daha ileride oluştur — bu fazlarda sis seyrek
             // olduğundan 900'de dev tünel oyuncunun gözü önünde beliriyordu (aniden "spawn" görünüyordu).
             const tunnelSpawnX = player.position.x + TUNNEL_SPAWN_LEAD;
             createTunnel(tunnelSpawnX, len);
             activeTunnelEndX = tunnelSpawnX + len * TUNNEL_LENGTH_MULTIPLIER;
             return;
        }

        if (Math.random() < 0.035 && lastObstacleType !== 'traffic_light') { 
            const linePositions = getLaneSeparators(); 
            const wallPositions = [getBarrierPositionZ(-1), getBarrierPositionZ(1)]; 
            const allSpots = [...linePositions, ...wallPositions];
            let selectedZ = allSpots[Math.floor(Math.random() * allSpots.length)];
            
            if (gamePhase >= 1 && (Math.abs(selectedZ) > 10)) selectedZ = 0; 
            const onWall = (gamePhase === 0) && wallPositions.includes(selectedZ); 
            
            createTrafficLight(regularSpawnX, selectedZ, onWall, 'right'); 
            lastObstacleType = 'traffic_light'; 
            lastObstacleX = regularSpawnX; 
            return; 
        }

        const isOccupied = isRegularSpawnLaneOccupied(regularSpawnX, lane);
        const isOccupiedByWaterCap = gamePhase >= 4 && waterBounceCaps.some(cap => {
            if (!cap || !cap.userData) return false;
            const dx = Math.abs(regularSpawnX - cap.position.x);
            const dz = Math.abs(lane - cap.position.z);
            const safeDistance = 85 + ((cap.userData.length || 11.8) * 0.5);
            return dx < safeDistance && dz < ((cap.userData.widthZ || 11.8) * 0.5 + 2.0);
        });
        const isOccupiedByGroundCoin = hasGroundCoinNearLane(regularSpawnX, lane, 10, 6.8);
        
        if (isOccupied || isOccupiedByWaterCap || isOccupiedByGroundCoin) return;

        const blockedLanesCount = lanePositions.filter(l => l !== lane && checkLaneIsBlocked(l, regularSpawnX)).length;
        const mustLeaveOpen = blockedLanesCount >= lanePositions.length - 1; 
        
        let chosenType = null;
        let attempt = 0;
        
        if (gamePhase >= 1 && Math.random() < 0.012) { 
            chosenType = 'gate_cluster';
        } else {
            do {
                const r = Math.random();
                
                // Nature+ fazlarında wall_type = rising_rock; sıklığı hafif artırıldı (%6→%9), City duvarı %6 kalır
                if (r > (gamePhase >= 1 ? 0.91 : 0.94)) chosenType = 'wall_type';
                else if (r > 0.88) chosenType = 'low_wall_type';
                else if (r > 0.82) chosenType = 'high_beam';
                else if (r > 0.76) chosenType = 'slide_barrier';
                else if (r > 0.70) chosenType = 'falling_wall';
                else if (r > 0.53) chosenType = 'train_type';
                else chosenType = 'vehicle';

                if (mustLeaveOpen) {
                    if (['wall_type', 'falling_wall', 'train_type', 'gate_cluster'].includes(chosenType)) chosenType = 'vehicle'; 
                }
                attempt++;
            } while (
                (chosenType === lastObstacleType && attempt < 20) ||
                (gamePhase >= 1 && chosenType === 'low_wall_type' && attempt < 20)
            );
        }
        
        if (gamePhase >= 1 && chosenType === 'low_wall_type') chosenType = 'vehicle';

        // PLAY can be pressed while detailed traffic is still streaming. Avoid
        // both obsolete fallback models and empty spawn slots during that window.
        if (chosenType === 'train_type' && !isTrafficVisualReadyForSpawn('train')) {
            chosenType = resolveReadyTrafficSpawnType('train') ? 'vehicle' : 'low_wall_type';
        }
        if (chosenType === 'vehicle'
            && !isTrafficVisualReadyForSpawn('car')
            && !isTrafficVisualReadyForSpawn('motorcycle')) {
            chosenType = 'low_wall_type';
        }

        if (chosenType === 'gate_cluster') {
            spawnGateCluster(regularSpawnX);
            lastObstacleType = 'gate_cluster';
            lastObstacleX = regularSpawnX;
            return; 
        }

        let sequenceBaseLaneIdx = laneIdx;
        let sequencePrimaryChoice = chosenType;
        let primaryCreated = true;
        let sequenceBaseX = regularSpawnX;

        if (chosenType === 'wall_type') {
            if (gamePhase === 0) {
                const createdWall = createObstacle('wall', regularSpawnX, laneIdx);
                primaryCreated = !!createdWall;
                if (createdWall) sequenceBaseX = createdWall.position.x;
            } else {
                const createdRock = createObstacle('rising_rock', regularSpawnX, laneIdx);
                primaryCreated = !!createdRock;
                if (createdRock) sequenceBaseX = createdRock.position.x;
            }
        }
        else if (chosenType === 'low_wall_type') {
            const createdLowWall = createObstacle('low_wall', regularSpawnX, laneIdx);
            primaryCreated = !!createdLowWall;
            if (createdLowWall) sequenceBaseX = createdLowWall.position.x;
        }
        else if (chosenType === 'train_type') {
            const trainR = Math.random();
            if (gamePhase === 0) {
                let createdTrain = null;
                if (trainR > 0.75) createdTrain = createObstacle('static_train', regularSpawnX, laneIdx);
                else if (trainR > 0.45) createdTrain = createObstacle('stopped_train', regularSpawnX, laneIdx);
                else createdTrain = createObstacle('train', regularSpawnX, laneIdx);
                primaryCreated = !!createdTrain;
                if (createdTrain) {
                    sequenceBaseLaneIdx = getClosestLaneIndexForZ(createdTrain.position.z);
                    sequenceBaseX = createdTrain.position.x;
                    trySpawnExtraTrain(createdTrain.position.x, sequenceBaseLaneIdx);
                }
            } else {
                let createdTrain = null;
                if (trainR > 0.70) createdTrain = createObstacle('static_train', regularSpawnX, laneIdx); 
                else if (trainR > 0.40) createdTrain = createObstacle('stopped_train', regularSpawnX, laneIdx); 
                else createdTrain = createObstacle('train', regularSpawnX, laneIdx);
                primaryCreated = !!createdTrain;
                if (createdTrain) {
                    sequenceBaseLaneIdx = getClosestLaneIndexForZ(createdTrain.position.z);
                    sequenceBaseX = createdTrain.position.x;
                }
            }
        }
       else if (chosenType === 'high_beam') {
    // DÃœZELTME 1: floorY burada tanÄ±mlanarak "hiÃ§ Ã§Ä±kmama" sorunu Ã§Ã¶zÃ¼ldÃ¼
    const floorY = onSkyLayer ? SKY_LAYER_Y : 0; 
    
    const totalLanes = lanePositions.length; 
    const spanCount = Math.floor(Math.random() * Math.min(3, totalLanes - 1)) + 1;
    const maxStartIndex = totalLanes - spanCount; 
    const startIdx = Math.floor(Math.random() * (maxStartIndex + 1));
    const startZ = lanePositions[startIdx]; 
    const endZ = lanePositions[startIdx + spanCount - 1];
    
    const beamPos = (startZ + endZ) / 2; 
    const beamWidth = (spanCount * 7.0) - 0.5; 
    const h = 10.0; 
    
    // DÃœZELTME 2: YÃ¼kseklik 14.2 yapÄ±ldÄ±.
    // Tren (6.5) + Kayma (1.8) = 8.3 (GeÃ§er)
    // Tren (6.5) + Ayakta (3.0) = 9.5 (Ã‡arpar)
    // Engel AltÄ± = 14.2 - 5.0 = 9.2
    const yPos = floorY + 14.2; 
    
    const obs = createDetailedHighBeam(beamWidth, h);
    obs.position.set(regularSpawnX, yPos, beamPos);
    
    obs.userData = { speedX: 0, length: 2.5, height: h, type: 'high_beam', widthZ: beamWidth }; 
    obs.castShadow = true; 
    obs.receiveShadow = true; 
    scene.add(obs); 
    obstacles.push(obs);
    lastObstacleType = 'high_beam';
    lastObstacleX = regularSpawnX;
    lastObstacleHadBarrier = false;
    requestShadowMapRefresh(regularSpawnX);
}
        else if (chosenType === 'slide_barrier' && !lastObstacleHadBarrier) {
            const createdSlide = createObstacle('slide_barrier', regularSpawnX, laneIdx);
            primaryCreated = !!createdSlide;
            if (createdSlide) sequenceBaseX = createdSlide.position.x;
        }
        else if (chosenType === 'falling_wall') {
             if (gamePhase >= 5 && snowMapActivated && !onSkyLayer) {
                const snowball = spawnSnowballLikeFallingWall(getPlayerLaneIndexForSnowball());
                if (snowball) {
                    nextSnowballX = Math.max(nextSnowballX, snowball.position.x + SNOWBALL_REPEAT_TRIGGER_MIN * 0.65);
                }
             } else {
                const fallingWallSpawnX = player.position.x + (20 + moveSpeed * 50);
                const isSpotTaken = isFallingWallDropZoneBlocked(fallingWallSpawnX, lanePositions[laneIdx]);
                if (!isSpotTaken) {
                    const createdFalling = createObstacle('falling_wall', fallingWallSpawnX, laneIdx);
                    primaryCreated = !!createdFalling;
                    if (createdFalling) sequenceBaseX = createdFalling.position.x;
                } else {
                    primaryCreated = false;
                }
             }
        }
        else {
            const carSpawnReady = isTrafficVisualReadyForSpawn('car');
            const motorSpawnReady = isTrafficVisualReadyForSpawn('motorcycle');
            let vehicleType = carSpawnReady && motorSpawnReady
                ? (Math.random() > 0.7 ? 'motorcycle' : 'car')
                : (carSpawnReady ? 'car' : (motorSpawnReady ? 'motorcycle' : null));
            if (!vehicleType) {
                const fallbackObstacle = createObstacle('low_wall', regularSpawnX, laneIdx);
                primaryCreated = !!fallbackObstacle;
                if (fallbackObstacle) sequenceBaseX = fallbackObstacle.position.x;
                sequencePrimaryChoice = 'low_wall_type';
                if (primaryCreated) {
                    spawnLaneScaledCompanions(sequencePrimaryChoice, sequenceBaseX, sequenceBaseLaneIdx);
                }
                return;
            }
            
            let targetLaneIdx = laneIdx;
            if (!checkLaneSafety(lanePositions[targetLaneIdx], regularSpawnX, 10)) {
                 const neighbors = [];
                 if (targetLaneIdx > 0) neighbors.push(targetLaneIdx - 1); 
                 if (targetLaneIdx < lanePositions.length - 1) neighbors.push(targetLaneIdx + 1);
                 neighbors.sort(() => Math.random() - 0.5);
                 for(let nIdx of neighbors) { 
                     if (checkLaneSafety(lanePositions[nIdx], regularSpawnX, 10) &&
                         !checkLaneIsBlocked(lanePositions[nIdx], regularSpawnX) &&
                         isTrafficSpawnAreaClear(vehicleType, regularSpawnX, lanePositions[nIdx], vehicleType === 'motorcycle' ? 4.0 : 10.0, vehicleType === 'motorcycle' ? 1.4 : 5.2)) { 
                          targetLaneIdx = nIdx; break; 
                     } 
                 }
            }
            const createdVehicle = createObstacle(vehicleType, regularSpawnX, targetLaneIdx);
            primaryCreated = !!createdVehicle;
            if (createdVehicle) {
                sequenceBaseLaneIdx = getClosestLaneIndexForZ(createdVehicle.position.z);
                sequencePrimaryChoice = 'vehicle';
                sequenceBaseX = createdVehicle.position.x;
            }
        }

        if (primaryCreated && sequencePrimaryChoice) {
            spawnLaneScaledCompanions(sequencePrimaryChoice, sequenceBaseX, sequenceBaseLaneIdx);
        }
    }

    function distanceSqToSweeperArmSegment(localX, localYMin, localYMax, localZ, segStart, segEnd, armY, dir) {
        const a = dir > 0 ? segStart : -segEnd;
        const b = dir > 0 ? segEnd : -segStart;
        const minX = Math.min(a, b);
        const maxX = Math.max(a, b);
        let dx = 0;
        if (localX < minX) dx = minX - localX;
        else if (localX > maxX) dx = localX - maxX;

        let dy = 0;
        if (armY < localYMin) dy = localYMin - armY;
        else if (armY > localYMax) dy = armY - localYMax;

        return (dx * dx) + (dy * dy) + (localZ * localZ);
    }

    function checkSkySweeperCollision(o, actualPhysicsHeight, delta) {
        const relX = player.position.x - o.position.x;
        const relZ = player.position.z - o.position.z;

        // updatePlayer runs before updateObstacles in the frame, so we sample
        // the sweeper using the pose that will actually be rendered this tick.
        const predictedAngle = (o.userData.sweepAngle || o.rotation.y || 0) + ((o.userData.rotSpeed || 0) * Math.max(0, delta || 0));
        // DÜNYA→YEREL dönüşüm (grup rotation.y=θ): lx=wx·cosθ−wz·sinθ, lz=wx·sinθ+wz·cosθ.
        // ESKİ KOD θ'yı önce negatifleyip aynı formülü uyguluyordu → çarpışma çerçevesi görsel
        // kolların AYNADAKİ yansımasında dönüyordu (yalnız 0°/90°'de çakışır) — "değmeden ölme /
        // değince ölmeme" hatasının nedeni buydu (2026-07-05).
        const cosA = Math.cos(predictedAngle);
        const sinA = Math.sin(predictedAngle);
        const localX = relX * cosA - relZ * sinA;
        const localZ = relX * sinA + relZ * cosA;

        const playerBottom = player.position.y - (actualPhysicsHeight / 2);
        const playerTop = player.position.y + (actualPhysicsHeight / 2);
        const playerSegMinY = playerBottom + 0.42;
        const playerSegMaxY = playerTop - 0.42;
        const playerBodyRadius = Math.min(PLAYER_WIDTH, PLAYER_DEPTH) * 0.035;

        const armY = o.position.y + (o.userData.armYLocal || 0);
        const localArmY = armY - o.position.y;
        const localPlayerMinY = playerSegMinY - o.position.y;
        const localPlayerMaxY = playerSegMaxY - o.position.y;
        const segStart = o.userData.armSegmentStart || ((o.userData.hubRadius || 3.2) * 0.7);
        const segEnd = o.userData.armSegmentEnd || ((o.userData.armLength || 20) * 0.5);
        const armVisualRadius = o.userData.armVisualRadius || o.userData.armRadius || 1.18;
        const armHitRadius = Math.max(0.32, o.userData.armCollisionRadius || (armVisualRadius * 0.34));
        const armLimit = armHitRadius + playerBodyRadius;
        const armDistSqA = distanceSqToSweeperArmSegment(localX, localPlayerMinY, localPlayerMaxY, localZ, segStart, segEnd, localArmY, 1);
        const armDistSqB = distanceSqToSweeperArmSegment(localX, localPlayerMinY, localPlayerMaxY, localZ, segStart, segEnd, localArmY, -1);
        const armHit = Math.min(armDistSqA, armDistSqB) <= (armLimit * armLimit);

        const hubBottom = o.position.y + 0.35;
        const hubTop = o.position.y + (o.userData.hubTopLocal || 8.8);
        const hubVisualRadius = o.userData.hubVisualRadius || o.userData.hubRadius || 3.35;
        const hubHitRadius = Math.max(1.15, o.userData.hubCollisionRadius || (hubVisualRadius * 0.42));
        const hubOverlapMin = Math.max(playerSegMinY, hubBottom);
        const hubOverlapMax = Math.min(playerSegMaxY, hubTop);
        const hubVerticalGap = (hubOverlapMax >= hubOverlapMin)
            ? 0
            : Math.min(Math.abs(playerSegMinY - hubTop), Math.abs(playerSegMaxY - hubBottom));
        const hubDist = Math.hypot(relX, relZ, hubVerticalGap);
        const hubHit = hubDist <= (hubHitRadius + playerBodyRadius * 0.45);

        return armHit || hubHit;
    }

    function updatePlayer(delta) {
        if (isGameOver) return; 
        const frameScale = currentFrameScale || getFrameScale(delta);
        updatePlayerSweepStart();
        if (noclipActive) {
            updateNoclip(delta);
            updatePlayerSweepEnd();
            return;
        }
        const elapsedTime = clock.getElapsedTime();
        if (skyTransitionInvulnTimer > 0) skyTransitionInvulnTimer -= delta;
        maxStrafeSpeed = baseMaxStrafeSpeed + (bhopCombo * 0.03); if (maxStrafeSpeed > 0.45) maxStrafeSpeed = 0.45; 
        const bhopScoreMultiplier = 1 + Math.min(BHOP_SCORE_BONUS_CAP, bhopCombo * BHOP_SCORE_BONUS_PER_COMBO);
        let rawSpeed = getStartingMoveSpeed() + (score * 0.0002); let baseSpeed = Math.min(maxMoveSpeed, rawSpeed);
        let bhopSpeedBonus = 0; if (baseSpeed >= maxMoveSpeed) { bhopSpeedBonus = bhopCombo * 0.0028; }
        if (trafficBonusTimer > 0) {
            trafficBonusTimer -= delta;
            trafficSpeedBonus = 0.12;
            if (trafficBonusTimer <= 0) {
                trafficSpeedBonus = 0;
                if (ui.speedVignette) ui.speedVignette.classList.remove('green-light-vignette');
            }
        } else { trafficSpeedBonus = 0; }
        if (trafficSpeedPenalty > 0) { trafficSpeedPenalty -= delta * 0.005; if(trafficSpeedPenalty < 0) trafficSpeedPenalty = 0; }
        
        if (jumpPadBoost > 0) {
            jumpPadBoost -= delta * 0.5; 
            if(jumpPadBoost < 0) jumpPadBoost = 0;
        }
        
        const fortuneSpeedMultiplier = Math.max(1, Number(fortuneWheelSystem?.getSpeedMultiplier?.()) || 1);
        moveSpeed = ((baseSpeed + bhopSpeedBonus + trafficSpeedBonus + jumpPadBoost) - trafficSpeedPenalty) * fortuneSpeedMultiplier;
        if (airDashActive) moveSpeed += AIR_DASH_SPEED_BONUS * Math.max(0.45, airDashBlend);
        if (moveSpeed < 0.1) moveSpeed = 0.1;
        fortuneWheelSystem?.update?.(
            scoreRealDelta || delta,
            !tutorialDirector?.active && currentRunMode !== 'tutorial' && !levelCompletionInProgress
        );
        score += moveSpeed * SCORE_RATE_PER_SPEED * (scoreRealDelta || delta) * bhopScoreMultiplier * getScoreMultiplier();
        if (levelSystem && typeof levelSystem.update === 'function' && levelSystem.isActive?.()) {
            if (levelMegaJumpTransition && !levelMegaJumpTransition.resumed) {
                // Travel to the pad and the cinematic ascent do not consume
                // the Sky half of the level. Move scoreBase with the global
                // score so the campaign progress remains exactly at midpoint
                // until the player lands in the destination world.
                levelSystem.setScoreBase(score - levelMegaJumpTransition.progress);
            }
            levelSystem.update({ score, coins: totalCoins, speed: moveSpeed, delta: scoreRealDelta || delta });
            if (levelCompletionInProgress) return;
        }
        updateLevelFinishTransition(scoreRealDelta || delta);
        hudTick++;
        if (hudTick % 3 === 0) {
            const currentScoreFloor = getDisplayedRunScore();
            const currentSpeedKmh = Math.floor(moveSpeed * 180);
            if (ui.currentScore) ui.currentScore.innerText = currentScoreFloor;
            if (ui.coinCount) ui.coinCount.innerText = totalCoins;
            if (ui.speedValue) ui.speedValue.innerText = currentSpeedKmh;
            checkScoreMilestoneAnim(currentScoreFloor);
            updateSpeedDangerAnim(currentSpeedKmh);
        }
        const bhopContainer = ui.bhopContainer;
        const bhopHudActive = bhopHudCombo > 0 && elapsedTime < bhopHudVisibleUntil;
        if (bhopHudActive) {
            if (bhopContainer) bhopContainer.classList.add('bhop-active');
            if (ui.bhopCount) ui.bhopCount.innerText = `x${bhopHudCombo}`;
            if (ui.bhopBonus) ui.bhopBonus.innerHTML = '';
        } else {
            if (bhopContainer) bhopContainer.classList.remove('bhop-active');
            if (elapsedTime >= bhopHudVisibleUntil) bhopHudCombo = 0;
        }
        if (jumpQueue) { jumpQueueTimer -= delta; if (jumpQueueTimer <= 0) { jumpQueue = false; if (isJumping) bhopAttemptFailed = true; } }
        if (doubleJumpCooldownTimer > 0) doubleJumpCooldownTimer = Math.max(0, doubleJumpCooldownTimer - delta);
        if (hudTick % 3 === 0) updateDoubleJumpCooldownUi();
        if (!isJumping && bhopCombo > 0 && elapsedTime - lastLandTime > bhopWindow + 0.1) { bhopCombo = 0; }
        if (!isAnimatingLane && !lavaDropTransitionActive && Math.floor(score) >= getNextLaneAdditionScore()) startLaneAddition();
        if (isSliding) {
            slideTimer -= delta; if (slideTimer <= 0) {
                isSliding = false; document.body.classList.remove('sliding'); if (ui.speedVignette) ui.speedVignette.classList.remove('sliding-vignette');
                player.position.y += (normalHeight - slideHeight) / 2; currentCameraHeight = normalHeight; 
                snapPlayerToTrainRoofIfSupported(normalHeight);
            }
        }
        if (shieldActive) { shieldTimer -= delta; if (ui.shieldTime) ui.shieldTime.innerText = shieldTimer.toFixed(1); if (ui.shieldBar) ui.shieldBar.classList.toggle('shield-warning', shieldTimer > 0 && shieldTimer < 1); if (shieldTimer <= 0) { deactivateShield(); } }
        for (let i = powerups.length - 1; i >= 0; i--) {
            const p = powerups[i]; p.rotation.y += delta * 2; p.children[0].rotation.x += delta * 3; 
            const pdx = player.position.x - p.position.x;
            const pdy = player.position.y - p.position.y;
            const pdz = player.position.z - p.position.z;
            const powerupDistSq = pdx * pdx + pdy * pdy + pdz * pdz;
            if (powerupDistSq < 16.0) { disposeNode(p); powerups.splice(i, 1); activateShield(); }
            else if (p.position.x < player.position.x - 50) { disposeNode(p); powerups.splice(i, 1); }
        }

        for (let i = jumpPads.length - 1; i >= 0; i--) {
            const p = jumpPads[i];
            
            if (p.userData.rotSpeed) {
                p.rotation.y += delta * p.userData.rotSpeed;
            }
            
            if (p.userData.particles) {
                const positions = p.userData.particles.geometry.attributes.position.array;
                const speeds = p.userData.pSpeeds;
                for(let k=0; k < speeds.length; k++) {
                    positions[k*3+1] += speeds[k]; 
                    if (positions[k*3+1] > 5.0) positions[k*3+1] = 0; 
                }
                p.userData.particles.geometry.attributes.position.needsUpdate = true;
            }

            const jumpDx = player.position.x - p.position.x;
            const jumpDz = player.position.z - p.position.z;
            const jumpDistSq = jumpDx * jumpDx + jumpDz * jumpDz;
            if (!p.userData.triggered && jumpDistSq < 6.25 && player.position.y - p.position.y < 6.0 && player.position.y - p.position.y > -1.0) {
                 p.userData.triggered = true;
                 playerVelocityY = 1.75;
                 isJumping = true;
                 resetGlideTimer();
                 jumpPadBoost = 0.25;
                 bhopCombo += 2;
                 playJumpPadSound();
                 spawnArrowEffect('blue');
                 spawnImpactRing(p.position.x, p.position.y + 0.3, p.position.z, 0x33ddff, 5.5, 0.42, 0.85);
                 scene.remove(p);
                 disposeNode(p);
                 jumpPads.splice(i, 1);
                 continue;
            }
            if (p.position.x < player.position.x - 50) {
                scene.remove(p);
                disposeNode(p);
                jumpPads.splice(i, 1);
            }
        }

        if (coinMaterial && rimMaterial && dollarMaterial) {
           const pulse = (Math.sin(elapsedTime * 4.0) * 0.5 + 0.5); 
           coinMaterial.emissiveIntensity = 0.5 + (pulse * 0.8); rimMaterial.emissiveIntensity = 0.3 + (pulse * 0.6); dollarMaterial.emissiveIntensity = 0.3 + (pulse * 0.6); 
        }
        const playerPos = player.position;
        const magnetRadius = getMagnetRadiusValue();
        const magnetRadiusSq = magnetRadius * magnetRadius;
        for (let i = coins.length - 1; i >= 0; i--) {
            const c = coins[i];
            if (c.userData.magnetized && !magnetActive) c.userData.magnetized = false; // mıknatıs bitince normal davranışa dön
            const magnetized = !!c.userData.magnetized;
            if (c.userData.rotSpeed) c.rotation.y += delta * (c.userData.rotSpeed * (magnetized ? 5.0 : 0.5));
            if (c.userData.baseY !== undefined && !magnetized) { c.position.y = c.userData.baseY + Math.sin(elapsedTime * 3 + c.userData.bobOffset) * 0.3; }
            const glow = c.userData.glowRef;
            if (glow) {
                const glowPulse = magnetized ? (1.7 + Math.sin(elapsedTime * 16 + c.userData.bobOffset) * 0.4) : (1.0 + Math.sin(elapsedTime * 5 + c.userData.bobOffset) * 0.2);
                glow.scale.set(6 * glowPulse, 6 * glowPulse, 1);
                // Keep the glow plane facing the first-person camera while its
                // position remains locked to the coin's curved rigid pivot.
                glow.rotation.y = (Math.PI / 2) - c.rotation.y;
            }
            // Dünya konumu + oyuncuya uzaklık
            if (c.parent === scene) {
                tempWorldPos.copy(c.position);
            } else {
                if (c.parent.position.x < playerPos.x - 200 || c.parent.position.x > playerPos.x + 200) { if (c.parent.position.x < playerPos.x - 100) { recycleCoin(c); coins.splice(i, 1); } continue; }
                c.getWorldPosition(tempWorldPos);
            }
            let dx = playerPos.x - tempWorldPos.x, dy = playerPos.y - tempWorldPos.y, dz = playerPos.z - tempWorldPos.z;
            let distSq = dx*dx + dy*dy + dz*dz;
            if (c.parent === scene && tempWorldPos.x < playerPos.x - 50) { recycleCoin(c); coins.splice(i, 1); continue; }
            // Mıknatıs çekimi: yarıçap içindeki coinleri oyuncuya çek (mesafeyle hızlanan çekim)
            if (magnetActive && distSq < magnetRadiusSq) {
                if (c.parent !== scene) {
                    scene.attach(c); // dünya konumunu koruyarak sahneye taşı (tren coinleri de çekilebilsin)
                    tempWorldPos.copy(c.position);
                    dx = playerPos.x - tempWorldPos.x; dy = playerPos.y - tempWorldPos.y; dz = playerPos.z - tempWorldPos.z;
                    distSq = dx*dx + dy*dy + dz*dz;
                }
                if (!c.userData.magnetized) { c.userData.magnetized = true; playMagnetLockSound(); }
                const dist = Math.sqrt(distSq) || 0.0001;
                const closeness = 1 - Math.min(1, dist / magnetRadius);
                const step = Math.min(dist, MAGNET_PULL_SPEED * (0.9 + closeness * 2.6) * delta);
                const inv = step / dist;
                c.position.x += dx * inv; c.position.y += dy * inv; c.position.z += dz * inv;
                tempWorldPos.copy(c.position);
                dx = playerPos.x - tempWorldPos.x; dy = playerPos.y - tempWorldPos.y; dz = playerPos.z - tempWorldPos.z;
                distSq = dx*dx + dy*dy + dz*dz;
            }
            const collectRadiusSq = c.userData.magnetized ? 40.0 : 16.0;
            if (distSq < collectRadiusSq) {
                const coinValue = getCoinPickupValue();
                recycleCoin(c); coins.splice(i, 1); totalCoins += coinValue; playCoinSound(); playCoinCollectAnim();
                noteDailyMissionEvent('collectCoins', coinValue);
            }
        }
        const targetHeight = isSliding ? slideHeight : normalHeight; currentCameraHeight += (targetHeight - currentCameraHeight) * 12.0 * delta;
        const targetSlideTilt = isSliding ? -0.2 : 0; currentSlideTilt += (targetSlideTilt - currentSlideTilt) * 10.0 * delta;
        
        const forward = tempForward.set(0, 0, -1).applyAxisAngle(tempUp, yaw);
        let scaleFactor = 1;
        if (Math.abs(forward.x) > 0.01) {
            scaleFactor = 1 / Math.abs(forward.x);
            scaleFactor = Math.min(scaleFactor, 2.5); 
        }
        forward.multiplyScalar(scaleFactor);
        player.position.addScaledVector(forward, moveSpeed * frameScale);
        updatePlayerSweepEnd();
        if (
            currentRunMode === 'level'
            && levelFinishGate
            && player.position.x >= levelFinishX
            && levelSystem?.isFinishArmed?.()
        ) {
            levelSystem.crossFinish({ score, coins: totalCoins });
            if (levelCompletionInProgress) return;
        }

        // RÃ¼zgar fanÄ± etkisi
        if (windPushTimer > 0) {
            windPushTimer -= delta;
            player.position.z += activeWindPush * delta * 18;
            // Renk efekti
            const vign = ui.speedVignette;
            if (activeWindPush > 0) { vign.classList.add('green-light-vignette'); }
            else { vign.classList.add('red-light-vignette'); }
        } else {
            activeWindPush = 0;
            const vign = ui.speedVignette;
            vign.classList.remove('green-light-vignette');
            vign.classList.remove('red-light-vignette');
        }

        // Fan gÃ¼ncelle
        for (let i = windFans.length - 1; i >= 0; i--) {
            const fan = windFans[i];
            const ud  = fan.userData;
            const wl  = ud.windLines;

            if (wl) {
                const pos      = wl.geometry.attributes.position.array;
                const speeds   = ud.pSpeeds;
                const side     = ud.side;
                const moveDir  = side > 0 ? -1 : 1;
                const streakLen = ud.streakLen;
                const zFrom    = ud.zFrom;
                const zTo      = ud.zTo;
                const xMin     = ud.xMin;
                const xMax     = ud.xMax;
                const yMin     = ud.yMin;
                const yMax     = ud.yMax;

                for (let k = 0; k < speeds.length; k++) {
                    const step = moveDir * speeds[k] * delta;
                    pos[k*6+2] += step;
                    pos[k*6+5] += step;

                    // KarÅŸÄ± kenara ulaÅŸÄ±nca fanÄ±n Ã§Ä±ktÄ±ÄŸÄ± kenara geri sar
                    const out = side > 0
                        ? pos[k*6+2] < zTo
                        : pos[k*6+2] > zTo;

                    if (out) {
                        const x    = xMin + Math.random() * (xMax - xMin);
                        const y    = yMin + Math.random() * (yMax - yMin);
                        const zNew = zFrom + moveDir * (-1) * Math.random() * 4; // baÅŸa yakÄ±n
                        pos[k*6]   = x;
                        pos[k*6+1] = y;
                        pos[k*6+2] = zNew;
                        pos[k*6+3] = x;
                        pos[k*6+4] = y;
                        pos[k*6+5] = zNew + (side > 0 ? -streakLen : streakLen);
                    }
                }
                wl.geometry.attributes.position.needsUpdate = true;

                const distX = Math.abs(fan.position.x - player.position.x);
                const nearFade = 1 - Math.min(1, Math.max(0, (distX - 110) / 420));
                wl.material.opacity = 0.02 + nearFade * (ud.baseOpacity || 0.12);
            }

            // Oyuncu rüzgar alanındaysa it. NOT (floating origin): ud.xMin/xMax spawn-anı
            // absolüt X'i — rebase edilmiyor, oysa player.x -10'a pinli ve fan sahneyle
            // birlikte kayıyor → bu sabitlere karşı test HİÇ tutmuyordu (itme çalışmıyordu).
            // Tespit rebase-değişmez olsun diye fanın GÜNCEL position.x'ine göre yapılır.
            // (xMin/xMax yalnız streak-buffer geri-dönüşümünde kalır; orası obje rebase'iyle
            //  tutarlı olduğundan dokunulmaz.)
            const halfWindX = (ud.xMax - ud.xMin) * 0.5;
            const inWindX = Math.abs(player.position.x - fan.position.x) <= halfWindX;
            const inWindZ = player.position.z >= ud.windZoneMin && player.position.z <= ud.windZoneMax;

            if (inWindX && inWindZ) {
                if (elapsedTime - lastWindGustAt > 0.4) {
                    playWindGustSound();
                    lastWindGustAt = elapsedTime;
                }
                activeWindPush = ud.windDir;
                windPushTimer  = 0.15;
            }

            // Temizle
            if (fan.position.x < player.position.x - 300) {
                if (wl) {
                    scene.remove(wl);
                    wl.geometry.dispose();
                    wl.material.dispose();
                }
                scene.remove(fan);
                windFans.splice(i, 1);
                const obsIdx = obstacles.indexOf(fan);
                if (obsIdx !== -1) obstacles.splice(obsIdx, 1);
            }
        }

        const activeSnowIceRoad = getActiveSnowIceRoadUnderPlayer();
        snowIceRoadUnderPlayer = !!activeSnowIceRoad && !isJumping;

        let targetVelocity = 0;
        if (CONTROL_ACTION_STATE.moveLeft) targetVelocity = -maxStrafeSpeed;
        if (CONTROL_ACTION_STATE.moveRight) targetVelocity = maxStrafeSpeed;
        if (Math.abs(gamepadMoveInput) > 0.01) targetVelocity = gamepadMoveInput * maxStrafeSpeed;
        if (MOBILE_RUNTIME && mobileControlsVisible) {
            if (isMobilePortraitLayout() && mobilePortraitTargetZ !== null) {
                const laneDelta = mobilePortraitTargetZ - player.position.z;
                targetVelocity = Math.sign(laneDelta) * maxStrafeSpeed * Math.min(1.45, Math.max(0.6, Math.abs(laneDelta) / Math.max(1, LANE_WIDTH * 0.45)));
            } else if (!isMobilePortraitLayout() && Math.abs(mobileMoveX) > 0.01) {
                targetVelocity = mobileMoveX * maxStrafeSpeed;
            }
        }
        const lookSlipDir = Math.abs(forward.z) > 0.045 ? Math.sign(forward.z) : 0;
        const iceControlScale = snowIceRoadUnderPlayer ? 0.42 : 1.0;
        const iceAccelScale = snowIceRoadUnderPlayer ? (targetVelocity !== 0 ? 0.32 : 0.08) : 1.0;
        currentStrafeVelocity += ((targetVelocity * iceControlScale) - currentStrafeVelocity) * (targetVelocity !== 0 ? strafeAccel * iceAccelScale : strafeFriction * iceAccelScale) * frameScale;
        player.position.z += currentStrafeVelocity * frameScale;
        if (isMobilePortraitLayout() && mobilePortraitTargetZ !== null) {
            const remainingLaneDelta = mobilePortraitTargetZ - player.position.z;
            if (Math.abs(remainingLaneDelta) < 0.16 || Math.sign(remainingLaneDelta) !== Math.sign(targetVelocity)) {
                player.position.z = mobilePortraitTargetZ;
                mobilePortraitTargetZ = null;
                currentStrafeVelocity *= 0.12;
            }
        }
        if (snowIceRoadUnderPlayer) {
            snowIceRoadSlipTimer = 0.18;
            snowIceRoadSlipRamp = Math.min(1, snowIceRoadSlipRamp + delta * 2.6);
            const mobileInputDir = MOBILE_RUNTIME && mobileControlsVisible && Math.abs(targetVelocity) > 0.2 ? Math.sign(targetVelocity) : 0;
            const inputDir = CONTROL_ACTION_STATE.moveLeft ? -1 : (CONTROL_ACTION_STATE.moveRight ? 1 : (Math.abs(gamepadMoveInput) > 0.2 ? Math.sign(gamepadMoveInput) : mobileInputDir));
            const velocityDir = Math.abs(currentStrafeVelocity) > 0.03 ? Math.sign(currentStrafeVelocity) : 0;
            if (Math.abs(snowIceRoadSlipDir) < 0.05) {
                snowIceRoadSlipDir = inputDir || lookSlipDir || velocityDir || 0;
            }
            const edgeBias = (player.position.z - getRoadCenterZ()) / Math.max(1, getRoadHalfWidth());
            const edgeCorrectDir = Math.abs(edgeBias) > 0.56 ? -Math.sign(edgeBias) : 0;
            const desiredSlipDir = edgeCorrectDir || inputDir || lookSlipDir || velocityDir || snowIceRoadSlipDir || 0;
            snowIceRoadSlipDir += (desiredSlipDir - snowIceRoadSlipDir) * Math.min(1, delta * 2.8);
            const targetSlipSpeed = desiredSlipDir === 0
                ? 0
                : (5.4 + moveSpeed * 4.2 + Math.min(1.8, Math.abs(currentStrafeVelocity) * 3.2) + Math.min(2.4, Math.abs(forward.z) * 1.2));
            snowIceRoadSlipSpeed += (targetSlipSpeed - snowIceRoadSlipSpeed) * Math.min(1, delta * 3.4);
            player.position.z += snowIceRoadSlipDir * snowIceRoadSlipSpeed * delta * snowIceRoadSlipRamp;
        } else {
            snowIceRoadSlipTimer = Math.max(0, snowIceRoadSlipTimer - delta);
            snowIceRoadSlipRamp = Math.max(0, snowIceRoadSlipRamp - delta * 4.0);
            snowIceRoadSlipSpeed *= Math.max(0, 1 - delta * 3.2);
            if (snowIceRoadSlipTimer <= 0.001) {
                snowIceRoadSlipDir *= Math.max(0, 1 - delta * 4.0);
            }
        }
        if (waterBouncePushTimer > 0) {
            waterBouncePushTimer = Math.max(0, waterBouncePushTimer - delta);
            player.position.z += waterBouncePushDir * LANE_WIDTH * 8.0 * delta;
            if (waterBounceTargetZ !== null) {
                const targetDiff = waterBounceTargetZ - player.position.z;
                if (Math.abs(targetDiff) < 0.55 || Math.sign(targetDiff) !== waterBouncePushDir || waterBouncePushTimer <= 0) {
                    player.position.z = waterBounceTargetZ;
                    waterBouncePushTimer = 0;
                    waterBouncePushDir = 0;
                    waterBounceTargetZ = null;
                    currentStrafeVelocity *= 0.28;
                }
            }
        }
        player.position.z = Math.max(roadLimitZMin + 0.5, Math.min(roadLimitZMax - 0.5, player.position.z));
        const canJump = ((CONTROL_ACTION_STATE.jump || gamepadJumpHeld) && !jumpKeyPressed) || jumpQueue;
        if (canJump && !isJumping) {
            performGroundJump(elapsedTime);
        }
        let glideActive = isGlideActive();
        if (glideActive) {
            // Glide basılı tutulan sürekli bir yetenek; bu blok her karede çalışır.
            // Görev sayacı yalnızca BAŞLAMA kenarında artmalı, yoksa saniyede 60 kez sayar.
            if (!glideWasActive) noteDailyMissionEvent('useAbility');
            glideTimeLeft = Math.max(0, glideTimeLeft - delta);
            if (glideTimeLeft <= 0) glideActive = false;
        }
        glideWasActive = glideActive;
        if (glideActive && playerVelocityY < GLIDE_FALL_SPEED_CAP) playerVelocityY = GLIDE_FALL_SPEED_CAP;
        const previousPlayerY = player.position.y;
        player.position.y += playerVelocityY * frameScale;
        if (!(airDashActive && isJumping)) {
            playerVelocityY -= (glideActive ? gravity * GLIDE_GRAVITY_SCALE : gravity) * frameScale;
        }
        if (glideActive && playerVelocityY < GLIDE_FALL_SPEED_CAP) playerVelocityY = GLIDE_FALL_SPEED_CAP;
        setGlideWindActive(glideActive);
        updateLavaDropTransition(delta);
        updateLavaApproachFade(delta);
        
        // --- ZEMÄ°N MANTIÄI (DÃœZELTÄ°LDÄ°) ---
        let baseFloor = onSkyLayer ? SKY_LAYER_Y + (isSliding ? slideHeight/2 : normalHeight/2) : (isSliding ? slideHeight/2 : normalHeight/2);
        if (lavaDropStarted && !lavaMapActivated) {
            baseFloor = -10000;
        }
        
        // Mega Jump uÃ§uÅŸu: Sadece YÃ¼kseklik 310'u geÃ§erse Sky Layer'Ä± aktif et
        if (megaJumpSpawned && !onSkyLayer && !lavaDropTransitionActive && !lavaMapActivated) {
            if (player.position.y > SKY_LAYER_Y + 10 && playerVelocityY < 0) {
                onSkyLayer = true; 
                baseFloor = SKY_LAYER_Y + (isSliding ? slideHeight/2 : normalHeight/2);
                // createSkyFloor ikinci kez Ã§aÄŸrÄ±lmÄ±yor â€” zaten pad tetiklenince Ã§aÄŸrÄ±ldÄ±
            }
        }

        let floorY = baseFloor;
        const actualPhysicsHeight = isSliding ? slideHeight : normalHeight;
        if (checkCyberSkybridgeCollision(actualPhysicsHeight, previousPlayerY)) return;
        
        obstacles.forEach((o, index) => {
            if (o.userData.type === 'traffic_light') {
                if (o.userData.active) {
                    if (didPlayerCrossTrafficLight(o)) {
                        o.userData.active = false; const lightType = o.userData.lightType;
                        if (lightType === 'green') { trafficBonusTimer = 5.0; playPickupSound(); const vign = ui.speedVignette; if (vign) { vign.classList.remove('red-light-vignette'); vign.classList.add('green-light-vignette'); } spawnArrowEffect('green'); } 
                        else { trafficSpeedPenalty += 0.12; playShieldBreakSound(); const vign = ui.speedVignette; if (vign) { vign.classList.remove('green-light-vignette'); vign.classList.add('red-light-vignette'); setTimeout(() => { if (trafficBonusTimer <= 0) vign.classList.remove('red-light-vignette'); }, 500); } spawnArrowEffect('red'); }
                    }
                }
                return; 
            }
            
            // --- MEGA JUMP PAD Ã‡ARPIÅMASI VE ANÄ°MASYONU ---
            if (o.userData.type === 'mega_jump_pad') {
                
                // YENÄ° EKLENEN ANÄ°MASYON KODLARI
                if (o.userData.ring1) o.userData.ring1.rotation.z += delta * 1.5;
                if (o.userData.ring2) o.userData.ring2.rotation.z -= delta * 2.5;
                if (o.userData.particles) {
                    const pos = o.userData.particles.geometry.attributes.position.array;
                    for(let k=0; k < o.userData.pSpeeds.length; k++) {
                        pos[k*3+1] += o.userData.pSpeeds[k];
                        if(pos[k*3+1] > 40.0) pos[k*3+1] = 0; // YukarÄ± Ã§Ä±kan parÃ§acÄ±ÄŸÄ± sÄ±fÄ±rla
                    }
                    o.userData.particles.geometry.attributes.position.needsUpdate = true;
                }

                if (o.userData.triggered) return;

                // Tetik yarıçapı pad'in KENDİ boyutundan gelmeli: yol şerit eklemeleriyle
                // genişliyor, sabit 25/20 penceresi kenar şeritleri kapsamıyordu (pad'in
                // yanından sıyrılıyordu). Pad spawn'dan sonra şerit eklenirse diye güncel
                // yol yarı genişliği de tabana alınır.
                const padRadius = Math.max(
                    o.userData.radius || (o.userData.length || 0) * 0.5,
                    getRoadHalfWidth() + 1.9
                );
                const zDist = Math.abs(player.position.z - o.position.z);
                // X'te swept aralık: yüksek hızda tek karede padin üstünden atlamasın
                const xReach = Math.max(padRadius, 25);
                const hitX = (playerSweptMaxX + xReach) >= o.position.x &&
                             (playerSweptMinX - xReach) <= o.position.x;

                if (hitX && zDist < padRadius + 4) {
                    if (isSliding) {
                        isSliding = false;
                        slideTimer = 0;
                        document.body.classList.remove('sliding');
                        if (ui.speedVignette) ui.speedVignette.classList.remove('sliding-vignette');
                        player.position.y += (normalHeight - slideHeight) / 2;
                        currentCameraHeight = normalHeight;
                    }
                    skyTransitionInvulnTimer = 2.5;
                    natureToSkyFadeProgress = 0;
                    if (o.userData.levelMidTransition && levelMegaJumpTransition) {
                        levelMegaJumpTransition.padTriggered = true;
                        gamePhase = levelMegaJumpTransition.targetPhase;
                        transitionFactor = 0;
                        playPhaseShiftSound('sky');
                        updateHudMapLabel(gamePhase);
                    }
                    skyMountainTargetCount = Math.min(
                        SKY_DECOR_MAX_MOUNTAINS,
                        Math.max(Math.ceil(countNatureMountains() * 0.85), SKY_DECOR_MIN_MOUNTAINS)
                    );
                    o.userData.triggered = true;
                    unlockAchievement('megaJump');
                    // Initialize the textured road before any Sky hierarchy is
                    // populated. Direct Sky levels and mid-level jumps now share
                    // this exact resource order.
                    createSkyFloor();
                    fillInitialSkyMap(player.position.x);
                    playerVelocityY = 5.0;
                    isJumping = true;
                    resetGlideTimer();
                    player.position.y += 2.0;
                    playJumpPadSound();
                    spawnArrowEffect('blue');
                    // Sky'a fırlatma: büyük şok halkası + parçacık sütunu + hafif sarsıntı
                    spawnImpactRing(o.position.x, player.position.y - 2.0, o.position.z, 0x8ff5ff, 13, 0.7, 0.9);
                    impactShake = Math.max(impactShake, 0.25);
                    o.position.y = -500;
                    isSkyFading = true;
                    skyAlpha = 0;
                }
                return;
            }

            if (!onSkyLayer && (isSkyFading || skyTransitionInvulnTimer > 0)) {
                return;
            }

            const verticalGap = Math.abs(player.position.y - o.position.y);
            if (verticalGap > 120) {
                return;
            }

            if (o.userData.triggerOnly) {
                return;
            }

            if (o.userData.lavaFading) {
                return;
            }

            // Phase Shift and Time Rewind are logical intangibility windows.
            // Trigger-only gameplay objects above still work, while every
            // lethal hazard below is skipped without moving its CPU collider.
            if (isHandSkillCollisionImmune()) return;

            if (o.userData.type && (o.userData.type.includes('train'))) {
                const trainRoofSafeThisFrame = isPlayerSupportedByTrainRoof(o, actualPhysicsHeight, isSliding ? 2.7 : 1.4, previousPlayerY);
                if (trainRoofSafeThisFrame) {
                    floorY = Math.max(floorY, getTrainRoofCenterY(o, actualPhysicsHeight));
                }
                o.children.forEach(child => {
                    if (child.name === 'train_barrier' && child.visible) {
                         const wallWorldX = o.position.x + child.position.x; const wallWorldY = o.position.y + child.position.y; const wallWorldZ = o.position.z + child.position.z;
                         const dz = Math.abs(player.position.z - wallWorldZ);
                         const colZ = (PLAYER_DEPTH + child.userData.widthZ) / 2;
                         if (sweptXOverlaps(wallWorldX, (child.userData.length || 2.0) * 0.5, 0.8 + Math.abs((o.userData.speedX || 0) * delta)) && dz < colZ) {
                             const playerBottom = player.position.y - (actualPhysicsHeight / 2); const playerTop = player.position.y + (actualPhysicsHeight / 2);
                             const collisionDrop = getTrainBarrierCollisionDrop(child);
                             const obsBottom = wallWorldY - (child.userData.height / 2) - collisionDrop; const obsTop = wallWorldY + (child.userData.height / 2) - collisionDrop;
                             if (playerTop > obsBottom && playerBottom < obsTop) {
                                 if (shieldActive) { child.visible = false; playShieldBreakSound(); spawnGlobalExplosion(wallWorldX, wallWorldY, wallWorldZ, 0xffff00, 30); spawnImpactRing(wallWorldX, player.position.y - actualPhysicsHeight / 2 + 0.2, wallWorldZ, 0xffff00, 7, 0.5, 0.85); trafficSpeedPenalty += 0.06; deactivateShield(); }
                             else { pushPlayerOutsideTrain(o); gameOver("Kaza yaptın!"); }
                             }
                         }
                    }
                });
            }
            
            // PERF (2026-07-05): getObjectByName her karede TÜM alt-ağacı (GLB vagonlar =
            // yüzlerce node) rekürsif tarıyordu — shield referansı artık spawn'da
            // userData.attachedShield'a yazılıyor, burada O(1) okunuyor.
            const attachedShield = o.userData.attachedShield;
            if (attachedShield) {
                attachedShield.rotation.y += delta * 2; attachedShield.getWorldPosition(tempWorldPos2);
                if (player.position.distanceTo(tempWorldPos2) < 5.0) { o.remove(attachedShield); o.userData.attachedShield = null; disposeNode(attachedShield); activateShield(); }
            }
            
            const staticTrainRampContact = o.userData.type === 'static_train'
                ? getStaticTrainRampContact(o, actualPhysicsHeight, previousPlayerY)
                : { supported: false, crossed: false, inFootprint: false, surfaceY: 0, centerY: 0 };
            if (o.userData.type === 'static_train' || o.userData.type === 'stopped_train' || o.userData.type === 'train') { 
                 if (isPlayerSupportedByTrainRoof(o, actualPhysicsHeight, isSliding ? 2.7 : 1.4, previousPlayerY)) {
                     floorY = Math.max(floorY, getTrainRoofCenterY(o, actualPhysicsHeight));
                 }
            }
            if (staticTrainRampContact.supported) floorY = Math.max(floorY, staticTrainRampContact.centerY);

            const isTrainCollisionBody = isTrainLikeTrafficType(o.userData.type);
            const obstacleCollisionCenterX = isTrainCollisionBody ? getTrainCollisionCenterX(o) : o.position.x;
            const dx = Math.abs(player.position.x - obstacleCollisionCenterX);
            const dz = Math.abs(player.position.z - o.position.z);
            const collisionX = (PLAYER_WIDTH + o.userData.length) / 2; 
            const collisionZ = (PLAYER_DEPTH + o.userData.widthZ) / 2;
            
            const useSweptX = !!(o.userData.type && (o.userData.type.includes('train') || o.userData.speedX));
            // Sürekli çarpışma: çarpışma bu frame'de trenin ESKİ konumuyla kontrol edilir,
            // tren updateObstacles'ta SONRA hareket eder → bir frame'lik boşluk. Trenin bu
            // frame'de kat edeceği mesafeyi padding'e ekleyerek hızda tünellemeyi önle.
            const obsSweepPad = Math.abs((o.userData.speedX || 0) * delta);
            const overlapsX = useSweptX ? sweptXOverlaps(obstacleCollisionCenterX, o.userData.length * 0.5, 0.8 + obsSweepPad) : dx < collisionX + obsSweepPad;
            if (overlapsX && dz < collisionZ + 0.2) {
                let collisionHappened = false;
                
                if (o.userData.type === 'falling_wall') {
                    const wallBottom = o.position.y - (o.userData.height / 2);
                    const wallTop = o.position.y + (o.userData.height / 2);
                    const groundLevel = onSkyLayer ? SKY_LAYER_Y : 0;
                    if (wallBottom < groundLevel + 8.0) { 
                        const playerBottom = player.position.y - (actualPhysicsHeight / 2);
                        const playerTop = player.position.y + (actualPhysicsHeight / 2);
                        if (playerBottom >= wallTop - 0.35 && playerVelocityY <= 0.25) {
                            floorY = Math.max(floorY, wallTop + (actualPhysicsHeight / 2) + 0.12);
                        } else if (playerTop > wallBottom + 0.2 && playerBottom < wallTop - 0.35) {
                            collisionHappened = true;
                        }
                    }
                }
                else if (o.userData.type === 'gate_part') {
                    if (o.position.y < (onSkyLayer ? SKY_LAYER_Y - 15.0 : -15.0)) {
                        collisionHappened = false;
                    } else {
                        const gateTop = o.position.y + 20.0;
                        const feetY = player.position.y - (actualPhysicsHeight / 2);
                        if (feetY < gateTop - 1.0) {
                            collisionHappened = true;
                        }
                    }
                }
                else if (o.userData.type === 'rising_rock') {
                    const rockTop = o.position.y + (o.userData.height / 2);
                    const feetY = player.position.y - (actualPhysicsHeight / 2);
                    
                    if (feetY < rockTop - 0.5) {
                        collisionHappened = true;
                    } else {
                        floorY = Math.max(floorY, rockTop + actualPhysicsHeight/2);
                    }
                }
                else if (o.userData.type === 'trap') {
                    const bladeLevel = o.userData.bladeHeight - 1.5; 
                    const playerHead = player.position.y + (actualPhysicsHeight / 2);
                    const dxTrap = Math.abs(player.position.x - o.position.x);
                    
                    if (playerHead > bladeLevel && dxTrap < 1.0) {
                        collisionHappened = true;
                    }
                }
                else if (o.userData.type === 'high_beam' || o.userData.type === 'slide_barrier') {
                    const playerBottom = player.position.y - (actualPhysicsHeight / 2); const playerTop = player.position.y + (actualPhysicsHeight / 2);
                    const obsBottom = o.position.y - (o.userData.height / 2); const obsTop = o.position.y + (o.userData.height / 2);
                    if (playerTop > obsBottom && playerBottom < obsTop) collisionHappened = true;
                }
                else if (o.userData.type === 'lava_lane') {
                    if (o.userData.active) {
                        const playerBottom = player.position.y - (actualPhysicsHeight / 2);
                        const lavaSafeBottom = (onSkyLayer ? SKY_LAYER_Y : 0) + 2.25;
                        if (playerBottom < lavaSafeBottom) collisionHappened = true;
                    }
                }
                else if (o.userData.type === 'snow_falling_ball') {
                    if (o.userData.phase === 'falling' && o.userData.ballGroup) {
                        const radius = (o.userData.radius || SNOWBALL_RADIUS) + 0.18;
                        const ballX = o.position.x;
                        const ballY = o.position.y + o.userData.ballGroup.position.y;
                        const ballZ = o.position.z;
                        const playerMinX = player.position.x - PLAYER_WIDTH * 0.5;
                        const playerMaxX = player.position.x + PLAYER_WIDTH * 0.5;
                        const playerMinY = player.position.y - actualPhysicsHeight * 0.5;
                        const playerMaxY = player.position.y + actualPhysicsHeight * 0.5;
                        const playerMinZ = player.position.z - PLAYER_DEPTH * 0.5;
                        const playerMaxZ = player.position.z + PLAYER_DEPTH * 0.5;
                        const closestX = Math.max(playerMinX, Math.min(playerMaxX, ballX));
                        const closestY = Math.max(playerMinY, Math.min(playerMaxY, ballY));
                        const closestZ = Math.max(playerMinZ, Math.min(playerMaxZ, ballZ));
                        const sx = closestX - ballX;
                        const sy = closestY - ballY;
                        const sz = closestZ - ballZ;
                        collisionHappened = (sx * sx + sy * sy + sz * sz) <= radius * radius;
                    } else if (o.userData.phase === 'shattering' && (o.userData.impactDangerTimer || 0) > 0) {
                        const radius = (o.userData.radius || SNOWBALL_RADIUS) + 0.35;
                        const impactX = Math.abs(player.position.x - o.position.x);
                        const impactZ = Math.abs(player.position.z - o.position.z);
                        const impactXRange = radius + PLAYER_WIDTH * 0.5;
                        const impactZRange = radius + PLAYER_DEPTH * 0.5;
                        collisionHappened = impactX < impactXRange && impactZ < impactZRange;
                    }
                }
                else if (o.userData.type === 'sky_sweeper') {
                    collisionHappened = checkSkySweeperCollision(o, actualPhysicsHeight, delta);
                }
                else {
                    const obstacleHeight = (typeof o.userData.height === 'number') ? o.userData.height : 0; const obstacleTop = obstacleHeight + (onSkyLayer ? SKY_LAYER_Y : 0);
                    const isTrainLikeObstacle = isTrainLikeTrafficType(o.userData.type);
                    const bodyHeightForObstacle = (isTrainLikeObstacle && isSliding) ? normalHeight : actualPhysicsHeight;
                    const feetY = player.position.y - (bodyHeightForObstacle / 2);
                    const onStaticTrainRamp = staticTrainRampContact.supported;
                    const climbTolerance = (o.userData.type === 'motorcycle') ? 1.8 : (isTrainLikeObstacle && !onStaticTrainRamp ? 0.45 : 1.8); // motorcycle: let the player land/ride on top instead of dying
                    if (onStaticTrainRamp) {
                        floorY = Math.max(floorY, staticTrainRampContact.centerY);
                    } else if (o.userData.type === 'static_train' && staticTrainRampContact.inFootprint) {
                        // The ramp footprint is always traversal-safe. This also
                        // covers edge contact, a stale jump flag, and very large
                        // low-FPS steps where the player can briefly sample below
                        // the visible wedge. Never fall through to the train's
                        // full-height lethal AABB while touching the ramp itself.
                        if (!isJumping || playerVelocityY <= 0.22) {
                            floorY = Math.max(
                                floorY,
                                staticTrainRampContact.surfaceY + bodyHeightForObstacle * 0.5 + getTrainRoofClearance()
                            );
                        }
                        collisionHappened = false;
                    } else if (isTrainLikeObstacle && isPlayerSupportedByTrainRoof(o, actualPhysicsHeight, isSliding ? 2.7 : 1.4, previousPlayerY)) {
                        floorY = Math.max(floorY, obstacleTop + (actualPhysicsHeight / 2) + getTrainRoofClearance());
                    } else if (feetY < obstacleTop - climbTolerance) collisionHappened = true; else { floorY = Math.max(floorY, obstacleTop + (actualPhysicsHeight/2) + 0.1); }
                }
                
                if (collisionHappened) {
                    lastCollisionDebug = {
                        type: o.userData.type || 'unknown',
                        playerX: Number(player.position.x.toFixed(3)),
                        playerPrevX: Number(playerPrevX.toFixed(3)),
                        playerY: Number(player.position.y.toFixed(3)),
                        playerZ: Number(player.position.z.toFixed(3)),
                        obstacleX: Number(o.position.x.toFixed(3)),
                        obstacleZ: Number(o.position.z.toFixed(3)),
                        length: Number(o.userData.length || 0),
                        bodyLength: Number(o.userData.bodyLength || 0),
                        widthZ: Number(o.userData.widthZ || 0),
                        ramp: o.userData.type === 'static_train' ? {
                            supported: !!staticTrainRampContact.supported,
                            inFootprint: !!staticTrainRampContact.inFootprint,
                            surfaceY: Number((staticTrainRampContact.surfaceY || 0).toFixed(3)),
                            rampStartX: Number((staticTrainRampContact.rampStartX || 0).toFixed(3)),
                            rampEndX: Number((staticTrainRampContact.rampEndX || 0).toFixed(3))
                        } : null
                    };
                }

                if (collisionHappened && tutorialDirector && tutorialDirector.active && o.userData?.tutorial) {
                    // Every tutorial collision is either protected by a correct
                    // input or sent through rewind. It can never kill the run.
                    if (!protectTutorialCollision(o)) tutorialDirector.beginRewind(o);
                    collisionHappened = false;
                } else if (collisionHappened && protectTutorialCollision(o)) {
                    collisionHappened = false;
                } else if (collisionHappened && tutorialDirector && tutorialDirector.beginRewind(o)) {
                    // Tutorial misses rewind rather than ending/resetting the run.
                    collisionHappened = false;
                }

                if (collisionHappened) {
                    if (o.userData.type === 'snow_falling_ball') {
                        shatterSnowFallingBall(o);
                        gameOver("Kartopu çarptı!");
                    } else if (shieldActive) { deactivateShield(); playShieldBreakSound(); spawnGlobalExplosion(o.position.x, o.position.y, o.position.z, 0x00ffff, 50); spawnImpactRing(o.position.x, player.position.y - actualPhysicsHeight / 2 + 0.2, o.position.z, 0x00ffff, 8, 0.5, 0.85); impactShake = Math.max(impactShake, 0.3); o.position.y = -1000; o.userData.speedX = 0; trafficSpeedPenalty += 0.06; } else { if (o.userData.type && o.userData.type.includes('train')) pushPlayerOutsideTrain(o); gameOver("Kaza yaptın!"); }
                }
            }
        });
        
        // --- DÃœZELTÄ°LMÄ°Å Ä°NÄ°Å MANTIÄI ---
        if (player.position.y <= floorY) {
            // EÄŸer Mega Jump yaptÄ±k, yoldayÄ±z (pad'e koÅŸuyoruz) ve henÃ¼z uÃ§madÄ±k.
            // Bu durumda floorY=0'dÄ±r ve player.y <= 0 olur.
            // Buraya girmeli ve yere basmalÄ±yÄ±z.
            // Eski kodda "if(megaJumpSpawned)" engelliyordu, bu yÃ¼zden dÃ¼ÅŸÃ¼yordunuz.
            // ArtÄ±k engel yok, karakter normal ÅŸekilde yere basacak.
            // ZÄ±pladÄ±ÄŸÄ±nda ise player.y > floorY olacaÄŸÄ± iÃ§in buraya girmeyecek.
            
            if (isJumping) {
                landImpact = 0.5; lastLandTime = clock.getElapsedTime(); playLandSound();
                // Eski shakeIntense=0.5 ataması bir frame sonra eziliyordu (her frame yeniden
                // hesap) — decay'li impactShake slam sarsıntısını gerçekten görünür kılar.
                if (isSlamming) {
                    const feetY = floorY - actualPhysicsHeight / 2;
                    bhopCombo = 0; bhopHudCombo = 0; bhopHudVisibleUntil = 0; isSlamming = false;
                    impactShake = Math.max(impactShake, 0.4);
                    spawnImpactRing(player.position.x, feetY + 0.14, player.position.z, 0x8ff5ff, 6.5, 0.45, 0.8);
                }
            }
            player.position.y = floorY; 
            playerVelocityY = 0; 
            isJumping = false;
            doubleJumpUsedInAir = false;
            resetGlideTimer();
            setGlideWindActive(false);
        }

        bobTimer += delta * bobFreq; let bY = 0, bZ = 0; if(!isJumping) { bY = Math.sin(bobTimer) * bobAmp; bZ = Math.cos(bobTimer * 0.5) * (bobAmp * 0.5); }
        if(landImpact > 0) landImpact -= delta * 3; else landImpact = 0;
        const impY = -Math.sin(landImpact * Math.PI) * 0.5;
        const speedRatio = Math.max(0, (moveSpeed - minMoveSpeed) / Math.max(0.001, maxMoveSpeed - minMoveSpeed));
        const windTremor = speedRatio * 0.012;
        shakeIntense = Math.min(0.07, score * 0.00008) + earthquakeIntensity + impactShake + windTremor;
        const sX = (Math.random() - 0.5) * shakeIntense; const sY = (Math.random() - 0.5) * shakeIntense; const sZ = (Math.random() - 0.5) * shakeIntense;
        const feetY = player.position.y - (actualPhysicsHeight / 2); const eyeHeightFromFeet = currentCameraHeight - 0.3;
        const iceSlipTilt = (snowIceRoadSlipTimer > 0 ? snowIceRoadSlipDir * Math.min(0.08, snowIceRoadSlipSpeed * 0.006) : 0);
        const tilt = (-currentStrafeVelocity * 0.15) + iceSlipTilt;
        camera.position.set(player.position.x + sX, feetY + eyeHeightFromFeet + bY + sY + impY, player.position.z + bZ + sZ);
        updateCameraAutoCenter(delta);
        camera.rotation.set(pitch + currentSlideTilt, yaw, tilt, 'YXZ');
        const targetFov = 85 + (score * 0.0015) + (bhopCombo * 1.5);
        currentFov += (targetFov - currentFov) * 3.0 * delta; 
        
        camera.fov = Math.min(110, currentFov + airDashBlend * 10); 
        camera.updateProjectionMatrix();
        
        if (isJumping) document.body.classList.add('jumping'); else document.body.classList.remove('jumping');
        // Update the shared curve before deformRoad() runs. Previously the road
        // used the previous frame's curve while shader-bent buildings/obstacles
        // used the current frame, which presented as a one-frame world bend and
        // changed the road's lighting/shadow response at the same instant.
        if (curvedPathSystem && typeof curvedPathSystem.update === 'function') {
            curvedPathSystem.update(score, scoreRealDelta || delta, player.position.x);
        }
        updateLanesProgress(); updateWindParticles(delta);
        
        updateSkyObjects(delta); 
    }

    function createDetailedLavaTunnel(startX, length) {
        const tunnelGroup = new THREE.Group();
        tunnelGroup.userData = { lavaTunnel: true };

        const centerZ = getRoadCenterZ();
        const roadHalfWidth = getRoadHalfWidth();
        const tunnelWidth = Math.max(60, getRoadWidth() + 28);
        const tunnelHeight = 32 * TUNNEL_HEIGHT_SCALE;
        const ribStep = 42;
        const panelStep = 84;
        const leftZ = centerZ - tunnelWidth * 0.5;
        const rightZ = centerZ + tunnelWidth * 0.5;
        const unitGeo = new THREE.BoxGeometry(1, 1, 1);
        const pillarMat = mats.lavaRockWarm;
        const basaltMat = mats.lavaRock;
        const glowMat = mats.lavaCore.clone();
        glowMat.emissiveIntensity = 1.85;
        const dimGlowMat = mats.lavaCore.clone();
        dimGlowMat.emissiveIntensity = 0.95;
        dimGlowMat.transparent = true;
        dimGlowMat.opacity = 0.82;

        const addBlock = (x, y, z, sx, sy, sz, mat, rx = 0, ry = 0, rz = 0) => {
            const isLongitudinal = sx >= 20;
            const mesh = isLongitudinal
                ? createSplineTunnelBox(sx, sy, sz, mat)
                : new THREE.Mesh(unitGeo, mat);
            mesh.position.set(x, y, z);
            mesh.scale.set(isLongitudinal ? 1 : sx, isLongitudinal ? 1 : sy, isLongitudinal ? 1 : sz);
            mesh.rotation.set(rx, ry, rz);
            mesh.castShadow = false;
            mesh.receiveShadow = true;
            tunnelGroup.add(mesh);
            return mesh;
        };

        const addGlow = (x, y, z, sx, sy, sz, mat = glowMat, seed = Math.random() * Math.PI * 2) => {
            const mesh = addBlock(x, y, z, sx, sy, sz, mat);
            mesh.userData = { isLavaTunnelGlow: true, baseIntensity: mat === glowMat ? 1.85 : 0.95, pulseSeed: seed };
            return mesh;
        };

        for (let x = startX; x <= startX + length; x += ribStep) {
            addBlock(x, 12.5, leftZ, 4.8, 25.0, 6.0, pillarMat);
            addBlock(x, 12.5, rightZ, 4.8, 25.0, 6.0, pillarMat);
            addBlock(x, 26.5, leftZ + 8.5, 4.8, 5.0, 13.0, basaltMat, 0, 0, -0.22);
            addBlock(x, 26.5, rightZ - 8.5, 4.8, 5.0, 13.0, basaltMat, 0, 0, 0.22);
            addBlock(x, tunnelHeight, centerZ, 4.9, 4.4, tunnelWidth * 0.48, pillarMat);

            if (Math.round((x - startX) / ribStep) % 2 === 0) {
                addGlow(x, 15.0, leftZ + 3.25, 0.5, 9.5, 0.9, dimGlowMat);
                addGlow(x, 15.0, rightZ - 3.25, 0.5, 9.5, 0.9, dimGlowMat);
            }
        }

        for (let x = startX + 22; x < startX + length - 22; x += panelStep) {
            const sectionLen = Math.min(panelStep * 0.82, startX + length - x);
            const midX = x + sectionLen * 0.5;
            addBlock(midX, 9.6, leftZ - 1.1, sectionLen, 14.8, 2.6, basaltMat);
            addBlock(midX, 9.6, rightZ + 1.1, sectionLen, 14.8, 2.6, basaltMat);
            addBlock(midX, 23.8, leftZ + 5.0, sectionLen * 0.66, 2.2, 1.4, pillarMat);
            addBlock(midX, 23.8, rightZ - 5.0, sectionLen * 0.66, 2.2, 1.4, pillarMat);
            addGlow(midX, tunnelHeight - 1.15, centerZ - tunnelWidth * 0.18, sectionLen * 0.38, 0.5, 1.0, dimGlowMat);
            addGlow(midX, tunnelHeight - 1.15, centerZ + tunnelWidth * 0.18, sectionLen * 0.38, 0.5, 1.0, dimGlowMat);
        }

        addGlow(startX + length * 0.5, 1.85, centerZ - roadHalfWidth - 4.0, length * 0.92, 0.36, 1.05, glowMat, 0.4);
        addGlow(startX + length * 0.5, 1.85, centerZ + roadHalfWidth + 4.0, length * 0.92, 0.36, 1.05, glowMat, 2.8);

        [startX, startX + length].forEach((x, index) => {
            addBlock(x, 14.0, leftZ - 1.7, 7.6, 28.0, 7.8, pillarMat);
            addBlock(x, 14.0, rightZ + 1.7, 7.6, 28.0, 7.8, pillarMat);
            addBlock(x, tunnelHeight + 1.0, centerZ, 8.0, 5.4, tunnelWidth + 9.0, pillarMat);
            addGlow(x, 24.0, leftZ + 4.0, 0.6, 12.0, 1.0, glowMat, index * 1.7);
            addGlow(x, 24.0, rightZ - 4.0, 0.6, 12.0, 1.0, glowMat, index * 1.7 + 0.8);
        });

        const spikeCount = Math.max(8, Math.floor(length / 58));
        for (let i = 0; i < spikeCount; i++) {
            const spike = new THREE.Mesh(geoms.lavaSpire, i % 2 === 0 ? basaltMat : pillarMat);
            const h = 5.5 + (i % 3) * 1.7 + Math.random() * 2.0;
            const x = startX + 30 + (i / Math.max(1, spikeCount - 1)) * Math.max(1, length - 60);
            spike.position.set(x, tunnelHeight - h * 0.48, centerZ + ((i % 2 === 0 ? -1 : 1) * tunnelWidth * (0.14 + Math.random() * 0.14)));
            spike.scale.set(1.35, h, 1.35);
            spike.rotation.z = Math.PI;
            spike.rotation.y = Math.random() * Math.PI * 2;
            tunnelGroup.add(spike);
        }

        const emberCount = Math.max(8, Math.floor(length / 62));
        for (let i = 0; i < emberCount; i++) {
            const ember = new THREE.Mesh(geoms.lavaBoulder, dimGlowMat);
            const side = i % 2 === 0 ? -1 : 1;
            ember.position.set(startX + 24 + (i / emberCount) * (length - 48), 2.0, centerZ + side * (roadHalfWidth + 5.2));
            ember.scale.setScalar(0.55 + Math.random() * 0.38);
            ember.userData = { isLavaTunnelGlow: true, baseIntensity: 0.95, pulseSeed: i * 0.77 };
            tunnelGroup.add(ember);
        }

        for (let i = 0; i < Math.max(4, Math.floor(length / 120)); i++) {
            const smoke = new THREE.Mesh(geoms.lavaSmokePuff, mats.lavaSmoke);
            smoke.position.set(startX + 70 + i * 115, 20 + Math.random() * 6, centerZ + (Math.random() - 0.5) * tunnelWidth * 0.45);
            smoke.scale.setScalar(3.0 + Math.random() * 2.2);
            smoke.rotation.set(Math.random(), Math.random(), Math.random());
            tunnelGroup.add(smoke);
        }

        return tunnelGroup;
    }

    function createDetailedWaterTunnel(startX, length) {
        const tunnelGroup = new THREE.Group();
        const centerX = startX + length * 0.5;
        const roadCenterZ = getRoadCenterZ();
        const width = Math.max(70, getRoadWidth() + 42);
        const halfWidth = width * 0.5;
        const height = 34 * TUNNEL_HEIGHT_SCALE;
        const wallHeight = height - 4.5;

        const roofGlass = createSplineTunnelBox(length, 0.55, width, mats.waterTunnelGlass);
        roofGlass.position.set(centerX, height, roadCenterZ);
        roofGlass.renderOrder = 2;
        tunnelGroup.add(roofGlass);

        [-1, 1].forEach((side) => {
            const wallGlass = createSplineTunnelBox(length, wallHeight, 0.55, mats.waterTunnelGlass);
            wallGlass.position.set(centerX, wallHeight * 0.5 + 1.2, roadCenterZ + side * halfWidth);
            wallGlass.renderOrder = 2;
            tunnelGroup.add(wallGlass);

            const shoulderGlass = createSplineTunnelBox(length, 0.42, 14, mats.waterTunnelGlass);
            shoulderGlass.position.set(centerX, height - 5.8, roadCenterZ + side * (halfWidth - 5.4));
            shoulderGlass.rotation.x = -side * 0.48;
            shoulderGlass.renderOrder = 2;
            tunnelGroup.add(shoulderGlass);
        });

        const framePlacements = [];
        const ribSpacing = 42;
        const ribCount = Math.max(5, Math.floor(length / ribSpacing) + 1);
        for (let i = 0; i <= ribCount; i++) {
            const x = Math.min(startX + length, startX + i * ribSpacing);
            framePlacements.push({ x, y: wallHeight * 0.5 + 1.0, z: roadCenterZ - halfWidth, sx: 1.35, sy: wallHeight + 2.4, sz: 1.25 });
            framePlacements.push({ x, y: wallHeight * 0.5 + 1.0, z: roadCenterZ + halfWidth, sx: 1.35, sy: wallHeight + 2.4, sz: 1.25 });
            framePlacements.push({ x, y: height, z: roadCenterZ, sx: 1.45, sy: 1.25, sz: width + 2.8 });
            framePlacements.push({ x, y: height - 6.8, z: roadCenterZ - halfWidth + 5.2, sx: 1.1, sy: 13.5, sz: 1.0, rx: 0.48 });
            framePlacements.push({ x, y: height - 6.8, z: roadCenterZ + halfWidth - 5.2, sx: 1.1, sy: 13.5, sz: 1.0, rx: -0.48 });
        }
        addInstancedDecor(tunnelGroup, geoms.waterTunnelUnit, mats.waterTunnelFrame, framePlacements, { receiveShadow: true });

        [
            [1.05, roadCenterZ - halfWidth + 5.6, 0.52],
            [1.05, roadCenterZ + halfWidth - 5.6, 0.52],
            [height - 1.0, roadCenterZ, 0.72]
        ].forEach(([y, z, depth]) => {
            const glow = createSplineTunnelBox(length, 0.18, depth, mats.waterTunnelGlow);
            glow.position.set(centerX, y, z);
            tunnelGroup.add(glow);
        });

        const fishBodiesA = [];
        const fishBodiesB = [];
        const fishTailsA = [];
        const fishTailsB = [];
        const fishCount = 30;
        for (let i = 0; i < fishCount; i++) {
            const side = Math.random() > 0.5 ? 1 : -1;
            const dir = Math.random() > 0.5 ? 1 : -1;
            const size = 0.75 + Math.random() * 1.35;
            const x = startX + 36 + Math.random() * Math.max(1, length - 72);
            const y = 7 + Math.random() * 22;
            const z = roadCenterZ + side * (halfWidth + 6 + Math.random() * 20);
            const yaw = (dir > 0 ? 0 : Math.PI) + (Math.random() - 0.5) * 0.45;
            const targetBodies = i % 2 === 0 ? fishBodiesA : fishBodiesB;
            const targetTails = i % 2 === 0 ? fishTailsA : fishTailsB;
            targetBodies.push({ x, y, z, sx: size, sy: size, sz: size, ry: yaw });
            targetTails.push({
                x: x - dir * 1.35 * size,
                y,
                z,
                sx: size * 0.72,
                sy: size * 0.72,
                sz: size * 0.72,
                ry: yaw,
                rz: dir > 0 ? Math.PI / 2 : -Math.PI / 2
            });
        }
        addInstancedDecor(tunnelGroup, geoms.waterTunnelFishBody, mats.waterTunnelFishA, fishBodiesA);
        addInstancedDecor(tunnelGroup, geoms.waterTunnelFishBody, mats.waterTunnelFishB, fishBodiesB);
        addInstancedDecor(tunnelGroup, geoms.waterTunnelFishTail, mats.waterTunnelFishA, fishTailsA);
        addInstancedDecor(tunnelGroup, geoms.waterTunnelFishTail, mats.waterTunnelFishB, fishTailsB);

        const seaweedPlacements = [];
        for (let i = 0; i < 34; i++) {
            const side = Math.random() > 0.5 ? 1 : -1;
            const h = 3.2 + Math.random() * 6.6;
            seaweedPlacements.push({
                x: startX + Math.random() * length,
                y: h * 0.5 - 0.8,
                z: roadCenterZ + side * (halfWidth + 8 + Math.random() * 18),
                sx: 0.28 + Math.random() * 0.18,
                sy: h,
                sz: 0.46 + Math.random() * 0.36,
                rx: (Math.random() - 0.5) * 0.26,
                rz: (Math.random() - 0.5) * 0.32
            });
        }
        addInstancedDecor(tunnelGroup, geoms.waterTunnelUnit, mats.waterIslandGrass, seaweedPlacements);

        const bubbleCount = isMobilePerformanceGraphics() ? 40 : 120;
        const bubblePositions = new Float32Array(bubbleCount * 3);
        for (let i = 0; i < bubbleCount; i++) {
            const side = Math.random() > 0.5 ? 1 : -1;
            bubblePositions[i * 3] = startX + Math.random() * length;
            bubblePositions[i * 3 + 1] = 3 + Math.random() * 29;
            bubblePositions[i * 3 + 2] = roadCenterZ + side * (halfWidth + 1.5 + Math.random() * 28);
        }
        const bubbleGeo = new THREE.BufferGeometry();
        bubbleGeo.setAttribute('position', new THREE.BufferAttribute(bubblePositions, 3));
        const bubbles = new THREE.Points(bubbleGeo, mats.waterTunnelBubble);
        bubbles.frustumCulled = false;
        tunnelGroup.add(bubbles);

        tunnelGroup.userData = {
            waterAquariumTunnel: true,
            bubbles,
            phase: Math.random() * Math.PI * 2
        };
        return tunnelGroup;
    }

    function updateWaterTunnelAnimation(tunnelMesh) {
        if (!tunnelMesh || !tunnelMesh.userData || !tunnelMesh.userData.waterAquariumTunnel) return;
        const bubbles = tunnelMesh.userData.bubbles;
        if (!bubbles) return;
        bubbles.position.y = Math.sin(clock.getElapsedTime() * 0.85 + (tunnelMesh.userData.phase || 0)) * 0.42;
    }

    function updateWaterAquariumTunnels() {
        if (gamePhase !== 4 || !waterMapActivated || !player) return;
        const playerX = player.position.x;
        if (nextWaterTunnelX < playerX + 760) {
            nextWaterTunnelX = playerX + 1050 + Math.random() * 360;
        }
        const hasLiveWaterTunnel = tunnels.some((t) => {
            return t && t.mesh && t.mesh.userData && t.mesh.userData.waterAquariumTunnel
                && t.endX > playerX - 180
                && t.startX < playerX + 2300;
        });
        if (hasLiveWaterTunnel || nextWaterTunnelX > playerX + 1850) return;
        const length = 520 + Math.random() * 260;
        createTunnel(nextWaterTunnelX, length, 'water_aquarium');
        nextWaterTunnelX += length + 1450 + Math.random() * 650;
    }

    function createDetailedSnowTunnel(startX, length) {
        const tunnelGroup = new THREE.Group();
        const centerX = startX + length * 0.5;
        const roadCenterZ = getRoadCenterZ();
        const width = Math.max(74, getRoadWidth() + 48);
        const halfWidth = width * 0.5;
        const height = 35 * TUNNEL_HEIGHT_SCALE;
        const wallHeight = height - 4.5;

        const roofGlass = createSplineTunnelBox(length, 0.62, width, mats.snowTunnelGlass);
        roofGlass.position.set(centerX, height, roadCenterZ);
        roofGlass.renderOrder = 2;
        tunnelGroup.add(roofGlass);

        [-1, 1].forEach((side) => {
            const wallGlass = createSplineTunnelBox(length, wallHeight, 0.66, mats.snowTunnelGlass);
            wallGlass.position.set(centerX, wallHeight * 0.5 + 1.0, roadCenterZ + side * halfWidth);
            wallGlass.renderOrder = 2;
            tunnelGroup.add(wallGlass);

            const shoulderGlass = createSplineTunnelBox(length, 0.48, 16, mats.snowTunnelGlass);
            shoulderGlass.position.set(centerX, height - 6.4, roadCenterZ + side * (halfWidth - 6.2));
            shoulderGlass.rotation.x = -side * 0.54;
            shoulderGlass.renderOrder = 2;
            tunnelGroup.add(shoulderGlass);
        });

        const framePlacements = [];
        const ribSpacing = 40;
        const ribCount = Math.max(6, Math.floor(length / ribSpacing) + 1);
        for (let i = 0; i <= ribCount; i++) {
            const x = Math.min(startX + length, startX + i * ribSpacing);
            framePlacements.push({ x, y: wallHeight * 0.5 + 0.8, z: roadCenterZ - halfWidth, sx: 1.55, sy: wallHeight + 2.6, sz: 1.5 });
            framePlacements.push({ x, y: wallHeight * 0.5 + 0.8, z: roadCenterZ + halfWidth, sx: 1.55, sy: wallHeight + 2.6, sz: 1.5 });
            framePlacements.push({ x, y: height, z: roadCenterZ, sx: 1.6, sy: 1.4, sz: width + 3.8 });
            framePlacements.push({ x, y: height - 7.4, z: roadCenterZ - halfWidth + 5.8, sx: 1.25, sy: 14.8, sz: 1.2, rx: 0.54 });
            framePlacements.push({ x, y: height - 7.4, z: roadCenterZ + halfWidth - 5.8, sx: 1.25, sy: 14.8, sz: 1.2, rx: -0.54 });
        }
        addInstancedDecor(tunnelGroup, geoms.waterTunnelUnit, mats.snowTunnelFrame, framePlacements, { receiveShadow: true, castShadow: true });

        [
            [height - 0.9, roadCenterZ, 0.82, 0.18],
            [wallHeight * 0.56, roadCenterZ - halfWidth + 0.8, 0.72, 0.2],
            [wallHeight * 0.56, roadCenterZ + halfWidth - 0.8, 0.72, 0.2]
        ].forEach(([y, z, depth, stripHeight]) => {
            const glow = createSplineTunnelBox(length, stripHeight, depth, mats.snowTunnelGlow);
            glow.position.set(centerX, y, z);
            tunnelGroup.add(glow);
        });

        const driftPlacements = [];
        const driftCount = Math.max(14, Math.floor(length / 34));
        for (let i = 0; i < driftCount; i++) {
            const x = startX + 12 + Math.random() * Math.max(1, length - 24);
            const side = i % 2 === 0 ? -1 : 1;
            const size = 0.8 + Math.random() * 0.75;
            driftPlacements.push({
                x,
                y: -0.55,
                z: roadCenterZ + side * (halfWidth + 2.4 + Math.random() * 4.5),
                sx: (9 + Math.random() * 8) * size,
                sy: 0.85 + Math.random() * 0.65,
                sz: (3 + Math.random() * 3.5) * size,
                ry: Math.random() * Math.PI
            });
        }
        addInstancedDecor(tunnelGroup, geoms.snowDrift, mats.snowCap, driftPlacements, { receiveShadow: true });

        const iciclePlacements = [];
        const icicleCount = Math.max(34, Math.floor(length / 16));
        for (let i = 0; i < icicleCount; i++) {
            const scaleY = 0.62 + Math.random() * 1.35;
            const actualHeight = 3.8 * scaleY;
            const sideBias = Math.random() > 0.62 ? (Math.random() > 0.5 ? 1 : -1) * (halfWidth * (0.48 + Math.random() * 0.34)) : 0;
            iciclePlacements.push({
                x: startX + 16 + Math.random() * Math.max(1, length - 32),
                y: height - actualHeight * 0.5 - 0.4 - Math.random() * 2.2,
                z: roadCenterZ + sideBias + (Math.random() - 0.5) * 8,
                sx: 0.7 + Math.random() * 0.75,
                sy: scaleY,
                sz: 0.7 + Math.random() * 0.75,
                rz: Math.PI,
                ry: Math.random() * Math.PI
            });
        }
        addInstancedDecor(tunnelGroup, geoms.snowTunnelIcicle, mats.snowIce, iciclePlacements, { castShadow: true });

        const crystalPlacements = [];
        const glowCrystalPlacements = [];
        const crystalCount = Math.max(24, Math.floor(length / 26));
        for (let i = 0; i < crystalCount; i++) {
            const side = i % 2 === 0 ? -1 : 1;
            const h = 2.4 + Math.random() * 5.2;
            const placement = {
                x: startX + 24 + Math.random() * Math.max(1, length - 48),
                y: 3.4 + Math.random() * 16,
                z: roadCenterZ + side * (halfWidth - 1.4),
                sx: 0.75 + Math.random() * 1.35,
                sy: h,
                sz: 0.75 + Math.random() * 1.25,
                rx: (Math.random() - 0.5) * 0.45,
                ry: Math.random() * Math.PI,
                rz: side * (0.12 + Math.random() * 0.25)
            };
            (i % 3 === 0 ? glowCrystalPlacements : crystalPlacements).push(placement);
        }
        addInstancedDecor(tunnelGroup, geoms.snowCrystal, mats.snowIce, crystalPlacements, { castShadow: true });
        addInstancedDecor(tunnelGroup, geoms.snowCrystal, mats.snowGlow, glowCrystalPlacements, { castShadow: true });

        const frostPanels = [];
        const panelCount = Math.max(16, Math.floor(length / 38));
        for (let i = 0; i < panelCount; i++) {
            const side = i % 2 === 0 ? -1 : 1;
            frostPanels.push({
                x: startX + Math.random() * length,
                y: 8 + Math.random() * 13,
                z: roadCenterZ + side * (halfWidth - 0.5),
                sx: 14 + Math.random() * 24,
                sy: 3 + Math.random() * 5.5,
                sz: 0.22,
                ry: (Math.random() - 0.5) * 0.08
            });
        }
        addInstancedDecor(tunnelGroup, geoms.waterTunnelUnit, mats.snowTunnelGlass, frostPanels);

        const sparkleCount = isMobilePerformanceGraphics() ? 42 : 128;
        const sparklePositions = new Float32Array(sparkleCount * 3);
        for (let i = 0; i < sparkleCount; i++) {
            sparklePositions[i * 3] = startX + Math.random() * length;
            sparklePositions[i * 3 + 1] = 5 + Math.random() * 27;
            sparklePositions[i * 3 + 2] = roadCenterZ + (Math.random() - 0.5) * (width - 12);
        }
        const sparkleGeo = new THREE.BufferGeometry();
        sparkleGeo.setAttribute('position', new THREE.BufferAttribute(sparklePositions, 3));
        const sparkles = new THREE.Points(sparkleGeo, mats.snowTunnelSparkle);
        sparkles.frustumCulled = false;
        tunnelGroup.add(sparkles);

        tunnelGroup.userData = {
            snowIceTunnel: true,
            sparkles,
            phase: Math.random() * Math.PI * 2
        };
        return tunnelGroup;
    }

    function updateSnowTunnelAnimation(tunnelMesh) {
        if (!tunnelMesh || !tunnelMesh.userData || !tunnelMesh.userData.snowIceTunnel) return;
        const sparkles = tunnelMesh.userData.sparkles;
        if (!sparkles) return;
        const time = clock.getElapsedTime();
        sparkles.position.y = Math.sin(time * 0.72 + (tunnelMesh.userData.phase || 0)) * 0.24;
        sparkles.rotation.y = Math.sin(time * 0.2 + (tunnelMesh.userData.phase || 0)) * 0.006;
    }

    function updateSnowIceTunnels() {
        if (gamePhase < 5 || !snowMapActivated || !player) return;
        const playerX = player.position.x;
        if (nextSnowTunnelX < playerX + 820) {
            nextSnowTunnelX = playerX + 1120 + Math.random() * 420;
        }
        const hasLiveSnowTunnel = tunnels.some((t) => {
            return t && t.mesh && t.mesh.userData && t.mesh.userData.snowIceTunnel
                && t.endX > playerX - 180
                && t.startX < playerX + 2400;
        });
        if (hasLiveSnowTunnel || nextSnowTunnelX > playerX + 1950) return;
        const length = 540 + Math.random() * 280;
        createTunnel(nextSnowTunnelX, length, 'snow_ice');
        nextSnowTunnelX += length + 1500 + Math.random() * 760;
    }

    function createTunnel(startX, length, tunnelTheme = null) {
        length *= TUNNEL_LENGTH_MULTIPLIER;
        let tunnelMesh;
        const isLavaTunnel = gamePhase === 3 && lavaMapActivated && !waterMapActivated;
        const isSnowTunnel = tunnelTheme === 'snow_ice' || (gamePhase >= 5 && snowMapActivated);
        const isWaterTunnel = tunnelTheme === 'water_aquarium' || (gamePhase === 4 && waterMapActivated);
        const isNature = (gamePhase >= 1);

        if (isLavaTunnel) {
            tunnelMesh = createDetailedLavaTunnel(startX, length);
        } else if (isSnowTunnel) {
            tunnelMesh = createDetailedSnowTunnel(startX, length);
        } else if (isWaterTunnel) {
            tunnelMesh = createDetailedWaterTunnel(startX, length);
        } else if (isNature) {
            tunnelMesh = createDetailedNatureTunnel(startX, length);
        } else {
            // CYBER TÜNEL v2 (2026-07-04): çelik kaburga kemerleri + dönüşümlü cyan/magenta
            // neon şeritler + tavan aydınlatma barları + zemin kılavuz ışıkları + giriş/çıkış
            // portal çerçeveleri. TÜM detay duvar hattında/tavanda — çarpışma zarfı (walls/roof,
            // halfWidth) birebir korunur, koşu koridoruna hiçbir şey taşmaz.
            tunnelMesh = new THREE.Group();
            const width = Math.max(CYBER_TUNNEL_MIN_WIDTH, getRoadWidth() + 22); const height = CYBER_TUNNEL_HEIGHT;
            tunnelMesh.userData = { cyberTunnel: true, halfWidth: width * 0.5 };

            const roof = createSplineTunnelBox(length, 2, width, mats.tunnel);
            roof.position.set(startX + length/2, height, 0);
            tunnelMesh.add(roof);

            const leftWall = createSplineTunnelBox(length, height, 2, mats.tunnel);
            leftWall.position.set(startX + length/2, height/2, -width/2);
            leftWall.receiveShadow = true;
            tunnelMesh.add(leftWall);

            const rightWall = createSplineTunnelBox(length, height, 2, mats.tunnel);
            rightWall.position.set(startX + length/2, height/2, width/2);
            rightWall.receiveShadow = true;
            tunnelMesh.add(rightWall);

            // duvar iç yüzeyinde koyu panel bandı (kaburgalar arasında derinlik hissi)
            for (const zSide of [-1, 1]) {
                const panel = createSplineTunnelBox(length, 13, 0.6, mats.tunnelPanel);
                panel.position.set(startX + length/2, 8.5, zSide * (width/2 - 1.0));
                tunnelMesh.add(panel);
            }

            const ribStep = 42;
            const postZ = width/2 - 1.7;      // duvar hattı — yol kenarından ~9 birim dışarıda
            const stripZ = width/2 - 2.8;
            const posts = [], beams = [], stripC = [], stripM = [], ceilC = [], ceilM = [];
            const lightBars = [], lightBacks = [], dashesL = [], dashesR = [];
            let ribIdx = 0;
            for (let x = startX + ribStep/2; x < startX + length - 8; x += ribStep, ribIdx++) {
                posts.push({ x, y: height/2, z: -postZ }, { x, y: height/2, z: postZ });
                beams.push({ x, y: height - 1.7 });
                const strips = (ribIdx % 2 === 0) ? stripC : stripM;
                strips.push({ x, y: 24, z: -stripZ }, { x, y: 24, z: stripZ });
                ((ribIdx % 2 === 0) ? ceilC : ceilM).push({ x, y: height - 2.8 });
                // kaburgalar ARASINDA tavan aydınlatması
                if (x + ribStep/2 < startX + length - 8) {
                    lightBars.push({ x: x + ribStep/2, y: height - 1.5 });
                    lightBacks.push({ x: x + ribStep/2, y: height - 1.1 });
                }
                // zemin kılavuz ışıkları (pist kenarı hissi)
                dashesL.push({ x, y: 0.28, z: -(width/2 - 2.4) }, { x: x + ribStep/2, y: 0.28, z: -(width/2 - 2.4) });
                dashesR.push({ x, y: 0.28, z: width/2 - 2.4 }, { x: x + ribStep/2, y: 0.28, z: width/2 - 2.4 });
            }
            addInstancedDecor(tunnelMesh, new THREE.BoxGeometry(1.7, height, 1.7), mats.tunnelSteel, posts, { receiveShadow: true });
            addInstancedDecor(tunnelMesh, new THREE.BoxGeometry(1.7, 1.7, width - 3), mats.tunnelSteel, beams);
            addInstancedDecor(tunnelMesh, new THREE.BoxGeometry(0.6, 44, 0.6), mats.neonCyan, stripC);
            addInstancedDecor(tunnelMesh, new THREE.BoxGeometry(0.6, 44, 0.6), mats.tunnelNeonMag, stripM);
            addInstancedDecor(tunnelMesh, new THREE.BoxGeometry(0.7, 0.6, width - 5), mats.neonCyan, ceilC);
            addInstancedDecor(tunnelMesh, new THREE.BoxGeometry(0.7, 0.6, width - 5), mats.tunnelNeonMag, ceilM);
            addInstancedDecor(tunnelMesh, new THREE.BoxGeometry(7, 0.4, 3.4), mats.neonCyan, lightBars);
            addInstancedDecor(tunnelMesh, new THREE.BoxGeometry(8, 0.3, 4.2), mats.tunnelSteel, lightBacks);
            addInstancedDecor(tunnelMesh, new THREE.BoxGeometry(3.4, 0.5, 0.8), mats.neonCyan, dashesL);
            addInstancedDecor(tunnelMesh, new THREE.BoxGeometry(3.4, 0.5, 0.8), mats.tunnelNeonMag, dashesR);

            // GİRİŞ/ÇIKIŞ PORTALLARI: kalın çelik çerçeve + neon kontur — tünel uzaktan okunur
            for (const px of [startX, startX + length]) {
                for (const zSide of [-1, 1]) {
                    const post = new THREE.Mesh(new THREE.BoxGeometry(3.4, height + 3, 3.4), mats.tunnelSteel);
                    post.position.set(px, (height + 3)/2, zSide * (width/2 + 0.8));
                    tunnelMesh.add(post);
                    const pStrip = new THREE.Mesh(new THREE.BoxGeometry(0.9, height - 6, 0.9), mats.neonCyan);
                    pStrip.position.set(px, (height - 6)/2 + 2, zSide * (width/2 - 0.4));
                    tunnelMesh.add(pStrip);
                }
                const header = new THREE.Mesh(new THREE.BoxGeometry(3.4, 5, width + 9), mats.tunnelSteel);
                header.position.set(px, height + 2.5, 0);
                tunnelMesh.add(header);
                const headerNeon = new THREE.Mesh(new THREE.BoxGeometry(1.2, 0.9, width + 3), mats.tunnelNeonMag);
                headerNeon.position.set(px, height - 1.0, 0);
                tunnelMesh.add(headerNeon);
            }
        }

        prepareTunnelForCurvedWorld(tunnelMesh, startX, length);
        scene.add(tunnelMesh);
        tunnels.push({ mesh: tunnelMesh, startX: startX, endX: startX + length, halfWidth: ((tunnelMesh.userData && tunnelMesh.userData.halfWidth) || Math.max(CYBER_TUNNEL_MIN_WIDTH, getRoadWidth() + 22) * 0.5) }); 
        removeJumpPadsInTunnelRange(startX, startX + length, 120);
        requestShadowMapRefresh(startX);
        
        if (typeof fixBuildingsInTunnel === 'function') {
            fixBuildingsInTunnel(startX, startX + length, tunnelMesh.userData?.halfWidth || Math.max(CYBER_TUNNEL_MIN_WIDTH, getRoadWidth() + 22) * 0.5);
        }
    }

    function updateTunnels() {
        if (!player) return;
        for (let i = tunnels.length - 1; i >= 0; i--) {
            const t = tunnels[i];
            updateWaterTunnelAnimation(t.mesh);
            updateSnowTunnelAnimation(t.mesh);
            if (t.endX < player.position.x - 200) {
                scene.remove(t.mesh);
                disposeNode(t.mesh);
                tunnels.splice(i, 1);
            }
        }
    }

    function createDetailedGateDoor() {
        const group = new THREE.Group();
        
        const frameGeo = new THREE.BoxGeometry(2.0, 20, 6.8);
        const frameMat = new THREE.MeshStandardMaterial({ color: 0x2a2a2a, roughness: 0.8, metalness: 0.7 });
        const frame = new THREE.Mesh(frameGeo, frameMat);
        frame.position.y = 10; 
        frame.castShadow = true;
        group.add(frame);

        const stripeGeo = new THREE.BoxGeometry(2.2, 18, 5.0);
        const stripeMat = new THREE.MeshStandardMaterial({ 
            color: 0x111111, 
            roughness: 0.6, 
            metalness: 0.8 
        });
        const stripes = new THREE.Mesh(stripeGeo, stripeMat);
        stripes.position.y = 10;
        group.add(stripes);

        const detailGeo = new THREE.BoxGeometry(2.3, 0.5, 4.0);
        const detailMat = new THREE.MeshStandardMaterial({ color: 0x555555 });
        
        for(let i=0; i<8; i++) {
            const bar = new THREE.Mesh(detailGeo, detailMat);
            bar.position.set(0, 3 + i * 2.5, 0);
            group.add(bar);
        }

        return group;
    }

    function spawnGateCluster(spawnX) {
        const indices = lanePositions.map((_, index) => index);
        
        for (let i = indices.length - 1; i > 0; i--) {
            const j = Math.floor(Math.random() * (i + 1));
            [indices[i], indices[j]] = [indices[j], indices[i]];
        }
        const openingCount = lanePositions.length > 5 ? 3 : 2;
        const sinkingIndices = indices.slice(0, Math.min(openingCount, indices.length)); 

        const floorY = onSkyLayer ? SKY_LAYER_Y : 0; // YENÄ° EKLENDÄ°: Zemin yÃ¼ksekliÄŸi

        for(let i=0; i<lanePositions.length; i++) {
            const lane = lanePositions[i];
            
            const gate = createDetailedGateDoor();
            gate.position.set(spawnX, floorY, lane); // DÃœZELTME: 0 yerine floorY yazÄ±ldÄ±

            const willSink = sinkingIndices.includes(i);
            
            gate.userData = {
                type: 'gate_part',     
                speedX: 0,            
                length: 2.0,           
                height: 20.0,         
                widthZ: 5.5,           
                willSink: willSink,    
                targetY: floorY - 22.0 // DÃœZELTME: KapÄ±nÄ±n ineceÄŸi yer zemin hizasÄ±na gÃ¶re ayarlandÄ±
            };

            scene.add(gate);
            obstacles.push(gate);
        }
        requestShadowMapRefresh(spawnX);
    }

    // Paylaşımlı geometri + siyah-beyaz tehlike şeridi dokusu bir kez kurulur (2026-07-14,
    // "düz duran siyah beyaz duvar" baştan tasarım — eski sürüm siyah çerçeve + CYAN parlayan
    // çekirdekti, "siyah beyaz" tarifiyle uyuşmuyordu; artık gerçekten monokrom).
    const _sw = { ready: false };
    function ensureStandingWallCache() {
        if (_sw.ready) return;
        const height = 18, thickness = 5.0, halfZ = 3.6;
        _sw.height = height; _sw.thickness = thickness; _sw.halfZ = halfZ;
        _sw.geoFrame = new THREE.BoxGeometry(thickness, height, halfZ * 2);
        _sw.geoSkin = new THREE.BoxGeometry(0.3, height - 1.6, halfZ * 2 - 1.0); // çerçeveden dışa taşan ince "tabela" paneli
        _sw.geoEdgeV = new THREE.BoxGeometry(thickness + 0.3, height, 0.3);
        _sw.geoEdgeH = new THREE.BoxGeometry(thickness + 0.3, 0.3, halfZ * 2 + 0.3);
        _sw.geoBolt = new THREE.CylinderGeometry(0.14, 0.14, 0.26, 8);
        _sw.geoBeacon = new THREE.SphereGeometry(0.24, 10, 10);

        // Siyah-beyaz diyagonal tehlike şeridi (yakıt/yol bariyeri kimliği — kırmızı duvardan
        // renk olarak ayrışsın diye SARI değil BEYAZ kullanıldı). 2026-07-14: kullanıcı isteğiyle
        // ters çevrildi — zemin artık beyaz, şeritler siyah (öncesi tam tersiydi).
        const s = 128;
        const cv = document.createElement('canvas'); cv.width = s; cv.height = s;
        const c = cv.getContext('2d');
        c.fillStyle = '#f2f2f2'; c.fillRect(0, 0, s, s);
        c.fillStyle = '#0a0a0a';
        c.save();
        c.translate(s / 2, s / 2); c.rotate(Math.PI / 4); c.translate(-s, -s);
        const stripeW = 22;
        for (let x = -s; x < s * 3; x += stripeW * 2) c.fillRect(x, -s, stripeW, s * 4);
        c.restore();
        _sw.hazardTex = new THREE.CanvasTexture(cv);
        _sw.hazardTex.colorSpace = THREE.SRGBColorSpace;
        _sw.hazardTex.wrapS = _sw.hazardTex.wrapT = THREE.RepeatWrapping;
        _sw.hazardTex.repeat.set(2, 5);
        _sw.hazardTex.__pooled = true;

        spawnPoolGeoms.push(_sw.geoFrame, _sw.geoSkin, _sw.geoEdgeV, _sw.geoEdgeH, _sw.geoBolt, _sw.geoBeacon);
        _sw.ready = true;
    }

    function createDetailedWall() {
        ensureStandingWallCache();
        const group = new THREE.Group();
        const height = _sw.height, thickness = _sw.thickness, halfZ = _sw.halfZ;
        const R = Math.random;

        // Ana çerçeve — açık, neredeyse beyaz metal (2026-07-14: siyah/beyaz ters çevrildi).
        // DÜŞÜK metalness kasıtlı: sahnede envMap kapalı (CLAUDE.md kuralı), yüksek metalness +
        // envMap'siz ortamda parlak renkler bile neredeyse siyah okunur (diffuse katkı sıfırlanır).
        const frameMat = new THREE.MeshStandardMaterial({ color: 0xf0f0f0, metalness: 0.25, roughness: 0.45 });
        const frame = new THREE.Mesh(_sw.geoFrame, frameMat);
        frame.position.y = height / 2;
        frame.castShadow = true;
        group.add(frame);

        // Siyah-beyaz tehlike şeridi paneli — çerçeveden dışa taşıyor (proud), MeshBasicMaterial:
        // sahnenin karanlık ışığından bağımsız her zaman okunaklı (kırmızı duvarda öğrenilen ders).
        // KRİTİK YÖN: kamera +X'e bakıyor → oyuncuya dönük yüz -X (bkz. falling_wall'daki aynı ders,
        // v2'de bu +X'te (kör tarafta) idi, çerçevenin solid kutusu arkasında tamamen gizleniyordu).
        const skinMat = new THREE.MeshBasicMaterial({ map: _sw.hazardTex });
        const skin = new THREE.Mesh(_sw.geoSkin, skinMat);
        skin.position.set(-(thickness / 2 + 0.15), height / 2, 0);
        group.add(skin);

        // Siyah kenar çerçevesi — 4 kenarın tamamı (2026-07-14: siyah/beyaz ters çevrildi)
        const edgeMat = new THREE.MeshBasicMaterial({ color: 0x0a0a0a });
        const edgeLeft = new THREE.Mesh(_sw.geoEdgeV, edgeMat); edgeLeft.position.set(0, height / 2, halfZ); group.add(edgeLeft);
        const edgeRight = new THREE.Mesh(_sw.geoEdgeV, edgeMat); edgeRight.position.set(0, height / 2, -halfZ); group.add(edgeRight);
        const edgeTop = new THREE.Mesh(_sw.geoEdgeH, edgeMat); edgeTop.position.set(0, height, 0); group.add(edgeTop);
        const edgeBottom = new THREE.Mesh(_sw.geoEdgeH, edgeMat); edgeBottom.position.set(0, 0, 0); group.add(edgeBottom);

        // Köşe cıvataları
        const boltMat = new THREE.MeshStandardMaterial({ color: 0x181818, metalness: 1.0, roughness: 0.35 });
        [1.3, height - 1.3].forEach((by) => {
            [-(halfZ - 0.3), halfZ - 0.3].forEach((bz) => {
                [thickness / 2 + 0.1, -(thickness / 2 + 0.1)].forEach((bx) => {
                    const bolt = new THREE.Mesh(_sw.geoBolt, boltMat);
                    bolt.rotation.z = Math.PI / 2;
                    bolt.position.set(bx, by, bz);
                    group.add(bolt);
                });
            });
        });

        // İki kehribar uyarı feneri (üst köşeler) — tamamen monokrom kalmasın, klasik bariyer
        // ışığı hissi versin; updateObstacles'ta falling_wall ile aynı blink mekanizmasını kullanır.
        const beaconMat = new THREE.MeshBasicMaterial({ color: 0xffaa00 });
        const warningLights = [];
        [-(halfZ - 0.4), halfZ - 0.4].forEach((lz) => {
            const beacon = new THREE.Mesh(_sw.geoBeacon, beaconMat);
            beacon.position.set(-(thickness / 2 + 0.15), height - 1.4, lz);
            group.add(beacon);
            warningLights.push(beacon);
        });

        group.userData.warningLights = warningLights;
        group.userData.pulseSeed = R() * Math.PI * 2;

        return group;
    }

    // --- YENÄ° GÃ–KYÃœZÃœ SÄ°STEMÄ° ---

function initSkyResources() {
    geoms.smallCloud = new THREE.IcosahedronGeometry(8, 1);
    geoms.cloudPuff = new THREE.IcosahedronGeometry(1, 1);

    mats.cloud = new THREE.MeshStandardMaterial({
        color: 0xffffff,
        roughness: 0.9,
        metalness: 0.0,
        transparent: true,
        opacity: 0.0,
        flatShading: true,
        depthWrite: true
    });

    mats.smallCloud = new THREE.MeshStandardMaterial({
        color: 0xffffff,
        transparent: true,
        opacity: 0.0,
        flatShading: true,
        depthWrite: true
    });

    mats.skyRoad = new THREE.MeshPhysicalMaterial({
        color: 0xaaccff,
        metalness: 0.1,
        roughness: 0.1,
        transparent: false,
        opacity: 1.0,
        transmission: 0.0,
        side: THREE.DoubleSide
    });

    geoms.skyScraperCore = new THREE.BoxGeometry(1, 1, 1);
    geoms.skyScraperTop = new THREE.BoxGeometry(1, 1, 1);
    geoms.skyWindowStrip = new THREE.BoxGeometry(1, 1, 0.12);

    geoms.skyPlaneBody = new THREE.CylinderGeometry(0.55, 0.75, 8.0, 10);
    geoms.skyPlaneWing = new THREE.BoxGeometry(0.24, 4.8, 1.2);
    geoms.skyPlaneTail = new THREE.BoxGeometry(0.2, 1.6, 0.55);
    geoms.skyPlaneTailWing = new THREE.BoxGeometry(0.12, 1.2, 0.45);

    geoms.skyMountainMain = new THREE.ConeGeometry(1, 1, 6);
    geoms.skyMountainSide = new THREE.ConeGeometry(1, 1, 5);

    mats.skyScraper = new THREE.MeshStandardMaterial({ color: 0x1a2535, roughness: 0.4, metalness: 0.85 });
    mats.skyScraperTrim = new THREE.MeshStandardMaterial({ color: 0x2a3f5a, roughness: 0.3, metalness: 0.9 });
    mats.skyWindowGlow = new THREE.MeshStandardMaterial({ color: 0x9fd6ff, emissive: 0x4488dd, emissiveIntensity: 1.2, roughness: 0.1, metalness: 0.5 });
    mats.skyScraperGlass = new THREE.MeshStandardMaterial({ color: 0x5599cc, emissive: 0x112244, emissiveIntensity: 0.4, roughness: 0.05, metalness: 0.95, transparent: true, opacity: 0.82 });
    mats.skyScraperNeonA = new THREE.MeshBasicMaterial({ color: 0x00ffff });
    mats.skyScraperNeonB = new THREE.MeshBasicMaterial({ color: 0xff00ff });
    mats.skyScraperNeonC = new THREE.MeshBasicMaterial({ color: 0xffaa00 });
    mats.skyScraperDark = new THREE.MeshStandardMaterial({ color: 0x0d1520, roughness: 0.6, metalness: 0.7 });

    mats.skyPlaneBody = new THREE.MeshStandardMaterial({ color: 0xe6edf5, roughness: 0.35, metalness: 0.25 });
    mats.skyPlaneWing = new THREE.MeshStandardMaterial({ color: 0x8ea3bd, roughness: 0.42, metalness: 0.38 });

    mats.skyMountain = new THREE.MeshStandardMaterial({ color: 0x6f7e95, roughness: 0.9, metalness: 0.06, flatShading: true });

    // Sky v2 model kütüphanesi materyalleri (2026-07-05) — hepsi mats.* içinde:
    // disposeNode paylaşımlı koruması + resetSkySharedMaterials restore listesi için.
    mats.skyMountainVC = new THREE.MeshStandardMaterial({ vertexColors: true, roughness: 0.9, metalness: 0.05, flatShading: true });
    mats.balloonRed = new THREE.MeshStandardMaterial({ color: 0xd8434f, roughness: 0.55, flatShading: true });
    mats.balloonCream = new THREE.MeshStandardMaterial({ color: 0xf2e6cf, roughness: 0.6, flatShading: true });
    mats.balloonBasket = new THREE.MeshStandardMaterial({ color: 0x7a5b38, roughness: 0.85 });
    mats.blimpBody = new THREE.MeshStandardMaterial({ color: 0xcdd6e2, roughness: 0.35, metalness: 0.45 });
    mats.blimpDark = new THREE.MeshStandardMaterial({ color: 0x39455a, roughness: 0.5, metalness: 0.6 });
    // FPS kova materyalleri: kule/balon/zeplin parçaları renk-bake ile 2 ortak materyalde
    // (glow = pencere/neon → MeshBasic: sürekli yanık görünür, ışık hesabı yok)
    mats.skyVCSolid = new THREE.MeshStandardMaterial({ vertexColors: true, roughness: 0.42, metalness: 0.6 });
    mats.skyVCGlow = new THREE.MeshBasicMaterial({ vertexColors: true });
    ensureSkyModelTypes(); // yükleme ekranında kur — oyun ortasında merge maliyeti olmasın
}

