function applyWaterThemeToLavaDecorObject(obj) {
    if (!obj || !mats.waterRock || obj.userData?.waterThemed) return;
    obj.traverse((child) => {
        if (!child.isMesh || !child.material) return;
        if (child.material === mats.lavaRockWarm) child.material = mats.waterRock;
        else if (child.material === mats.lavaRock) child.material = mats.waterRockDark;
        else if (child.material === mats.lavaCore) child.material = mats.waterGlow;
        else if (child.material === mats.lavaFlowHighlight) child.material = mats.waterFoam;
        else if (child.material === mats.lavaSmoke) child.material = mats.waterMist;
    });
    obj.userData = obj.userData || {};
    obj.userData.waterThemed = true;
}

function applyWaterThemeToAllLavaDecor() {
    lavaDecorObjects.forEach(applyWaterThemeToLavaDecorObject);
    lavaTerrainChunks.forEach((chunk) => {
        if (!chunk || chunk.userData?.waterThemed) return;
        chunk.material = mats.waterRock;
        chunk.userData = chunk.userData || {};
        chunk.userData.waterThemed = true;
    });
}

function trimLavaDecorForWaterPhase(playerX = 0) {
    const crowdedSmallLavaTypes = new Set(['rock', 'vent', 'rock_shelf']);
    const replaceWithCoastalMountains = new Set(['mountain', 'mountain_twin', 'mountain_range']);
    for (let i = lavaDecorObjects.length - 1; i >= 0; i--) {
        const obj = lavaDecorObjects[i];
        if (!obj) continue;
        const decorType = obj.userData && obj.userData.decorType;
        const distAhead = obj.position.x - playerX;
        const farBehind = distAhead < -360;
        const oldSmallLavaAhead = crowdedSmallLavaTypes.has(decorType) && distAhead > -220 && distAhead < 2800;
        const oldLavaMountainAhead = replaceWithCoastalMountains.has(decorType) && distAhead > -260 && distAhead < 3200;
        if (!farBehind && !oldSmallLavaAhead && !oldLavaMountainAhead) continue;
        disposeNode(obj);
        lavaDecorObjects.splice(i, 1);
    }
}

function applySnowThemeToLavaDecorObject(obj) {
    if (!obj || !mats.snowRock || obj.userData?.snowThemed) return;
    obj.traverse((child) => {
        if (!child.isMesh || !child.material) return;
        if (child.material === mats.lavaRockWarm || child.material === mats.waterRock || child.material === mats.waterSand || child.material === mats.waterIslandGrass) child.material = mats.snowRock;
        else if (child.material === mats.lavaRock || child.material === mats.waterRockDark) child.material = mats.snowRockDark;
        else if (child.material === mats.lavaCore || child.material === mats.waterGlow) child.material = mats.snowGlow;
        else if (child.material === mats.lavaFlowHighlight || child.material === mats.waterFoam) child.material = mats.snowCap;
        else if (child.material === mats.lavaSmoke || child.material === mats.waterMist) child.material = mats.snowIce;
        else if (child.material === mats.waterPalmLeaf) child.material = mats.snowPineNeedle;
        else if (child.material === mats.waterPalmTrunk || child.material === mats.pirateDeck || child.material === mats.pirateHull) child.material = mats.snowWood;
        else if (child.material === mats.pirateSail || child.material === mats.lighthouseWhite) child.material = mats.snowCap;
        else if (child.material === mats.waterContainerRed || child.material === mats.waterContainerBlue || child.material === mats.waterContainerYellow) child.material = mats.snowRock;
    });
    obj.userData = obj.userData || {};
    obj.userData.snowThemed = true;
}

function applySnowThemeToAllLavaDecor() {
    lavaDecorObjects.forEach(applySnowThemeToLavaDecorObject);
    lavaTerrainChunks.forEach((chunk) => {
        if (!chunk || chunk.userData?.snowThemed) return;
        chunk.material = mats.snowRock;
        chunk.userData = chunk.userData || {};
        chunk.userData.snowThemed = true;
    });
}

function removeWaterDecorForSnowPhase() {
    const blockedTypes = new Set(['water_oil_platform', 'water_island', 'water_container', 'water_buoy', 'water_cargo_ship']);
    for (let i = lavaDecorObjects.length - 1; i >= 0; i--) {
        const obj = lavaDecorObjects[i];
        const decorType = obj && obj.userData && obj.userData.decorType;
        const themedMountain = !!(obj && obj.userData && obj.userData.waterThemed)
            && (decorType === 'mountain' || decorType === 'mountain_twin' || decorType === 'mountain_range');
        if (!blockedTypes.has(decorType) && !themedMountain) continue;
        disposeNode(obj);
        lavaDecorObjects.splice(i, 1);
    }
}

function setEnergyPlasmaTheme(group, theme = 'lava') {
    if (!group || !group.userData) return;
    const isWater = theme === 'water';
    const isSnow = theme === 'snow';
    const baseMat = isSnow ? mats.snowPlasma : (isWater ? mats.waterPlasma : mats.energyPlasma);
    const core = group.userData.coreMesh;
    const shell = group.userData.shellMesh;

    if (core && baseMat) {
        core.material = baseMat;
        core.material.transparent = false;
        core.material.opacity = 1.0;
        core.material.depthTest = true;
        core.material.depthWrite = true;
        core.renderOrder = 0;
    }

    if (shell && baseMat) {
        if (shell.material && shell.material !== mats.energyPlasma && shell.material !== mats.waterPlasma && shell.material !== mats.snowPlasma) {
            shell.material.dispose();
        }
        const shellMat = baseMat.clone();
        shellMat.transparent = true;
        shellMat.opacity = isSnow ? 0.34 : (isWater ? 0.36 : 0.42);
        shellMat.emissiveIntensity = isSnow ? 3.8 : (isWater ? 3.45 : 4.2);
        shellMat.depthTest = true;
        shellMat.depthWrite = true;
        shell.material = shellMat;
        shell.renderOrder = 0;
    }

    group.userData.hazardTheme = theme;
}

// ===== LAV v2 MODEL KÜTÜPHANESİ (2026-07-05) — cyber/doğa/sky merge kalıbının lav karşılığı.
// KRİTİK: lav dekoru su/kar fazında materyal-REFERANSIYLA yeniden temalanıyor
// (applyWaterTheme/applySnowTheme child.material===mats.lavaRock kontrolü) + pulse animasyonu
// child.material===lavaCore arıyor. Bu yüzden color-bake KULLANILMAZ (referans bozulur) —
// cbMergeByMaterial ile 4 tema-materyalini (lavaRock/lavaRockWarm/lavaCore/lavaSmoke) AYRI
// tutarak birleştir → hem draw call düşer hem tema-swap + pulse çalışmaya devam eder.
const lavaModelGeoms = [];
const lavaTypeCache = { volcano: [], obsidian: [], geyser: [], ashtree: [], basalt: [], peak: [] };
const lavaDecorPrototypeCache = new Map();

async function prewarmLavaDecorPrototypes() {
    // These large composite factories still built/extruded/merged fresh meshes
    // per spawn (20-50ms in the transition test). Keep two authored-layout
    // variants per type; clones retain per-instance transforms and matrices.
    const factories = [
        ['mountain_range', createLavaMountainRange],
        ['mountain_twin', createLavaTwinMountain],
        ['castle', createLavaCastle],
        ['rock_shelf', createLavaRockShelf]
    ];
    const seenGeometry = new Set(lavaModelGeoms);
    for (const [type, factory] of factories) {
        if (lavaDecorPrototypeCache.has(type)) continue;
        const variants = [];
        for (let i = 0; i < 2; i++) {
            const prototype = factory();
            prototype.traverse(node => {
                if (node.geometry && !seenGeometry.has(node.geometry)) {
                    seenGeometry.add(node.geometry);
                    lavaModelGeoms.push(node.geometry); // shared-dispose protection
                }
            });
            variants.push(prototype);
            await yieldLoadingSlice();
        }
        lavaDecorPrototypeCache.set(type, variants);
    }
}

function cloneCachedLavaDecor(type, factory) {
    const variants = lavaDecorPrototypeCache.get(type);
    if (!variants?.length) return factory();
    const object = variants[Math.floor(Math.random() * variants.length)].clone(true);
    object.userData.pulseSeed = Math.random() * Math.PI * 2;
    return object;
}
const elementalMountainTypeCache = {
    water: { single: [], twin: [], range: [] },
    snow: { single: [], twin: [], range: [] }
};
const elementalMountainPeakGeos = [];
const LAVA_MODEL_BUILD_STEP_COUNT = 11;
const ELEMENTAL_MOUNTAIN_BUILD_STEP_COUNT = 6;
let lavaModelBuildStepIndex = 0;
let elementalMountainBuildStepIndex = 0;
let browserDeferredCacheWarmScheduled = false;
let browserDeferredCacheWarmReady = false;
let browserDeferredPrototypeWarmScheduled = false;
let browserDeferredPrototypeWarmReady = false;
let browserDeferredEnvironmentIndex = 0;
const BROWSER_DEFERRED_ENVIRONMENT_PHASES = Object.freeze([2, 3, 4]);

function lavaCacheParts(bucket, group) {
    const parts = cbMergeByMaterial(group);
    parts.forEach(p => lavaModelGeoms.push(p.geo));
    bucket.push(parts);
}

function instantiateLavaParts(partsList) {
    const parts = partsList[Math.floor(Math.random() * partsList.length)];
    const g = new THREE.Group();
    for (const p of parts) {
        const m = new THREE.Mesh(p.geo, p.mat);
        m.castShadow = false;
        m.receiveShadow = false;
        g.add(m);
    }
    return g;
}

// Sky dağlarındaki makeSkyPeakGeo'nun tema-güvenli lava karşılığı: jitter'lı organik bazalt zirve.
// Vertex-color YOK (lav dekoru su/kar fazında materyal-REFERANSIYLA temalanır + pulse lavaCore arar);
// silueti düz koniden çıkarıp doğal kayalık tepe yapar. Taban-orijinli birim koni (yarıçap 1, boy 1) →
// mesh.scale.set(w,h,w) doğrudan en/boy verir, lavaSpire ile aynı ölçek semantiği.
function makeLavaPeakGeo(seed, radialSeg) {
    const rnd = natSeedRand(seed);
    const geo = new THREE.CylinderGeometry(0.30, 1, 1, radialSeg, 6, true);
    geo.translate(0, 0.5, 0);
    const pos = geo.attributes.position;
    for (let i = 0; i < pos.count; i++) {
        const t = Math.max(0, Math.min(1, pos.getY(i)));
        if (t < 0.9) {
            const j = 0.22 * (1 - t * 0.6); // tabanda geniş pürüz, zirveye doğru sivrilir
            pos.setX(i, pos.getX(i) + (rnd() - 0.5) * j);
            pos.setZ(i, pos.getZ(i) + (rnd() - 0.5) * j);
            pos.setY(i, pos.getY(i) + (rnd() - 0.5) * 0.035);
        }
    }
    geo.computeVertexNormals();
    geo.computeBoundingSphere();
    return geo;
}

function buildLavaVolcano(seed) {
    const rnd = natSeedRand(seed);
    const g = new THREE.Group();
    // Ana koni: jitter'lı, pürüzlü bazalt gövde (düz koniden daha organik)
    const mainHeight = 154;
    const mainGeo = new THREE.CylinderGeometry(13.5, 49, mainHeight, 12, 7, true);
    mainGeo.translate(0, mainHeight * 0.5, 0);
    const mp = mainGeo.attributes.position;
    for (let i = 0; i < mp.count; i++) {
        const t = Math.max(0, Math.min(1, mp.getY(i) / mainHeight));
        if (t < 0.92) {
            const shelf = 1 + Math.sin(t * Math.PI * 5.0) * 0.055;
            mp.setX(i, mp.getX(i) * shelf + (rnd() - 0.5) * 10.5 * (1 - t * 0.62));
            mp.setZ(i, mp.getZ(i) * shelf + (rnd() - 0.5) * 10.5 * (1 - t * 0.62));
            mp.setY(i, mp.getY(i) + (rnd() - 0.5) * 4.4);
        }
    }
    mainGeo.computeVertexNormals();
    const main = new THREE.Mesh(mainGeo, mats.lavaRockWarm);
    g.add(main);
    // yan tepeler
    let sidePeakIndex = 0;
    for (const [sx, sy, sz, px, pz, mat] of [
        [29, 92, 27, -36, 18, mats.lavaRock],
        [24, 72, 25, 38, -14, mats.lavaRock],
        [19, 58, 21, 22, 29, mats.lavaRockWarm]
    ]) {
        const sGeo = makeLavaPeakGeo(seed + 31 + sidePeakIndex * 17, 7 - (sidePeakIndex % 2));
        sidePeakIndex++;
        const s = new THREE.Mesh(sGeo, mat);
        s.scale.set(sx, sy, sz);
        s.position.set(px, -2, pz);
        s.rotation.z = (rnd() - 0.5) * 0.3;
        s.rotation.y = rnd() * Math.PI * 2;
        g.add(s);
    }
    // AKAN lav dereleri: koninin ön yüzünde birden çok kıvrımlı ince şerit
    const seamCount = 6;
    for (let i = 0; i < seamCount; i++) {
        const h = 40 + rnd() * 24;
        const w = 3.8 + rnd() * 2.8;
        const seam = new THREE.Mesh(createLavaRibbonGeometry(h, w, 1.25, 6), mats.lavaCore);
        const a = (i - (seamCount - 1) * 0.5) * 0.3;
        seam.position.set(Math.sin(a) * 27, 91 - i * 5.5, Math.cos(a) * 35);
        seam.rotation.z = a * 0.22;
        seam.rotation.x = -0.52;
        g.add(seam);

        const seamHighlight = new THREE.Mesh(
            createLavaRibbonGeometry(h * 0.94, w * 0.24, 0.24, 9),
            mats.lavaFlowHighlight
        );
        seamHighlight.position.copy(seam.position);
        seamHighlight.position.z += 0.75;
        seamHighlight.rotation.copy(seam.rotation);
        g.add(seamHighlight);
    }
    // krater ağzı (parlak) + duman
    const caldera = new THREE.Mesh(new THREE.TorusGeometry(11.5, 3.2, 6, 12), mats.lavaRock);
    caldera.rotation.x = Math.PI / 2;
    caldera.position.y = 149;
    g.add(caldera);
    const crater = new THREE.Mesh(new THREE.CylinderGeometry(9.2, 7.5, 2.4, 12), mats.lavaCore);
    crater.position.y = 148.4;
    g.add(crater);
    for (let i = 0; i < 8; i++) {
        const s = 3.4 + rnd() * 2.0;
        const puff = new THREE.Mesh(geoms.lavaSmokePuff, mats.lavaSmoke);
        puff.scale.setScalar(s);
        puff.position.set((rnd() - 0.5) * 14, 160 + i * 8.5, (rnd() - 0.5) * 14);
        g.add(puff);
    }
    return g;
}

function buildObsidianSpires(seed) {
    const rnd = natSeedRand(seed);
    const g = new THREE.Group();
    const count = 4 + Math.floor(rnd() * 3);
    for (let i = 0; i < count; i++) {
        const h = 16 + rnd() * 34;
        const w = 2.5 + rnd() * 4;
        // keskin obsidyen dikeni — az kenarlı (3-4) sivri prizma
        const spire = new THREE.Mesh(new THREE.ConeGeometry(w, h, 3 + (i % 2), 1), mats.lavaRock);
        const a = rnd() * Math.PI * 2;
        const d = rnd() * 16;
        spire.position.set(Math.cos(a) * d, h * 0.5 - 1.5, Math.sin(a) * d);
        spire.rotation.set((rnd() - 0.5) * 0.3, rnd() * Math.PI, (rnd() - 0.5) * 0.3);
        g.add(spire);
        // dipte parlayan lav damarı
        if (i % 2 === 0) {
            const vein = new THREE.Mesh(new THREE.BoxGeometry(w * 1.6, 0.4, 1.0), mats.lavaCore);
            vein.position.set(spire.position.x, -0.6, spire.position.z);
            vein.rotation.y = rnd() * Math.PI;
            g.add(vein);
        }
    }
    // taban kayası
    const base = new THREE.Mesh(geoms.lavaBoulder, mats.lavaRockWarm);
    base.scale.set(20, 4, 16);
    base.position.y = -1;
    base.rotation.y = rnd() * Math.PI;
    g.add(base);
    return g;
}

function buildLavaGeyser(seed) {
    const rnd = natSeedRand(seed);
    const g = new THREE.Group();
    // kaya baca gövdesi
    const chimney = new THREE.Mesh(new THREE.CylinderGeometry(3.4, 6.0, 22, 8), mats.lavaRockWarm);
    chimney.position.y = 11;
    g.add(chimney);
    const rim = new THREE.Mesh(new THREE.CylinderGeometry(4.4, 3.6, 3.0, 8), mats.lavaRock);
    rim.position.y = 22;
    g.add(rim);
    // fışkıran lav sütunu (yükselen kademeli bloklar)
    for (let i = 0; i < 5; i++) {
        const t = i / 4;
        const col = new THREE.Mesh(new THREE.CylinderGeometry(2.6 * (1 - t * 0.6), 3.0 * (1 - t * 0.5), 6, 7), mats.lavaCore);
        col.position.set((rnd() - 0.5) * 2 * t, 24 + i * 5.5, (rnd() - 0.5) * 2 * t);
        g.add(col);
    }
    // saçılan lav damlaları
    for (let i = 0; i < 5; i++) {
        const blob = new THREE.Mesh(geoms.lavaBoulder, mats.lavaCore);
        const s = 0.7 + rnd() * 0.9;
        blob.scale.setScalar(s);
        const a = rnd() * Math.PI * 2;
        blob.position.set(Math.cos(a) * (4 + rnd() * 6), 34 + rnd() * 16, Math.sin(a) * (4 + rnd() * 6));
        g.add(blob);
    }
    // duman
    for (let i = 0; i < 3; i++) {
        const puff = new THREE.Mesh(geoms.lavaSmokePuff, mats.lavaSmoke);
        puff.scale.setScalar(2.2 + rnd() * 1.4);
        puff.position.set((rnd() - 0.5) * 5, 46 + i * 6, (rnd() - 0.5) * 5);
        g.add(puff);
    }
    return g;
}

function buildAshTree(seed) {
    const rnd = natSeedRand(seed);
    const g = new THREE.Group();
    const trunkH = 14 + rnd() * 8;
    const trunk = new THREE.Mesh(new THREE.CylinderGeometry(0.7, 1.7, trunkH, 6), mats.lavaRock);
    trunk.position.y = trunkH / 2;
    g.add(trunk);
    // çıplak, açılı kömürleşmiş dallar
    const branchCount = 5 + Math.floor(rnd() * 3);
    for (let i = 0; i < branchCount; i++) {
        const len = 4 + rnd() * 5;
        const bGeo = new THREE.CylinderGeometry(0.12, 0.4, len, 5);
        bGeo.translate(0, len / 2, 0);
        const branch = new THREE.Mesh(bGeo, mats.lavaRock);
        const yaw = rnd() * Math.PI * 2;
        const by = trunkH * (0.5 + rnd() * 0.42);
        branch.position.set(Math.cos(yaw) * 1.2, by, Math.sin(yaw) * 1.2);
        branch.rotation.set(Math.sin(yaw) * (0.8 + rnd() * 0.5), 0, -Math.cos(yaw) * (0.8 + rnd() * 0.5));
        g.add(branch);
    }
    // dipte için için yanan köz çatlakları
    for (let i = 0; i < 3; i++) {
        const a = rnd() * Math.PI * 2;
        const crack = new THREE.Mesh(new THREE.BoxGeometry(1.2 + rnd() * 1.4, 0.3, 0.6), mats.lavaCore);
        crack.position.set(Math.cos(a) * (1.5 + rnd()), -0.5, Math.sin(a) * (1.5 + rnd()));
        crack.rotation.y = rnd() * Math.PI;
        g.add(crack);
    }
    return g;
}

function buildBasaltColumns(seed) {
    const rnd = natSeedRand(seed);
    const g = new THREE.Group();
    // altıgen sütunlu bazalt kümesi (Giant's Causeway) — değişken yükseklikte prizma ormanı
    const cols = 7 + Math.floor(rnd() * 4);
    for (let i = 0; i < cols; i++) {
        const h = 8 + rnd() * 30;
        const r = 2.2 + rnd() * 1.4;
        const col = new THREE.Mesh(new THREE.CylinderGeometry(r, r * 1.02, h, 6), (i % 3 === 0) ? mats.lavaRockWarm : mats.lavaRock);
        const a = (i / cols) * Math.PI * 2 + rnd() * 0.5;
        const d = 2 + rnd() * 12;
        col.position.set(Math.cos(a) * d, h * 0.5 - 1.5, Math.sin(a) * d);
        col.rotation.y = rnd() * Math.PI;
        col.rotation.z = (rnd() - 0.5) * 0.14;
        g.add(col);
        // bazı sütunların tepesinde parlayan çatlak
        if (i % 4 === 0) {
            const glow = new THREE.Mesh(new THREE.CylinderGeometry(r * 0.6, r * 0.6, 0.5, 6), mats.lavaCore);
            glow.position.set(col.position.x, h - 1.5, col.position.z);
            g.add(glow);
        }
    }
    // aralardan sızan lav taban çizgileri
    for (let i = 0; i < 2; i++) {
        const seam = new THREE.Mesh(new THREE.BoxGeometry(10 + rnd() * 8, 0.4, 1.2), mats.lavaCore);
        seam.position.set((rnd() - 0.5) * 8, -1.2, (rnd() - 0.5) * 8);
        seam.rotation.y = rnd() * Math.PI;
        g.add(seam);
    }
    return g;
}

function buildNextLavaModelTypeStep() {
    if (lavaModelBuildStepIndex >= LAVA_MODEL_BUILD_STEP_COUNT) return false;
    const step = lavaModelBuildStepIndex;
    if (step === 0) lavaCacheParts(lavaTypeCache.volcano, buildLavaVolcano(801));
    else if (step === 1) lavaCacheParts(lavaTypeCache.volcano, buildLavaVolcano(817));
    else if (step === 2) lavaCacheParts(lavaTypeCache.volcano, buildLavaVolcano(829));
    else if (step === 3) lavaCacheParts(lavaTypeCache.obsidian, buildObsidianSpires(841));
    else if (step === 4) lavaCacheParts(lavaTypeCache.obsidian, buildObsidianSpires(853));
    else if (step === 5) lavaCacheParts(lavaTypeCache.geyser, buildLavaGeyser(863));
    else if (step === 6) lavaCacheParts(lavaTypeCache.ashtree, buildAshTree(877));
    else if (step === 7) lavaCacheParts(lavaTypeCache.ashtree, buildAshTree(883));
    else if (step === 8) lavaCacheParts(lavaTypeCache.basalt, buildBasaltColumns(897));
    else if (step === 9) lavaCacheParts(lavaTypeCache.basalt, buildBasaltColumns(911));
    else {
        for (const [seed, seg] of [[921, 7], [937, 6], [949, 7], [967, 6], [971, 8]]) {
            const geo = makeLavaPeakGeo(seed, seg);
            lavaModelGeoms.push(geo);
            lavaTypeCache.peak.push(geo);
        }
    }
    lavaModelBuildStepIndex++;
    return true;
}

function ensureLavaModelTypes() {
    while (buildNextLavaModelTypeStep()) {}
}

