function createWaterCargoShipModel() {
    const group = new THREE.Group();

    const hull = new THREE.Mesh(geoms.cargoHull, mats.oilPlatformMetal);
    hull.position.y = 3.0;
    group.add(hull);

    // Sivri pruva: 3 kenarlı prizma; three.js silindirinde ilk köşe +Z'de → +X'e çevir
    const bow = new THREE.Mesh(geoms.cargoBow, mats.oilPlatformMetal);
    bow.position.set(39.5, 3.0, 0);
    bow.rotation.y = Math.PI / 2;
    bow.scale.set(1.0, 1.0, 1.15);
    group.add(bow);

    const bridge = new THREE.Mesh(geoms.cargoBridge, mats.lighthouseWhite);
    bridge.position.set(-28, 12.75, 0);
    group.add(bridge);

    const bridgeTop = new THREE.Mesh(geoms.cargoBridgeTop, mats.oilPlatformDeck);
    bridgeTop.position.set(-28, 19.9, 0);
    group.add(bridgeTop);

    const funnel = new THREE.Mesh(geoms.cargoFunnel, mats.lighthouseRed);
    funnel.position.set(-31.5, 23.4, 0);
    group.add(funnel);

    const mastBow = new THREE.Mesh(geoms.cargoMastThin, mats.oilPlatformMetal);
    mastBow.position.set(33.5, 11.2, 0);
    group.add(mastBow);

    // Konteyner yükü: 3 materyal kovası, 5 sütun × 3 sıra × 2 kat rastgele doluluk
    const buckets = [[], [], []];
    for (let col = 0; col < 5; col++) {
        for (let row = -1; row <= 1; row++) {
            if (Math.random() < 0.22) continue;
            const x = -16 + col * 9.8;
            const z = row * 4.9;
            buckets[Math.floor(Math.random() * 3)].push({ x, y: 8.35, z });
            if (Math.random() < 0.45) {
                buckets[Math.floor(Math.random() * 3)].push({ x, y: 11.55, z });
            }
        }
    }
    const cargoMats = [mats.waterContainerRed, mats.waterContainerBlue, mats.waterContainerYellow];
    buckets.forEach((placements, i) => {
        if (placements.length) addInstancedDecor(group, geoms.waterContainer, cargoMats[i], placements);
    });

    group.userData = {
        lavaDecor: true,
        decorType: 'water_cargo_ship',
        waterThemed: true
    };
    return group;
}

function createSnowPineClusterModel() {
    const group = new THREE.Group();
    const count = 6 + Math.floor(Math.random() * 5);
    const trunkPlacements = [];
    const branchPlacements = [];
    const capPlacements = [];
    const pineParent = new THREE.Object3D();
    const pineChild = new THREE.Object3D();

    function pushPinePlacement(target, x, z, s, childY, childScale, childRotY = 0) {
        pineParent.position.set(x, 0, z);
        pineParent.rotation.set(0, 0, 0);
        pineParent.scale.setScalar(s);
        pineChild.position.set(0, childY, 0);
        pineChild.rotation.set(0, childRotY, 0);
        pineChild.scale.set(childScale[0], childScale[1], childScale[2]);
        pineParent.add(pineChild);
        pineParent.updateMatrixWorld(true);
        target.push({ matrix: pineChild.matrixWorld.clone() });
        pineParent.remove(pineChild);
    }

    for (let i = 0; i < count; i++) {
        const x = (Math.random() - 0.5) * 44;
        const z = (Math.random() - 0.5) * 30;
        const s = 1.15 + Math.random() * 0.7;
        pushPinePlacement(trunkPlacements, x, z, s, 3.1, [1, 1, 1]);

        for (let layer = 0; layer < 3; layer++) {
            const branchY = 5.2 + layer * 2.25;
            const branchScale = 1.0 - layer * 0.18;
            const branchRotY = Math.random() * Math.PI;
            pushPinePlacement(branchPlacements, x, z, s, branchY, [branchScale, 1.0, branchScale], branchRotY);

            const capScale = 0.78 - layer * 0.13;
            pushPinePlacement(capPlacements, x, z, s, branchY + 0.28, [capScale, 0.22, capScale], branchRotY + 0.22);
        }
    }
    addInstancedDecor(group, geoms.snowPineTrunk, mats.snowPineTrunk, trunkPlacements, { castShadow: true });
    addInstancedDecor(group, geoms.snowPineBranch, mats.snowPineNeedle, branchPlacements, { castShadow: true });
    addInstancedDecor(group, geoms.snowPineBranch, mats.snowCap, capPlacements);
    group.userData = { snowThemed: true, decorType: 'snow_pine', pulseSeed: Math.random() * Math.PI * 2, pulseAmp: 0.12 };
    return group;
}

