function createSnowIglooModel() {
    const group = new THREE.Group();
    const dome = new THREE.Mesh(geoms.snowIgloo, mats.snowCap);
    dome.scale.set(9.2, 6.6, 9.2);
    dome.position.y = 0.15;
    dome.castShadow = true;
    dome.receiveShadow = true;
    group.add(dome);

    const door = new THREE.Mesh(geoms.snowIglooDoor, mats.snowRockDark);
    door.position.set(0, 1.45, -8.55);
    door.castShadow = true;
    group.add(door);

    const blockPlacements = [];
    for (let i = 0; i < 7; i++) {
        blockPlacements.push({
            x: (i - 3) * 2.0,
            y: 3.1 + Math.abs(i - 3) * 0.34,
            z: -8.78,
            rz: (i - 3) * 0.08
        });
    }
    addInstancedDecor(group, geoms.snowIglooBlock, mats.snowRock, blockPlacements);

    const base = new THREE.Mesh(geoms.snowDrift, mats.snowCap);
    base.scale.set(11.5, 0.95, 10.5);
    base.position.y = -0.48;
    group.add(base);
    group.userData = { snowThemed: true, decorType: 'snow_igloo', pulseSeed: Math.random() * Math.PI * 2, pulseAmp: 0.1 };
    return group;
}

function createSnowMountainModel() {
    // v2 (2026-07-10): düz lavaSpire konileri yerine jitter'lı organik zirveler
    // (lavaTypeCache.peak, taban-orijinli) + zirveyi saran karlı tepe katmanı.
    // Materyaller tema-seti içinde (snowRock/Dark/Cap) — kar-only tip, tema-swap görmez.
    ensureLavaModelTypes();
    const P = lavaTypeCache.peak;
    const group = new THREE.Group();
    const layouts = [
        { x: -22, z: -8, sx: 20, sy: 86, sz: 22 },
        { x: 4, z: 4, sx: 28, sy: 122, sz: 30 },
        { x: 30, z: 10, sx: 18, sy: 76, sz: 20 }
    ];
    layouts.forEach((p, idx) => {
        const yaw = Math.random() * Math.PI * 2;
        const body = new THREE.Mesh(P[(idx * 2 + 1) % P.length], idx === 1 ? mats.snowRock : mats.snowRockDark);
        body.scale.set(p.sx, p.sy, p.sz);
        body.position.set(p.x, -3, p.z);
        body.rotation.y = yaw;
        group.add(body);

        // Karlı tepe: taban-orijinli küçük zirve, gövde ucunu sarar (gövde o yükseklikte
        // ~%26 yarıçapa inmişken kap %66 ile üstünü örter)
        const capH = p.sy * 0.26;
        const cap = new THREE.Mesh(P[(idx * 2 + 3) % P.length], mats.snowCap);
        cap.scale.set(p.sx * 0.66, capH, p.sz * 0.66);
        cap.position.set(p.x, p.sy - 3 - capH * 0.96, p.z);
        cap.rotation.y = yaw + 0.16;
        group.add(cap);

        if (idx === 1) {
            const ice = new THREE.Mesh(geoms.snowCrystal, mats.snowIce);
            ice.scale.set(3.2, 18, 2.2);
            ice.position.set(p.x + 7, p.sy * 0.46, p.z - 5);
            ice.rotation.z = -0.18;
            group.add(ice);
        }
    });
    group.userData = { snowThemed: true, decorType: 'snow_mountain', pulseSeed: Math.random() * Math.PI * 2, pulseAmp: 0.22 };
    return group;
}

// KAR v3 YENİ MODELLER (2026-07-10): kardan adam / buzdağı / buz katedrali / donmuş ağaç.
// Kar-only tipler tema-swap görmez; tüm geometriler geoms.* veya lavaTypeCache.peak cache'inden.
