function makeSkyPeakGeo(rnd, radialSeg) {
    // Birim koni (taban orijinli) + jitter + yükseklik-bazlı vertex color (kayalık → karlı zirve)
    const geo = new THREE.ConeGeometry(1, 1, radialSeg, 4, true);
    geo.translate(0, 0.5, 0);
    const pos = geo.attributes.position;
    const col = new Float32Array(pos.count * 3);
    const cBase = new THREE.Color(0x54637c), cMid = new THREE.Color(0x76879e), cSnow = new THREE.Color(0xeef3fa), tmp = new THREE.Color();
    for (let i = 0; i < pos.count; i++) {
        const t = Math.max(0, Math.min(1, pos.getY(i)));
        if (t < 0.96) {
            pos.setX(i, pos.getX(i) * (1 + (rnd() - 0.5) * 0.26));
            pos.setZ(i, pos.getZ(i) * (1 + (rnd() - 0.5) * 0.26));
        }
        const snowEdge = 0.56 + (rnd() - 0.5) * 0.14;
        if (t > snowEdge) tmp.copy(cSnow);
        else if (t > 0.3) tmp.copy(cMid).lerp(cBase, rnd() * 0.5);
        else tmp.copy(cBase);
        col[i * 3] = tmp.r; col[i * 3 + 1] = tmp.g; col[i * 3 + 2] = tmp.b;
    }
    geo.setAttribute('color', new THREE.BufferAttribute(col, 3));
    geo.computeVertexNormals();
    geo.computeBoundingSphere();
    return geo;
}

function ensureSkyModelTypes() {
    if (skyTypeCache.tower.length) return;
    skyCacheParts(skyTypeCache.tower, buildSkyTower(601, 150, 24, 18, mats.skyScraperNeonA, 'crown'));
    skyCacheParts(skyTypeCache.tower, buildSkyTower(617, 200, 22, 17, mats.skyScraperNeonC, 'tank'));
    skyCacheParts(skyTypeCache.tower, buildSkyTower(631, 240, 26, 20, mats.skyScraperNeonB, 'helipad'));
    skyCacheParts(skyTypeCache.tower, buildSkyTower(647, 380, 28, 22, mats.skyScraperNeonA, 'antenna'));
    skyCacheParts(skyTypeCache.tower, buildSkyZiggurat(659, 260, 34, 26, mats.skyScraperNeonC));
    skyCacheParts(skyTypeCache.tower, buildSkyTwinTowers(673, 300, 38, 18, mats.skyScraperNeonB));
    skyCacheParts(skyTypeCache.tower, buildSkyArcology(683, 285, 38, 30, mats.skyScraperNeonA));
    skyCacheParts(skyTypeCache.tower, buildSkyArcology(691, 360, 44, 34, mats.skyScraperNeonB));
    skyTypeCache.balloon = skyCacheParts([], buildSkyBalloonModel());
    skyTypeCache.blimp = skyCacheParts([], buildSkyBlimpModel());
    skyTypeCache.plane = skyCacheParts([], buildSkyPlaneModel());
    for (const seed of [701, 719, 733]) {
        const rnd = natSeedRand(seed);
        const v = {
            main: makeSkyPeakGeo(rnd, 7),
            sideA: makeSkyPeakGeo(rnd, 6),
            sideB: makeSkyPeakGeo(rnd, 5),
            aOff: { x: -(0.32 + rnd() * 0.12), s: 0.45 + rnd() * 0.2, z: 0.12 + rnd() * 0.18 },
            bOff: { x: 0.28 + rnd() * 0.18, s: 0.4 + rnd() * 0.2, z: -(0.1 + rnd() * 0.2) }
        };
        skyModelGeoms.push(v.main, v.sideA, v.sideB);
        skyTypeCache.mountain.push(v);
    }
}

function instantiateSkyParts(parts) {
    const g = new THREE.Group();
    for (const p of parts) {
        const m = new THREE.Mesh(p.geo, p.mat);
        m.castShadow = false;
        m.receiveShadow = false;
        g.add(m);
    }
    return g;
}

function createSkySkyscraper() {
    ensureSkyModelTypes();
    const list = skyTypeCache.tower;
    const group = instantiateSkyParts(list[Math.floor(Math.random() * list.length)]);
    // Boyut çeşitliliği: taban ölçek + bağımsız dikey esneme (pencere oranı mesafede fark edilmez)
    group.scale.setScalar(0.8 + Math.random() * 0.5);
    group.scale.y *= 0.85 + Math.random() * 0.4;
    group.rotation.y = (Math.random() - 0.5) * 0.5;
    group.userData = {
        skyDecor: true,
        decorType: 'skyscraper',
        // Follow the visual curve at the root but preserve the building's up
        // axis. Pitching a 300m tower around its base looked like mesh animation.
        elementalCurveKeepUpright: true
    };
    return group;
}

