    const aScale = mainScale * v.aOff.s;
    const sideA = new THREE.Mesh(v.sideA, mats.skyMountainVC);
    sideA.scale.set(aScale * 0.7, aScale, aScale * 0.7);
    sideA.position.set(mainScale * v.aOff.x, 0, mainScale * v.aOff.z);
