function initializeSkyStreamFade(object) {
    if (!object) return object;
    object.userData = object.userData || {};
    // The curve adapter translates sky scenery around one stable root anchor.
    // Keeping that root upright prevents cloud/tower rotation from being
    // mistaken for a second position correction while curvature blends.
    object.userData.elementalCurveKeepUpright = true;
    object.userData.elementalSkyStableAnchor = true;
    if (!object.userData.skyStreamBaseScale) {
        object.userData.skyStreamBaseScale = {
            x: object.scale.x,
            y: object.scale.y,
            z: object.scale.z
        };
    }
    object.userData.skyStreamAlpha = 0;
    object.userData.skyStreamEnvelopeVersion = 2;
    const base = object.userData.skyStreamBaseScale;
    object.scale.set(base.x * 0.001, base.y * 0.001, base.z * 0.001);
    object.visible = false;
    return object;
}

function smoothSkyStreamStep(value) {
    const t = Math.max(0, Math.min(1, value));
    return t * t * (3 - 2 * t);
}

function updateSkyStreamFade(object, distanceAhead, fullAhead, zeroAhead, fullBehind, zeroBehind, active = true) {
    if (!object) return 0;
    if (!object.userData?.skyStreamBaseScale) initializeSkyStreamFade(object);
    let alpha = active ? 1 : 0;
    if (alpha > 0 && distanceAhead > fullAhead) {
        alpha *= 1 - smoothSkyStreamStep((distanceAhead - fullAhead) / Math.max(1, zeroAhead - fullAhead));
    }
    if (alpha > 0 && distanceAhead < fullBehind) {
        alpha *= smoothSkyStreamStep((distanceAhead - zeroBehind) / Math.max(1, fullBehind - zeroBehind));
    }
    const base = object.userData.skyStreamBaseScale;
    const visualScale = Math.max(0.001, alpha);
    object.scale.set(base.x * visualScale, base.y * visualScale, base.z * visualScale);
    object.userData.skyStreamAlpha = alpha;
    object.userData.skyStreamDistanceAhead = distanceAhead;
    const band = object.userData.skyStreamBand || (object.userData.skyStreamBand = {});
    band.fullAhead = fullAhead;
    band.zeroAhead = zeroAhead;
    band.fullBehind = fullBehind;
    band.zeroBehind = zeroBehind;
    object.visible = alpha > 0.01;
    return alpha;
}

function clearSkyDecor() {
    skyInitialFill = null;
    for (let i = 0; i < skyDecorObjects.length; i++) {
        disposeNode(skyDecorObjects[i]);
    }
    skyDecorObjects = [];
}

function isSkyDecorAnchor(obj) {
    // hareketli dekorlar (uçak/balon/zeplin) çapa sayılmaz — kapsama hesabını şişirmesinler
    const t = obj && obj.userData && obj.userData.skyDecor ? obj.userData.decorType : null;
    return !!t && t !== 'plane' && t !== 'balloon' && t !== 'blimp';
}

function countSkyDecorAnchorsInRange(minX, maxX) {
    let count = 0;
    for (let i = 0; i < skyDecorObjects.length; i++) {
        const obj = skyDecorObjects[i];
        if (isSkyDecorAnchor(obj) && obj.position.x >= minX && obj.position.x <= maxX) count++;
    }
    return count;
}

function removeSkyDecorAtIndex(index) {
    const obj = skyDecorObjects[index];
    if (obj) disposeNode(obj);
    skyDecorObjects.splice(index, 1);
}

function ensureSkyDecorCoverage() {
    if (!player) return;

    const minX = player.position.x - SKY_DECOR_NEAR_BEHIND;
    const maxX = player.position.x + SKY_DECOR_NEAR_AHEAD;
    let anchors = countSkyDecorAnchorsInRange(minX, maxX);
    let guard = 0;

    while (
        anchors < SKY_DECOR_MIN_NEAR_ANCHORS &&
        skyDecorObjects.length < SKY_DECOR_MAX_COUNT - 4 &&
        guard < SKY_DECOR_BACKFILL_MAX && takeSkyStreamWork('decor', 2)
    ) {
        const spawnX = player.position.x + SKY_DECOR_BACKFILL_START_AHEAD + guard * SKY_DECOR_BACKFILL_STEP + Math.random() * 120;
        const needsMountain = countSkyMountains() < getSkyMountainTargetCount();
        const needsSkyscraper = countSkySkyscrapers() < SKY_DECOR_MIN_SKYSCRAPERS;
        const forceType = needsSkyscraper || (!needsMountain && guard % 3 !== 2) ? 'skyscraper' : 'mountain';
        spawnSkyDecorAt(spawnX, forceType);
        nextSkyDecorSpawnX = Math.max(nextSkyDecorSpawnX, spawnX + SKY_DECOR_STEP_MIN);
        anchors += 2;
        guard++;
    }
}

function pruneSkyDecorOverflow(maxDecor) {
    if (skyDecorObjects.length <= maxDecor || !player) return;

    for (let pass = 0; pass < 3 && skyDecorObjects.length > maxDecor; pass++) {
        for (let i = skyDecorObjects.length - 1; i >= 0 && skyDecorObjects.length > maxDecor; i--) {
            const obj = skyDecorObjects[i];
            if (!obj) {
                skyDecorObjects.splice(i, 1);
                continue;
            }
            const type = obj.userData && obj.userData.decorType;
            const farBehind = obj.position.x < player.position.x - (pass === 0 ? 900 : pass === 1 ? 560 : 260);
            const lowPriority = pass === 0 ? (type === 'plane' || type === 'balloon' || type === 'blimp') : true;
            if (farBehind && lowPriority) removeSkyDecorAtIndex(i);
        }
    }
}

// Dekor objesinin Z yarı genişliği. Obje henüz sahneye eklenmemiş ve konumlandırılmamışken
// çağrılır → setFromObject yerel dönüşümleri kullanır, sonuç saf boyut olur.
// Yalnızca dağ spawn'ında çalışır (fill başına ~18 kez), sıcak döngüde değil.
const _skyDecorBox = new THREE.Box3();
const _skyDecorSize = new THREE.Vector3();
function getSkyDecorHalfZ(obj) {
    _skyDecorBox.setFromObject(obj);
    _skyDecorBox.getSize(_skyDecorSize);
    return Math.max(1, _skyDecorSize.z * 0.5);
}

function spawnSkyDecorAt(spawnX, forcedType = null, sides = null) {
    let spawnedAny = false;
    const resolvedSpawnX = player
        ? Math.max(spawnX, player.position.x + SKY_DECOR_MIN_SAFE_AHEAD)
        : spawnX;
    const sideList = Array.isArray(sides) && sides.length > 0 ? sides : [-1, 1];
    for (const side of sideList) {
        let type = forcedType;
        if (!type) {
            const canSpawnMountain = countSkyMountains() < getSkyMountainTargetCount();
            // Gökdelen açığı varsa olasılığı YÜKSELT — eskiden `needsSkyscraper` %100'e
            // ZORLUYORDU. Boş listeden doldururken bu, ilk ~14 adımı tamamen gökdelen
            // yapıp 28'e ulaşınca aniden çeşitlendiriyordu; yakın/uzak arasında görünür
            // bir tip sıçraması oluyordu. Yumuşak ağırlık aynı minimumu garanti eder.
            const scChance = countSkySkyscrapers() < SKY_DECOR_MIN_SKYSCRAPERS ? 0.78 : 0.60;
            const r = Math.random();
            if (r < scChance) type = 'skyscraper';
            else {
                // Kalan payı orijinal oranlarla böl (dağ/balon/uçak/blimp), böylece
                // scChance değişse de tipler arası denge korunur.
                const q = (r - scChance) / (1 - scChance);
                if (canSpawnMountain && q < 0.55) type = 'mountain';
                else if (q < 0.73) type = 'balloon';
                else if (q < 0.83) type = 'plane';
                else if (q < 0.91) type = 'blimp';
                else type = canSpawnMountain && Math.random() > 0.5 ? 'mountain' : 'skyscraper';
            }
        }

        let obj = null;

        if (type === 'skyscraper') {
            obj = createSkySkyscraper();
            const z = side * (SKY_SKYSCRAPER_Z_MIN + Math.random() * (SKY_SKYSCRAPER_Z_MAX - SKY_SKYSCRAPER_Z_MIN));
            const y = SKY_LAYER_Y - (80 + Math.random() * 60);
            obj.position.set(resolvedSpawnX + (Math.random() - 0.5) * 80, y, z);
        } else if (type === 'plane') {
            obj = createSkyPlane();
            const z = side * (180 + Math.random() * 180);
            const y = SKY_LAYER_Y + 90 + Math.random() * 210;
            obj.position.set(resolvedSpawnX + (100 + Math.random() * 160), y, z);
            obj.rotation.y = side > 0 ? Math.PI * 0.92 : -Math.PI * 0.92;
            obj.userData.baseY = y;
        } else if (type === 'balloon') {
            obj = createSkyBalloon();
            const z = side * (170 + Math.random() * 240);
            const y = SKY_LAYER_Y + 40 + Math.random() * 180;
            obj.position.set(resolvedSpawnX + (Math.random() - 0.5) * 120, y, z);
            obj.userData.baseY = y;
        } else if (type === 'blimp') {
            obj = createSkyBlimp();
            const z = side * (260 + Math.random() * 260);
            const y = SKY_LAYER_Y + 110 + Math.random() * 160;
            obj.position.set(resolvedSpawnX + Math.random() * 160, y, z);
            obj.rotation.y = side > 0 ? Math.PI : 0; // reklam panosu yola baksın
            obj.userData.baseY = y;
        } else {
            obj = createSkyMountain();
            // Z, dağın KENDİ yarı genişliğinden türetilir: iç kenarı gökdelen bandını asla
            // kesmez. Sabit aralık kullanmak (eski 420-320) geniş dağlarda gökdelenleri
            // yutuyordu — genişlik mainScale ile 2 kat değişebiliyor.
            const halfZ = getSkyDecorHalfZ(obj);
            const zInner = SKY_SKYSCRAPER_Z_MAX + halfZ + SKY_DECOR_Z_GAP;
            const z = side * (zInner + Math.random() * SKY_MOUNTAIN_Z_SPREAD);
            const y = SKY_LAYER_Y - (200 + Math.random() * 140);
            obj.position.set(resolvedSpawnX + (Math.random() - 0.5) * 100, y, z);
            obj.userData.halfZ = halfZ;
        }

        if (!obj) continue;
        curvedPathSystem?.prepareObjectVisibility?.(obj);
        if (type === 'skyscraper' || type === 'mountain') {
            curvedPathSystem?.stabilizeObjectBounds?.(obj, {
                lateralPadding: type === 'mountain' ? 260 : 90,
                verticalPadding: type === 'mountain' ? 320 : 420
            });
        }
        cacheCurvedGroundContactSpan(obj, type === 'mountain' ? 180 : 90);
        initializeSkyStreamFade(obj);
        scene.add(obj);
        skyDecorObjects.push(obj);
        spawnedAny = true;
    }
    if (spawnedAny) requestShadowMapRefresh(spawnX);
}

// Dekorun TEK adım mantığı — hem ilk doldurma hem canlı spawn bunu kullanır.
// Ayrı kalırlarsa yoğunlukları sapar (bkz. fillInitialSkyDecor notu).
//
// HİÇBİR TİPİ ZORLAMA: sert zorlama (eski `forceType`) o tipten bitişik bir BLOK üretir ve
// diğer tipte görünür bir DELİK bırakır — ölçümde gökdelen kovası tam 0'a düşmüştü
// (2600-3250 aralığı boş). Minimumlar artık iki mekanizmayla tutuluyor:
//   1) spawnSkyDecorAt içindeki olasılık ağırlığı (açık varsa gökdelen %60→%78) ve
//      `canSpawnMountain` (her taraf için yeniden ölçülür → dağ hedefini aşmaz),
//   2) fillInitialSkyDecor sonundaki dağ tamamlama döngüsü.
function spawnSkyDecorStep(atX) {
    spawnSkyDecorAt(atX, null, null);
}

function fillInitialSkyDecor(playerX) {
    clearSkyDecor();
    // TEK SPAWN YOLU (2026-07-17 düzeltmesi). Eskiden giriş bölgesi ELLE yerleştiriliyordu
    // (gökdelen arası ~440 birim: 680/1120/1580/2060) ama devamındaki prosedürel dolgu
    // STEP_MIN+rand (~116 birim) kullanıyordu → oyuncu önce seyrek, ~2600'den sonra aniden
    // yoğun silüet görüyordu. Ölçüldü (sky-density-diag.js): kova başına 2 vs 14, oran 14x.
    // Artık ilk doldurma updateSkyDecor ile AYNI adımı ve AYNI tip mantığını kullanıyor.
    // DİKKAT: iki yol tekrar ayrışırsa aynı bug geri gelir — ortak spawnSkyDecorStep'i koru.
    nextSkyDecorSpawnX = playerX + SKY_DECOR_MIN_SAFE_AHEAD;
    // The same cursor is consumed a few rows per frame by updateSkyDecor.
    // Never build the entire 5200-unit corridor inside a jump-pad collision.
}

function updateSkyDecor(delta, allowSpawn = true) {
    const spawnAhead = player.position.x + SKY_DECOR_SPAWN_AHEAD;
    if (allowSpawn && nextSkyDecorSpawnX < player.position.x + 220) {
        nextSkyDecorSpawnX = player.position.x + SKY_DECOR_BACKFILL_START_AHEAD;
    }

    while (allowSpawn && nextSkyDecorSpawnX < spawnAhead && takeSkyStreamWork('decor', 2)) {
        // İlk doldurma ile AYNI yardımcı — mantık burada kopyalanırsa iki yol sapar.
        spawnSkyDecorStep(nextSkyDecorSpawnX);
        nextSkyDecorSpawnX += SKY_DECOR_STEP_MIN + Math.random() * SKY_DECOR_STEP_RANDOM;
    }

    if (allowSpawn && nextSkyDecorSpawnX >= spawnAhead &&
        countSkyMountains() < getSkyMountainTargetCount() && takeSkyStreamWork('decor', 2)) {
        const deficit = getSkyMountainTargetCount() - countSkyMountains();
        spawnSkyDecorAt(nextSkyDecorSpawnX, 'mountain', deficit === 1 ? [Math.random() > 0.5 ? 1 : -1] : null);
        nextSkyDecorSpawnX += SKY_DECOR_STEP_MIN + Math.random() * SKY_DECOR_STEP_RANDOM;
    }

    const time = clock.getElapsedTime();
    const maxAhead = player.position.x + (allowSpawn ? SKY_DECOR_CULL_AHEAD : SKY_DECOR_CULL_AHEAD + 1800);
    const cullBehind = player.position.x - (allowSpawn ? SKY_DECOR_CULL_BEHIND : SKY_DECOR_CULL_BEHIND + 900);
    for (let i = skyDecorObjects.length - 1; i >= 0; i--) {
        const obj = skyDecorObjects[i];
        if (!obj) continue;

        // FPS: sis penceresi dışındaki dekoru çizme (dağ silüetleri dev — daha geniş pencere)
        const ddx = obj.position.x - player.position.x;
        const isMountain = obj.userData && obj.userData.decorType === 'mountain';
        const fullAhead = isMountain ? SKY_MOUNTAIN_STREAM_FULL_AHEAD : SKY_DECOR_STREAM_FULL_AHEAD;
        const zeroAhead = isMountain ? SKY_MOUNTAIN_STREAM_ZERO_AHEAD : SKY_DECOR_STREAM_ZERO_AHEAD;
        const skyActive = skyAlpha > 0.2 || onSkyLayer;
        updateSkyStreamFade(
            obj,
            ddx,
            fullAhead,
            zeroAhead,
            SKY_DECOR_STREAM_FULL_BEHIND,
            SKY_DECOR_STREAM_ZERO_BEHIND,
            skyActive
        );

        const moverType = obj.userData && obj.userData.decorType;
        if (moverType === 'plane' || moverType === 'balloon' || moverType === 'blimp') {
            obj.position.x += obj.userData.speedX * delta;
            obj.position.z += obj.userData.driftZ * delta;
            obj.position.y = obj.userData.baseY + Math.sin(time * (moverType === 'balloon' ? 0.6 : 1.2) + obj.userData.bobSeed) * obj.userData.bobAmp;
        }

        if (obj.position.x < cullBehind || obj.position.x > maxAhead || Math.abs(obj.position.z) > SKY_DECOR_Z_CULL) {
            removeSkyDecorAtIndex(i);
        }
    }

    if (allowSpawn && nextSkyDecorSpawnX >= spawnAhead) ensureSkyDecorCoverage();

    const maxDecor = SKY_DECOR_MAX_COUNT;
    pruneSkyDecorOverflow(maxDecor);
}

function takeSkyStreamWork(kind, limit) {
    if (skyStreamBudget[kind] >= limit || performance.now() >= skyStreamBudget.deadline) return false;
    skyStreamBudget[kind]++;
    return true;
}

function fillInitialSkyMap(playerX) {
    fillInitialSkyDecor(playerX);
    // Absolute coordinates survive floating-origin shifts while the queue drains.
    skyInitialFill = { origin: playerX + worldScrollX, cloudOffset: -400, smallOffset: -400 };
    nextSkySpawnX = playerX + 2800;
    window.nextSmallCloudX = playerX + 2800;
    nextCloudFloorX = playerX + 2800;
}

function processInitialSkyMapFill() {
    if (!skyInitialFill) return;
    const fill = skyInitialFill;
    const playerX = fill.origin - worldScrollX;
    // SPAWN MESAFESÄ° UZATILDI: 1400 yerine 2800'e Ã§ekilerek aniden belirmeleri engellendi
    while (fill.cloudOffset <= 2800 && takeSkyStreamWork('cloud', 4)) {
        const i = fill.cloudOffset;
        fill.cloudOffset += 40;
        for(let side=0; side<2; side++) {
            if (Math.random() > 0.1) {
                const cloud = createCloudCluster();
                const zOffset = 90 + Math.random() * 250; 
                const z = (side === 0 ? -1 : 1) * zOffset;
                const y = SKY_LAYER_Y + 20 + Math.random() * 480; 
                
                cloud.position.set(playerX + i, y, z);
                cloud.userData = { rotSpeed: (Math.random()-0.5) * 0.2 };
                initializeSkyStreamFade(cloud);
                cloud.renderOrder = 2;
                scene.add(cloud);
                skyObjects.push(cloud);
            }
        }
    }

    while (fill.smallOffset <= 2800 && takeSkyStreamWork('small', 6)) {
        const j = fill.smallOffset;
        fill.smallOffset += 80;
        if (Math.random() < 0.7) {
            const cloud = new THREE.Mesh(geoms.smallCloud, mats.smallCloud);
            
            // KÃœÃ‡ÃœK BULUTLARIN BASIKLIÄI DÃœZELTÄ°LDÄ°: * 0.6 yerine (0.9 + Math.random() * 0.2)
            const baseScale = 0.8 + Math.random() * 1.5;
            cloud.scale.set(baseScale * (0.8 + Math.random() * 0.4), baseScale * (0.9 + Math.random() * 0.2), baseScale * (0.8 + Math.random() * 0.4));
            
            const x = playerX + j + Math.random() * 50;
            const y = SKY_LAYER_Y + 20 + Math.random() * 380; 
                
            const minSafeDist = 90; 
            const maxDist = 250;
            const side = Math.random() > 0.5 ? 1 : -1;
            const z = side * (minSafeDist + Math.random() * (maxDist - minSafeDist));
            
            cloud.position.set(x, y, z);
            cloud.rotation.set((Math.random() - 0.5) * 0.2, Math.random() * Math.PI, (Math.random() - 0.5) * 0.2);
            initializeSkyStreamFade(cloud);
            cloud.renderOrder = 2;
            scene.add(cloud);
            skyClouds.push(cloud);
        }
    }

    if (fill.cloudOffset > 2800 && fill.smallOffset > 2800) skyInitialFill = null;
 }

function updateSky(delta) {
        if (gamePhase < 2) return;

        if (!isSkyFading && !onSkyLayer && !lavaDropTransitionActive) return;
        const freezeSkyScenery = lavaDropTransitionActive && !lavaMapActivated;
        skyStreamBudget.deadline = performance.now() + 3;
        skyStreamBudget.cloud = skyStreamBudget.small = skyStreamBudget.decor = skyStreamBudget.plane = 0;
        if (!freezeSkyScenery) processInitialSkyMapFill();

        // GÃ¶kyÃ¼zÃ¼ne Ã§Ä±kÄ±ÅŸ animasyonu (Jump Pad ile uÃ§arken)
        if (isSkyFading) {
            skyAlpha += delta * 0.5; 
            
            // YENİ EKLENDİ: skyAlpha artarken yolun opacity deÄŸerini de gÃ¼ncelle
            if (skyFloor && skyFloor.material.transparent) {
                skyFloor.material.opacity = skyAlpha; 
            }
            
            if (skyAlpha >= 1.0) {
                skyAlpha = 1.0;
                isSkyFading = false;
                if (skyFloor) {
                    skyFloor.material.opacity = 1.0; // Garantilemek iÃ§in eklendi
                    skyFloor.material.transparent = false;
                }
            }
            
            if (skyBarriers.length > 0) {
                skyBarriers.forEach(b => setObjectOpacity(b, skyAlpha));
            }

            if (skyLines && skyLines.mesh && skyLines.mesh.material) {
                skyLines.mesh.material.opacity = skyAlpha;
                if (skyAlpha >= 1.0) {
                    skyLines.mesh.material.transparent = false; 
                }
            }
        }

        if (isSkyFading || onSkyLayer) {
            if (mats.cloud && mats.cloud.opacity < 0.65) {
                mats.cloud.opacity += delta * 0.15;
            }
            if (mats.smallCloud && mats.smallCloud.opacity < 0.65) {
                mats.smallCloud.opacity += delta * 0.15;
            }
            if (skyCloudFloor) {
                skyCloudFloor.visible = true;
                skyCloudFloor.children.forEach(mesh => {
                    const target = mesh.material.userData.targetOpacity;
                    if (mesh.material.opacity < target) {
                        mesh.material.opacity += delta * 0.4;
                    }
                });
            }
        } else {
            if (mats.cloud && mats.cloud.opacity > 0) {
                mats.cloud.opacity -= delta * 0.5;
            }
            if (mats.smallCloud && mats.smallCloud.opacity > 0) {
                mats.smallCloud.opacity -= delta * 0.5;
            }
            if (skyCloudFloor && skyCloudFloor.visible) {
                let allZero = true;
                skyCloudFloor.children.forEach(mesh => {
                    if (mesh.material.opacity > 0) {
                        mesh.material.opacity -= delta * 0.5;
                        allZero = false;
                    }
                });
                if (allZero) skyCloudFloor.visible = false;
            }
        }
        
        if (skyFloor) {
            if (lavaDropTransitionActive && !lavaMapActivated) {
                const leftX = lavaDropRoadStartX;
                const rightX = lavaDropCutoffX - 2.2;
                const roadLength = Math.max(85, rightX - leftX);
                const edgeLead = Math.max(0, lavaDropCutoffX - player.position.x);
                const collapseProgress = lavaDropInitialLead > 0
                    ? Math.max(0, Math.min(1, 1 - (edgeLead / lavaDropInitialLead)))
                    : 1;
                const fallDepth = Math.max(0, SKY_LAYER_Y - player.position.y);
                const dropFade = lavaDropStarted ? Math.max(0, 1 - (fallDepth / 70)) : 1;
                const roadAlpha = (0.9 - collapseProgress * 0.28) * dropFade;
                skyFloor.scale.x = roadLength / 2000;
                skyFloor.position.x = leftX + roadLength * 0.5;
                skyFloor.position.z = getRoadCenterZ();
                skyFloor.material.transparent = true;
                skyFloor.material.opacity = lavaDropStarted
                    ? roadAlpha
                    : Math.max(roadAlpha, skyFloor.material.opacity);
            } else {
                skyFloor.scale.x = 1;
                skyFloor.position.x = player.position.x;
                if (isAnimatingLane && onSkyLayer) {
                    syncSkyFloorForLaneAnimation(getLaneAnimationCurrentRoadEdgeZ());
                } else {
                    skyFloor.scale.z = 1;
                    skyFloor.position.z = getRoadCenterZ();
                }
            }
        }

        if (lavaDropTransitionActive && !lavaMapActivated) {
            const cutoffFade = Math.max(0, Math.min(1, (lavaDropCutoffX - player.position.x + 45) / 240));
            const edgeLead = Math.max(0, lavaDropCutoffX - player.position.x);
            const collapseProgress = lavaDropInitialLead > 0
                ? Math.max(0, Math.min(1, 1 - (edgeLead / lavaDropInitialLead)))
                : 1;
            const fallDepth = Math.max(0, SKY_LAYER_Y - player.position.y);
            const dropFade = lavaDropStarted ? Math.max(0, 1 - (fallDepth / 70)) : 1;
            if (skyLines && skyLines.mesh && skyLines.mesh.material) {
                skyLines.mesh.material.transparent = true;
                skyLines.mesh.material.opacity = lavaDropStarted
                    ? (0.16 + cutoffFade * 0.42 - collapseProgress * 0.08) * dropFade
                    : Math.max(0.58, skyLines.mesh.material.opacity || 0);
            }
            if (skyBarriers.length > 0) {
                const leftX = lavaDropRoadStartX;
                const rightX = lavaDropCutoffX - 2.2;
                const barrierLength = Math.max(40, rightX - leftX);
                skyBarriers.forEach((b, index) => {
                    b.scale.x = barrierLength / 3000;
                    b.scale.y = 1;
                    b.scale.z = 1;
                    b.position.x = leftX + barrierLength * 0.5;
                    b.position.y = SKY_LAYER_Y;
                    b.position.z = index === 0 ? getBarrierPositionZ(-1) : getBarrierPositionZ(1);
                    setObjectOpacity(b, lavaDropStarted
                        ? (0.28 + cutoffFade * 0.18 - collapseProgress * 0.12) * dropFade
                        : 1.0);
                });
            }
        } else if (skyBarriers.length > 0) {
            skyBarriers.forEach((b, index) => {
                b.scale.x = 1;
                b.scale.y = 1;
                b.scale.z = 1;
                b.position.y = SKY_LAYER_Y;
                b.position.z = index === 0 ? getBarrierPositionZ(-1) : getBarrierPositionZ(1);
            });
        }

        const spawnAhead = player.position.x + 3200 + (moveSpeed * 1800);
        
        // A stale/reset cursor must resume beyond the visible fade envelope.
        // Restarting at +50 used to generate a complete cloud corridor directly
        // in front of the player in one frame.
        if (!freezeSkyScenery && nextSkySpawnX < player.position.x) {
            nextSkySpawnX = player.position.x + SKY_CLOUD_STREAM_ZERO_AHEAD + 180;
        }

        while (!freezeSkyScenery && !skyInitialFill && nextSkySpawnX < spawnAhead && takeSkyStreamWork('cloud', 4)) {
            nextSkySpawnX += 20 + Math.random() * 28; 
            
            for(let side=0; side<2; side++) {
                if (Math.random() > 0.14) { 
                    const cloud = createCloudCluster();
                    const zOffset = 90 + Math.random() * 250; 
                    const z = (side === 0 ? -1 : 1) * zOffset;
                    
                    const y = SKY_LAYER_Y + 20 + Math.random() * 480;
                    
                    cloud.position.set(nextSkySpawnX, y, z);
                    cloud.userData = { rotSpeed: (Math.random()-0.5) * 0.2 };
                    initializeSkyStreamFade(cloud);
                    cloud.renderOrder = 2;
                    scene.add(cloud);
                    skyObjects.push(cloud);

                    if (skyBarriers.length > 0) {
                        skyBarriers.forEach(b => setObjectOpacity(b, skyAlpha));
                    }
            
                    // DEÄÄ°ÅTÄ°RÄ°LDÄ°: Spawn olan bulutlarÄ±n anlÄ±k opacity limitleri de dÃ¼ÅŸÃ¼rÃ¼ldÃ¼ (0.65)
                    if (mats.cloud) mats.cloud.opacity = skyAlpha * 0.65;
                    if (mats.smallCloud) mats.smallCloud.opacity = skyAlpha * 0.65; 
                }
            }
        }

        const minSkyClouds = 138;
        let refillGuard = 0;
        while (!freezeSkyScenery && !skyInitialFill && skyObjects.length < minSkyClouds && refillGuard < 46 && takeSkyStreamWork('cloud', 4)) {
            refillGuard++;
            const cloud = createCloudCluster();
            // Refill only in the invisible staging band. Creating a replacement
            // at +700 placed a full-size cloud inside the camera view.
            const x = player.position.x + SKY_CLOUD_STREAM_ZERO_AHEAD + 80 + Math.random() * 520;
            const y = SKY_LAYER_Y + 20 + Math.random() * 480;
            const side = Math.random() > 0.5 ? 1 : -1;
            const z = side * (90 + Math.random() * 250);
            cloud.position.set(x, y, z);
            cloud.userData = { rotSpeed: (Math.random() - 0.5) * 0.2 };
            initializeSkyStreamFade(cloud);
            scene.add(cloud);
            skyObjects.push(cloud);
        }

        for (let i = skyObjects.length - 1; i >= 0; i--) {
            const obj = skyObjects[i];

            // FPS (2026-07-05): sky sisi (~0.0028) 1200+ birimde her şeyi tamamen örtüyor —
            // görünmez uzaktaki bulut kümelerini çizme (küme başına 1 draw call tasarrufu).
            const cdx = obj.position.x - player.position.x;
            updateSkyStreamFade(
                obj,
                cdx,
                SKY_CLOUD_STREAM_FULL_AHEAD,
                SKY_CLOUD_STREAM_ZERO_AHEAD,
                SKY_CLOUD_STREAM_FULL_BEHIND,
                SKY_CLOUD_STREAM_ZERO_BEHIND,
                true
            );

            if (obj.visible && obj.userData.rotSpeed) {
                obj.rotation.y += obj.userData.rotSpeed * delta;
                obj.rotation.z += obj.userData.rotSpeed * 0.5 * delta;
            }

            if (obj.position.x < player.position.x - 900) {
                disposeNode(obj);
                skyObjects.splice(i, 1);
            }
        }

        // Dikdörtgen bulut strip'leri kaldırıldı
        for (let i = skyCloudFloorStrips.length - 1; i >= 0; i--) {
            if (skyCloudFloorStrips[i].position.x < player.position.x - 800) {
                scene.remove(skyCloudFloorStrips[i]);
                skyCloudFloorStrips[i].geometry.dispose();
                skyCloudFloorStrips[i].material.dispose();
                skyCloudFloorStrips.splice(i, 1);
            }
        }

        // UÃ§ak spawn sistemi
        if (isSkyFading || onSkyLayer) {
            // Maksimum 8 uÃ§ak aynÄ± anda
            const maxPlanes = 5;
            while (!freezeSkyScenery && skyPlanes.length < maxPlanes && takeSkyStreamWork('plane', 1)) {
                const plane = createSkyPlane();
                const y = SKY_LAYER_Y + 50 + Math.random() * 220;
                const moveType = Math.floor(Math.random() * 3);

                if (moveType === 0) {
                    // SaÄŸdan sola geÃ§iÅŸ (Z ekseninde)
                    plane.position.set(
                        player.position.x + 200 + Math.random() * 600,
                        y,
                        600 + Math.random() * 200
                    );
                    plane.rotation.y = Math.PI * 0.5;
                    plane.userData.speedX = (Math.random() - 0.5) * 4;
                    plane.userData.speedZ = -(55 + Math.random() * 40);
                    plane.userData.moveType = 0;
                } else if (moveType === 1) {
                    // Soldan saÄŸa geÃ§iÅŸ (Z ekseninde)
                    plane.position.set(
                        player.position.x + 200 + Math.random() * 600,
                        y,
                        -600 - Math.random() * 200
                    );
                    plane.rotation.y = -Math.PI * 0.5;
                    plane.userData.speedX = (Math.random() - 0.5) * 4;
                    plane.userData.speedZ = 55 + Math.random() * 40;
                    plane.userData.moveType = 1;
                } else {
                    // Ä°leriden arkaya (X ekseninde, oyuncuyu geÃ§iyor)
                    const side = Math.random() > 0.5 ? 1 : -1;
                    plane.position.set(
                        player.position.x + 800 + Math.random() * 400,
                        y,
                        side * (120 + Math.random() * 200)
                    );
                    plane.rotation.y = side > 0 ? Math.PI * 0.95 : -Math.PI * 0.95;
                    plane.userData.speedX = -(35 + Math.random() * 25);
                    plane.userData.speedZ = side * (Math.random() * 5);
                    plane.userData.moveType = 2;
                }

                plane.userData.baseY = y;
                plane.userData.bobSeed = Math.random() * Math.PI * 2;
                plane.userData.bobAmp = 3 + Math.random() * 5;
                plane.visible = (skyAlpha > 0.2 || onSkyLayer);
                scene.add(plane);
                skyPlanes.push(plane);
            }

            const time = clock.getElapsedTime();
            for (let i = skyPlanes.length - 1; i >= 0; i--) {
                const p = skyPlanes[i];
                p.position.x += p.userData.speedX * delta;
                p.position.z += p.userData.speedZ * delta;
                p.position.y = p.userData.baseY + Math.sin(time * 0.8 + p.userData.bobSeed) * p.userData.bobAmp;
                p.visible = (skyAlpha > 0.2 || onSkyLayer);

                // Ekrandan Ã§Ä±ktÄ±ysa sil (yeni bir tane otomatik spawn olacak)
                const tooFarZ = Math.abs(p.position.z) > 800;
                const tooFarBack = p.position.x < player.position.x - 1500;
                if (tooFarZ || tooFarBack) {
                    disposeNode(p);
                    skyPlanes.splice(i, 1);
                }
            }
        }

        updateSkyDecor(delta, !freezeSkyScenery);
    }

function updateLava(delta) {
        if (gamePhase < 3) return;

        const isPostLavaPhase = gamePhase >= 4;
        const isWaterPhase = gamePhase === 4;
        const isSnowPhase = gamePhase >= 5;
        lavaTime += delta;
        if (isPostLavaPhase) waterTime += delta;
        if (isSnowPhase) snowTime += delta;

        if (!isPostLavaPhase && lavaPreviewProgress < 1) {
            setLavaPreviewOpacity(Math.min(1, lavaPreviewProgress + delta * 0.22));
        }

        if (lavaFloor) {
            lavaFloor.position.x = player.position.x;
            lavaFloor.position.z = 0;
            setLavaFloorTime(lavaTime);
            if (isPostLavaPhase) {
                const easedWaterFade = waterTransitionProgress * waterTransitionProgress * (3 - 2 * waterTransitionProgress);
                const lavaAlpha = waterTransitionActive ? (1 - easedWaterFade) * 0.92 : 0;
                lavaFloor.visible = lavaAlpha > 0.01;
                setLavaFloorAlpha(lavaAlpha);
            } else {
                lavaFloor.visible = true;
                if (typeof lavaFloor.material.emissiveIntensity === 'number') {
                    // Emissive flow carries the magma volume; reflection stays matte.
                    lavaFloor.material.emissiveIntensity = 1.08
                        + Math.sin(clock.getElapsedTime() * 1.7) * 0.08
                        + Math.sin(clock.getElapsedTime() * 4.3) * 0.035;
                }
            }
        }

        if (isPostLavaPhase) {
            if (waterTransitionActive) {
                waterTransitionProgress = Math.min(1, waterTransitionProgress + delta * WATER_TRANSITION_SPEED);
                if (waterTransitionProgress >= 1) {
                    waterTransitionActive = false;
                    if (lavaFloor) lavaFloor.visible = false;
                }
            }
            if (isSnowPhase && snowTransitionActive) {
                snowTransitionProgress = Math.min(1, snowTransitionProgress + delta * SNOW_TRANSITION_SPEED);
                if (snowTransitionProgress >= 1) {
                    snowTransitionActive = false;
                    if (waterFloor) waterFloor.visible = false;
                }
            }
            if (waterFloor) {
                waterFloor.position.x = player.position.x;
                waterFloor.position.z = 0;
                const easedWaterAlpha = waterTransitionActive
                    ? waterTransitionProgress * waterTransitionProgress * (3 - 2 * waterTransitionProgress)
                    : 1;
                const easedSnowFade = isSnowPhase
                    ? snowTransitionProgress * snowTransitionProgress * (3 - 2 * snowTransitionProgress)
                    : 0;
                const keepWaterFloorDuringSnow = !isSnowPhase || snowTransitionProgress < 0.42;
                const waterAlpha = isSnowPhase
                    ? (keepWaterFloorDuringSnow ? Math.pow(1 - easedSnowFade, 2.35) * WATER_FLOOR_TARGET_ALPHA : 0)
                    : easedWaterAlpha * WATER_FLOOR_TARGET_ALPHA;
                setWaterFloorAlpha(waterAlpha);
                waterFloor.visible = waterAlpha > 0.015;
                setWaterFloorTime(waterTime);
                animateWaterSurface(player.position.x, delta);
                if (typeof waterFloor.material.emissiveIntensity === 'number') {
                    waterFloor.material.emissiveIntensity = 0.22 + Math.sin(clock.getElapsedTime() * 1.05) * 0.03;
                }
            }
            if (isSnowPhase) {
                if (!snowFloor) createSnowFloor();
                if (!snowFlurries) createSnowFlurries();
                const easedSnowAlpha = snowTransitionActive
                    ? snowTransitionProgress * snowTransitionProgress * (3 - 2 * snowTransitionProgress)
                    : 1;
                if (snowFloor) {
                    snowFloor.visible = true;
                    snowFloor.position.x = player.position.x;
                    snowFloor.position.z = 0;
                    setSnowFloorAlpha(easedSnowAlpha * SNOW_FLOOR_TARGET_ALPHA);
                    setSnowFloorTime(snowTime);
                    if (typeof snowFloor.material.emissiveIntensity === 'number') {
                        snowFloor.material.emissiveIntensity = 0.065 + Math.sin(clock.getElapsedTime() * 0.9) * 0.008;
                    }
                }
                updateSnowFlurries(delta, easedSnowAlpha);
            } else if (snowFlurries) {
                updateSnowFlurries(delta, 0);
            }
            updateWaterOilPipes(delta);
            updateWaterBounceCaps(delta);
            updateWaterAquariumTunnels(delta);
            updateSnowIceTunnels(delta);
        }

        const spawnAhead = player.position.x + 2500;
        if (nextLavaSpawnX < player.position.x + 180) nextLavaSpawnX = player.position.x + 180;
        // Generate one row only after the intro/previous row has drained. Keep the
        // cursor behind the horizon until caught up rather than filling it in one frame.
        if (nextLavaSpawnX < spawnAhead && lateDecorSpawnHead === lateDecorSpawnQueue.length) {
            lateDecorSpawnPhase = gamePhase;
            nextLavaSpawnX += isSnowPhase
                ? (24 + Math.random() * 38)
                : (isWaterPhase ? (38 + Math.random() * 52) : (isPostLavaPhase ? (22 + Math.random() * 34) : (30 + Math.random() * 46)));
            const mainSide = Math.random() > 0.5 ? 1 : -1;
            queueLateDecorSpawn(nextLavaSpawnX, null, mainSide);
            const sideFillChance = isSnowPhase ? 0.76 : (isWaterPhase ? 0.72 : (isPostLavaPhase ? 0.78 : 0.72));
            if (Math.random() < sideFillChance) {
                queueLateDecorSpawn(nextLavaSpawnX + 10 + Math.random() * 24, null, -mainSide);
            }
        }
        processLateDecorSpawnQueue();

        const time = clock.getElapsedTime();
        // En geniş dekorların X eksenindeki taşmasını da kapsayan güvenlik payı.
        // Eşiğin ötesinde Exp2 sis katkıyı 1/4096'nın altına indirmiş durumdadır.
        const fogCullAhead = getFogInvisibleDistance(220);
        for (let i = lavaDecorObjects.length - 1; i >= 0; i--) {
            const obj = lavaDecorObjects[i];
            const decorDistAhead = obj.position.x - player.position.x;
            obj.visible = decorDistAhead <= fogCullAhead;
            const shouldAnimateSpecialDecor = obj.visible && (!isPostLavaPhase || (decorDistAhead > -120 && decorDistAhead < 1250));
            if (shouldAnimateSpecialDecor && obj.userData && typeof obj.userData.pulseSeed === 'number') {
                const pulse = 1.0 + Math.sin(time * 2.2 + obj.userData.pulseSeed) * obj.userData.pulseAmp;
                const pulseMat = isSnowPhase ? mats.snowGlow : (isPostLavaPhase ? mats.waterGlow : mats.lavaCore);
                obj.traverse((child) => {
                    if (!child.isMesh || !child.material || child.material !== pulseMat) return;
                    child.material.emissiveIntensity = isSnowPhase ? (0.28 + pulse * 0.16) : (isPostLavaPhase ? (0.28 + pulse * 0.14) : (1.2 + pulse * 0.7));
                });
            }
            const decorType = obj.userData?.decorType;
            if (shouldAnimateSpecialDecor && decorType === 'water_birds') {
                const baseY = obj.userData.baseY ?? obj.position.y;
                const phase = obj.userData.phase || 0;
                obj.position.y = baseY + Math.sin(time * 1.45 + phase) * 1.4;
                obj.rotation.z = Math.sin(time * 0.85 + phase) * 0.035;
                obj.traverse((child) => {
                    if (!child.userData || !child.userData.waterWing) return;
                    child.rotation.z = child.userData.baseRotZ + Math.sin(time * 8.4 + child.userData.phase) * 0.24 * child.userData.wingDir;
                });
            } else if (shouldAnimateSpecialDecor && !isSnowPhase && (decorType === 'water_sailboat' || decorType === 'water_buoy')) {
                // Dalga salınımı: şamandıra sert yalpalar, yelkenli hafif süzülür (karda donuk kalır)
                const baseY = obj.userData.baseY ?? obj.position.y;
                const ph = obj.userData.phase || 0;
                if (decorType === 'water_buoy') {
                    obj.position.y = baseY + Math.sin(time * 1.9 + ph) * 0.55;
                    obj.rotation.x = Math.sin(time * 1.3 + ph) * 0.11;
                    obj.rotation.z = Math.cos(time * 1.6 + ph) * 0.13;
                } else {
                    obj.position.y = baseY + Math.sin(time * 1.05 + ph) * 0.45;
                    obj.rotation.z = Math.sin(time * 0.85 + ph) * 0.055;
                }
            } else if (shouldAnimateSpecialDecor && decorType === 'water_lighthouse') {
                const phase = obj.userData.pulseSeed || 0;
                const lampPulse = 1 + Math.sin(time * 2.8 + phase) * 0.12;
                if (obj.userData.lightMesh) obj.userData.lightMesh.scale.setScalar(lampPulse);
                if (obj.userData.beamMesh) {
                    obj.userData.beamMesh.scale.x = 0.95 + Math.sin(time * 1.3 + phase) * 0.08;
                    obj.userData.beamMesh.rotation.y = Math.sin(time * 0.5 + phase) * 0.18;
                }
            } else if (shouldAnimateSpecialDecor && decorType === 'water_oil_platform' && obj.userData.warningLights) {
                const phase = obj.userData.pulseSeed || 0;
                const warningPulse = 1 + Math.max(0, Math.sin(time * 3.4 + phase)) * 0.28;
                obj.userData.warningLights.forEach((light) => {
                    light.scale.setScalar(warningPulse);
                });
            }
            if (obj.position.x < player.position.x - 400) {
                disposeNode(obj);
                lavaDecorObjects.splice(i, 1);
            }
        }

        if (!isPostLavaPhase && lavaEmbers && lavaEmbers.geometry && lavaEmbers.material) {
            lavaEmbers.visible = true;
            const positions = lavaEmbers.geometry.attributes.position.array;
            for (let i = 0; i < lavaEmberData.length; i++) {
                const ember = lavaEmberData[i];
                ember.relX -= moveSpeed * (8.5 + ember.rise * 0.05);
                if (ember.relX < -320) {
                    ember.relX = 1100 + Math.random() * 900;
                    ember.z = (Math.random() > 0.5 ? 1 : -1) * (34 + Math.random() * 170);
                    ember.baseY = 1 + Math.random() * 10;
                    ember.phase = Math.random() * Math.PI * 2;
                }
                const wobble = Math.sin(time * 2.4 + ember.phase) * 0.9;
                positions[i * 3] = player.position.x + ember.relX + wobble;
                positions[i * 3 + 1] = ember.baseY + Math.abs(Math.sin(time * ember.rise + ember.phase)) * 13;
                positions[i * 3 + 2] = ember.z + Math.cos(time * 1.8 + ember.phase) * ember.drift * 6;
            }
            lavaEmbers.geometry.attributes.position.needsUpdate = true;
        } else if (isPostLavaPhase && lavaEmbers && lavaEmbers.material) {
            lavaEmbers.material.opacity = Math.max(0, lavaEmbers.material.opacity - delta * 0.7);
            lavaEmbers.visible = lavaEmbers.material.opacity > 0.02;
        }

        // YOL-SEVİYESİ LAV IŞIĞI: yalnızca lav fazında (su/kar'da sönümlenir). Oyuncunun hafif
        // önünde-altında konumlanır, nabızla titrer → yol ve yakın kayalar canlı turuncu aydınlanır.
        if (lavaGlowLight) {
            const wantGlow = !isPostLavaPhase;
            const targetInt = wantGlow ? (3.4 + Math.sin(time * 3.1) * 0.7 + Math.sin(time * 7.7) * 0.3) : 0;
            lavaGlowLight.intensity += (targetInt - lavaGlowLight.intensity) * Math.min(1, delta * 4);
            lavaGlowLight.position.set(player.position.x + 26, 6, getRoadCenterZ());
        }
        if (lavaHeatHaze && lavaHeatHaze.material) {
            const wantHaze = !isPostLavaPhase;
            lavaHeatHaze.visible = wantHaze || lavaHeatHaze.material.opacity > 0.02;
            const tOp = wantHaze ? 0.28 : 0; // 0.5→0.28: üstüne gelen duman daha soluk
            lavaHeatHaze.material.opacity += (tOp - lavaHeatHaze.material.opacity) * Math.min(1, delta * 2.5);
            if (lavaHeatHaze.visible) {
                const hp = lavaHeatHaze.geometry.attributes.position.array;
                for (let i = 0; i < hp.length; i += 3) {
                    hp[i] -= moveSpeed * 8.5;
                    if (hp[i] < player.position.x - 260) hp[i] = player.position.x + 700 + Math.random() * 500;
                    hp[i + 1] = 3 + Math.abs(Math.sin(time * 0.7 + i)) * 6;
                }
                lavaHeatHaze.geometry.attributes.position.needsUpdate = true;
            }
        }
    }

    function createDetailedLowWall() {
        const group = new THREE.Group();
        
        const baseGeo = new THREE.BoxGeometry(4.5, 2.5, 7.0);
        const baseMat = new THREE.MeshStandardMaterial({ 
            color: 0x222222, 
            metalness: 0.6, 
            roughness: 0.4 
        });
        const base = new THREE.Mesh(baseGeo, baseMat);
        base.position.y = 1.25;
        base.castShadow = true;
        group.add(base);

        const lightBarGeo = new THREE.CylinderGeometry(0.8, 0.8, 6.8, 16);
        const lightBarMat = new THREE.MeshStandardMaterial({ 
            color: 0xffff00, 
            emissive: 0xffaa00, 
            emissiveIntensity: 4.0,
            metalness: 0.5,
            roughness: 0.2
        });
        const lightBar = new THREE.Mesh(lightBarGeo, lightBarMat);
        lightBar.rotation.x = Math.PI / 2;
        lightBar.position.y = 3.0;
        group.add(lightBar);

        const sideGeo = new THREE.BoxGeometry(5.0, 3.5, 1.0);
        const sideMat = new THREE.MeshStandardMaterial({ color: 0x111111, metalness: 0.8 });
        
        const side1 = new THREE.Mesh(sideGeo, sideMat);
        side1.position.set(0, 1.75, 3.5);
        group.add(side1);

        const side2 = new THREE.Mesh(sideGeo, sideMat);
        side2.position.set(0, 1.75, -3.5);
        group.add(side2);

        return group;
    }

    // 2026-07-14: kullanıcı iki re-detail turunu da (endüstriyel şerit + chevron/çatlak/kablo)
    // beğenmedi, oturum öncesi orijinal (2026-06-20 cinematic pass) haline geri alındı.
    function createDetailedFallingWall() {
        const group = new THREE.Group();
        const height = 20;
        const thickness = 1.2; // Duvarı incelttik

        // Ana Çerçeve (Koyu Metalik Kırmızı)
        const frameGeo = new THREE.BoxGeometry(thickness, height, 7.0);
        const frameMat = new THREE.MeshStandardMaterial({
            color: 0x440000,
            metalness: 0.9,
            roughness: 0.3
        });
        const frame = new THREE.Mesh(frameGeo, frameMat);
        frame.position.y = height / 2;
        // Airborne falling walls must not project a detached dark slab onto the
        // road. updateObstacles enables this caster after the wall lands.
        frame.castShadow = false;
        group.add(frame);
        group.userData.shadowCaster = frame;

        // İç Enerji Çekirdeği (Parlak Kırmızı Neon)
        const coreGeo = new THREE.BoxGeometry(thickness + 0.2, height - 2, 5.5);
        const coreMat = new THREE.MeshStandardMaterial({
            color: 0xff0000,
            emissive: 0xff0000,
            emissiveIntensity: 2.5, // Parlaklığı arttırdık
            roughness: 0.1
        });
        const core = new THREE.Mesh(coreGeo, coreMat);
        core.position.y = height / 2;
        group.add(core);

        // Alt Dikenler (Tehlike hissi için)
        const spikeGeo = new THREE.ConeGeometry(0.4, 1.5, 4);
        const spikeMat = new THREE.MeshStandardMaterial({ color: 0x220000, metalness: 1.0 });

        for(let k=0; k<5; k++) {
            const spike = new THREE.Mesh(spikeGeo, spikeMat);
            spike.rotation.x = Math.PI; // Aşağı baksın
            spike.position.set(0, -0.75, (k - 2) * 1.2);
            group.add(spike);
        }

        // --- re-detail: bright neon edge bars that frame the core and catch bloom ---
        const edgeGeo = new THREE.BoxGeometry(thickness + 0.4, height, 0.55);
        const edgeMat = new THREE.MeshBasicMaterial({ color: 0xff5570 });
        const edgeA = new THREE.Mesh(edgeGeo, edgeMat); edgeA.position.set(0, height / 2, 3.25); group.add(edgeA);
        const edgeB = new THREE.Mesh(edgeGeo, edgeMat); edgeB.position.set(0, height / 2, -3.25); group.add(edgeB);

        // İniş-hedef göstergesi: duvar havadayken zeminde pulse eden halka (updateObstacles
        // her frame local-Y'sini dünya zeminine sabitler). Materyal per-instance — mesafe-fade
        // setObjectOpacity paylaşımlı materyali bozar; geometri paylaşımlı (geoms.fwDropRing).
        const markerMat = new THREE.MeshBasicMaterial({ color: 0xff2438, transparent: true, opacity: 0.5, blending: THREE.AdditiveBlending, depthWrite: false, side: THREE.DoubleSide });
        const marker = new THREE.Mesh(geoms.fwDropRing, markerMat);
        marker.rotation.x = -Math.PI / 2;
        marker.renderOrder = 5;
        marker.visible = false;
        group.add(marker);
        group.userData.dropMarker = marker;

        return group;
    }

    function createCurvedDetailedBarrier() {
        const group = new THREE.Group();
        const length = 3000;
        const segmentLength = 40;
        const segmentCount = Math.ceil(length / segmentLength);
        const segmentStartX = -length * 0.5 + segmentLength * 0.5;
        const instanceSets = [];
        const dummy = tempSkyLineDummy;
        const railMat = new THREE.MeshStandardMaterial({ color: 0xff0000, emissive: 0x550000, roughness: 0.3, metalness: 0.7 });
        const postMat = new THREE.MeshStandardMaterial({ color: 0x222222, roughness: 0.8 });
        const baseMat = new THREE.MeshStandardMaterial({ color: 0x331111, roughness: 0.9 });
        const lightMat = new THREE.MeshBasicMaterial({ color: 0xff3333 });

        const addSet = (geometry, material, entries, castShadow = false, receiveShadow = false) => {
            const mesh = new THREE.InstancedMesh(geometry, material, entries.length);
            entries.forEach((entry, index) => {
                dummy.position.set(entry.x, entry.y, entry.z);
                dummy.rotation.set(0, 0, 0);
                dummy.scale.set(1, 1, 1);
                dummy.updateMatrix();
                mesh.setMatrixAt(index, dummy.matrix);
            });
            mesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
            mesh.instanceMatrix.needsUpdate = true;
            mesh.castShadow = castShadow;
            mesh.receiveShadow = receiveShadow;
            mesh.frustumCulled = false;
            group.add(mesh);
            instanceSets.push({ mesh, entries });
            return mesh;
        };

        const segmentEntries = (y, z = 0) => Array.from({ length: segmentCount }, (_, index) => ({
            x: segmentStartX + index * segmentLength,
            y,
            z
        }));
        addSet(new THREE.BoxGeometry(segmentLength + 0.35, 0.4, 0.25, 4, 1, 1), railMat, segmentEntries(1.6), true, true);
        addSet(new THREE.BoxGeometry(segmentLength + 0.35, 0.4, 0.25, 4, 1, 1), railMat, segmentEntries(0.9), true, true);
        addSet(new THREE.BoxGeometry(segmentLength + 0.35, 0.4, 0.6, 4, 1, 1), baseMat, segmentEntries(0.2), false, true);

        const postCount = 150;
        const postSpacing = length / postCount;
        const postEntries = Array.from({ length: postCount + 1 }, (_, index) => ({
            x: -length * 0.5 + index * postSpacing,
            y: 1,
            z: 0
        }));
        addSet(new THREE.BoxGeometry(0.5, 2, 0.5), postMat, postEntries, true, true);

        const lightEntries = [];
        for (let index = 0; index <= postCount; index += 4) {
            lightEntries.push({ x: -length * 0.5 + index * postSpacing, y: 1.6, z: 0.15 });
        }
        addSet(new THREE.BoxGeometry(0.15, 0.6, 0.05), lightMat, lightEntries, false, false);
        group.userData.curvedPathInstanceSets = instanceSets;
        // Bend the rail vertices with the asphalt. Pivot-only (rigid) bending
        // left the ends of each straight rail cell floating above the curved
        // road. Instanced transforms stay immutable; only their rendered
        // vertices use the shared smooth shader, so CPU gameplay is unchanged.
        curvedPathSystem?.installGpuCurvedObject?.(group, true, { mode: 'smooth' });
        return group;
    }

    function setFallingWallBodyVisible(wall, visible) {
        if (!wall || !wall.children) return;
        const marker = wall.userData?.dropMarker;
        for (const child of wall.children) {
            if (child !== marker) child.visible = visible;
        }
    }

    function createDetailedBarrier() {
        return createCurvedDetailedBarrier();
        const group = new THREE.Group();
        const length = 3000; // Bariyer uzunluÄŸu
        
        // 1. Ãœst ve Orta Metal Raylar (Parlak KÄ±rmÄ±zÄ±)
        const railGeo = new THREE.BoxGeometry(length, 0.4, 0.25);
        const railMat = new THREE.MeshStandardMaterial({ 
            color: 0xff0000, 
            emissive: 0x550000, 
            roughness: 0.3, 
            metalness: 0.7 
        });
        
        const topRail = new THREE.Mesh(railGeo, railMat);
        topRail.position.set(0, 1.6, 0); // Ãœst ray
        topRail.castShadow = true;
        group.add(topRail);

        const midRail = new THREE.Mesh(railGeo, railMat);
        midRail.position.set(0, 0.9, 0); // Orta ray
        midRail.castShadow = true;
        group.add(midRail);

        // 2. Dikmeler (Koyu Gri Metal) - Optimizasyonlu (InstancedMesh)
        const postGeo = new THREE.BoxGeometry(0.5, 2.0, 0.5);
        const postMat = new THREE.MeshStandardMaterial({ color: 0x222222, roughness: 0.8 });
        
        const postCount = 150; // 3000 birimlik yolda 150 direk
        const spacing = length / postCount;
        const startX = -length / 2;
        
        const instancedPost = new THREE.InstancedMesh(postGeo, postMat, postCount + 1);
        const dummy = tempSkyLineDummy;
        
        for(let i=0; i <= postCount; i++) {
            dummy.position.set(startX + i * spacing, 1.0, 0);
            dummy.updateMatrix();
            instancedPost.setMatrixAt(i, dummy.matrix);
        }
        instancedPost.castShadow = true;
        instancedPost.receiveShadow = true;
        group.add(instancedPost);

        // 3. Alt Beton Kaide (Daha koyu ton)
        const baseGeo = new THREE.BoxGeometry(length, 0.4, 0.6);
        const baseMat = new THREE.MeshStandardMaterial({ color: 0x331111, roughness: 0.9 });
        const base = new THREE.Mesh(baseGeo, baseMat);
        base.position.y = 0.2;
        base.receiveShadow = true;
        group.add(base);

        // 4. Neon UyarÄ± IÅŸÄ±klarÄ± (Her 4 direkte bir)
        const lightGeo = new THREE.BoxGeometry(0.15, 0.6, 0.05);
        const lightMat = new THREE.MeshBasicMaterial({ color: 0xff3333 });
        const instancedLight = new THREE.InstancedMesh(lightGeo, lightMat, Math.floor(postCount/4) + 1);
        
        let lIdx = 0;
        for(let i=0; i <= postCount; i+=4) {
            dummy.position.set(startX + i * spacing, 1.6, 0.15); // RayÄ±n yÃ¼zeyinde
            dummy.updateMatrix();
            instancedLight.setMatrixAt(lIdx++, dummy.matrix);
        }
        group.add(instancedLight);

        return group;
    }

    function createDetailedSlideBarrier() {
        const group = new THREE.Group();
        const width = 6.8;
        
        // Ãœst Ana Blok (SarÄ±)
        const mainGeo = new THREE.BoxGeometry(2.0, 3.0, width);
        const mainMat = new THREE.MeshStandardMaterial({ 
            color: 0xffcc00, 
            roughness: 0.4,
            metalness: 0.6
        });
        const main = new THREE.Mesh(mainGeo, mainMat);
        group.add(main);

        // Siyah UyarÄ± Åeritleri
        const stripeGeo = new THREE.BoxGeometry(2.1, 3.0, 0.5);
        const stripeMat = new THREE.MeshBasicMaterial({ color: 0x000000 });
        
        for(let i=0; i<4; i++) {
            const stripe = new THREE.Mesh(stripeGeo, stripeMat);
            stripe.position.z = (i * 1.5) - 2.25;
            group.add(stripe);
        }

        // Alt Lazer/SensÃ¶r BarÄ± (Cyan IÅŸÄ±k - KayÄ±lacak yeri gÃ¶sterir)
        const laserGeo = new THREE.CylinderGeometry(0.1, 0.1, width, 8);
        const laserMat = new THREE.MeshBasicMaterial({ color: 0x00ffff });
        const laser = new THREE.Mesh(laserGeo, laserMat);
        laser.rotation.x = Math.PI / 2;
        laser.position.y = -2.0; // BloÄŸun biraz altÄ±nda
        group.add(laser);

        // Yan Motorlar (Havada durduÄŸunu desteklemek iÃ§in)
        const motorGeo = new THREE.BoxGeometry(2.5, 4.0, 1.2);
        const motorMat = new THREE.MeshStandardMaterial({ color: 0x222222 });
        
        const m1 = new THREE.Mesh(motorGeo, motorMat);
        m1.position.set(0, 0, width/2);
        group.add(m1);

        const m2 = new THREE.Mesh(motorGeo, motorMat);
        m2.position.set(0, 0, -width/2);
        group.add(m2);

        return group;
    }

    const _sweep = { ready: false };

    function ensureSkySweeperCache() {
        if (_sweep.ready) return;
        const hubRadius = 3.35;
        const armRadius = 1.18;

        // Göbek: alt geniş taban + tehlike-şeritli bel + üst daralan gövde (3 bantlı modüler direk).
        _sweep.geoBase = new THREE.CylinderGeometry(hubRadius * 1.05, hubRadius * 1.15, 3.2, 20);
        _sweep.geoWaist = new THREE.CylinderGeometry(hubRadius * 0.78, hubRadius * 0.95, 2.6, 20);
        _sweep.geoTop = new THREE.CylinderGeometry(hubRadius * 0.55, hubRadius * 0.78, 3.0, 20);
        _sweep.geoFlange = new THREE.TorusGeometry(hubRadius * 0.9, 0.22, 10, 24);
        _sweep.geoCap = new THREE.SphereGeometry(hubRadius * 0.5, 16, 14);
        _sweep.geoAntennaRod = new THREE.CylinderGeometry(0.09, 0.09, 1.6, 8);
        _sweep.geoBeacon = new THREE.SphereGeometry(0.34, 10, 10);
        _sweep.geoBolt = new THREE.CylinderGeometry(0.16, 0.16, 0.32, 8);

        // Kol: birim-uzunlukta bom + kenar neonu (scale ile uzatılır) + kaburga halkaları +
        // bağlantı dirseği + uç uyarı kanadı. Birim-uzunluk sayesinde retune artık oran değil
        // doğrudan armHalfLength kullanıyor (bkz. retuneSkySweeperObstacle).
        _sweep.geoBoom = new THREE.CylinderGeometry(armRadius, armRadius * 1.05, 1, 16);
        _sweep.geoNeon = new THREE.BoxGeometry(1, 0.18, 0.18);
        _sweep.geoRib = new THREE.TorusGeometry(armRadius * 1.2, 0.12, 8, 16);
        _sweep.geoBracket = new THREE.BoxGeometry(1.1, armRadius * 2.1, armRadius * 2.1);
        _sweep.geoPaddle = new THREE.BoxGeometry(0.9, armRadius * 2.6, armRadius * 2.2);

        // Sarı-siyah diyagonal tehlike şeridi — göbek beli ve kol kanadı ortak (paylaşımlı, __pooled).
        const s = 128;
        const cv = document.createElement('canvas'); cv.width = s; cv.height = s;
        const c = cv.getContext('2d');
        c.fillStyle = '#1a1a1a'; c.fillRect(0, 0, s, s);
        c.fillStyle = '#ffcc00';
        c.save();
        c.translate(s / 2, s / 2); c.rotate(Math.PI / 4); c.translate(-s, -s);
        const stripeW = 22;
        for (let x = -s; x < s * 3; x += stripeW * 2) c.fillRect(x, -s, stripeW, s * 4);
        c.restore();
        _sweep.hazardTex = new THREE.CanvasTexture(cv);
        _sweep.hazardTex.colorSpace = THREE.SRGBColorSpace;
        _sweep.hazardTex.wrapS = _sweep.hazardTex.wrapT = THREE.RepeatWrapping;
        _sweep.hazardTex.repeat.set(2, 1);
        _sweep.hazardTex.__pooled = true;

        spawnPoolGeoms.push(
            _sweep.geoBase, _sweep.geoWaist, _sweep.geoTop, _sweep.geoFlange, _sweep.geoCap,
            _sweep.geoAntennaRod, _sweep.geoBeacon, _sweep.geoBolt,
            _sweep.geoBoom, _sweep.geoNeon, _sweep.geoRib, _sweep.geoBracket, _sweep.geoPaddle
        );
        _sweep.ready = true;
    }

    function createSkySweeperObstacle() {
        ensureSkySweeperCache();
        const group = new THREE.Group();

        const roadHalfWidth = getRoadHalfWidth();
        const hubRadius = 3.35;
        const hubHeight = 8.8;
        const armHalfLength = roadHalfWidth + PLAYER_WIDTH * 1.15 + 1.8;
        const armRadius = 1.18;
        const armY = 2.3;
        const armReach = armHalfLength + PLAYER_WIDTH * 0.9;

        // Materyaller per-instance (spawn başına taze) — geometriler paylaşımlı olsa da
        // mesafe-bazlı fade (setObjectOpacity) her sweeper'ı ayrı etkilemeli (CLAUDE.md:
        // paylaşımlı materyal + per-instance fade = görünmez olma bug'ı).
        const matDrum = new THREE.MeshStandardMaterial({ color: 0x33383f, metalness: 0.55, roughness: 0.48 });
        const matHazard = new THREE.MeshBasicMaterial({ map: _sweep.hazardTex });
        // emissive eklendi — Sky fazının mavi/mor ortam ışığı emissive'siz açık renkleri lavantaya
        // çekiyordu (falling_wall'daki foamWhite ile aynı numara: kendi rengini korusun).
        const matCap = new THREE.MeshStandardMaterial({ color: 0xe8e8ec, emissive: 0xd8d8dc, emissiveIntensity: 0.3, metalness: 0.18, roughness: 0.4 });
        const matBolt = new THREE.MeshStandardMaterial({ color: 0x161616, metalness: 0.75, roughness: 0.4 });
        const matBeacon = new THREE.MeshBasicMaterial({ color: 0xff2a2a });
        const matRib = new THREE.MeshStandardMaterial({ color: 0x20232a, metalness: 0.6, roughness: 0.4 });
        const matNeon = new THREE.MeshBasicMaterial({ color: 0xffb020 });
        const matArm = new THREE.MeshStandardMaterial({ color: 0xe8e8ec, emissive: 0xd8d8dc, emissiveIntensity: 0.3, metalness: 0.18, roughness: 0.42 });

        // --- Göbek (0 → hubHeight + anten) ---
        const baseFlange = new THREE.Mesh(_sweep.geoFlange, matDrum);
        baseFlange.rotation.x = Math.PI / 2;
        baseFlange.scale.setScalar(1.15);
        baseFlange.position.y = 0.7;
        group.add(baseFlange);

        const drumBase = new THREE.Mesh(_sweep.geoBase, matDrum);
        drumBase.position.y = 1.6;
        drumBase.castShadow = true;
        drumBase.receiveShadow = true;
        group.add(drumBase);

        const boltCount = 6;
        for (let i = 0; i < boltCount; i++) {
            const a = (i / boltCount) * Math.PI * 2;
            const bolt = new THREE.Mesh(_sweep.geoBolt, matBolt);
            bolt.position.set(Math.cos(a) * (hubRadius * 1.1), 1.6, Math.sin(a) * (hubRadius * 1.1));
            group.add(bolt);
        }

        const seamFlange1 = new THREE.Mesh(_sweep.geoFlange, matDrum);
        seamFlange1.rotation.x = Math.PI / 2;
        seamFlange1.position.y = 3.2;
        group.add(seamFlange1);

        const drumWaist = new THREE.Mesh(_sweep.geoWaist, matHazard);
        drumWaist.position.y = 4.5;
        drumWaist.castShadow = true;
        group.add(drumWaist);

        const seamFlange2 = new THREE.Mesh(_sweep.geoFlange, matDrum);
        seamFlange2.rotation.x = Math.PI / 2;
        seamFlange2.position.y = 5.8;
        group.add(seamFlange2);

        const drumTop = new THREE.Mesh(_sweep.geoTop, matDrum);
        drumTop.position.y = 7.3;
        drumTop.castShadow = true;
        group.add(drumTop);

        const hubCap = new THREE.Mesh(_sweep.geoCap, matCap);
        hubCap.scale.y = 0.42;
        hubCap.position.y = hubHeight + 0.2;
        hubCap.castShadow = true;
        group.add(hubCap);

        const antennaRod = new THREE.Mesh(_sweep.geoAntennaRod, matCap);
        antennaRod.position.y = hubHeight + 1.0;
        group.add(antennaRod);

        const hubBeacon = new THREE.Mesh(_sweep.geoBeacon, matBeacon);
        hubBeacon.position.y = hubHeight + 1.9;
        group.add(hubBeacon);

        // --- Kollar (armPivot: armY yüksekliğinde, hub ile birlikte döner) ---
        const armParts = [];
        const armPivot = new THREE.Group();
        armPivot.position.y = armY;
        group.add(armPivot);

        const warningLights = [hubBeacon];
        const ribFracs = [0.26, 0.52, 0.8];

        [1, -1].forEach((dir) => {
            const bracket = new THREE.Mesh(_sweep.geoBracket, matDrum);
            bracket.position.x = dir * (hubRadius * 0.85);
            armPivot.add(bracket);

            const arm = new THREE.Mesh(_sweep.geoBoom, matArm);
            arm.rotation.z = Math.PI / 2;
            arm.castShadow = true;
            arm.receiveShadow = true;
            armPivot.add(arm);

            const neon = new THREE.Mesh(_sweep.geoNeon, matNeon);
            // armRadius*1.05 boom'un dış yarıçapı — neon bunun DIŞINDA olmalı yoksa gövdenin
            // içinde kalıp görünmez olur (falling_wall'daki "proud kenar" dersiyle aynı tuzak).
            neon.position.y = armRadius * 1.45;
            armPivot.add(neon);

            const ribs = ribFracs.map(() => {
                const rib = new THREE.Mesh(_sweep.geoRib, matRib);
                rib.rotation.y = Math.PI / 2;
                armPivot.add(rib);
                return rib;
            });

            const paddle = new THREE.Mesh(_sweep.geoPaddle, matHazard);
            paddle.castShadow = true;
            armPivot.add(paddle);

            const tipLight = new THREE.Mesh(_sweep.geoBeacon, matBeacon);
            armPivot.add(tipLight);
            warningLights.push(tipLight);

            armParts.push({ dir, arm, neon, ribs, ribFracs, paddle, tipLight });
        });

        group.userData = {
            type: 'sky_sweeper',
            speedX: 0,
            length: armReach * 2 + 6,
            widthZ: roadHalfWidth * 2 + 8,
            height: hubHeight,
            hubRadius: hubRadius,
            hubVisualRadius: hubRadius,
            hubTopLocal: hubHeight + 0.4,
            armYLocal: armY,
            armLength: armHalfLength * 2,
            armReach: armReach,
            armSegmentStart: hubRadius * 0.72,
            armSegmentEnd: armHalfLength + armRadius * 0.72,
            armCollisionRadius: armRadius * 0.34,
            hubCollisionRadius: hubRadius * 0.42,
            armRadius: armRadius,
            armVisualRadius: armRadius,
            armThickness: armRadius * 2,
            rotSpeed: 1.2 + Math.random() * 0.35,
            sweepAngle: Math.random() * Math.PI * 2,
            blockRangeX: SKY_SWEEPER_BLOCK_RANGE_X,
            blocksAllLanes: true,
            fadeStartDistance: 620,
            fadeLength: 140,
            visualAlpha: 0,
            armParts: armParts,
            warningLights: warningLights,
            pulseSeed: Math.random() * Math.PI * 2
        };

        group.rotation.y = group.userData.sweepAngle;
        retuneSkySweeperObstacle(group);
        setObjectOpacity(group, 0);
        group.visible = false;
        return group;
    }

     function createMegaJumpPad(x) {
        const group = new THREE.Group();

        const radius = getRoadHalfWidth() + 1.9; 
        const baseGeo = new THREE.CylinderGeometry(radius - 1, radius, 1.5, 64);
        const baseMat = new THREE.MeshStandardMaterial({ 
            color: 0x0a0a1a, 
            roughness: 0.2, 
            metalness: 0.9 
        });
        const baseMesh = new THREE.Mesh(baseGeo, baseMat);
        baseMesh.position.y = 0.75;
        group.add(baseMesh);

        // 2. Ä°Ã§ Parlayan Zemin (Neon Pembe/Mor)
        const coreGeo = new THREE.CylinderGeometry(radius - 2.5, radius - 2.5, 1.6, 64);
        const coreMat = new THREE.MeshBasicMaterial({ 
            color: 0xaa00ff, 
            transparent: true, 
            opacity: 0.5,
            blending: THREE.AdditiveBlending
        });
        const coreMesh = new THREE.Mesh(coreGeo, coreMat);
        coreMesh.position.y = 0.8;
        group.add(coreMesh);

        // 3. DÃ¶nen Enerji HalkalarÄ± (TorusGeometry)
        const ringGeo1 = new THREE.TorusGeometry(radius - 4, 0.4, 16, 64);
        const ringMat1 = new THREE.MeshBasicMaterial({ color: 0x00ffff });
        const ring1 = new THREE.Mesh(ringGeo1, ringMat1);
        ring1.rotation.x = -Math.PI / 2;
        ring1.position.y = 1.6;
        group.add(ring1);

        const ringGeo2 = new THREE.TorusGeometry(radius - 8, 0.6, 16, 64);
        const ringMat2 = new THREE.MeshBasicMaterial({ color: 0xff00ff });
        const ring2 = new THREE.Mesh(ringGeo2, ringMat2);
        ring2.rotation.x = -Math.PI / 2;
        ring2.position.y = 1.6;
        group.add(ring2);

        // 4. YukarÄ± Bakan Devasa IÅŸÄ±k HÃ¼zmesi (Teleport IÅŸÄ±nÄ±)
        const beamGeo = new THREE.CylinderGeometry(radius - 3, radius, 300, 64, 1, true);
        const beamMat = new THREE.MeshBasicMaterial({ 
            color: 0x00ffff, 
            transparent: true, 
            opacity: 0.12, 
            side: THREE.DoubleSide,
            blending: THREE.AdditiveBlending,
            depthWrite: false
        });
        const beam = new THREE.Mesh(beamGeo, beamMat);
        beam.position.y = 150;
        group.add(beam);

        // 5. Ä°Ã§eriden YÃ¼kselen Enerji ParÃ§acÄ±klarÄ±
        const pCount = isMobilePerformanceGraphics() ? 28 : 80;
        const pGeo = new THREE.BufferGeometry();
        const pPosArr = new Float32Array(pCount * 3);
        const pSpeeds = [];
        for(let i=0; i<pCount; i++) {
            // Dairesel alanda rastgele daÄŸÄ±lÄ±m
            const r = Math.random() * (radius - 3);
            const theta = Math.random() * Math.PI * 2;
            pPosArr[i*3] = r * Math.cos(theta);
            pPosArr[i*3+1] = Math.random() * 40.0; // Y yÃ¼ksekliÄŸi
            pPosArr[i*3+2] = r * Math.sin(theta);
            pSpeeds.push(0.1 + Math.random() * 0.4);
        }
        pGeo.setAttribute('position', new THREE.BufferAttribute(pPosArr, 3));
        const pMat = new THREE.PointsMaterial({ 
            color: 0xffffff, 
            size: 0.8, 
            transparent: true, 
            opacity: 0.8, 
            blending: THREE.AdditiveBlending 
        });
        const particles = new THREE.Points(pGeo, pMat);
        group.add(particles);

        // Pozisyonu ayarla (Havadaysak ona gÃ¶re Y ekseni alÄ±r)
        const floorY = typeof onSkyLayer !== 'undefined' && onSkyLayer ? SKY_LAYER_Y : 0;
        group.position.set(x, floorY, getRoadCenterZ()); 
        
        // Animasyon ve Ã‡arpÄ±ÅŸma DatasÄ±
        group.userData = { 
            type: 'mega_jump_pad',
            radius: radius,
            widthZ: radius * 2,
            length: radius * 2,
            ring1: ring1,
            ring2: ring2,
            particles: particles,
            pSpeeds: pSpeeds
        };
        
        scene.add(group);
        obstacles.push(group);
        requestShadowMapRefresh(x);
        return group;
    }

function createSkyFloor() {
    if (skyFloor) {
        disposeNode(skyFloor);
        skyFloor = null;
    }
    createSkyCloudFloor();

    if (skyBarriers.length > 0) {
        skyBarriers.forEach(b => disposeNode(b));
        skyBarriers = [];
    }
    clearSkyCloudFloorStrips();
    if (skyLines && skyLines.mesh) {
            disposeNode(skyLines.mesh);
            skyLines = null;
        } else if (Array.isArray(skyLines)) {
        skyLines.forEach(l => disposeNode(l));
        skyLines = [];
    }

    const leftBarrierZ = getBarrierPositionZ(-1);
    const rightBarrierZ = getBarrierPositionZ(1);
    // The rail base is 0.6 units wide. Fit the asphalt to its INNER faces;
    // covering the rail pivots made the slab protrude outside both barriers,
    // especially on the outside of a curve.
    const barrierHalfWidth = 0.30;
    const leftRoadEdgeZ = leftBarrierZ + barrierHalfWidth;
    const rightRoadEdgeZ = rightBarrierZ - barrierHalfWidth;
    const roadWidth = Math.max(1, rightRoadEdgeZ - leftRoadEdgeZ);
    const centerZ = (leftRoadEdgeZ + rightRoadEdgeZ) * 0.5;
    const fullyVisibleSkyRoad = (onSkyLayer || (currentRunMode === 'level' && gamePhase === 2))
        && !isSkyFading && !lavaDropTransitionActive;
    const initialSkyAlpha = fullyVisibleSkyRoad ? 1 : (isSkyFading ? skyAlpha : 0);

    // A deeper opaque slab hides the underside of rigid scenery while the
    // curved-world shader drops the distant path below the local horizon.
    const geo = new THREE.BoxGeometry(2000, 10, roadWidth, 64, 1, 1);
    
    const skyRoadMat = mats.road.clone();
    // Direct Sky starts used to clear the asphalt map and therefore produced an
    // untextured/missing road. Reuse the already initialized shared canvas map.
    skyRoadMat.map = roadTexScroll || mats.road.map || null;
    if (skyRoadMat.map) skyRoadMat.map.needsUpdate = true;
    skyRoadMat.color.setHex(skyRoadMat.map ? 0xffffff : 0x111111);
    skyRoadMat.roughness = 0.66;
    skyRoadMat.metalness = 0.035;
    skyRoadMat.envMapIntensity = 0.18;
    skyRoadMat.transparent = !fullyVisibleSkyRoad;
    skyRoadMat.opacity = initialSkyAlpha;
    skyRoadMat.depthWrite = true;

    skyFloor = new THREE.Mesh(geo, skyRoadMat);
    skyFloor.position.set(player.position.x + 500, SKY_LAYER_Y - 5, centerZ);
    skyFloor.receiveShadow = true;
    skyFloor.frustumCulled = false;
    skyFloor.visible = true;
    skyFloor.userData = { baseRoadWidth: roadWidth, geometryRoadWidth: roadWidth };
    scene.add(skyFloor);
    curvedPathSystem?.installObjectMaterials?.(skyFloor);

    const bLeft = createDetailedBarrier();
    const bRight = createDetailedBarrier();
    
    bLeft.position.set(player.position.x, SKY_LAYER_Y - 0.08, leftBarrierZ);
    bRight.position.set(player.position.x, SKY_LAYER_Y - 0.08, rightBarrierZ);
    
    setObjectOpacity(bLeft, initialSkyAlpha);
    setObjectOpacity(bRight, initialSkyAlpha);

    scene.add(bLeft);
    scene.add(bRight);
    
    skyBarriers = [bLeft, bRight];

    const lineGeo = new THREE.PlaneGeometry(8, 0.5);
    const lineMat = new THREE.MeshStandardMaterial({ 
        color: 0xffff88, 
        emissive: 0x444400, 
        roughness: 0.4, 
        metalness: 0.6,
        transparent: !fullyVisibleSkyRoad,
        opacity: initialSkyAlpha
    });

    const laneZs = getLaneSeparators(); 
    const stepSize = 18; 
    const linesPerLane = Math.floor(1400 / stepSize); 
    const totalLines = laneZs.length * linesPerLane;

    const instancedLines = new THREE.InstancedMesh(lineGeo, lineMat, totalLines);
    instancedLines.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
    instancedLines.frustumCulled = false;
    scene.add(instancedLines);
    
    skyLines = { mesh: instancedLines, data: [], lastSnapX: null, lastDropActive: false };

    let idx = 0;
    const dummy = new THREE.Object3D();

    for(let z of laneZs) {
        for(let x = -200; x < 1200; x += stepSize) {
            const startX = Math.floor(player.position.x / stepSize) * stepSize + x;
            
            dummy.position.set(startX, SKY_LAYER_Y + 0.05, z);
            dummy.rotation.x = -Math.PI / 2;
            dummy.updateMatrix();
            
            instancedLines.setMatrixAt(idx, dummy.matrix);
            
            skyLines.data.push({ 
                relX: x, 
                z: z, 
                index: idx 
            });
            idx++;
        }
    }
    instancedLines.instanceMatrix.needsUpdate = true;
    requestShadowMapRefresh();
}

function getLaneAnimationEase() {
    return laneAnimProgress < 0.5
        ? 2 * laneAnimProgress * laneAnimProgress
        : 1 - Math.pow(-2 * laneAnimProgress + 2, 2) / 2;
}

function getLaneAnimationCurrentRoadEdgeZ() {
    const t = getLaneAnimationEase();
    return laneAnimStartLimitZMax + (laneAnimTargetLimitZMax - laneAnimStartLimitZMax) * t;
}

function syncSkyFloorForLaneAnimation(currentRoadEdgeZ = roadLimitZMax) {
    if (!skyFloor || !player) return;

    const barrierHalfWidth = 0.30;
    const leftBarrierZ = getBarrierPositionZ(-1);
    // roadLimitZMax already stores the final edge during lane introduction.
    // Drive both the visible rail and asphalt from the eased current edge.
    const rightBarrierZ = (isAnimatingLane ? currentRoadEdgeZ : roadLimitZMax) + ROAD_EDGE_BARRIER_OFFSET;
    const leftRoadEdgeZ = leftBarrierZ + barrierHalfWidth;
    const rightRoadEdgeZ = rightBarrierZ - barrierHalfWidth;
    const requiredWidth = Math.max(1, rightRoadEdgeZ - leftRoadEdgeZ);
    const geometryWidth = (skyFloor.userData && skyFloor.userData.geometryRoadWidth) || requiredWidth;

    skyFloor.scale.x = 1;
    skyFloor.scale.z = requiredWidth / Math.max(0.001, geometryWidth);
    skyFloor.position.x = player.position.x;
    skyFloor.position.y = SKY_LAYER_Y - 5;
    skyFloor.position.z = (leftRoadEdgeZ + rightRoadEdgeZ) * 0.5;
    skyFloor.visible = true;
    skyFloor.userData.baseRoadWidth = requiredWidth;

    if (skyBarriers.length >= 2) {
        skyBarriers[0].position.z = leftBarrierZ;
        skyBarriers[1].position.z = rightBarrierZ;
        // A tiny deterministic embed removes the hairline between the rail
        // feet and the top of the ten-unit Sky road slab.
        skyBarriers[0].position.y = SKY_LAYER_Y - 0.08;
        skyBarriers[1].position.y = SKY_LAYER_Y - 0.08;
    }
}

function setObjectOpacity(obj, alpha) {
    obj.traverse((child) => {
        if (!child.isMesh || !child.material) return;

        if (Array.isArray(child.material)) {
            child.material.forEach((m) => {
                if (!m) return;
                m.transparent = true;
                m.opacity = alpha;
            });
        } else {
            child.material.transparent = true;
            child.material.opacity = alpha;
        }
    });
}	
   function updateSkyObjects(delta) {
    if (gamePhase >= 3 && !lavaDropTransitionActive) {
        window.nextSmallCloudX = undefined;
        return;
    }
    // Yerdeyken kÃ¼Ã§Ã¼k bulutlarÄ±n spawn mesafesini sÄ±fÄ±rlÄ±yoruz ki her zÄ±playÄ±ÅŸta baÅŸtan dizilsinler
    if (!onSkyLayer && player.position.y < 100) {
        window.nextSmallCloudX = undefined; 
        return;
    }

    if (skyFloor) {
        if (!(lavaDropTransitionActive && !lavaMapActivated)) {
            syncSkyFloorForLaneAnimation(isAnimatingLane ? getLaneAnimationCurrentRoadEdgeZ() : roadLimitZMax);
        }
    }

    if (skyBarriers.length > 0) {
        if (!(lavaDropTransitionActive && !lavaMapActivated)) {
            // Match the repeating barrier geometry period so recycling swaps
            // identical visual cells instead of visibly sliding the rail seams.
            const segmentSize = 240;
            // Sanal-X snap (floating origin): bariyer dünyaya-sabit 80'lik adımlarla ilerler
            const barrierX = Math.floor((player.position.x + worldScrollX) / segmentSize) * segmentSize + 150 - worldScrollX;

            skyBarriers[0].position.x = barrierX;
            skyBarriers[1].position.x = barrierX;
        }
    }

    if (skyLines && skyLines.mesh) {
        const dummy = tempSkyLineDummy;
        let needsUpdate = false;
        const stepSize = 18;
        
        // Sanal-X snap (floating origin): gate sanal ilerlemeyle tetiklenir, matris X'i
        // o anki dünya-frame'ine çevrilir (- worldScrollX). Yeniden yazımda mesh'in
        // birikmiş rebase kayması sıfırlanmalı, yoksa çift kayma olur.
        const snapPlayerX = Math.floor((player.position.x + worldScrollX) / stepSize) * stepSize;
        const dropActive = lavaDropTransitionActive && !lavaMapActivated;
        const shouldUpdateLines = dropActive || skyLines.lastSnapX !== snapPlayerX || skyLines.lastDropActive !== dropActive;

        if (shouldUpdateLines) {
            skyLines.lastSnapX = snapPlayerX;
            skyLines.lastDropActive = dropActive;
            skyLines.mesh.position.x = 0;

            for (let i = 0; i < skyLines.data.length; i++) {
                const item = skyLines.data[i];
                let worldX = snapPlayerX + item.relX - worldScrollX;

                while (worldX < player.position.x - 200) {
                    item.relX += 1400;
                    worldX = snapPlayerX + item.relX - worldScrollX;
                }

                if (dropActive && worldX > lavaDropCutoffX - 4.0) {
                    dummy.position.set(worldX, SKY_LAYER_Y - 140, item.z);
                } else {
                    dummy.position.set(worldX, SKY_LAYER_Y + 0.05, item.z);
                }
                dummy.rotation.x = -Math.PI / 2;
                dummy.updateMatrix();
                
                skyLines.mesh.setMatrixAt(item.index, dummy.matrix);
                needsUpdate = true;
            }
            
            if (needsUpdate) {
                skyLines.mesh.instanceMatrix.needsUpdate = true;
            }
        }
    }

    // --- KÃœÃ‡ÃœK BULUTLARIN BÃœYÃœK BULUTLAR GÄ°BÄ° DÄ°ZÄ°LMESÄ° ---
    
    // ZÄ±pladÄ±ÄŸÄ±n anda ilk kÃ¼Ã§Ã¼k bulutlarÄ±n baÅŸlayacaÄŸÄ± mesafe (yÃ¼zÃ¼ne Ã§arpmamasÄ± iÃ§in +300)
    if (typeof window.nextSmallCloudX === 'undefined') {
        window.nextSmallCloudX = player.position.x + 300; 
    }

    const spawnAhead = player.position.x + 3000 + (moveSpeed * 1500); // HÄ±za gÃ¶re Ã¶nden Ã¼retim

    // TÄ±pkÄ± bÃ¼yÃ¼k bulutlar gibi ileriye doÄŸru Ã¶nceden oluÅŸturma dÃ¶ngÃ¼sÃ¼
    const smallSpawnDeadline = performance.now() + 1.5;
    let smallSpawnRows = 0;
    while (!skyInitialFill && window.nextSmallCloudX < spawnAhead && smallSpawnRows < 6 && performance.now() < smallSpawnDeadline) {
        smallSpawnRows++;
        window.nextSmallCloudX += 26 + Math.random() * 38; 
        
        if (Math.random() < 0.75) { 
            const cloud = new THREE.Mesh(geoms.smallCloud, mats.smallCloud);
            
            // Y ekseni basÄ±klÄ±ÄŸÄ± giderildi
            const baseScale = 0.8 + Math.random() * 1.5;
            cloud.scale.set(baseScale * (0.8 + Math.random()*0.4), baseScale * (0.9 + Math.random()*0.2), baseScale * (0.8 + Math.random()*0.4));
            
            cloud.rotation.y = Math.random() * Math.PI;
            cloud.rotation.z = (Math.random() - 0.5) * 0.2;
            cloud.rotation.x = (Math.random() - 0.5) * 0.2;
            
            const y = SKY_LAYER_Y + 20 + Math.random() * 380; 
            const minSafeDist = 90; 
            const maxDist = 250;
            const side = Math.random() > 0.5 ? 1 : -1;
            
            const z = side * (minSafeDist + Math.random() * (maxDist - minSafeDist));
            
            cloud.position.set(window.nextSmallCloudX, y, z);
            initializeSkyStreamFade(cloud);
            cloud.renderOrder = 2;
            scene.add(cloud);
            skyClouds.push(cloud);
        }
    }

    const minSmallClouds = 120;
    let smallRefill = 0;
    while (!skyInitialFill && skyClouds.length < minSmallClouds && smallSpawnRows < 6 && performance.now() < smallSpawnDeadline) {
        smallSpawnRows++;
        smallRefill++;
        const cloud = new THREE.Mesh(geoms.smallCloud, mats.smallCloud);
        const baseScale = 0.8 + Math.random() * 1.5;
        cloud.scale.set(baseScale * (0.8 + Math.random()*0.4), baseScale * (0.9 + Math.random()*0.2), baseScale * (0.8 + Math.random()*0.4));
        cloud.rotation.y = Math.random() * Math.PI;
        cloud.rotation.z = (Math.random() - 0.5) * 0.2;
        cloud.rotation.x = (Math.random() - 0.5) * 0.2;
        // Keep emergency refills beyond the visible horizon; they ease in while
        // approaching instead of appearing at a random point inside the view.
        const x = player.position.x + SKY_SMALL_CLOUD_STREAM_ZERO_AHEAD + 70 + Math.random() * 460;
        const y = SKY_LAYER_Y + 20 + Math.random() * 380;
        const side = Math.random() > 0.5 ? 1 : -1;
        const z = side * (90 + Math.random() * 160);
        cloud.position.set(x, y, z);
        initializeSkyStreamFade(cloud);
        scene.add(cloud);
        skyClouds.push(cloud);
    }

    for (let i = skyClouds.length - 1; i >= 0; i--) {
        const c = skyClouds[i];
        // FPS: sis penceresi dışındaki tekil bulutları çizme
        const cdx = c.position.x - player.position.x;
        updateSkyStreamFade(
            c,
            cdx,
            SKY_SMALL_CLOUD_STREAM_FULL_AHEAD,
            SKY_SMALL_CLOUD_STREAM_ZERO_AHEAD,
            SKY_CLOUD_STREAM_FULL_BEHIND,
            SKY_CLOUD_STREAM_ZERO_BEHIND,
            true
        );
        if (c.visible) c.rotation.y += delta * 0.05;

        // Arkada kalan bulutları sil
        if (c.position.x < player.position.x - 900) {
            scene.remove(c);
            if(c.geometry && c.geometry !== geoms.smallCloud) c.geometry.dispose();
            skyClouds.splice(i, 1);
        }
    }
}
 
    // PERF (2026-07-07 hitch fix): materyaller + genişliğe-göre geometriler cache'lenir.
    // Eskiden her high-beam spawn'ında (spawnManager, oyun döngüsü) 3 materyal + 3 geometri
    // taze yaratılıyordu → GPU-upload/shader-lookup/GC hitch. beamWidth şerit-sayısına bağlı
    // (birkaç ayrık değer) → Map ile cache.
    const _hbGeoCache = new Map();
    function createDetailedHighBeam(widthZ, height) {
    const group = new THREE.Group();
    const thickness = 2.5;
    const frameThickness = 1.0;
    const innerHeight = height - (frameThickness * 2);

    if (!mats.hbPanel) {
        mats.hbPanel = new THREE.MeshStandardMaterial({ color: 0x0066ff, emissive: 0x0022ff, emissiveIntensity: 0.8, transparent: true, opacity: 0.85, metalness: 0.8, roughness: 0.1 });
        mats.hbFrame = new THREE.MeshStandardMaterial({ color: 0x444444, metalness: 1.0 });
        mats.hbLine = new THREE.MeshBasicMaterial({ color: 0x00ffff });
    }
    const key = widthZ.toFixed(2) + ':' + height.toFixed(2);
    let gc = _hbGeoCache.get(key);
    if (!gc) {
        gc = {
            panel: new THREE.BoxGeometry(thickness, innerHeight, widthZ),
            frame: new THREE.BoxGeometry(thickness + 0.5, frameThickness, widthZ + 0.5),
            line: new THREE.BoxGeometry(thickness + 0.6, 0.3, widthZ)
        };
        _hbGeoCache.set(key, gc);
        spawnPoolGeoms.push(gc.panel, gc.frame, gc.line); // dispose koruması
    }

    const panel = new THREE.Mesh(gc.panel, mats.hbPanel);
    group.add(panel);

    const topFrame = new THREE.Mesh(gc.frame, mats.hbFrame);
    topFrame.position.y = (height / 2) - (frameThickness / 2);
    group.add(topFrame);

    const bottomFrame = new THREE.Mesh(gc.frame, mats.hbFrame);
    bottomFrame.position.y = -(height / 2) + (frameThickness / 2);
    group.add(bottomFrame);

    for(let i=-1; i<=1; i++) {
        const line = new THREE.Mesh(gc.line, mats.hbLine);
        line.position.y = i * (innerHeight / 4);
        group.add(line);
    }

    return group;
}
    
    function beginFallingWallTrafficCrush(wall) {
        if (!wall?.userData) return 0;
        const wallX = getTrafficObjectXRange(wall);
        const wallZ = getTrafficObjectZRange(wall);
        let crushed = 0;
        for (const vehicle of obstacles) {
            if (!vehicle?.userData || vehicle === wall || vehicle.userData.crushedByFallingWall) continue;
            if (!isTrafficObjectType(vehicle.userData.type)) continue;
            const vehicleX = getTrafficObjectXRange(vehicle);
            if (wallX.max <= vehicleX.min || vehicleX.max <= wallX.min) continue;
            if (!trafficZRangesOverlap(wallZ, getTrafficObjectZRange(vehicle), 0.2)) continue;
            vehicle.userData.crushedByFallingWall = {
                elapsed: 0,
                duration: 0.42,
                baseY: vehicle.position.y,
                baseScale: vehicle.scale.clone(),
                driftZ: (vehicle.position.z <= wall.position.z ? -1 : 1) * 0.45
            };
            vehicle.userData.triggerOnly = true;
            vehicle.userData.speedX = 0;
            vehicle.userData.originalSpeed = 0;
            vehicle.userData.laneChanging = false;
            crushed++;
        }
        return crushed;
    }

    function updateFallingWallTrafficCrush(vehicle, delta) {
        const crush = vehicle?.userData?.crushedByFallingWall;
        if (!crush) return false;
        crush.elapsed += Math.max(0, Number(delta) || 0);
        const t = Math.min(1, crush.elapsed / crush.duration);
        const eased = 1 - Math.pow(1 - t, 3);
        vehicle.scale.set(
            crush.baseScale.x * (1 - eased * 0.22),
            crush.baseScale.y * Math.max(0.04, 1 - eased * 0.96),
            crush.baseScale.z * (1 + Math.sin(t * Math.PI) * 0.12)
        );
        vehicle.position.y = crush.baseY - eased * 1.35;
        vehicle.position.z += crush.driftZ * Math.max(0, Number(delta) || 0);
        if (!crush.burstPlayed && t >= 0.42) {
            crush.burstPlayed = true;
            spawnGlobalExplosion(vehicle.position.x, crush.baseY + 0.8, vehicle.position.z, 0xff6b42, 18);
        }
        return t >= 1;
    }

    function updateObstacles(delta) {
        const currentTime = clock.getElapsedTime();
        const frameScale = currentFrameScale || getFrameScale(delta);
        for (let i = 0; i < obstacles.length; i++) {
            const o = obstacles[i];

            if (o.userData.crushedByFallingWall) {
                if (updateFallingWallTrafficCrush(o, delta)) {
                    removeObstacleAt(i);
                    i--;
                }
                continue;
            }
            
            if (o.userData.type === 'traffic_light' && o.userData.smoke) {
                updateTrafficLightVisibility(o);
                const smoke = o.userData.smoke;
                const positions = smoke.mesh.geometry.attributes.position.array;
                const velocities = smoke.velocities;
                const beamH = smoke.height;
                const zCenter = smoke.zOffset;
                
                for(let j=0; j < velocities.length / 3; j++) {
                    const idx = j * 3;
                    positions[idx] += velocities[idx]; 
                    positions[idx+1] += velocities[idx+1]; 
                    positions[idx+2] += velocities[idx+2]; 
                    
                    if (positions[idx+1] < 0) { positions[idx+1] = beamH; } 
                    else if (positions[idx+1] > beamH) { positions[idx+1] = 0; }
                    
                    const currentY = positions[idx+1];
                    const ratio = currentY / beamH;
                    const maxR = 2.2 * (1-ratio) + 0.4 * ratio;
                    const dx = positions[idx];
                    const dz = positions[idx+2] - zCenter;
                    const distSq = dx*dx + dz*dz;
                    
                    if (distSq > maxR * maxR) {
                        const angle = Math.random() * Math.PI * 2;
                        const r = Math.random() * maxR * 0.8; 
                        positions[idx] = r * Math.cos(angle);
                        positions[idx+2] = zCenter + (r * Math.sin(angle));
                        velocities[idx] = (Math.random() - 0.5) * 0.02;
                        velocities[idx+2] = (Math.random() - 0.5) * 0.02;
                    }
                }
                smoke.mesh.geometry.attributes.position.needsUpdate = true;
            }

            if (o.position.y === -1000) {
                removeObstacleAt(i); i--; continue;
            }

            // Yanıp sönen uyarı fenerleri — falling_wall VE wall (siyah-beyaz bariyer) ortak,
            // tip'e bakılmaksızın warningLights taşıyan her engelde çalışır.
            if (o.userData.warningLights) {
                const blinkOn = Math.sin(currentTime * 6.0 + (o.userData.pulseSeed || 0)) > 0.15;
                const waitingLevelDrop = o.userData.type === 'falling_wall' && !o.userData.dropArmed;
                for (let li = 0; li < o.userData.warningLights.length; li++) {
                    o.userData.warningLights[li].visible = !waitingLevelDrop && blinkOn;
                }
            }

            if (o.userData.type === 'motorcycle') {
                updateVehicleFlashLights(o, currentTime);
            }

            if (o.userData.type === 'falling_wall') {
                const marker = o.userData.dropMarker;
                if (!o.userData.dropArmed) {
                    const distanceAhead = o.position.x - player.position.x;
                    const pulse = Math.abs(Math.sin(currentTime * 7));
                    if (marker) {
                        marker.visible = true;
                        marker.position.y = (o.userData.targetY - o.position.y) + 0.14;
                        marker.material.opacity = 0.22 + pulse * 0.4;
                        const ms = 0.8 + pulse * 0.28;
                        marker.scale.set(ms, ms, 1);
                    }
                    if (distanceAhead < -12) {
                        // A debug teleport or a very large frame can jump past
                        // the trigger. Recycle the unarmed wall instead of
                        // leaving a permanent off-screen pooled object.
                        removeObstacleAt(i);
                        i--;
                        continue;
                    }
                    if (distanceAhead <= o.userData.dropTriggerDistance) {
                        o.userData.dropArmed = true;
                        if (o.userData.revealBodyOnArm) setFallingWallBodyVisible(o, true);
                    } else {
                        // Do not execute the landing branch while an authored
                        // level wall is still waiting at its distant row.
                        continue;
                    }
                }
                if (o.position.y > o.userData.targetY) {
                    o.position.y -= o.userData.fallSpeed * frameScale;
                    if (o.userData.hideAirborneBody) setFallingWallBodyVisible(o, false);
                    // Düşerken hafif tilt salınımı — görsel-only (çarpışma position/height bazlı, rotation'a bakmaz)
                    o.rotation.z = Math.sin(currentTime * 11 + (o.userData.pulseSeed || 0)) * 0.03;
                    if (marker) {
                        // Grup orijini duvar tabanında; dünya zemini = targetY → local offset
                        marker.visible = true;
                        marker.position.y = (o.userData.targetY - o.position.y) + 0.14;
                        const pulse = Math.abs(Math.sin(currentTime * 7));
                        marker.material.opacity = 0.22 + pulse * 0.4;
                        const ms = 0.8 + pulse * 0.28;
                        marker.scale.set(ms, ms, 1);
                    }
                } else {
                    o.position.y = o.userData.targetY;
                    if (!o.userData.fwLanded) {
                        o.userData.fwLanded = true;
                        o.rotation.z = 0;
                        setFallingWallBodyVisible(o, true);
                        if (marker) marker.visible = false;
                        if (o.userData.shadowCaster && !o.userData.shadowCaster.castShadow) {
                            o.userData.shadowCaster.castShadow = true;
                            requestShadowMapRefresh(null, true);
                        }
                        // A wall landing on traffic crushes and removes it. The
                        // old blocker clamp teleported cars/bikes/trains back to
                        // a safe gap in one frame, which looked like a reversal.
                        beginFallingWallTrafficCrush(o);
                        // Yere çarpma: şok halkası + kıvılcım saçılması + yakınsa kamera sarsıntısı
                        spawnImpactRing(o.position.x, o.userData.targetY + 0.16, o.position.z, 0xff5570, 7.5, 0.55, 0.8);
                        spawnGlobalExplosion(o.position.x, o.userData.targetY + 0.8, o.position.z, 0xffb36b, 24);
                        const dxp = Math.abs(o.position.x - player.position.x);
                        playFallingWallImpactSound(Math.max(0.18, 1 - dxp / 120));
                        if (dxp < 60) impactShake = Math.max(impactShake, 0.34 * (1 - dxp / 60));
                    }
                }
            }

            else if (o.userData.type === 'gate_part') {
                if (o.position.x - player.position.x < 80) {
                    if (o.userData.willSink) {
                        if (!o.userData.gateSoundPlayed) {
                            o.userData.gateSoundPlayed = true;
                            playGateMechanismSound();
                        }
                        if (o.position.y > o.userData.targetY) {
                            o.position.y -= 2.5 * frameScale; 
                        }
                    }
                }
            }
 
            else if (o.userData.type === 'rising_rock') {
                // DÃœZELTME: Mesafe 70'e dÃ¼ÅŸÃ¼rÃ¼ldÃ¼ (Ã‡ok uzak olmamasÄ± iÃ§in)
                if (o.position.x - player.position.x < 70) {
                     if (o.position.y < o.userData.targetY) {
                        const rockGroundY = o.userData.targetY - 3.5; // targetY = floorY + 3.5 (spawn) → zemin
                        if (!o.userData.riseFxDone) {
                            o.userData.riseFxDone = true;
                            // Yerden fırlama: toprak halkası + toz patlaması
                            spawnImpactRing(o.position.x, rockGroundY + 0.16, o.position.z, 0xc8a06a, 5.5, 0.5, 0.7);
                            spawnGlobalExplosion(o.position.x, rockGroundY + 0.9, o.position.z, 0xb9885a, 18);
                            playRisingRockSound();
                        }
                        // DÃœZELTME: HÄ±z 2.2 katÄ±na Ã§Ä±karÄ±ldÄ± (Mesafe kÄ±saldÄ±ÄŸÄ± iÃ§in yetiÅŸsin)
                        o.position.y += moveSpeed * 2.2 * frameScale;
                        // Yükselirken zeminden toz sızıntısı (throttle'lı — havuz 600 parçacık)
                        if (!o.userData.nextRiseDustAt || currentTime >= o.userData.nextRiseDustAt) {
                            o.userData.nextRiseDustAt = currentTime + 0.07;
                            spawnGlobalExplosion(o.position.x + (Math.random() - 0.5) * 4, rockGroundY + 0.5, o.position.z + (Math.random() - 0.5) * 3, 0xa87f52, 3);
                        }
                    } else {
                        o.position.y = o.userData.targetY;
                    }
                }
            }
            else if (o.userData.type === 'sky_sweeper') {
                o.userData.sweepAngle += o.userData.rotSpeed * delta;
                o.rotation.y = o.userData.sweepAngle;
                const distAhead = o.position.x - player.position.x;
                const fadeStart = o.userData.fadeStartDistance || 620;
                const fadeLength = o.userData.fadeLength || 140;
                let targetAlpha = 1;
                if (distAhead > fadeStart) {
                    targetAlpha = 0;
                } else if (distAhead > fadeStart - fadeLength) {
                    targetAlpha = 1 - ((distAhead - (fadeStart - fadeLength)) / fadeLength);
                }
                targetAlpha = Math.max(0, Math.min(1, targetAlpha));
                o.visible = targetAlpha > 0.01;
                if (Math.abs((o.userData.visualAlpha ?? -1) - targetAlpha) > 0.01) {
                    setObjectOpacity(o, targetAlpha);
                    o.userData.visualAlpha = targetAlpha;
                }
                if (distAhead > 8 && distAhead < 95 && Math.abs(o.position.z - player.position.z) < 18) {
                    if (!o.userData.lastWhooshAt || (currentTime - o.userData.lastWhooshAt) > 0.8) {
                        playSweeperWhooshSound(1 - (distAhead / 95));
                        o.userData.lastWhooshAt = currentTime;
                    }
                }
            }
            else if (o.userData.type === 'energy_plasma') {
                const radius = o.userData.radius || 2.2;
                const minZ = roadLimitZMin + radius + 0.9;
                const maxZ = roadLimitZMax - radius - 0.9;
                const dir = o.userData.direction || 1;
                const speedZ = o.userData.speedZ || 12.0;

                if (minZ >= maxZ) {
                    o.position.z = getRoadCenterZ();
                } else {
                    o.position.z += dir * speedZ * delta;
                    if (o.position.z <= minZ) {
                        o.position.z = minZ;
                        o.userData.direction = 1;
                    } else if (o.position.z >= maxZ) {
                        o.position.z = maxZ;
                        o.userData.direction = -1;
                    }
                }

                const pulse = 0.84 + Math.sin(currentTime * 7.2 + (o.userData.pulseSeed || 0)) * 0.16;
                if (o.userData.coreMesh) {
                    o.userData.coreMesh.scale.setScalar((o.userData.baseScale || 1.0) * pulse);
                }
                if (o.userData.shellMesh) {
                    o.userData.shellMesh.scale.setScalar((o.userData.shellBaseScale || 1.36) * (0.95 + pulse * 0.12));
                }
            }
            else if (o.userData.type === 'lava_lane') {
                const distAhead = o.position.x - player.position.x;
                const fadeDuration = o.userData.fadeDuration || 0.45;

                if (o.userData.phase === 'idle' && distAhead <= o.userData.activationDistance) {
                    o.userData.phase = 'fade_in';
                    o.userData.phaseTimer = 0;
                }

                if (o.userData.phase === 'fade_in') {
                    o.userData.phaseTimer += delta;
                    const t = Math.max(0, Math.min(1, o.userData.phaseTimer / fadeDuration));
                    const eased = t * t * (3 - 2 * t);
                    const targetOpacity = o.userData.activeSurfaceOpacity || 0.9;
                    if (o.userData.asphaltSurface?.material) {
                        o.userData.asphaltSurface.material.opacity = 1 - eased;
                    }
                    if (o.userData.lavaSurface?.material) {
                        o.userData.lavaSurface.material.opacity = targetOpacity * eased;
                    }
                    if (t >= 1) {
                        o.userData.phase = 'active';
                        o.userData.active = true;
                        o.userData.timer = o.userData.duration;
                    }
                } else if (o.userData.phase === 'active') {
                    const pulse = 0.72 + 0.28 * Math.sin(currentTime * 8.0 + o.userData.pulseSeed);
                    if (o.userData.asphaltSurface?.material) {
                        o.userData.asphaltSurface.material.opacity = 0.0;
                    }
                    if (o.userData.lavaSurface?.material) {
                        o.userData.lavaSurface.material.opacity = (o.userData.activeSurfaceOpacity || 0.9) * (0.84 + pulse * 0.16);
                        o.userData.lavaSurface.material.emissiveIntensity = (o.userData.activeEmissiveBase || 0.95) + pulse * (o.userData.activeEmissivePulse || 0.4);
                    }
                    o.userData.timer -= delta;
                    if (o.userData.timer <= 0) {
                        o.userData.phase = 'fade_out';
                        o.userData.phaseTimer = 0;
                        o.userData.fadeOutStartAsphaltOpacity = o.userData.asphaltSurface?.material?.opacity ?? 0.0;
                        o.userData.fadeOutStartLavaOpacity = o.userData.lavaSurface?.material?.opacity ?? 0.9;
                        o.userData.fadeOutStartEmissiveIntensity = o.userData.lavaSurface?.material?.emissiveIntensity ?? (o.userData.baseLavaEmissiveIntensity || 0.46);
                        o.userData.active = false;
                    }
                } else if (o.userData.phase === 'fade_out') {
                    o.userData.phaseTimer += delta;
                    const t = Math.max(0, Math.min(1, o.userData.phaseTimer / fadeDuration));
                    const eased = t * t * (3 - 2 * t);
                    if (o.userData.asphaltSurface?.material) {
                        o.userData.asphaltSurface.material.opacity = o.userData.fadeOutStartAsphaltOpacity + ((1.0 - o.userData.fadeOutStartAsphaltOpacity) * eased);
                    }
                    if (o.userData.lavaSurface?.material) {
                        o.userData.lavaSurface.material.opacity = o.userData.fadeOutStartLavaOpacity * (1.0 - eased);
                        o.userData.lavaSurface.material.emissiveIntensity = (o.userData.fadeOutStartEmissiveIntensity || 0.46) + (((o.userData.baseLavaEmissiveIntensity || 0.46) - (o.userData.fadeOutStartEmissiveIntensity || 0.46)) * eased);
                    }
                    if (o.userData.phaseTimer >= fadeDuration) {
                        removeObstacleAt(i);
                        i--;
                        continue;
                    }
                } else {
                    if (o.userData.asphaltSurface?.material) {
                        o.userData.asphaltSurface.material.opacity = 1.0;
                    }
                    if (o.userData.lavaSurface?.material) {
                        o.userData.lavaSurface.material.opacity = 0.0;
                    }
                }

                if (o.userData.lavaSurface?.material?.map) {
                    const sourceFloor = o.userData.hazardTheme === 'water' ? waterFloor : lavaFloor;
                    o.userData.lavaSurface.material.map.offset.x = sourceFloor?.material?.map?.offset.x || 0;
                    o.userData.lavaSurface.material.map.offset.y = sourceFloor?.material?.map?.offset.y || 0;
                    if (o.userData.lavaSurface.material.emissiveMap) {
                        o.userData.lavaSurface.material.emissiveMap.offset.x = o.userData.lavaSurface.material.map.offset.x;
                        o.userData.lavaSurface.material.emissiveMap.offset.y = o.userData.lavaSurface.material.map.offset.y;
                    }
                }
            }
            else if (o.userData.type === 'snow_ice_road') {
                const distAhead = o.position.x - player.position.x;
                const fadeDuration = o.userData.fadeDuration || 0.44;
                const pulse = 0.5 + 0.5 * Math.sin(currentTime * 7.4 + (o.userData.pulseSeed || 0));

                if (o.userData.phase === 'idle' && distAhead <= (o.userData.activationDistance || 220)) {
                    o.userData.phase = 'fade_in';
                    o.userData.phaseTimer = 0;
                    o.userData.active = true;
                    o.userData.timer = o.userData.duration || SNOW_ICE_ROAD_DURATION;
                }

                if (o.userData.phase === 'fade_in') {
                    o.userData.phaseTimer += delta;
                    const t = Math.max(0, Math.min(1, o.userData.phaseTimer / fadeDuration));
                    const eased = t * t * (3 - 2 * t);
                    setSnowIceRoadHazardVisual(o, 1, eased);
                    if (t >= 1) {
                        o.userData.phase = 'active';
                        o.userData.phaseTimer = 0;
                    }
                } else if (o.userData.phase === 'active') {
                    o.userData.timer -= delta;
                    setSnowIceRoadHazardVisual(o, 1, 0.78 + pulse * 0.22);
                    if (o.userData.timer <= 0) {
                        o.userData.phase = 'fade_out';
                        o.userData.phaseTimer = 0;
                        o.userData.active = false;
                    }
                } else if (o.userData.phase === 'fade_out') {
                    o.userData.phaseTimer += delta;
                    const t = Math.max(0, Math.min(1, o.userData.phaseTimer / fadeDuration));
                    const eased = t * t * (3 - 2 * t);
                    setSnowIceRoadHazardVisual(o, 1 - eased, 1 - eased);
                    if (t >= 1) {
                        removeObstacleAt(i);
                        i--;
                        continue;
                    }
                } else {
                    setSnowIceRoadHazardVisual(o, 1, 0.08 + pulse * 0.12);
                }
            }
            else if (o.userData.type === 'snow_falling_ball') {
                updateSnowFallingBall(o, delta, currentTime);
            }
            else if (o.userData.type === 'tutorial_vehicle') {
                // No lane AI here: all four tutorial cars advance together and
                // preserve a clear, deterministic jump lesson.
                o.position.x += (o.userData.speedX || 0) * frameScale;
            }
            else if (o.userData.type === 'vehicle' || o.userData.type === 'motorcycle' || o.userData.type === 'train') {
                // Preserve the pre-step coordinate so the post-step safety pass can detect a
                // complete tunnel-through even when a low-FPS frame crosses a thin blocker.
                o.userData.previousTrafficX = o.position.x;
                const frameTravel = Math.abs(Number(o.userData.speedX || o.userData.originalSpeed) || 0) * frameScale;
                const trafficLookAhead = (o.userData.type === 'train' ? 280 : (o.userData.type === 'motorcycle' ? 210 : 235))
                    + frameTravel + (o.userData.length || 8);
                let obstacleAhead = checkObstacleAhead(o, trafficLookAhead);
                let aheadDistForDecision = obstacleAhead ? (o.position.x - obstacleAhead.position.x) : Infinity;
                if (shouldTrafficBypassEmbeddedBlocker(o, obstacleAhead, aheadDistForDecision)) {
                    o.userData.embeddedBypassUntil = currentTime + 0.85;
                    obstacleAhead = null;
                    aheadDistForDecision = Infinity;
                } else if ((o.userData.embeddedBypassUntil || 0) > currentTime && obstacleAhead && !isTrafficObjectType(obstacleAhead.userData.type)) {
                    obstacleAhead = null;
                    aheadDistForDecision = Infinity;
                }
               
                if (obstacleAhead && !o.userData.levelPatternLaneLocked && !o.userData.laneChanging && currentTime >= (o.userData.nextLaneDecisionTime || 0)) {
                    if (o.userData.type === 'motorcycle') {
                        const closeObstacle = aheadDistForDecision < 92;
                        if (closeObstacle || currentTime - (o.userData.lastLaneChangeTime || 0) > 0.25) {
                            const possibleLanes = []; 
                            const currentZ = o.position.z; 
                            const currentLaneIdx = getClosestLaneIndexForZ(currentZ);
                            
                            if (currentLaneIdx !== -1) {
                                const neighbors = [];
                                if (currentLaneIdx > 0) neighbors.push(currentLaneIdx - 1);
                                if (currentLaneIdx < lanePositions.length - 1) neighbors.push(currentLaneIdx + 1);
                                for(let nIdx of neighbors) {
                                    const testLane = lanePositions[nIdx];
                                    if (!checkLaneIsBlocked(testLane, o.position.x) &&
                                        checkLaneSafety(testLane, o.position.x, o.userData.length) &&
                                        isTrafficMergeLaneClear(o, testLane, o.position.x, 118, 34)) {
                                        possibleLanes.push(testLane);
                                    }
                                }
                            }
                            if (possibleLanes.length > 0) { 
                                possibleLanes.sort((a, b) => Math.abs(a - currentZ) - Math.abs(b - currentZ));
                                beginTrafficLaneChange(o, possibleLanes[0], currentTime);
                            } else {
                                setTrafficLaneDecisionDelay(o, currentTime, 0.22);
                            }
                        }
                    } else if (o.userData.type === 'vehicle' || o.userData.type === 'train') {
                        const changeCooldown = o.userData.type === 'train' ? 1.45 : 0.55;
                        const closeObstacle = aheadDistForDecision < (o.userData.type === 'train' ? 210 : 128);
                        if (closeObstacle || currentTime - (o.userData.lastLaneChangeTime || 0) > changeCooldown) {
                            const currentLaneIdx = getClosestLaneIndexForZ(o.position.z);
                            if (currentLaneIdx !== -1) {
                                const neighbors = [currentLaneIdx-1, currentLaneIdx+1].filter(n => n >= 0 && n < lanePositions.length);
                                neighbors.sort(() => Math.random() - 0.5);
                                let changedLane = false;
                                for (let nIdx of neighbors) {
                                    const nLane = lanePositions[nIdx];
                                    if (isTrafficMergeLaneClear(o, nLane, o.position.x, o.userData.type === 'train' ? 230 : 138, o.userData.type === 'train' ? 76 : 38) &&
                                        checkLaneSafety(nLane, o.position.x, o.userData.length)) { 
                                        beginTrafficLaneChange(o, nLane, currentTime);
                                        changedLane = true;
                                        break; 
                                    }
                                }
                                if (!changedLane) setTrafficLaneDecisionDelay(o, currentTime, closeObstacle ? 0.16 : 0.34);
                            }
                        } else {
                            setTrafficLaneDecisionDelay(o, currentTime, 0.18);
                        }
                    }
                }
                 
                if (o.userData.laneChanging) {
                    const diff = o.userData.targetLane - o.position.z;
                    let changeSpeed = 0.35; 
                    if (o.userData.type === 'motorcycle') changeSpeed = 0.65; 
                    else if (o.userData.type === 'train') changeSpeed = 0.15; 
                     
                    const laneStep = Math.max(0.001, changeSpeed * frameScale);
                    if (Math.abs(diff) > laneStep) { 
                        o.position.z += Math.sign(diff) * laneStep; 
                    } else { 
                        o.position.z = o.userData.targetLane;
                        o.userData.lane = o.userData.targetLane; // keep lane in sync for all (incl. motorcycle) so z-range stays tight
                        o.userData.laneChanging = false;
                        o.userData.lastLaneChangeTime = currentTime;
                        o.userData.nextLaneDecisionTime = currentTime + (o.userData.type === 'motorcycle' ? 0.45 : (o.userData.type === 'train' ? 1.0 : 0.75));
                    }
                }
                
                let currentSpeed = o.userData.originalSpeed;
                if (o.userData.type === 'motorcycle') {
                    if (!Number.isFinite(currentSpeed) || Math.abs(currentSpeed) < 0.05) {
                        currentSpeed = -Math.max(MOTORCYCLE_RECOVERY_SPEED_MIN, Math.abs(moveSpeed || 0.35) * MOTORCYCLE_RECOVERY_SPEED_FACTOR);
                        o.userData.originalSpeed = currentSpeed;
                    }
                    if (!obstacleAhead) {
                        o.userData.motorcycleBlockedId = null;
                        o.userData.motorcycleBlockedSince = 0;
                        if (Math.abs(o.userData.speedX || 0) < 0.05 && !o.userData.laneChanging) {
                            o.userData.speedX = currentSpeed;
                        }
                    }
                    o.userData.trafficHoldSpeedUntil = 0;
                    o.userData.trafficHoldSpeedX = null;
                } else if ((o.userData.trafficHoldSpeedUntil || 0) > currentTime && obstacleAhead) {
                    currentSpeed = getTrafficSafeFollowSpeed(currentSpeed, o.userData.trafficHoldSpeedX);
                } else if ((o.userData.trafficHoldSpeedUntil || 0) > currentTime) {
                    o.userData.trafficHoldSpeedUntil = 0;
                    o.userData.trafficHoldSpeedX = null;
                }
                let positionManuallySet = false; 
                
                if (o.userData.type === 'motorcycle') {
                    if (obstacleAhead) {
                        const dist = o.position.x - obstacleAhead.position.x;
                        const stopGap = getTrafficSafeGap(o, obstacleAhead, 6);
                        const minAllowedX = obstacleAhead.position.x + stopGap;
                        const projectedX = o.position.x + currentSpeed * frameScale;
                        if (projectedX < minAllowedX) {
                            const blockerId = obstacleAhead.uuid || `${obstacleAhead.userData.type}:${Math.round(obstacleAhead.position.x)}`;
                            if (o.userData.motorcycleBlockedId !== blockerId) {
                                o.userData.motorcycleBlockedId = blockerId;
                                o.userData.motorcycleBlockedSince = currentTime;
                            } else if (!o.userData.laneChanging && o.position.x < player.position.x - 25 && currentTime - (o.userData.motorcycleBlockedSince || currentTime) > MOTORCYCLE_BLOCKED_DESPAWN_DELAY) {
                                // only remove a stuck motorcycle once it is behind the player (off-screen) so it never vanishes in view
                                removeObstacleAt(i); i--; continue;
                            }
                            const aheadSpeed = obstacleAhead.userData.speedX || 0;
                            o.position.x = minAllowedX;
                            currentSpeed = getTrafficSafeFollowSpeed(currentSpeed, aheadSpeed);
                            positionManuallySet = true;
                            setTrafficLaneDecisionDelay(o, currentTime, 0.18);
                        } else if (dist <= stopGap + 2.0) {
                            const blockerId = obstacleAhead.uuid || `${obstacleAhead.userData.type}:${Math.round(obstacleAhead.position.x)}`;
                            if (o.userData.motorcycleBlockedId !== blockerId) {
                                o.userData.motorcycleBlockedId = blockerId;
                                o.userData.motorcycleBlockedSince = currentTime;
                            } else if (!o.userData.laneChanging && o.position.x < player.position.x - 25 && currentTime - (o.userData.motorcycleBlockedSince || currentTime) > MOTORCYCLE_BLOCKED_DESPAWN_DELAY) {
                                // only remove a stuck motorcycle once it is behind the player (off-screen) so it never vanishes in view
                                removeObstacleAt(i); i--; continue;
                            }
                            const aheadSpeed = obstacleAhead.userData.speedX || 0;
                            o.position.x = minAllowedX;
                            currentSpeed = getTrafficSafeFollowSpeed(currentSpeed, aheadSpeed);
                            positionManuallySet = true;
                            setTrafficLaneDecisionDelay(o, currentTime, 0.18);
                        } else {
                            o.userData.motorcycleBlockedId = null;
                            o.userData.motorcycleBlockedSince = 0;
                        }
                    }
                } else {
                    if (obstacleAhead) {
                        const dist = o.position.x - obstacleAhead.position.x;
                        const stopGap = getTrafficSafeGap(o, obstacleAhead, 10); 
                        const brakingDistance = 80.0; 
                        
                        if (dist < stopGap + brakingDistance) {
                            const aheadSpeed = obstacleAhead.userData.speedX || 0;
                            if (dist <= stopGap + 5.0 && Math.abs(aheadSpeed) < 0.01) {
                                currentSpeed = 0; 
                                if (dist <= stopGap + 2.0) {
                                    o.position.x = obstacleAhead.position.x + stopGap; 
                                    positionManuallySet = true;
                                    if (o.userData.type === 'train') { o.userData.type = 'stopped_train'; }
                                }
                            } else if (dist <= stopGap + 2.0) {
                                currentSpeed = aheadSpeed;
                                if (dist < stopGap) { o.position.x = obstacleAhead.position.x + stopGap; positionManuallySet = true; }
                            } else {
                                const t = (dist - stopGap) / brakingDistance; 
                                currentSpeed = aheadSpeed + (o.userData.originalSpeed - aheadSpeed) * t;
                            }
                        }
                    }
                }
                if (!positionManuallySet && obstacleAhead && o.userData.type !== 'motorcycle') {
                    const stopGap = getTrafficSafeGap(o, obstacleAhead, 10);
                    const aheadSpeed = obstacleAhead.userData.speedX || 0;
                    const minAllowedX = obstacleAhead.position.x + stopGap;
                    const projectedX = o.position.x + currentSpeed * frameScale;
                    if (projectedX < minAllowedX) {
                        o.position.x = minAllowedX;
                        currentSpeed = getTrafficSafeFollowSpeed(currentSpeed, aheadSpeed);
                        positionManuallySet = true;
                    }
                }
                currentSpeed = clampReadableTrafficSpeed(o.userData.type, currentSpeed);
                o.userData.speedX = currentSpeed;
                if (!positionManuallySet) { o.position.x += o.userData.speedX * frameScale; }
                maybePlayVehicleNearPass(o, o.userData.previousTrafficX, currentTime);
            }
            if (o.userData.type === 'lava_lane') {
                const fullFrontEdge = o.position.x + ((o.userData.length || 0) * 0.5);
                if (fullFrontEdge < player.position.x - 220 && o.userData.phase === 'idle') {
                    removeObstacleAt(i); i--;
                }
            } else if (o.userData.type === 'snow_ice_road') {
                const backEdge = o.position.x + ((o.userData.length || SNOW_ICE_ROAD_LENGTH) * 0.5);
                if (backEdge < player.position.x - 180) {
                    removeObstacleAt(i); i--;
                }
            } else if (o.position.x < player.position.x - 150) { removeObstacleAt(i); i--; }
        }
        preventTrafficSweptTunneling();
        stabilizeTrafficSpacing(frameScale);
        clampTrafficOutOfObstacles();
    }

    // Solid things a road vehicle must never drive into (walls, barriers, trains, gates, rocks,
    // other traffic). Pass-through hazards / pickups / ground FX are not blockers.
    function isSolidTrafficBlocker(ob) {
        if (!ob || !ob.userData) return false;
        const t = ob.userData.type;
        if (!t || isTrafficPhantomHazard(ob)) return false;
        if (t === 'rising_rock' && ob.position.y < -1.0) return false;
        if (t === 'falling_wall' && ob.position.y > 8.0) return false;
        if (t === 'gate_part' && ob.position.y < -5.0) return false;
        return true;
    }

    // Hard safety net: after all AI/movement, never leave moving traffic overlapping a static
    // solid obstacle. Traffic-vs-traffic spacing is handled once, in stable sorted order, by
    // stabilizeTrafficSpacing; doing it here too made equal-X cars/bikes push each other back and
    // forth on alternate frames (the visible trembling reported in dense level formations).
    function clampTrafficOutOfObstacles() {
        if (!obstacles || !player) return;
        const px = player.position.x;
        for (let a = 0; a < obstacles.length; a++) {
            const v = obstacles[a];
            if (!v || !v.userData) continue;
            const vt = v.userData.type;
            if (vt !== 'vehicle' && vt !== 'motorcycle' && vt !== 'train') continue;
            if (v.userData.crushedByFallingWall) continue;
            if (v.position.x < px - 60 || v.position.x > px + 1300) continue;
            const vzr = getTrafficObjectZRange(v);
            const previousX = Number.isFinite(v.userData.previousTrafficX)
                ? v.userData.previousTrafficX
                : v.position.x;
            let nearestStopX = -Infinity;
            let nearestBlocker = null;
            for (let b = 0; b < obstacles.length; b++) {
                const ob = obstacles[b];
                if (ob === v || !isSolidTrafficBlocker(ob)) continue;
                if (isTrafficObjectType(ob.userData.type)) continue;
                if (!trafficZRangesOverlap(getTrafficObjectZRange(ob), vzr, -0.15)) continue;
                const stopX = getTrafficStopRootX(v, ob, 1.35);
                const sweptMinX = Math.min(previousX, v.position.x);
                const sweptMaxX = Math.max(previousX, v.position.x);
                const currentRange = getTrafficObjectXRange(v);
                const blockerRange = getTrafficObjectXRange(ob);
                const overlapsNow = currentRange.max > blockerRange.min && blockerRange.max > currentRange.min;
                if ((stopX < sweptMinX - 1.5 || stopX > sweptMaxX + 1.5) && !overlapsNow) continue;
                if (stopX > nearestStopX) {
                    nearestStopX = stopX;
                    nearestBlocker = ob;
                }
            }
            if (nearestBlocker && v.position.x < nearestStopX) {
                v.position.x = nearestStopX;
                const blockerSpeed = Number(nearestBlocker.userData.speedX) || 0;
                v.userData.speedX = getTrafficSafeFollowSpeed(v.userData.speedX, blockerSpeed);
                v.userData.trafficHoldSpeedX = v.userData.speedX;
                v.userData.trafficHoldSpeedUntil = clock.getElapsedTime() + 0.28;
                v.userData.previousTrafficX = v.position.x;
            }
        }
    }

    // Stable previous-frame ordering prevents two moving bodies from exchanging places during a
    // long frame. Physics remains the existing straight CPU lane model; this is deliberately
    // independent from the curved-world visual shader and from the player's Swept-X collision.
    function preventTrafficSweptTunneling() {
        if (!obstacles || obstacles.length < 2) return;
        const traffic = obstacles.filter((object) => object?.userData
            && !object.userData.crushedByFallingWall
            && isTrafficObjectType(object.userData.type));
        const previousXOf = (object) => {
            const moving = ['vehicle', 'motorcycle', 'train'].includes(object.userData.type);
            return moving && Number.isFinite(object.userData.previousTrafficX)
                ? object.userData.previousTrafficX
                : object.position.x;
        };
        traffic.sort((a, b) => {
            return previousXOf(a) - previousXOf(b);
        });
        for (let i = 1; i < traffic.length; i++) {
            const back = traffic[i];
            const backPreviousX = previousXOf(back);
            for (let j = i - 1; j >= 0; j--) {
                const front = traffic[j];
                if (!trafficZRangesOverlap(getTrafficObjectZRange(back), getTrafficObjectZRange(front), 0.15)) continue;
                const frontPreviousX = previousXOf(front);
                if (backPreviousX < frontPreviousX) continue;
                const safeGap = getTrafficSafeGap(back, front, 10);
                const stopX = front.position.x + safeGap;
                if (back.position.x >= stopX) continue;
                back.position.x = stopX;
                const heldSpeed = getTrafficSafeFollowSpeed(
                    back.userData.speedX || back.userData.originalSpeed || 0,
                    front.userData.speedX || 0
                );
                back.userData.speedX = heldSpeed;
                back.userData.trafficHoldSpeedX = heldSpeed;
                back.userData.trafficHoldSpeedUntil = clock.getElapsedTime() + 0.22;
                break;
            }
        }
    }

    function stabilizeTrafficSpacing(frameScale = 1) {
        if (!obstacles || obstacles.length < 2) return;
        const traffic = [];
        const minX = player ? player.position.x - 120 : -Infinity;
        const maxX = player ? player.position.x + 1250 : Infinity;
        for (let o of obstacles) {
            if (!o || !o.userData || o.userData.crushedByFallingWall || !isTrafficObjectType(o.userData.type)) continue;
            if (o.position.x < minX || o.position.x > maxX) continue;
            traffic.push(o);
        }
        if (traffic.length < 2) return;

        traffic.sort((a, b) => a.position.x - b.position.x);
        for (let i = 1; i < traffic.length; i++) {
            const back = traffic[i];
            if (!back || !back.userData) continue;
            let nearestFront = null;
            let nearestGap = Infinity;

            for (let j = i - 1; j >= 0; j--) {
                const front = traffic[j];
                if (!front || !front.userData) continue;
                if (!trafficZRangesOverlap(getTrafficObjectZRange(back), getTrafficObjectZRange(front), 0.15)) continue;

                const safeGap = getTrafficSafeGap(back, front, 10);
                const gap = back.position.x - front.position.x;
                if (gap >= 0 && gap < safeGap && gap < nearestGap) {
                    nearestGap = gap;
                    nearestFront = front;
                }
            }

            if (!nearestFront) continue;
            const safeGap = getTrafficSafeGap(back, nearestFront, 10);
            const targetX = nearestFront.position.x + safeGap;
            if (back.position.x < targetX) {
                back.position.x = targetX;
                const frontSpeed = nearestFront.userData.speedX || 0;
                const heldSpeed = getTrafficSafeFollowSpeed(back.userData.speedX || back.userData.originalSpeed || 0, frontSpeed);
                back.userData.speedX = heldSpeed;
                back.userData.trafficHoldSpeedX = heldSpeed;
                back.userData.trafficHoldSpeedUntil = clock.getElapsedTime() + 0.2;
                if (isTrainLikeTrafficType(back.userData.type) && Math.abs(frontSpeed) < 0.01) {
                    back.userData.originalSpeed = Math.min(0, back.userData.originalSpeed || 0);
                }
                back.userData.nextLaneDecisionTime = Math.min(back.userData.nextLaneDecisionTime || Infinity, clock.getElapsedTime() + 0.08);
            }
        }
    }

    let audioContext;
    let masterGain;
    let sfxGain;
    let ambienceGain;
    let uiGain;
    let lastUiHoverSoundAt = -1;
    let lastWindGustAt = -10;
    let lastVehicleNearPassAt = -10;
    let vehicleNearPassSoundCount = 0;
    let lastVehicleNearPass = null;
    // Zaman-yavaşlatma ses efekti: özgün (telifsiz) sentezlenmiş "zaman durdu" sesi.
    const TIME_SLOW_SFX_SRC = 'assets/time-stop.wav';
    const TIME_SLOW_SFX_OFFSET = 0;     // özgün ses — baştan çal
    const TIME_SLOW_SFX_GAIN = 0.95;
    const TIME_SLOW_SFX_PITCH = 1.0;
    const TIME_SLOW_SFX_DETUNE = 0;
    let timeSlowSfxBuffer = null;
    let timeSlowSfxLoading = false;
    // Mıknatıs aktivasyon sesi: özgün sentez (generate-magnet-sound.js), elektromanyetik şarj.
    const MAGNET_SFX_SRC = 'assets/magnet.wav';
    const MAGNET_SFX_GAIN = 0.9;
    let magnetSfxBuffer = null;
    let magnetSfxLoading = false;
    // Coin toplama sesi: kullanıcının sağladığı örnek, oyuna özel gain/pitch-varyasyon ile.
    const COIN_SFX_SRC = 'assets/coin-collect.wav';
    const COIN_SFX_GAIN = 0.38; // coin trenlerinde çok sayıda üst üste binebildiğinden düşük tutuldu (klip/kalabalık olmasın)
    let coinSfxBuffer = null;
    let coinSfxLoading = false;
    const audioNoiseCache = Object.create(null);

    function randRange(min, max) {
        return min + Math.random() * (max - min);
    }

    let elementalAudioConfigured = false;
    function ensureElementalAudioSystem() {
        const audio = window.ElementalAudio;
        if (!audio || elementalAudioConfigured) return audio || null;
        audio.configure({
            getState: () => ({
                platformKind: getPlatformKind(),
                settings: {
                    muted: !!menuState.muted,
                    masterVolume: menuState.masterVolume,
                    musicVolume: menuState.musicVolume,
                    sfxVolume: menuState.sfxVolume,
                    uiVolume: menuState.uiVolume
                },
                mainMenuVisible,
                isGamePaused,
                isGameOver,
                reviveMusicHold,
                runStartedFromMenu,
                moveSpeed,
                minMoveSpeed,
                maxMoveSpeed,
                gamePhase,
                onSkyLayer,
                isSkyFading
            }),
            onMenuUnlockChange: updateMenuAudioUnlockPrompt
        });
        elementalAudioConfigured = true;
        return audio;
    }

    function syncLegacyAudioNodes() {
        const audio = ensureElementalAudioSystem();
        if (!audio) return false;
        const nodes = audio.getNodes();
        audioContext = nodes.audioContext;
        masterGain = nodes.masterGain;
        sfxGain = nodes.sfxGain;
        ambienceGain = nodes.ambienceGain;
        uiGain = nodes.uiGain;
        return !!audioContext;
    }

    function initAudio() {
        const extractedAudio = ensureElementalAudioSystem();
        if (!extractedAudio) {
            console.error('audio-system.js yuklenemedi; ses sistemi devre disi.');
            return;
        }
        extractedAudio.init();
        syncLegacyAudioNodes();
        loadTimeSlowSfx();
        loadMagnetSfx();
        loadCoinSfx();
    }

    function playHandSkillSfx(kind) {
        if (!audioContext || !masterGain) return;
        try {
            if (audioContext.state === 'suspended') audioContext.resume();
            const now = audioContext.currentTime;
            const output = sfxGain || masterGain;
            const gain = audioContext.createGain();
            const osc = audioContext.createOscillator();
            const filter = audioContext.createBiquadFilter();
            const isDash = kind === 'airDash';
            const isRewind = kind === 'timeRewind' || kind === 'timeRewindEnd';
            const ending = kind === 'timeRewindEnd' || kind === 'phaseShiftEnd';
            osc.type = isDash ? 'sawtooth' : (isRewind ? 'triangle' : 'sine');
            const startHz = isDash ? 720 : (isRewind ? (ending ? 180 : 760) : (ending ? 170 : 110));
            const endHz = isDash ? 105 : (isRewind ? (ending ? 620 : 125) : (ending ? 420 : 70));
            osc.frequency.setValueAtTime(startHz, now);
            osc.frequency.exponentialRampToValueAtTime(Math.max(30, endHz), now + (isRewind ? 0.55 : 0.32));
            filter.type = 'lowpass';
            filter.frequency.setValueAtTime(isDash ? 2200 : 1350, now);
            gain.gain.setValueAtTime(0.0001, now);
            gain.gain.exponentialRampToValueAtTime(isDash ? 0.095 : 0.075, now + 0.018);
            gain.gain.exponentialRampToValueAtTime(0.0001, now + (isRewind ? 0.58 : 0.36));
            osc.connect(filter).connect(gain).connect(output);
            osc.start(now);
            osc.stop(now + (isRewind ? 0.6 : 0.38));
        } catch (error) {}
    }

    function loadTimeSlowSfx() {
        if (!audioContext || timeSlowSfxBuffer || timeSlowSfxLoading) return;
        timeSlowSfxLoading = true;
        fetch(TIME_SLOW_SFX_SRC)
            .then((r) => r.arrayBuffer())
            .then((buf) => audioContext.decodeAudioData(buf))
            .then((decoded) => { timeSlowSfxBuffer = decoded; timeSlowSfxLoading = false; })
            .catch((e) => { timeSlowSfxLoading = false; console.warn('Zaman sesi yuklenemedi:', e); });
    }

    function loadMagnetSfx() {
        if (!audioContext || magnetSfxBuffer || magnetSfxLoading) return;
        magnetSfxLoading = true;
        fetch(MAGNET_SFX_SRC)
            .then((r) => r.arrayBuffer())
            .then((buf) => audioContext.decodeAudioData(buf))
            .then((decoded) => { magnetSfxBuffer = decoded; magnetSfxLoading = false; })
            .catch((e) => { magnetSfxLoading = false; console.warn('Miknatis sesi yuklenemedi:', e); });
    }

    function loadCoinSfx() {
        if (!audioContext || coinSfxBuffer || coinSfxLoading) return;
        coinSfxLoading = true;
        fetch(COIN_SFX_SRC)
            .then((r) => r.arrayBuffer())
            .then((buf) => audioContext.decodeAudioData(buf))
            .then((decoded) => { coinSfxBuffer = decoded; coinSfxLoading = false; })
            .catch((e) => { coinSfxLoading = false; console.warn('Coin sesi yuklenemedi:', e); });
    }

