    function playCoinSound() {
        if (!audioContext || audioContext.state !== 'running') return;
        if (!coinSfxBuffer) { loadCoinSfx(); playCoinSoundSynthFallback(); return; }
        try {
            const src = audioContext.createBufferSource();
            src.buffer = coinSfxBuffer;
            // Coin trenlerinde art arda aynı örnek tekdüze/robotik durmasın diye küçük perde varyasyonu
            // (eski sentez sesteki randRange frekans sweep'iyle aynı amaç).
            src.playbackRate.value = randRange(0.94, 1.12);
            const gain = audioContext.createGain();
            gain.gain.value = COIN_SFX_GAIN;
            src.connect(gain).connect(sfxGain || masterGain);
            src.start(0);
        } catch (e) {}
    }

